-- Permit the genuine immutable Source Umbrella origin already qualified by
-- the collection writer. No rows, economics, owners, grants or ledgers change.
-- Ordinary/cross-channel eligibility remains the writer's explicit authority.


do $origin_channel$
declare
  v_constraint record;
  v_expression text;
begin
  if not exists (select 1 from pg_catalog.pg_class c
    where c.oid='private.bpay_next_work_collection'::regclass
      and c.relowner=current_user::regrole) then
    raise exception using errcode='42501',message='BPAY_SOURCE_ORIGIN_CHANNEL_OWNER_MISMATCH';
  end if;
  select c.* into strict v_constraint from pg_catalog.pg_constraint c
    where c.conrelid='private.bpay_next_work_collection'::regclass
      and c.conname='bpay_next_work_collection_original_source_pay_channel_check';
  v_expression:=pg_catalog.pg_get_expr(v_constraint.conbin,v_constraint.conrelid);
  if v_constraint.contype<>'c' or not v_constraint.convalidated
    or not v_constraint.conislocal or v_constraint.coninhcount<>0 then
    raise exception using errcode='23514',message='BPAY_SOURCE_ORIGIN_CHANNEL_CONSTRAINT_SHAPE';
  end if;
  if v_expression=$old$(original_source_pay_channel = 'PAYE'::text)$old$ then
    alter table private.bpay_next_work_collection
      drop constraint bpay_next_work_collection_original_source_pay_channel_check;
    alter table private.bpay_next_work_collection
      add constraint bpay_next_work_collection_original_source_pay_channel_check
      check (original_source_pay_channel in ('PAYE','UMBRELLA'));
  elsif v_expression<>$new$(original_source_pay_channel = ANY (ARRAY['PAYE'::text, 'UMBRELLA'::text]))$new$ then
    raise exception using errcode='23514',message='BPAY_SOURCE_ORIGIN_CHANNEL_UNEXPECTED_PREIMAGE';
  end if;
end;
$origin_channel$;


