alter table private.bpay_next_case_cancel_binding
  add column umbrella_draft_state_id uuid,
  add constraint bpay_next_case_cancel_umbrella_draft_fk_v2
    foreign key (umbrella_draft_state_id,run_worker_id,candidate_id,preparation_revision,selection_revision)
    references private.bpay_next_case_allocation_state(id,run_worker_id,candidate_id,preparation_revision,selection_revision) on delete restrict;
-- Same exact-expression admission used by actual0400; unknown shapes fail closed.
do $cancel_projection_shape$
declare old_constraint name;
  expected text:=pg_catalog.regexp_replace($audited$
    (((accepted_projection_revision IS NULL) AND (projection_id IS NULL) AND (net_state_id IS NULL))
      OR ((accepted_projection_revision = 0) AND (projection_id IS NULL) AND (net_state_id IS NULL))
      OR ((accepted_projection_revision > 0) AND (projection_id IS NOT NULL) AND (net_state_id IS NOT NULL)))
  $audited$,'[[:space:]()]','','g');
begin
  if not exists(select 1 from pg_catalog.pg_class c where c.oid='private.bpay_next_case_cancel_binding'::regclass
    and c.relowner=current_user::regrole) then raise exception 'BPAY_NEXT_UM_CANCEL_BINDING_OWNER_MISMATCH' using errcode='42501';end if;
  select c.conname into strict old_constraint from pg_catalog.pg_constraint c
    where c.conrelid='private.bpay_next_case_cancel_binding'::regclass and c.contype='c'
      and c.convalidated and c.conislocal and c.coninhcount=0
      and pg_catalog.regexp_replace(pg_catalog.pg_get_expr(c.conbin,c.conrelid),'[[:space:]()]','','g')=expected;
  execute pg_catalog.format('alter table private.bpay_next_case_cancel_binding drop constraint %I',old_constraint);
end $cancel_projection_shape$;
alter table private.bpay_next_case_cancel_binding add constraint bpay_next_case_cancel_projection_shape_v2 check ((
  (accepted_projection_revision is null and projection_id is null and net_state_id is null and umbrella_draft_state_id is null)
  or (accepted_projection_revision=0 and projection_id is null and net_state_id is null and umbrella_draft_state_id is null)
  or (accepted_projection_revision>0 and projection_id is not null and
    ((net_state_id is not null and umbrella_draft_state_id is null)
      or (net_state_id is null and umbrella_draft_state_id is not null and umbrella_draft_state_id=draft_state_id)))) is true);
-- One actual cancellation can consume an accepted projection only once; this
-- permits a constant point proof without enumerating old blocked commands.
create unique index bpay_next_case_cancel_projection_once_v2
  on private.bpay_next_case_cancel_binding(projection_id) where projection_id is not null;


-- Repeatable CloudTMS authority: weekly_source_entitlement_publication_v1
--
-- The Weekly Source entitlement-head publication coordinator (Gates 3 and 5):
-- the one place where a complete entitlement becomes current, the payment
-- Workbench is woken exactly once, and exactly one receipt is written, all or
-- nothing.
--
-- Pack authority, read word for word before this file was written:
--   P:\proof\32_PENDING_PUBLICATION_OWNER_SPECIFICATION_20260917.md
--     sections 6 (locks and ordering), 7 (revalidation), 8 (release
--     transaction), 9 (receipt relation and the canonical request digest) and
--     11 (forbidden).
--   P:\24_CROSS_SYSTEM_SOURCE_PAY_INVOICE_AMENDMENT_AUTHORITY.md
--     sections 4.3, 4.4, 4.5 and 5.1.
--   P:\26_PLAN_6_2_IMPLEMENTATION_AND_PROOF_LEDGER.md Gate 5, steps 1 to 10.
--   P:\27_WORKBENCH_COMPATIBILITY_AND_BANKING_PAY_HANDOFF.md sections 2, 4, 8.
--   P:\proof\34_… sections 4, 5, 6 and 7.
--   H2-024, H2-031, H2-032, H2-035, H2-036, H2-038.
--
-- The request shape is the fixed interface I-3, published by this package as
-- `plan6-2-implementation\interfaces\PUBLICATION_REQUEST_SHAPE.md` before any
-- code was written.  WP-06, WP-07 and WP-08b conform to that file.
--
-- What this coordinator never does (proof/32 section 11, 24 section 4.5):
-- it calculates no residual; it writes no pay, recovery, Draft, Case, provider,
-- settlement, reservation or remittance row; it reads no C1 staging or
-- checkpoint table as authority; it never mutates, rotates, replaces,
-- unauthorises, reauthorises or rebuilds a public Timesheet or a current TSFIN;
-- it never trusts a stored timesheet_id without the family resolution carried in
-- the I-1 lock result; it holds no lock on any Banking Pay table; it accepts no
-- actor and no timestamp from the caller (the actor is read from the immutable
-- accepted decision bundle, the time is pg_catalog.clock_timestamp()); and it
-- never sets, pre-seeds or reads a Workbench session setting.
--
-- Late binding.  plpgsql resolves called functions at run time, so the calls to
-- interfaces I-1 (WP-03), I-2 (WP-08a), I-5 (WP-08b) and I-6 (WP-07) compile
-- before those owners exist.
--
-- No function in this file is PostgREST-callable: every one is in `private`,
-- owned by postgres, with all privileges revoked from PUBLIC, anon,
-- authenticated and service_role.  There is therefore no
-- `notify pgrst, 'reload schema';` in this file.





-- ---------------------------------------------------------------------------
-- 1. The canonical JSON text encoder
-- ---------------------------------------------------------------------------
-- proof/32 section 9, last paragraph: "SHA-256 over the UTF-8 bytes of a
-- canonical JSON object - keys sorted, no insignificant whitespace, integers as
-- base-10 strings, UUIDs lower-case".
--
-- PostgreSQL's own jsonb key order is length-first and then bytewise, which is
-- NOT sorted order, so the keys are sorted explicitly under the C collation
-- (byte order).  A JSON number must be an exact integer: every non-integral
-- quantity travels through this encoder as a fixed-scale decimal STRING, so a
-- caller can never change a money digest by writing a rate differently.
--
-- An integer is emitted as a bare base-10 numeral rather than a quoted string,
-- so that an integer and its decimal string remain distinguishable.  That
-- reading of "integers as base-10 strings" is recorded as an open question in
-- IMPL\reports\WP-02_REPORT.md; flipping it is a one-line change here.
create or replace function private.weekly_source_canonical_json_text_v1(
  p_value jsonb
) returns text
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_type text;
  v_num numeric;
  v_parts text[];
begin
  if p_value is null then
    return 'null';
  end if;
  v_type:=pg_catalog.jsonb_typeof(p_value);

  if v_type='null' then
    return 'null';

  elsif v_type='boolean' then
    return case when p_value::boolean then 'true' else 'false' end;

  elsif v_type='number' then
    v_num:=pg_catalog.trim_scale(p_value::numeric);
    if pg_catalog.scale(v_num)<>0 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_DIGEST_NON_INTEGER'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_DIGEST_NON_INTEGER',
                'value',p_value)::text;
    end if;
    return v_num::text;

  elsif v_type='string' then
    -- PostgreSQL's own JSON string escaping: " -> \", \ -> \\, the five short
    -- escapes \b \f \n \r \t, every other control character below 0x20 as
    -- \u00xx with lower-case hex, / unescaped, non-ASCII emitted literally.
    return pg_catalog.to_jsonb(p_value #>> '{}')::text;

  elsif v_type='array' then
    select coalesce(
             pg_catalog.array_agg(
               private.weekly_source_canonical_json_text_v1(array_element.value)
               order by array_element.ordinality),
             array[]::text[])
      into v_parts
      from pg_catalog.jsonb_array_elements(p_value)
           with ordinality as array_element(value,ordinality);
    return '['||pg_catalog.array_to_string(v_parts,',')||']';

  elsif v_type='object' then
    select coalesce(
             pg_catalog.array_agg(
               pg_catalog.to_jsonb(object_entry.key)::text
               ||':'
               ||private.weekly_source_canonical_json_text_v1(object_entry.value)
               order by object_entry.key collate "C"),
             array[]::text[])
      into v_parts
      from pg_catalog.jsonb_each(p_value) as object_entry(key,value);
    return '{'||pg_catalog.array_to_string(v_parts,',')||'}';
  end if;

  raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
    using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
            'reason','UNKNOWN_JSON_TYPE','jsonb_typeof',v_type)::text;
end;
$function$;

-- The single canonical request-digest encoder, shared by immediate
-- publication, deferred release and replay verification (proof/32 section 9;
-- H2-032).  There is exactly one implementation and every caller uses it.
create or replace function private.weekly_source_publication_request_digest_v1(
  p_canonical jsonb
) returns bytea
language sql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select pg_catalog.sha256(
    pg_catalog.convert_to(
      private.weekly_source_canonical_json_text_v1(p_canonical),'UTF8'));
$function$;

-- ---------------------------------------------------------------------------
-- 2. Request validation helpers
-- ---------------------------------------------------------------------------
-- One scalar coercion owner for the whole request, so every field is validated
-- and normalised in exactly one place (I-3 section 6.2).
create or replace function private.weekly_source_publication_scalar_v1(
  p_value jsonb,
  p_field text,
  p_kind text,
  p_scale integer default null,
  p_nullable boolean default false
) returns jsonb
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_type text:=case when p_value is null then 'null'
                    else pg_catalog.jsonb_typeof(p_value) end;
  v_text text;
  v_num numeric;
  v_format text;
begin
  if v_type='null' then
    if p_nullable then
      return 'null'::jsonb;
    end if;
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field',p_field,'reason','NULL_NOT_ALLOWED')::text;
  end if;

  if p_kind='BOOL' then
    if v_type<>'boolean' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EXPECTED_BOOLEAN',
                'jsonb_typeof',v_type)::text;
    end if;
    return p_value;
  end if;

  if p_kind='INT' then
    if v_type<>'number' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EXPECTED_INTEGER',
                'jsonb_typeof',v_type)::text;
    end if;
    v_num:=pg_catalog.trim_scale(p_value::numeric);
    if pg_catalog.scale(v_num)<>0 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_DIGEST_NON_INTEGER'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_DIGEST_NON_INTEGER',
                'field',p_field,'value',p_value)::text;
    end if;
    return pg_catalog.to_jsonb(v_num);
  end if;

  if v_type<>'string' then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field',p_field,'reason','EXPECTED_STRING',
              'jsonb_typeof',v_type)::text;
  end if;
  v_text:=p_value #>> '{}';

  if p_kind='TEXT' then
    if pg_catalog.length(v_text)=0 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EMPTY_TEXT')::text;
    end if;
    return pg_catalog.to_jsonb(v_text);

  elsif p_kind='RAWTEXT' then
    -- The raw booking_id travels byte for byte; it is never trimmed, because
    -- the trimmed form is a lock and index key, not an identity (H2-035).
    return pg_catalog.to_jsonb(v_text);

  elsif p_kind='UUID' then
    if v_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EXPECTED_UUID')::text;
    end if;
    return pg_catalog.to_jsonb(v_text::uuid::text);

  elsif p_kind='HEX32' then
    if v_text !~* '^[0-9a-f]{64}$' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EXPECTED_32_BYTE_HEX')::text;
    end if;
    return pg_catalog.to_jsonb(pg_catalog.lower(v_text));

  elsif p_kind='DATE' then
    -- The wire form is validated as ISO by pattern, parsed to prove it is a
    -- real date, and rendered back by PATTERN, never by DateStyle.  `date::text`
    -- honours the session's DateStyle, so under `German, DMY` the same request
    -- would canonicalise `2026-03-02` as `02.03.2026` and produce a different
    -- money digest from the same decision (review finding, lower severity 2).
    if v_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EXPECTED_ISO_DATE')::text;
    end if;
    return pg_catalog.to_jsonb(pg_catalog.to_char(v_text::date,'YYYY-MM-DD'));

  elsif p_kind='DEC' then
    if v_text !~ '^-?[0-9]+(\.[0-9]+)?$' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','EXPECTED_DECIMAL_STRING')::text;
    end if;
    v_num:=pg_catalog.trim_scale(v_text::numeric);
    -- More precision than the stored column can hold is refused, never rounded:
    -- silently rounding money is how a penny goes missing.
    if pg_catalog.scale(v_num)>p_scale then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','DECIMAL_SCALE_EXCEEDED',
                'max_scale',p_scale,'actual_scale',pg_catalog.scale(v_num))::text;
    end if;
    -- And more MAGNITUDE than the column can hold is refused too.  The relation
    -- is numeric(18,s), so the integer part may carry at most 18-s digits.  The
    -- first version rendered through a fixed to_char picture, which prints `#`
    -- on overflow: `1000000000000000000.00` and `2000000000000000000.00` both
    -- became `##################.##` and DIGESTED THE SAME (review finding,
    -- lower severity 3).  A money digest may never be ambiguous, so this
    -- refuses instead of printing.
    if pg_catalog.length((pg_catalog.trunc(pg_catalog.abs(v_num)))::text)>18-p_scale then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',p_field,'reason','DECIMAL_MAGNITUDE_EXCEEDED',
                'max_integer_digits',18-p_scale,
                'actual_integer_digits',
                  pg_catalog.length((pg_catalog.trunc(pg_catalog.abs(v_num)))::text))::text;
    end if;
    -- Rendered by arithmetic, not by to_char: to_char's decimal separator
    -- follows lc_numeric, while `numeric::text` is always '.' with no grouping.
    v_format:=v_num::text;
    if p_scale>0 then
      if pg_catalog.strpos(v_format,'.')=0 then
        v_format:=v_format||'.'||pg_catalog.repeat('0',p_scale);
      else
        v_format:=v_format||pg_catalog.repeat('0',p_scale-pg_catalog.scale(v_num));
      end if;
    end if;
    return pg_catalog.to_jsonb(v_format);
  end if;

  raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
    using errcode='22023',
          detail=pg_catalog.jsonb_build_object(
            'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
            'field',p_field,'reason','UNKNOWN_KIND','kind',p_kind)::text;
end;
$function$;

-- A money digest that silently drops a field it does not recognise is worse
-- than no digest, so an unknown key inside the digest scope is a refusal.
create or replace function private.weekly_source_publication_require_keys_v1(
  p_object jsonb,
  p_expected text[],
  p_field text
) returns void
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_unknown text[];
  v_missing text[];
begin
  if p_object is null or pg_catalog.jsonb_typeof(p_object)<>'object' then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field',p_field,'reason','EXPECTED_OBJECT')::text;
  end if;

  select pg_catalog.array_agg(present_key order by present_key)
    into v_unknown
    from pg_catalog.jsonb_object_keys(p_object) as present_key
   where not (present_key=any(p_expected));
  if v_unknown is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_UNKNOWN_FIELD'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_UNKNOWN_FIELD',
              'field',p_field,'unknown_keys',pg_catalog.to_jsonb(v_unknown))::text;
  end if;

  select pg_catalog.array_agg(expected_key order by expected_key)
    into v_missing
    from pg_catalog.unnest(p_expected) as expected_key
   where not p_object ? expected_key;
  if v_missing is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field',p_field,'reason','MISSING_KEYS',
              'missing_keys',pg_catalog.to_jsonb(v_missing))::text;
  end if;
end;
$function$;

-- One entitlement component, normalised to the complete WB-005 allowlist of
-- public.weekly_source_entitlement_head_components minus the columns the
-- coordinator owns.  Every key is required and present; a missing key is a
-- refusal, not a default.  `adjustment_id` does not exist here and never will:
-- adjustments are never copied into a head (24 section 5; WB-007, WB-013).
create or replace function private.weekly_source_publication_component_canonical_v1(
  p_component jsonb,
  p_field text
) returns jsonb
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_out jsonb;
begin
  perform private.weekly_source_publication_require_keys_v1(
    p_component,
    array[
      'component_ordinal','component_id','component_kind','economic_key_type',
      'economic_key_value','component_member_identity','segment_id','segment_key',
      'segment_stable_key','work_date','reference_number','hours_day','hours_night',
      'hours_sat','hours_sun','hours_bh','additional_code_raw','unit_count',
      'unit_pay_rate','unit_charge_rate','expense_code','pay_ex_vat','charge_ex_vat',
      'exclude_from_pay','origin','movement_id','movement_group_id'
    ],
    p_field);

  v_out:=pg_catalog.jsonb_build_object(
    'component_ordinal',private.weekly_source_publication_scalar_v1(p_component->'component_ordinal',p_field||'.component_ordinal','INT'),
    'component_id',private.weekly_source_publication_scalar_v1(p_component->'component_id',p_field||'.component_id','UUID'),
    'component_kind',private.weekly_source_publication_scalar_v1(p_component->'component_kind',p_field||'.component_kind','TEXT'),
    'economic_key_type',private.weekly_source_publication_scalar_v1(p_component->'economic_key_type',p_field||'.economic_key_type','TEXT'),
    'economic_key_value',private.weekly_source_publication_scalar_v1(p_component->'economic_key_value',p_field||'.economic_key_value','TEXT'),
    'component_member_identity',private.weekly_source_publication_scalar_v1(p_component->'component_member_identity',p_field||'.component_member_identity','TEXT'),
    'segment_id',private.weekly_source_publication_scalar_v1(p_component->'segment_id',p_field||'.segment_id','TEXT',null,true),
    'segment_key',private.weekly_source_publication_scalar_v1(p_component->'segment_key',p_field||'.segment_key','TEXT',null,true),
    'segment_stable_key',private.weekly_source_publication_scalar_v1(p_component->'segment_stable_key',p_field||'.segment_stable_key','TEXT',null,true),
    'work_date',private.weekly_source_publication_scalar_v1(p_component->'work_date',p_field||'.work_date','DATE',null,true),
    'reference_number',private.weekly_source_publication_scalar_v1(p_component->'reference_number',p_field||'.reference_number','TEXT',null,true),
    'hours_day',private.weekly_source_publication_scalar_v1(p_component->'hours_day',p_field||'.hours_day','DEC',6,true),
    'hours_night',private.weekly_source_publication_scalar_v1(p_component->'hours_night',p_field||'.hours_night','DEC',6,true),
    'hours_sat',private.weekly_source_publication_scalar_v1(p_component->'hours_sat',p_field||'.hours_sat','DEC',6,true),
    'hours_sun',private.weekly_source_publication_scalar_v1(p_component->'hours_sun',p_field||'.hours_sun','DEC',6,true),
    'hours_bh',private.weekly_source_publication_scalar_v1(p_component->'hours_bh',p_field||'.hours_bh','DEC',6,true),
    'additional_code_raw',private.weekly_source_publication_scalar_v1(p_component->'additional_code_raw',p_field||'.additional_code_raw','TEXT',null,true),
    'unit_count',private.weekly_source_publication_scalar_v1(p_component->'unit_count',p_field||'.unit_count','DEC',6,true),
    'unit_pay_rate',private.weekly_source_publication_scalar_v1(p_component->'unit_pay_rate',p_field||'.unit_pay_rate','DEC',6,true),
    'unit_charge_rate',private.weekly_source_publication_scalar_v1(p_component->'unit_charge_rate',p_field||'.unit_charge_rate','DEC',6,true),
    'expense_code',private.weekly_source_publication_scalar_v1(p_component->'expense_code',p_field||'.expense_code','TEXT',null,true),
    'pay_ex_vat',private.weekly_source_publication_scalar_v1(p_component->'pay_ex_vat',p_field||'.pay_ex_vat','DEC',2),
    'charge_ex_vat',private.weekly_source_publication_scalar_v1(p_component->'charge_ex_vat',p_field||'.charge_ex_vat','DEC',2,true),
    'exclude_from_pay',private.weekly_source_publication_scalar_v1(p_component->'exclude_from_pay',p_field||'.exclude_from_pay','BOOL'),
    'origin',private.weekly_source_publication_scalar_v1(p_component->'origin',p_field||'.origin','TEXT'),
    'movement_id',private.weekly_source_publication_scalar_v1(p_component->'movement_id',p_field||'.movement_id','UUID',null,true),
    'movement_group_id',private.weekly_source_publication_scalar_v1(p_component->'movement_group_id',p_field||'.movement_group_id','UUID',null,true)
  );

  -- 24 section 4.5 step 3: movement_group_id groups components that MOVE
  -- together, so it cannot exist without a movement identity.  The head
  -- component relation carries the same rule as a CHECK.
  if v_out->'movement_group_id'<>'null'::jsonb and v_out->'movement_id'='null'::jsonb then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_MOVEMENT_IDENTITY_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_MOVEMENT_IDENTITY_INVALID',
              'field',p_field,'reason','GROUP_WITHOUT_MOVEMENT')::text;
  end if;

  return v_out;
end;
$function$;

-- ---------------------------------------------------------------------------
-- 3. The canonicaliser: project exactly the eleven proof/32 section 9 fields
-- ---------------------------------------------------------------------------
-- "Nothing outside that object influences the digest, and the same object is
-- what exact replay compares field by field" (proof/32 section 9).
--
-- publication_mode and pending_bundle_id are supplied by the coordinator, not
-- by the caller: they are digest fields, so the same economic decision has a
-- different digest when it is published immediately and when it is released
-- from a pending bundle.  That is what makes the pending bundle's stored digest
-- (section 2, section 7) and the deferred receipt's digest (section 9) one
-- value.
create or replace function private.weekly_source_publication_request_canonical_v1(
  p_request jsonb,
  p_publication_mode text,
  p_pending_bundle_id uuid
) returns jsonb
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_mode text:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_publication_mode,'')));
  v_financial jsonb;
  v_source_revision jsonb;
  v_contract_choices jsonb;
  v_member_entitlements jsonb;
  v_member_count integer;
  v_entry jsonb;
  v_components jsonb;
  v_component_count integer;
  v_certified_zero boolean;
  v_ordinal integer;
  v_index integer;
  v_seen integer;
begin
  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object' then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field','request','reason','EXPECTED_OBJECT')::text;
  end if;
  if v_mode not in ('IMMEDIATE','DEFERRED') then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field','publication_mode','reason','EXPECTED_IMMEDIATE_OR_DEFERRED')::text;
  end if;
  if (v_mode='DEFERRED')<>(p_pending_bundle_id is not null) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field','pending_bundle_id',
              'reason','DEFERRED_REQUIRES_PENDING_BUNDLE')::text;
  end if;

  -- The four aligned arrays (H2-032).
  for v_index in 1..4 loop
    if pg_catalog.jsonb_typeof(p_request->(array['member_root_ids','member_family_booking_ids',
                                                 'member_root_versions','head_ids'])[v_index])<>'array' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field',(array['member_root_ids','member_family_booking_ids',
                               'member_root_versions','head_ids'])[v_index],
                'reason','EXPECTED_ARRAY')::text;
    end if;
  end loop;

  v_member_count:=pg_catalog.jsonb_array_length(p_request->'member_root_ids');
  if v_member_count<1
     or v_member_count<>pg_catalog.jsonb_array_length(p_request->'member_family_booking_ids')
     or v_member_count<>pg_catalog.jsonb_array_length(p_request->'member_root_versions')
     or v_member_count<>pg_catalog.jsonb_array_length(p_request->'head_ids') then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field','member_root_ids','reason','ARRAYS_NOT_ALIGNED',
              'member_root_ids',v_member_count)::text;
  end if;

  -- 24 section 4.5: this approval is the BOUNDED old-Contract/new-Contract A/B
  -- amendment.  "A larger member set requires staged keyset work and a
  -- constant-size bundle activation pointer", which does not exist, so three
  -- roots are refused rather than silently attempted.
  if v_member_count>2 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_BUNDLE_UNBOUNDED'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_BUNDLE_UNBOUNDED',
              'member_count',v_member_count)::text;
  end if;

  -- financial_request (I-3 section 4).
  v_financial:=p_request->'financial_request';
  perform private.weekly_source_publication_require_keys_v1(
    v_financial,
    array['source_revision','contract_choices','member_entitlements'],
    'financial_request');

  -- Encoding only: the closed Local producer has no fabricated nullable Final.
  -- Its factual receipt/whole-vector authority remains the publisher's job.
  if v_financial#>>'{source_revision,origin_kind}'='PROTECTED_LOCAL_DECISION_V1' then
    v_source_revision:=private.weekly_source_local_origin_canonical_v2(
      v_financial->'source_revision');
  else
  perform private.weekly_source_publication_require_keys_v1(
    v_financial->'source_revision',
    case when v_financial#>>'{source_revision,origin_kind}'='CURRENT_FINAL_SOURCE_V1'
      then array['final_revision_id','source_cycle_id','revision_number','manifest_hash',
                 'policy_fingerprint','origin_kind','accepted_action_id']
      else array['final_revision_id','source_cycle_id','revision_number','manifest_hash',
                 'policy_fingerprint'] end,
    'financial_request.source_revision');
  v_source_revision:=pg_catalog.jsonb_build_object(
    'final_revision_id',private.weekly_source_publication_scalar_v1(v_financial->'source_revision'->'final_revision_id','financial_request.source_revision.final_revision_id','UUID'),
    'source_cycle_id',private.weekly_source_publication_scalar_v1(v_financial->'source_revision'->'source_cycle_id','financial_request.source_revision.source_cycle_id','UUID'),
    'revision_number',private.weekly_source_publication_scalar_v1(v_financial->'source_revision'->'revision_number','financial_request.source_revision.revision_number','INT'),
    'manifest_hash',private.weekly_source_publication_scalar_v1(v_financial->'source_revision'->'manifest_hash','financial_request.source_revision.manifest_hash','HEX32'),
    'policy_fingerprint',private.weekly_source_publication_scalar_v1(v_financial->'source_revision'->'policy_fingerprint','financial_request.source_revision.policy_fingerprint','HEX32'));
  -- Closed accepted-Final provenance. This only encodes the exact fact; it
  -- grants no retained-content exception. The integrated publisher must verify
  -- the immutable acceptance and complete before/vector through both guards.
  if v_financial#>>'{source_revision,origin_kind}'='CURRENT_FINAL_SOURCE_V1' then
    v_source_revision:=v_source_revision||pg_catalog.jsonb_build_object(
      'origin_kind','CURRENT_FINAL_SOURCE_V1',
      'accepted_action_id',private.weekly_source_publication_scalar_v1(
        v_financial#>'{source_revision,accepted_action_id}',
        'financial_request.source_revision.accepted_action_id','UUID'));
  end if;
  end if;

  if pg_catalog.jsonb_typeof(v_financial->'contract_choices')<>'array'
     or pg_catalog.jsonb_array_length(v_financial->'contract_choices')<>v_member_count then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field','financial_request.contract_choices',
              'reason','NOT_ALIGNED_WITH_MEMBERS')::text;
  end if;
  if pg_catalog.jsonb_typeof(v_financial->'member_entitlements')<>'array'
     or pg_catalog.jsonb_array_length(v_financial->'member_entitlements')<>v_member_count then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
      using errcode='22023',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
              'field','financial_request.member_entitlements',
              'reason','NOT_ALIGNED_WITH_MEMBERS')::text;
  end if;

  -- Contract choices, re-ordered by root_ordinal so caller order cannot change
  -- the digest.  Each ordinal must appear exactly once.
  v_contract_choices:='[]'::jsonb;
  for v_index in 1..v_member_count loop
    select choice_element.value into v_entry
      from pg_catalog.jsonb_array_elements(v_financial->'contract_choices') as choice_element(value)
     where (choice_element.value->>'root_ordinal')::text=v_index::text;
    if v_entry is null then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.contract_choices',
                'reason','MISSING_ROOT_ORDINAL','root_ordinal',v_index)::text;
    end if;
    perform private.weekly_source_publication_require_keys_v1(
      v_entry,
      array['root_ordinal','contract_id','week_ending_date','selection_method']
        ||case when v_index=2 and v_member_count=2 and v_entry ? 'destination_reprice'
          then array['destination_reprice'] else array[]::text[] end,
      'financial_request.contract_choices['||v_index::text||']');
    if (v_entry->>'selection_method') not in
       ('AUTO_UNIQUE','OFFICE_SELECTED','DURABLE_LINEAGE','UNCHANGED') then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.contract_choices['||v_index::text||'].selection_method',
                'reason','UNKNOWN_SELECTION_METHOD',
                'selection_method',v_entry->'selection_method')::text;
    end if;
    if v_entry ? 'destination_reprice' then
      perform private.weekly_source_publication_require_keys_v1(v_entry->'destination_reprice',
        array['schema_version','witness_id','review_sha256'],'contract_choice.destination_reprice');
      if v_entry#>>'{destination_reprice,schema_version}' is distinct from 'WEEKLY_SOURCE_DESTINATION_REPRICE_V1' then
        raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_SCHEMA_INVALID' using errcode='22023'; end if;
    end if;
    v_contract_choices:=v_contract_choices||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'root_ordinal',private.weekly_source_publication_scalar_v1(v_entry->'root_ordinal','financial_request.contract_choices.root_ordinal','INT'),
        'contract_id',private.weekly_source_publication_scalar_v1(v_entry->'contract_id','financial_request.contract_choices.contract_id','UUID'),
        'week_ending_date',private.weekly_source_publication_scalar_v1(v_entry->'week_ending_date','financial_request.contract_choices.week_ending_date','DATE'),
        'selection_method',private.weekly_source_publication_scalar_v1(v_entry->'selection_method','financial_request.contract_choices.selection_method','TEXT'))
      ||case when v_entry ? 'destination_reprice' then pg_catalog.jsonb_build_object('destination_reprice',
        pg_catalog.jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1',
          'witness_id',private.weekly_source_publication_scalar_v1(v_entry#>'{destination_reprice,witness_id}','destination_reprice.witness_id','UUID'),
          'review_sha256',private.weekly_source_publication_scalar_v1(v_entry#>'{destination_reprice,review_sha256}','destination_reprice.review_sha256','HEX32')))
        else '{}'::jsonb end);
    v_entry:=null;
  end loop;

  -- Every root's complete entitlement vector.
  v_member_entitlements:='[]'::jsonb;
  for v_index in 1..v_member_count loop
    select entitlement_element.value into v_entry
      from pg_catalog.jsonb_array_elements(v_financial->'member_entitlements') as entitlement_element(value)
     where (entitlement_element.value->>'root_ordinal')::text=v_index::text;
    if v_entry is null then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.member_entitlements',
                'reason','MISSING_ROOT_ORDINAL','root_ordinal',v_index)::text;
    end if;
    perform private.weekly_source_publication_require_keys_v1(
      v_entry,
      array['root_ordinal','authority_kind','certified_zero','component_count','components'],
      'financial_request.member_entitlements['||v_index::text||']');

    -- 24 section 4.3: one common interface for both authority kinds.
    if (v_entry->>'authority_kind') not in ('PROTECTED','LOCKED_FINAL_SOURCE') then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.member_entitlements['||v_index::text||'].authority_kind',
                'reason','EXPECTED_PROTECTED_OR_LOCKED_FINAL_SOURCE')::text;
    end if;
    if pg_catalog.jsonb_typeof(v_entry->'components')<>'array' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.member_entitlements['||v_index::text||'].components',
                'reason','EXPECTED_ARRAY')::text;
    end if;
    v_component_count:=pg_catalog.jsonb_array_length(v_entry->'components');
    if (v_entry->'component_count')::text<>v_component_count::text then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.member_entitlements['||v_index::text||'].component_count',
                'reason','COMPONENT_COUNT_MISMATCH',
                'declared',v_entry->'component_count','actual',v_component_count)::text;
    end if;
    -- WB-009 and 24 section 4.5 step 3: certified zero is an EXPLICIT head and
    -- exists only when no component remains.
    v_certified_zero:=(private.weekly_source_publication_scalar_v1(
      v_entry->'certified_zero',
      'financial_request.member_entitlements['||v_index::text||'].certified_zero','BOOL'))::boolean;
    if v_certified_zero<>(v_component_count=0) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_CERTIFIED_ZERO_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_CERTIFIED_ZERO_INVALID',
                'root_ordinal',v_index,'certified_zero',v_certified_zero,
                'component_count',v_component_count)::text;
    end if;

    -- Components re-ordered by component_ordinal; ordinals are 1..n exactly
    -- once each, so the inventory is complete and has no gap or repeat.
    v_components:='[]'::jsonb;
    for v_ordinal in 1..v_component_count loop
      select pg_catalog.count(*)::integer into v_seen
        from pg_catalog.jsonb_array_elements(v_entry->'components') as component_element(value)
       where (component_element.value->>'component_ordinal')::text=v_ordinal::text;
      if v_seen<>1 then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
          using errcode='22023',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                  'field','financial_request.member_entitlements['||v_index::text||'].components',
                  'reason','COMPONENT_ORDINAL_NOT_UNIQUE',
                  'component_ordinal',v_ordinal,'occurrences',v_seen)::text;
      end if;
      v_components:=v_components||pg_catalog.jsonb_build_array(
        private.weekly_source_publication_component_canonical_v1(
          (select component_element.value
             from pg_catalog.jsonb_array_elements(v_entry->'components') as component_element(value)
            where (component_element.value->>'component_ordinal')::text=v_ordinal::text),
          'financial_request.member_entitlements['||v_index::text||'].components['||v_ordinal::text||']'));
    end loop;

    -- One component_id may not appear twice inside one head.
    select pg_catalog.count(distinct canonical_component.value->>'component_id')::integer
      into v_seen
      from pg_catalog.jsonb_array_elements(v_components) as canonical_component(value);
    if v_seen<>v_component_count then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','financial_request.member_entitlements['||v_index::text||'].components',
                'reason','DUPLICATE_COMPONENT_ID')::text;
    end if;

    v_member_entitlements:=v_member_entitlements||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'root_ordinal',private.weekly_source_publication_scalar_v1(v_entry->'root_ordinal','financial_request.member_entitlements.root_ordinal','INT'),
        'authority_kind',private.weekly_source_publication_scalar_v1(v_entry->'authority_kind','financial_request.member_entitlements.authority_kind','TEXT'),
        'certified_zero',pg_catalog.to_jsonb(v_certified_zero),
        'component_count',pg_catalog.to_jsonb(v_component_count),
        'components',v_components));
    v_entry:=null;
  end loop;

  return pg_catalog.jsonb_build_object(
    'decision_bundle_id',private.weekly_source_publication_scalar_v1(p_request->'decision_bundle_id','decision_bundle_id','UUID'),
    'pending_bundle_id',case when p_pending_bundle_id is null then 'null'::jsonb
                             else pg_catalog.to_jsonb(p_pending_bundle_id::text) end,
    'bundle_revision',private.weekly_source_publication_scalar_v1(p_request->'bundle_revision','bundle_revision','INT'),
    'candidate_id',private.weekly_source_publication_scalar_v1(p_request->'candidate_id','candidate_id','UUID'),
    'member_root_ids',(
      select coalesce(pg_catalog.jsonb_agg(
               private.weekly_source_publication_scalar_v1(root_element.value,'member_root_ids','UUID')
               order by root_element.ordinality),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(p_request->'member_root_ids')
             with ordinality as root_element(value,ordinality)),
    'member_family_booking_ids',(
      select coalesce(pg_catalog.jsonb_agg(
               private.weekly_source_publication_scalar_v1(booking_element.value,'member_family_booking_ids','RAWTEXT')
               order by booking_element.ordinality),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(p_request->'member_family_booking_ids')
             with ordinality as booking_element(value,ordinality)),
    'member_root_versions',(
      select coalesce(pg_catalog.jsonb_agg(
               private.weekly_source_publication_scalar_v1(version_element.value,'member_root_versions','INT')
               order by version_element.ordinality),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(p_request->'member_root_versions')
             with ordinality as version_element(value,ordinality)),
    'head_ids',(
      select coalesce(pg_catalog.jsonb_agg(
               private.weekly_source_publication_scalar_v1(head_element.value,'head_ids','UUID')
               order by head_element.ordinality),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements(p_request->'head_ids')
             with ordinality as head_element(value,ordinality)),
    'decision_id',private.weekly_source_publication_scalar_v1(p_request->'decision_id','decision_id','UUID'),
    'publication_mode',pg_catalog.to_jsonb(v_mode),
    'financial_request',pg_catalog.jsonb_build_object(
      'source_revision',v_source_revision,
      'contract_choices',v_contract_choices,
      'member_entitlements',v_member_entitlements));
end;
$function$;

-- ---------------------------------------------------------------------------
-- 3a. Set algebra for the H2-024 post-decision head proofs
-- ---------------------------------------------------------------------------
-- 24 section 4.5 step 3 requires the coordinator to prove, in the same
-- transaction, "A-before = A-after union moved", "A-after intersect moved is
-- empty", "every moved component in exactly one destination head" and "every
-- unrelated B component retained".  These four owners make those proofs
-- readable instead of four nested array expressions.
create or replace function private.weekly_source_uuid_set_union_v1(
  p_left uuid[],p_right uuid[]
) returns uuid[]
language sql immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce((
    select pg_catalog.array_agg(distinct set_value order by set_value)
    from pg_catalog.unnest(coalesce(p_left,array[]::uuid[])
                           ||coalesce(p_right,array[]::uuid[])) as set_value
  ),array[]::uuid[]);
$function$;

create or replace function private.weekly_source_uuid_set_intersect_v1(
  p_left uuid[],p_right uuid[]
) returns uuid[]
language sql immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce((
    select pg_catalog.array_agg(distinct left_value order by left_value)
    from pg_catalog.unnest(coalesce(p_left,array[]::uuid[])) as left_value
    where left_value=any(coalesce(p_right,array[]::uuid[]))
  ),array[]::uuid[]);
$function$;

create or replace function private.weekly_source_uuid_set_difference_v1(
  p_left uuid[],p_right uuid[]
) returns uuid[]
language sql immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select coalesce((
    select pg_catalog.array_agg(distinct left_value order by left_value)
    from pg_catalog.unnest(coalesce(p_left,array[]::uuid[])) as left_value
    where not (left_value=any(coalesce(p_right,array[]::uuid[])))
  ),array[]::uuid[]);
$function$;

create or replace function private.weekly_source_uuid_set_equals_v1(
  p_left uuid[],p_right uuid[]
) returns boolean
language sql immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select private.weekly_source_uuid_set_union_v1(p_left,array[]::uuid[])
         =private.weekly_source_uuid_set_union_v1(p_right,array[]::uuid[]);
$function$;

-- A component's CONTENT identity: what the component is, with the three facts
-- that describe where it sits removed.
--
--   component_ordinal   - its position inside one head.  A component retained
--                         while another moves out from in front of it changes
--                         position without changing.
--   movement_id,
--   movement_group_id   - bundle-scoped provenance.  A component that moved in
--                         bundle N carries a movement identity there and none
--                         when it is merely retained by bundle N+1.
--
-- Everything else - the economic keys, the hours, the rates, the money, the
-- expense code, exclude_from_pay and origin - is content, and `component_sha256`
-- is the digest of exactly that.  It is what lets the coordinator prove that a
-- RETAINED component is byte-identical (review finding U3(a)) without refusing
-- every legal move.  Position is still covered by `inventory_digest` and
-- `entitlement_digest`, and the movement rules by their own explicit checks and
-- unique indexes.
create or replace function private.weekly_source_publication_component_content_v1(
  p_component jsonb
) returns jsonb
language sql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select p_component-'component_ordinal'-'movement_id'-'movement_group_id';
$function$;

-- Is the target root PROVABLY BLANK, not merely unknown to Weekly Source?
-- Review finding U2: a B Timesheet that already existed, was never touched by
-- Weekly Source and carries its own unrelated shifts passed the old
-- "no head and no lineage row" test and was authorised silently, which
-- 24 section 4.5 step 4, file 26 Gate 5 step 6, 27 section 8 step 6 and H2-024
-- all forbid.  Every clause below is a fact this coordinator can read; the
-- clean case is a root created inside this very transaction.
create or replace function private.weekly_source_publication_target_root_blank_v1(
  p_root_timesheet_id uuid,
  p_family_booking_id text
) returns jsonb
language plpgsql
stable
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_root record;
  v_reasons jsonb:='[]'::jsonb;
  v_created_in_this_transaction boolean:=false;
  v_snapshot_inventory jsonb;
  v_family uuid[];
begin
  select timesheet_id,status::text as status_text,actual_schedule_json,created_at,
         authorised_at_server
    into v_root
    from public.timesheets
   where timesheet_id=p_root_timesheet_id;
  if not found then
    return pg_catalog.jsonb_build_object('blank',false,
      'reasons',pg_catalog.jsonb_build_array('ROOT_TIMESHEET_NOT_FOUND'));
  end if;

  v_created_in_this_transaction:=v_root.created_at>=pg_catalog.transaction_timestamp();

  -- WP-30 (WP-27 sweep finding N2), standing rule 3.  Three consecutive
  -- eligibility reasons, and they disagreed with each other: the head limb below
  -- was already keyed on the family booking id while the authorisation limb here
  -- and the lineage limb after it were keyed on the physical root id.  A reason
  -- that is not added makes the root look PROVABLY BLANK, which is the
  -- fail-OPEN direction in the one test that stands between an Office decision
  -- and authorising a root silently.  EXECUTED on a rotated family whose
  -- authorisation and lineage rows sit on the demoted sibling: the current root
  -- returned `blank=true, reasons=[]`, while the demoted id returned both
  -- reasons.
  --
  -- One family resolution, through the one installed adapter, read by both
  -- limbs.  The adapter is used rather than the family booking string the two
  -- relations happen to carry, because a trimmed-booking join is a SECOND
  -- identity mechanism and disagrees with the installed resolver on a
  -- whitespace-padded booking id.
  v_family:=private.weekly_source_invoice_family_timesheet_ids_v1(p_root_timesheet_id);
  -- Standing rule 3's fail-closed branch, as an explicit cardinality test and
  -- never a `limit`: an unresolvable family is a REASON, so the root is not
  -- reported blank.
  if v_family is null or pg_catalog.cardinality(v_family)=0 then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('FAMILY_IDENTITY_UNRESOLVED'::text);
    v_family:=array[p_root_timesheet_id]::uuid[];
  end if;

  -- Never authorised, by Weekly Source or by anyone.
  if exists (select 1 from public.weekly_source_root_authorisations as authorisation_row
              where authorisation_row.root_timesheet_id=any(v_family)) then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('HAS_A_ROOT_AUTHORISATION_GENERATION'::text);
  end if;
  if exists (select 1 from public.weekly_source_entitlement_heads as head_row
              where pg_catalog.btrim(head_row.root_family_booking_id)
                    =pg_catalog.btrim(p_family_booking_id)) then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('FAMILY_ALREADY_HAS_AN_ENTITLEMENT_HEAD'::text);
  end if;
  if exists (select 1 from public.weekly_source_row_timesheet_lineages as lineage_row
              where lineage_row.timesheet_id=any(v_family)) then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('ALREADY_BOUND_TO_A_SOURCE_ROW'::text);
  end if;

  -- The ordinary Authorise owner that interface I-6 calls REQUIRES a current
  -- TSFIN row (`TARGET_NOT_FOUND`/`NO_TSFIN`), so a genuinely new B root always
  -- has one by the time it is authorised: it is prepared by the same source
  -- pipeline.  Refusing on its mere existence would make a new B root
  -- impossible, so the question is what the snapshot CARRIES.
  --
  -- WP-06c review observation O2, reproduced by WP-02b and fixed here.  This
  -- test used to be `created_at < transaction_timestamp()`: a snapshot that
  -- predated the transaction disqualified the root whatever it held.  That made
  -- a genuinely new B root provably blank ONLY inside the transaction that
  -- created it, so the two publication paths the design actually has - a
  -- retryable `WEEKLY_SOURCE_CANDIDATE_BUSY` (I-3 section 7.1 calls it common,
  -- not exceptional) and the `FROZEN` -> pending -> `DEFERRED` release that runs
  -- minutes or days later (proof/32 section 2) - both arrived at publication
  -- demanding a whole-root Office review that the accepted decision could not
  -- carry, because at proposal time there was nothing to review.  Executed
  -- before the fix: the same request, the same untouched root, composed and
  -- recorded in one transaction, refused in the next with
  -- `THE_ACCEPTED_DECISION_CARRIES_NO_WHOLE_ROOT_OFFICE_REVIEW`, and the builder
  -- could not re-compose it either.
  --
  -- `24 section 4.5` step 4 is about CONTENT - "an existing unauthorised B with
  -- unrelated content" - not about when a row was written.  So the test is now:
  -- does the snapshot hold any entitlement content?  The answer comes from the
  -- ONE named owner of "what a root effectively holds", interface I-7, so this
  -- introduces no second path to a figure, and every other disqualifier below
  -- and above (a lineage binding, an authorisation generation, a head on the
  -- family, the root's own schedule, an ordinary authorisation, a status that is
  -- not a new root's) is untouched.  I-7 absent, refusing, reporting a HEAD, or
  -- reporting any component at all all disqualify the root: fail closed.
  if exists (select 1 from public.timesheets_financials as financial_row
              where financial_row.timesheet_id=p_root_timesheet_id
                and financial_row.is_current) then
    if pg_catalog.to_regprocedure(
         'private.weekly_source_effective_inventory_v1(uuid)') is null then
      v_reasons:=v_reasons||pg_catalog.to_jsonb('HAS_A_CURRENT_FINANCIAL_SNAPSHOT'::text);
    else
      v_snapshot_inventory:=private.weekly_source_effective_inventory_v1(p_root_timesheet_id);
      if coalesce(pg_catalog.jsonb_typeof(v_snapshot_inventory),'')<>'object'
         or coalesce((v_snapshot_inventory->>'ok')::boolean,false) is not true
         or v_snapshot_inventory->>'authority' is distinct from 'TSFIN'
         or coalesce((v_snapshot_inventory->>'component_count')::integer,1)<>0
         or pg_catalog.jsonb_array_length(
              coalesce(v_snapshot_inventory->'components','["unknown"]'::jsonb))<>0 then
        v_reasons:=v_reasons||pg_catalog.to_jsonb('HAS_A_CURRENT_FINANCIAL_SNAPSHOT'::text);
      end if;
    end if;
  end if;
  if pg_catalog.jsonb_typeof(coalesce(v_root.actual_schedule_json,'[]'::jsonb))='array' then
    if pg_catalog.jsonb_array_length(coalesce(v_root.actual_schedule_json,'[]'::jsonb))>0 then
      v_reasons:=v_reasons||pg_catalog.to_jsonb('CARRIES_ITS_OWN_SCHEDULE'::text);
    end if;
  elsif coalesce(v_root.actual_schedule_json,'{}'::jsonb)<>'{}'::jsonb then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('CARRIES_ITS_OWN_SCHEDULE'::text);
  end if;
  -- Authorisation is `timesheets.authorised_at_server`, NOT a status label: the
  -- installed `timesheet_status_enum` is RECEIVED, STORED, SHEETS_PENDING,
  -- SHEETS_PARTIAL, SHEETS_SYNCED, ERROR, REVOKED, so a status test for the
  -- word "authorised" can never fire and would be a silent no-op.
  if v_root.authorised_at_server is not null then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('ALREADY_AUTHORISED_BY_THE_ORDINARY_OWNER'::text);
  end if;
  if v_root.status_text in ('SHEETS_PARTIAL','SHEETS_SYNCED','ERROR','REVOKED') then
    v_reasons:=v_reasons||pg_catalog.to_jsonb('STATUS_IS_NOT_A_NEW_ROOT_STATUS'::text);
  end if;

  return pg_catalog.jsonb_build_object(
    'blank',pg_catalog.jsonb_array_length(v_reasons)=0,
    'created_in_this_transaction',v_created_in_this_transaction,
    'root_timesheet_id',p_root_timesheet_id,
    'status',v_root.status_text,
    'snapshot_inventory',case when v_snapshot_inventory is null then 'null'::jsonb
      else pg_catalog.jsonb_build_object(
             'ok',v_snapshot_inventory->'ok',
             'authority',v_snapshot_inventory->'authority',
             'component_count',v_snapshot_inventory->'component_count') end,
    'reasons',v_reasons);
end;
$function$;

-- The canonical before-inventory of a whole request: one entry per member root,
-- ordered by root_ordinal, each carrying its component identities lower-cased
-- and sorted.  Its digest is what the accepted decision bundle stores as
-- `before_inventory_digest` (24 section 4.5 step 2, "approval digest"), so the
-- proposal composer and the coordinator compute the same value from the same
-- declared positions.  The caller's own per-root `inventory_digest` is
-- deliberately NOT included: it is a caller assertion, and the component
-- identities are the fact that binds.
create or replace function private.weekly_source_publication_before_inventory_v1(
  p_control jsonb,
  p_member_count integer
) returns jsonb
language plpgsql
immutable
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_out jsonb:='[]'::jsonb;
  v_entry jsonb;
  v_i integer;
begin
  for v_i in 1..coalesce(p_member_count,0) loop
    select position_element.value into v_entry
      from pg_catalog.jsonb_array_elements(
             coalesce(p_control->'before_positions','[]'::jsonb)) as position_element(value)
     where (position_element.value->>'root_ordinal')::integer=v_i;
    if v_entry is null then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','control.before_positions','reason','MISSING_ROOT_ORDINAL',
                'root_ordinal',v_i)::text;
    end if;
    v_out:=v_out||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'root_ordinal',pg_catalog.to_jsonb(v_i),
        'component_ids',coalesce((
          select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(component_element.value::uuid::text)
                                      order by component_element.value::uuid::text)
            from pg_catalog.jsonb_array_elements_text(
                   coalesce(v_entry->'component_ids','[]'::jsonb)) as component_element(value)
        ),'[]'::jsonb)));
    v_entry:=null;
  end loop;
  return v_out;
end;
$function$;

-- The receipt as the coordinator returns it: every immutable field, with the
-- digest rendered as lower-case hex so a caller never has to decode bytea.
create or replace function private.weekly_source_publication_receipt_json_v1(
  p_receipt_id uuid
) returns jsonb
language sql stable
set search_path to 'pg_catalog','pg_temp'
as $function$
  select pg_catalog.jsonb_build_object(
    'id',receipt_row.id,
    'decision_bundle_id',receipt_row.decision_bundle_id,
    'pending_bundle_id',receipt_row.pending_bundle_id,
    'bundle_revision',receipt_row.bundle_revision,
    'request_digest',pg_catalog.encode(receipt_row.request_digest,'hex'),
    'publication_mode',receipt_row.publication_mode,
    'candidate_id',receipt_row.candidate_id,
    'member_root_ids',pg_catalog.to_jsonb(receipt_row.member_root_ids),
    'member_family_booking_ids',pg_catalog.to_jsonb(receipt_row.member_family_booking_ids),
    'member_root_versions',pg_catalog.to_jsonb(receipt_row.member_root_versions),
    'head_ids',pg_catalog.to_jsonb(receipt_row.head_ids),
    'scope_change_tx_token',receipt_row.scope_change_tx_token,
    'decision_id',receipt_row.decision_id,
    'decided_by_user_id',receipt_row.decided_by_user_id,
    'released_by_worker_id',receipt_row.released_by_worker_id,
    'released_by_worker_run_id',receipt_row.released_by_worker_run_id,
    'census_json',receipt_row.census_json,
    'proof_json',receipt_row.proof_json,
    'created_at_utc',receipt_row.created_at_utc)
  from private.weekly_source_entitlement_publication_receipts as receipt_row
  where receipt_row.id=p_receipt_id;
$function$;

-- ---------------------------------------------------------------------------
-- 4. Interface I-4 — the atomic head-publication coordinator (core)
-- ---------------------------------------------------------------------------
-- Assumes the I-1 rotation locks are ALREADY HELD in this transaction and
-- receives the helper result as the proof of it (proof/32 section 6; H2-035).
--
-- Order, exactly file 26 Gate 5 steps 4 to 10 and proof/32 section 8:
--   1  exact receipt replay, before anything else (section 8 step 1);
--   2  the immutable accepted decision bundle, locked;
--   3  member identity revalidated against the lock result (section 4.0);
--   4  compare-and-swap on each member's expected current head, under lock;
--   5  the complete post-decision head proofs of H2-024;
--   6  the target root's authorisation state;
--   7  stage every member head and its complete component inventory;
--   8  interface I-6 for a genuinely new B root, after staging;
--   9  activate every head together, superseding the old ones;
--  10  current_entitlement_head_id on every live lineage generation;
--  11  ONE call to private.pay_workbench_scope_invalidate_v1, success required;
--  12  exactly one immutable receipt;
--  13  return it.
--
-- Return discipline: a failure before the first write is RETURNED as
-- {ok:false,code,retryable}; a failure after the first write RAISES and rolls
-- the whole transaction back (R11; R25 point 7).  proof/32 section 6 step 1
-- states the rule for the gate refusals - "No write has happened at this point,
-- so these are returned, not raised" - and this coordinator applies it
-- consistently.  A caller that ignores ok:false is the one way to get a double
-- publication out of this design.
create or replace function private.weekly_source_entitlement_publish_core_v1(
  p_request jsonb,
  p_publication_mode text,
  p_lock_result jsonb,
  p_pending_bundle_id uuid,
  p_worker_id text,
  p_worker_run_id uuid,
  p_census jsonb,
  p_proof jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_mode text;
  v_canonical jsonb;
  v_digest bytea;
  v_now timestamptz;
  v_err_message text;
  v_err_detail text;
  v_err_state text;
  v_bundle record;
  v_pending record;
  v_receipt record;
  v_decision_bundle_id uuid;
  v_bundle_revision bigint;
  v_candidate_id uuid;
  v_decision_id uuid;
  v_member_root_ids uuid[];
  v_member_family_booking_ids text[];
  v_member_root_versions integer[];
  v_head_ids uuid[];
  v_expected_head_ids uuid[]:=array[]::uuid[];
  v_current_head_ids uuid[]:=array[]::uuid[];
  v_prior_head_ids uuid[]:=array[]::uuid[];
  v_head_revisions bigint[]:=array[]::bigint[];
  v_n integer;
  v_i integer;
  v_control jsonb;
  v_family jsonb;
  v_member_timesheet_ids uuid[]:=array[]::uuid[];
  v_entitlement jsonb;
  v_choice jsonb;
  v_component jsonb;
  v_component_sha bytea;
  v_component_ids uuid[];
  v_before_ids uuid[];
  v_after_1 uuid[]:=array[]::uuid[];
  v_after_2 uuid[]:=array[]::uuid[];
  v_before_1 uuid[]:=array[]::uuid[];
  v_before_2 uuid[]:=array[]::uuid[];
  v_moved uuid[]:=array[]::uuid[];
  -- WP-06c review F1: the CONTENT hash the SOURCE authority holds for every
  -- component of member 1's before-position, keyed by component_id.  It is what
  -- a MOVED component must still equal on the destination side.
  v_source_component_hashes jsonb:='{}'::jsonb;
  v_moved_found integer;
  v_inventory_pairs jsonb;
  v_component_hashes jsonb;
  v_head_revision bigint;
  v_token uuid;
  v_invalidation jsonb;
  v_rows integer;
  v_live_generations integer;
  v_family_live_generations integer;
  v_family_members uuid[];
  v_any_generations integer;
  v_any_heads integer;
  v_target_auth jsonb;
  v_target_authorise_result jsonb;
  v_review jsonb;
  v_source_generation_digest bytea;
  v_contract_choice_digest bytea;
  v_before_inventory jsonb;
  v_before_inventory_digest bytea;
  v_acceptance_digest bytea;
  v_before_source text[]:=array[]::text[];
  v_effective jsonb;
  v_blank jsonb;
  v_jobs_before uuid[]:=array[]::uuid[];
  v_scope_tx_before uuid[]:=array[]::uuid[];
  v_scope_state_before jsonb:='{}'::jsonb;
  v_token_recheck uuid;
  v_declared_scope uuid[];
  v_normalised jsonb;
  v_offending jsonb;
  v_result_heads jsonb:='[]'::jsonb;
  v_lineage_rows integer:=0;
begin
  -- Service-only, exactly as public.weekly_source_timesheet_lineage_ensure_atomic_v1.
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  -- Shape validation and the one canonical digest.  Nothing has been written,
  -- so a malformed request is returned rather than raised.
  begin
    v_mode:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_publication_mode,'')));
    if v_mode not in ('IMMEDIATE','DEFERRED') then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_publication_mode','reason','EXPECTED_IMMEDIATE_OR_DEFERRED')::text;
    end if;
    -- proof/32 section 9 and H2-038: both Worker fields are required when the
    -- mode is DEFERRED and null when it is IMMEDIATE.
    if (v_mode='DEFERRED')<>(p_worker_id is not null and p_worker_run_id is not null)
       or (v_mode='IMMEDIATE' and (p_worker_id is not null or p_worker_run_id is not null)) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_worker_id','reason','WORKER_FIELDS_MUST_MATCH_MODE')::text;
    end if;
    if pg_catalog.jsonb_typeof(coalesce(p_census,'{}'::jsonb))<>'object'
       or pg_catalog.jsonb_typeof(coalesce(p_proof,'{}'::jsonb))<>'object' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_census','reason','EXPECTED_OBJECT')::text;
    end if;
    v_canonical:=private.weekly_source_publication_request_canonical_v1(
      p_request,v_mode,p_pending_bundle_id);
    v_digest:=private.weekly_source_publication_request_digest_v1(v_canonical);
  -- Review finding F10: catching only `invalid_parameter_value` let a malformed
  -- request RAISE instead of returning - an impossible calendar date (22008),
  -- an integer outside the range (22003) and a non-uuid in the control scope
  -- (22P02) all escaped.  Nothing has been written at this point, so every one
  -- of them is a returned refusal, and WP-08b no longer counts a caller's typo
  -- as a technical failure on its way to MANUAL_REVIEW.
  exception when invalid_parameter_value
              or datetime_field_overflow
              or invalid_datetime_format
              or numeric_value_out_of_range
              or invalid_text_representation then
    get stacked diagnostics v_err_message=message_text, v_err_detail=pg_exception_detail,
                            v_err_state=returned_sqlstate;
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code',case when v_err_state='22023' then v_err_message
                  else 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID' end,
      'retryable',false,
      'detail',case when coalesce(v_err_detail,'') ~ '^\{' then v_err_detail::jsonb
                    else pg_catalog.jsonb_build_object(
                           'reason','REQUEST_VALUE_COULD_NOT_BE_PARSED',
                           'sqlstate',v_err_state,'message',v_err_message) end);
  end;

  v_now:=pg_catalog.clock_timestamp();
  v_control:=coalesce(p_request->'control','{}'::jsonb);
  v_decision_bundle_id:=(v_canonical->>'decision_bundle_id')::uuid;
  v_bundle_revision:=(v_canonical->>'bundle_revision')::bigint;
  v_candidate_id:=(v_canonical->>'candidate_id')::uuid;
  v_decision_id:=(v_canonical->>'decision_id')::uuid;

  select pg_catalog.array_agg(root_element.value::uuid order by root_element.ordinality)
    into v_member_root_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_root_ids')
         with ordinality as root_element(value,ordinality);
  select pg_catalog.array_agg(booking_element.value order by booking_element.ordinality)
    into v_member_family_booking_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_family_booking_ids')
         with ordinality as booking_element(value,ordinality);
  select pg_catalog.array_agg(version_element.value::integer order by version_element.ordinality)
    into v_member_root_versions
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_root_versions')
         with ordinality as version_element(value,ordinality);
  select pg_catalog.array_agg(head_element.value::uuid order by head_element.ordinality)
    into v_head_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'head_ids')
         with ordinality as head_element(value,ordinality);
  v_n:=pg_catalog.cardinality(v_member_root_ids);

  -- H2-032: no duplicate root and no duplicate head id.  The receipt relation
  -- repeats both rules; refusing here keeps the failure a refusal rather than a
  -- rolled-back transaction.
  if not private.weekly_source_uuid_array_is_distinct_v1(v_member_root_ids)
     or not private.weekly_source_uuid_array_is_distinct_v1(v_head_ids) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DUPLICATE_ROOT_OR_HEAD_ID'));
  end if;
  if v_n=2 and pg_catalog.btrim(v_member_family_booking_ids[1])
              =pg_catalog.btrim(v_member_family_booking_ids[2]) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','MEMBERS_SHARE_ONE_FAMILY'));
  end if;

  -- ---- 1. exact receipt replay, before any mutation (proof/32 section 8.1) --
  -- The digest is only an index lookup: every immutable receipt field is
  -- compared before a replay may be returned (H2-032).
  select * into v_receipt
    from private.weekly_source_entitlement_publication_receipts as receipt_row
   where receipt_row.request_digest=v_digest;
  if found then
    if v_receipt.decision_bundle_id<>v_decision_bundle_id
       or v_receipt.bundle_revision<>v_bundle_revision
       or v_receipt.candidate_id<>v_candidate_id
       or v_receipt.member_root_ids is distinct from v_member_root_ids
       or v_receipt.member_family_booking_ids is distinct from v_member_family_booking_ids
       or v_receipt.member_root_versions is distinct from v_member_root_versions
       or v_receipt.head_ids is distinct from v_head_ids
       or v_receipt.decision_id<>v_decision_id
       or v_receipt.publication_mode<>v_mode
       or v_receipt.pending_bundle_id is distinct from p_pending_bundle_id then
      -- Round-5 ruling A1 control 5: "conflicting replay and a tampered row are
      -- PERMANENT integrity failures and go DIRECTLY to manual review; they are
      -- not retried ten times".  The same digest over different immutable
      -- receipt fields means two different economic decisions share one money
      -- identity, which no amount of retrying can resolve.  `retryable:false`
      -- alone only stops the immediate retry; the disposition below is what
      -- tells the deferred release owner to route the bundle to MANUAL_REVIEW
      -- at once instead of counting it as one of its ten technical failures.
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REPLAY_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','A_COMMITTED_RECEIPT_CARRIES_THIS_DIGEST_WITH_DIFFERENT_IMMUTABLE_FIELDS',
          'receipt_id',v_receipt.id,
          'request_digest',pg_catalog.encode(v_digest,'hex')));
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'published',true,'replayed',true,
      'receipt',private.weekly_source_publication_receipt_json_v1(v_receipt.id));
  end if;

  -- ---- 2. the immutable accepted decision bundle -------------------------
  select * into v_bundle
    from public.weekly_source_entitlement_decision_bundles as bundle_row
   where bundle_row.decision_bundle_id=v_decision_bundle_id
     and bundle_row.bundle_revision=v_bundle_revision
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_NOT_FOUND',
        'decision_bundle_id',v_decision_bundle_id,'bundle_revision',v_bundle_revision));
  end if;
  if v_bundle.candidate_id<>v_candidate_id
     or v_bundle.decision_id<>v_decision_id
     or v_bundle.proposed_head_ids is distinct from v_head_ids
     or (v_bundle.bundle_kind='SINGLE_ROOT')<>(v_n=1)
     or (v_bundle.bundle_kind='CROSS_CONTRACT_A_B')<>(v_n=2) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_DISAGREES_WITH_REQUEST',
        'bundle_kind',v_bundle.bundle_kind,'member_count',v_n));
  end if;
  if v_bundle.state not in ('PROPOSED','COMMITTED') then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_NOT_LIVE',
        'state',v_bundle.state));
  end if;
  -- Review finding F7.  The replay check above runs BEFORE the bundle lock and
  -- matches on the digest, so a SECOND, DIFFERENT request under an already
  -- COMMITTED bundle revision used to pass every pre-write check and be stopped
  -- only by the head primary key, as a raised 23505 that WP-08b would count as
  -- a technical failure.  A committed revision has had its one publication:
  -- anything that is not that exact request is refused here, with a code.
  if v_bundle.state='COMMITTED'
     and not exists (
       select 1
         from private.weekly_source_entitlement_publication_receipts as receipt_row
        where receipt_row.decision_bundle_id=v_decision_bundle_id
          and receipt_row.bundle_revision=v_bundle_revision
          and receipt_row.request_digest=v_digest) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_BUNDLE_REVISION_ALREADY_PUBLISHED','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','THIS_BUNDLE_REVISION_HAS_ALREADY_PUBLISHED_A_DIFFERENT_REQUEST',
        'decision_bundle_id',v_decision_bundle_id,'bundle_revision',v_bundle_revision));
  end if;

  -- ---- 2a0. DEFERRED mode is not trusted on the census (review U5) ---------
  -- The core's contract is "the caller ran the census", but a frozen root must
  -- never publish (24 section 4.4; proof/32 section 7, last bullet), and the
  -- reviewer executed a DEFERRED release that published with
  -- p_census = {"result":"FROZEN"} and a p_pending_bundle_id naming no row at
  -- all.  So the one step where the answer decides whether money moves is
  -- checked here as well as by the caller.
  if v_mode='DEFERRED' then
    if coalesce(p_census->>'result','')<>'RELEASABLE' then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_CENSUS_NOT_RELEASABLE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','A_DEFERRED_RELEASE_MAY_ONLY_PUBLISH_ON_A_RELEASABLE_CENSUS',
          'census_result',coalesce(p_census->'result','null'::jsonb)));
    end if;
    select * into v_pending
      from public.weekly_source_pending_entitlement_bundles as pending_row
     where pending_row.id=p_pending_bundle_id
       and pending_row.decision_bundle_id=v_decision_bundle_id
       and pending_row.bundle_revision=v_bundle_revision
       and pending_row.candidate_id=v_candidate_id
     for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','NO_PENDING_BUNDLE_ROW_FOR_THIS_DECISION_BUNDLE_AND_REVISION',
          'pending_bundle_id',p_pending_bundle_id,
          'decision_bundle_id',v_decision_bundle_id,
          'bundle_revision',v_bundle_revision));
    end if;
    -- Decision D10.  The migration cannot bind the pending bundle's stored
    -- request to its stored digest, because such a trigger would have to call
    -- the canonical encoder, which lives in a repeatable, and migrations are
    -- applied first: a rebuild from empty would fail.  The safety therefore
    -- belongs here, where the decision to move money is actually made.  Under
    -- the lock already held, the stored request and the stored digest are
    -- verified TOGETHER, and against the request being released.
    --
    -- Round-5 ruling A1 control 3 is exactly this: "release must lock the row,
    -- recalculate the digest from the stored canonical request and refuse
    -- BEFORE EFFECTS on any mismatch".  The row is locked `for update` above,
    -- the digest is recomputed by this coordinator from the stored request, and
    -- both refusals below happen before the first write.  Control 5 adds that a
    -- tampered row is a PERMANENT integrity failure that goes DIRECTLY to
    -- manual review, so each one carries the disposition the deferred release
    -- owner must honour instead of counting a technical failure.
    if private.weekly_source_publication_request_digest_v1(
         private.weekly_source_publication_request_canonical_v1(
           v_pending.request_json,'DEFERRED',p_pending_bundle_id))
       is distinct from v_pending.request_digest then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','THE_STORED_REQUEST_DOES_NOT_MATCH_ITS_STORED_DIGEST',
          'pending_bundle_id',p_pending_bundle_id,
          'stored_digest',pg_catalog.encode(v_pending.request_digest,'hex'),
          'recomputed_digest',pg_catalog.encode(
            private.weekly_source_publication_request_digest_v1(
              private.weekly_source_publication_request_canonical_v1(
                v_pending.request_json,'DEFERRED',p_pending_bundle_id)),'hex')));
    end if;
    if v_pending.request_digest is distinct from v_digest then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','THE_REQUEST_BEING_RELEASED_IS_NOT_THE_ONE_THAT_WAS_SAVED',
          'pending_bundle_id',p_pending_bundle_id,
          'stored_digest',pg_catalog.encode(v_pending.request_digest,'hex'),
          'release_digest',pg_catalog.encode(v_digest,'hex')));
    end if;
  end if;

  -- ---- 2b. the accepted decision BINDS what is published (review U1) -------
  -- 24 section 4.5 step 2 and file 26 Gate 5 step 4 require the coordinator to
  -- revalidate "the current source revision, Contract choices, Candidate,
  -- Client, week, approval digest and the immutable identity of every moved
  -- component".  Quoting the right bundle id, decision id and head ids is not
  -- enough: the request must equal the accepted decision in every identity the
  -- bundle row carries, or a caller could publish a different root, Contract,
  -- week and amount of money under the Office decision's identity and actor.
  v_choice:=(
    select choice_element.value
      from pg_catalog.jsonb_array_elements(
             v_canonical->'financial_request'->'contract_choices') as choice_element(value)
     where (choice_element.value->>'root_ordinal')::integer=1);
  if v_member_root_ids[1] is distinct from v_bundle.source_root_timesheet_id
     or v_member_family_booking_ids[1] is distinct from v_bundle.source_root_family_booking_id
     or (v_choice->>'contract_id')::uuid is distinct from v_bundle.source_contract_id then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','SOURCE_ROOT_DISAGREES_WITH_ACCEPTED_DECISION',
        'accepted_root',v_bundle.source_root_timesheet_id,'requested_root',v_member_root_ids[1],
        'accepted_family',v_bundle.source_root_family_booking_id,
        'requested_family',v_member_family_booking_ids[1],
        'accepted_contract',v_bundle.source_contract_id,
        'requested_contract',v_choice->'contract_id'));
  end if;
  v_choice:=null;
  if v_n=2 then
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=2);
    if v_member_root_ids[2] is distinct from v_bundle.target_root_timesheet_id
       or v_member_family_booking_ids[2] is distinct from v_bundle.target_root_family_booking_id
       or (v_choice->>'contract_id')::uuid is distinct from v_bundle.target_contract_id then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','TARGET_ROOT_DISAGREES_WITH_ACCEPTED_DECISION',
          'accepted_root',v_bundle.target_root_timesheet_id,'requested_root',v_member_root_ids[2],
          'accepted_family',v_bundle.target_root_family_booking_id,
          'requested_family',v_member_family_booking_ids[2],
          'accepted_contract',v_bundle.target_contract_id,
          'requested_contract',v_choice->'contract_id'));
    end if;
    v_choice:=null;
  elsif v_bundle.target_root_timesheet_id is not null
     or v_bundle.target_root_family_booking_id is not null
     or v_bundle.target_contract_id is not null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','SINGLE_ROOT_BUNDLE_CARRIES_A_TARGET_ROOT'));
  end if;

  -- The week is the accepted decision's, and it is also each root Timesheet's
  -- own week and Contract.  One ordinary root per Candidate, Contract and week
  -- (contract section 5) only means anything if the week is checked.
  for v_i in 1..v_n loop
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=v_i);
    if (v_choice->>'week_ending_date')::date is distinct from v_bundle.week_ending_date
       or not exists (
         select 1
           from public.timesheets as root_row
          where root_row.timesheet_id=v_member_root_ids[v_i]
            and root_row.week_ending_date=v_bundle.week_ending_date
            and root_row.contract_id=(v_choice->>'contract_id')::uuid) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','WEEK_OR_CONTRACT_DISAGREES_WITH_ACCEPTED_DECISION',
          'root_ordinal',v_i,'accepted_week',v_bundle.week_ending_date,
          'requested_week',v_choice->'week_ending_date',
          'requested_contract',v_choice->'contract_id'));
    end if;
    -- The Candidate must actually OWN the root.  The reviewer published a head,
    -- a receipt and an invalidation under a second Candidate for a root it did
    -- not own: the installed invalidator's ownership rule fires only when a
    -- current TSFIN row exists, so the coordinator checks the Contract itself
    -- rather than leaving it to I-1 or to Banking Pay.
    if not exists (
      select 1
        from public.contracts as contract_row
       where contract_row.id=(v_choice->>'contract_id')::uuid
         and contract_row.candidate_id=v_candidate_id) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','CANDIDATE_DOES_NOT_OWN_THE_ROOT',
          'root_ordinal',v_i,'candidate_id',v_candidate_id,
          'contract_id',v_choice->'contract_id'));
    end if;
    v_choice:=null;
  end loop;

  -- The three approval digests the bundle row carries, recomputed here with the
  -- one canonical encoder.  These are mode-independent by construction, so the
  -- same values bind an immediate publication and a deferred release.
  v_source_generation_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'source_revision');
  v_contract_choice_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'contract_choices');
  v_before_inventory:=private.weekly_source_publication_before_inventory_v1(v_control,v_n);
  v_before_inventory_digest:=private.weekly_source_publication_request_digest_v1(v_before_inventory);
  -- The acceptance digest: the canonical request in IMMEDIATE mode with no
  -- pending bundle.  publication_mode and pending_bundle_id are digest fields
  -- (proof/32 section 9), so the digest the RECEIPT carries changes with the
  -- mode and cannot be the one stored on the accepted decision.  The bundle
  -- row's request_digest is therefore always taken in IMMEDIATE/null, which is
  -- what the proposal composer can compute at proposal time, before any pending
  -- bundle exists.  Written into interfaces\PUBLICATION_REQUEST_SHAPE.md.
  v_acceptance_digest:=private.weekly_source_publication_request_digest_v1(
    private.weekly_source_publication_request_canonical_v1(p_request,'IMMEDIATE',null::uuid));
  if v_bundle.source_revision_digest is distinct from v_source_generation_digest
     or v_bundle.contract_choice_digest is distinct from v_contract_choice_digest
     or v_bundle.before_inventory_digest is distinct from v_before_inventory_digest
     or v_bundle.request_digest is distinct from v_acceptance_digest then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','APPROVAL_DIGESTS_DISAGREE_WITH_ACCEPTED_DECISION',
        'source_revision_digest_matches',
          v_bundle.source_revision_digest is not distinct from v_source_generation_digest,
        'contract_choice_digest_matches',
          v_bundle.contract_choice_digest is not distinct from v_contract_choice_digest,
        'before_inventory_digest_matches',
          v_bundle.before_inventory_digest is not distinct from v_before_inventory_digest,
        'request_digest_matches',
          v_bundle.request_digest is not distinct from v_acceptance_digest));
  end if;

  -- ---- 2a. the current source revision (24 section 4.5 step 2; R7) --------
  -- "revalidate the current source revision".  A head built from a superseded
  -- or merely prepared final revision must never become current.
  if not exists (
    select 1
      from public.weekly_source_final_revisions as revision_row
     where revision_row.id=(v_canonical->'financial_request'->'source_revision'->>'final_revision_id')::uuid
       and revision_row.source_cycle_id=(v_canonical->'financial_request'->'source_revision'->>'source_cycle_id')::uuid
       and revision_row.revision_number=(v_canonical->'financial_request'->'source_revision'->>'revision_number')::integer
       and revision_row.state='CURRENT'
       and pg_catalog.encode(revision_row.manifest_hash,'hex')
           =(v_canonical->'financial_request'->'source_revision'->>'manifest_hash')
       and pg_catalog.encode(revision_row.policy_fingerprint,'hex')
           =(v_canonical->'financial_request'->'source_revision'->>'policy_fingerprint')
  ) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_SOURCE_REVISION_STALE','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'source_revision',v_canonical->'financial_request'->'source_revision'));
  end if;

  -- ---- 3. member identity against the I-1 lock result ---------------------
  -- proof/32 section 4.0 integrity gate; proof/34 section 6: after first
  -- authorisation an unexpected rotation is an INTEGRITY FAILURE, never a stale
  -- rebuild.  This coordinator never rebuilds anything.
  if p_lock_result is null
     or pg_catalog.jsonb_typeof(p_lock_result)<>'object'
     or coalesce((p_lock_result->>'ok')::boolean,false) is not true
     or coalesce(p_lock_result->>'gate','')<>'GRANTED' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','LOCK_RESULT_NOT_GRANTED'));
  end if;

  for v_i in 1..v_n loop
    select family_element.value into v_family
      from pg_catalog.jsonb_array_elements(p_lock_result->'families') as family_element(value)
     where family_element.value->>'requested_timesheet_id'=v_member_root_ids[v_i]::text;
    if v_family is null
       or coalesce((v_family->>'requested_is_canonical')::boolean,false) is not true
       or coalesce((v_family->>'family_is_current')::boolean,false) is not true
       or (v_family->>'canonical_timesheet_id')::uuid is distinct from v_member_root_ids[v_i]
       or (v_family->>'canonical_version')::integer is distinct from v_member_root_versions[v_i]
       or pg_catalog.btrim(coalesce(v_family->>'family_booking_id',''))
          is distinct from pg_catalog.btrim(v_member_family_booking_ids[v_i]) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'requested_timesheet_id',v_member_root_ids[v_i],
          'lock_result_family',v_family));
    end if;
    select v_member_timesheet_ids||coalesce(
             pg_catalog.array_agg(member_element.value::uuid),array[]::uuid[])
      into v_member_timesheet_ids
      from pg_catalog.jsonb_array_elements_text(
             coalesce(v_family->'member_timesheet_ids','[]'::jsonb)) as member_element(value);

    -- WP-01a review U1: `root_family_booking_id` is free text on the head row and
    -- nothing in the schema ties it to the root's real booking_id, so the
    -- coordinator validates it itself.  The raw value must equal
    -- public.timesheets.booking_id of the canonical root BYTE FOR BYTE: the
    -- trimmed form is the lock and index key (proof/32 section 6 step 2), not an
    -- identity, and a differently cased or unrelated string would take a
    -- different advisory lock from the one protecting the uniqueness index.
    if not exists (
      select 1
        from public.timesheets as root_row
       where root_row.timesheet_id=v_member_root_ids[v_i]
         and root_row.booking_id=v_member_family_booking_ids[v_i]
         and root_row.version=v_member_root_versions[v_i]
         and root_row.is_current) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','FAMILY_BOOKING_ID_DOES_NOT_MATCH_THE_ROOT',
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'declared_family_booking_id',v_member_family_booking_ids[v_i],
          'declared_version',v_member_root_versions[v_i]));
    end if;
    v_family:=null;
  end loop;

  -- ---- 4. compare-and-swap on each member's expected current head ---------
  -- jsonb_array_elements_text turns a JSON null into a SQL NULL, which is
  -- exactly "the caller believes this root has no committed head yet".
  select pg_catalog.array_agg(expected_element.value::uuid
                              order by expected_element.ordinality)
    into v_expected_head_ids
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_control->'expected_current_head_ids','[]'::jsonb))
         with ordinality as expected_element(value,ordinality);
  if coalesce(pg_catalog.cardinality(v_expected_head_ids),0)<>v_n then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','EXPECTED_CURRENT_HEAD_IDS_NOT_ALIGNED'));
  end if;

  for v_i in 1..v_n loop
    -- One committed current head per root across both authority kinds
    -- (24 section 4.3), read under lock (H2-024).
    --
    -- WP-01a review U1: "at most one committed current head" is a partial unique
    -- index on the TRIMMED family string only, so it is not a schema guarantee
    -- for a physical root.  The coordinator therefore counts the rows itself,
    -- refuses more than one as an integrity failure rather than choosing one,
    -- and asserts that the head it found belongs to the canonical root I-1
    -- resolved.  It never falls back to stale TSFIN (27 section 5.1).
    select pg_catalog.count(*)::integer into v_rows
      from public.weekly_source_entitlement_heads as head_row
     where pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(v_member_family_booking_ids[v_i])
       and head_row.state='COMMITTED_CURRENT';
    if v_rows>1 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','MORE_THAN_ONE_COMMITTED_CURRENT_HEAD',
          'root_ordinal',v_i,'committed_current_heads',v_rows));
    end if;
    v_current_head_ids:=v_current_head_ids||(
      select head_row.id
        from public.weekly_source_entitlement_heads as head_row
       where pg_catalog.btrim(head_row.root_family_booking_id)
             =pg_catalog.btrim(v_member_family_booking_ids[v_i])
         and head_row.state='COMMITTED_CURRENT'
         for update);
    if v_current_head_ids[v_i] is not null
       and not exists (
         select 1
           from public.weekly_source_entitlement_heads as head_row
          where head_row.id=v_current_head_ids[v_i]
            and head_row.root_timesheet_id=v_member_root_ids[v_i]) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','COMMITTED_HEAD_BELONGS_TO_ANOTHER_PHYSICAL_ROOT',
          'root_ordinal',v_i,'current_head_id',v_current_head_ids[v_i]));
    end if;
    -- The MIRROR of the guard above, and the same defect class as WP-06 review
    -- finding F2: the family key found no head, but the PHYSICAL root carries
    -- one.  Since schema change S8 removed unique(root_timesheet_id) from the
    -- family relation, nothing keyed on the physical id is unique any more, so
    -- the two identities really can disagree.  Falling through here would take a
    -- TSFIN — or an unproved — before-position for a root that demonstrably HAS
    -- a committed head, understating the effective entitlement, which is exactly
    -- how a residual turns into an overpayment.  It costs one indexed lookup
    -- (weekly_source_entitlement_heads_committed_root_uq), so it is checked
    -- rather than assumed, and it is checked HERE so it covers the I-7 branch
    -- and the no-I-7 branch alike.
    if v_current_head_ids[v_i] is null
       and exists (
         select 1
           from public.weekly_source_entitlement_heads as head_row
          where head_row.root_timesheet_id=v_member_root_ids[v_i]
            and head_row.state='COMMITTED_CURRENT') then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','COMMITTED_HEAD_EXISTS_FOR_THE_PHYSICAL_ROOT_BUT_NOT_THE_DECLARED_FAMILY',
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'declared_family_booking_id',v_member_family_booking_ids[v_i],
          'physical_root_head_id',(
            select head_row.id
              from public.weekly_source_entitlement_heads as head_row
             where head_row.root_timesheet_id=v_member_root_ids[v_i]
               and head_row.state='COMMITTED_CURRENT')));
    end if;
    if v_current_head_ids[v_i] is distinct from v_expected_head_ids[v_i] then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_HEAD_CAS_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,
          'expected_current_head_id',v_expected_head_ids[v_i],
          'actual_current_head_id',v_current_head_ids[v_i]));
    end if;
    select coalesce(pg_catalog.max(head_row.head_revision),0)+1
      into v_head_revision
      from public.weekly_source_entitlement_heads as head_row
     where pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(v_member_family_booking_ids[v_i]);
    v_head_revisions:=v_head_revisions||v_head_revision;
    v_prior_head_ids:=v_prior_head_ids||(
      select head_row.id
        from public.weekly_source_entitlement_heads as head_row
       where pg_catalog.btrim(head_row.root_family_booking_id)
             =pg_catalog.btrim(v_member_family_booking_ids[v_i])
       order by head_row.head_revision desc
       limit 1);
  end loop;

  -- ---- 5. the complete post-decision head proofs (H2-024) -----------------
  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    select coalesce(pg_catalog.array_agg(
             (component_element.value->>'component_id')::uuid
             order by (component_element.value->>'component_ordinal')::integer),
             array[]::uuid[])
      into v_component_ids
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value);

    select coalesce(pg_catalog.array_agg(before_element.value::uuid),array[]::uuid[])
      into v_before_ids
      from pg_catalog.jsonb_array_elements_text(
             coalesce((select position_element.value->'component_ids'
                         from pg_catalog.jsonb_array_elements(
                                coalesce(v_control->'before_positions','[]'::jsonb)) as position_element(value)
                        where (position_element.value->>'root_ordinal')::integer=v_i),
                      'null'::jsonb)) as before_element(value);
    if (select position_element.value
          from pg_catalog.jsonb_array_elements(
                 coalesce(v_control->'before_positions','[]'::jsonb)) as position_element(value)
         where (position_element.value->>'root_ordinal')::integer=v_i) is null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','BEFORE_POSITION_MISSING','root_ordinal',v_i));
    end if;

    -- A head may never contain an adjustment, whatever key it arrives under
    -- (24 section 5; WB-007, WB-013; review U3 case H6c).  component_kind,
    -- economic_key_type and origin are free text on the relation, so the
    -- coordinator allowlists the kind and refuses the adjustment vocabulary
    -- outright rather than trusting the absence of an `adjustment_id` key.
    v_offending:=(
      select component_element.value
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where (component_element.value->>'component_kind') not in
               ('WORKED_TIME','ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE')
          or component_element.value->>'component_kind' ~* 'ADJUST|ADVANCE'
          or component_element.value->>'economic_key_type' ~* 'ADJUST|ADVANCE'
          or component_element.value->>'origin' ~* 'ADJUST|ADVANCE'
       limit 1);
    if v_offending is not null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_COMPONENT_KIND_FORBIDDEN','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'component',v_offending,
          'permitted_kinds',pg_catalog.jsonb_build_array(
            'WORKED_TIME','ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE')));
    end if;
    v_offending:=null;

    -- H2-024: "each before-position is read from the single committed effective
    -- authority under lock".  Three cases, and only the third is ever accepted
    -- without a server-side read (review U3).
    if v_current_head_ids[v_i] is not null then
      -- (1) A committed head exists: the declared position must equal its
      -- component set EXACTLY, and every RETAINED component must be
      -- byte-identical - the committed row stores component_sha256, so
      -- re-pricing a component that is merely "kept by id" is detectable and
      -- is refused (review U3 cases H10 and H4c).
      if exists (
        select 1
          from (select component_row.component_id
                  from public.weekly_source_entitlement_head_components as component_row
                 where component_row.head_id=v_current_head_ids[v_i]
                except
                select pg_catalog.unnest(v_before_ids)) as missing_from_declared
        union all
        select 1
          from (select pg_catalog.unnest(v_before_ids)
                except
                select component_row.component_id
                  from public.weekly_source_entitlement_head_components as component_row
                 where component_row.head_id=v_current_head_ids[v_i]) as extra_in_declared
      ) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_MISMATCH','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'current_head_id',v_current_head_ids[v_i]));
      end if;
      -- `component_sha256` is a CONTENT identity and deliberately excludes
      -- `component_ordinal`: the ordinal is the component's position inside a
      -- head, and a component that is retained while another moves out from in
      -- front of it legitimately changes position.  Position is still covered,
      -- by `inventory_digest` (the ordered ordinal/id pairs) and by
      -- `entitlement_digest` (the content hashes in ordinal order).
      v_offending:=(
        select pg_catalog.jsonb_build_object(
                 'component_id',component_element.value->'component_id',
                 'committed_sha256',pg_catalog.encode(committed_row.component_sha256,'hex'),
                 'requested_sha256',pg_catalog.encode(
                   private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),'hex'))
          from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
          join public.weekly_source_entitlement_head_components as committed_row
            on committed_row.head_id=v_current_head_ids[v_i]
           and committed_row.component_id=(component_element.value->>'component_id')::uuid
         where committed_row.component_sha256
               is distinct from private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value))
         limit 1);
      if v_offending is not null then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_RETAINED_COMPONENT_CHANGED','retryable',false,
          'detail',pg_catalog.jsonb_build_object('root_ordinal',v_i,'component',v_offending));
      end if;
      v_offending:=null;
      -- WP-06c review F1: member 1 is the SOURCE of a cross-Contract move, so
      -- its committed head is the authority for what every MOVED component
      -- actually held.  The content hashes are taken here, under the same lock
      -- and from the same rows the retained check just used, and are compared
      -- against the destination side after the set proofs.
      if v_i=1 then
        select coalesce(pg_catalog.jsonb_object_agg(
                 committed_row.component_id::text,
                 pg_catalog.encode(committed_row.component_sha256,'hex')),'{}'::jsonb)
          into v_source_component_hashes
          from public.weekly_source_entitlement_head_components as committed_row
         where committed_row.head_id=v_current_head_ids[v_i];
      end if;
      v_before_source:=v_before_source||'HEAD'::text;

    elsif pg_catalog.to_regprocedure(
            'private.weekly_source_effective_inventory_v1(uuid)') is not null then
      -- (2) No head yet, but interface I-7 exists (decision D9, built by WP-06):
      -- the before-position is derived SERVER-SIDE from the single committed
      -- effective authority - the ordinary financial snapshot - under the same
      -- locks, and the declared position must equal it.
      v_effective:=private.weekly_source_effective_inventory_v1(v_member_root_ids[v_i]);
      if coalesce(pg_catalog.jsonb_typeof(v_effective),'')<>'object' then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_EFFECTIVE_INVENTORY_INVALID'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_EFFECTIVE_INVENTORY_INVALID',
                  'root_ordinal',v_i,'result',v_effective)::text;
      end if;
      -- I-7 answers `ok:false` with an EMPTY components array when it cannot
      -- resolve the root.  Reading that as "the root holds nothing" would turn
      -- an integrity failure into a silent certified-zero publication, so the
      -- refusal is honoured before the sets are compared at all.
      if coalesce((v_effective->>'ok')::boolean,false) is not true then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','INTERFACE_I7_REFUSED_THE_ROOT',
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'effective_inventory',v_effective));
      end if;
      -- I-7 is reached ONLY when the family key above found no committed head,
      -- so the only authority it can legitimately report here is the ordinary
      -- financial snapshot.  If it reports a HEAD, the two keyings disagree
      -- about the same root — the shape of WP-06 review finding F2, in whichever
      -- direction the disagreement runs — and the coordinator must not pick a
      -- winner between them.  It refuses, cheaply, on a field it already holds.
      if v_effective->>'authority' is distinct from 'TSFIN' then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','INTERFACE_I7_REPORTS_AN_AUTHORITY_THE_FAMILY_KEY_DOES_NOT',
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'declared_family_booking_id',v_member_family_booking_ids[v_i],
            'i7_authority',v_effective->'authority','i7_head_id',v_effective->'head_id'));
      end if;
      if exists (
        select 1
          from (select (effective_element.value->>'component_id')::uuid as component_id
                  from pg_catalog.jsonb_array_elements(
                         coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)
                except
                select pg_catalog.unnest(v_before_ids)) as missing_from_declared
        union all
        select 1
          from (select pg_catalog.unnest(v_before_ids)
                except
                select (effective_element.value->>'component_id')::uuid
                  from pg_catalog.jsonb_array_elements(
                         coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)) as extra_in_declared
      ) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_MISMATCH','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'authority',v_effective->'authority',
            'reason','DECLARED_POSITION_DIFFERS_FROM_THE_EFFECTIVE_INVENTORY'));
      end if;
      -- I-7 also carries each component's content hash, so a component RETAINED
      -- from a head-less root gets the same byte-identity guarantee as one
      -- retained from a committed head (review finding U3(a), extended).
      v_offending:=(
        select pg_catalog.jsonb_build_object(
                 'component_id',component_element.value->'component_id',
                 'effective_sha256',effective_element.value->'component_sha256',
                 'requested_sha256',pg_catalog.encode(
                   private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(
                       component_element.value)),'hex'))
          from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
          join pg_catalog.jsonb_array_elements(
                 coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)
            on effective_element.value->>'component_id'=component_element.value->>'component_id'
         where effective_element.value->>'component_sha256'
               is distinct from pg_catalog.encode(
                 private.weekly_source_publication_request_digest_v1(
                   private.weekly_source_publication_component_content_v1(
                     component_element.value)),'hex')
         limit 1);
      if v_offending is not null then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_RETAINED_COMPONENT_CHANGED','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'authority',v_effective->'authority',
            'component',v_offending));
      end if;
      v_offending:=null;
      -- WP-06c review F1, the head-less source: I-7 carries each component's
      -- own content hash, computed through this file's canonicaliser, content
      -- projection and encoder, so it is directly comparable with a committed
      -- head row's `component_sha256` and with the destination side.
      if v_i=1 then
        select coalesce(pg_catalog.jsonb_object_agg(
                 effective_element.value->>'component_id',
                 effective_element.value->'component_sha256'),'{}'::jsonb)
          into v_source_component_hashes
          from pg_catalog.jsonb_array_elements(
                 coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value);
      end if;
      v_before_source:=v_before_source||'I7'::text;

    else
      -- (3) No head and no I-7.  The declared position cannot be proved, so it
      -- is never recorded as if it were.  An A-to-B bundle is REFUSED rather
      -- than published on an unverified before-position, because that is where
      -- "minus only the moved components" and "keeps every existing component"
      -- would otherwise rest on the caller's word (review U3 case G1-a).
      if v_n=2 then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_UNPROVABLE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'reason','NO_COMMITTED_HEAD_AND_INTERFACE_I7_IS_NOT_INSTALLED',
            'required_owner','private.weekly_source_effective_inventory_v1(uuid)'));
      end if;
      v_before_source:=v_before_source||'DECLARED_UNPROVED'::text;
    end if;

    if v_i=1 then
      v_after_1:=v_component_ids; v_before_1:=v_before_ids;
    else
      v_after_2:=v_component_ids; v_before_2:=v_before_ids;
    end if;
    v_entitlement:=null;
  end loop;

  select coalesce(pg_catalog.array_agg(moved_element.value::uuid),array[]::uuid[])
    into v_moved
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_control->'moved_component_ids','[]'::jsonb)) as moved_element(value);

  if v_n=1 then
    if pg_catalog.cardinality(v_moved)>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','MOVED_SET_ON_SINGLE_ROOT_BUNDLE'));
    end if;
  else
    -- "an already-authorised B keeps EVERY existing component" (24 section 4.5
    -- step 3).  This is tested FIRST so that a B which loses one gets the exact
    -- code the interface documents.  Placed after the combined set proof it was
    -- unreachable, because `B-after = B-before union moved` already implies
    -- `B-before is a subset of B-after` (review finding F12).
    if pg_catalog.cardinality(
         private.weekly_source_uuid_set_difference_v1(v_before_2,v_after_2))>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_TARGET_COMPONENT_DROPPED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'dropped',pg_catalog.to_jsonb(
            private.weekly_source_uuid_set_difference_v1(v_before_2,v_after_2))));
    end if;
    -- 24 section 4.5 step 3 and H2-024, proved in the same transaction.
    if pg_catalog.cardinality(v_moved)=0
       or not private.weekly_source_uuid_array_is_distinct_v1(v_moved)
       or private.weekly_source_uuid_set_equals_v1(
            v_before_1,private.weekly_source_uuid_set_union_v1(v_after_1,v_moved)) is not true
       or pg_catalog.cardinality(private.weekly_source_uuid_set_intersect_v1(v_after_1,v_moved))>0
       or pg_catalog.cardinality(private.weekly_source_uuid_set_intersect_v1(v_before_2,v_moved))>0
       or private.weekly_source_uuid_set_equals_v1(
            v_after_2,private.weekly_source_uuid_set_union_v1(v_before_2,v_moved)) is not true then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'a_before',pg_catalog.to_jsonb(v_before_1),'a_after',pg_catalog.to_jsonb(v_after_1),
          'b_before',pg_catalog.to_jsonb(v_before_2),'b_after',pg_catalog.to_jsonb(v_after_2),
          'moved',pg_catalog.to_jsonb(v_moved)));
    end if;

    -- Round-5 ruling, Part E, "Partial Contract-to-Contract move":
    --
    --   "Not in scope for this release.  The supported operation is the
    --    whole-entitlement move.  A requested partial move must take the named
    --    fail-closed path and explain that partial movement is unsupported; it
    --    must not approximate the move."
    --
    -- THE DEFINITION IS THE WHOLE OF THE RULE.  A move is WHOLE when the source
    -- member retains nothing after it, and PARTIAL otherwise.  Three statements
    -- of that are available here and they are the SAME statement, because the
    -- set proofs immediately above have already established
    -- `A_after = A_before \ moved`:
    --
    --   (i)   A-after is empty                     -> cardinality(v_after_1)=0
    --   (ii)  every component of A-before moved    -> moved = A_before
    --   (iii) member 1 is certified zero           -> the declared flag, which
    --         the coordinator re-checks against `component_count` below and
    --         which the head relation's own CHECK enforces
    --
    -- (i) is the one tested, because it is read from what the request actually
    -- carries rather than from a flag the caller sets.  (ii) is asserted
    -- alongside it: if the two ever disagreed, the set proofs above would have
    -- been wrong, so the disagreement is itself refused rather than resolved.
    --
    -- This is a SCOPE gate, so it is tested before the content proof below: a
    -- partial move is refused for being partial, in plain English, not for a
    -- hash mismatch it may not even have.  It is a returned refusal before the
    -- first write, exactly like every other check in this section.
    if pg_catalog.cardinality(v_after_1)>0
       or private.weekly_source_uuid_set_equals_v1(v_moved,v_before_1) is not true then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PARTIAL_MOVE_UNSUPPORTED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','ONLY_A_WHOLE_ENTITLEMENT_MOVE_IS_SUPPORTED_IN_THIS_RELEASE',
          'message','This bundle moves only part of the entitlement from one Contract '
                  ||'to the other and leaves the rest behind. Moving part of an '
                  ||'entitlement is not supported in this release: a Contract-to-Contract '
                  ||'amendment must move the whole entitlement, so that the old Contract '
                  ||'is left holding nothing. Nothing has been published. Either move '
                  ||'every component of the old Contract''s entitlement, or leave the '
                  ||'entitlement where it is.',
          'definition','A move is WHOLE when the source root retains nothing after it.',
          'a_before',pg_catalog.to_jsonb(v_before_1),
          'a_after',pg_catalog.to_jsonb(v_after_1),
          'a_after_component_count',pg_catalog.cardinality(v_after_1),
          'moved',pg_catalog.to_jsonb(v_moved),
          'moved_is_the_whole_source_position',
            private.weekly_source_uuid_set_equals_v1(v_moved,v_before_1)));
    end if;

    -- WP-06c review finding F1 (HIGH).  Everything above proves the move by
    -- IDENTITY.  A moved component's CONTENT was never compared with anything:
    -- it is absent from A-after and from B-before, so neither retained-component
    -- check above joins it, and a request composed outside the builder could
    -- re-price a shift on its way from A to B and be published with a receipt
    -- (executed: 85.50 -> 850.50 and 4.25 -> 40 hours).  The coordinator is the
    -- last gate before an entitlement is published, so it verifies rather than
    -- trusts: every moved component must still equal, byte for byte, what the
    -- SOURCE authority actually held - A's committed head row's
    -- `component_sha256` where A has a head, else interface I-7's own content
    -- hash for the same component.  `24 section 4.5` step 3 is "B-after is B's
    -- previously effective complete entitlement plus only those component(s)" -
    -- THOSE components, not components with those identities.
    --
    -- The comparison uses the same content projection as the retained checks, so
    -- `component_ordinal`, `movement_id` and `movement_group_id` - the three
    -- things a move legitimately changes - are excluded, and nothing else is.
    -- A moved component the source authority does not carry at all has a null
    -- hash here and is refused by the same test (`is distinct from`).
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=2);
    select pg_catalog.count(*)::integer into v_moved_found
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
     where (component_element.value->>'component_id')::uuid=any(v_moved);
    if v_moved_found<>pg_catalog.cardinality(v_moved) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','THE_DESTINATION_DOES_NOT_CARRY_EACH_MOVED_COMPONENT_EXACTLY_ONCE',
          'moved',pg_catalog.to_jsonb(v_moved),
          'moved_components_in_b_after',v_moved_found));
    end if;
    v_offending:=(
      select pg_catalog.jsonb_build_object(
               'component_id',component_element.value->'component_id',
               'source_authority',v_before_source[1],
               'source_sha256',pg_catalog.to_jsonb(
                 v_source_component_hashes->>(component_element.value->>'component_id')),
               'requested_sha256',pg_catalog.encode(
                 private.weekly_source_publication_request_digest_v1(
                   private.weekly_source_publication_component_content_v1(
                     component_element.value)),'hex'))
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where (component_element.value->>'component_id')::uuid=any(v_moved)
         and (v_source_component_hashes->>(component_element.value->>'component_id'))
             is distinct from pg_catalog.encode(
               private.weekly_source_publication_request_digest_v1(
                 private.weekly_source_publication_component_content_v1(
                   component_element.value)),'hex')
       limit 1);
    if v_offending is not null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVED_COMPONENT_CHANGED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',2,'component',v_offending));
    end if;
    v_offending:=null;
    v_entitlement:=null;
  end if;

  -- Movement identity: every moved component carries movement_id in its
  -- destination head and no retained component carries one.
  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    if exists (
      select 1
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where ((component_element.value->>'component_id')::uuid=any(v_moved)
              and v_i=2
              and component_element.value->'movement_id'='null'::jsonb)
          or (not ((component_element.value->>'component_id')::uuid=any(v_moved) and v_i=2)
              and component_element.value->'movement_id'<>'null'::jsonb)
    ) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVEMENT_IDENTITY_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('root_ordinal',v_i));
    end if;
    v_entitlement:=null;
  end loop;

  -- ---- 6. the target root's authorisation state ---------------------------
  v_target_auth:=case when pg_catalog.jsonb_typeof(coalesce(v_control->'target_root_authorisation','null'::jsonb))='object'
                      then v_control->'target_root_authorisation' end;
  v_review:=case when pg_catalog.jsonb_typeof(coalesce(v_control->'whole_root_office_review','null'::jsonb))='object'
                 then v_control->'whole_root_office_review' end;

  for v_i in 1..v_n loop
    -- Decision D8: the authorisation record is per ROOT and lives in
    -- public.weekly_source_root_authorisations, keyed on the physical
    -- root_timesheet_id, with at most one live generation per root.  It is no
    -- longer the per-source-row lineage binding.
    select pg_catalog.count(*)::integer into v_live_generations
      from public.weekly_source_root_authorisations as authorisation_row
     where authorisation_row.root_timesheet_id=v_member_root_ids[v_i]
       and authorisation_row.withdrawn_at_utc is null;

    -- WP-07 review finding F2, answered from THIS side of the seam.  The
    -- authorisation record is keyed on the PHYSICAL root_timesheet_id, and since
    -- schema change S8 removed the physical uniqueness a single family can hold
    -- several of them.  A test that counts only the canonical root's own
    -- generations lets a ROTATED family whose NON-CANONICAL member is already
    -- authorised be authorised a second time; the root is then payable and
    -- carries two live generations, which every withdrawal path treats as an
    -- impossible state, so it can never be withdrawn again.
    --
    -- The "is it already authorised?" test is therefore over the whole FAMILY:
    -- every member Timesheet the lock result carries for this root, and the
    -- family booking id the authorisation row itself records.  The coordinator
    -- does not rely on interface I-6 having been widened to match — that is
    -- precisely the assumption this finding punished.
    select coalesce(pg_catalog.array_agg(member_element.value::uuid),array[]::uuid[])
      into v_family_members
      from pg_catalog.jsonb_array_elements(p_lock_result->'families') as family_element(value)
     cross join pg_catalog.jsonb_array_elements_text(
                  coalesce(family_element.value->'member_timesheet_ids','[]'::jsonb))
                as member_element(value)
     where family_element.value->>'requested_timesheet_id'=v_member_root_ids[v_i]::text;
    select pg_catalog.count(*)::integer into v_family_live_generations
      from public.weekly_source_root_authorisations as authorisation_row
     where authorisation_row.withdrawn_at_utc is null
       and (authorisation_row.root_timesheet_id=v_member_root_ids[v_i]
            or authorisation_row.root_timesheet_id=any(v_family_members)
            or pg_catalog.btrim(authorisation_row.family_booking_id)
               =pg_catalog.btrim(v_member_family_booking_ids[v_i]));

    if v_i=2 and v_target_auth is not null then
      -- 24 section 4.5 step 4: only a genuinely new, never-authorised B root is
      -- created and authorised here, and it is never authorised silently.
      if v_family_live_generations>0 then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ALREADY_AUTHORISED','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'live_generations',v_family_live_generations,
            'live_generations_on_this_physical_root',v_live_generations,
            'root_timesheet_id',v_member_root_ids[v_i],
            'family_booking_id',v_member_family_booking_ids[v_i],
            'family_member_timesheet_ids',pg_catalog.to_jsonb(v_family_members)));
      end if;
      if (v_target_auth->>'timesheet_id')::uuid is distinct from v_member_root_ids[2] then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','TARGET_AUTHORISATION_TIMESHEET_MISMATCH'));
      end if;

      -- Review U2.  "Unknown to Weekly Source" is NOT the same as "blank": a B
      -- Timesheet that already existed, was never touched by Weekly Source and
      -- carries its own unrelated shifts satisfied the old test and was
      -- authorised silently, which 24 section 4.5 step 4, file 26 Gate 5 step 6,
      -- 27 section 8 step 6 and H2-024 all forbid.  B is now treated as
      -- genuinely new only when it is provably blank as well as unknown.
      v_blank:=private.weekly_source_publication_target_root_blank_v1(
        v_member_root_ids[2],v_member_family_booking_ids[2]);
      if coalesce((v_blank->>'blank')::boolean,false) is not true then
        -- The whole-root Office review is the only way past this, and it is a
        -- real control or it is nothing: a genuine boolean true, an existing
        -- reviewer, a time, bound to the accepted decision, and PERSISTED on
        -- the accepted decision so the act can be shown afterwards.  The three
        -- identity columns now exist on the bundle relation, so the check is
        -- the real one: the ACCEPTED DECISION must carry the review, and the
        -- request must quote exactly what it carries.
        if v_bundle.whole_root_review_required is not true
           or v_bundle.whole_root_reviewed_by_user_id is null
           or v_bundle.whole_root_reviewed_at_utc is null then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','THE_ACCEPTED_DECISION_CARRIES_NO_WHOLE_ROOT_OFFICE_REVIEW',
              'blank_check',v_blank,
              'decision_bundle_id',v_decision_bundle_id,
              'bundle_revision',v_bundle_revision));
        end if;
        -- The request's own review object: a real boolean, a real reviewer, a
        -- real time, and bound to this accepted decision.
        if v_review is null
           or pg_catalog.jsonb_typeof(v_review->'reviewed')<>'boolean'
           or (v_review->'reviewed')::boolean is not true
           or (v_review->>'reviewed_by_user_id') is null
           or (v_review->>'reviewed_at_utc') is null
           or (v_review->>'decision_id')::uuid is distinct from v_decision_id then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','WHOLE_ROOT_OFFICE_REVIEW_MISSING_OR_MALFORMED',
              'blank_check',v_blank,'review',v_review));
        end if;
        -- And it must be the review the ACCEPTED DECISION carries, not one the
        -- caller invented for this request.  The reviewer's existence is the
        -- bundle column's own foreign key, so it is proved by the row, not
        -- re-checked here.
        if (v_review->>'reviewed_by_user_id')::uuid
             is distinct from v_bundle.whole_root_reviewed_by_user_id
           or (v_review->>'reviewed_at_utc')::timestamptz
                is distinct from v_bundle.whole_root_reviewed_at_utc then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','REVIEW_IS_NOT_THE_ONE_ON_THE_ACCEPTED_DECISION',
              'accepted_reviewer',v_bundle.whole_root_reviewed_by_user_id,
              'requested_reviewer',v_review->'reviewed_by_user_id'));
        end if;
      end if;
    elsif v_live_generations=0 then
      -- A head over a root Weekly Source has not authorised would never reach
      -- payroll, so it is refused rather than written (decision D8: the live
      -- authorisation row is the test).
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_TARGET_NOT_AUTHORISED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'family_booking_id',v_member_family_booking_ids[v_i]));
    end if;
  end loop;

  -- =========================================================================
  -- Everything from here writes.  Every failure below RAISES and rolls the
  -- whole transaction back: no head, pointer, invalidation, dirty job, B
  -- authorisation or receipt may survive (R11; 26 Gate 5 pass condition).
  -- =========================================================================

  -- HANDOVER 2 round-4 ruling 6 needs to know which invalidations and dirty
  -- jobs this transaction created, so the state is snapshotted before the first
  -- write.  Reading the Workbench's own tables is allowed; nothing of theirs is
  -- edited, wrapped or re-created.
  select coalesce(pg_catalog.array_agg(job_row.id),array[]::uuid[]) into v_jobs_before
    from public.banking_pay_workbench_jobs as job_row;
  select coalesce(pg_catalog.array_agg(scope_tx_row.tx_token),array[]::uuid[]) into v_scope_tx_before
    from public.banking_pay_scope_change_transactions as scope_tx_row;
  select coalesce(pg_catalog.jsonb_object_agg(
           scope_state_row.timesheet_id::text,
           coalesce(scope_state_row.last_scope_change_tx_token::text,'')),'{}'::jsonb)
    into v_scope_state_before
    from private.banking_pay_workbench_timesheet_scope_state as scope_state_row
   where scope_state_row.candidate_id=v_candidate_id;

  -- ---- 7. stage every member head and its complete component inventory ----
  v_source_generation_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'source_revision');

  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=v_i);

    select coalesce(pg_catalog.jsonb_agg(
             pg_catalog.jsonb_build_object(
               'component_ordinal',component_element.value->'component_ordinal',
               'component_id',component_element.value->'component_id')
             order by (component_element.value->>'component_ordinal')::integer),'[]'::jsonb),
           coalesce(pg_catalog.jsonb_agg(
             pg_catalog.to_jsonb(pg_catalog.encode(
               private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),'hex'))
             order by (component_element.value->>'component_ordinal')::integer),'[]'::jsonb)
      into v_inventory_pairs,v_component_hashes
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value);

    insert into public.weekly_source_entitlement_heads(
      id,authority_kind,agency_id,candidate_id,contract_id,week_ending_date,
      root_timesheet_id,root_family_booking_id,root_timesheet_version,head_revision,
      prior_head_id,state,certified_zero,component_count,entitlement_digest,inventory_digest,
      source_generation_digest,decision_bundle_id,bundle_revision,decision_id,
      decided_by_user_id,staged_at_utc,created_at_utc
    ) values (
      v_head_ids[v_i],
      v_entitlement->>'authority_kind',
      v_bundle.agency_id,
      v_candidate_id,
      (v_choice->>'contract_id')::uuid,
      (v_choice->>'week_ending_date')::date,
      v_member_root_ids[v_i],
      v_member_family_booking_ids[v_i],
      v_member_root_versions[v_i],
      v_head_revisions[v_i],
      v_prior_head_ids[v_i],
      'STAGED',
      (v_entitlement->>'certified_zero')::boolean,
      (v_entitlement->>'component_count')::integer,
      -- entitlement_digest: the complete economic content of the head.
      private.weekly_source_publication_request_digest_v1(
        pg_catalog.jsonb_build_object(
          'authority_kind',v_entitlement->'authority_kind',
          'certified_zero',v_entitlement->'certified_zero',
          'component_count',v_entitlement->'component_count',
          'components',v_component_hashes)),
      -- inventory_digest: which components the head contains, identity only.
      private.weekly_source_publication_request_digest_v1(
        pg_catalog.jsonb_build_object('components',v_inventory_pairs)),
      v_source_generation_digest,
      v_decision_bundle_id,v_bundle_revision,v_decision_id,
      v_bundle.decided_by_user_id,v_now,v_now);

    insert into public.weekly_source_entitlement_head_components(
      head_id,component_ordinal,component_id,component_kind,economic_key_type,
      economic_key_value,component_member_identity,segment_id,segment_key,
      segment_stable_key,work_date,reference_number,hours_day,hours_night,hours_sat,
      hours_sun,hours_bh,additional_code_raw,unit_count,unit_pay_rate,unit_charge_rate,
      expense_code,pay_ex_vat,charge_ex_vat,exclude_from_pay,origin,
      decision_bundle_id,bundle_revision,movement_id,movement_group_id,
      component_sha256,created_at_utc)
    select
      v_head_ids[v_i],
      (component_element.value->>'component_ordinal')::integer,
      (component_element.value->>'component_id')::uuid,
      component_element.value->>'component_kind',
      component_element.value->>'economic_key_type',
      component_element.value->>'economic_key_value',
      component_element.value->>'component_member_identity',
      component_element.value->>'segment_id',
      component_element.value->>'segment_key',
      component_element.value->>'segment_stable_key',
      (component_element.value->>'work_date')::date,
      component_element.value->>'reference_number',
      (component_element.value->>'hours_day')::numeric,
      (component_element.value->>'hours_night')::numeric,
      (component_element.value->>'hours_sat')::numeric,
      (component_element.value->>'hours_sun')::numeric,
      (component_element.value->>'hours_bh')::numeric,
      component_element.value->>'additional_code_raw',
      (component_element.value->>'unit_count')::numeric,
      (component_element.value->>'unit_pay_rate')::numeric,
      (component_element.value->>'unit_charge_rate')::numeric,
      component_element.value->>'expense_code',
      (component_element.value->>'pay_ex_vat')::numeric,
      (component_element.value->>'charge_ex_vat')::numeric,
      (component_element.value->>'exclude_from_pay')::boolean,
      component_element.value->>'origin',
      v_decision_bundle_id,v_bundle_revision,
      (component_element.value->>'movement_id')::uuid,
      (component_element.value->>'movement_group_id')::uuid,
      private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),
      v_now
    from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
    order by (component_element.value->>'component_ordinal')::integer;

    v_entitlement:=null; v_choice:=null;
  end loop;

  -- ---- 8. interface I-6 for a genuinely new B root ------------------------
  -- After staging and before the single invalidation.  I-6 calls the UNCHANGED
  -- ordinary Authorise owner exactly once and inserts the lineage generation of
  -- proof/34 section 4.  It is late-bound: WP-07 owns it.
  if v_target_auth is not null then
    v_target_authorise_result:=private.weekly_source_first_authorise_core_v1(
      v_member_root_ids[2],
      v_target_auth->>'expected_row_signature',
      (v_target_auth->>'actor_user_id')::uuid,
      p_lock_result);
    if coalesce((v_target_authorise_result->>'ok')::boolean,false) is not true then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_TARGET_AUTHORISATION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_TARGET_AUTHORISATION_FAILED',
                'first_authorise_result',v_target_authorise_result)::text;
    end if;
  end if;

  -- ---- 9. activate every head together ------------------------------------
  -- 24 section 5.1: pass the same transaction token and scalar head/currentness
  -- evidence used by the publication receipt.  The token is taken before
  -- activation so the head, the invalidation and the receipt all carry it.
  v_token:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token is null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_SCOPE_TOKEN_UNAVAILABLE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_SCOPE_TOKEN_UNAVAILABLE')::text;
  end if;

  -- Notification reads the exact certified HEAD only after this coordinator has
  -- completed every aligned auth pointer, receipt and bundle. Defer ONLY its
  -- existing HEAD event; financial activation/order and all refusals stay intact.
  set constraints public.weekly_source_candidate_hours_push_head deferred;
  for v_i in 1..v_n loop
    if v_current_head_ids[v_i] is not null then
      update public.weekly_source_entitlement_heads
         set state='SUPERSEDED',
             superseded_at_utc=v_now,
             superseded_by_head_id=v_head_ids[v_i]
       where id=v_current_head_ids[v_i];
    end if;
  end loop;
  for v_i in 1..v_n loop
    update public.weekly_source_entitlement_heads
       set state='COMMITTED_CURRENT',
           committed_at_utc=v_now,
           publication_receipt_digest=v_digest,
           scope_change_tx_token=v_token
     where id=v_head_ids[v_i];
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_HEAD_ACTIVATION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_HEAD_ACTIVATION_FAILED',
                'head_id',v_head_ids[v_i],'rows',v_rows)::text;
    end if;
  end loop;

  -- ---- 10. current_entitlement_head_id on the live ROOT AUTHORISATION ------
  -- Decision D8 (WP-01c): the authorisation record, and therefore this pointer,
  -- is per ROOT in public.weekly_source_root_authorisations, not on the
  -- per-source-row lineage binding.  proof/34 section 4: written by the
  -- head-publication coordinator only, and nothing else on the generation row
  -- is touched.  The relation's own partial unique index gives at most one live
  -- generation per root, so exactly one row must move.
  for v_i in 1..v_n loop
    update public.weekly_source_root_authorisations
       set current_entitlement_head_id=v_head_ids[v_i]
     where root_timesheet_id=v_member_root_ids[v_i]
       and withdrawn_at_utc is null;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_ROOT_AUTHORISATION_POINTER_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_ROOT_AUTHORISATION_POINTER_FAILED',
                'root_ordinal',v_i,
                'root_timesheet_id',v_member_root_ids[v_i],
                'live_authorisation_rows_updated',v_rows)::text;
    end if;
    v_lineage_rows:=v_lineage_rows+v_rows;
  end loop;

  -- ---- 11. ONE bounded Workbench invalidation -----------------------------
  -- proof/32 section 8 step 3 and H2-036: exactly once, after every head and
  -- any B creation/Authorise, with the complete aligned Candidate/root pairs
  -- and the transaction token, success required before the receipt.  The
  -- ordinary Authorise trigger may queue a strict-subset job for the same
  -- Candidate under the same token; that is the accepted option 1 outcome and
  -- Weekly Source neither suppresses it nor folds it.
  v_invalidation:=private.pay_workbench_scope_invalidate_v1(
    p_candidate_ids=>pg_catalog.array_fill(v_candidate_id,array[v_n]),
    p_timesheet_ids=>v_member_root_ids,
    p_reason=>'WEEKLY_SOURCE_ENTITLEMENT_HEAD_PUBLICATION',
    p_scope_change_tx_token=>v_token,
    p_payload_json=>pg_catalog.jsonb_build_object(
      'weekly_source_publication',pg_catalog.jsonb_build_object(
        'decision_bundle_id',v_decision_bundle_id,
        'bundle_revision',v_bundle_revision,
        'publication_mode',v_mode,
        'request_digest',pg_catalog.encode(v_digest,'hex'),
        'head_ids',pg_catalog.to_jsonb(v_head_ids),
        'head_revisions',pg_catalog.to_jsonb(v_head_revisions))));
  -- `<>` on a missing key yields NULL, the IF does not fire, and the receipt is
  -- written anyway.  An invalidation result that does not say it covered
  -- exactly one Candidate must FAIL, so this is `is distinct from` (review
  -- finding, lower severity 1: executed with a wrapper that stripped the key,
  -- and the publication went through).
  if coalesce((v_invalidation->>'ok')::boolean,false) is not true
     or (v_invalidation->>'candidate_count')::integer is distinct from 1
     or (v_invalidation->>'scope_change_tx_token')::uuid is distinct from v_token
     or coalesce((v_invalidation->>'job_inserted_count')::integer,0)
        +coalesce((v_invalidation->>'job_coalesced_count')::integer,0)<1 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_FAILED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_FAILED',
              'invalidation',v_invalidation)::text;
  end if;

  -- ---- 11a. the R25 invalidation contract (HANDOVER 2 round 4, ruling 6) ---
  -- Restated R25: EVERY invalidation and dirty job created for this Candidate
  -- in this transaction - the explicit call, the ordinary Authorise route and
  -- every registered DIRTY_TRIGGER:<table>:<op> path - must carry the same
  -- token UUID and the same generation, and every non-complete job's scope,
  -- after the installed rotation normaliser, must be an exact subset of the
  -- declared aligned scope for that Candidate.  A different Candidate, an
  -- outside root or a token disagreement is a CONTRACT FAILURE, not extra
  -- harmless work, and rolls the whole transaction back.  Checked here, after
  -- the one explicit invalidation and BEFORE the receipt.
  --
  -- Ruling 6 point 1: calling the token owner again counts as the same token
  -- only if the returned UUID equals the controlling transaction token.
  v_token_recheck:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token_recheck is distinct from v_token then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','CONTROLLING_TOKEN_CHANGED_INSIDE_THE_TRANSACTION',
              'controlling_token',v_token,'recheck_token',v_token_recheck)::text;
  end if;

  -- The declared complete aligned scope for this Candidate, expanded through
  -- the INSTALLED rotation normaliser (call-only, contract section 2).
  v_normalised:=public._pay_workbench_normalise_timesheet_rotation_scope_payload(
    v_member_root_ids,array[]::uuid[]);
  select coalesce(pg_catalog.array_agg(distinct scope_element.value::uuid),array[]::uuid[])
    into v_declared_scope
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_normalised->'family_timesheet_ids',
                    coalesce(v_normalised->'canonical_timesheet_ids',
                             pg_catalog.to_jsonb(v_member_root_ids)))) as scope_element(value);
  v_declared_scope:=private.weekly_source_uuid_set_union_v1(v_declared_scope,v_member_root_ids);

  -- At most one new scope-change transaction, and it is the controlling token.
  if exists (
    select 1 from public.banking_pay_scope_change_transactions as scope_tx_row
     where not (scope_tx_row.tx_token=any(v_scope_tx_before))
       and scope_tx_row.tx_token is distinct from v_token) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_SECOND_SCOPE_CHANGE_TOKEN_WAS_CREATED_IN_THIS_TRANSACTION')::text;
  end if;

  -- Every job this transaction queued: same token, same (absent) generation,
  -- this Candidate, and a scope inside the declared aligned scope.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
             'job_id',job_row.id,'job_type',job_row.job_type,
             'candidate_id',job_row.candidate_id,
             'scope_change_tx_token',job_row.scope_change_tx_token,
             'scope_change_generation',job_row.scope_change_generation,
             'targeted_timesheet_ids',job_row.payload_json->'targeted_timesheet_ids',
             'reason',job_row.payload_json->'reason')
      from public.banking_pay_workbench_jobs as job_row
     where not (job_row.id=any(v_jobs_before))
       and (
         job_row.scope_change_tx_token is distinct from v_token
         or job_row.scope_change_generation is not null
         or (job_row.candidate_id is not null and job_row.candidate_id<>v_candidate_id)
         or exists (
           select 1
             from pg_catalog.jsonb_array_elements_text(
                    coalesce(job_row.payload_json->'targeted_timesheet_ids','[]'::jsonb)) as target(value)
            where not (target.value::uuid=any(v_declared_scope)))
         or exists (
           select 1
             from pg_catalog.jsonb_array_elements_text(
                    coalesce(job_row.payload_json->'linked_timesheet_ids','[]'::jsonb)) as linked(value)
            where not (linked.value::uuid=any(v_declared_scope))))
     limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_JOB_QUEUED_IN_THIS_TRANSACTION_BREAKS_THE_R25_CONTRACT',
              'controlling_token',v_token,
              'declared_scope',pg_catalog.to_jsonb(v_declared_scope),
              'job',v_offending)::text;
  end if;

  -- Every scope-state row THIS PUBLICATION dirtied for this Candidate.  The
  -- snapshot taken before the first write holds each row's token as it then
  -- was, so a row that already carried the controlling token before the
  -- publication began is not attributed to the publication.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
             'timesheet_id',scope_state_row.timesheet_id,
             'candidate_id',scope_state_row.candidate_id,
             'last_scope_change_tx_token',scope_state_row.last_scope_change_tx_token,
             'last_dirty_reason',scope_state_row.last_dirty_reason)
      from private.banking_pay_workbench_timesheet_scope_state as scope_state_row
     where scope_state_row.candidate_id=v_candidate_id
       and scope_state_row.last_scope_change_tx_token=v_token
       and coalesce(v_scope_state_before->>scope_state_row.timesheet_id::text,'')
           is distinct from v_token::text
       and not (scope_state_row.timesheet_id=any(v_declared_scope))
     limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_SCOPE_STATE_ROW_OUTSIDE_THE_DECLARED_ALIGNED_SCOPE_WAS_DIRTIED',
              'declared_scope',pg_catalog.to_jsonb(v_declared_scope),
              'scope_state',v_offending)::text;
  end if;

  -- Exactly one effective complete-scope dirty result per Candidate and token
  -- (ruling 6 point 6).
  if (select pg_catalog.count(*)
        from public.banking_pay_workbench_jobs as job_row
       where job_row.candidate_id=v_candidate_id
         and job_row.scope_change_tx_token=v_token
         and job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
         and job_row.status in ('QUEUED','RUNNING')
         and private.weekly_source_uuid_set_equals_v1(
               (select coalesce(pg_catalog.array_agg(distinct target.value::uuid),array[]::uuid[])
                  from pg_catalog.jsonb_array_elements_text(
                         coalesce(job_row.payload_json->'targeted_timesheet_ids','[]'::jsonb)) as target(value)),
               v_member_root_ids))<>1 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','NOT_EXACTLY_ONE_COMPLETE_SCOPE_JOB_FOR_THE_CANDIDATE_UNDER_THIS_TOKEN')::text;
  end if;

  -- ---- 12. exactly one immutable receipt ----------------------------------
  insert into private.weekly_source_entitlement_publication_receipts(
    decision_bundle_id,pending_bundle_id,bundle_revision,request_digest,publication_mode,
    candidate_id,member_root_ids,member_family_booking_ids,member_root_versions,head_ids,
    scope_change_tx_token,decision_id,decided_by_user_id,released_by_worker_id,
    released_by_worker_run_id,census_json,proof_json,created_at_utc
  ) values (
    v_decision_bundle_id,p_pending_bundle_id,v_bundle_revision,v_digest,v_mode,
    v_candidate_id,v_member_root_ids,v_member_family_booking_ids,v_member_root_versions,
    v_head_ids,v_token,v_decision_id,v_bundle.decided_by_user_id,p_worker_id,
    p_worker_run_id,coalesce(p_census,'{}'::jsonb),coalesce(p_proof,'{}'::jsonb),v_now)
  returning * into v_receipt;

  if v_bundle.state='PROPOSED' then
    update public.weekly_source_entitlement_decision_bundles
       set state='COMMITTED',committed_at_utc=v_now
     where decision_bundle_id=v_decision_bundle_id
       and bundle_revision=v_bundle_revision;
  end if;

  -- The same automatic HEAD trigger now sees the complete approved publication.
  -- Its original privacy/reconciliation/dedupe/withhold semantics are unchanged.
  set constraints public.weekly_source_candidate_hours_push_head immediate;

  for v_i in 1..v_n loop
    v_result_heads:=v_result_heads||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'root_ordinal',v_i,
        'head_id',v_head_ids[v_i],
        'head_revision',v_head_revisions[v_i],
        'prior_head_id',v_prior_head_ids[v_i],
        'superseded_head_id',v_current_head_ids[v_i],
        'root_timesheet_id',v_member_root_ids[v_i],
        'family_booking_id',v_member_family_booking_ids[v_i],
        'root_timesheet_version',v_member_root_versions[v_i]));
  end loop;

  return pg_catalog.jsonb_build_object(
    'ok',true,'published',true,'replayed',false,
    'receipt',private.weekly_source_publication_receipt_json_v1(v_receipt.id),
    'heads',v_result_heads,
    'scope_change_tx_token',v_token,
    'invalidation',v_invalidation,
    'root_authorisations_pointed',v_lineage_rows,
    'before_position_source',pg_catalog.to_jsonb(v_before_source),
    'declared_aligned_scope',pg_catalog.to_jsonb(v_declared_scope),
    'member_timesheet_ids',pg_catalog.to_jsonb(v_member_timesheet_ids));
end;
$function$;

-- ---------------------------------------------------------------------------
-- 5. Interface I-4 — the immediate publication entry point
-- ---------------------------------------------------------------------------
-- Takes the I-1 locks with job type WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION
-- (proof/32 section 6 step 1), runs the I-2 census over EVERY physical member of
-- EVERY family, and either calls the core (IMMEDIATE) or, when the census is
-- FROZEN, calls I-5 and publishes nothing (24 section 4.4).  CENSUS_ERROR
-- refuses with no write.
create or replace function private.weekly_source_entitlement_publish_immediate_v1(
  p_request jsonb
) returns jsonb
language plpgsql
volatile
security definer
set search_path to 'pg_catalog','pg_temp'
as $function$
declare
  v_candidate_id uuid;
  v_member_root_ids uuid[];
  v_member_timesheet_ids uuid[]:=array[]::uuid[];
  v_lock_result jsonb;
  v_census jsonb;
  v_core jsonb;
  v_pending jsonb;
  v_replay_canonical jsonb;
  v_replay_receipt record;
  v_saved record;
  v_saved_rows integer;
  v_err_message text;
  v_err_detail text;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  if p_request is null or pg_catalog.jsonb_typeof(p_request)<>'object'
     or pg_catalog.jsonb_typeof(coalesce(p_request->'member_root_ids','null'::jsonb))<>'array' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','EXPECTED_OBJECT_WITH_MEMBER_ROOT_IDS'));
  end if;
  v_candidate_id:=(p_request->>'candidate_id')::uuid;
  select pg_catalog.array_agg(root_element.value::uuid order by root_element.ordinality)
    into v_member_root_ids
    from pg_catalog.jsonb_array_elements_text(p_request->'member_root_ids')
         with ordinality as root_element(value,ordinality);

  -- ---- exact receipt replay, FIRST (review U4) ----------------------------
  -- proof/32 section 8 step 1 and section 2: "Exact receipt replay ... is
  -- evaluated FIRST"; 24 section 5.1: "An exact idempotent replay must return
  -- the already committed receipt before calling the invalidator".
  --
  -- The core has this check, but the core is reached only on a RELEASABLE
  -- census, and the normal state after a publication is that the Workbench
  -- drafts the new entitlement and FREEZES the root.  A retry whose first
  -- response was lost therefore used to fall into the FROZEN branch and save a
  -- PENDING bundle for a decision that was already published, sending the
  -- stale warning to the very Draft paying that entitlement.  The replay is
  -- answered here, before the serial gate, the locks, the census and I-5.
  begin
    v_replay_canonical:=private.weekly_source_publication_request_canonical_v1(
      p_request,'IMMEDIATE',null::uuid);
  exception when invalid_parameter_value then
    get stacked diagnostics v_err_message=message_text, v_err_detail=pg_exception_detail;
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code',v_err_message,'retryable',false,
      'detail',case when coalesce(v_err_detail,'') ~ '^\{' then v_err_detail::jsonb
                    else pg_catalog.to_jsonb(v_err_detail) end);
  end;
  select * into v_replay_receipt
    from private.weekly_source_entitlement_publication_receipts as receipt_row
   where receipt_row.request_digest
         =private.weekly_source_publication_request_digest_v1(v_replay_canonical);
  if found then
    -- A digest hit is only an index lookup: every immutable receipt field is
    -- compared before a replay may be returned (H2-032).
    if v_replay_receipt.decision_bundle_id
         is distinct from (v_replay_canonical->>'decision_bundle_id')::uuid
       or v_replay_receipt.bundle_revision
            is distinct from (v_replay_canonical->>'bundle_revision')::bigint
       or v_replay_receipt.candidate_id is distinct from v_candidate_id
       or v_replay_receipt.member_root_ids is distinct from v_member_root_ids
       -- Every immutable receipt field, exactly as the core compares them
       -- (H2-032): the digest is only an index lookup.
       or pg_catalog.to_jsonb(v_replay_receipt.member_family_booking_ids)
            is distinct from v_replay_canonical->'member_family_booking_ids'
       or pg_catalog.to_jsonb(v_replay_receipt.member_root_versions)
            is distinct from v_replay_canonical->'member_root_versions'
       or pg_catalog.to_jsonb(v_replay_receipt.head_ids)
            is distinct from v_replay_canonical->'head_ids'
       or v_replay_receipt.decision_id
            is distinct from (v_replay_canonical->>'decision_id')::uuid
       or v_replay_receipt.publication_mode<>'IMMEDIATE'
       or v_replay_receipt.pending_bundle_id is not null then
      -- Round-5 ruling A1 control 5, at the entry point as well as in the core:
      -- a conflicting replay is a PERMANENT integrity failure that goes DIRECTLY
      -- to manual review, never one of ten retries.
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REPLAY_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','A_COMMITTED_RECEIPT_CARRIES_THIS_DIGEST_WITH_DIFFERENT_IMMUTABLE_FIELDS',
          'receipt_id',v_replay_receipt.id));
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'published',true,'replayed',true,
      'receipt',private.weekly_source_publication_receipt_json_v1(v_replay_receipt.id));
  end if;

  -- Interface I-1 (WP-03), late-bound.
  perform private.weekly_source_pay_query_admit_v2();
  v_lock_result:=private.weekly_source_lock_and_resolve_families_v1(
    v_candidate_id,
    v_member_root_ids,
    'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',
    pg_catalog.gen_random_uuid(),
    'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if coalesce((v_lock_result->>'ok')::boolean,false) is not true then
    return v_lock_result||pg_catalog.jsonb_build_object('published',false,'replayed',false);
  end if;

  -- proof/34 section 8 and interface I-2: EVERY physical member of EVERY
  -- family, never only the canonical rows.
  select coalesce(pg_catalog.array_agg(distinct member_element.value::uuid),array[]::uuid[])
    into v_member_timesheet_ids
    from pg_catalog.jsonb_array_elements(v_lock_result->'families') as family_element(value)
   cross join lateral pg_catalog.jsonb_array_elements_text(
           coalesce(family_element.value->'member_timesheet_ids','[]'::jsonb)) as member_element(value);

  v_census:=private.weekly_source_freeze_census_v1(v_candidate_id,v_member_timesheet_ids);

  if coalesce(v_census->>'result','')='CENSUS_ERROR' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_CENSUS_ERROR','retryable',false,
      'census',v_census);
  end if;

  if coalesce(v_census->>'result','')='FROZEN' then
    -- 24 section 4.4: the decision is saved as pending, the previous effective
    -- entitlement remains current, and the existing Draft and all frozen
    -- evidence remain unchanged.  Interface I-5 (WP-08b), late-bound.
    v_pending:=private.weekly_source_pending_entitlement_bundle_save_v1(
      p_request,v_lock_result,v_census);

    -- Decision D10, the SAVE half.  A pending bundle is a promise to move money
    -- later, so before this transaction commits the coordinator re-reads what
    -- was actually stored, under the locks it already holds, and proves the
    -- stored request and the stored digest agree with each other and with the
    -- request it was given.  A disagreement raises and rolls the save back;
    -- it is never merely recorded.
    if coalesce((v_pending->>'ok')::boolean,false) is true then
      -- Round-5 ruling A1 control 2: "verify request plus digest UNDER THE SAME
      -- LOCK when saving".  The row is therefore re-read `for update`, and its
      -- cardinality is an explicit check rather than a `select ... into` that
      -- would silently take an arbitrary row if a second live pending bundle
      -- ever existed for one decision revision (Part 1 review rule 5).
      select pg_catalog.count(*)::integer into v_saved_rows
        from public.weekly_source_pending_entitlement_bundles as pending_row
       where pending_row.decision_bundle_id=(p_request->>'decision_bundle_id')::uuid
         and pending_row.bundle_revision=(p_request->>'bundle_revision')::bigint
         and pending_row.state in ('PENDING','RELEASING');
      if v_saved_rows>1 then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID',
                  'reason','MORE_THAN_ONE_LIVE_PENDING_BUNDLE_FOR_THIS_DECISION_REVISION',
                  'integrity_failure',true,'disposition','MANUAL_REVIEW',
                  'decision_bundle_id',p_request->'decision_bundle_id',
                  'bundle_revision',p_request->'bundle_revision',
                  'pending_bundle_rows',v_saved_rows)::text;
      end if;
      select pending_row.id,pending_row.request_json,pending_row.request_digest
        into v_saved
        from public.weekly_source_pending_entitlement_bundles as pending_row
       where pending_row.decision_bundle_id=(p_request->>'decision_bundle_id')::uuid
         and pending_row.bundle_revision=(p_request->>'bundle_revision')::bigint
         and pending_row.state in ('PENDING','RELEASING')
         for update;
      if not found then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_NOT_SAVED'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_NOT_SAVED',
                  'save_result',v_pending)::text;
      end if;
      if private.weekly_source_publication_request_digest_v1(
           private.weekly_source_publication_request_canonical_v1(
             v_saved.request_json,'DEFERRED',v_saved.id))
         is distinct from v_saved.request_digest
         or private.weekly_source_publication_request_digest_v1(
              private.weekly_source_publication_request_canonical_v1(
                p_request,'DEFERRED',v_saved.id))
            is distinct from v_saved.request_digest then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID',
                  'integrity_failure',true,'disposition','MANUAL_REVIEW',
                  'reason','THE_SAVED_REQUEST_AND_ITS_SAVED_DIGEST_DO_NOT_AGREE',
                  'pending_bundle_id',v_saved.id,
                  'stored_digest',pg_catalog.encode(v_saved.request_digest,'hex'))::text;
      end if;
    end if;

    return pg_catalog.jsonb_build_object(
      'ok',coalesce((v_pending->>'ok')::boolean,false),
      'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_DEFERRED_PENDING_FREEZE',
      'retryable',false,
      'pending',v_pending,'census',v_census,'lock_result',v_lock_result,
      'pending_bundle_verified',v_saved.id);
  end if;

  if coalesce(v_census->>'result','')<>'RELEASABLE' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_CENSUS_ERROR','retryable',false,
      'census',v_census);
  end if;

  -- proof/32 section 9: census_json and proof_json are "an empty object for
  -- immediate".  The census that was actually run is returned to the caller,
  -- not written to the frozen receipt relation.
  v_core:=private.weekly_source_entitlement_publish_core_v1(
    p_request=>p_request,
    p_publication_mode=>'IMMEDIATE',
    p_lock_result=>v_lock_result,
    p_pending_bundle_id=>null::uuid,
    p_worker_id=>null::text,
    p_worker_run_id=>null::uuid,
    p_census=>'{}'::jsonb,
    p_proof=>'{}'::jsonb);

  return v_core||pg_catalog.jsonb_build_object('census',v_census,'lock_result',v_lock_result);
end;
$function$;

-- ---------------------------------------------------------------------------
-- 6. Ownership and privileges
-- ---------------------------------------------------------------------------
alter function private.weekly_source_canonical_json_text_v1(jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_request_digest_v1(jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_scalar_v1(jsonb,text,text,integer,boolean) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_require_keys_v1(jsonb,text[],text) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_component_canonical_v1(jsonb,text) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_request_canonical_v1(jsonb,text,uuid) OWNER TO CURRENT_USER;
alter function private.weekly_source_uuid_set_union_v1(uuid[],uuid[]) OWNER TO CURRENT_USER;
alter function private.weekly_source_uuid_set_intersect_v1(uuid[],uuid[]) OWNER TO CURRENT_USER;
alter function private.weekly_source_uuid_set_difference_v1(uuid[],uuid[]) OWNER TO CURRENT_USER;
alter function private.weekly_source_uuid_set_equals_v1(uuid[],uuid[]) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_component_content_v1(jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_target_root_blank_v1(uuid,text) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_before_inventory_v1(jsonb,integer) OWNER TO CURRENT_USER;
alter function private.weekly_source_publication_receipt_json_v1(uuid) OWNER TO CURRENT_USER;
alter function private.weekly_source_entitlement_publish_core_v1(jsonb,text,jsonb,uuid,text,uuid,jsonb,jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_entitlement_publish_immediate_v1(jsonb) OWNER TO CURRENT_USER;

revoke all on function private.weekly_source_canonical_json_text_v1(jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_request_digest_v1(jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_scalar_v1(jsonb,text,text,integer,boolean) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_require_keys_v1(jsonb,text[],text) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_component_canonical_v1(jsonb,text) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_request_canonical_v1(jsonb,text,uuid) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_uuid_set_union_v1(uuid[],uuid[]) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_uuid_set_intersect_v1(uuid[],uuid[]) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_uuid_set_difference_v1(uuid[],uuid[]) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_uuid_set_equals_v1(uuid[],uuid[]) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_component_content_v1(jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_target_root_blank_v1(uuid,text) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_before_inventory_v1(jsonb,integer) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_publication_receipt_json_v1(uuid) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_entitlement_publish_core_v1(jsonb,text,jsonb,uuid,text,uuid,jsonb,jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_entitlement_publish_immediate_v1(jsonb) from public,anon,authenticated,service_role;

comment on function private.weekly_source_publication_request_digest_v1(jsonb) is
  'The one canonical Weekly Source publication request-digest encoder, shared by immediate publication, deferred release and replay verification (proof/32 section 9; H2-032).';
comment on function private.weekly_source_entitlement_publish_core_v1(jsonb,text,jsonb,uuid,text,uuid,jsonb,jsonb) is
  'Atomic Weekly Source entitlement head-publication coordinator (interface I-4). Assumes the I-1 rotation locks are already held. One invalidation, one receipt, all or nothing (proof/32 sections 6 to 9; 24 section 4.5; file 26 Gate 5).';
comment on function private.weekly_source_entitlement_publish_immediate_v1(jsonb) is
  'Immediate Weekly Source entitlement publication (interface I-4): I-1 locks, I-2 census, then the core, or I-5 when the census is FROZEN.';



-- Capture the exact newly authorised ordinary or independent expense-carrier
-- financial row. The trigger is dormant until the replacement is the exclusive
-- financial owner. Source HOURS have a separate Source-owned producer.




create or replace function private.bpay_next_publish_ordinary_from_financial_v1(
  p_financial_id uuid
) returns uuid
language plpgsql security definer
set search_path = pg_catalog, public, private
as $function$
declare
  v_tf public.timesheets_financials%rowtype;
  v_ts public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_work private.bpay_next_work%rowtype;
  v_revision_id uuid;
  v_line_id uuid;
  v_shift_id uuid;
  v_command_id uuid:=pg_catalog.gen_random_uuid();
  v_mode text;
  v_route text;
  v_detail_kind text;
  v_segment jsonb;
  v_segment_row record;
  v_schedule jsonb;
  v_shift_entry jsonb;
  v_extra record;
  v_bucket record;
  v_break jsonb;
  v_segment_count integer:=0;
  v_additional_count integer:=0;
  v_expense_count integer:=0;
  v_mileage_count integer:=0;
  v_base_count integer:=0;
  v_expected_count integer;
  v_schedule_count integer;
  v_resolved_daily_rates boolean;
  v_available_daily_evidence jsonb;
  v_available_daily_rows jsonb;
  v_line_no integer:=0;
  v_rate_detail_count integer;
  v_break_no integer;
  v_shift_no integer;
  v_break_total integer;
  v_break_mins integer;
  v_begin_mins integer;
  v_end_mins integer;
  v_break_start text;
  v_break_end text;
  v_shift_start_local text;
  v_shift_end_local text;
  v_hours numeric;
  v_amount numeric;
  v_base_amount numeric;
  v_expense_total numeric;
  v_expected_total numeric;
  v_written_total numeric:=0;
  v_work_date date;
  v_component_key text;
  v_excluded boolean;
  v_candidate_name text;
  v_candidate_ref text;
  v_candidate_mileage_pay_rate numeric;
  v_client_name text;
  v_client_mileage_charge_rate numeric;
  v_mileage_pay_rate numeric;
  v_mileage_charge_rate numeric;
begin
  if p_financial_id is null then
    raise exception using errcode='22023', message='BPAY_NEXT_ORDINARY_FINANCIAL_ID_REQUIRED';
  end if;
  if (select active_owner from private.bpay_next_module_control
        where id=1 for share)<>'NEXT' then
    raise exception using errcode='55000', message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_tf from public.timesheets_financials
    where id=p_financial_id;
  select * into strict v_ts from public.timesheets
    where timesheet_id=v_tf.timesheet_id;
  select * into strict v_contract from public.contracts
    where id=v_ts.contract_id;
  v_route:=private.bpay_next_approval_route_v1(v_ts.timesheet_id);
  if v_route not in ('ORDINARY_HOURS','EXPENSE_CARRIER')
     or v_tf.is_current is distinct from true
     or v_tf.is_stale is distinct from false
     or v_tf.authorised_at_utc is null
     or v_ts.authorised_at_server is null
     or v_tf.timesheet_version<>v_ts.version
     or v_tf.candidate_id is distinct from v_contract.candidate_id
     or v_tf.client_id is distinct from v_contract.client_id
     or upper(coalesce(v_tf.pay_method,'')) not in ('PAYE','UMBRELLA') then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_APPROVAL_NOT_CURRENT';
  end if;
  select coalesce(nullif(btrim(c.display_name),''),
                  nullif(btrim(concat_ws(' ',c.first_name,c.last_name)),''),
                  c.id::text),c.tms_ref,c.mileage_pay_rate
    into strict v_candidate_name,v_candidate_ref,v_candidate_mileage_pay_rate
    from public.candidates c where c.id=v_contract.candidate_id;
  select name,mileage_charge_rate into strict
    v_client_name,v_client_mileage_charge_rate from public.clients
    where id=v_contract.client_id;
  v_mode:=upper(coalesce(v_tf.invoice_breakdown_json->>'mode',''));
  if v_mode='SEGMENTS' then
    if jsonb_typeof(v_tf.invoice_breakdown_json->'segments')<>'array' then
      raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENTS_NOT_ARRAY';
    end if;
    v_segment_count:=jsonb_array_length(v_tf.invoice_breakdown_json->'segments');
    -- Validate identities before grouping. Physical segment IDs are retained
    -- as original evidence, not continuing financial obligations.
    for v_segment in select value from jsonb_array_elements(
      v_tf.invoice_breakdown_json->'segments')
    loop
      if jsonb_typeof(v_segment)<>'object'
         or nullif(btrim(v_segment->>'segment_id'),'') is null
         or coalesce(v_segment->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENT_ID_OR_DATE_INVALID';
      end if;
    end loop;
    select count(distinct (value->>'date')::date) into v_segment_count
      from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments');
    v_detail_kind:='SHIFT';
  elsif v_mode='AGGREGATE' then
    v_detail_kind:='AGGREGATE';
    v_base_amount:=v_tf.total_pay_ex_vat-v_tf.additional_pay_ex_vat
      -coalesce(v_tf.expenses_pay_ex_vat,0)-coalesce(v_tf.mileage_pay_ex_vat,0);
    v_base_count:=case when v_base_amount<>0 or v_tf.total_hours<>0 then 1 else 0 end;
  elsif v_mode='EXPENSES_ONLY' and v_route='EXPENSE_CARRIER' then
    v_detail_kind:='FIXED';
  else
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_FINANCIAL_MODE_UNSUPPORTED';
  end if;
  if jsonb_typeof(v_tf.additional_units_json)<>'object' then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_ADDITIONAL_NOT_OBJECT';
  end if;
  select count(*) into v_additional_count from jsonb_each(v_tf.additional_units_json);
  if v_route='EXPENSE_CARRIER' then
    if v_segment_count<>0 or v_base_count<>0 or v_additional_count<>0
       or v_tf.total_hours<>0 or v_tf.additional_pay_ex_vat<>0
       or v_tf.hours_day<>0 or v_tf.hours_night<>0
       or v_tf.hours_sat<>0 or v_tf.hours_sun<>0 or v_tf.hours_bh<>0
       or v_tf.total_pay_ex_vat is distinct from
          coalesce(v_tf.expenses_pay_ex_vat,0)+coalesce(v_tf.mileage_pay_ex_vat,0) then
      raise exception using errcode='23514', message='BPAY_NEXT_EXPENSE_CARRIER_MONEY_SHAPE_INVALID';
    end if;
    v_detail_kind:='FIXED';
  end if;
  v_expense_total:=coalesce(v_tf.travel_pay_ex_vat,0)
    +coalesce(v_tf.accommodation_pay_ex_vat,0)+coalesce(v_tf.other_pay_ex_vat,0);
  if v_expense_total<>0 then
    if coalesce(v_tf.expenses_pay_ex_vat,0) not in (0,v_expense_total) then
      raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_EXPENSE_TOTAL_CONFLICT';
    end if;
    v_expense_count:=(case when v_tf.travel_pay_ex_vat<>0 then 1 else 0 end)
      +(case when v_tf.accommodation_pay_ex_vat<>0 then 1 else 0 end)
      +(case when v_tf.other_pay_ex_vat<>0 then 1 else 0 end);
  else
    v_expense_total:=coalesce(v_tf.expenses_pay_ex_vat,0);
    v_expense_count:=case when v_expense_total<>0 then 1 else 0 end;
  end if;
  v_mileage_count:=case when v_tf.mileage_pay_ex_vat<>0
    or v_tf.mileage_units<>0 then 1 else 0 end;
  v_expected_count:=v_segment_count+v_base_count+v_additional_count
    +v_expense_count+v_mileage_count;
  -- Both production snapshot writers include additional pay, expenses and
  -- mileage in total_pay_ex_vat. They are components of this total, not extras.
  v_expected_total:=v_tf.total_pay_ex_vat;
  if v_expected_total<>round(v_expected_total,2)
     or v_tf.total_pay_ex_vat<>round(v_tf.total_pay_ex_vat,2)
     or v_tf.additional_pay_ex_vat<>round(v_tf.additional_pay_ex_vat,2)
     or v_tf.expenses_pay_ex_vat<>round(v_tf.expenses_pay_ex_vat,2)
     or v_tf.travel_pay_ex_vat<>round(v_tf.travel_pay_ex_vat,2)
     or v_tf.accommodation_pay_ex_vat<>round(v_tf.accommodation_pay_ex_vat,2)
     or v_tf.other_pay_ex_vat<>round(v_tf.other_pay_ex_vat,2)
     or v_tf.mileage_pay_ex_vat<>round(v_tf.mileage_pay_ex_vat,2) then
    raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_MONEY_PRECISION_INVALID';
  end if;
  v_mileage_pay_rate:=coalesce(v_tf.mileage_pay_rate,
                               v_contract.mileage_pay_rate,
                               v_candidate_mileage_pay_rate);
  v_mileage_charge_rate:=coalesce(v_tf.mileage_charge_rate,
                                  v_contract.mileage_charge_rate,
                                  v_client_mileage_charge_rate);
  v_resolved_daily_rates:=v_route in ('ORDINARY_HOURS','DAILY_HOURS')
    and v_ts.sheet_scope='DAILY'::public.timesheet_scope_enum;
  if v_resolved_daily_rates then
    v_available_daily_evidence:=private.bpay_next_daily_approval_evidence_v1(v_tf.id);
    select (v_available_daily_evidence->'rates')
      ||coalesce(jsonb_agg(to_jsonb(r) order by r.rate_family,r.rate_code),'[]'::jsonb)
      into v_available_daily_rows
      from private.bpay_next_contract_rate_rows_v1(
        '{}'::jsonb,v_contract.bucket_labels_json,v_contract.additional_rates_json,
        v_mileage_pay_rate,v_mileage_charge_rate) r;
    v_schedule_count:=jsonb_array_length(v_available_daily_rows);
  else
    select count(*) into v_schedule_count
      from private.bpay_next_contract_rate_rows_v1(
        v_contract.rates_json,v_contract.bucket_labels_json,v_contract.additional_rates_json,
        v_mileage_pay_rate,v_mileage_charge_rate);
  end if;

  insert into private.bpay_next_worker_control(candidate_id)
    values (v_contract.candidate_id) on conflict (candidate_id) do nothing;
  select * into v_work from private.bpay_next_work
    where booking_id=v_ts.booking_id for update;
  if not found then
    insert into private.bpay_next_work
      (candidate_id,contract_id,original_timesheet_id,booking_id,
       work_kind,week_ending_date)
      values (v_contract.candidate_id,v_contract.id,v_ts.timesheet_id,
              v_ts.booking_id,
              case when v_route='EXPENSE_CARRIER' then 'EXPENSE' else 'ORDINARY' end,
              v_ts.week_ending_date)
      returning * into v_work;
  elsif v_work.candidate_id<>v_contract.candidate_id
     or v_work.contract_id<>v_contract.id
     or v_work.week_ending_date<>v_ts.week_ending_date
     or v_work.work_kind<>(case when v_route='EXPENSE_CARRIER'
       then 'EXPENSE' else 'ORDINARY' end) then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_WORK_IDENTITY_CONFLICT';
  end if;
  insert into private.bpay_next_work_revision
    (work_id,revision_no,source_kind,physical_timesheet_id,
     financial_snapshot_id,physical_timesheet_version,
     source_pay_channel,week_ending_date,detail_kind,
     expected_line_count,expected_rate_schedule_count,certified_zero,
     approved_source_ex_vat,candidate_display_name,candidate_reference,
     client_display_name,job_title,band_label,timesheet_reference)
    values (v_work.id,v_work.current_revision_no+1,
            case when v_route='EXPENSE_CARRIER' then 'EXPENSE' else 'ORDINARY' end,
            v_ts.timesheet_id,v_tf.id,v_ts.version,upper(v_tf.pay_method),
            v_ts.week_ending_date,v_detail_kind,v_expected_count,
            v_schedule_count,v_expected_total=0,v_expected_total,
            v_candidate_name,v_candidate_ref,v_client_name,
            v_contract.role,v_contract.band,v_ts.reference_number)
    returning id into v_revision_id;
  if v_resolved_daily_rates then
    insert into private.bpay_next_rate_schedule
      (revision_id,rate_family,rate_code,unit_label,paye_rate,umbrella_rate,charge_rate)
      select v_revision_id,r.rate_family,r.rate_code,r.unit_label,r.paye_rate,r.umbrella_rate,r.charge_rate
      from jsonb_to_recordset(v_available_daily_rows)
        r(rate_family text,rate_code text,unit_label text,paye_rate numeric,umbrella_rate numeric,charge_rate numeric);
  else
    insert into private.bpay_next_rate_schedule
      (revision_id,rate_family,rate_code,unit_label,paye_rate,umbrella_rate,charge_rate)
      select v_revision_id,r.rate_family,r.rate_code,r.unit_label,r.paye_rate,r.umbrella_rate,r.charge_rate
      from private.bpay_next_contract_rate_rows_v1(
        v_contract.rates_json,v_contract.bucket_labels_json,v_contract.additional_rates_json,
        v_mileage_pay_rate,v_mileage_charge_rate) r;
  end if;

  if v_mode='SEGMENTS' then
    -- One pass ordered by stable business date and original array ordinal.
    -- Window sums use exact stored amounts, not a new hours/rates calculator.
    -- Child INSERTs retain every original shift, including zero/excluded ones.
    for v_segment_row in
      select value,ordinality,
        row_number() over day_order as detail_no,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
            then 0 else (value->>'pay_amount')::numeric end) over day_set as day_pay,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_day')::numeric,0)
          +coalesce((value->>'hours_night')::numeric,0)
          +coalesce((value->>'hours_sat')::numeric,0)
          +coalesce((value->>'hours_sun')::numeric,0)
          +coalesce((value->>'hours_bh')::numeric,0) end) over day_set as day_hours,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_day')::numeric,0) end) over day_set as day_day,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_night')::numeric,0) end) over day_set as day_night,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_sat')::numeric,0) end) over day_set as day_sat,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_sun')::numeric,0) end) over day_set as day_sun,
        sum(case when coalesce((value->>'exclude_from_pay')::boolean,false)
          then 0 else coalesce((value->>'hours_bh')::numeric,0) end) over day_set as day_bh
      from jsonb_array_elements(v_tf.invoice_breakdown_json->'segments') with ordinality
      window day_set as (partition by (value->>'date')::date),
        day_order as (partition by (value->>'date')::date order by ordinality)
      order by (value->>'date')::date,ordinality
    loop
      v_segment:=v_segment_row.value;
      if jsonb_typeof(v_segment)<>'object'
         or nullif(btrim(v_segment->>'segment_id'),'') is null
         or coalesce(v_segment->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENT_ID_OR_DATE_INVALID';
      end if;
      v_work_date:=(v_segment->>'date')::date;
      -- TS_DAY is the supported payment choice. A new physical UUID, edited
      -- clock/break or array order cannot create another DAY obligation.
      -- Per-segment authorisation exclusions remain independent below.
      v_component_key:='WORK:DAY:'||v_work_date::text;
      v_excluded:=coalesce((v_segment->>'exclude_from_pay')::boolean,false);
      v_amount:=case when v_excluded then 0
        else (v_segment->>'pay_amount')::numeric end;
      if v_amount is null or v_amount<>round(v_amount,2) then
        raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_SEGMENT_AMOUNT_INVALID';
      end if;
      v_hours:=0; v_rate_detail_count:=0;
      for v_bucket in select * from (values
        ('DAY'::text,'hours_day'::text,v_tf.pay_day),
        ('NIGHT','hours_night',v_tf.pay_night),
        ('SAT','hours_sat',v_tf.pay_sat),
        ('SUN','hours_sun',v_tf.pay_sun),
        ('BH','hours_bh',v_tf.pay_bh)) b(code,hours_key,pay_rate)
      loop
        if coalesce((v_segment->>v_bucket.hours_key)::numeric,0)<0
           or coalesce((v_segment->>v_bucket.hours_key)::numeric,0)
                <>round(coalesce((v_segment->>v_bucket.hours_key)::numeric,0),6) then
          raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_SEGMENT_HOURS_INVALID';
        end if;
        v_hours:=v_hours+coalesce((v_segment->>v_bucket.hours_key)::numeric,0);
        if not v_excluded and coalesce((v_segment->>v_bucket.hours_key)::numeric,0)>0 then
          if v_bucket.pay_rate is null
             or v_bucket.pay_rate<>round(v_bucket.pay_rate,6)
             or abs(v_bucket.pay_rate)>=1000000000000 then
            raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_USED_RATE_MISSING';
          end if;
          v_rate_detail_count:=v_rate_detail_count+1;
        end if;
      end loop;
      if v_segment_row.detail_no=1 then
        v_rate_detail_count:=(case when v_segment_row.day_day>0 then 1 else 0 end)
          +(case when v_segment_row.day_night>0 then 1 else 0 end)
          +(case when v_segment_row.day_sat>0 then 1 else 0 end)
          +(case when v_segment_row.day_sun>0 then 1 else 0 end)
          +(case when v_segment_row.day_bh>0 then 1 else 0 end);
        v_line_no:=v_line_no+1;
        insert into private.bpay_next_approved_line
          (revision_id,line_no,component_key,component_kind,work_date,
           approved_quantity,expected_rate_detail_count,source_pay_ex_vat,tax_treatment,evidence_ref)
          values (v_revision_id,v_line_no,v_component_key,'WORK',v_work_date,
            v_segment_row.day_hours,v_rate_detail_count,v_segment_row.day_pay,'TAXABLE',
            'timesheets_financials:'||v_tf.id::text||'#day:'||v_work_date::text)
          returning id into v_line_id;
        insert into private.bpay_next_rate_detail
          (approved_line_id,bucket,approved_hours,source_pay_rate)
          select v_line_id,b.code,b.hours,b.pay_rate from (values
            ('DAY'::text,v_segment_row.day_day,v_tf.pay_day),
            ('NIGHT',v_segment_row.day_night,v_tf.pay_night),
            ('SAT',v_segment_row.day_sat,v_tf.pay_sat),
            ('SUN',v_segment_row.day_sun,v_tf.pay_sun),
            ('BH',v_segment_row.day_bh,v_tf.pay_bh)) b(code,hours,pay_rate)
          where b.hours>0;
      end if;
      v_shift_start_local:=nullif(btrim(coalesce(v_segment->>'start_local',v_segment->>'start','')),'');
      v_shift_end_local:=nullif(btrim(coalesce(v_segment->>'end_local',v_segment->>'end','')),'');
      if (v_shift_start_local is null)<>(v_shift_end_local is null)
         or (v_shift_start_local is not null and
           (v_shift_start_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
            or v_shift_end_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')) then
        raise exception using errcode='23514',message='BPAY_NEXT_ORDINARY_SCHEDULE_CLOCK_INVALID';
      end if;
      insert into private.bpay_next_shift_detail
        (approved_line_id,detail_no,work_date,shift_start_at,shift_end_at,
         shift_start_local,shift_end_local,shift_overnight,
         approved_minutes,approved_hours,immutable_evidence_ref,
         segment_pay_ex_vat,pay_excluded,hours_day,hours_night,hours_sat,hours_sun,hours_bh)
        values (v_line_id,v_segment_row.detail_no::integer,v_work_date,
          nullif(v_segment->>'start_utc','')::timestamptz,
          nullif(v_segment->>'end_utc','')::timestamptz,
          v_shift_start_local,v_shift_end_local,
          nullif(v_segment->>'overnight','')::boolean,
          case when v_hours*60=trunc(v_hours*60) then (v_hours*60)::integer end,
          v_hours,'timesheets_financials:'||v_tf.id::text||'#segment:'||v_segment_row.ordinality::text,
          v_amount,v_excluded,
          coalesce((v_segment->>'hours_day')::numeric,0),
          coalesce((v_segment->>'hours_night')::numeric,0),
          coalesce((v_segment->>'hours_sat')::numeric,0),
          coalesce((v_segment->>'hours_sun')::numeric,0),
          coalesce((v_segment->>'hours_bh')::numeric,0)) returning id into v_shift_id;
      v_break_total:=0; v_break_no:=0;
      if v_segment ? 'breaks' and jsonb_typeof(v_segment->'breaks')<>'array' then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_SHAPE_INVALID';
      end if;
      for v_break in select value from jsonb_array_elements(
        coalesce(v_segment->'breaks','[]'::jsonb))
      loop
        v_break_start:=v_break->>'start';
        v_break_end:=v_break->>'end';
        if jsonb_typeof(v_break)<>'object'
           or coalesce(v_break_start,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or coalesce(v_break_end,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
          raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_CLOCK_INVALID';
        end if;
        v_begin_mins:=substring(v_break_start,1,2)::integer*60
          +substring(v_break_start,4,2)::integer;
        v_end_mins:=substring(v_break_end,1,2)::integer*60
          +substring(v_break_end,4,2)::integer;
        v_break_mins:=(v_end_mins-v_begin_mins+1440)%1440;
        if v_break_mins=0 then
          raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_ZERO_WINDOW';
        end if;
        v_break_no:=v_break_no+1;
        v_break_total:=v_break_total+v_break_mins;
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_start_local,break_end_local,break_minutes)
          values (v_shift_id,v_break_no,v_break_start,v_break_end,v_break_mins);
      end loop;
      if v_break_no=0 and coalesce((v_segment->>'break_mins')::integer,
                                   (v_segment->>'break_minutes')::integer,0)>0 then
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_minutes)
          values (v_shift_id,1,coalesce((v_segment->>'break_mins')::integer,
                                        (v_segment->>'break_minutes')::integer));
      elsif v_break_no>0 and (v_segment ? 'break_mins' or v_segment ? 'break_minutes')
         and v_break_total<>coalesce((v_segment->>'break_mins')::integer,
                                    (v_segment->>'break_minutes')::integer) then
        raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_BREAK_DURATION_CONFLICT';
      end if;
      v_written_total:=v_written_total+v_amount;
    end loop;
  elsif v_base_count=1 then
    for v_bucket in select * from (values
      (v_tf.hours_day,v_tf.pay_day),(v_tf.hours_night,v_tf.pay_night),
      (v_tf.hours_sat,v_tf.pay_sat),(v_tf.hours_sun,v_tf.pay_sun),
      (v_tf.hours_bh,v_tf.pay_bh)) b(hours,pay_rate)
    loop
      if v_bucket.hours<0 or v_bucket.hours<>round(v_bucket.hours,6)
         or (v_bucket.hours>0 and
             (v_bucket.pay_rate is null
              or v_bucket.pay_rate<>round(v_bucket.pay_rate,6)
              or abs(v_bucket.pay_rate)>=1000000000000)) then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_AGGREGATE_RATE_INVALID';
      end if;
    end loop;
    v_rate_detail_count:=
      (case when v_tf.hours_day>0 then 1 else 0 end)
      +(case when v_tf.hours_night>0 then 1 else 0 end)
      +(case when v_tf.hours_sat>0 then 1 else 0 end)
      +(case when v_tf.hours_sun>0 then 1 else 0 end)
      +(case when v_tf.hours_bh>0 then 1 else 0 end);
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,component_kind,approved_quantity,
       expected_rate_detail_count,source_pay_ex_vat,tax_treatment,evidence_ref)
      values (v_revision_id,v_line_no,'WORK:AGGREGATE','WORK',v_tf.total_hours,
              v_rate_detail_count,v_base_amount,'TAXABLE',
              'timesheets_financials:'||v_tf.id::text||'#aggregate')
      returning id into v_line_id;
    insert into private.bpay_next_rate_detail
      (approved_line_id,bucket,approved_hours,source_pay_rate)
      select v_line_id,b.code,b.hours,b.pay_rate
      from (values ('DAY'::text,v_tf.hours_day,v_tf.pay_day),
                   ('NIGHT',v_tf.hours_night,v_tf.pay_night),
                   ('SAT',v_tf.hours_sat,v_tf.pay_sat),
                   ('SUN',v_tf.hours_sun,v_tf.pay_sun),
                   ('BH',v_tf.hours_bh,v_tf.pay_bh)) b(code,hours,pay_rate)
      where b.hours>0;
    -- An AGGREGATE money line can still originate from an entered weekly
    -- schedule. Keep the entered date/clock/break evidence as small typed
    -- children, without inventing a money split across those shifts.
    if v_tf.actual_schedule_json is not null
       and jsonb_typeof(v_tf.actual_schedule_json)<>'array' then
      raise exception using errcode='23514',
        message='BPAY_NEXT_ORDINARY_SCHEDULE_SHAPE_INVALID';
    end if;
    v_schedule:=case
      when jsonb_typeof(v_tf.actual_schedule_json)='array'
       and jsonb_array_length(v_tf.actual_schedule_json)>0
        then v_tf.actual_schedule_json
      else v_ts.actual_schedule_json end;
    if v_schedule is not null and jsonb_typeof(v_schedule)<>'array' then
      raise exception using errcode='23514',
        message='BPAY_NEXT_ORDINARY_SCHEDULE_SHAPE_INVALID';
    end if;
    v_shift_no:=0;
    for v_shift_entry in select value from jsonb_array_elements(
      coalesce(v_schedule,'[]'::jsonb))
    loop
      if jsonb_typeof(v_shift_entry)<>'object'
         or coalesce(v_shift_entry->>'date',v_shift_entry->>'work_date','')
              !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_SCHEDULE_DATE_INVALID';
      end if;
      v_shift_start_local:=nullif(btrim(coalesce(v_shift_entry->>'start','')),'');
      v_shift_end_local:=nullif(btrim(coalesce(v_shift_entry->>'end','')),'');
      if (v_shift_start_local is null)<>(v_shift_end_local is null)
         or (v_shift_start_local is not null and
             (v_shift_start_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
              or v_shift_end_local !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')) then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_SCHEDULE_CLOCK_INVALID';
      end if;
      v_shift_no:=v_shift_no+1;
      insert into private.bpay_next_shift_detail
        (approved_line_id,detail_no,work_date,shift_start_at,shift_end_at,
         shift_start_local,shift_end_local,approved_minutes,approved_hours)
        values (v_line_id,v_shift_no,
          coalesce(v_shift_entry->>'date',v_shift_entry->>'work_date')::date,
          nullif(v_shift_entry->>'start_utc','')::timestamptz,
          nullif(v_shift_entry->>'end_utc','')::timestamptz,
          v_shift_start_local,v_shift_end_local,
          nullif(v_shift_entry->>'worked_minutes','')::integer,
          nullif(v_shift_entry->>'approved_hours','')::numeric)
        returning id into v_shift_id;
      if v_shift_entry ? 'breaks'
         and jsonb_typeof(v_shift_entry->'breaks') not in ('array','null') then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_BREAK_SHAPE_INVALID';
      end if;
      v_break_no:=0; v_break_total:=0;
      for v_break in select value from jsonb_array_elements(
        case when jsonb_typeof(v_shift_entry->'breaks')='array'
          then v_shift_entry->'breaks' else '[]'::jsonb end)
      loop
        v_break_start:=v_break->>'start';
        v_break_end:=v_break->>'end';
        if jsonb_typeof(v_break)<>'object'
           or coalesce(v_break_start,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or coalesce(v_break_end,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
          raise exception using errcode='23514',
            message='BPAY_NEXT_ORDINARY_BREAK_CLOCK_INVALID';
        end if;
        v_begin_mins:=substring(v_break_start,1,2)::integer*60
          +substring(v_break_start,4,2)::integer;
        v_end_mins:=substring(v_break_end,1,2)::integer*60
          +substring(v_break_end,4,2)::integer;
        v_break_mins:=(v_end_mins-v_begin_mins+1440)%1440;
        if v_break_mins=0 then
          raise exception using errcode='23514',
            message='BPAY_NEXT_ORDINARY_BREAK_ZERO_WINDOW';
        end if;
        v_break_no:=v_break_no+1;
        v_break_total:=v_break_total+v_break_mins;
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_start_local,break_end_local,break_minutes)
          values (v_shift_id,v_break_no,v_break_start,v_break_end,v_break_mins);
      end loop;
      if v_break_no=0
         and coalesce((v_shift_entry->>'break_minutes')::integer,
                      (v_shift_entry->>'break_mins')::integer,0)>0 then
        insert into private.bpay_next_break_detail
          (shift_detail_id,break_no,break_minutes)
          values (v_shift_id,1,
            coalesce((v_shift_entry->>'break_minutes')::integer,
                     (v_shift_entry->>'break_mins')::integer));
      elsif v_break_no>0
         and (v_shift_entry ? 'break_minutes' or v_shift_entry ? 'break_mins')
         and v_break_total<>coalesce((v_shift_entry->>'break_minutes')::integer,
                                    (v_shift_entry->>'break_mins')::integer) then
        raise exception using errcode='23514',
          message='BPAY_NEXT_ORDINARY_BREAK_DURATION_CONFLICT';
      end if;
    end loop;
    v_written_total:=v_written_total+v_base_amount;
  end if;

  for v_extra in select key,value from jsonb_each(v_tf.additional_units_json)
                 order by key
  loop
    if jsonb_typeof(v_extra.value)<>'object'
       or nullif(btrim(v_extra.key),'') is null
       or length('ADDITIONAL:'||upper(btrim(v_extra.key)))>256 then
      raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_ADDITIONAL_SHAPE_INVALID';
    end if;
    v_amount:=coalesce((v_extra.value->>'pay_ex_vat')::numeric,
      (v_extra.value->>'amount_ex_vat')::numeric,
      coalesce((v_extra.value->>'unit_count')::numeric,
               (v_extra.value->>'units_week')::numeric,0)
       *coalesce((v_extra.value->>'pay_rate')::numeric,
                 (v_extra.value->>'rate')::numeric,0));
    if v_amount<>round(v_amount,2) then
      raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_ADDITIONAL_PRECISION_INVALID';
    end if;
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,component_kind,unit_label,
       approved_quantity,approved_unit_rate,source_pay_ex_vat,evidence_ref)
      values (v_revision_id,v_line_no,'ADDITIONAL:'||upper(btrim(v_extra.key)),
        'ADDITIONAL',nullif(v_extra.value->>'unit_name',''),
        coalesce((v_extra.value->>'unit_count')::numeric,
                 (v_extra.value->>'units_week')::numeric),
        coalesce((v_extra.value->>'pay_rate')::numeric,
                 (v_extra.value->>'rate')::numeric),v_amount,
        'timesheets_financials:'||v_tf.id::text||'#additional:'||v_extra.key);
    v_written_total:=v_written_total+v_amount;
  end loop;
  if v_written_total <> v_tf.total_pay_ex_vat-v_expense_total
      -v_tf.mileage_pay_ex_vat then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_WORK_TOTAL_MISMATCH';
  end if;

  for v_extra in select * from (values
      ('TRAVEL'::text,v_tf.travel_pay_ex_vat),
      ('ACCOMMODATION',v_tf.accommodation_pay_ex_vat),
      ('OTHER',v_tf.other_pay_ex_vat),
      ('EXPENSES',case when v_expense_count=1
        and v_tf.travel_pay_ex_vat=0 and v_tf.accommodation_pay_ex_vat=0
        and v_tf.other_pay_ex_vat=0 then v_expense_total else 0 end)) x(code,amount)
  loop
    if v_extra.amount<>0 then
      if v_extra.amount<>round(v_extra.amount,2) then
        raise exception using errcode='22003', message='BPAY_NEXT_ORDINARY_EXPENSE_PRECISION_INVALID';
      end if;
      v_line_no:=v_line_no+1;
      insert into private.bpay_next_approved_line
        (revision_id,line_no,component_key,component_kind,
         source_pay_ex_vat,evidence_ref)
        values (v_revision_id,v_line_no,'EXPENSE:'||v_extra.code,'EXPENSE',
          v_extra.amount,'timesheets_financials:'||v_tf.id::text||'#expense:'||v_extra.code);
      v_written_total:=v_written_total+v_extra.amount;
    end if;
  end loop;
  if v_mileage_count=1 then
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,component_kind,unit_label,
       approved_quantity,approved_unit_rate,source_pay_ex_vat,evidence_ref)
      values (v_revision_id,v_line_no,'MILEAGE:MILE','MILEAGE','mile',
        v_tf.mileage_units,v_mileage_pay_rate,v_tf.mileage_pay_ex_vat,
        'timesheets_financials:'||v_tf.id::text||'#mileage');
    v_written_total:=v_written_total+v_tf.mileage_pay_ex_vat;
  end if;
  if v_line_no<>v_expected_count or v_written_total<>v_expected_total then
    raise exception using errcode='23514', message='BPAY_NEXT_ORDINARY_COMPONENT_TOTAL_MISMATCH';
  end if;
  perform private.bpay_next_publish_staged_revision_v1(
    v_work.id,v_revision_id,v_command_id);
  return v_revision_id;
end
$function$;

create or replace function private.bpay_next_ordinary_authorisation_trigger_v1()
returns trigger
language plpgsql security definer
set search_path = pg_catalog, public, private
as $function$
declare
  v_new_authorisation boolean;
  v_removed_authorisation boolean;
  v_route text;
  v_booking_id text;
  v_contract_id uuid;
  v_candidate_id uuid;
  v_work private.bpay_next_work%rowtype;
  v_physical_timesheet_id uuid;
begin
  if tg_op='INSERT' then
    v_new_authorisation:=new.authorised_at_utc is not null;
    v_removed_authorisation:=false;
  else
    v_new_authorisation:=old.authorised_at_utc is null
      and new.authorised_at_utc is not null;
    v_removed_authorisation:=old.authorised_at_utc is not null
      and new.authorised_at_utc is null;
  end if;
  if not (v_new_authorisation or v_removed_authorisation)
     or (select active_owner from private.bpay_next_module_control
          where id=1)<>'NEXT' then
    return new;
  end if;
  if v_new_authorisation then
    v_route:=private.bpay_next_approval_route_v1(new.timesheet_id);
    if v_route in ('ORDINARY_HOURS','EXPENSE_CARRIER') then
      perform private.bpay_next_publish_ordinary_from_financial_v1(new.id);
    end if;
  else
    -- Unauthorisation changes what may be offered next; it does not erase a
    -- revision already captured into a frozen offer or rewrite paid history.
    select t.booking_id,t.contract_id,c.candidate_id
      into strict v_booking_id,v_contract_id,v_candidate_id
      from public.timesheets t
      join public.contracts c on c.id=t.contract_id
      where t.timesheet_id=new.timesheet_id;
    insert into private.bpay_next_worker_control(candidate_id)
      values (v_candidate_id) on conflict(candidate_id) do nothing;
    perform 1 from private.bpay_next_worker_control
      where candidate_id=v_candidate_id for update;
    select * into v_work from private.bpay_next_work
      where booking_id=v_booking_id for update;
    -- The installed unauthorisation owner stamps revoked_at BEFORE clearing
    -- the financial row. Its approval route rightly rejects revoked rows;
    -- use the already-published exact work identity for this transition.
    if not found or v_work.work_kind='SOURCE' then
      return new;
    end if;
    select r.physical_timesheet_id into strict v_physical_timesheet_id
      from private.bpay_next_work_revision r
      where r.id=v_work.current_revision_id and r.work_id=v_work.id;
    if v_work.candidate_id<>v_candidate_id
       or v_work.contract_id<>v_contract_id
       or v_work.work_kind not in ('EXPENSE','ORDINARY')
       or v_work.approval_state<>'APPROVED'
       or v_physical_timesheet_id<>new.timesheet_id then
      raise exception using errcode='23514',
        message='BPAY_NEXT_ORDINARY_UNAUTHORISE_WORK_MISMATCH';
    end if;
    update private.bpay_next_work
      set approval_state='WITHDRAWN',current_revision_id=null,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where id=v_work.id;
    update private.bpay_next_worker_control
      set financial_view_revision=financial_view_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where candidate_id=v_candidate_id;
  end if;
  return new;
end
$function$;

drop trigger if exists bpay_next_ordinary_authorisation_v1
  on public.timesheets_financials;
create trigger bpay_next_ordinary_authorisation_v1
  after insert or update of authorised_at_utc on public.timesheets_financials
  for each row execute function private.bpay_next_ordinary_authorisation_trigger_v1();

alter function private.bpay_next_publish_ordinary_from_financial_v1(uuid)
  OWNER TO CURRENT_USER;
alter function private.bpay_next_ordinary_authorisation_trigger_v1()
  OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_publish_ordinary_from_financial_v1(uuid)
  from public, anon, authenticated, service_role;
revoke all on function private.bpay_next_ordinary_authorisation_trigger_v1()
  from public, anon, authenticated, service_role;



-- Bind only the Source detail actually chosen by the Office decision. This
-- runs before immediate/deferred publication, when the exact segment and
-- immutable provenance IDs are still available. No current-row recovery.



create or replace function private.bpay_next_capture_chosen_source_detail_v1(
  p_head_id uuid,p_bundle_id uuid,p_bundle_revision bigint,
  p_components jsonb,p_segments jsonb,p_copy_head_id uuid default null
) returns integer
language plpgsql security definer
set search_path = pg_catalog, private, public
as $function$
declare
  v_component jsonb;
  v_canonical jsonb;
  v_component_sha bytea;
  v_component_id uuid;
  v_segment jsonb;
  v_match_count integer;
  v_detail jsonb;
  v_detail_sha bytea;
  v_existing record;
  v_count integer:=0;
  v_key text;
  v_start_utc timestamptz;
  v_end_utc timestamptz;
begin
  if p_head_id is null or p_bundle_id is null or p_bundle_revision is null
     or pg_catalog.jsonb_typeof(p_components)<>'array'
     or (p_copy_head_id is null and pg_catalog.jsonb_typeof(p_segments)<>'array')
     or (p_copy_head_id is not null and p_segments is not null) then
    raise exception using errcode='22023',
      message='BPAY_NEXT_SOURCE_DETAIL_INPUT_INVALID';
  end if;
  if not exists (
    select 1 from public.weekly_source_entitlement_decision_bundles b
    where b.decision_bundle_id=p_bundle_id
      and b.bundle_revision=p_bundle_revision
      and p_head_id=any(b.proposed_head_ids)
  ) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SOURCE_DETAIL_DECISION_MISMATCH';
  end if;
  for v_component in select value from pg_catalog.jsonb_array_elements(p_components)
  loop
    if v_component->>'component_kind'<>'WORKED_TIME' then
      continue;
    end if;
    v_canonical:=private.weekly_source_publication_component_canonical_v1(
      v_component,'bpay_next_chosen_detail.component');
    v_component_id:=(v_canonical->>'component_id')::uuid;
    v_component_sha:=private.weekly_source_publication_request_digest_v1(
      private.weekly_source_publication_component_content_v1(v_canonical));
    if p_copy_head_id is not null then
      select d.detail_json,d.component_sha256
        into v_detail,v_detail_sha
        from private.bpay_next_source_chosen_detail d
        where d.head_id=p_copy_head_id and d.component_id=v_component_id;
      if not found or v_detail_sha<>v_component_sha then
        raise exception using errcode='23514',
          message='BPAY_NEXT_SOURCE_DETAIL_COPY_NOT_EXACT';
      end if;
    else
      select pg_catalog.count(*)::integer,pg_catalog.jsonb_agg(s.value)->0
        into v_match_count,v_segment
        from pg_catalog.jsonb_array_elements(p_segments) s(value)
        where s.value->>'segment_id'=v_canonical->>'segment_id';
      if v_match_count<>1
         or v_segment->>'date' is distinct from v_canonical->>'work_date'
         or (v_segment->>'pay_amount')::numeric
              is distinct from (v_canonical->>'pay_ex_vat')::numeric
         or (v_segment->>'exclude_from_pay')::boolean
              is distinct from (v_canonical->>'exclude_from_pay')::boolean then
        raise exception using errcode='23514',
          message='BPAY_NEXT_SOURCE_DETAIL_SEGMENT_NOT_EXACT';
      end if;
      foreach v_key in array array['hours_day','hours_night','hours_sat','hours_sun','hours_bh']
      loop
        if coalesce((v_segment->>v_key)::numeric,0)
             is distinct from coalesce((v_canonical->>v_key)::numeric,0) then
          raise exception using errcode='23514',
            message='BPAY_NEXT_SOURCE_DETAIL_BUCKET_NOT_EXACT';
        end if;
      end loop;
      if coalesce(v_segment->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
         or coalesce(v_segment->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
         or (v_segment->>'overnight')::boolean is null
         or (v_segment->>'break_mins')::integer is null
         or (v_segment->>'break_mins')::integer<0
         or pg_catalog.jsonb_typeof(v_segment->'weekly_source')<>'object'
         or nullif(v_segment#>>'{weekly_source,work_event_id}','') is null
         or v_segment#>>'{weekly_source,work_event_id}'
              is distinct from v_canonical->>'component_member_identity'
         or v_segment#>>'{weekly_source,calculation_fingerprint}'
              is distinct from v_canonical->>'segment_stable_key'
         or nullif(v_segment#>>'{weekly_source,row_resolution_id}','') is null
         or nullif(v_segment#>>'{weekly_source,economic_snapshot_id}','') is null
         or nullif(v_segment#>>'{weekly_source,movement_id}','') is null
         or nullif(v_segment#>>'{weekly_source,final_revision_id}','') is null
         or pg_catalog.jsonb_typeof(v_segment#>'{weekly_source,pay_vector,rates}')<>'object' then
        raise exception using errcode='23514',
          message='BPAY_NEXT_SOURCE_DETAIL_PROVENANCE_INCOMPLETE';
      end if;
      foreach v_key in array array['day','night','sat','sun','bh']
      loop
        if coalesce((v_canonical->>('hours_'||v_key))::numeric,0)<>0
           and ((v_segment#>>array['weekly_source','pay_vector','rates',v_key])::numeric is null
             or (v_segment#>>array['weekly_source','pay_vector','rates',v_key])::numeric
                 <>pg_catalog.round(
                   (v_segment#>>array['weekly_source','pay_vector','rates',v_key])::numeric,6)) then
          raise exception using errcode='23514',
            message='BPAY_NEXT_SOURCE_DETAIL_USED_RATE_MISSING';
        end if;
      end loop;
      v_detail:=pg_catalog.jsonb_build_object(
        'work_date',v_segment->>'date',
        'start',v_segment->>'start',
        'end',v_segment->>'end',
        'overnight',(v_segment->>'overnight')::boolean,
        'break_minutes',(v_segment->>'break_mins')::integer,
        'work_event_id',(v_segment#>>'{weekly_source,work_event_id}')::uuid,
        'movement_id',(v_segment#>>'{weekly_source,movement_id}')::uuid,
        'final_revision_id',(v_segment#>>'{weekly_source,final_revision_id}')::uuid,
        'row_resolution_id',(v_segment#>>'{weekly_source,row_resolution_id}')::uuid,
        'economic_snapshot_id',(v_segment#>>'{weekly_source,economic_snapshot_id}')::uuid,
        'rates',pg_catalog.jsonb_build_object(
          'day',(v_segment#>>'{weekly_source,pay_vector,rates,day}')::numeric,
          'night',(v_segment#>>'{weekly_source,pay_vector,rates,night}')::numeric,
          'sat',(v_segment#>>'{weekly_source,pay_vector,rates,sat}')::numeric,
          'sun',(v_segment#>>'{weekly_source,pay_vector,rates,sun}')::numeric,
          'bh',(v_segment#>>'{weekly_source,pay_vector,rates,bh}')::numeric));
      -- Retain only already supplied instants from this exact chosen segment.
      -- Missing UTC keeps the old detail shape/hash; no local-clock guess or
      -- current-source lookup enriches a copied or previously captured HEAD.
      if (v_segment->'start_utc' is not null and v_segment->'start_utc'<>'null'::jsonb)
         or (v_segment->'end_utc' is not null and v_segment->'end_utc'<>'null'::jsonb) then
        if pg_catalog.jsonb_typeof(v_segment->'start_utc') is distinct from 'string'
           or pg_catalog.jsonb_typeof(v_segment->'end_utc') is distinct from 'string'
           or coalesce(v_segment->>'start_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
           or coalesce(v_segment->>'end_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_DETAIL_UTC_INVALID';
        end if;
        begin
          v_start_utc:=(v_segment->>'start_utc')::timestamptz;
          v_end_utc:=(v_segment->>'end_utc')::timestamptz;
        exception when invalid_datetime_format or datetime_field_overflow
          or invalid_time_zone_displacement_value then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_DETAIL_UTC_INVALID';
        end;
        if not pg_catalog.isfinite(v_start_utc) or not pg_catalog.isfinite(v_end_utc)
           or v_end_utc<=v_start_utc
           or pg_catalog.to_char(v_start_utc at time zone 'Europe/London','YYYY-MM-DD')<>v_segment->>'date'
           or pg_catalog.to_char(v_start_utc at time zone 'Europe/London','HH24:MI')<>v_segment->>'start'
           or pg_catalog.to_char(v_end_utc at time zone 'Europe/London','HH24:MI')<>v_segment->>'end'
           or (v_end_utc at time zone 'Europe/London')::date<>
             (v_segment->>'date')::date+(case when (v_segment->>'overnight')::boolean then 1 else 0 end) then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_DETAIL_UTC_INVALID';
        end if;
        v_detail:=v_detail||pg_catalog.jsonb_build_object(
          'start_utc',v_segment->'start_utc','end_utc',v_segment->'end_utc');
      end if;
    end if;
    v_detail_sha:=pg_catalog.sha256(pg_catalog.convert_to(v_detail::text,'UTF8'));
    insert into private.bpay_next_source_chosen_detail
      (head_id,component_id,decision_bundle_id,bundle_revision,
       component_sha256,detail_json,detail_sha256)
    values(p_head_id,v_component_id,p_bundle_id,p_bundle_revision,
           v_component_sha,v_detail,v_detail_sha)
    on conflict (head_id,component_id) do nothing;
    select d.decision_bundle_id,d.bundle_revision,d.component_sha256,
           d.detail_json,d.detail_sha256 into strict v_existing
      from private.bpay_next_source_chosen_detail d
      where d.head_id=p_head_id and d.component_id=v_component_id;
    if v_existing.decision_bundle_id<>p_bundle_id
       or v_existing.bundle_revision<>p_bundle_revision
       or v_existing.component_sha256<>v_component_sha
       or v_existing.detail_sha256<>v_detail_sha
       or v_existing.detail_json<>v_detail then
      raise exception using errcode='23514',
        message='BPAY_NEXT_SOURCE_DETAIL_REPLAY_CONFLICT';
    end if;
    v_count:=v_count+1;
  end loop;
  return v_count;
end
$function$;

alter function private.bpay_next_capture_chosen_source_detail_v1(
  uuid,uuid,bigint,jsonb,jsonb,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_capture_chosen_source_detail_v1(
  uuid,uuid,bigint,jsonb,jsonb,uuid)
  from public,anon,authenticated,service_role;
-- The sole two-root publisher calls this after both genuine STAGED inventories
-- exist, but before I6, activation or I1. The arrays retain semantic A/B order;
-- lock ordering must never turn the target into the source. No financial write,
-- intermediate B approval, current-WORK selector or historical repair occurs.
create or replace function private.bpay_next_capture_source_pair_before_detail_v1(
  p_decision_bundle_id uuid,p_bundle_revision bigint,
  p_before_source_event_ids uuid[],p_before_financial_snapshot_ids uuid[]
) returns integer
language plpgsql security definer
set search_path = pg_catalog, private, public
as $function$
declare
  v_bundle public.weekly_source_entitlement_decision_bundles%rowtype;
  v_root public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_auth public.weekly_source_root_authorisations%rowtype;
  v_head public.weekly_source_entitlement_heads%rowtype;
  v_before_head public.weekly_source_entitlement_heads%rowtype;
  v_tf public.timesheets_financials%rowtype;
  v_revision private.bpay_next_work_revision%rowtype;
  v_work private.bpay_next_work%rowtype;
  v_line private.bpay_next_approved_line%rowtype;
  v_shift private.bpay_next_shift_detail%rowtype;
  v_existing private.bpay_next_source_chosen_detail%rowtype;
  v_roots uuid[];
  v_bookings text[];
  v_contracts uuid[];
  v_before_heads uuid[]:=array[null,null]::uuid[];
  v_before_revisions uuid[]:=array[null,null]::uuid[];
  v_tf_components jsonb[]:=array[null,null]::jsonb[];
  v_i integer;
  v_origin integer;
  v_role integer;
  v_count integer:=0;
  v_seen integer;
  v_matches integer;
  v_before_count integer;
  v_expected_rates integer;
  v_actual_rates integer;
  v_hours numeric;
  v_bucket record;
  v_row record;
  v_component public.weekly_source_entitlement_head_components%rowtype;
  v_before_component public.weekly_source_entitlement_head_components%rowtype;
  v_canonical jsonb;
  v_before_canonical jsonb;
  v_component_sha bytea;
  v_composed jsonb;
  v_segment jsonb;
  v_rates jsonb;
  v_rate numeric;
  v_stored_hours numeric;
  v_detail jsonb;
  v_detail_sha bytea;
  v_break jsonb;
  v_breaks jsonb;
  v_break_total integer;
  v_break_no integer;
  v_break_minutes integer;
  v_all_clocked boolean;
  v_start text;
  v_end text;
  v_start_utc timestamptz;
  v_end_utc timestamptz;
  v_blank jsonb;
  v_reprice_detail jsonb;
begin
  if p_decision_bundle_id is null or p_bundle_revision is null or p_bundle_revision<1
     or p_before_source_event_ids is null or p_before_financial_snapshot_ids is null
     or pg_catalog.array_ndims(p_before_source_event_ids) is distinct from 1
     or pg_catalog.array_ndims(p_before_financial_snapshot_ids) is distinct from 1
     or pg_catalog.array_lower(p_before_source_event_ids,1) is distinct from 1
     or pg_catalog.array_lower(p_before_financial_snapshot_ids,1) is distinct from 1
     or pg_catalog.cardinality(p_before_source_event_ids)<>2
     or pg_catalog.cardinality(p_before_financial_snapshot_ids)<>2
     or p_before_source_event_ids[1] is null then
    raise exception using errcode='22023',message='BPAY_NEXT_PAIR_DETAIL_INPUT_INVALID';
  end if;
  perform 1 from private.bpay_next_module_control
    where id=1 and active_owner='NEXT' for share;
  if not found then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into v_bundle from public.weekly_source_entitlement_decision_bundles
    where decision_bundle_id=p_decision_bundle_id and bundle_revision=p_bundle_revision
    for share;
  if not found or v_bundle.bundle_kind is distinct from 'CROSS_CONTRACT_A_B'
     or v_bundle.state not in ('PROPOSED','COMMITTED')
     or v_bundle.source_root_timesheet_id is null or v_bundle.target_root_timesheet_id is null
     or v_bundle.source_root_timesheet_id=v_bundle.target_root_timesheet_id
     or v_bundle.source_contract_id is null or v_bundle.target_contract_id is null
     or v_bundle.source_contract_id=v_bundle.target_contract_id
     or pg_catalog.array_ndims(v_bundle.proposed_head_ids) is distinct from 1
     or pg_catalog.array_lower(v_bundle.proposed_head_ids,1) is distinct from 1
     or pg_catalog.cardinality(v_bundle.proposed_head_ids)<>2
     or v_bundle.proposed_head_ids[1] is null or v_bundle.proposed_head_ids[2] is null
     or v_bundle.proposed_head_ids[1]=v_bundle.proposed_head_ids[2] then
    raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BUNDLE_NOT_EXACT';
  end if;
  v_roots:=array[v_bundle.source_root_timesheet_id,v_bundle.target_root_timesheet_id];
  v_bookings:=array[v_bundle.source_root_family_booking_id,v_bundle.target_root_family_booking_id];
  v_contracts:=array[v_bundle.source_contract_id,v_bundle.target_contract_id];

  -- Source family/root locks already precede this call. Reacquire exact rows
  -- consistently, without resolving old physical versions or choosing history.
  for v_row in select t.timesheet_id from public.timesheets t
    where t.timesheet_id=any(v_roots)
    order by pg_catalog.btrim(t.booking_id),t.timesheet_id for key share
  loop null; end loop;
  for v_row in select c.id from public.contracts c
    where c.id=any(v_contracts) order by c.id for key share
  loop null; end loop;
  for v_role in select i from pg_catalog.generate_series(1,2) r(i)
    order by pg_catalog.btrim(v_bookings[i]),v_roots[i]
  loop
    v_i:=v_role;
    select * into strict v_root from public.timesheets where timesheet_id=v_roots[v_i];
    select * into strict v_contract from public.contracts where id=v_contracts[v_i];
    if v_root.is_current is distinct from true or v_root.archived_at_utc is not null
       or v_root.revoked_at is not null or v_root.booking_id is distinct from v_bookings[v_i]
       or v_root.contract_id is distinct from v_contracts[v_i]
       or v_root.week_ending_date is distinct from v_bundle.week_ending_date
       or v_contract.candidate_id is distinct from v_bundle.candidate_id then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_ROOT_NOT_EXACT';
    end if;
    -- A canonical current collision is a refusal, never an identity remap.
    select pg_catalog.count(*)::integer into v_seen from (
      select t.timesheet_id from public.timesheets t
      where t.is_current=true and t.booking_id is not null and pg_catalog.btrim(t.booking_id)<>''
        and pg_catalog.btrim(t.booking_id)=pg_catalog.btrim(v_bookings[v_i])
      limit 2) actual_current;
    if v_seen<>1 then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_ROOT_NOT_EXACT';
    end if;
    select * into v_head from public.weekly_source_entitlement_heads
      where id=v_bundle.proposed_head_ids[v_i] for share;
    if not found or v_head.state is distinct from 'STAGED'
       or v_head.decision_bundle_id is distinct from p_decision_bundle_id
       or v_head.bundle_revision is distinct from p_bundle_revision
       or v_head.decision_id is distinct from v_bundle.decision_id
       or v_head.decided_by_user_id is distinct from v_bundle.decided_by_user_id
       or v_head.agency_id is distinct from v_bundle.agency_id
       or v_head.root_timesheet_id is distinct from v_roots[v_i]
       or v_head.root_family_booking_id is distinct from v_bookings[v_i]
       or v_head.root_timesheet_version is distinct from v_root.version
       or v_head.candidate_id is distinct from v_bundle.candidate_id
       or v_head.contract_id is distinct from v_contracts[v_i]
       or v_head.week_ending_date is distinct from v_bundle.week_ending_date
       or (select pg_catalog.count(*) from public.weekly_source_entitlement_head_components c
           where c.head_id=v_head.id) is distinct from v_head.component_count::bigint then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_STAGED_NOT_EXACT';
    end if;
    select pg_catalog.count(*)::integer into v_seen from (
      select a.id from public.weekly_source_root_authorisations a
      where a.withdrawn_at_utc is null and (a.root_timesheet_id=v_roots[v_i]
        or pg_catalog.btrim(a.family_booking_id)=pg_catalog.btrim(v_bookings[v_i]))
      order by a.id limit 2 for update) actual_authorisation;
    select * into v_auth from public.weekly_source_root_authorisations a
      where a.root_timesheet_id=v_roots[v_i] and a.withdrawn_at_utc is null;
    select pg_catalog.count(*)::integer into v_before_count from (
      select h.id from public.weekly_source_entitlement_heads h
      where h.state='COMMITTED_CURRENT'
        and (h.root_timesheet_id=v_roots[v_i]
          or pg_catalog.btrim(h.root_family_booking_id)=pg_catalog.btrim(v_bookings[v_i]))
      order by h.id limit 2 for share) actual_before;
    if v_seen>1 or v_before_count>1 then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BEFORE_NOT_EXACT';
    end if;
    if v_before_count=1 then
      select * into strict v_before_head from public.weekly_source_entitlement_heads h
        where h.state='COMMITTED_CURRENT' and (h.root_timesheet_id=v_roots[v_i]
          or pg_catalog.btrim(h.root_family_booking_id)=pg_catalog.btrim(v_bookings[v_i]));
      if v_seen<>1 or v_auth.id is null
         or v_auth.family_booking_id is distinct from v_bookings[v_i]
         or v_auth.timesheet_version is distinct from v_root.version
         or v_auth.current_entitlement_head_id is distinct from v_before_head.id
         or p_before_source_event_ids[v_i] is distinct from v_before_head.id
         or p_before_financial_snapshot_ids[v_i] is not null
         or v_before_head.root_timesheet_id is distinct from v_roots[v_i]
         or v_before_head.root_family_booking_id is distinct from v_bookings[v_i]
         or v_before_head.root_timesheet_version is distinct from v_root.version
         or v_before_head.candidate_id is distinct from v_bundle.candidate_id
         or v_before_head.contract_id is distinct from v_contracts[v_i]
         or v_before_head.week_ending_date is distinct from v_bundle.week_ending_date then
        raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_HEAD_BEFORE_NOT_EXACT';
      end if;
      v_before_heads[v_i]:=v_before_head.id;
    else
      if v_seen=1 then
        if v_auth.id is null or v_auth.id is distinct from p_before_source_event_ids[v_i]
           or v_auth.family_booking_id is distinct from v_bookings[v_i]
           or v_auth.timesheet_version is distinct from v_root.version
           or v_auth.current_entitlement_head_id is not null
           or v_root.authorised_at_server is null then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_INITIAL_BEFORE_NOT_EXACT';
        end if;
      elsif v_i<>2 or p_before_source_event_ids[v_i] is not null then
        raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_NULL_EVENT_NOT_PERMITTED';
      end if;
      if p_before_financial_snapshot_ids[v_i] is null then
        -- Only an actually blank new B has no own before evidence. The caller's
        -- accepted target_auth/signature checks still dominate this helper;
        -- genuine I6 must succeed after capture, before activation.
        v_blank:=private.weekly_source_publication_target_root_blank_v1(v_roots[v_i],v_bookings[v_i]);
        if v_i<>2 or v_seen<>0 or v_blank->'blank' is distinct from 'true'::jsonb then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FINANCIAL_REQUIRED';
        end if;
        v_tf_components[v_i]:='[]'::jsonb;
        continue;
      end if;
      select * into v_tf from public.timesheets_financials
        where id=p_before_financial_snapshot_ids[v_i] for share;
      select pg_catalog.count(*)::integer into v_matches from (
        select f.id from public.timesheets_financials f
        where f.timesheet_id=v_roots[v_i] and f.is_current=true limit 2) actual_financial;
      if v_tf.id is null or v_matches<>1 or v_tf.timesheet_id is distinct from v_roots[v_i]
         or v_tf.timesheet_version is distinct from v_root.version
         or v_tf.is_current is distinct from true or v_tf.is_stale is distinct from false
         or v_tf.candidate_id is distinct from v_bundle.candidate_id
         or v_tf.client_id is distinct from v_contract.client_id
         or pg_catalog.jsonb_typeof(v_tf.invoice_breakdown_json->'segments') is distinct from 'array'
         or (v_seen=1 and v_tf.authorised_at_utc is null) then
        raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FINANCIAL_NOT_EXACT';
      end if;
      if v_seen=0 then
        v_blank:=private.weekly_source_publication_target_root_blank_v1(v_roots[v_i],v_bookings[v_i]);
        if v_blank->'blank' is distinct from 'true'::jsonb and (
          v_bundle.whole_root_review_required is distinct from true
          or v_bundle.whole_root_reviewed_by_user_id is null
          or v_bundle.whole_root_reviewed_at_utc is null
          or not pg_catalog.isfinite(v_bundle.whole_root_reviewed_at_utc)) then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_TARGET_REVIEW_REQUIRED';
        end if;
      end if;
      -- One composer over each exact named snapshot's existing segment vector.
      -- It selects no current upload, movement ladder, revision history or I7.
      v_tf_components[v_i]:=private.weekly_source_entitlement_components_v1(
        v_tf.invoice_breakdown_json->'segments','[]'::jsonb);
    end if;
  end loop;

  perform 1 from public.candidates where id=v_bundle.candidate_id for key share;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_bundle.candidate_id for update;
  if not found then
    raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_CANDIDATE_OWNER_MISSING';
  end if;
  -- Unique immutable Source event, never current_revision_id/applied_revision_id.
  for v_i in 1..2 loop
    if v_before_heads[v_i] is not null or p_before_source_event_ids[v_i] is null then
      continue;
    end if;
    select * into v_revision from private.bpay_next_work_revision
      where source_event_id=p_before_source_event_ids[v_i] for share;
    if not found or v_revision.source_kind is distinct from 'SOURCE'
       or v_revision.source_head_id is not null
       or v_revision.financial_snapshot_id is distinct from p_before_financial_snapshot_ids[v_i]
       or v_revision.physical_timesheet_id is distinct from v_roots[v_i]
       or v_revision.physical_timesheet_version is distinct from
         (select t.version from public.timesheets t where t.timesheet_id=v_roots[v_i])
       or v_revision.week_ending_date is distinct from v_bundle.week_ending_date
       or v_revision.currency is distinct from 'GBP'
       or v_revision.approved_at_utc is null or v_revision.sealed_at_utc is null
       or not pg_catalog.isfinite(v_revision.approved_at_utc)
       or not pg_catalog.isfinite(v_revision.sealed_at_utc) then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_INITIAL_REVISION_NOT_EXACT';
    end if;
    select * into strict v_work from private.bpay_next_work where id=v_revision.work_id;
    if v_work.work_kind is distinct from 'SOURCE'
       or v_work.booking_id is distinct from v_bookings[v_i]
       or v_work.candidate_id is distinct from v_bundle.candidate_id
       or v_work.contract_id is distinct from v_contracts[v_i]
       or v_work.week_ending_date is distinct from v_bundle.week_ending_date
       or not exists (
         select 1 from private.bpay_next_publication p
         join private.bpay_next_command c on c.id=p.command_id
         join private.bpay_next_command_member m
           on m.command_id=c.id and m.candidate_id=v_bundle.candidate_id
         where p.work_id=v_work.id and p.revision_id=v_revision.id
           and p.candidate_id=v_bundle.candidate_id and p.revision_no=v_revision.revision_no
           and c.id=private.bpay_next_source_command_id_v1(p_before_source_event_ids[v_i])
           and c.command_kind='POSITION_APPLY' and c.status in ('SEALED','COMPLETE')
           and c.expected_member_count=1 and c.sealed_at_utc is not null
           and pg_catalog.isfinite(c.sealed_at_utc) and m.member_no=1) then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_INITIAL_PUBLICATION_NOT_EXACT';
    end if;
    v_before_revisions[v_i]:=v_revision.id;
  end loop;

  for v_component in select c.* from public.weekly_source_entitlement_head_components c
    where c.head_id=any(v_bundle.proposed_head_ids) and c.component_kind='WORKED_TIME'
    order by c.head_id,c.component_ordinal
  loop
    -- The retained canonical owner requires DEC JSON strings, not the JSON
    -- numbers produced by to_jsonb(row). Its own scale/padding/magnitude guards
    -- remain authoritative; nullable numeric::text preserves NULL, and the
    -- explicit ISO date is independent of the session's DateStyle.
    v_canonical:=private.weekly_source_publication_component_canonical_v1(
      (pg_catalog.to_jsonb(v_component)-array['id','head_id','component_sha256',
        'decision_bundle_id','bundle_revision','created_at_utc'])||pg_catalog.jsonb_build_object(
        'work_date',pg_catalog.to_char(v_component.work_date,'YYYY-MM-DD'),
        'hours_day',v_component.hours_day::text,'hours_night',v_component.hours_night::text,
        'hours_sat',v_component.hours_sat::text,'hours_sun',v_component.hours_sun::text,
        'hours_bh',v_component.hours_bh::text,'unit_count',v_component.unit_count::text,
        'unit_pay_rate',v_component.unit_pay_rate::text,'unit_charge_rate',v_component.unit_charge_rate::text,
        'pay_ex_vat',v_component.pay_ex_vat::text,'charge_ex_vat',v_component.charge_ex_vat::text),
      'bpay_next_pair_detail.successor');
    v_component_sha:=private.weekly_source_publication_request_digest_v1(
      private.weekly_source_publication_component_content_v1(v_canonical));
    if v_component.decision_bundle_id is distinct from p_decision_bundle_id
       or v_component.bundle_revision is distinct from p_bundle_revision
       or v_component.component_sha256 is distinct from v_component_sha then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_COMPONENT_NOT_EXACT';
    end if;
    v_matches:=0; v_origin:=null; v_segment:=null;
    for v_i in 1..2 loop
      if v_before_heads[v_i] is not null then
        if exists(select 1 from public.weekly_source_entitlement_head_components c
          where c.head_id=v_before_heads[v_i] and c.component_id=v_component.component_id) then
          v_matches:=v_matches+1; v_origin:=v_i;
        end if;
      else
        select pg_catalog.count(*)::integer into v_seen
          from pg_catalog.jsonb_array_elements(v_tf_components[v_i]) c(value)
          where c.value->>'component_id'=v_component.component_id::text;
        if v_seen>1 then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_COMPONENT_AMBIGUOUS';
        elsif v_seen=1 then v_matches:=v_matches+1; v_origin:=v_i;
        end if;
      end if;
    end loop;
    if v_matches<>1 then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_COMPONENT_ORIGIN_NOT_EXACT';
    end if;
    v_i:=v_origin;
    v_reprice_detail:=private.weekly_source_destination_reprice_detail_v1(
      p_decision_bundle_id,p_bundle_revision,v_canonical,v_i);
    if v_reprice_detail is not null then
      v_detail:=v_reprice_detail;
    elsif v_before_heads[v_i] is not null then
      select * into strict v_before_component from public.weekly_source_entitlement_head_components c
        where c.head_id=v_before_heads[v_i] and c.component_id=v_component.component_id;
      v_before_canonical:=private.weekly_source_publication_component_canonical_v1(
        (pg_catalog.to_jsonb(v_before_component)-array['id','head_id','component_sha256',
          'decision_bundle_id','bundle_revision','created_at_utc'])||pg_catalog.jsonb_build_object(
          'work_date',pg_catalog.to_char(v_before_component.work_date,'YYYY-MM-DD'),
          'hours_day',v_before_component.hours_day::text,'hours_night',v_before_component.hours_night::text,
          'hours_sat',v_before_component.hours_sat::text,'hours_sun',v_before_component.hours_sun::text,
          'hours_bh',v_before_component.hours_bh::text,'unit_count',v_before_component.unit_count::text,
          'unit_pay_rate',v_before_component.unit_pay_rate::text,'unit_charge_rate',v_before_component.unit_charge_rate::text,
          'pay_ex_vat',v_before_component.pay_ex_vat::text,'charge_ex_vat',v_before_component.charge_ex_vat::text),
        'bpay_next_pair_detail.before');
      select * into strict v_before_head from public.weekly_source_entitlement_heads
        where id=v_before_heads[v_i];
      select * into v_existing from private.bpay_next_source_chosen_detail d
        where d.head_id=v_before_heads[v_i] and d.component_id=v_component.component_id;
      if not found or v_before_component.component_sha256 is distinct from v_component_sha
         or private.weekly_source_publication_request_digest_v1(
           private.weekly_source_publication_component_content_v1(v_before_canonical))
              is distinct from v_component_sha
         or v_existing.decision_bundle_id is distinct from v_before_head.decision_bundle_id
         or v_existing.bundle_revision is distinct from v_before_head.bundle_revision
         or v_existing.component_sha256 is distinct from v_component_sha
         or v_existing.detail_sha256 is distinct from
           pg_catalog.sha256(pg_catalog.convert_to(v_existing.detail_json::text,'UTF8')) then
        raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_HEAD_COPY_NOT_EXACT';
      end if;
      v_detail:=v_existing.detail_json; -- exact old JSON, no UTC/rate enrichment
    else
      select c.value into strict v_composed from pg_catalog.jsonb_array_elements(v_tf_components[v_i]) c(value)
        where c.value->>'component_id'=v_component.component_id::text;
      v_before_canonical:=private.weekly_source_publication_component_canonical_v1(
        v_composed,'bpay_next_pair_detail.snapshot');
      if private.weekly_source_publication_request_digest_v1(
           private.weekly_source_publication_component_content_v1(v_before_canonical))
             is distinct from v_component_sha then
        raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_SNAPSHOT_COMPONENT_NOT_EXACT';
      end if;
      select * into strict v_tf from public.timesheets_financials
        where id=p_before_financial_snapshot_ids[v_i];
      if v_before_revisions[v_i] is not null then
        select * into v_line from private.bpay_next_approved_line
          where revision_id=v_before_revisions[v_i]
            and component_key='SOURCE:'||v_component.component_id::text;
        v_hours:=coalesce(v_component.hours_day,0)+coalesce(v_component.hours_night,0)
          +coalesce(v_component.hours_sat,0)+coalesce(v_component.hours_sun,0)+coalesce(v_component.hours_bh,0);
        if not found or v_line.source_component_id is distinct from v_component.component_id
           or v_line.component_kind is distinct from 'WORK'
           or v_line.evidence_ref is distinct from 'source-component:'||v_component.component_id::text
             ||'#'||pg_catalog.encode(v_component_sha,'hex')
           or v_line.source_pay_ex_vat is distinct from
             (case when v_component.exclude_from_pay then 0 else v_component.pay_ex_vat end)
           or v_line.work_date is distinct from v_component.work_date
           or v_line.approved_quantity is distinct from v_hours then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FROZEN_LINE_NOT_EXACT';
        end if;
        v_rates:='{}'::jsonb; v_expected_rates:=0;
        for v_bucket in select * from (values
          ('DAY'::text,'day'::text,coalesce(v_component.hours_day,0)),
          ('NIGHT','night',coalesce(v_component.hours_night,0)),
          ('SAT','sat',coalesce(v_component.hours_sat,0)),
          ('SUN','sun',coalesce(v_component.hours_sun,0)),
          ('BH','bh',coalesce(v_component.hours_bh,0))) b(code,key,hours)
        loop
          select rd.approved_hours,rd.source_pay_rate into v_stored_hours,v_rate
            from private.bpay_next_rate_detail rd
            where rd.approved_line_id=v_line.id and rd.bucket=v_bucket.code;
          if coalesce(v_stored_hours,0) is distinct from v_bucket.hours
             or (v_bucket.hours<>0 and not found)
             or (v_bucket.hours=0 and found) then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FROZEN_BUCKET_NOT_EXACT';
          end if;
          if v_bucket.hours<>0 then
            v_expected_rates:=v_expected_rates+1;
            v_rates:=v_rates||pg_catalog.jsonb_build_object(v_bucket.key,v_rate);
          end if;
        end loop;
        select pg_catalog.count(*)::integer into v_actual_rates from private.bpay_next_rate_detail rd
          where rd.approved_line_id=v_line.id;
        if v_actual_rates<>v_expected_rates or v_line.expected_rate_detail_count<>v_expected_rates then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FROZEN_BUCKET_NOT_EXACT';
        end if;
        select pg_catalog.count(*)::integer into v_seen from private.bpay_next_shift_detail s
          where s.approved_line_id=v_line.id;
        if v_seen<>1 then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FROZEN_SHIFT_NOT_EXACT';
        end if;
        select * into strict v_shift from private.bpay_next_shift_detail s where s.approved_line_id=v_line.id;
        if v_shift.work_date is distinct from v_component.work_date
           or v_shift.approved_hours is distinct from v_hours then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_FROZEN_SHIFT_NOT_EXACT';
        end if;
        v_break_total:=0; v_break_no:=0; v_all_clocked:=true; v_breaks:='[]'::jsonb;
        for v_row in select b.* from private.bpay_next_break_detail b
          where b.shift_detail_id=v_shift.id order by b.break_no
        loop
          v_break_no:=v_break_no+1;
          if v_row.break_no<>v_break_no or v_row.break_minutes<0 then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
          end if;
          if v_row.break_start_local is not null then
            v_break_minutes:=((pg_catalog.substring(v_row.break_end_local,1,2)::integer*60
              +pg_catalog.substring(v_row.break_end_local,4,2)::integer)
              -(pg_catalog.substring(v_row.break_start_local,1,2)::integer*60
              +pg_catalog.substring(v_row.break_start_local,4,2)::integer)+1440)%1440;
            if v_row.break_end_local is null or v_break_minutes=0
               or v_break_minutes<>v_row.break_minutes then
              raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
            end if;
          else v_all_clocked:=false;
          end if;
          v_break_total:=v_break_total+v_row.break_minutes;
          v_breaks:=v_breaks||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'start',v_row.break_start_local,'end',v_row.break_end_local));
        end loop;
        select * into strict v_revision from private.bpay_next_work_revision where id=v_before_revisions[v_i];
        select * into strict v_work from private.bpay_next_work where id=v_revision.work_id;
        v_detail:=pg_catalog.jsonb_build_object(
          'from_frozen_pair',true,'prior_approved_line_id',v_line.id,
          'prior_revision_id',v_revision.id,'prior_work_id',v_work.id,
          'prior_source_event_id',v_revision.source_event_id,
          'prior_financial_snapshot_id',v_revision.financial_snapshot_id,
          'prior_root_timesheet_id',v_revision.physical_timesheet_id,
          'prior_root_version',v_revision.physical_timesheet_version,
          'prior_family_booking_id',v_work.booking_id,
          'source_component_id',v_component.component_id,
          'source_component_sha256',pg_catalog.encode(v_component_sha,'hex'),
          'work_date',pg_catalog.to_char(v_shift.work_date,'YYYY-MM-DD'),'start',v_shift.shift_start_local,
          'end',v_shift.shift_end_local,'overnight',v_shift.shift_overnight,
          'break_minutes',v_break_total,'rates',v_rates);
        if v_all_clocked then v_detail:=v_detail||pg_catalog.jsonb_build_object('breaks',v_breaks); end if;
        if (v_shift.shift_start_at is null)<>(v_shift.shift_end_at is null)
           or (v_shift.shift_start_at is not null and (
             not pg_catalog.isfinite(v_shift.shift_start_at) or not pg_catalog.isfinite(v_shift.shift_end_at)
             or v_shift.shift_end_at<=v_shift.shift_start_at)) then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_UTC_INVALID';
        end if;
        if v_shift.shift_start_at is not null then
          v_detail:=v_detail||pg_catalog.jsonb_build_object(
            'start_utc',pg_catalog.to_char(v_shift.shift_start_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'end_utc',pg_catalog.to_char(v_shift.shift_end_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
        end if;
      else
        -- Reviewed, not-yet-authorised B: ordinary segment identity is real;
        -- no Final/movement/work-event/Bank approval identity is manufactured.
        select pg_catalog.count(*)::integer,pg_catalog.jsonb_agg(s.value)->0 into v_seen,v_segment
          from pg_catalog.jsonb_array_elements(v_tf.invoice_breakdown_json->'segments') s(value)
          where s.value->>'segment_id'=v_component.segment_id;
        if v_i<>2 or p_before_source_event_ids[v_i] is not null or v_seen<>1 then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_TARGET_SEGMENT_NOT_EXACT';
        end if;
        if (v_segment->>'start_local' is not null and v_segment->>'start' is not null
              and v_segment->>'start_local' is distinct from v_segment->>'start')
           or (v_segment->>'end_local' is not null and v_segment->>'end' is not null
              and v_segment->>'end_local' is distinct from v_segment->>'end') then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_CLOCK_ALIAS_CONFLICT';
        end if;
        v_start:=nullif(pg_catalog.btrim(coalesce(v_segment->>'start_local',v_segment->>'start','')),'');
        v_end:=nullif(pg_catalog.btrim(coalesce(v_segment->>'end_local',v_segment->>'end','')),'');
        v_rates:='{}'::jsonb;
        for v_bucket in select * from (values
          ('day'::text,v_tf.pay_day),('night',v_tf.pay_night),('sat',v_tf.pay_sat),
          ('sun',v_tf.pay_sun),('bh',v_tf.pay_bh)) b(key,rate)
        loop
          if pg_catalog.jsonb_typeof(v_segment->'weekly_source')='object' then
            v_rate:=(v_segment#>>array['weekly_source','pay_vector','rates',v_bucket.key])::numeric;
          else v_rate:=v_bucket.rate;
          end if;
          v_rates:=v_rates||pg_catalog.jsonb_build_object(v_bucket.key,v_rate);
        end loop;
        v_break_total:=0; v_break_no:=0; v_breaks:='[]'::jsonb;
        if v_segment ? 'breaks' and pg_catalog.jsonb_typeof(v_segment->'breaks') not in ('array','null') then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
        end if;
        for v_break in select value from pg_catalog.jsonb_array_elements(
          case when pg_catalog.jsonb_typeof(v_segment->'breaks')='array' then v_segment->'breaks' else '[]'::jsonb end)
        loop
          if pg_catalog.jsonb_typeof(v_break) is distinct from 'object'
             or coalesce(v_break->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
             or coalesce(v_break->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
          end if;
          v_break_minutes:=((pg_catalog.substring(v_break->>'end',1,2)::integer*60
            +pg_catalog.substring(v_break->>'end',4,2)::integer)
            -(pg_catalog.substring(v_break->>'start',1,2)::integer*60
            +pg_catalog.substring(v_break->>'start',4,2)::integer)+1440)%1440;
          if v_break_minutes=0 then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
          end if;
          v_break_no:=v_break_no+1; v_break_total:=v_break_total+v_break_minutes;
          v_breaks:=v_breaks||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'start',v_break->>'start','end',v_break->>'end'));
        end loop;
        if v_segment ? 'break_mins' and v_segment ? 'break_minutes'
           and (v_segment->>'break_mins')::integer is distinct from (v_segment->>'break_minutes')::integer then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
        end if;
        if v_break_no=0 then
          v_break_total:=coalesce((v_segment->>'break_mins')::integer,(v_segment->>'break_minutes')::integer,0);
        elsif (v_segment ? 'break_mins' or v_segment ? 'break_minutes') and v_break_total is distinct from
          coalesce((v_segment->>'break_mins')::integer,(v_segment->>'break_minutes')::integer) then
          raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_BREAK_NOT_EXACT';
        end if;
        v_detail:=pg_catalog.jsonb_build_object(
          'from_reviewed_target_tsfin',true,'before_financial_snapshot_id',v_tf.id,
          'before_root_timesheet_id',v_tf.timesheet_id,'before_root_version',v_tf.timesheet_version,
          'before_segment_id',v_component.segment_id,'source_component_id',v_component.component_id,
          'source_component_sha256',pg_catalog.encode(v_component_sha,'hex'),
          'decision_bundle_id',p_decision_bundle_id,'bundle_revision',p_bundle_revision,
          'snapshot_detail_sha256',pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            pg_catalog.jsonb_build_object('segments',v_tf.invoice_breakdown_json->'segments',
              'actual_schedule',v_tf.actual_schedule_json,'rate_source_refs',v_tf.rate_source_refs_json)::text,'UTF8')),'hex'),
          'work_date',v_segment->>'date','start',v_start,'end',v_end,
          'overnight',(v_segment->>'overnight')::boolean,'break_minutes',v_break_total,'rates',v_rates);
        if v_break_no>0 then v_detail:=v_detail||pg_catalog.jsonb_build_object('breaks',v_breaks); end if;
        if (v_segment->'start_utc' is not null and v_segment->'start_utc'<>'null'::jsonb)
           or (v_segment->'end_utc' is not null and v_segment->'end_utc'<>'null'::jsonb) then
          if pg_catalog.jsonb_typeof(v_segment->'start_utc') is distinct from 'string'
             or pg_catalog.jsonb_typeof(v_segment->'end_utc') is distinct from 'string'
             or coalesce(v_segment->>'start_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
             or coalesce(v_segment->>'end_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_UTC_INVALID';
          end if;
          begin
            v_start_utc:=(v_segment->>'start_utc')::timestamptz;
            v_end_utc:=(v_segment->>'end_utc')::timestamptz;
          exception when invalid_datetime_format or datetime_field_overflow or invalid_time_zone_displacement_value then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_UTC_INVALID';
          end;
          if not pg_catalog.isfinite(v_start_utc) or not pg_catalog.isfinite(v_end_utc)
             or v_end_utc<=v_start_utc
             or pg_catalog.to_char(v_start_utc at time zone 'Europe/London','YYYY-MM-DD')<>v_segment->>'date'
             or pg_catalog.to_char(v_start_utc at time zone 'Europe/London','HH24:MI')<>v_start
             or pg_catalog.to_char(v_end_utc at time zone 'Europe/London','HH24:MI')<>v_end
             or (v_end_utc at time zone 'Europe/London')::date<>(v_segment->>'date')::date
                +(case when (v_segment->>'overnight')::boolean then 1 else 0 end) then
            raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_UTC_INVALID';
          end if;
          v_detail:=v_detail||pg_catalog.jsonb_build_object('start_utc',v_segment->'start_utc','end_utc',v_segment->'end_utc');
        end if;
      end if;
    end if;
    -- Shared presentation qualification does not turn clocks into money.
    if pg_catalog.jsonb_typeof(v_detail) is distinct from 'object'
       or v_detail->>'work_date' is distinct from pg_catalog.to_char(v_component.work_date,'YYYY-MM-DD')
       or coalesce(v_detail->>'start','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or coalesce(v_detail->>'end','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or pg_catalog.jsonb_typeof(v_detail->'overnight') is distinct from 'boolean'
       or pg_catalog.jsonb_typeof(v_detail->'rates') is distinct from 'object'
       or coalesce(v_detail->>'break_minutes','') !~ '^[0-9]+$'
       or pg_catalog.octet_length(v_detail::text)>4096 then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_PRESENTATION_NOT_EXACT';
    end if;
    for v_bucket in select * from (values
      ('day'::text,coalesce(v_component.hours_day,0)),('night',coalesce(v_component.hours_night,0)),
      ('sat',coalesce(v_component.hours_sat,0)),('sun',coalesce(v_component.hours_sun,0)),
      ('bh',coalesce(v_component.hours_bh,0))) b(key,hours)
    loop
      v_rate:=(v_detail->'rates'->>v_bucket.key)::numeric;
      if (v_bucket.hours<>0 and not v_component.exclude_from_pay and v_rate is null)
         or (v_rate is not null and (v_rate::text in ('NaN','Infinity','-Infinity')
           or v_rate<>pg_catalog.round(v_rate,6) or pg_catalog.abs(v_rate)>=1000000000000)) then
        raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_USED_RATE_NOT_EXACT';
      end if;
    end loop;
    v_detail_sha:=pg_catalog.sha256(pg_catalog.convert_to(v_detail::text,'UTF8'));
    insert into private.bpay_next_source_chosen_detail
      (head_id,component_id,decision_bundle_id,bundle_revision,component_sha256,detail_json,detail_sha256)
      values(v_component.head_id,v_component.component_id,p_decision_bundle_id,p_bundle_revision,
        v_component_sha,v_detail,v_detail_sha)
      on conflict(head_id,component_id) do nothing;
    select * into strict v_existing from private.bpay_next_source_chosen_detail d
      where d.head_id=v_component.head_id and d.component_id=v_component.component_id;
    if v_existing.decision_bundle_id is distinct from p_decision_bundle_id
       or v_existing.bundle_revision is distinct from p_bundle_revision
       or v_existing.component_sha256 is distinct from v_component_sha
       or v_existing.detail_json is distinct from v_detail
       or v_existing.detail_sha256 is distinct from v_detail_sha then
      raise exception using errcode='23514',message='BPAY_NEXT_PAIR_DETAIL_REPLAY_CONFLICT';
    end if;
    v_count:=v_count+1;
  end loop;
  return v_count;
end
$function$;

alter function private.bpay_next_capture_source_pair_before_detail_v1(uuid,bigint,uuid[],uuid[]) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_capture_source_pair_before_detail_v1(uuid,bigint,uuid[],uuid[])
  from public,anon,authenticated,service_role;


-- Convert one Source-owned, already final approval into the small immutable
-- Banking Pay revision. The Source owner calls this only at its successful
-- outer boundary; this routine never chooses a Source decision or approves a
-- separate expense-claim Timesheet.




create or replace function private.bpay_next_stage_source_current_v1(
  p_root_timesheet_id uuid, p_source_event_id uuid, p_expected_head_id uuid
) returns table(work_id uuid,revision_id uuid,source_event_id uuid)
language plpgsql security definer
set search_path = pg_catalog, private, public
as $function$
declare
  v_existing record;
  v_ts public.timesheets%rowtype;
  v_tf public.timesheets_financials%rowtype;
  v_contract public.contracts%rowtype;
  v_work private.bpay_next_work%rowtype;
  v_inventory jsonb;
  v_basis jsonb;
  v_scope jsonb;
  v_origin jsonb;
  v_initial_details jsonb;
  v_inventory_digest bytea;
  v_component jsonb;
  v_segment jsonb;
  v_chosen_component_sha bytea;
  v_chosen_detail_sha bytea;
  v_head_bundle_id uuid;
  v_head_bundle_revision bigint;
  v_segment_match_count integer;
  v_break jsonb;
  v_head_count integer;
  v_auth_id uuid;
  v_auth_generation integer;
  v_auth_signature text;
  v_auth_booking text;
  v_auth_version integer;
  v_head_authority text;
  v_head_certified_zero boolean;
  v_head_component_count integer;
  v_head_revision bigint;
  v_head_inventory_digest bytea;
  v_head_entitlement_digest bytea;
  v_head_generation_digest bytea;
  v_head_origin jsonb;
  v_candidate_name text;
  v_candidate_ref text;
  v_candidate_mileage_rate numeric;
  v_client_name text;
  v_client_mileage_rate numeric;
  v_component_id uuid;
  v_component_kind text;
  v_component_key text;
  v_component_amount numeric;
  v_total numeric:=0;
  v_hours numeric;
  v_rate_count integer;
  v_schedule_count integer;
  v_line_id uuid;
  v_shift_id uuid;
  v_break_no integer;
  v_break_minutes integer;
  v_break_total integer;
  v_break_start text;
  v_break_end text;
  v_use_segment boolean;
  v_line_no integer:=0;
  v_work_count integer:=0;
  v_missing_work_date boolean:=false;
  v_detail_kind text;
  v_revision_id uuid;
  v_first_snapshot boolean;
  v_source_pay_method text;
  v_bucket record;
  v_source_rate numeric;
  v_destination_stage_snapshot jsonb;
  v_stage_financial_id uuid;
  v_job_title text;
  v_band_label text;
  v_timesheet_reference text;
begin
  if p_root_timesheet_id is null or p_source_event_id is null then
    raise exception using errcode='22023', message='BPAY_NEXT_SOURCE_STAGE_INPUT_INVALID';
  end if;
  if (select active_owner from private.bpay_next_module_control
      where id=1 for share)<>'NEXT' then
    raise exception using errcode='55000', message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  -- Exact replay precedes current-state discovery: the Source head may have
  -- advanced since this already accepted event, but its revision cannot.
  select r.id as revision_id,w.id as work_id,r.physical_timesheet_id,
         r.source_head_id,r.source_kind
    into v_existing
    from private.bpay_next_work_revision r
    join private.bpay_next_work w on w.id=r.work_id
    where r.source_event_id=p_source_event_id;
  if found then
    if v_existing.physical_timesheet_id is distinct from p_root_timesheet_id
       or v_existing.source_head_id is distinct from p_expected_head_id
       or v_existing.source_kind not in ('SOURCE','PROTECTED') then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_STAGE_REPLAY_CONFLICT';
    end if;
    work_id:=v_existing.work_id;
    revision_id:=v_existing.revision_id;
    source_event_id:=p_source_event_id;
    return next;
    return;
  end if;

  if private.bpay_next_approval_route_v1(p_root_timesheet_id)<>'SOURCE_HOURS' then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_STAGE_ROUTE_INVALID';
  end if;
  select * into strict v_ts from public.timesheets
    where timesheet_id=p_root_timesheet_id for key share;
  select * into strict v_contract from public.contracts
    where id=v_ts.contract_id for key share;
  v_first_snapshot:=p_expected_head_id is null;
  -- A first authorisation is the sole case in which the financial snapshot
  -- supplies Source money. A committed head supplies its own complete money
  -- and may have no current TSFIN row (the Source publisher does not create
  -- one). Never require or silently substitute an older snapshot for a head.
  select * into v_tf from public.timesheets_financials
    where timesheet_id=p_root_timesheet_id and is_current=true for share;
  -- The saved contract channel is available even when the first-authorisation
  -- owner leaves TSFIN.pay_method NULL, or a head has no TSFIN at all.
  v_destination_stage_snapshot:=private.weekly_source_destination_reprice_stage_snapshot_v1(
    p_root_timesheet_id,p_expected_head_id);
  if v_destination_stage_snapshot is not null then
    if v_first_snapshot or (v_destination_stage_snapshot->>'client_id')::uuid is distinct from v_contract.client_id then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_STAGE_CERTIFICATE_IDENTITY_MISMATCH';
    end if;
    v_source_pay_method:=v_destination_stage_snapshot->>'destination_pay_channel';
  else
  v_source_pay_method:=upper(coalesce(
    case when v_first_snapshot then v_tf.pay_method end,
    v_contract.pay_method_snapshot,''));
  end if;
  if v_ts.is_current is distinct from true
     or (v_first_snapshot and (
       v_tf.id is null or v_ts.authorised_at_server is null
       or v_tf.authorised_at_utc is null
       or v_tf.is_stale is distinct from false
       or v_tf.timesheet_version<>v_ts.version
       or v_tf.candidate_id is distinct from v_contract.candidate_id
       or v_tf.client_id is distinct from v_contract.client_id))
     or v_source_pay_method not in ('PAYE','UMBRELLA') then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SOURCE_STAGE_FINANCIAL_NOT_CURRENT',
      detail=pg_catalog.jsonb_build_object(
        'timesheet_current',v_ts.is_current is true,
        'timesheet_authorised',v_ts.authorised_at_server is not null,
        'financial_authorised',v_tf.authorised_at_utc is not null,
        'financial_fresh',v_tf.is_stale is false,
        'version_matches',v_tf.timesheet_version=v_ts.version,
        'candidate_matches',v_tf.candidate_id is not distinct from v_contract.candidate_id,
        'client_matches',v_tf.client_id is not distinct from v_contract.client_id,
        'pay_method',v_source_pay_method)::text;
  end if;
  select a.id,a.authorisation_generation,a.authorised_row_signature,
         a.family_booking_id,a.timesheet_version
    into v_auth_id,v_auth_generation,v_auth_signature,v_auth_booking,v_auth_version
    from public.weekly_source_root_authorisations a
    where a.root_timesheet_id=p_root_timesheet_id
      and a.withdrawn_at_utc is null
      and a.current_entitlement_head_id is not distinct from p_expected_head_id
    for share;
  if v_auth_id is null then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_STAGE_AUTHORITY_MISMATCH';
  end if;
  if v_first_snapshot then
    if v_auth_id<>p_source_event_id
       or exists(select 1 from public.weekly_source_entitlement_heads h
                 where pg_catalog.btrim(h.root_family_booking_id)
                       =pg_catalog.btrim(v_ts.booking_id)) then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_FIRST_SNAPSHOT_NOT_PERMITTED';
    end if;
    v_head_authority:='LOCKED_FINAL_SOURCE';
  else
    if p_source_event_id<>p_expected_head_id then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_HEAD_EVENT_MISMATCH';
    end if;
    select h.authority_kind,h.certified_zero,h.component_count,
           h.decision_bundle_id,h.bundle_revision,h.head_revision,
           h.inventory_digest,h.entitlement_digest,h.source_generation_digest,
           h.source_origin_json
      into v_head_authority,v_head_certified_zero,v_head_component_count,
           v_head_bundle_id,v_head_bundle_revision,v_head_revision,
           v_head_inventory_digest,v_head_entitlement_digest,v_head_generation_digest,
           v_head_origin
      from public.weekly_source_entitlement_heads h
      where h.id=p_expected_head_id and h.root_timesheet_id=p_root_timesheet_id
        and h.root_family_booking_id=v_ts.booking_id
        and h.root_timesheet_version=v_ts.version
        and h.candidate_id=v_contract.candidate_id
        and h.week_ending_date=v_ts.week_ending_date
        and h.contract_id=v_contract.id and h.state='COMMITTED_CURRENT'
      for share;
    if not found then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_HEAD_NOT_CURRENT';
    end if;
  end if;
  v_inventory:=private.weekly_source_effective_inventory_v1(p_root_timesheet_id);
  if coalesce((v_inventory->>'ok')::boolean,false) is not true
     or (v_inventory->>'authority') is distinct from
        (case when v_first_snapshot then 'TSFIN' else 'HEAD' end)
     or (v_inventory->>'head_id')::uuid is distinct from p_expected_head_id
     or pg_catalog.jsonb_typeof(v_inventory->'components')<>'array'
     or (v_inventory->>'component_count')::integer is distinct from
        pg_catalog.jsonb_array_length(v_inventory->'components')
     or (not v_first_snapshot and v_head_component_count is distinct from
        pg_catalog.jsonb_array_length(v_inventory->'components')) then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_INVENTORY_NOT_EXACT';
  end if;
  -- JD01: I7 calls the genuine Source I1 once for this complete vector. Missing
  -- basis is unavailable, never a zero approval or a second live-money route.
  -- This qualification precedes every Banking financial INSERT. The actual
  -- Source owner must capture all chosen HEAD detail before invoking this mapper.
  v_basis:=v_inventory->'approval_basis';
  v_scope:=v_basis->'scope';
  v_origin:=v_basis->'origin';
  if pg_catalog.jsonb_typeof(v_basis) is distinct from 'object'
     or pg_catalog.jsonb_typeof(v_scope) is distinct from 'object'
     or pg_catalog.jsonb_typeof(v_origin) is distinct from 'object'
     or v_basis->'coverage_complete' is distinct from 'true'::jsonb
     or v_basis->'component_count' is distinct from
        pg_catalog.to_jsonb(pg_catalog.jsonb_array_length(v_inventory->'components'))
     or coalesce(v_basis->>'inventory_digest','') !~ '^[0-9a-f]{64}$'
     or coalesce(v_basis->>'entitlement_digest','') !~ '^[0-9a-f]{64}$'
     or coalesce(v_basis->>'detail_digest','') !~ '^[0-9a-f]{64}$'
     or coalesce(v_basis->>'policy_fingerprint','') !~ '^[0-9a-f]{64}$'
     or coalesce(v_basis->>'approved_pay_ex_vat','') !~ '^-?[0-9]+[.][0-9]{2}$'
     or v_basis->>'inventory_digest' is distinct from v_inventory->>'inventory_digest'
     or v_scope->'root_timesheet_id' is distinct from pg_catalog.to_jsonb(v_ts.timesheet_id)
     or v_scope->'family_booking_id' is distinct from pg_catalog.to_jsonb(v_ts.booking_id)
     or v_scope->'root_version' is distinct from pg_catalog.to_jsonb(v_ts.version::text)
     or v_scope->'candidate_id' is distinct from pg_catalog.to_jsonb(v_contract.candidate_id)
     or v_scope->'client_id' is distinct from pg_catalog.to_jsonb(v_contract.client_id)
     or v_scope->'contract_id' is distinct from pg_catalog.to_jsonb(v_contract.id)
     or v_scope->'week_ending_date' is distinct from pg_catalog.to_jsonb(v_ts.week_ending_date)
     or v_auth_booking is distinct from v_ts.booking_id
     or v_auth_version is distinct from v_ts.version then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_APPROVAL_BASIS_NOT_EXACT';
  end if;
  -- A genuine ordinary HEAD can have no exceptional family. A declared family
  -- instead binds its exact PK/current root and bound version; neither lane
  -- trims or remaps the immutable raw WORK booking identity.
  if (v_scope->'target_family_id'='null'::jsonb
      and v_scope->'family_bound_version'='null'::jsonb) is not true then
    if pg_catalog.jsonb_typeof(v_scope->'target_family_id') is distinct from 'string'
       or pg_catalog.jsonb_typeof(v_scope->'family_bound_version') is distinct from 'string'
       or coalesce(v_scope->>'target_family_id','') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_scope->>'family_bound_version','') !~ '^[1-9][0-9]*$' then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_APPROVAL_SCOPE_NOT_EXACT';
    end if;
    if not exists(select 1 from public.weekly_exceptional_pay_target_families f
      where f.id=(v_scope->>'target_family_id')::uuid
        and f.bound_version::text=v_scope->>'family_bound_version'
        and f.root_timesheet_id=v_ts.timesheet_id
        and f.candidate_id=v_contract.candidate_id and f.contract_id=v_contract.id
        and f.week_ending_date=v_ts.week_ending_date) then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_APPROVAL_SCOPE_NOT_EXACT';
    end if;
  end if;
  v_inventory_digest:=pg_catalog.decode(v_basis->>'inventory_digest','hex');
  if v_first_snapshot then
    v_initial_details:=pg_catalog.jsonb_build_object(
      'segments',v_tf.invoice_breakdown_json->'segments',
      'additional_units',v_tf.additional_units_json,
      'actual_schedule',v_tf.actual_schedule_json,
      'rate_source_refs',v_tf.rate_source_refs_json);
    if v_origin is distinct from pg_catalog.jsonb_build_object(
        'kind','INITIAL_AUTHORISED_TSFIN_V1','root_authorisation_id',v_auth_id,
        'financial_snapshot_id',v_tf.id,'authorisation_generation',v_auth_generation,
        'root_timesheet_id',v_ts.timesheet_id,'root_version',v_ts.version::text,
        'authorised_row_signature',v_auth_signature,
        'financial_snapshot_digest',pg_catalog.encode(
          private.weekly_source_sha256_jsonb_v1(
            'WEEKLY_SOURCE_APPROVED_FINANCIAL_SNAPSHOT_V2',pg_catalog.jsonb_build_object(
            'policy',v_tf.policy_snapshot_json,'details',v_initial_details,
            'components',v_inventory->'components')),'hex'),
        'inventory_digest',v_basis->>'inventory_digest',
        'entitlement_digest',v_basis->>'entitlement_digest')
       or v_basis->>'detail_digest' is distinct from pg_catalog.encode(
         private.weekly_source_sha256_jsonb_v1(
           'WEEKLY_SOURCE_APPROVED_DETAIL_V2',v_initial_details),'hex')
       or v_basis->>'policy_fingerprint' is distinct from pg_catalog.encode(
         private.weekly_source_sha256_jsonb_v1(
           'WEEKLY_SOURCE_APPROVED_POLICY_V2',v_tf.policy_snapshot_json),'hex') then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_INITIAL_BASIS_ORIGIN_MISMATCH';
    end if;
  elsif v_origin is distinct from pg_catalog.jsonb_build_object(
      'kind','COMMITTED_SOURCE_HEAD_V1','head_id',p_expected_head_id,
      'head_revision',v_head_revision::text,'decision_bundle_id',v_head_bundle_id,
      'bundle_revision',v_head_bundle_revision::text,'root_authorisation_id',v_auth_id,
      'authorisation_generation',v_auth_generation,'root_timesheet_id',v_ts.timesheet_id,
      'root_version',v_ts.version::text,
      'source_generation_digest',pg_catalog.encode(v_head_generation_digest,'hex'),
      'source_revision',v_head_origin,'inventory_digest',v_basis->>'inventory_digest',
      'entitlement_digest',v_basis->>'entitlement_digest')
     or v_inventory_digest is distinct from v_head_inventory_digest
     or pg_catalog.decode(v_basis->>'entitlement_digest','hex') is distinct from
        v_head_entitlement_digest
     or v_basis->>'policy_fingerprint' is distinct from v_head_origin->>'policy_fingerprint'
     or pg_catalog.jsonb_typeof(v_head_origin) is distinct from 'object'
     or private.weekly_source_publication_request_digest_v1(v_head_origin) is distinct from
        v_head_generation_digest then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_HEAD_BASIS_ORIGIN_MISMATCH';
  end if;
  for v_component in select value from pg_catalog.jsonb_array_elements(
    v_inventory->'components')
  loop
    v_component_kind:=v_component->>'component_kind';
    if v_component_kind not in
       ('WORKED_TIME','ADDITIONAL_UNIT','EXPENSE','SOURCE_FIXED_EXPENSE')
       or nullif(v_component->>'component_id','') is null
       or (v_component->>'pay_ex_vat')::numeric is null
       or (v_component->>'pay_ex_vat')::numeric<>
          pg_catalog.round((v_component->>'pay_ex_vat')::numeric,2)
       or (v_component->>'exclude_from_pay')::boolean is null then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_COMPONENT_INVALID';
    end if;
    if v_component_kind='WORKED_TIME' then
      v_work_count:=v_work_count+1;
      if nullif(v_component->>'work_date','') is null then
        v_missing_work_date:=true;
      end if;
    end if;
    v_total:=v_total+case when (v_component->>'exclude_from_pay')::boolean
      then 0 else (v_component->>'pay_ex_vat')::numeric end;
  end loop;
  if v_total<>pg_catalog.round(v_total,2) then
    raise exception using errcode='22003', message='BPAY_NEXT_SOURCE_TOTAL_PRECISION_INVALID';
  end if;
  if (v_basis->>'approved_pay_ex_vat')::numeric is distinct from v_total then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_APPROVAL_MONEY_MISMATCH';
  end if;
  -- With no committed head, the authorised financial snapshot is the first
  -- Source amount. An empty or incomplete component inventory must never
  -- turn a positive authorised amount into a certified zero payment.
  if v_first_snapshot and (v_tf.total_pay_ex_vat is null
       or v_total is distinct from pg_catalog.round(v_tf.total_pay_ex_vat,2)) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SOURCE_FIRST_TOTAL_MISMATCH';
  end if;
  v_head_count:=pg_catalog.jsonb_array_length(v_inventory->'components');
  if v_head_count=0 and v_total<>0 then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_EMPTY_MONEY_INVALID';
  end if;
  v_detail_kind:=case when v_work_count>0 and not v_missing_work_date
    then 'SHIFT' when v_work_count>0 then 'AGGREGATE' else 'FIXED' end;
  if v_destination_stage_snapshot is not null then
    v_candidate_name:=v_destination_stage_snapshot#>>'{metadata,candidate_display_name}';
    v_candidate_ref:=v_destination_stage_snapshot#>>'{metadata,candidate_reference}';
    v_client_name:=v_destination_stage_snapshot#>>'{metadata,client_display_name}';
    v_job_title:=v_destination_stage_snapshot#>>'{metadata,job_title}';
    v_band_label:=v_destination_stage_snapshot#>>'{metadata,band_label}';
    v_timesheet_reference:=v_destination_stage_snapshot#>>'{metadata,timesheet_reference}';
    v_stage_financial_id:=(v_destination_stage_snapshot->>'financial_snapshot_id')::uuid;
    v_schedule_count:=pg_catalog.jsonb_array_length(v_destination_stage_snapshot->'rate_schedule');
  else
  select coalesce(nullif(btrim(c.display_name),''),
                  nullif(btrim(concat_ws(' ',c.first_name,c.last_name)),''),
                  c.id::text),c.tms_ref,c.mileage_pay_rate
    into strict v_candidate_name,v_candidate_ref,v_candidate_mileage_rate
    from public.candidates c where c.id=v_contract.candidate_id;
  select cl.name,cl.mileage_charge_rate
    into strict v_client_name,v_client_mileage_rate
    from public.clients cl where cl.id=v_contract.client_id;
  select count(*) into v_schedule_count
    from private.bpay_next_contract_rate_rows_v1(
      v_contract.rates_json,v_contract.bucket_labels_json,
      v_contract.additional_rates_json,
      coalesce(v_tf.mileage_pay_rate,v_contract.mileage_pay_rate,
               v_candidate_mileage_rate),
      coalesce(v_tf.mileage_charge_rate,v_contract.mileage_charge_rate,
               v_client_mileage_rate));
    v_stage_financial_id:=v_tf.id;
    v_job_title:=v_contract.role; v_band_label:=v_contract.band; v_timesheet_reference:=v_ts.reference_number;
  end if;
  -- Source head publication can cover two roots. The worker-control lock is
  -- taken before either work lock, matching the pair publisher and worker.
  insert into private.bpay_next_worker_control(candidate_id)
    values(v_contract.candidate_id) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_contract.candidate_id for update;
  select * into v_work from private.bpay_next_work
    where booking_id=v_ts.booking_id for update;
  if not found then
    insert into private.bpay_next_work
      (candidate_id,contract_id,original_timesheet_id,booking_id,
       work_kind,week_ending_date)
      values(v_contract.candidate_id,v_contract.id,v_ts.timesheet_id,
             v_ts.booking_id,'SOURCE',v_ts.week_ending_date)
      returning * into v_work;
  elsif v_work.candidate_id<>v_contract.candidate_id
     or v_work.contract_id<>v_contract.id
     or v_work.week_ending_date<>v_ts.week_ending_date
     or v_work.work_kind<>'SOURCE' then
    raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_WORK_IDENTITY_CONFLICT';
  end if;
  insert into private.bpay_next_work_revision
    (work_id,revision_no,source_kind,source_head_id,source_event_id,
     physical_timesheet_id,financial_snapshot_id,physical_timesheet_version,
     source_pay_channel,week_ending_date,detail_kind,expected_line_count,
     expected_rate_schedule_count,certified_zero,approved_source_ex_vat,
     candidate_display_name,candidate_reference,client_display_name,
     job_title,band_label,timesheet_reference,source_inventory_digest)
    values(v_work.id,v_work.current_revision_no+1,
      case when v_head_authority='PROTECTED' then 'PROTECTED' else 'SOURCE' end,
      p_expected_head_id,p_source_event_id,v_ts.timesheet_id,v_stage_financial_id,v_ts.version,
      v_source_pay_method,v_ts.week_ending_date,v_detail_kind,v_head_count,
      v_schedule_count,case when v_first_snapshot then v_head_count=0
        else v_head_certified_zero end,v_total,
      v_candidate_name,v_candidate_ref,v_client_name,
      v_job_title,v_band_label,v_timesheet_reference,v_inventory_digest)
    returning id into v_revision_id;
  if v_destination_stage_snapshot is not null then
    insert into private.bpay_next_rate_schedule
      (revision_id,rate_family,rate_code,unit_label,paye_rate,umbrella_rate,charge_rate)
      select v_revision_id,r.rate_family,r.rate_code,r.unit_label,r.paye_rate,r.umbrella_rate,r.charge_rate
        from pg_catalog.jsonb_to_recordset(v_destination_stage_snapshot->'rate_schedule')
          as r(rate_family text,rate_code text,unit_label text,paye_rate numeric,umbrella_rate numeric,charge_rate numeric);
  else
  insert into private.bpay_next_rate_schedule
    (revision_id,rate_family,rate_code,unit_label,paye_rate,umbrella_rate,charge_rate)
    select v_revision_id,r.rate_family,r.rate_code,r.unit_label,
           r.paye_rate,r.umbrella_rate,r.charge_rate
      from private.bpay_next_contract_rate_rows_v1(
        v_contract.rates_json,v_contract.bucket_labels_json,
        v_contract.additional_rates_json,
        coalesce(v_tf.mileage_pay_rate,v_contract.mileage_pay_rate,
                 v_candidate_mileage_rate),
        coalesce(v_tf.mileage_charge_rate,v_contract.mileage_charge_rate,
                 v_client_mileage_rate)) r;
  end if;

  for v_component in select value from pg_catalog.jsonb_array_elements(
    v_inventory->'components') order by (value->>'component_ordinal')::integer
  loop
    v_component_id:=(v_component->>'component_id')::uuid;
    v_component_kind:=v_component->>'component_kind';
    v_component_key:='SOURCE:'||v_component_id::text;
    v_component_amount:=case when (v_component->>'exclude_from_pay')::boolean
      then 0 else (v_component->>'pay_ex_vat')::numeric end;
    v_hours:=coalesce((v_component->>'hours_day')::numeric,0)
      +coalesce((v_component->>'hours_night')::numeric,0)
      +coalesce((v_component->>'hours_sat')::numeric,0)
      +coalesce((v_component->>'hours_sun')::numeric,0)
      +coalesce((v_component->>'hours_bh')::numeric,0);
    if (v_first_snapshot and v_hours<0)
       or v_hours<>pg_catalog.round(v_hours,6) then
      raise exception using errcode='23514', message='BPAY_NEXT_SOURCE_HOURS_INVALID';
    end if;
    v_rate_count:=0;
    if v_component_kind='WORKED_TIME' then
      -- A committed head can contain signed correction hours. Freeze every
      -- non-zero bucket exactly, but never invent a Source hourly rate from
      -- its independently authoritative component amount.
      v_rate_count:=(case when coalesce((v_component->>'hours_day')::numeric,0)<>0 then 1 else 0 end)
        +(case when coalesce((v_component->>'hours_night')::numeric,0)<>0 then 1 else 0 end)
        +(case when coalesce((v_component->>'hours_sat')::numeric,0)<>0 then 1 else 0 end)
        +(case when coalesce((v_component->>'hours_sun')::numeric,0)<>0 then 1 else 0 end)
        +(case when coalesce((v_component->>'hours_bh')::numeric,0)<>0 then 1 else 0 end);
    end if;
    v_line_no:=v_line_no+1;
    insert into private.bpay_next_approved_line
      (revision_id,line_no,component_key,source_component_id,component_kind,tax_treatment,
       work_date,approved_quantity,approved_unit_rate,
       expected_rate_detail_count,source_pay_ex_vat,evidence_ref)
      values(v_revision_id,v_line_no,v_component_key,v_component_id,
        case v_component_kind when 'WORKED_TIME' then 'WORK'
          when 'ADDITIONAL_UNIT' then 'ADDITIONAL' else 'EXPENSE' end,
        case when v_component_kind='WORKED_TIME' then 'TAXABLE' else null end,
        nullif(v_component->>'work_date','')::date,
        case when v_component_kind='WORKED_TIME' then v_hours
          when v_component_kind='ADDITIONAL_UNIT'
            then (v_component->>'unit_count')::numeric else null end,
        case when v_component_kind='ADDITIONAL_UNIT'
          then (v_component->>'unit_pay_rate')::numeric else null end,
        v_rate_count,v_component_amount,
        'source-component:'||v_component_id::text||'#'||
          coalesce(v_component->>'component_sha256','no-hash'))
      returning id into v_line_id;
    if v_component_kind='WORKED_TIME'
       and nullif(v_component->>'work_date','') is not null then
      v_segment:=null; v_segment_match_count:=0;
      if v_first_snapshot then
        select pg_catalog.count(*)::integer,
               pg_catalog.jsonb_agg(segment.value)->0
          into v_segment_match_count,v_segment
          from pg_catalog.jsonb_array_elements(
            case when pg_catalog.jsonb_typeof(v_tf.invoice_breakdown_json->'segments')='array'
              then v_tf.invoice_breakdown_json->'segments' else '[]'::jsonb end)
            segment(value)
          where segment.value->>'segment_id'=v_component->>'segment_id';
      else
        -- A published head stores amount and bucket hours but not accepted
        -- clocks/rates. Only its exact chosen-detail key may add those facts.
        select d.detail_json,d.component_sha256,d.detail_sha256
          into v_segment,v_chosen_component_sha,v_chosen_detail_sha
          from private.bpay_next_source_chosen_detail d
          where d.head_id=p_expected_head_id
            and d.component_id=v_component_id
            and d.decision_bundle_id=v_head_bundle_id
            and d.bundle_revision=v_head_bundle_revision;
        if not found or v_segment is null or (
           v_chosen_component_sha is distinct from
             pg_catalog.decode(v_component->>'component_sha256','hex')
           or v_chosen_detail_sha is distinct from
             pg_catalog.sha256(pg_catalog.convert_to(v_segment::text,'UTF8'))
           or v_segment->>'work_date' is distinct from v_component->>'work_date') then
          raise exception using errcode='23514',
            message='BPAY_NEXT_SOURCE_CHOSEN_DETAIL_MISMATCH';
        end if;
      end if;
      if v_segment_match_count>1 then
        raise exception using errcode='23514',
          message='BPAY_NEXT_SOURCE_SEGMENT_ID_AMBIGUOUS';
      end if;
      v_use_segment:=v_segment is not null
        and coalesce(v_segment->>'date',v_segment->>'work_date')
            =v_component->>'work_date'
        and (not v_first_snapshot or (
        coalesce((v_segment->>'hours_day')::numeric,0)
            =coalesce((v_component->>'hours_day')::numeric,0)
        and coalesce((v_segment->>'hours_night')::numeric,0)
            =coalesce((v_component->>'hours_night')::numeric,0)
        and coalesce((v_segment->>'hours_sat')::numeric,0)
            =coalesce((v_component->>'hours_sat')::numeric,0)
        and coalesce((v_segment->>'hours_sun')::numeric,0)
            =coalesce((v_component->>'hours_sun')::numeric,0)
        and coalesce((v_segment->>'hours_bh')::numeric,0)
            =coalesce((v_component->>'hours_bh')::numeric,0)));
      if v_first_snapshot and not v_use_segment then
        raise exception using errcode='23514',
          message='BPAY_NEXT_SOURCE_FIRST_SEGMENT_EVIDENCE_MISMATCH';
      end if;
      insert into private.bpay_next_shift_detail
        (approved_line_id,detail_no,work_date,shift_start_at,shift_end_at,
         shift_start_local,shift_end_local,shift_overnight,
         approved_hours,
         detail_label,immutable_evidence_ref)
        values(v_line_id,1,(v_component->>'work_date')::date,
          case when v_use_segment then nullif(v_segment->>'start_utc','')::timestamptz end,
          case when v_use_segment then nullif(v_segment->>'end_utc','')::timestamptz end,
          case when v_use_segment then nullif(v_segment->>'start','') end,
          case when v_use_segment then nullif(v_segment->>'end','') end,
          case when v_use_segment then (v_segment->>'overnight')::boolean end,
          v_hours,
          nullif(v_component->>'reference_number',''),
          'source-component:'||v_component_id::text)
        returning id into v_shift_id;
      if v_use_segment then
        if v_segment ? 'breaks'
           and pg_catalog.jsonb_typeof(v_segment->'breaks') not in ('array','null') then
          raise exception using errcode='23514',
            message='BPAY_NEXT_SOURCE_BREAK_SHAPE_INVALID';
        end if;
        v_break_no:=0; v_break_total:=0;
        for v_break in select value from pg_catalog.jsonb_array_elements(
          case when pg_catalog.jsonb_typeof(v_segment->'breaks')='array'
            then v_segment->'breaks' else '[]'::jsonb end)
        loop
          v_break_start:=v_break->>'start';
          v_break_end:=v_break->>'end';
          if pg_catalog.jsonb_typeof(v_break)<>'object'
             or coalesce(v_break_start,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
             or coalesce(v_break_end,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
            raise exception using errcode='23514',
              message='BPAY_NEXT_SOURCE_BREAK_CLOCK_INVALID';
          end if;
          v_break_minutes:=(
            (pg_catalog.substring(v_break_end,1,2)::integer*60
              +pg_catalog.substring(v_break_end,4,2)::integer)
            -(pg_catalog.substring(v_break_start,1,2)::integer*60
              +pg_catalog.substring(v_break_start,4,2)::integer)+1440)%1440;
          if v_break_minutes=0 then
            raise exception using errcode='23514',
              message='BPAY_NEXT_SOURCE_BREAK_ZERO_WINDOW';
          end if;
          v_break_no:=v_break_no+1;
          v_break_total:=v_break_total+v_break_minutes;
          insert into private.bpay_next_break_detail
            (shift_detail_id,break_no,break_start_local,break_end_local,break_minutes)
            values(v_shift_id,v_break_no,v_break_start,v_break_end,v_break_minutes);
        end loop;
        if v_break_no=0
           and coalesce((v_segment->>'break_mins')::integer,
                        (v_segment->>'break_minutes')::integer,0)>0 then
          insert into private.bpay_next_break_detail
            (shift_detail_id,break_no,break_minutes)
            values(v_shift_id,1,coalesce((v_segment->>'break_mins')::integer,
                (v_segment->>'break_minutes')::integer));
        elsif v_break_no>0
           and (v_segment ? 'break_mins' or v_segment ? 'break_minutes')
           and v_break_total is distinct from
               coalesce((v_segment->>'break_mins')::integer,
                        (v_segment->>'break_minutes')::integer) then
          raise exception using errcode='23514',
            message='BPAY_NEXT_SOURCE_BREAK_DURATION_CONFLICT';
        end if;
      end if;
    end if;
    if v_rate_count>0 then
      for v_bucket in select * from (values
        ('DAY'::text,'hours_day'::text,v_tf.pay_day),
        ('NIGHT','hours_night',v_tf.pay_night),
        ('SAT','hours_sat',v_tf.pay_sat),
        ('SUN','hours_sun',v_tf.pay_sun),
        ('BH','hours_bh',v_tf.pay_bh)) b(code,hours_key,pay_rate)
      loop
        if coalesce((v_component->>v_bucket.hours_key)::numeric,0)<>0 then
          -- TSFIN's pay_day/... are explicitly FIRST-SEGMENT display rates.
          -- A Source first authorisation may contain several shifts with
          -- different rates in the same bucket, so use each exact matched
          -- segment's immutable Source pay vector when it exists.
          v_source_rate:=case
            when not v_use_segment then null
            when v_first_snapshot
              and pg_catalog.jsonb_typeof(v_segment->'weekly_source')='object'
              then (v_segment#>>array['weekly_source','pay_vector','rates',
                                    pg_catalog.lower(v_bucket.code)])::numeric
            when v_first_snapshot and v_work_count=1 then v_bucket.pay_rate
            when v_first_snapshot then null
            else (v_segment->'rates'->>pg_catalog.lower(v_bucket.code))::numeric
          end;
           if v_use_segment
              and not (v_source_rate is null and (
                coalesce(v_segment->>'from_frozen_pair','false')='true'
                or (v_first_snapshot
                    and (v_component->>'exclude_from_pay')::boolean)))
             and (v_source_rate is null
             or v_source_rate<>pg_catalog.round(v_source_rate,6)) then
            raise exception using errcode='23514',
              message='BPAY_NEXT_SOURCE_USED_RATE_MISSING';
          end if;
          insert into private.bpay_next_rate_detail
            (approved_line_id,bucket,approved_hours,source_pay_rate)
            values(v_line_id,v_bucket.code,
              (v_component->>v_bucket.hours_key)::numeric,v_source_rate);
        end if;
      end loop;
    end if;
  end loop;
  work_id:=v_work.id;
  revision_id:=v_revision_id;
  source_event_id:=p_source_event_id;
  return next;
end
$function$;

alter function private.bpay_next_stage_source_current_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_stage_source_current_v1(uuid,uuid,uuid)
  from public, anon, authenticated, service_role;



-- Bounded evidence step for the replacement preparation. It copies only the
-- financially relevant CURRENT component positions of SELECTED work, never
-- old revisions or a Candidate-wide payment history. This file captures no
-- hold and confers no executable Draft authority.




create or replace function private.bpay_next_capture_position_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_work_cursor uuid,p_expected_component_cursor text,
  p_limit integer default 100
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_module_epoch bigint;
  v_row record;
  v_member record;
  v_seen integer:=0;
  v_selected_seen integer:=0;
  v_resolution_count integer:=0;
  v_managed_seen integer:=0;
  v_needs_resolution boolean;v_residual numeric;v_zero_managed boolean;
  v_comparison private.bpay_next_source_comparison_receipt%rowtype;
  v_collection private.bpay_next_work_collection%rowtype;
  v_work_cursor uuid;
  v_component_cursor text;
  v_issue text;
  v_issue_work_id uuid;
  v_query_pin private.bpay_next_run_work_query_pin_v2%rowtype;
  v_binding private.bpay_next_source_component_binding_version%rowtype;v_book record;
  v_seed_effect uuid;v_seed_hold uuid;v_seed_holds uuid[];v_seed record;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit not between 1 and 100
     or (p_expected_work_cursor is null and p_expected_component_cursor is not null) then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CAPTURE_POSITION_INPUT_INVALID';
  end if;
  select rc.run_id into strict v_run_id
    from private.bpay_next_job j
    join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.status<>'LEASED'
     or v_job.phase not in ('RESERVE','ALLOCATE')
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CAPTURE_POSITION_LEASE_STALE';
  end if;
  if v_job.phase='ALLOCATE' then
    return pg_catalog.jsonb_build_object('done',true,'phase','ALLOCATE',
      'replay',true,'rows_visited',0);
  end if;
  if v_job.position_work_cursor is distinct from p_expected_work_cursor
     or v_job.position_component_cursor is distinct from p_expected_component_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase','RESERVE',
      'replay',true,'rows_visited',0,
      'work_cursor',v_job.position_work_cursor,
      'component_cursor',v_job.position_component_cursor);
  end if;
  select * into strict v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CAPTURE_POSITION_WORKER_NOT_PREPARING';
  end if;
  v_work_cursor:=v_job.position_work_cursor;
  v_component_cursor:=v_job.position_component_cursor;
  for v_member in
    -- Each lane emits at most one page before the bounded merge. SUBSET is
    -- driven by selected membership, not an EXISTS filter over all positions.
    -- A selected missing position remains a member and is refused below.
    with all_page as materialized (
      select rw.id as run_work_id,rw.work_id,rw.captured_revision_id,
             p.component_key,'ALL'::text as selection_mode
        from private.bpay_next_run_work rw
        join private.bpay_next_work_choice choice
          on choice.run_id=v_run_id and choice.work_id=rw.work_id
         and choice.selection_mode='ALL' and choice.selection_state='SEALED'
         and choice.expected_revision_id=rw.captured_revision_id
        join private.bpay_next_position p
          on p.work_id=rw.work_id
         and p.applied_revision_id=rw.captured_revision_id
        where rw.run_worker_id=v_worker.id
          and not private.bpay_next_source_comparison_retired_approval_v2(
            v_worker.candidate_id,rw.work_id,p.component_key)
          and (v_work_cursor is null or rw.work_id>v_work_cursor
            or (rw.work_id=v_work_cursor and p.component_key>v_component_cursor))
        order by rw.work_id,p.component_key limit p_limit
    ), selected_page as materialized (
      select rw.id as run_work_id,rw.work_id,rw.captured_revision_id,
             member.component_key,'SUBSET'::text as selection_mode
        from private.bpay_next_selected_component member
        join private.bpay_next_run_work rw
          on rw.work_id=member.work_id
         and rw.captured_revision_id=member.expected_revision_id
        join private.bpay_next_work_choice choice
          on choice.run_id=member.run_id and choice.work_id=member.work_id
         and choice.selection_mode='SUBSET' and choice.selection_state='SEALED'
         and choice.expected_revision_id=rw.captured_revision_id
        where member.run_id=v_run_id and rw.run_worker_id=v_worker.id
          and (v_work_cursor is null or member.work_id>v_work_cursor
            or (member.work_id=v_work_cursor and member.component_key>v_component_cursor))
        order by member.work_id,member.component_key limit p_limit
    )
    select * from (
      select * from all_page union all select * from selected_page
    ) page order by work_id,component_key limit p_limit
  loop
    -- The Candidate control is already exclusively held. Lock this exact
    -- selected WORK before its position, matching the reentrant seed order.
    perform 1 from private.bpay_next_work w where w.id=v_member.work_id
      and w.candidate_id=v_worker.candidate_id for update;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_POSITION_WORK_SCOPE_INVALID';end if;
    -- Read and lock the exact position after choosing the bounded member.
    -- Do not FOR SHARE the nullable side of an outer join (PostgreSQL refuses
    -- that), and never turn a missing selected position into an omitted line.
    select v_member.run_work_id as run_work_id,v_member.work_id as work_id,
           v_member.captured_revision_id as captured_revision_id,
           p.component_key,p.applied_revision_id,
           p.approved_source_ex_vat,p.realised_source_ex_vat,
           p.held_source_ex_vat,p.realised_target_ex_vat,
           p.realised_target_vat,p.realised_target_inc_vat,
           p.held_target_ex_vat,p.held_target_vat,
           p.held_target_inc_vat,p.source_basis_channel,
           rev.source_pay_channel,rev.source_kind,rev.source_event_id,
           rev.source_head_id,rev.financial_snapshot_id,
           rev.physical_timesheet_id,rev.physical_timesheet_version,
           w.work_kind,w.candidate_id as origin_candidate_id,
           case when l.id is null and sb.component_state='REMOVED'
             then classification.component_kind else l.component_kind end as component_kind,
           l.id as approved_line_id,coalesce(l.source_component_id,sb.source_component_id) as source_component_id,
           l.source_pay_ex_vat as approved_line_source_ex_vat,
           case when l.id is null and sb.component_state='REMOVED'
             then classification.tax_treatment else l.tax_treatment end as tax_treatment,
           p.source_book_state,p.source_book_revision
      into v_row
      from private.bpay_next_position p
      join private.bpay_next_work_revision rev
        on rev.id=v_member.captured_revision_id and rev.work_id=v_member.work_id
      join private.bpay_next_work w on w.id=rev.work_id
      left join private.bpay_next_approved_line l
        on l.revision_id=v_member.captured_revision_id
       and l.component_key=v_member.component_key
      left join lateral (
        select b.source_component_id,bv.component_state,bv.classification_line_id
        from private.bpay_next_source_component_binding b
        join private.bpay_next_source_component_binding_version bv on bv.id=b.current_binding_version_id
        where b.candidate_id=v_worker.candidate_id and bv.approval_work_id=v_member.work_id
          and bv.approval_revision_id=v_member.captured_revision_id
          and bv.approval_component_key=v_member.component_key and bv.component_state='REMOVED'
      ) sb on l.id is null and w.work_kind='SOURCE'
      left join private.bpay_next_approved_line classification on classification.id=sb.classification_line_id
        and classification.source_component_id=sb.source_component_id
      where p.work_id=v_member.work_id and p.component_key=v_member.component_key
      for update of p;
    v_issue:=null;
    if not found
       or v_row.applied_revision_id is distinct from v_member.captured_revision_id then
      v_issue:='CAPTURE_POSITION_CHANGED';
    elsif v_row.approved_line_id is null
       and v_row.approved_source_ex_vat<>0 then
      v_issue:='POSITION_COMPONENT_EVIDENCE_MISSING';
    elsif v_row.approved_line_id is not null
       and v_row.approved_line_source_ex_vat is distinct from
         v_row.approved_source_ex_vat then
      v_issue:='POSITION_APPROVAL_AMOUNT_MISMATCH';
    end if;
    if v_issue is null and v_member.selection_mode='SUBSET'
       and private.bpay_next_source_comparison_retired_approval_v2(
         v_worker.candidate_id,v_row.work_id,v_row.component_key) then
      v_issue:='SOURCE_COMPONENT_MOVED_RESELECT_CURRENT_WORK';
    end if;
    if v_worker.target_pay_channel='UMBRELLA' and v_issue is null and
       (v_row.source_pay_channel is distinct from 'UMBRELLA'
        or v_row.work_kind not in ('ORDINARY','SOURCE')
        or v_row.component_kind is distinct from 'WORK'
        or v_row.tax_treatment is distinct from 'TAXABLE') then
      v_issue:='UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
    end if;
    if v_issue is not null then
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code=v_issue,
            review_issue_work_id=v_member.work_id
        where id=v_worker.id;
      update private.bpay_next_job
        set status='DONE',phase='DONE',cursor_key=null,
            lease_nonce=null,lease_until_utc=null
        where id=p_job_id;
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code',v_issue,'work_id',v_member.work_id,'replay',false);
    end if;
    -- Typed initial I-1 is the ONLY new no-HEAD binding arm. Initial and
    -- common-HEAD captures require self-canonical same-channel TAXABLE WORK.
    v_binding:=null;v_book:=null;v_comparison:=null;
    v_residual:=v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat;
    if v_row.work_kind='SOURCE' and v_row.source_component_id is not null then
      v_comparison:=private.bpay_next_source_comparison_select_approval_v2(
        v_worker.candidate_id,v_row.source_component_id,v_row.work_id,
        v_row.captured_revision_id,v_row.approved_line_id);
    end if;
    if v_comparison.id is not null then
      select * into strict v_binding from private.bpay_next_source_component_binding_version
        where id=v_comparison.source_binding_version_id;
      if (v_comparison.approved_source_ex_vat,v_comparison.target_pay_channel,
          v_row.source_pay_channel,v_row.component_kind,v_row.tax_treatment)
        is distinct from (v_row.approved_source_ex_vat,v_worker.target_pay_channel,
          v_worker.target_pay_channel,'WORK'::text,'TAXABLE'::text) then
        raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_CAPTURE_APPROVAL_CHANGED';
      end if;
      if v_row.approved_line_id is null and
         (v_binding.component_state<>'REMOVED' or v_comparison.approved_source_ex_vat<>0) then
        raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_REMOVAL_NOT_CERTIFIED';
      end if;
      v_residual:=v_comparison.selected_residual_ex_vat;
    elsif v_row.work_kind='SOURCE' and (v_row.source_head_id is not null
      or (v_row.source_kind='SOURCE' and v_row.source_event_id is not null
        and v_row.financial_snapshot_id is not null)) then
      select v.* into v_binding from private.bpay_next_source_component_binding b
        join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
        where b.canonical_work_id=v_row.work_id and b.canonical_component_key=v_row.component_key
          and v.approval_work_id=v_row.work_id and v.approval_revision_id=v_row.captured_revision_id
          and v.approval_component_key=v_row.component_key
          and ((v_row.source_head_id is not null and v.origin_kind='COMMON_HEAD_RECEIPT_V1'
              and v.head_id=v_row.source_head_id)
            or (v_row.source_head_id is null and v.origin_kind='INITIAL_AUTHORISED_TSFIN_V1'
              and v.initial_root_authorisation_id=v_row.source_event_id
              and v.initial_financial_snapshot_id=v_row.financial_snapshot_id
              and v.initial_root_timesheet_id=v_row.physical_timesheet_id
              and v.initial_root_version=v_row.physical_timesheet_version));
      if v_binding.id is null or v_binding.publication_command_id_2 is not null
         or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
         or v_worker.target_pay_channel is distinct from v_row.source_pay_channel
         or v_row.component_kind is distinct from 'WORK' or v_row.tax_treatment is distinct from 'TAXABLE' then
        v_issue:='SOURCE_BOOK_APPROVAL_UNBOUND';
      else
        if v_row.source_book_state='UNBOUND' then
          -- Capture is already a bounded selected point with real APPLIED/DONE
          -- authority. Adoption never borrows a queued writer's lease here.
          v_seed_effect:=null;v_seed_hold:=null;v_seed_holds:=null;
          if v_row.realised_source_ex_vat>0 then
            select b.original_effect_id into v_seed_effect from private.bpay_next_work_collection b
              where b.work_id=v_row.work_id and b.component_key=v_row.component_key
                and b.candidate_id=v_worker.candidate_id and b.paid_basis_qualified;
          end if;
          if v_row.held_source_ex_vat>0 then
            select pg_catalog.array_agg(h.id order by h.id) into v_seed_holds from (
              select id from private.bpay_next_hold where work_id=v_row.work_id
                and component_key=v_row.component_key and status='ACTIVE' order by id limit 2) h;
            if pg_catalog.cardinality(v_seed_holds) is distinct from 1 then
              raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_ACTIVE_HOLD_WITNESS_AMBIGUOUS';
            end if;
            v_seed_hold:=v_seed_holds[1];
          end if;
          select seed.* into strict v_seed from private.bpay_next_source_disposition_seed_v1(
            v_row.work_id,v_row.component_key,v_row.captured_revision_id,v_seed_effect,v_seed_hold) seed;
          if v_seed.qualification_state is distinct from 'READY' then
            raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_SELECTED_SEED_NOT_READY';
          end if;
          select p.source_book_state,p.source_book_revision into v_row.source_book_state,v_row.source_book_revision
            from private.bpay_next_position p where p.work_id=v_row.work_id and p.component_key=v_row.component_key;
        end if;
        select s.* into strict v_book from private.bpay_next_bound_source_snapshot_v1(
          v_binding.id,v_row.source_book_revision) s;
        if v_book.qualification_state is distinct from 'READY'
           or (v_book.candidate_id,v_book.canonical_work_id,v_book.canonical_component_key,
               v_book.approval_work_id,v_book.approval_revision_id,v_book.approved_line_id,
               v_book.source_channel,v_book.tax_treatment,v_book.approved_source_ex_vat,
               v_book.native_realised_paye,v_book.native_held_paye,v_book.native_realised_umbrella,v_book.native_held_umbrella)
             is distinct from (v_worker.candidate_id,v_row.work_id,v_row.component_key,
               v_row.work_id,v_row.captured_revision_id,v_row.approved_line_id,
               v_row.source_pay_channel,'TAXABLE'::text,v_row.approved_source_ex_vat,
               case when v_row.source_pay_channel='PAYE' then v_row.realised_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='PAYE' then v_row.held_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='UMBRELLA' then v_row.realised_source_ex_vat else 0::numeric end,
               case when v_row.source_pay_channel='UMBRELLA' then v_row.held_source_ex_vat else 0::numeric end) then
          v_issue:='SOURCE_BOOK_APPROVAL_UNBOUND';
        end if;
      end if;
      if v_issue is not null then
        update private.bpay_next_run_worker set status='REVIEW',review_issue_code=v_issue,
          review_issue_work_id=v_row.work_id where id=v_worker.id;
        update private.bpay_next_job set status='DONE',phase='DONE',cursor_key=null,
          lease_nonce=null,lease_until_utc=null where id=p_job_id;
        return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW','issue_code',v_issue,
          'work_id',v_row.work_id,'rows_visited',v_seen,'replay',false);
      end if;
    end if;
    v_collection:=null;
    -- Only the exact typed original ordinary PAYE liability can own a
    -- negative residual. Unknown signed/cross-basis/held shapes still REVIEW.
    if v_comparison.id is not null then
      if v_residual<0 and v_comparison.comparable_paid_ex_vat>v_comparison.approved_source_ex_vat then
        v_collection:=private.bpay_next_source_comparison_collection_origin_v2(
          v_comparison.id,v_worker.candidate_id);
      end if;
    elsif v_worker.target_pay_channel='PAYE' and v_row.source_pay_channel='PAYE'
       and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat<0
       and (v_row.held_source_ex_vat,v_row.held_target_ex_vat,v_row.held_target_vat,v_row.held_target_inc_vat)
         is not distinct from (0::numeric,0::numeric,0::numeric,0::numeric) then
      select b.* into v_collection from private.bpay_next_work_collection b
        where b.work_id=v_row.work_id and b.component_key=v_row.component_key;
      if v_collection.case_id is not null then
        v_collection:=private.bpay_next_work_collection_origin_v1(
          v_collection.case_id,v_collection.case_component_id,v_worker.candidate_id);
      else v_collection:=null;end if;
      if v_collection.id is not null and
         (v_collection.observed_revision_id,v_collection.observed_approved_source_ex_vat,v_collection.observed_realised_source_ex_vat)
           is distinct from (v_row.captured_revision_id,v_row.approved_source_ex_vat,v_row.realised_source_ex_vat) then
        v_collection:=null;
      end if;
    end if;
    if v_comparison.id is not null then
      -- This accepted basis already qualifies signed native history and its
      -- pay-channel translation. H alone never creates a recovery Case.
      v_zero_managed:=v_row.approved_line_id is null and v_binding.component_state='REMOVED'
        and (v_comparison.approved_source_ex_vat,v_comparison.comparable_paid_ex_vat,
             v_comparison.comparable_held_ex_vat,v_residual)=(0::numeric,0::numeric,0::numeric,0::numeric)
        and (v_comparison.case_basis is null or
          ((v_comparison.case_basis->>'J')::numeric=0 and (v_comparison.case_basis->>'P')::numeric=
            (v_comparison.case_basis->>'K')::numeric+(v_comparison.case_basis->>'W')::numeric));
      v_needs_resolution:=v_collection.id is null and (v_residual<0
        or (v_row.approved_line_id is null and not v_zero_managed));
    else
    v_zero_managed:=false;
    v_needs_resolution:=v_collection.id is null and (
       v_row.approved_line_id is null
       or v_row.approved_source_ex_vat<0
       or ((v_row.realised_source_ex_vat<>0
          or v_row.held_source_ex_vat<>0
          or v_row.realised_target_inc_vat<>0
          or v_row.held_target_inc_vat<>0)
         and v_row.source_basis_channel is distinct from v_row.source_pay_channel)
       or v_row.realised_source_ex_vat<0
       or v_row.realised_target_ex_vat<0 or v_row.realised_target_vat<0 or v_row.realised_target_inc_vat<0
       or (v_row.held_source_ex_vat>0 and v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat<=0)
       or (v_row.held_source_ex_vat=0 and v_row.held_target_inc_vat<>0)
       or v_row.approved_source_ex_vat-v_row.realised_source_ex_vat-v_row.held_source_ex_vat<0);
    end if;
    -- Only genuine positive Source WORK consumes the retained disposition.
    -- Expense/additional/ordinary, zero, realised/held-away, managed negative
    -- and already-unresolved financial shapes do not become query holds.
    -- The actual pin validated the typed origin before this immutable row;
    -- missing evidence is REVIEW, never a lazy live Source reader fallback.
    if v_row.work_kind='SOURCE' and v_row.source_kind in ('SOURCE','PROTECTED')
       and v_row.source_event_id is not null
       and v_row.component_kind in ('WORK','PROTECTED_WORK')
       and not v_needs_resolution
       and v_residual>0 then
      select qp.* into v_query_pin from private.bpay_next_run_work_query_pin_v2 qp
        where qp.run_work_id=v_row.run_work_id;
      if found and (v_query_pin.run_worker_id,v_query_pin.candidate_id,
          v_query_pin.work_id,v_query_pin.captured_revision_id,
          v_query_pin.prepare_job_id,v_query_pin.module_epoch,v_query_pin.gate_version)
          is distinct from (v_worker.id,v_worker.candidate_id,
          v_row.work_id,v_row.captured_revision_id,p_job_id,v_module_epoch,'PAY_QUERY_STATE_V3'::text) then
        raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_QUERY_PIN_MISMATCH';
      end if;
      if not found or v_query_pin.disposition='UNAVAILABLE' then
        v_issue:='SOURCE_PAY_QUERY_EVIDENCE_UNAVAILABLE';
      elsif v_query_pin.disposition='BLOCKED' then
        v_issue:='SOURCE_PAY_QUERY_OPEN';
      elsif v_query_pin.disposition<>'CLEAR' or v_query_pin.scope is null
         or v_query_pin.query_state_sha256 is null
         or pg_catalog.octet_length(v_query_pin.query_state_sha256)<>32 then
        raise exception using errcode='23514',message='BPAY_NEXT_CAPTURE_QUERY_PIN_INVALID';
      end if;
      if v_issue is not null then
        update private.bpay_next_run_worker
          set status='REVIEW',review_issue_code=v_issue,review_issue_work_id=v_row.work_id
          where id=v_worker.id;
        update private.bpay_next_job
          set status='DONE',phase='DONE',cursor_key=null,
              lease_nonce=null,lease_until_utc=null
          where id=p_job_id;
        return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
          'issue_code',v_issue,'work_id',v_row.work_id,'rows_visited',v_seen,'replay',false);
      end if;
    end if;
    insert into private.bpay_next_run_position
      (run_worker_id,run_work_id,work_id,captured_revision_id,
       component_key,approved_line_id,source_pay_channel,
       source_basis_channel,
       approved_source_ex_vat,realised_source_ex_vat,held_source_ex_vat,
       residual_source_ex_vat,realised_target_ex_vat,realised_target_vat,
       realised_target_inc_vat,held_target_ex_vat,held_target_vat,
       held_target_inc_vat,needs_financial_resolution,work_collection_id,work_collection_revision,
       source_binding_version_id,canonical_source_work_id,canonical_source_component_key,source_book_revision,
       source_comparison_receipt_id,comparable_paid_ex_vat,comparable_held_ex_vat,selected_residual_ex_vat)
      values(v_worker.id,v_row.run_work_id,v_row.work_id,
       v_row.captured_revision_id,v_row.component_key,v_row.approved_line_id,
       v_row.source_pay_channel,v_row.source_basis_channel,
       v_row.approved_source_ex_vat,
       v_row.realised_source_ex_vat,v_row.held_source_ex_vat,
       v_residual,
       v_row.realised_target_ex_vat,v_row.realised_target_vat,
       v_row.realised_target_inc_vat,v_row.held_target_ex_vat,
       v_row.held_target_vat,v_row.held_target_inc_vat,
       v_needs_resolution,v_collection.id,v_collection.reconcile_revision,
       v_binding.id,v_binding.canonical_work_id,v_binding.canonical_component_key,
       case when v_comparison.id is not null then v_comparison.source_book_revision
         when v_binding.id is null then null else v_row.source_book_revision end,
       v_comparison.id,v_comparison.comparable_paid_ex_vat,v_comparison.comparable_held_ex_vat,
       v_comparison.selected_residual_ex_vat);
    if v_needs_resolution then
      v_resolution_count:=v_resolution_count+1;
    end if;
    if v_collection.id is not null or v_zero_managed then v_managed_seen:=v_managed_seen+1;end if;
    v_work_cursor:=v_row.work_id;
    v_component_cursor:=v_row.component_key;
    v_seen:=v_seen+1;
    if v_member.selection_mode='SUBSET' then
      v_selected_seen:=v_selected_seen+1;
    end if;
  end loop;
  if v_resolution_count>0 then
    update private.bpay_next_run_worker
      set financial_resolution_count=financial_resolution_count+v_resolution_count
      where id=v_worker.id;
  end if;
  if v_seen>0 then
    update private.bpay_next_run_worker
      set captured_position_count=captured_position_count+v_seen,
          expected_managed_position_count=expected_managed_position_count+v_managed_seen,
          captured_selected_component_count=
            captured_selected_component_count+v_selected_seen
      where id=v_worker.id;
  end if;
  if v_seen<p_limit then
    if v_worker.captured_selected_component_count+v_selected_seen
       <>v_worker.expected_selected_component_count then
      select rw.work_id into strict v_issue_work_id
        from private.bpay_next_run_work rw
        join private.bpay_next_work_choice choice
          on choice.run_id=v_run_id and choice.work_id=rw.work_id
         and choice.selection_mode='SUBSET'
        where rw.run_worker_id=v_worker.id
        order by rw.work_id limit 1;
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code='CAPTURE_POSITION_CHANGED',
            review_issue_work_id=v_issue_work_id
        where id=v_worker.id;
      update private.bpay_next_job
        set status='DONE',phase='DONE',cursor_key=null,
            lease_nonce=null,lease_until_utc=null
        where id=p_job_id;
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code','CAPTURE_POSITION_CHANGED','work_id',v_issue_work_id,'replay',false);
    end if;
    update private.bpay_next_job
      set phase='ALLOCATE',position_work_cursor=null,
          position_component_cursor=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','ALLOCATE',
      'rows_visited',v_seen,'replay',false);
  end if;
  update private.bpay_next_job
    set position_work_cursor=v_work_cursor,
        position_component_cursor=v_component_cursor
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','RESERVE',
    'rows_visited',v_seen,'work_cursor',v_work_cursor,
    'component_cursor',v_component_cursor,'replay',false);
end
$function$;

alter function private.bpay_next_capture_position_page_v1(
  uuid,uuid,bigint,uuid,text,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_capture_position_page_v1(
  uuid,uuid,bigint,uuid,text,integer)
  from public,anon,authenticated,service_role;



-- First bounded exact hold step. It preserves a certified-zero advice line
-- without a hold. Same-basis active holds can leave a positive residual;
-- Unknown signed, removed and cross-basis positions require financial review.
-- A captured typed ordinary collection spends a position, not a negative line.
-- This is not a Draft.




create or replace function private.bpay_next_hold_fresh_position_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_work_cursor uuid,p_expected_component_cursor text,
  p_limit integer default 100
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_module_epoch bigint;
  v_issue_work_id uuid;
  v_row record;
  v_position private.bpay_next_position%rowtype;
  v_value record;v_book record;
  v_run_line_id uuid;v_hold_id uuid;
  v_comparison private.bpay_next_source_comparison_receipt%rowtype;
  v_seen integer:=0;
  v_work_cursor uuid;
  v_component_cursor text;
  v_line_count bigint;
  v_managed_count bigint;
  v_total_ex numeric(18,2);
  v_total_vat numeric(18,2);
  v_total_inc numeric(18,2);
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit not between 1 and 100
     or (p_expected_work_cursor is null and p_expected_component_cursor is not null) then
    raise exception using errcode='22023',message='BPAY_NEXT_HOLD_INPUT_INVALID';
  end if;
  select rc.run_id into strict v_run_id
    from private.bpay_next_job j
    join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_module_epoch
    from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_module_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for share;
  select candidate_id into strict v_job.candidate_id
    from private.bpay_next_job where id=p_job_id;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_job.candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED'
     or v_job.job_kind<>'PREPARE' or v_job.status<>'LEASED'
     or v_job.phase not in ('ALLOCATE','FINANCE_ALLOCATE')
     or v_job.module_epoch<>v_module_epoch
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() then
    raise exception using errcode='55000',message='BPAY_NEXT_HOLD_LEASE_STALE';
  end if;
  if v_job.phase='FINANCE_ALLOCATE' then
    return pg_catalog.jsonb_build_object('done',true,
      'phase','FINANCE_ALLOCATE','rows_visited',0,'replay',true);
  end if;
  if v_job.position_work_cursor is distinct from p_expected_work_cursor
     or v_job.position_component_cursor is distinct from p_expected_component_cursor then
    return pg_catalog.jsonb_build_object('done',false,'phase','ALLOCATE',
      'rows_visited',0,'replay',true,
      'work_cursor',v_job.position_work_cursor,
      'component_cursor',v_job.position_component_cursor);
  end if;
  select * into strict v_worker from private.bpay_next_run_worker
    where run_id=v_run_id and candidate_id=v_job.candidate_id for update;
  if v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null then
    raise exception using errcode='55000',
      message='BPAY_NEXT_HOLD_WORKER_NOT_PREPARING';
  end if;
  if v_worker.financial_resolution_count>0 then
    select rp.work_id into strict v_issue_work_id
      from private.bpay_next_run_position rp
      where rp.run_worker_id=v_worker.id and rp.needs_financial_resolution
      order by rp.work_id,rp.component_key limit 1;
    update private.bpay_next_run_worker
      set status='REVIEW',review_issue_code='FINANCIAL_RESOLUTION_REQUIRED',
          review_issue_work_id=v_issue_work_id
      where id=v_worker.id;
    update private.bpay_next_job
      set status='DONE',phase='DONE',cursor_key=null,
          lease_nonce=null,lease_until_utc=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
      'issue_code','FINANCIAL_RESOLUTION_REQUIRED',
      'work_id',v_issue_work_id,'replay',false);
  end if;
  if v_worker.target_pay_channel='UMBRELLA'
     and (v_worker.target_umbrella_id is null
       or v_worker.target_umbrella_vat_chargeable is null) then
    select rp.work_id into v_issue_work_id
      from private.bpay_next_run_position rp
      where rp.run_worker_id=v_worker.id
      order by rp.work_id,rp.component_key limit 1;
    if v_issue_work_id is not null then
      update private.bpay_next_run_worker
        set status='REVIEW',review_issue_code='TARGET_UMBRELLA_MISSING',
            review_issue_work_id=v_issue_work_id
        where id=v_worker.id;
      update private.bpay_next_job
        set status='DONE',phase='DONE',cursor_key=null,
            lease_nonce=null,lease_until_utc=null
        where id=p_job_id;
      return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW',
        'issue_code','TARGET_UMBRELLA_MISSING',
        'work_id',v_issue_work_id,'replay',false);
    end if;
  end if;
  v_work_cursor:=v_job.position_work_cursor;
  v_component_cursor:=v_job.position_component_cursor;
  v_line_count:=v_worker.captured_line_count;
  v_managed_count:=v_worker.captured_managed_position_count;
  v_total_ex:=v_worker.gross_ex_vat;
  v_total_vat:=v_worker.gross_vat;
  v_total_inc:=v_worker.gross_inc_vat;
  for v_row in
    select rp.*,rw.id as pinned_work_id,rev.valuation_policy_id
      from private.bpay_next_run_position rp
      join private.bpay_next_run_work rw on rw.id=rp.run_work_id
      join private.bpay_next_work_revision rev
        on rev.id=rp.captured_revision_id and rev.work_id=rp.work_id
      where rp.run_worker_id=v_worker.id
        and (v_work_cursor is null or rp.work_id>v_work_cursor
          or (rp.work_id=v_work_cursor
            and rp.component_key>v_component_cursor))
      order by rp.work_id,rp.component_key limit p_limit
  loop
    if v_row.needs_financial_resolution
       or (v_row.work_collection_id is null and
         (v_row.residual_source_ex_vat<0 or (v_row.approved_line_id is null and not
           (v_row.source_comparison_receipt_id is not null and
             (v_row.approved_source_ex_vat,v_row.comparable_paid_ex_vat,
              v_row.comparable_held_ex_vat,v_row.residual_source_ex_vat)=(0::numeric,0::numeric,0::numeric,0::numeric))))) then
      raise exception using errcode='23514',
        message='BPAY_NEXT_HOLD_UNEXPECTED_POSITION_SHAPE';
    end if;
    select * into strict v_position from private.bpay_next_position
      where work_id=v_row.work_id and component_key=v_row.component_key
      for update;
    if v_position.applied_revision_id is distinct from v_row.captured_revision_id
       or v_position.approved_source_ex_vat is distinct from
         v_row.approved_source_ex_vat
       or v_position.realised_source_ex_vat is distinct from
         v_row.realised_source_ex_vat
       or v_position.held_source_ex_vat is distinct from
         v_row.held_source_ex_vat
       or v_position.source_basis_channel is distinct from
         v_row.source_basis_channel
       or v_position.realised_target_ex_vat is distinct from
         v_row.realised_target_ex_vat
       or v_position.realised_target_vat is distinct from
         v_row.realised_target_vat
       or v_position.realised_target_inc_vat is distinct from
         v_row.realised_target_inc_vat
       or v_position.held_target_ex_vat is distinct from
         v_row.held_target_ex_vat
       or v_position.held_target_vat is distinct from
         v_row.held_target_vat
       or v_position.held_target_inc_vat is distinct from
         v_row.held_target_inc_vat then
      raise exception using errcode='55000',
        message='BPAY_NEXT_HOLD_CURRENT_POSITION_CHANGED';
    end if;
    v_comparison:=null;
    if v_row.source_comparison_receipt_id is not null then
      v_comparison:=private.bpay_next_source_comparison_current_v2(
        v_row.source_binding_version_id,v_row.source_book_revision,v_row.source_comparison_receipt_id);
      if (v_comparison.id,v_comparison.candidate_id,v_comparison.canonical_work_id,
          v_comparison.canonical_component_key,v_comparison.approval_work_id,
          v_comparison.approval_revision_id,v_comparison.approval_component_key,
          v_comparison.approved_line_id,v_comparison.approved_source_ex_vat,
          v_comparison.comparable_paid_ex_vat,v_comparison.comparable_held_ex_vat,
          v_comparison.selected_residual_ex_vat,v_comparison.target_pay_channel)
        is distinct from (v_row.source_comparison_receipt_id,v_worker.candidate_id,
          v_row.canonical_source_work_id,v_row.canonical_source_component_key,
          v_row.work_id,v_row.captured_revision_id,v_row.component_key,v_row.approved_line_id,
          v_row.approved_source_ex_vat,v_row.comparable_paid_ex_vat,v_row.comparable_held_ex_vat,
          v_row.residual_source_ex_vat,v_worker.target_pay_channel)
        or v_row.source_pay_channel is distinct from v_comparison.target_pay_channel
        or v_row.selected_residual_ex_vat is distinct from v_row.residual_source_ex_vat then
        raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_CAPTURE_CHANGED';
      end if;
    elsif v_row.source_binding_version_id is not null then
      select s.* into strict v_book from private.bpay_next_bound_source_snapshot_v1(
        v_row.source_binding_version_id,v_row.source_book_revision) s;
      if v_book.qualification_state is distinct from 'READY'
         or (v_book.canonical_work_id,v_book.canonical_component_key,v_book.approval_work_id,
             v_book.approval_revision_id,v_book.approved_line_id,v_book.source_channel,v_book.tax_treatment,
             v_book.approved_source_ex_vat,v_book.native_realised_paye,v_book.native_held_paye,
             v_book.native_realised_umbrella,v_book.native_held_umbrella)
           is distinct from (v_row.work_id,v_row.component_key,v_row.work_id,
             v_row.captured_revision_id,v_row.approved_line_id,v_row.source_pay_channel,'TAXABLE'::text,
             v_row.approved_source_ex_vat,
             case when v_row.source_pay_channel='PAYE' then v_row.realised_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='PAYE' then v_row.held_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='UMBRELLA' then v_row.realised_source_ex_vat else 0::numeric end,
             case when v_row.source_pay_channel='UMBRELLA' then v_row.held_source_ex_vat else 0::numeric end)
         or v_row.source_pay_channel not in ('PAYE','UMBRELLA')
         or v_worker.target_pay_channel is distinct from v_row.source_pay_channel
         or v_row.canonical_source_work_id is distinct from v_row.work_id
         or v_row.canonical_source_component_key is distinct from v_row.component_key then
        raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_BOOK_CAPTURE_CHANGED';
      end if;
    end if;
    if v_row.work_collection_id is not null then
      -- Classification and original provenance were frozen by RESERVE. Never
      -- reread a newer WORK approval or create an ordinary negative/zero hold.
      update private.bpay_next_run_position set managed_capture_completed=true
        where id=v_row.id and not managed_capture_completed;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_ALREADY_SPENT';end if;
      v_managed_count:=v_managed_count+1;
    elsif v_row.source_comparison_receipt_id is not null and v_row.approved_line_id is null then
      -- Exact current REMOVED zero was captured with its immutable comparison.
      -- No current approved WORK line exists: do not invent one, a payment or
      -- an old-hours advice line. The existing managed counters conserve it.
      if (v_comparison.approved_source_ex_vat,v_comparison.comparable_paid_ex_vat,
          v_comparison.comparable_held_ex_vat,v_comparison.selected_residual_ex_vat)
        is distinct from (0::numeric,0::numeric,0::numeric,0::numeric)
        or (v_comparison.case_basis is not null and
          ((v_comparison.case_basis->>'J')::numeric<>0 or (v_comparison.case_basis->>'P')::numeric<>
            (v_comparison.case_basis->>'K')::numeric+(v_comparison.case_basis->>'W')::numeric)) then
        raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_ZERO_CAPTURE_INVALID';
      end if;
      update private.bpay_next_run_position set managed_capture_completed=true
        where id=v_row.id and not managed_capture_completed;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_ZERO_CAPTURE_ALREADY_SPENT';end if;
      v_managed_count:=v_managed_count+1;
    else
    select * into strict v_value
      from private.bpay_next_value_source_for_target_v1(
        v_row.residual_source_ex_vat,v_row.source_pay_channel,
        v_worker.target_pay_channel,
        case when v_worker.target_pay_channel='UMBRELLA'
          then v_worker.target_umbrella_vat_chargeable else false end,
        v_row.valuation_policy_id,v_run.pay_date);
    v_line_count:=v_line_count+1;
    insert into private.bpay_next_run_line
      (run_worker_id,run_work_id,line_no,approved_line_id,
       captured_revision_id,work_id,component_key,source_consumed_ex_vat,
       source_pay_channel,target_pay_channel,valuation_policy_id,
       policy_window_id,frozen_ex_vat,frozen_vat,frozen_inc_vat,source_binding_version_id,
       canonical_source_work_id,canonical_source_component_key,source_book_revision,updates_original_source_scalar,
       source_comparison_receipt_id)
      values(v_worker.id,v_row.run_work_id,v_line_count,
       v_row.approved_line_id,v_row.captured_revision_id,v_row.work_id,
       v_row.component_key,v_row.residual_source_ex_vat,
       v_row.source_pay_channel,v_worker.target_pay_channel,
       v_row.valuation_policy_id,v_value.policy_window_id,
       v_value.target_ex_vat,v_value.target_vat,v_value.target_inc_vat,
       v_row.source_binding_version_id,v_row.canonical_source_work_id,v_row.canonical_source_component_key,
       v_row.source_book_revision,case when v_row.source_binding_version_id is null then null
         else (v_row.work_id,v_row.component_key)=(v_row.canonical_source_work_id,v_row.canonical_source_component_key) end,
       v_row.source_comparison_receipt_id)
      returning id into v_run_line_id;
    -- An authorised zero still has immutable shift/rate advice detail. It
    -- becomes a frozen zero line, never a zero-valued financial hold.
    if v_row.residual_source_ex_vat>0 then
      insert into private.bpay_next_hold
        (run_line_id,work_id,component_key,source_reserved_ex_vat,
         target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,status)
        values(v_run_line_id,v_row.work_id,v_row.component_key,
         v_row.residual_source_ex_vat,v_value.target_ex_vat,
         v_value.target_vat,v_value.target_inc_vat,'ACTIVE') returning id into v_hold_id;
      if v_row.source_comparison_receipt_id is not null then
        -- The shared owner proves the real ACTIVE hold, frozen input receipt,
        -- Candidate lease and exact positive rho. It writes native book and
        -- legitimate local hold scalars once. No caller supplies money.
        perform private.bpay_next_source_comparison_carry_v2(p_job_id,
          v_row.source_book_revision,v_row.source_comparison_receipt_id,'RESERVE',v_hold_id);
      else
      update private.bpay_next_position
        set held_source_ex_vat=held_source_ex_vat+v_row.residual_source_ex_vat,
            held_target_ex_vat=held_target_ex_vat+v_value.target_ex_vat,
            held_target_vat=held_target_vat+v_value.target_vat,
            held_target_inc_vat=held_target_inc_vat+v_value.target_inc_vat,
            updated_at_utc=pg_catalog.transaction_timestamp()
        where work_id=v_row.work_id and component_key=v_row.component_key;
      end if;
    end if;
    v_total_ex:=v_total_ex+v_value.target_ex_vat;
    v_total_vat:=v_total_vat+v_value.target_vat;
    v_total_inc:=v_total_inc+v_value.target_inc_vat;
    end if;
    v_work_cursor:=v_row.work_id;
    v_component_cursor:=v_row.component_key;
    v_seen:=v_seen+1;
  end loop;
  if v_seen>0 then
    update private.bpay_next_run_worker
      set captured_line_count=v_line_count,
          captured_managed_position_count=v_managed_count,
          gross_ex_vat=v_total_ex,gross_vat=v_total_vat,
          gross_inc_vat=v_total_inc
      where id=v_worker.id;
    update private.bpay_next_worker_control
      set financial_view_revision=financial_view_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp()
      where candidate_id=v_job.candidate_id;
  end if;
  if v_seen<p_limit then
    if v_managed_count<>v_worker.expected_managed_position_count or exists(
      select 1 from private.bpay_next_run_position where run_worker_id=v_worker.id
        and work_collection_id is not null and not managed_capture_completed) then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_COUNT_MISMATCH';
    end if;
    update private.bpay_next_job
      set phase='FINANCE_ALLOCATE',position_work_cursor=null,
          position_component_cursor=null
      where id=p_job_id;
    return pg_catalog.jsonb_build_object('done',true,
      'phase','FINANCE_ALLOCATE','rows_visited',v_seen,'replay',false);
  end if;
  update private.bpay_next_job
    set position_work_cursor=v_work_cursor,
        position_component_cursor=v_component_cursor
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('done',false,'phase','ALLOCATE',
    'rows_visited',v_seen,'work_cursor',v_work_cursor,
    'component_cursor',v_component_cursor,'replay',false);
end
$function$;

alter function private.bpay_next_hold_fresh_position_page_v1(
  uuid,uuid,bigint,uuid,text,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_hold_fresh_position_page_v1(
  uuid,uuid,bigint,uuid,text,integer)
  from public,anon,authenticated,service_role;



-- Owner-only handoff from a frozen PAYE projection or same-channel TAXABLE
-- Umbrella WORK to a per-Candidate transfer. Bank details bind later.




create or replace function private.bpay_next_begin_simple_transfer_v1(
  p_command_id uuid,p_run_worker_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_sequence bigint;
  v_candidate_id uuid;
  v_case_selection_revision bigint;
begin
  if p_command_id is null or p_run_worker_id is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_TRANSFER_BEGIN_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select run_id,candidate_id,case_selection_revision
    into strict v_run_id,v_candidate_id,v_case_selection_revision from private.bpay_next_run_worker
    where id=p_run_worker_id;
  if v_case_selection_revision>0 then
    return private.bpay_next_begin_case_transfer_v1(p_command_id,p_run_worker_id);
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate_id for update;
  select * into strict v_worker from private.bpay_next_run_worker
    where id=p_run_worker_id for update;
  select * into v_transfer from private.bpay_next_transfer
    where build_command_id=p_command_id;
  if found then
    if v_transfer.run_worker_id<>p_run_worker_id
       or v_transfer.candidate_id<>v_worker.candidate_id then
      raise exception using errcode='23514',
        message='BPAY_NEXT_TRANSFER_BEGIN_REPLAY_CONFLICT';
    end if;
    select agency_sequence into strict v_sequence
      from private.bpay_next_command
      where id=p_command_id and command_kind='TRANSFER_BUILD';
    return pg_catalog.jsonb_build_object('sequence',v_sequence,
      'transfer_id',v_transfer.id,'phase',v_transfer.status,'replay',true);
  end if;
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id and r.status in ('REQUESTED','CANCELLING'))
     or v_worker.status<>'READY'
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or (v_worker.target_pay_channel='PAYE' and
         (v_worker.net_projection_revision<>1 or v_worker.net_request_revision<>1))
     or (v_worker.target_pay_channel='UMBRELLA' and
         (v_worker.net_projection_revision<>0 or v_worker.net_request_revision<>0
          or v_worker.entered_paye_net is not null
          or v_worker.target_umbrella_id is null or v_worker.target_umbrella_vat_chargeable is null
          or v_worker.gross_inc_vat<=0 or v_worker.captured_line_count<1
          or v_worker.financial_resolution_count<>0 or v_worker.expected_managed_position_count<>0
          or exists(select 1 from private.bpay_next_paye_net_request where run_worker_id=v_worker.id)))
     or v_worker.case_selection_revision<>0
     or exists(select 1 from private.bpay_next_transfer t
               where t.run_worker_id=v_worker.id) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_SIMPLE_TRANSFER_NOT_ELIGIBLE';
  end if;
  if v_worker.target_pay_channel='UMBRELLA' then
    -- No payroll NET request/value, CASE adjustment or live financial lookup.
    -- Bounded member pages must certify every included line as same-channel
    -- TAXABLE WORK before the transfer can become issuable.
    insert into private.bpay_next_net_projection
      (run_worker_id,request_command_id,projection_no,input_kind,
       gross_ex_vat,gross_vat,gross_inc_vat,entered_paye_net,accepted_recoveries,cash_amount)
      values(v_worker.id,null,1,'UMBRELLA',v_worker.gross_ex_vat,v_worker.gross_vat,
        v_worker.gross_inc_vat,null,0,v_worker.gross_inc_vat);
    update private.bpay_next_run_worker set net_projection_revision=1 where id=v_worker.id;
  end if;
  select * into strict v_projection from private.bpay_next_net_projection
    where run_worker_id=v_worker.id and projection_no=1;
  if v_worker.target_pay_channel='PAYE' and (v_projection.input_kind<>'PAYE_MANUAL'
     or v_projection.gross_ex_vat<>v_worker.gross_ex_vat
     or v_projection.gross_vat<>0
     or v_projection.gross_inc_vat<>v_worker.gross_inc_vat
     or v_projection.entered_paye_net is distinct from
        v_worker.entered_paye_net
     or v_projection.accepted_recoveries<>0
     or v_projection.cash_amount<0
     or v_projection.cash_amount<>v_worker.entered_paye_net
     or v_projection.request_command_id is null) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SIMPLE_TRANSFER_PROJECTION_INVALID';
  end if;
  if v_worker.target_pay_channel='UMBRELLA' and
     ((v_projection.input_kind,v_projection.gross_ex_vat,v_projection.gross_vat,
       v_projection.gross_inc_vat,v_projection.cash_amount,v_projection.accepted_recoveries,
       v_projection.accepted_gross_additions,v_projection.accepted_gross_deductions,v_projection.accepted_net_additions)
       is distinct from ('UMBRELLA'::text,v_worker.gross_ex_vat,v_worker.gross_vat,
         v_worker.gross_inc_vat,v_worker.gross_inc_vat,0::numeric,0::numeric,0::numeric,0::numeric)
      or v_projection.entered_paye_net is not null or v_projection.request_command_id is not null) then
    raise exception using errcode='23514',message='BPAY_NEXT_SIMPLE_TRANSFER_PROJECTION_INVALID';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(
    p_command_id,'TRANSFER_BUILD');
  insert into private.bpay_next_command_member
    (command_id,candidate_id,member_no)
    values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_transfer
    (run_worker_id,candidate_id,projection_id,build_command_id,
     transfer_no,beneficiary_kind,beneficiary_id,cash_amount,status,execution_kind)
    values(v_worker.id,v_worker.candidate_id,v_projection.id,p_command_id,
      1,case when v_worker.target_pay_channel='UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end,
      case when v_worker.target_pay_channel='UMBRELLA' then v_worker.target_umbrella_id else v_worker.candidate_id end,
      v_projection.cash_amount,'BUILDING',
      case when v_projection.cash_amount=0 then 'INTERNAL_ZERO' else 'BANK' end)
    returning * into v_transfer;
  update private.bpay_next_command
    set expected_member_count=1,status='SEALED',
        sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('sequence',v_sequence,
    'transfer_id',v_transfer.id,'phase','BUILDING','replay',false);
end
$function$;

alter function private.bpay_next_begin_simple_transfer_v1(uuid,uuid)
  OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_begin_simple_transfer_v1(uuid,uuid)
  from public,anon,authenticated,service_role;



-- Owner-only, cursor-bounded Candidate transfer membership. A completed
-- member list still has no approved bank instruction and cannot be issued.




create or replace function private.bpay_next_claim_simple_transfer_job_v1(
  p_job_id uuid,p_lease_seconds integer default 120
) returns table(lease_nonce uuid,owner_epoch bigint)
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_candidate_id uuid;
  v_job private.bpay_next_job%rowtype;
  v_owner_epoch bigint;
  v_nonce uuid;
begin
  if p_job_id is null or p_lease_seconds is null
     or p_lease_seconds not between 1 and 120 then
    raise exception using errcode='22023',
      message='BPAY_NEXT_TRANSFER_LEASE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select candidate_id into strict v_candidate_id from private.bpay_next_job
    where id=p_job_id;
  insert into private.bpay_next_worker_control(candidate_id)
    values(v_candidate_id) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_job.module_epoch<>v_epoch or v_job.job_kind<>'TRANSFER_BUILD'
     or v_job.status not in ('READY','LEASED')
     or (v_job.status='LEASED'
         and v_job.lease_until_utc>pg_catalog.clock_timestamp())
     or exists(select 1 from private.bpay_next_job earlier
               where earlier.candidate_id=v_candidate_id
                 and earlier.command_sequence<v_job.command_sequence
                 and earlier.status<>'DONE') then
    raise exception using errcode='55000',
      message='BPAY_NEXT_TRANSFER_JOB_NOT_CLAIMABLE';
  end if;
  update private.bpay_next_worker_control
    set active_owner_epoch=active_owner_epoch+1,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where candidate_id=v_candidate_id
    returning active_owner_epoch into v_owner_epoch;
  v_nonce:=pg_catalog.gen_random_uuid();
  update private.bpay_next_job
    set status='LEASED',owner_epoch=v_owner_epoch,
        lease_nonce=v_nonce,
        lease_until_utc=pg_catalog.clock_timestamp()+
          pg_catalog.make_interval(secs=>p_lease_seconds),
        attempt_count=attempt_count+1
    where id=p_job_id;
  lease_nonce:=v_nonce; owner_epoch:=v_owner_epoch;
  return next;
end
$function$;

create or replace function private.bpay_next_build_simple_transfer_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint,p_limit integer
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_candidate_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_line record;
  v_seen integer:=0;
  v_member_count bigint;
  v_cash_sum numeric(18,2);
  v_cursor bigint;
  v_adjustment numeric(18,2);
  v_epoch bigint;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit is null or p_limit not between 1 and 100
     or p_expected_cursor is not null and p_expected_cursor<1 then
    raise exception using errcode='22023',
      message='BPAY_NEXT_TRANSFER_PAGE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate_id
    from private.bpay_next_job j
    join private.bpay_next_transfer t on t.build_command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where j.id=p_job_id and j.candidate_id=w.candidate_id;
  if exists(select 1 from private.bpay_next_destination_group b
     join private.bpay_next_transfer t on t.id=b.anchor_transfer_id
     join private.bpay_next_job j on j.command_id=t.build_command_id where j.id=p_job_id) then
    return private.bpay_next_build_destination_group_page_v1(
      p_job_id,p_lease_nonce,p_owner_epoch,p_expected_cursor,p_limit);
  end if;
  if exists(select 1 from private.bpay_next_case_transfer_build b
     join private.bpay_next_transfer t on t.id=b.transfer_id
     join private.bpay_next_job j on j.command_id=t.build_command_id
     where j.id=p_job_id) then
    return private.bpay_next_build_case_transfer_page_v1(
      p_job_id,p_lease_nonce,p_owner_epoch,p_expected_cursor,p_limit);
  end if;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  select * into strict v_transfer from private.bpay_next_transfer
    where build_command_id=v_job.command_id for update;
  select * into strict v_worker from private.bpay_next_run_worker
    where id=v_transfer.run_worker_id for update;
  select * into strict v_projection from private.bpay_next_net_projection
    where id=v_transfer.projection_id;
  if v_job.job_kind<>'TRANSFER_BUILD'
     or v_job.module_epoch<>v_epoch
     or v_job.candidate_id<>v_worker.candidate_id
     or v_transfer.candidate_id<>v_worker.candidate_id
     or not ((v_worker.target_pay_channel='PAYE' and
          v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_id is not null and
          v_transfer.beneficiary_kind='UMBRELLA' and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or v_run.id<>v_worker.run_id
     or v_projection.run_worker_id<>v_worker.id then
    raise exception using errcode='23514',
      message='BPAY_NEXT_TRANSFER_JOB_SCOPE_INVALID';
  end if;
  if v_job.status='DONE' and v_job.phase='MEMBERS_READY'
     and v_transfer.status<>'BUILDING' then
    return pg_catalog.jsonb_build_object('phase','MEMBERS_READY',
      'transfer_status',v_transfer.status,
      'transfer_id',v_transfer.id,'cursor',v_job.cursor_key,
      'member_count',v_transfer.member_count,'replay',true);
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'WORK'
     or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or v_worker.status<>'READY'
     or v_worker.net_projection_revision<>1
     or v_projection.projection_no<>1
     or v_projection.cash_amount<>v_transfer.cash_amount
     or v_transfer.status<>'BUILDING'
     or v_transfer.account_approval_ref is not null
     or v_transfer.original_transfer_id is not null
     or v_transfer.member_count>v_worker.captured_line_count then
    raise exception using errcode='55000',
      message='BPAY_NEXT_TRANSFER_BUILD_NOT_ELIGIBLE';
  end if;
  if v_job.cursor_key is distinct from p_expected_cursor::text then
    return pg_catalog.jsonb_build_object('phase','BUILDING',
      'transfer_id',v_transfer.id,'cursor',v_job.cursor_key,
      'member_count',v_transfer.member_count,'replay',true);
  end if;
  v_member_count:=v_transfer.member_count;
  v_cash_sum:=v_transfer.member_cash_sum;
  v_cursor:=p_expected_cursor;
  for v_line in
    select l.id,l.line_no,l.frozen_inc_vat,l.frozen_ex_vat,l.source_consumed_ex_vat,
      l.source_pay_channel,l.target_pay_channel,l.component_key,l.work_id,
      a.id as qualified_line_id,a.component_kind,a.tax_treatment,
      r.id as qualified_revision_id
    from private.bpay_next_run_line l
    left join private.bpay_next_approved_line a on a.id=l.approved_line_id
      and a.revision_id=l.captured_revision_id and a.component_key=l.component_key
    left join private.bpay_next_work_revision r on r.id=l.captured_revision_id and r.work_id=l.work_id
    where l.run_worker_id=v_worker.id
      and (v_cursor is null or l.line_no>v_cursor)
    order by l.line_no,l.id limit p_limit
  loop
    if v_worker.target_pay_channel='UMBRELLA' and
       (v_projection.input_kind is distinct from 'UMBRELLA'
        or v_worker.case_selection_revision<>0 or v_worker.net_request_revision<>0
        or v_projection.entered_paye_net is not null or v_projection.request_command_id is not null
        or v_projection.cash_amount is distinct from v_worker.gross_inc_vat
        or v_line.qualified_line_id is null or v_line.qualified_revision_id is null
        or v_line.component_kind is distinct from 'WORK' or v_line.tax_treatment is distinct from 'TAXABLE'
        or v_line.source_pay_channel is distinct from 'UMBRELLA'
        or v_line.target_pay_channel is distinct from 'UMBRELLA'
        or v_line.source_consumed_ex_vat<0
        or v_line.frozen_ex_vat is distinct from v_line.source_consumed_ex_vat) then
      raise exception using errcode='55000',message='BPAY_NEXT_UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
    end if;
    v_seen:=v_seen+1;
    v_member_count:=v_member_count+1;
    v_cash_sum:=v_cash_sum+v_line.frozen_inc_vat;
    insert into private.bpay_next_transfer_member
      (transfer_id,run_worker_id,member_no,subject_kind,
       run_line_id,signed_cash_contribution)
      values(v_transfer.id,v_worker.id,v_member_count,'WORK',
             v_line.id,v_line.frozen_inc_vat);
    v_cursor:=v_line.line_no;
  end loop;
  if v_member_count>v_worker.captured_line_count then
    raise exception using errcode='23514',
      message='BPAY_NEXT_TRANSFER_LINE_COUNT_EXCEEDED';
  end if;
  if v_member_count=v_worker.captured_line_count then
    if exists(select 1 from private.bpay_next_run_line l
              where l.run_worker_id=v_worker.id
                and (v_cursor is null or l.line_no>v_cursor))
       or v_cash_sum<>v_worker.gross_inc_vat then
      raise exception using errcode='23514',
        message='BPAY_NEXT_TRANSFER_FROZEN_GROSS_MISMATCH';
    end if;
    if v_worker.target_pay_channel='PAYE' then
      v_adjustment:=v_projection.cash_amount-v_worker.gross_inc_vat;
      insert into private.bpay_next_transfer_member
        (transfer_id,run_worker_id,member_no,subject_kind,
         signed_cash_contribution)
        values(v_transfer.id,v_worker.id,v_member_count+1,
               'NET_ADJUSTMENT',v_adjustment);
      v_member_count:=v_member_count+1;
      v_cash_sum:=v_cash_sum+v_adjustment;
    end if;
    if v_cash_sum<>v_projection.cash_amount then
      raise exception using errcode='23514',
        message='BPAY_NEXT_TRANSFER_CASH_MISMATCH';
    end if;
    update private.bpay_next_transfer
      set member_count=v_member_count,member_cash_sum=v_cash_sum,
          status='MEMBERS_READY'
      where id=v_transfer.id;
    update private.bpay_next_job
      set status='DONE',phase='MEMBERS_READY',
          cursor_key=v_cursor::text,
          lease_nonce=null,lease_until_utc=null
      where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE'
      where id=v_job.command_id;
    return pg_catalog.jsonb_build_object('phase','MEMBERS_READY',
      'transfer_id',v_transfer.id,'cursor',v_cursor,
      'member_count',v_member_count,'rows_visited',v_seen,'replay',false);
  end if;
  if v_seen=0 then
    raise exception using errcode='23514',
      message='BPAY_NEXT_TRANSFER_FROZEN_LINE_MISSING';
  end if;
  update private.bpay_next_transfer
    set member_count=v_member_count,member_cash_sum=v_cash_sum
    where id=v_transfer.id;
  update private.bpay_next_job set cursor_key=v_cursor::text
    where id=p_job_id;
  return pg_catalog.jsonb_build_object('phase','BUILDING',
    'transfer_id',v_transfer.id,'cursor',v_cursor,
    'member_count',v_member_count,'rows_visited',v_seen,'replay',false);
end
$function$;

alter function private.bpay_next_claim_simple_transfer_job_v1(uuid,integer)
  OWNER TO CURRENT_USER;
alter function private.bpay_next_build_simple_transfer_page_v1(
  uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_claim_simple_transfer_job_v1(uuid,integer),
  private.bpay_next_build_simple_transfer_page_v1(
    uuid,uuid,bigint,bigint,integer)
  from public,anon,authenticated,service_role;



-- Owner-only execution preparation for no-CASE PAYE or Umbrella WORK cash.
-- Copies the exact current beneficiary bank details without issuing a file,
-- approving execution or changing frozen money. CSV issue rechecks the
-- Candidate/recorded Umbrella destination against this snapshot.




create or replace function private.bpay_next_bind_simple_csv_destination_v1(
  p_transfer_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_candidate public.candidates%rowtype;
  v_umbrella public.umbrellas%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_name text;
  v_sort text;
  v_account text;
  v_hash text;
  v_replay boolean;
begin
  if p_transfer_id is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CSV_DESTINATION_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id into strict v_run_id
    from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where t.id=p_transfer_id;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=p_transfer_id for update;
  v_leg:=private.bpay_next_destination_execution_leg_v1(p_transfer_id);
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id and r.status in ('REQUESTED','CANCELLING'))
     or (v_worker.status<>'READY' and not (v_worker.status='COMPLETE'
       and v_leg.transfer_id is not null and v_transfer.original_transfer_id is not null))
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or v_transfer.status<>'MEMBERS_READY'
     or v_transfer.candidate_id<>v_worker.candidate_id
     or not ((v_worker.target_pay_channel='PAYE' and
          v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_id is not null and
          v_transfer.beneficiary_kind='UMBRELLA' and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or (v_transfer.projection_id is null and v_transfer.return_cash_id is null)
     or v_transfer.cash_amount<=0
     or v_transfer.member_count<=0
     or v_transfer.member_cash_sum<>v_transfer.cash_amount
     or (not exists(select 1 from private.bpay_next_command c
                   where c.id=v_transfer.build_command_id
                     and c.command_kind in ('TRANSFER_BUILD','CASH_REISSUE')
                     and c.status='COMPLETE')
       and not (v_leg.transfer_id is not null and v_transfer.original_transfer_id is null)) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_DESTINATION_NOT_ELIGIBLE';
  end if;
  select * into strict v_candidate from public.candidates
    where id=v_worker.candidate_id;
  v_name:=nullif(pg_catalog.btrim(v_candidate.account_holder),'');
  v_sort:=pg_catalog.regexp_replace(
    coalesce(v_candidate.sort_code,''),'[^0-9]','','g');
  v_account:=pg_catalog.regexp_replace(
    coalesce(v_candidate.account_number,''),'[^0-9]','','g');
  v_hash:=public._bank_hash(v_candidate.sort_code,
    v_candidate.account_number,v_candidate.account_holder);
  if v_worker.target_pay_channel='UMBRELLA' then
    if v_leg.transfer_id is not null or (v_worker.case_selection_revision<>0
       and not private.bpay_next_umbrella_case_csv_transfer_valid_v2(v_worker,v_transfer))
       or v_candidate.active is not true
       or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>'UMBRELLA'
       or v_candidate.umbrella_id is distinct from v_worker.target_umbrella_id then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
    select * into strict v_umbrella from public.umbrellas where id=v_worker.target_umbrella_id for share;
    v_name:=nullif(pg_catalog.btrim(v_umbrella.name),'');
    v_sort:=pg_catalog.regexp_replace(coalesce(v_umbrella.sort_code,''),'[^0-9]','','g');
    v_account:=pg_catalog.regexp_replace(coalesce(v_umbrella.account_number,''),'[^0-9]','','g');
    v_hash:=public._bank_hash(v_umbrella.sort_code,v_umbrella.account_number,v_umbrella.name);
    if v_umbrella.enabled is not true or v_hash is distinct from v_umbrella.bank_details_hash then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
  end if;
  if v_leg.leg_kind='ONEOFF' then
    select o.* into strict v_origin from private.bpay_next_net_destination_amount d
      join private.bpay_next_stored_credit_origin o on o.command_id=d.first_origin_command_id
      where d.destination_id=v_leg.destination_id;
    v_name:=nullif(pg_catalog.btrim(v_origin.beneficiary_name),'');
    v_sort:=v_origin.sort_code;v_account:=v_origin.account_number;v_hash:=v_origin.bank_details_hash;
  end if;
  if v_candidate.active is not true
     or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>v_worker.target_pay_channel
     or v_name is null
     or v_sort !~ '^[0-9]{6}$'
     or v_account !~ '^[0-9]{8}$'
     or v_hash is null
     or (v_worker.target_pay_channel='PAYE' and
         v_leg.leg_kind is distinct from 'ONEOFF' and v_hash is distinct from v_candidate.bank_details_hash) then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_BANK_DETAILS_NOT_READY';
  end if;
  v_replay:=coalesce(v_transfer.destination_rail='CSV'
    and v_transfer.beneficiary_name_snapshot=v_name
    and v_transfer.sort_code_snapshot=v_sort
    and v_transfer.account_number_snapshot=v_account
    and v_transfer.bank_details_hash_snapshot=v_hash,false);
  if not v_replay then
    update private.bpay_next_transfer
      set destination_rail='CSV',beneficiary_name_snapshot=v_name,
          sort_code_snapshot=v_sort,account_number_snapshot=v_account,
          bank_details_hash_snapshot=v_hash
      where id=p_transfer_id;
  end if;
  return pg_catalog.jsonb_build_object('transfer_id',p_transfer_id,
    'phase','MEMBERS_READY','destination_rail','CSV',
    'bank_hash',v_hash,'replay',v_replay,
    'instruction_issued',false);
end
$function$;

alter function private.bpay_next_bind_simple_csv_destination_v1(uuid)
  OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_bind_simple_csv_destination_v1(uuid)
  from public,anon,authenticated,service_role;



-- Owner-only, single-Candidate CSV issue for the first paid-outcome slice.
-- It does not mark money paid. The exact file bytes are stored before they
-- become available; replay returns those bytes, never a repriced/new file.
-- The backend still must authenticate and reauthorise the Office actor.




create or replace function private.bpay_next_issue_simple_csv_v1(
  p_instruction_id uuid,p_transfer_id uuid,p_actor_user_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_candidate public.candidates%rowtype;
  v_umbrella public.umbrellas%rowtype;
  v_actor public.tms_users%rowtype;
  v_existing private.bpay_next_csv_instruction%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_columns jsonb;
  v_options jsonb;
  v_with_account_type boolean;
  v_name text;
  v_sort text;
  v_account text;
  v_hash text;
  v_reference text;
  v_file_name text;
  v_csv text;
  v_sha text;
begin
  if p_instruction_id is null or p_transfer_id is null
     or p_actor_user_id is null then
    raise exception using errcode='22023',
      message='BPAY_NEXT_CSV_ISSUE_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m
                where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id into strict v_run_id
    from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where t.id=p_transfer_id;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=p_transfer_id for update;
  select * into strict v_actor from public.tms_users
    where id=p_actor_user_id for share;
  if v_actor.is_active is not true
     or (v_actor.payment_authoriser is not true
         and v_actor.payment_golden_key is not true) then
    raise exception using errcode='42501',
      message='BPAY_NEXT_CSV_ACTOR_NOT_AUTHORISED';
  end if;
  select * into v_existing from private.bpay_next_csv_instruction
    where id=p_instruction_id;
  if found then
    if v_existing.transfer_id<>p_transfer_id then
      raise exception using errcode='23514',
        message='BPAY_NEXT_CSV_ISSUE_REPLAY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object(
      'instruction_id',v_existing.id,'transfer_id',p_transfer_id,
      'file_name',v_existing.file_name,'csv_sha256',v_existing.csv_sha256,
      'csv_text',v_existing.csv_text,'replay',true,
      'payment_recorded',exists(select 1 from private.bpay_next_outcome_request r
        where r.transfer_id=p_transfer_id and r.posting_complete));
  end if;
  if exists(select 1 from private.bpay_next_csv_instruction i
            where i.transfer_id=p_transfer_id) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_CSV_TRANSFER_ALREADY_ISSUED';
  end if;
  -- Exact issued receipt readback above precedes current bank safety checks.
  v_leg:=private.bpay_next_destination_execution_leg_v1(p_transfer_id);
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id and r.status in ('REQUESTED','CANCELLING'))
     or (v_worker.status<>'READY' and not (v_worker.status='COMPLETE'
       and v_leg.transfer_id is not null and v_transfer.original_transfer_id is not null))
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or v_transfer.status<>'MEMBERS_READY'
     or v_transfer.candidate_id<>v_worker.candidate_id
     or not ((v_worker.target_pay_channel='PAYE' and
          v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.target_umbrella_id is not null and
          v_transfer.beneficiary_kind='UMBRELLA' and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or v_transfer.destination_rail<>'CSV'
     or v_transfer.account_approval_ref is not null
     or v_transfer.member_count<=0
     or v_transfer.member_cash_sum<>v_transfer.cash_amount
     or v_transfer.cash_amount<=0 then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_ISSUE_NOT_ELIGIBLE';
  end if;
  -- The Candidate row lock makes the actual issue and a simultaneous bank
  -- change resolve in one order. No historical account or Timesheet scan.
  select * into strict v_candidate from public.candidates
    where id=v_worker.candidate_id for share;
  v_name:=nullif(pg_catalog.btrim(v_candidate.account_holder),'');
  v_sort:=pg_catalog.regexp_replace(
    coalesce(v_candidate.sort_code,''),'[^0-9]','','g');
  v_account:=pg_catalog.regexp_replace(
    coalesce(v_candidate.account_number,''),'[^0-9]','','g');
  v_hash:=public._bank_hash(v_candidate.sort_code,
    v_candidate.account_number,v_candidate.account_holder);
  if v_worker.target_pay_channel='UMBRELLA' then
    if v_leg.transfer_id is not null or (v_worker.case_selection_revision<>0
       and not private.bpay_next_umbrella_case_csv_transfer_valid_v2(v_worker,v_transfer))
       or v_candidate.active is not true
       or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>'UMBRELLA'
       or v_candidate.umbrella_id is distinct from v_worker.target_umbrella_id then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
    select * into strict v_umbrella from public.umbrellas where id=v_worker.target_umbrella_id for share;
    v_name:=nullif(pg_catalog.btrim(v_umbrella.name),'');
    v_sort:=pg_catalog.regexp_replace(coalesce(v_umbrella.sort_code,''),'[^0-9]','','g');
    v_account:=pg_catalog.regexp_replace(coalesce(v_umbrella.account_number,''),'[^0-9]','','g');
    v_hash:=public._bank_hash(v_umbrella.sort_code,v_umbrella.account_number,v_umbrella.name);
    if v_umbrella.enabled is not true or v_hash is distinct from v_umbrella.bank_details_hash then
      raise exception using errcode='55000',message='BPAY_NEXT_CSV_UMBRELLA_DESTINATION_NOT_READY';
    end if;
  end if;
  if v_leg.leg_kind='ONEOFF' then
    select o.* into strict v_origin from private.bpay_next_net_destination_amount d
      join private.bpay_next_stored_credit_origin o on o.command_id=d.first_origin_command_id
      where d.destination_id=v_leg.destination_id;
    v_name:=nullif(pg_catalog.btrim(v_origin.beneficiary_name),'');
    v_sort:=v_origin.sort_code;v_account:=v_origin.account_number;v_hash:=v_origin.bank_details_hash;
  end if;
  if v_candidate.active is not true
     or pg_catalog.upper(coalesce(v_candidate.pay_method,''))<>v_worker.target_pay_channel
     or v_name is null
     or pg_catalog.octet_length(v_name)>70
     or position(E'\r' in v_name)>0
     or position(E'\n' in v_name)>0
     or v_sort !~ '^[0-9]{6}$'
     or v_account !~ '^[0-9]{8}$'
     or v_hash is null
     or (v_worker.target_pay_channel='PAYE' and
         v_leg.leg_kind is distinct from 'ONEOFF' and v_hash is distinct from v_candidate.bank_details_hash)
     or v_name is distinct from v_transfer.beneficiary_name_snapshot
     or v_sort is distinct from v_transfer.sort_code_snapshot
     or v_account is distinct from v_transfer.account_number_snapshot
     or v_hash is distinct from v_transfer.bank_details_hash_snapshot then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_DESTINATION_CHANGED_BEFORE_ISSUE';
  end if;
  select sd.pay_export_csv_columns_json,
         coalesce(sd.pay_export_csv_format_json,'{}'::jsonb)
    into strict v_columns,v_options
    from public.settings_defaults sd where sd.id=1;
  if v_options<>'{}'::jsonb then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_CONFIGURED_FORMAT_NOT_YET_SUPPORTED';
  end if;
  v_with_account_type:=coalesce(v_columns=
    '["payment_reference","payee_name","sort_code","account_number","account_type","amount"]'::jsonb,false);
  if not v_with_account_type and v_columns is distinct from
      '["payment_reference","payee_name","sort_code","account_number","amount"]'::jsonb then
    raise exception using errcode='55000',
      message='BPAY_NEXT_CSV_CONFIGURED_COLUMNS_NOT_YET_SUPPORTED';
  end if;
  v_reference:='BP'||substring(
    pg_catalog.replace(p_transfer_id::text,'-','') from 1 for 18);
  v_file_name:='bpay-next-'||p_instruction_id::text||'.csv';
  v_csv:='Payment reference,Payee name,Sort code,Bank account number,';
  if v_with_account_type then
    v_csv:=v_csv||'Bank account type,';
  end if;
  v_csv:=v_csv||'Amount'||E'\n'||v_reference||',"'||
    pg_catalog.replace(v_name,'"','""')||'",'||v_sort||','||v_account||',';
  if v_with_account_type then
    v_csv:=v_csv||',';
  end if;
  v_csv:=v_csv||pg_catalog.to_char(v_transfer.cash_amount,
    'FM9999999999999990.00')||E'\n';
  v_sha:=pg_catalog.encode(pg_catalog.sha256(
    pg_catalog.convert_to(v_csv,'UTF8')),'hex');
  insert into private.bpay_next_csv_instruction
    (id,transfer_id,run_worker_id,actor_user_id,payment_reference,
     bank_details_hash_snapshot,cash_amount,file_name,csv_text,csv_sha256)
    values(p_instruction_id,p_transfer_id,v_worker.id,p_actor_user_id,
      v_reference,v_hash,v_transfer.cash_amount,v_file_name,v_csv,v_sha);
  update private.bpay_next_transfer
    set account_approval_ref='CSV_INSTRUCTION:'||p_instruction_id::text,
        status='ISSUED_CSV'
    where id=p_transfer_id;
  return pg_catalog.jsonb_build_object(
    'instruction_id',p_instruction_id,'transfer_id',p_transfer_id,
    'file_name',v_file_name,'csv_sha256',v_sha,'csv_text',v_csv,
    'replay',false,'payment_recorded',false);
end
$function$;

alter function private.bpay_next_issue_simple_csv_v1(uuid,uuid,uuid)
  OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_issue_simple_csv_v1(uuid,uuid,uuid)
  from public,anon,authenticated,service_role;



-- Owner-only, first confirmed external CSV settlement. No provider call.
-- Receipt persists before bounded posting, using the existing command order.



create or replace function private.bpay_next_receive_simple_csv_settlement_v1(
  p_command_id uuid,p_transfer_id uuid,p_receipt_id text,
  p_amount numeric,p_occurred_at timestamptz,p_actor_user_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_candidate_id uuid;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_actor public.tms_users%rowtype;
  v_receipt private.bpay_next_transfer_outcome%rowtype;
  v_request private.bpay_next_outcome_request%rowtype;
  v_sequence bigint;
begin
  if p_command_id is null or p_transfer_id is null or p_receipt_id is null
     or pg_catalog.octet_length(p_receipt_id) not between 1 and 256
     or p_amount is null or p_amount<=0
     or p_amount<>pg_catalog.round(p_amount,2)
     or p_occurred_at is null or not pg_catalog.isfinite(p_occurred_at)
     or p_actor_user_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_SETTLEMENT_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control
                where id=1 and active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate_id
    from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id
    where t.id=p_transfer_id;
  perform 1 from private.bpay_next_pay_run where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=p_transfer_id for update;
  select * into strict v_actor from public.tms_users
    where id=p_actor_user_id for share;
  if v_actor.is_active is not true
     or (v_actor.payment_authoriser is not true
         and v_actor.payment_golden_key is not true) then
    raise exception using errcode='42501',message='BPAY_NEXT_SETTLEMENT_ACTOR_NOT_AUTHORISED';
  end if;
  select * into v_receipt from private.bpay_next_transfer_outcome
    where receipt_id=p_receipt_id;
  if found then
    if v_receipt.transfer_id<>p_transfer_id or v_receipt.outcome_kind<>'SETTLED'
       or v_receipt.whole_transfer_amount<>p_amount
       or v_receipt.occurred_at_utc<>p_occurred_at then
      raise exception using errcode='23514',message='BPAY_NEXT_SETTLEMENT_RECEIPT_CONFLICT';
    end if;
    select * into strict v_request from private.bpay_next_outcome_request
      where outcome_id=v_receipt.id;
    return pg_catalog.jsonb_build_object('command_id',v_request.command_id,
      'outcome_id',v_receipt.id,'replay',true,
      'posting_complete',v_request.posting_complete);
  end if;
  if exists(select 1 from private.bpay_next_outcome_request
            where command_id=p_command_id or transfer_id=p_transfer_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_SETTLEMENT_COMMAND_CONFLICT';
  end if;
  if v_transfer.status not in ('ISSUED_CSV','UNKNOWN')
     or v_transfer.destination_rail<>'CSV'
     or v_transfer.cash_amount<>p_amount
     or not exists(select 1 from private.bpay_next_csv_instruction i
                   where i.transfer_id=p_transfer_id and i.cash_amount=p_amount)
     or not (v_worker.target_pay_channel='PAYE' or
       (v_worker.target_pay_channel='UMBRELLA'
        and v_worker.target_umbrella_id is not null
        and v_transfer.beneficiary_kind='UMBRELLA'
        and v_transfer.beneficiary_id=v_worker.target_umbrella_id
        and exists(select 1 from private.bpay_next_net_projection p
          where p.id=coalesce(v_transfer.projection_id,
            (select projection_id from private.bpay_next_transfer where id=v_transfer.original_transfer_id))
            and p.run_worker_id=v_worker.id and p.input_kind='UMBRELLA'
            and p.entered_paye_net is null and p.request_command_id is null
            and ((v_worker.case_selection_revision=0 and p.umbrella_case_draft_state_id is null
                and p.cash_amount=v_worker.gross_inc_vat)
              or (v_worker.case_selection_revision>0 and private.bpay_next_umbrella_case_projection_valid_v2(v_worker,p)
                and exists(select 1 from private.bpay_next_case_transfer_build b
                  where b.transfer_id=coalesce(v_transfer.original_transfer_id,v_transfer.id)
                    and b.run_worker_id=v_worker.id and b.projection_id=p.id and b.target_pay_channel='UMBRELLA'
                    and b.stage='COMPLETE')))))) then
    raise exception using errcode='55000',message='BPAY_NEXT_SETTLEMENT_NOT_ELIGIBLE';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'CSV_SETTLEMENT');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no)
    values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_transfer_outcome
    (transfer_id,receipt_id,outcome_kind,whole_transfer_amount,occurred_at_utc)
    values(p_transfer_id,p_receipt_id,'SETTLED',p_amount,p_occurred_at)
    returning * into v_receipt;
  insert into private.bpay_next_outcome_request
    (command_id,outcome_id,transfer_id,run_worker_id,candidate_id,actor_user_id)
    values(p_command_id,v_receipt.id,p_transfer_id,v_worker.id,
      v_worker.candidate_id,p_actor_user_id);
  update private.bpay_next_transfer set status='SETTLED' where id=p_transfer_id;
  update private.bpay_next_command
    set expected_member_count=1,status='SEALED',sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('command_id',p_command_id,
    'outcome_id',v_receipt.id,'sequence',v_sequence,'replay',false,'posting_complete',false);
end
$function$;

create or replace function private.bpay_next_claim_simple_outcome_job_v1(
  p_job_id uuid,p_lease_seconds integer default 120
) returns table(lease_nonce uuid,owner_epoch bigint)
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_candidate uuid;
  v_job private.bpay_next_job%rowtype;
  v_nonce uuid;
  v_owner bigint;
begin
  if p_job_id is null or p_lease_seconds is null or p_lease_seconds not between 1 and 120 then
    raise exception using errcode='22023',message='BPAY_NEXT_OUTCOME_LEASE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select j.candidate_id into strict v_candidate from private.bpay_next_job j
    where j.id=p_job_id;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  if v_job.module_epoch<>v_epoch or v_job.job_kind not in ('CSV_SETTLEMENT','CSV_RETURN','CASH_REISSUE','INTERNAL_SETTLEMENT')
     or v_job.status not in ('READY','LEASED')
     or (v_job.status='LEASED' and v_job.lease_until_utc>pg_catalog.clock_timestamp())
     or exists(select 1 from private.bpay_next_job j
               where j.candidate_id=v_candidate and j.command_sequence<v_job.command_sequence
                 and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_OUTCOME_JOB_NOT_CLAIMABLE';
  end if;
  update private.bpay_next_worker_control
    set active_owner_epoch=active_owner_epoch+1
    where candidate_id=v_candidate returning active_owner_epoch into v_owner;
  v_nonce:=pg_catalog.gen_random_uuid();
  update private.bpay_next_job set status='LEASED',owner_epoch=v_owner,
    lease_nonce=v_nonce,lease_until_utc=pg_catalog.clock_timestamp()+
      pg_catalog.make_interval(secs=>p_lease_seconds),attempt_count=attempt_count+1
    where id=p_job_id;
  lease_nonce:=v_nonce; owner_epoch:=v_owner; return next;
end
$function$;

create or replace function private.bpay_next_post_simple_outcome_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint,p_limit integer
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_run uuid;
  v_candidate uuid;
  v_job private.bpay_next_job%rowtype;
  v_request private.bpay_next_outcome_request%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_line private.bpay_next_run_line%rowtype;
  v_hold private.bpay_next_hold%rowtype;
  v_member record;
  v_cursor bigint;
  v_count bigint;
  v_seen integer:=0;
  v_original uuid;
  v_effect uuid;v_seed_effect uuid;
  v_return_cash private.bpay_next_return_cash%rowtype;
  v_internal private.bpay_next_internal_receipt%rowtype;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_limit is null or p_limit not between 1 and 100
     or p_expected_cursor is not null and p_expected_cursor<1 then
    raise exception using errcode='22023',message='BPAY_NEXT_OUTCOME_PAGE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,j.candidate_id into strict v_run,v_candidate
    from private.bpay_next_job j
    join private.bpay_next_outcome_request r on r.command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=r.run_worker_id
    where j.id=p_job_id and r.candidate_id=j.candidate_id;
  perform 1 from private.bpay_next_pay_run where id=v_run for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_outcome_request
    where command_id=v_job.command_id for update;
  perform 1 from private.bpay_next_run_worker where id=v_request.run_worker_id for update;
  select * into strict v_transfer from private.bpay_next_transfer
    where id=v_request.transfer_id for update;
  if exists(select 1 from private.bpay_next_run_worker w
            where w.id=v_request.run_worker_id and w.status in ('CANCELLING','CANCELLED')) then
    raise exception using errcode='55000',message='BPAY_NEXT_OUTCOME_CANCELLED_GROUP';
  end if;
  if v_job.job_kind not in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') or v_job.module_epoch<>v_epoch
     or v_transfer.candidate_id<>v_candidate
     or v_transfer.run_worker_id<>v_request.run_worker_id then
    raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_SCOPE_INVALID';
  end if;
  if v_job.job_kind='INTERNAL_SETTLEMENT' then
    select * into strict v_internal from private.bpay_next_internal_receipt where id=v_request.internal_receipt_id;
    if v_request.outcome_id is not null or v_internal.command_id<>v_job.command_id
       or v_internal.transfer_id<>v_transfer.id or v_internal.run_worker_id<>v_request.run_worker_id
       or v_internal.candidate_id<>v_candidate or v_internal.projection_id<>v_transfer.projection_id
       or v_transfer.execution_kind<>'INTERNAL_ZERO' or v_transfer.cash_amount<>0
       or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_OUTCOME_SCOPE_INVALID';
    end if;
  elsif v_transfer.execution_kind<>'BANK' or v_request.outcome_id is null or v_request.internal_receipt_id is not null then
    raise exception using errcode='23514',message='BPAY_NEXT_BANK_OUTCOME_SCOPE_INVALID';
  end if;
  if v_job.status='DONE' and v_request.posting_complete then
    return pg_catalog.jsonb_build_object('done',true,'replay',true,
      'posted_members',v_request.posted_member_count);
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'MEMBERS'
     or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or (v_job.job_kind='CSV_SETTLEMENT' and v_transfer.status not in ('SETTLED','RETURNED'))
     or (v_job.job_kind='INTERNAL_SETTLEMENT' and v_transfer.status<>'INTERNAL_PROCESSING')
     or (v_job.job_kind='INTERNAL_SETTLEMENT' and not exists(select 1 from private.bpay_next_worker_control
       where candidate_id=v_candidate and active_owner_epoch=p_owner_epoch))
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate
               and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_OUTCOME_POST_NOT_ELIGIBLE';
  end if;
  if v_job.cursor_key is distinct from p_expected_cursor::text then
    return pg_catalog.jsonb_build_object('done',false,'replay',true,
      'cursor',v_job.cursor_key,'posted_members',v_request.posted_member_count);
  end if;
  v_cursor:=p_expected_cursor; v_count:=v_request.posted_member_count;
  if v_transfer.return_cash_id is not null then
    select * into strict v_return_cash from private.bpay_next_return_cash
      where id=v_transfer.return_cash_id for update;
    if v_transfer.member_count<>1 or v_return_cash.candidate_id<>v_candidate
       or v_return_cash.original_transfer_id<>v_transfer.original_transfer_id
       or v_return_cash.amount_held<v_transfer.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_CASH_HOLD_MISMATCH';
    end if;
  end if;
  for v_member in select * from private.bpay_next_transfer_member
    where transfer_id=v_transfer.id and (v_cursor is null or member_no>v_cursor)
    order by member_no limit p_limit
  loop
    if v_member.subject_kind='CASH_REISSUE' then
      if v_transfer.return_cash_id is null
         or v_member.signed_cash_contribution<>v_transfer.cash_amount then
        raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_MEMBER_MISMATCH';
      end if;
      update private.bpay_next_return_cash
        set amount_held=amount_held-v_transfer.cash_amount,
            amount_reissued_paid=amount_reissued_paid+v_transfer.cash_amount
        where id=v_return_cash.id;
    elsif v_transfer.return_cash_id is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_PAYROLL_MEMBER_FORBIDDEN';
    elsif v_member.subject_kind='WORK' then
      select * into strict v_line from private.bpay_next_run_line where id=v_member.run_line_id;
      if v_line.run_worker_id<>v_request.run_worker_id
         or v_line.target_pay_channel not in ('PAYE','UMBRELLA')
         or v_line.frozen_inc_vat<>v_member.signed_cash_contribution then
        raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_FROZEN_MEMBER_MISMATCH';
      end if;
      if v_line.target_pay_channel='UMBRELLA' and
         (v_line.source_pay_channel is distinct from 'UMBRELLA'
          or v_line.frozen_ex_vat is distinct from v_line.source_consumed_ex_vat
          or not exists(select 1 from private.bpay_next_approved_line a
            where a.id=v_line.approved_line_id and a.revision_id=v_line.captured_revision_id
              and a.component_key=v_line.component_key and a.component_kind='WORK' and a.tax_treatment='TAXABLE')) then
        raise exception using errcode='55000',message='BPAY_NEXT_UMBRELLA_WORK_EXECUTION_UNSUPPORTED';
      end if;
      if v_line.source_consumed_ex_vat>0 then
        select * into strict v_hold from private.bpay_next_hold where run_line_id=v_line.id for update;
        if v_hold.status<>'ACTIVE' or v_hold.work_id<>v_line.work_id
           or v_hold.component_key<>v_line.component_key
           or v_hold.source_reserved_ex_vat<>v_line.source_consumed_ex_vat
           or v_hold.target_amount_ex_vat<>v_line.frozen_ex_vat
           or v_hold.target_amount_vat<>v_line.frozen_vat
           or v_hold.target_amount_inc_vat<>v_line.frozen_inc_vat then
          raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_HOLD_MISMATCH';
        end if;
        -- A retained unbound frozen child may settle after common-HEAD adoption.
        -- Seed from the real ACTIVE hold/current APPLIED position only; never
        -- require its old capture to point at a newly-created binding version.
        if exists(select 1 from private.bpay_next_position p
          join private.bpay_next_source_component_binding b on b.canonical_work_id=p.work_id
            and b.canonical_component_key=p.component_key
          join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
          where p.work_id=v_line.work_id and p.component_key=v_line.component_key
            and p.source_book_state='UNBOUND' and v.approval_work_id=p.work_id
            and v.approval_revision_id=p.applied_revision_id and v.publication_command_id_2 is null
            and v.approval_source_channel=v_line.source_pay_channel
            and v.approval_source_channel in ('PAYE','UMBRELLA') and v.tax_treatment='TAXABLE') then
          select b.original_effect_id into v_seed_effect from private.bpay_next_work_collection b
            join private.bpay_next_position p on p.work_id=b.work_id and p.component_key=b.component_key
            where b.work_id=v_line.work_id and b.component_key=v_line.component_key and p.realised_source_ex_vat>0;
          perform * from private.bpay_next_source_disposition_seed_v1(v_line.work_id,v_line.component_key,
            (select applied_revision_id from private.bpay_next_position where work_id=v_line.work_id
              and component_key=v_line.component_key),v_seed_effect,v_hold.id);
        end if;
        select original_timesheet_id into strict v_original from private.bpay_next_work where id=v_line.work_id;
        insert into private.bpay_next_financial_effect
          (operation_id,operation_item_id,effect_kind,candidate_id,work_id,component_key,
           original_timesheet_id,original_transfer_id,source_disposition_ex_vat,
           target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,source_run_line_id,
           source_binding_version_id,canonical_source_work_id,canonical_source_component_key,native_source_channel)
          values(v_job.command_id,v_hold.id,'PAYROLL_SETTLED',v_candidate,
            v_line.work_id,v_line.component_key,v_original,v_transfer.id,
            v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,
            v_hold.target_amount_vat,v_hold.target_amount_inc_vat,
            case when v_line.source_binding_version_id is null then null else v_line.id end,
            v_line.source_binding_version_id,v_line.canonical_source_work_id,v_line.canonical_source_component_key,
            case when v_line.source_binding_version_id is null then null else v_line.source_pay_channel end)
          returning id into v_effect;
        update private.bpay_next_run_worker
          set realised_effect_count=realised_effect_count+1
          where id=v_request.run_worker_id;
        update private.bpay_next_hold set status='REALISED',finished_at_utc=pg_catalog.transaction_timestamp()
          where id=v_hold.id;
        if not private.bpay_next_source_comparison_carry_known_work_v2(
          p_job_id,v_line.id,'SETTLE',v_effect) then
          update private.bpay_next_position
            set held_source_ex_vat=held_source_ex_vat-v_hold.source_reserved_ex_vat,
                held_target_ex_vat=held_target_ex_vat-v_hold.target_amount_ex_vat,
                held_target_vat=held_target_vat-v_hold.target_amount_vat,
                held_target_inc_vat=held_target_inc_vat-v_hold.target_amount_inc_vat,
                realised_source_ex_vat=realised_source_ex_vat+v_hold.source_reserved_ex_vat,
                realised_target_ex_vat=realised_target_ex_vat+v_hold.target_amount_ex_vat,
                realised_target_vat=realised_target_vat+v_hold.target_amount_vat,
                realised_target_inc_vat=realised_target_inc_vat+v_hold.target_amount_inc_vat,
                updated_at_utc=pg_catalog.transaction_timestamp()
            where work_id=v_line.work_id and component_key=v_line.component_key
              and source_basis_channel=v_line.source_pay_channel
              and held_source_ex_vat>=v_hold.source_reserved_ex_vat;
          if not found then
            raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_POSITION_MISMATCH';
          end if;
        end if;
                perform private.bpay_next_reconcile_work_collection_v1(
          p_job_id,v_line.work_id,v_line.component_key,v_effect);
      end if;
    elsif v_member.subject_kind='CASE' then
      perform private.bpay_next_post_case_transfer_member_v1(p_job_id,v_transfer.id,v_member.member_no);
    elsif v_member.subject_kind<>'NET_ADJUSTMENT' then
      raise exception using errcode='55000',message='BPAY_NEXT_SIMPLE_OUTCOME_CASE_NOT_SUPPORTED';
    end if;
    v_cursor:=v_member.member_no; v_count:=v_count+1; v_seen:=v_seen+1;
  end loop;
  if v_seen=0 or v_count>v_transfer.member_count then
    raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_MEMBER_COUNT_INVALID';
  end if;
  update private.bpay_next_outcome_request
    set posted_member_count=v_count,posting_complete=(v_count=v_transfer.member_count)
    where command_id=v_job.command_id;
  update private.bpay_next_worker_control
    set financial_view_revision=financial_view_revision+1,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where candidate_id=v_candidate;
  if v_count=v_transfer.member_count then
    if exists(select 1 from private.bpay_next_transfer_member
              where transfer_id=v_transfer.id and member_no>v_cursor) then
      raise exception using errcode='23514',message='BPAY_NEXT_OUTCOME_EXTRA_MEMBER';
    end if;
    if v_job.job_kind='INTERNAL_SETTLEMENT' then
      perform private.bpay_next_complete_internal_zero_v1(p_job_id,v_cursor);
    else
      perform private.bpay_next_apply_week_outcome_v1(p_job_id,null);
    end if;
    perform private.bpay_next_complete_destination_leg_v1(p_job_id);
    update private.bpay_next_job set status='DONE',phase='COMPLETE',cursor_key=v_cursor::text,
      lease_nonce=null,lease_until_utc=null where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
  else
    update private.bpay_next_job set cursor_key=v_cursor::text where id=p_job_id;
  end if;
  return pg_catalog.jsonb_build_object('done',v_count=v_transfer.member_count,
    'replay',false,'cursor',v_cursor,'posted_members',v_count,'rows_visited',v_seen);
end
$function$;

drop trigger if exists bpay_next_outcome_immutable_v1 on private.bpay_next_transfer_outcome;
create trigger bpay_next_outcome_immutable_v1 before update or delete
on private.bpay_next_transfer_outcome for each row
execute function private.bpay_next_effect_immutable_v1();
