alter function private.bpay_next_claim_simple_outcome_job_v1(uuid,integer) OWNER TO CURRENT_USER;
alter function private.bpay_next_post_simple_outcome_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_receive_simple_csv_settlement_v1(uuid,uuid,text,numeric,timestamptz,uuid),
private.bpay_next_claim_simple_outcome_job_v1(uuid,integer),
private.bpay_next_post_simple_outcome_page_v1(uuid,uuid,bigint,bigint,integer)
from public,anon,authenticated,service_role;


-- Owner-only, one Candidate's exact PAYE or Umbrella returned-cash obligation.
-- No revaluation, new payroll, deduction, history scan or network action.


create or replace function private.bpay_next_receive_simple_reissue_v1(
  p_command_id uuid,p_return_cash_id uuid,p_actor_user_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run uuid;
  v_original private.bpay_next_transfer%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_actor public.tms_users%rowtype;
  v_request private.bpay_next_reissue_request%rowtype;
  v_cash private.bpay_next_return_cash%rowtype;
  v_sequence bigint;
begin
  if p_command_id is null or p_return_cash_id is null or p_actor_user_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_REISSUE_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id into strict v_run from private.bpay_next_return_cash c
    join private.bpay_next_transfer t on t.id=c.original_transfer_id
    join private.bpay_next_run_worker w on w.id=t.run_worker_id where c.id=p_return_cash_id;
  perform 1 from private.bpay_next_pay_run where id=v_run for update;
  select t.* into strict v_original from private.bpay_next_return_cash c
    join private.bpay_next_transfer t on t.id=c.original_transfer_id where c.id=p_return_cash_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_original.run_worker_id for update;
  select * into strict v_actor from public.tms_users where id=p_actor_user_id for share;
  if v_actor.is_active is not true or
     (v_actor.payment_authoriser is not true and v_actor.payment_golden_key is not true) then
    raise exception using errcode='42501',message='BPAY_NEXT_REISSUE_ACTOR_NOT_AUTHORISED';
  end if;
  select * into v_request from private.bpay_next_reissue_request where command_id=p_command_id;
  if found then
    if v_request.return_cash_id<>p_return_cash_id then
      raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_REPLAY_CONFLICT';
    end if;
    return pg_catalog.jsonb_build_object('command_id',p_command_id,'transfer_id',v_request.transfer_id,'replay',true);
  end if;
  if v_original.status<>'RETURNED'
     or not ((v_original.beneficiary_kind='CANDIDATE' and v_original.beneficiary_id=v_original.candidate_id)
       or (v_worker.target_pay_channel='UMBRELLA' and v_worker.case_selection_revision=0
         and v_worker.target_umbrella_id is not null and v_original.beneficiary_kind='UMBRELLA'
         and v_original.beneficiary_id=v_worker.target_umbrella_id))
     or not exists(select 1 from private.bpay_next_return_request r
                   where r.transfer_id=v_original.id and r.posting_complete) then
    raise exception using errcode='55000',message='BPAY_NEXT_REISSUE_RETURN_NOT_COMPLETE';
  end if;
  -- Reject duplicate NEW requests before receiving a command. Otherwise an
  -- unfulfillable earlier job could block the actual settlement/return.
  -- Run lock serialises all supported cash writers; the pending index also
  -- prevents two accepted requests before either one builds its transfer.
  select * into strict v_cash from private.bpay_next_return_cash where id=p_return_cash_id for update;
  if v_cash.amount_owed-v_cash.amount_held-v_cash.amount_reissued_paid<=0
     or exists(select 1 from private.bpay_next_reissue_request
               where return_cash_id=p_return_cash_id and transfer_id is null) then
    raise exception using errcode='55000',message='BPAY_NEXT_REISSUE_ALREADY_REQUESTED_OR_RESERVED';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'CASH_REISSUE');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no)
    values(p_command_id,v_original.candidate_id,1);
  insert into private.bpay_next_reissue_request(command_id,return_cash_id,run_worker_id,candidate_id,actor_user_id)
    values(p_command_id,p_return_cash_id,v_original.run_worker_id,v_original.candidate_id,p_actor_user_id);
  update private.bpay_next_command set status='SEALED',expected_member_count=1,
    sealed_at_utc=pg_catalog.transaction_timestamp() where id=p_command_id;
  return pg_catalog.jsonb_build_object('command_id',p_command_id,'sequence',v_sequence,'replay',false);
end
$function$;

create or replace function private.bpay_next_build_simple_reissue_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_run uuid;
  v_candidate uuid;
  v_job private.bpay_next_job%rowtype;
  v_request private.bpay_next_reissue_request%rowtype;
  v_cash private.bpay_next_return_cash%rowtype;
  v_original private.bpay_next_transfer%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_amount numeric;
  v_number integer;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null then
    raise exception using errcode='22023',message='BPAY_NEXT_REISSUE_BUILD_INPUT_INVALID';
  end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control
    where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE'; end if;
  select w.run_id,j.candidate_id into strict v_run,v_candidate from private.bpay_next_job j
    join private.bpay_next_reissue_request r on r.command_id=j.command_id and r.candidate_id=j.candidate_id
    join private.bpay_next_run_worker w on w.id=r.run_worker_id where j.id=p_job_id;
  perform 1 from private.bpay_next_pay_run where id=v_run for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_reissue_request where command_id=v_job.command_id for update;
  perform 1 from private.bpay_next_run_worker where id=v_request.run_worker_id for update;
  select * into strict v_cash from private.bpay_next_return_cash where id=v_request.return_cash_id for update;
  select * into strict v_original from private.bpay_next_transfer where id=v_cash.original_transfer_id;
  if v_job.job_kind<>'CASH_REISSUE' or v_job.module_epoch<>v_epoch
     or v_cash.candidate_id<>v_candidate or v_original.run_worker_id<>v_request.run_worker_id then
    raise exception using errcode='23514',message='BPAY_NEXT_REISSUE_SCOPE_INVALID';
  end if;
  if v_job.status='DONE' and v_request.transfer_id is not null then
    return pg_catalog.jsonb_build_object('transfer_id',v_request.transfer_id,'done',true,'replay',true);
  end if;
  if v_job.status<>'LEASED' or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate
               and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_REISSUE_BUILD_NOT_ELIGIBLE';
  end if;
  v_amount:=v_cash.amount_owed-v_cash.amount_held-v_cash.amount_reissued_paid;
  if v_amount<=0 then
    raise exception using errcode='55000',message='BPAY_NEXT_REISSUE_CASH_ALREADY_RESERVED';
  end if;
  -- Last transfer number is one indexed lookup, not history reconstruction.
  select transfer_no+1 into strict v_number from private.bpay_next_transfer
    where run_worker_id=v_request.run_worker_id order by transfer_no desc limit 1;
  insert into private.bpay_next_transfer(run_worker_id,candidate_id,build_command_id,
    transfer_no,beneficiary_kind,beneficiary_id,cash_amount,status,original_transfer_id,return_cash_id)
    values(v_request.run_worker_id,v_candidate,v_job.command_id,v_number,
      v_original.beneficiary_kind,v_original.beneficiary_id,v_amount,'BUILDING',v_original.id,v_cash.id)
    returning * into v_transfer;
  insert into private.bpay_next_transfer_member(transfer_id,run_worker_id,member_no,subject_kind,signed_cash_contribution)
    values(v_transfer.id,v_request.run_worker_id,1,'CASH_REISSUE',v_amount);
  update private.bpay_next_transfer set member_count=1,member_cash_sum=v_amount,status='MEMBERS_READY' where id=v_transfer.id;
  update private.bpay_next_return_cash set amount_held=amount_held+v_amount where id=v_cash.id;
  update private.bpay_next_reissue_request set transfer_id=v_transfer.id where command_id=v_job.command_id;
  update private.bpay_next_job set status='DONE',phase='COMPLETE',lease_nonce=null,lease_until_utc=null where id=p_job_id;
  update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1 where candidate_id=v_candidate;
  return pg_catalog.jsonb_build_object('transfer_id',v_transfer.id,'done',true,'replay',false);
end
$function$;
alter function private.bpay_next_receive_simple_reissue_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_build_simple_reissue_v1(uuid,uuid,bigint) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_receive_simple_reissue_v1(uuid,uuid,uuid),
private.bpay_next_build_simple_reissue_v1(uuid,uuid,bigint) from public,anon,authenticated,service_role;


-- Thin original-CSV advice only; no issue storage, delivery or current enrichment.
-- Source map: csv_instruction -> exact transfer.projection_id -> immutable NET;
-- WORK member -> run_line -> run_work.captured_revision_id -> immutable labels;
-- CASE member -> exact captured instruction/allocation result. No latest pointers.



create or replace function private.bpay_next_advice_work_v1(p_run_work_id uuid)
returns jsonb language sql stable security invoker
set search_path=pg_catalog,private
as $function$
  select pg_catalog.jsonb_build_object(
    'run_work_id',rw.id,'work_id',rw.work_id,'captured_revision_id',rw.captured_revision_id,
    'physical_timesheet_id',r.physical_timesheet_id,'physical_timesheet_version',r.physical_timesheet_version,
    'source_kind',r.source_kind,'detail_kind',r.detail_kind,'week_ending_date',r.week_ending_date,
    'candidate_display_name',r.candidate_display_name,'candidate_reference',r.candidate_reference,
    'client_display_name',r.client_display_name,'job_title',r.job_title,'band_label',r.band_label,
    'timesheet_reference',r.timesheet_reference,'expected_rate_schedule_count',r.expected_rate_schedule_count)
  from private.bpay_next_run_work rw
  join private.bpay_next_work_revision r on r.id=rw.captured_revision_id and r.work_id=rw.work_id
  where rw.id=p_run_work_id
$function$;

create or replace function public.bpay_next_original_csv_advice_page_v1(
  p_actor_user_id uuid,p_instruction_id uuid,p_kind text,
  p_run_work_id uuid default null,p_run_line_id uuid default null,p_shift_detail_id uuid default null,
  p_after_work_id uuid default null,p_after_member_no bigint default null,
  p_after_detail_no integer default null,p_after_break_no integer default null,
  p_after_bucket text default null,p_after_rate_family text default null,p_after_rate_code text default null,
  p_limit integer default 50
) returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,private,public
set timezone='UTC'
as $function$
declare
  v_instruction private.bpay_next_csv_instruction%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_group private.bpay_next_destination_group%rowtype;
  v_net private.bpay_next_net_destination_state%rowtype;
  v_destination private.bpay_next_net_destination_amount%rowtype;
  v_origin private.bpay_next_stored_credit_origin%rowtype;
  v_destination_kind text:='OWN';
  v_approved_line uuid;
  v_revision uuid;
  v_sql text;
  v_row record;
  v_rows jsonb:='[]'::jsonb;
  v_bytes integer:=512;
  v_count integer:=0;
  v_more boolean:=false;
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
    nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
    or not exists(select 1 from public.tms_users u where u.id=p_actor_user_id
      and u.is_active is true and u.role::text='admin') then
    raise exception using errcode='42501',message='BPAY_NEXT_ADVICE_FORBIDDEN';
  end if;
  if not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT') then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  if p_instruction_id is null or p_kind is null
    or p_kind not in ('HEADER','WORKS','MEMBERS','SHIFTS','BREAKS','RATE_DETAILS','RATE_SCHEDULE')
    or p_limit is null or p_limit not between 1 and 100
    or (p_after_member_no is not null and p_after_member_no<0)
    or (p_after_detail_no is not null and p_after_detail_no<0)
    or (p_after_break_no is not null and p_after_break_no<0)
    or (p_after_bucket is not null and p_after_bucket not in ('BH','DAY','NIGHT','SAT','SUN'))
    or ((p_after_rate_family is null)<>(p_after_rate_code is null))
    or (p_after_rate_family is not null and (p_after_rate_family not in ('ADDITIONAL','MILEAGE','STANDARD')
      or char_length(p_after_rate_code) not between 1 and 128)) then
    raise exception using errcode='22023',message='BPAY_NEXT_ADVICE_REQUEST_INVALID';
  end if;
  -- Closed shape: no cursor or child ID is silently ignored by a different kind.
  if (p_run_work_id is not null and p_kind<>'RATE_SCHEDULE')
    or (p_run_line_id is not null and p_kind not in ('SHIFTS','BREAKS','RATE_DETAILS'))
    or (p_shift_detail_id is not null and p_kind<>'BREAKS')
    or (p_after_work_id is not null and p_kind<>'WORKS')
    or (p_after_member_no is not null and p_kind<>'MEMBERS')
    or (p_after_detail_no is not null and p_kind<>'SHIFTS')
    or (p_after_break_no is not null and p_kind<>'BREAKS')
    or (p_after_bucket is not null and p_kind<>'RATE_DETAILS')
    or (p_after_rate_family is not null and p_kind<>'RATE_SCHEDULE')
    or (p_kind='RATE_SCHEDULE' and p_run_work_id is null)
    or (p_kind in ('SHIFTS','BREAKS','RATE_DETAILS') and p_run_line_id is null)
    or (p_kind='BREAKS' and p_shift_detail_id is null) then
    raise exception using errcode='22023',message='BPAY_NEXT_ADVICE_REQUEST_INVALID';
  end if;
  select * into v_instruction from private.bpay_next_csv_instruction where id=p_instruction_id;
  if not found then
    raise exception using errcode='P0002',message='BPAY_NEXT_ADVICE_INSTRUCTION_NOT_FOUND';
  end if;
  select * into strict v_transfer from private.bpay_next_transfer where id=v_instruction.transfer_id;
  if v_transfer.original_transfer_id is not null or v_transfer.projection_id is null then
    raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_ORIGINAL_CSV_REQUIRED';
  end if;
  select * into strict v_projection from private.bpay_next_net_projection where id=v_transfer.projection_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_instruction.run_worker_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_worker.run_id;
  if v_transfer.original_transfer_id is not null or v_transfer.execution_kind<>'BANK'
    or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE')
      or (v_worker.target_pay_channel='UMBRELLA' and v_transfer.beneficiary_kind='UMBRELLA'
        and v_worker.target_umbrella_id is not null and v_projection.input_kind='UMBRELLA'
        and v_worker.case_selection_revision=0))
    or v_transfer.run_worker_id<>v_worker.id or v_transfer.candidate_id<>v_worker.candidate_id
    or v_projection.run_worker_id<>v_worker.id
    or v_transfer.beneficiary_id is distinct from
      (case when v_worker.target_pay_channel='UMBRELLA' then v_worker.target_umbrella_id else v_worker.candidate_id end)
    or v_transfer.return_cash_id is not null
    or v_instruction.cash_amount<>v_transfer.cash_amount
    or v_instruction.bank_details_hash_snapshot is distinct from v_transfer.bank_details_hash_snapshot
    or v_transfer.member_count<1 or v_transfer.member_cash_sum<>v_transfer.cash_amount
    or (v_worker.target_pay_channel='PAYE' and v_projection.input_kind not in ('PAYE_MANUAL','PAYE_IMPORT','CASE_PAYOUT'))
    or (v_worker.target_pay_channel='UMBRELLA' and
      (v_projection.entered_paye_net is not null or v_projection.request_command_id is not null
       or v_projection.cash_amount is distinct from v_projection.gross_inc_vat)) then
    raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_ORIGINAL_CSV_REQUIRED';
  end if;
  -- A frozen leg may be smaller than its accepted Candidate projection. This
  -- is a point read of immutable sealed facts, NOT the execution qualifier:
  -- that qualifier checks today's bank version and must not invalidate advice
  -- for an already-issued original instruction after factual account changes.
  select * into v_leg from private.bpay_next_destination_group_leg where transfer_id=v_transfer.id;
  if not found then
    if v_projection.cash_amount<>v_transfer.cash_amount
      or exists(select 1 from private.bpay_next_destination_group where run_worker_id=v_worker.id) then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
  else
    select * into strict v_group from private.bpay_next_destination_group where anchor_transfer_id=v_leg.anchor_transfer_id;
    select * into strict v_net from private.bpay_next_net_destination_state where state_id=v_group.net_state_id;
    if v_group.stage<>'COMPLETE' or v_group.completed_at_utc is null
      or v_group.run_worker_id<>v_worker.id or v_group.candidate_id<>v_worker.candidate_id
      or v_group.projection_id<>v_projection.id or v_net.run_worker_id<>v_worker.id
      or v_net.projection_id is distinct from v_projection.id or v_net.completed_at_utc is null
      or v_group.processed_work_count<>v_group.expected_work_count or v_group.processed_case_count<>v_group.expected_case_count
      or v_group.created_leg_count<>v_group.expected_leg_count or v_group.sealed_leg_count<>v_group.expected_leg_count
      or v_group.expected_leg_count<>v_net.external_leg_count+1
      or v_group.member_cash_total<>v_projection.cash_amount or v_group.sealed_cash_total<>v_projection.cash_amount
      or v_net.cash_amount is distinct from v_projection.cash_amount
      or v_net.own_amount+v_net.external_amount is distinct from v_projection.cash_amount then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    v_destination_kind:=v_leg.leg_kind;
    if v_leg.leg_kind='OWN' then
      if v_transfer.id<>v_group.anchor_transfer_id or v_leg.destination_id is not null
        or v_transfer.cash_amount is distinct from v_net.own_amount then
        raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    else
      select * into strict v_destination from private.bpay_next_net_destination_amount where destination_id=v_leg.destination_id;
      select * into strict v_origin from private.bpay_next_stored_credit_origin where command_id=v_destination.first_origin_command_id;
      if v_destination.state_id<>v_net.state_id or v_destination.amount<>v_transfer.cash_amount
        or v_origin.candidate_id<>v_worker.candidate_id or v_destination.bank_details_hash<>v_origin.bank_details_hash
        or v_origin.original_source_pay_channel<>'UMBRELLA' or v_origin.original_tax_treatment<>'NON_TAXABLE'
        or v_origin.original_routing_kind<>'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        or (v_transfer.bank_details_hash_snapshot,v_transfer.beneficiary_name_snapshot,
            v_transfer.sort_code_snapshot,v_transfer.account_number_snapshot)
          is distinct from (v_origin.bank_details_hash,pg_catalog.btrim(v_origin.beneficiary_name),
            v_origin.sort_code,v_origin.account_number) then
        raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_FROZEN_DESTINATION_INVALID';end if;
    end if;
  end if;
  -- CSV issuance is the immutable read gate. Current worker/transfer/outcome
  -- status and retirement of this NET projection cannot re-price this issue.
  if p_kind='HEADER' then
    v_rows:=jsonb_build_array(jsonb_build_object(
      'instruction_id',v_instruction.id,'transfer_id',v_transfer.id,'projection_id',v_projection.id,
      'projection_no',v_projection.projection_no::text,'input_kind',v_projection.input_kind,
      'run_id',v_run.id,'run_worker_id',v_worker.id,'candidate_id',v_worker.candidate_id,
      'pay_date',v_run.pay_date,'target_pay_channel',v_worker.target_pay_channel,
      'beneficiary_name_snapshot',v_transfer.beneficiary_name_snapshot,
      'payment_reference',v_instruction.payment_reference,'issued_at_utc',v_instruction.issued_at_utc,
      'member_count',v_transfer.member_count::text,
      'gross_ex_vat',v_projection.gross_ex_vat::text,'gross_vat',v_projection.gross_vat::text,
      'gross_inc_vat',v_projection.gross_inc_vat::text,'entered_paye_net',v_projection.entered_paye_net::text,
      'accepted_gross_additions',v_projection.accepted_gross_additions::text,
      'accepted_gross_deductions',v_projection.accepted_gross_deductions::text,
      'accepted_net_additions',v_projection.accepted_net_additions::text,
      'accepted_recoveries',v_projection.accepted_recoveries::text,'cash_amount',v_instruction.cash_amount::text,
      'projection_cash_amount',v_projection.cash_amount::text,'destination_kind',v_destination_kind));
    if octet_length(v_rows::text)>120000 then
      raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';
    end if;
    return jsonb_build_object('rows',v_rows,'complete',true);
  end if;
  if p_kind in ('SHIFTS','BREAKS','RATE_DETAILS') then
    select l.approved_line_id into v_approved_line
    from private.bpay_next_transfer_member m join private.bpay_next_run_line l on l.id=m.run_line_id
    where m.transfer_id=v_transfer.id and m.subject_kind='WORK' and l.id=p_run_line_id
      and l.run_worker_id=v_worker.id;
    if not found then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_LINE_NOT_IN_INSTRUCTION';
    end if;
  elsif p_kind='RATE_SCHEDULE' then
    select rw.captured_revision_id into v_revision from private.bpay_next_run_work rw
    where rw.id=p_run_work_id and rw.run_worker_id=v_worker.id and exists(
      select 1 from private.bpay_next_run_line l join private.bpay_next_transfer_member m on m.run_line_id=l.id
      where l.run_work_id=rw.id and m.transfer_id=v_transfer.id and m.subject_kind='WORK');
    if not found then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_WORK_NOT_IN_INSTRUCTION';
    end if;
  end if;
  if p_kind='WORKS' then
    v_sql:=$query$select private.bpay_next_advice_work_v1(rw.id) row_value
      from private.bpay_next_run_work rw where rw.run_worker_id=$2
        and ($6::uuid is null or rw.work_id>$6) and exists(
          select 1 from private.bpay_next_run_line l join private.bpay_next_transfer_member m on m.run_line_id=l.id
          where l.run_work_id=rw.id and m.transfer_id=$1 and m.subject_kind='WORK')
      order by rw.work_id limit $12$query$;
  elsif p_kind='MEMBERS' then
    v_sql:=$query$select jsonb_build_object(
      'member_no',m.member_no::text,'subject_kind',m.subject_kind,'signed_cash_contribution',m.signed_cash_contribution::text,
      'work',case when m.subject_kind='WORK' then private.bpay_next_advice_work_v1(l.run_work_id) end,
      'line',case when m.subject_kind='WORK' then jsonb_build_object(
        'run_line_id',l.id,'run_work_id',l.run_work_id,'captured_revision_id',l.captured_revision_id,
        'line_no',l.line_no::text,'component_key',l.component_key,'component_kind',a.component_kind,
        'work_date',a.work_date,'unit_label',a.unit_label,'approved_quantity',a.approved_quantity::text,
        'approved_unit_rate',a.approved_unit_rate::text,'expected_rate_detail_count',a.expected_rate_detail_count,
        'evidence_ref',a.evidence_ref,'approved_source_ex_vat',a.source_pay_ex_vat::text,
        'source_consumed_ex_vat',l.source_consumed_ex_vat::text,'frozen_ex_vat',l.frozen_ex_vat::text,
        'frozen_vat',l.frozen_vat::text,'frozen_inc_vat',l.frozen_inc_vat::text) end,
      'case',case when m.subject_kind='CASE' then jsonb_build_object(
        'case_instruction_id',ci.id,'allocation_result_id',cr.id,'case_id',ci.case_id,
        'case_kind',ci.case_kind,'case_subtype',ci.case_subtype,'tax_treatment',ci.tax_treatment,
        'instruction_kind',ci.instruction_kind,'direction',ci.direction,'payroll_stage',ci.payroll_stage,
        'resolution_ref',ci.resolution_ref,'explanation',ci.explanation,
        'allocated_target_ex_vat',cr.allocated_target_ex_vat::text,'allocated_target_vat',cr.allocated_target_vat::text,
        'allocated_target_inc_vat',cr.allocated_target_inc_vat::text) end) row_value
      from private.bpay_next_transfer_member m
      left join private.bpay_next_run_line l on l.id=m.run_line_id and l.run_worker_id=m.run_worker_id
      left join private.bpay_next_approved_line a on a.id=l.approved_line_id and a.revision_id=l.captured_revision_id
      left join private.bpay_next_run_case_instruction ci on ci.id=m.case_instruction_id and ci.run_worker_id=m.run_worker_id
      left join private.bpay_next_case_allocation_result cr on cr.id=m.case_allocation_result_id and cr.instruction_id=ci.id
      where m.transfer_id=$1 and m.member_no>coalesce($7::bigint,0)
      order by m.member_no limit $12$query$;
  elsif p_kind='SHIFTS' then
    v_sql:=$query$select to_jsonb(page) row_value from (
      select s.id shift_detail_id,s.detail_no,s.work_date,s.shift_start_at,s.shift_end_at,s.shift_start_local,
        s.shift_end_local,s.shift_overnight,s.submitted_minutes,s.approved_minutes,s.approved_hours::text,s.detail_label,
        s.segment_pay_ex_vat::text,s.pay_excluded,s.hours_day::text,s.hours_night::text,s.hours_sat::text,s.hours_sun::text,s.hours_bh::text
      from private.bpay_next_shift_detail s where s.approved_line_id=$4 and s.detail_no>coalesce($8::integer,0)
      order by s.detail_no limit $12) page$query$;
  elsif p_kind='BREAKS' then
    if not exists(select 1 from private.bpay_next_shift_detail where id=p_shift_detail_id and approved_line_id=v_approved_line) then
      raise exception using errcode='55000',message='BPAY_NEXT_ADVICE_BREAK_NOT_IN_LINE';
    end if;
    v_sql:=$query$select to_jsonb(page) row_value from (
      select b.id break_detail_id,b.break_no,b.break_start_at,b.break_end_at,b.break_start_local,b.break_end_local,b.break_minutes
      from private.bpay_next_break_detail b where b.shift_detail_id=$5 and b.break_no>coalesce($8::integer,0)
      order by b.break_no limit $12) page$query$;
  elsif p_kind='RATE_DETAILS' then
    v_sql:=$query$select to_jsonb(page) row_value from (
      select d.id rate_detail_id,d.bucket,d.approved_hours::text,d.source_pay_rate::text
      from private.bpay_next_rate_detail d where d.approved_line_id=$4 and ($9::text is null or d.bucket>$9)
      order by d.bucket limit $12) page$query$;
  else
    v_sql:=$query$select to_jsonb(page) row_value from (
      select s.id rate_schedule_id,s.rate_family,s.rate_code,s.unit_label,s.paye_rate::text,s.umbrella_rate::text,s.charge_rate::text
      from private.bpay_next_rate_schedule s where s.revision_id=$3
        and ($10::text is null or (s.rate_family,s.rate_code)>($10,$11))
      order by s.rate_family,s.rate_code limit $12) page$query$;
  end if;
  for v_row in execute v_sql using v_transfer.id,v_worker.id,v_revision,v_approved_line,p_shift_detail_id,
    p_after_work_id,p_after_member_no,coalesce(p_after_detail_no,p_after_break_no),p_after_bucket,p_after_rate_family,p_after_rate_code,p_limit
  loop
    if v_bytes+octet_length(v_row.row_value::text)+1>120000 then
      if v_count=0 then raise exception using errcode='54000',message='BPAY_NEXT_ADVICE_ROW_TOO_LARGE';end if;
      v_more:=true;exit;
    end if;
    v_bytes:=v_bytes+octet_length(v_row.row_value::text)+1;
    v_rows:=v_rows||jsonb_build_array(v_row.row_value);v_count:=v_count+1;
  end loop;
  return jsonb_build_object('rows',v_rows,'complete',not(v_more or v_count=p_limit));
end
$function$;
alter function private.bpay_next_advice_work_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_advice_work_v1(uuid) from public,anon,authenticated,service_role;
alter function public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) OWNER TO CURRENT_USER;
revoke all on function public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer)
  from public,anon,authenticated;
grant execute on function public.bpay_next_original_csv_advice_page_v1(uuid,uuid,text,uuid,uuid,uuid,uuid,bigint,integer,integer,text,text,text,integer) to service_role;
notify pgrst,'reload schema';


-- Owner-only whole-Candidate cancellation of an unissued original PAYE Draft.
-- Requires the cancellation schema and shared ingress/enroller guards described
-- in tests/fixtures/bpay-next-simple-cancel-requirements.md. No public grant.
-- Intake records intent without disabling earlier accepted builders. Only the
-- ordered page owner starts CANCELLING, under the shared parent run mutex.




-- Call only while holding the parent run, Candidate control and worker locks.
-- This is a bounded admission check, not an unbounded member/history scan.
-- realised_effect_count MUST be maintained by every realised posting owner.
create or replace function private.bpay_next_simple_cancel_block_v1(
  p_run_worker_id uuid,p_allow_building boolean default false
) returns text
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_count integer;
begin
  select * into strict v_worker from private.bpay_next_run_worker
    where id=p_run_worker_id;
  -- Only a no-case, never-executed frozen UMB worker may use SIMPLE_CANCEL.
  -- No current Candidate/rate/Source lookup and no UMB NET/CSV admission.
  if v_worker.target_pay_channel='UMBRELLA' then
    if v_worker.status<>'READY' or v_worker.target_umbrella_id is null
       or v_worker.target_umbrella_vat_chargeable is null
       or v_worker.gross_ex_vat<0 or v_worker.gross_vat<0 or v_worker.gross_inc_vat<0
       or v_worker.gross_inc_vat<>v_worker.gross_ex_vat+v_worker.gross_vat
       or (v_worker.target_umbrella_vat_chargeable is false and v_worker.gross_vat<>0) then
      return 'BPAY_NEXT_CANCEL_GROUP_NOT_SIMPLE_DRAFT';
    end if;
    if v_worker.realised_effect_count<>0 or v_worker.financial_resolution_count<>0
       or not exists(select 1 from private.bpay_next_worker_control c
         where c.candidate_id=v_worker.candidate_id and c.pending_outcome_count=0) then
      return 'BPAY_NEXT_CANCEL_REALISED_OR_PENDING';
    end if;
    if v_worker.case_selection_revision<>0 or v_worker.active_case_hold_count<>0
       or v_worker.case_instruction_count<>0 or v_worker.case_allocated_count<>0
       or v_worker.case_pending_binding_count<>0
       or exists(select 1 from private.bpay_next_case_hold h where h.run_worker_id=v_worker.id) then
      return 'BPAY_NEXT_CANCEL_CASE_GROUP_UNSUPPORTED';
    end if;
    -- UMB uses frozen gross-inc cash, never a payroll NET request/value.
    if v_worker.net_request_revision is distinct from 0
       or v_worker.net_projection_revision not in (0,1)
       or v_worker.net_projection_revision is null
       or v_worker.entered_paye_net is not null
       or exists(select 1 from private.bpay_next_paye_net_request n where n.run_worker_id=v_worker.id) then
      return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
    end if;
    select count(*) into v_count from
      (select 1 from private.bpay_next_net_projection p
       where p.run_worker_id=v_worker.id order by p.projection_no limit 2) p;
    if v_count>1 or v_count is distinct from v_worker.net_projection_revision then
      return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
    end if;
    if v_count=1 then
      select p.* into strict v_projection from private.bpay_next_net_projection p
        where p.run_worker_id=v_worker.id;
      if (v_projection.run_worker_id,v_projection.projection_no,v_projection.input_kind,
          v_projection.gross_ex_vat,v_projection.gross_vat,v_projection.gross_inc_vat,
          v_projection.cash_amount,v_projection.accepted_recoveries,
          v_projection.accepted_gross_additions,v_projection.accepted_gross_deductions,
          v_projection.accepted_net_additions)
         is distinct from
         (v_worker.id,1::bigint,'UMBRELLA'::text,
          v_worker.gross_ex_vat,v_worker.gross_vat,v_worker.gross_inc_vat,
          v_worker.gross_inc_vat,0::numeric,0::numeric,0::numeric,0::numeric)
         or v_projection.entered_paye_net is not null
         or v_projection.request_command_id is not null
         or v_projection.retired_at_utc is not null then
        return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
      end if;
    end if;
    -- One original transfer only. Intake may precede its earlier builder;
    -- the unchanged claimant waits, and first ordered page disallows BUILDING.
    select count(*) into v_count from
      (select 1 from private.bpay_next_transfer t
       where t.run_worker_id=v_worker.id order by t.transfer_no limit 2) t;
    if v_count>1 then return 'BPAY_NEXT_CANCEL_MULTI_TRANSFER_UNSUPPORTED';end if;
    if v_count=1 then
      select t.* into strict v_transfer from private.bpay_next_transfer t
        where t.run_worker_id=v_worker.id;
      if v_projection.id is null
         or (v_transfer.run_worker_id,v_transfer.candidate_id,v_transfer.transfer_no,
             v_transfer.beneficiary_kind,v_transfer.beneficiary_id,
             v_transfer.projection_id,v_transfer.cash_amount,v_transfer.execution_kind)
            is distinct from
            (v_worker.id,v_worker.candidate_id,1::bigint,
             'UMBRELLA'::text,v_worker.target_umbrella_id,
             v_projection.id,v_projection.cash_amount,'BANK'::text)
         or v_transfer.cash_amount<=0
         or v_transfer.original_transfer_id is not null
         or v_transfer.return_cash_id is not null then
        return 'BPAY_NEXT_CANCEL_REISSUE_OR_NON_CANDIDATE_UNSUPPORTED';
      end if;
      if v_transfer.status not in ('MEMBERS_READY','DRAFT','SCHEDULED')
         and not (p_allow_building is true and v_transfer.status='BUILDING') then
        return 'BPAY_NEXT_CANCEL_TRANSFER_PROTECTED';
      end if;
      if v_transfer.account_approval_ref is not null
         or exists(select 1 from private.bpay_next_csv_instruction i where i.transfer_id=v_transfer.id)
         or exists(select 1 from private.bpay_next_transfer_outcome o where o.transfer_id=v_transfer.id)
         or exists(select 1 from private.bpay_next_internal_receipt r where r.transfer_id=v_transfer.id) then
        return 'BPAY_NEXT_CANCEL_INSTRUCTION_OR_OUTCOME_PROTECTED';
      end if;
    end if;
    return null;
  end if;
  if v_worker.case_selection_revision>0 then
    return private.bpay_next_case_cancel_block_v1(p_run_worker_id,p_allow_building);
  end if;
  if v_worker.status<>'READY' or v_worker.target_pay_channel<>'PAYE'
     or v_worker.target_umbrella_id is not null or v_worker.gross_vat<>0
     or v_worker.gross_inc_vat<0
     or v_worker.net_request_revision not between 0 and 1
     or v_worker.net_projection_revision not between 0 and 1
     or v_worker.net_projection_revision>v_worker.net_request_revision then
    return 'BPAY_NEXT_CANCEL_GROUP_NOT_SIMPLE_DRAFT';
  end if;
  if v_worker.realised_effect_count<>0
     or v_worker.financial_resolution_count<>0
     or exists(select 1 from private.bpay_next_worker_control c
               where c.candidate_id=v_worker.candidate_id
                 and c.pending_outcome_count<>0) then
    return 'BPAY_NEXT_CANCEL_GROUP_REALISED_OR_PENDING_OUTCOME';
  end if;
  if v_worker.case_selection_revision<>0
     or exists(select 1 from private.bpay_next_case_hold h
               where h.run_worker_id=v_worker.id) then
    return 'BPAY_NEXT_CANCEL_CASE_GROUP_UNSUPPORTED';
  end if;
  if exists(select 1 from private.bpay_next_net_projection p
            where p.run_worker_id=v_worker.id
              and (p.projection_no<>1 or p.input_kind<>'PAYE_MANUAL'
                   or p.accepted_recoveries<>0
                   or p.retired_at_utc is not null)) then
    return 'BPAY_NEXT_CANCEL_PROJECTION_UNSUPPORTED';
  end if;
  if p_allow_building is not true
     and v_worker.net_request_revision<>v_worker.net_projection_revision then
    return 'BPAY_NEXT_CANCEL_PROJECTION_PENDING';
  end if;
  -- The existing original builder admits at most one original transfer.
  -- LIMIT 2 is deliberate: a broader/reissue group is not this owner's slice.
  select count(*) into v_count from
    (select 1 from private.bpay_next_transfer t
     where t.run_worker_id=v_worker.id order by t.transfer_no limit 2) t;
  if v_count>1 then return 'BPAY_NEXT_CANCEL_MULTI_TRANSFER_UNSUPPORTED'; end if;
  if v_count=1 then
    select * into strict v_transfer from private.bpay_next_transfer
      where run_worker_id=v_worker.id;
    if v_transfer.original_transfer_id is not null
       or v_transfer.return_cash_id is not null
       or v_transfer.projection_id is null
       or v_transfer.candidate_id<>v_worker.candidate_id
       or v_transfer.beneficiary_kind<>'CANDIDATE'
       or v_transfer.beneficiary_id<>v_worker.candidate_id then
      return 'BPAY_NEXT_CANCEL_REISSUE_OR_NON_CANDIDATE_UNSUPPORTED';
    end if;
    if v_transfer.status not in ('MEMBERS_READY','DRAFT','SCHEDULED')
       and not (p_allow_building is true and v_transfer.status='BUILDING') then
      return 'BPAY_NEXT_CANCEL_TRANSFER_PROTECTED';
    end if;
    if v_transfer.account_approval_ref is not null
       or exists(select 1 from private.bpay_next_csv_instruction i
                 where i.transfer_id=v_transfer.id)
       or exists(select 1 from private.bpay_next_transfer_outcome o
                 where o.transfer_id=v_transfer.id)
       or exists(select 1 from private.bpay_next_internal_receipt r
                 where r.transfer_id=v_transfer.id) then
      return 'BPAY_NEXT_CANCEL_INSTRUCTION_OR_OUTCOME_PROTECTED';
    end if;
  end if;
  return null;
end
$function$;

create or replace function private.bpay_next_accept_simple_cancel_v1(
  p_command_id uuid,p_run_worker_id uuid
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_run_id uuid;
  v_candidate_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_prior private.bpay_next_cancel_request%rowtype;
  v_sequence bigint;
  v_block text;
begin
  if p_command_id is null or p_run_worker_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_CANCEL_INPUT_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_module_control
                where id=1 and active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  -- Frozen selection is routing information, not admission. The case owner
  -- rechecks the whole request under its command mutex BEFORE row locks,
  -- matching case NET/transfer intake and avoiding an inverted lock order.
  select * into strict v_worker from private.bpay_next_run_worker
    where id=p_run_worker_id;
  if v_worker.case_selection_revision>0 then
    return private.bpay_next_accept_case_cancel_v1(p_command_id,p_run_worker_id);
  end if;
  v_run_id:=v_worker.run_id;
  v_candidate_id:=v_worker.candidate_id;
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  insert into private.bpay_next_worker_control(candidate_id)
    values(v_candidate_id) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_candidate_id for update;
  select * into strict v_worker from private.bpay_next_run_worker
    where id=p_run_worker_id for update;
  select * into v_prior from private.bpay_next_cancel_request
    where command_id=p_command_id;
  if found then
    if v_prior.run_worker_id<>v_worker.id
       or v_prior.candidate_id<>v_worker.candidate_id then
      raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_REPLAY_CONFLICT';
    end if;
    select agency_sequence into strict v_sequence from private.bpay_next_command
      where id=p_command_id and command_kind='SIMPLE_CANCEL';
    return pg_catalog.jsonb_build_object('sequence',v_sequence,
      'run_worker_id',v_worker.id,'phase',v_prior.status,
      'cursor',v_prior.cursor_line_no,
      'released_line_count',v_prior.released_line_count,
      'blocked_code',v_prior.blocked_code,'replay',true);
  end if;
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
     or v_run.selection_state<>'SEALED'
     or exists(select 1 from private.bpay_next_cancel_request r
               where r.run_worker_id=v_worker.id
                 and r.status in ('REQUESTED','CANCELLING')) then
    raise exception using errcode='55000',message='BPAY_NEXT_CANCEL_NOT_ELIGIBLE';
  end if;
  -- BUILDING here is intentional. Its earlier accepted job must finish before
  -- the cancellation can claim; intake must not fence that job out of READY.
  v_block:=private.bpay_next_simple_cancel_block_v1(v_worker.id,true);
  if v_block is not null then
    raise exception using errcode='55000',message=v_block;
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'SIMPLE_CANCEL');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no)
    values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_cancel_request
    (command_id,run_worker_id,candidate_id,expected_line_count,status)
    values(p_command_id,v_worker.id,v_worker.candidate_id,
           v_worker.captured_line_count,'REQUESTED');
  update private.bpay_next_command
    set expected_member_count=1,status='SEALED',
        sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('sequence',v_sequence,
    'run_worker_id',v_worker.id,'phase','REQUESTED',
    'cursor',null,'released_line_count',0,'replay',false);
end
$function$;

create or replace function private.bpay_next_claim_simple_cancel_job_v1(
  p_job_id uuid,p_lease_seconds integer default 120
) returns table(lease_nonce uuid,owner_epoch bigint)
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_candidate_id uuid;
  v_job private.bpay_next_job%rowtype;
  v_owner_epoch bigint;
  v_nonce uuid;
begin
  if p_job_id is null or p_lease_seconds is null
     or p_lease_seconds not between 1 and 120 then
    raise exception using errcode='22023',message='BPAY_NEXT_CANCEL_LEASE_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select candidate_id into strict v_candidate_id from private.bpay_next_job
    where id=p_job_id;
  insert into private.bpay_next_worker_control(candidate_id)
    values(v_candidate_id) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control
    where candidate_id=v_candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  if v_job.module_epoch<>v_epoch or v_job.job_kind<>'SIMPLE_CANCEL'
     or v_job.phase not in ('NEW','RELEASE')
     or v_job.status not in ('READY','LEASED')
     or v_job.available_at_utc>pg_catalog.clock_timestamp()
     or (v_job.status='LEASED'
         and v_job.lease_until_utc>pg_catalog.clock_timestamp())
     or not exists(select 1 from private.bpay_next_cancel_request r
                   where r.command_id=v_job.command_id
                     and r.candidate_id=v_candidate_id
                     and r.status in ('REQUESTED','CANCELLING'))
     or exists(select 1 from private.bpay_next_job earlier
               where earlier.candidate_id=v_candidate_id
                 and earlier.command_sequence<v_job.command_sequence
                 and earlier.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_CANCEL_JOB_NOT_CLAIMABLE';
  end if;
  update private.bpay_next_worker_control
    set active_owner_epoch=active_owner_epoch+1,
        updated_at_utc=pg_catalog.transaction_timestamp()
    where candidate_id=v_candidate_id
    returning active_owner_epoch into v_owner_epoch;
  v_nonce:=pg_catalog.gen_random_uuid();
  update private.bpay_next_job
    set status='LEASED',owner_epoch=v_owner_epoch,lease_nonce=v_nonce,
        lease_until_utc=pg_catalog.clock_timestamp()+
          pg_catalog.make_interval(secs=>p_lease_seconds),
        attempt_count=attempt_count+1
    where id=p_job_id;
  lease_nonce:=v_nonce; owner_epoch:=v_owner_epoch;
  return next;
end
$function$;

create or replace function private.bpay_next_cancel_simple_worker_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint,p_limit integer
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;
  v_run_id uuid;
  v_candidate_id uuid;
  v_run private.bpay_next_pay_run%rowtype;
  v_control private.bpay_next_worker_control%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_request private.bpay_next_cancel_request%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_line record;
  v_hold private.bpay_next_hold%rowtype;
  v_block text;
  v_cursor bigint;
  v_released bigint;
  v_seen integer:=0;
  v_holds_released integer:=0;
  v_now timestamptz:=pg_catalog.transaction_timestamp();
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null
     or p_owner_epoch<=0 or p_limit is null or p_limit not between 1 and 100
     or (p_expected_cursor is not null and p_expected_cursor<=0) then
    raise exception using errcode='22023',message='BPAY_NEXT_CANCEL_PAGE_INPUT_INVALID';
  end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control
    where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate_id
    from private.bpay_next_job j
    join private.bpay_next_cancel_request r on r.command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=r.run_worker_id
    where j.id=p_job_id and j.candidate_id=w.candidate_id;
  -- Same mutex as net projection, transfer build, destination/CSV issue and
  -- outcomes. No SOURCE/TARGET money moves before whole-group admission.
  select * into strict v_run from private.bpay_next_pay_run
    where id=v_run_id for update;
  select * into strict v_control from private.bpay_next_worker_control
    where candidate_id=v_candidate_id for update;
  select * into strict v_job from private.bpay_next_job
    where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_cancel_request
    where command_id=v_job.command_id for update;
  select * into strict v_worker from private.bpay_next_run_worker
    where id=v_request.run_worker_id for update;
  if v_worker.case_selection_revision>0 then
    return private.bpay_next_cancel_case_worker_page_v1(
      p_job_id,p_lease_nonce,p_owner_epoch,p_expected_cursor,p_limit);
  end if;
  if v_job.job_kind<>'SIMPLE_CANCEL' or v_job.module_epoch<>v_epoch
     or v_job.candidate_id<>v_worker.candidate_id
     or v_request.candidate_id<>v_worker.candidate_id
     or v_worker.run_id<>v_run.id
     or v_job.applied_line_count<>v_request.released_line_count
     or v_job.cursor_key is distinct from v_request.cursor_line_no::text
     or not exists(select 1 from private.bpay_next_command c
                   where c.id=v_job.command_id
                     and c.command_kind='SIMPLE_CANCEL'
                     and c.agency_sequence=v_job.command_sequence
                     and c.module_epoch=v_epoch
                     and c.expected_member_count=1
                     and c.enrolled_member_count=1) then
    raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_JOB_SCOPE_INVALID';
  end if;
  if v_job.status='DONE' and v_request.status in ('CANCELLED','BLOCKED') then
    return pg_catalog.jsonb_build_object('phase',v_request.status,
      'run_worker_id',v_worker.id,'cursor',v_request.cursor_line_no,
      'released_line_count',v_request.released_line_count,
      'blocked_code',v_request.blocked_code,'replay',true);
  end if;
  if v_job.status<>'LEASED' or v_job.phase not in ('NEW','RELEASE')
     or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_control.active_owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or exists(select 1 from private.bpay_next_job earlier
               where earlier.candidate_id=v_candidate_id
                 and earlier.command_sequence<v_job.command_sequence
                 and earlier.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_CANCEL_PAGE_LEASE_INVALID';
  end if;
  if v_request.cursor_line_no is distinct from p_expected_cursor then
    return pg_catalog.jsonb_build_object('phase',v_request.status,
      'run_worker_id',v_worker.id,'cursor',v_request.cursor_line_no,
      'released_line_count',v_request.released_line_count,'replay',true);
  end if;
  if v_request.status='REQUESTED' then
    if v_job.phase<>'NEW' or v_request.released_line_count<>0
       or v_request.cursor_line_no is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_REQUEST_STATE_INVALID';
    end if;
    v_block:=private.bpay_next_simple_cancel_block_v1(v_worker.id,false);
    if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null
       or v_worker.captured_line_count<>v_request.expected_line_count then
      v_block:='BPAY_NEXT_CANCEL_DRAFT_CHANGED';
    end if;
    if v_block is not null then
      -- A newly protected group remains financially intact. Close this
      -- refused intent as DONE, not as an ordering job that stalls the queue.
      update private.bpay_next_cancel_request
        set status='BLOCKED',blocked_code=v_block,finished_at_utc=v_now
        where command_id=v_job.command_id;
      update private.bpay_next_job
        set status='DONE',phase='BLOCKED',last_error_code=v_block,
            lease_nonce=null,lease_until_utc=null where id=p_job_id;
      update private.bpay_next_command set status='COMPLETE'
        where id=v_job.command_id;
      return pg_catalog.jsonb_build_object('phase','BLOCKED',
        'run_worker_id',v_worker.id,'cursor',null,
        'released_line_count',0,'blocked_code',v_block,'replay',false);
    end if;
    -- Header lock plus READY -> CANCELLING fences the whole group before
    -- cancelling its exact unissued original transfer or releasing any hold.
    update private.bpay_next_run_worker set status='CANCELLING'
      where id=v_worker.id;
    update private.bpay_next_transfer set status='CANCELLED'
      where run_worker_id=v_worker.id;
    update private.bpay_next_cancel_request
      set status='CANCELLING',started_at_utc=v_now
      where command_id=v_job.command_id;
    update private.bpay_next_job set phase='RELEASE' where id=p_job_id;
    v_worker.status:='CANCELLING';
    v_request.status:='CANCELLING';
  end if;
  if v_request.status<>'CANCELLING' or v_worker.status<>'CANCELLING'
     or v_worker.realised_effect_count<>0
     or v_worker.financial_resolution_count<>0
     or v_control.pending_outcome_count<>0
     or v_run.status<>'DRAFT'
     or v_worker.captured_line_count<>v_request.expected_line_count then
    raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_FENCE_BROKEN';
  end if;
  v_cursor:=v_request.cursor_line_no;
  v_released:=v_request.released_line_count;
  for v_line in
    select l.id,l.line_no,l.work_id,l.component_key,l.source_consumed_ex_vat,
           l.frozen_ex_vat,l.frozen_vat,l.frozen_inc_vat
    from private.bpay_next_run_line l
    where l.run_worker_id=v_worker.id
      and l.line_no>coalesce(v_cursor,0)
    order by l.line_no,l.id limit p_limit
  loop
    select * into v_hold from private.bpay_next_hold
      where run_line_id=v_line.id for update;
    if found then
      if v_hold.status<>'ACTIVE'
         or v_hold.work_id<>v_line.work_id
         or v_hold.component_key<>v_line.component_key
         or v_hold.source_reserved_ex_vat<>v_line.source_consumed_ex_vat
         or v_hold.target_amount_ex_vat<>v_line.frozen_ex_vat
         or v_hold.target_amount_vat<>v_line.frozen_vat
         or v_hold.target_amount_inc_vat<>v_line.frozen_inc_vat then
        raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_HOLD_NOT_EXACT_ACTIVE';
      end if;
      update private.bpay_next_hold
        set status='RELEASED',finished_at_utc=v_now where id=v_hold.id;
      if not private.bpay_next_source_comparison_carry_known_work_v2(
        p_job_id,v_line.id,'RELEASE',v_hold.id) then
        update private.bpay_next_position
          set held_source_ex_vat=held_source_ex_vat-v_hold.source_reserved_ex_vat,
              held_target_ex_vat=held_target_ex_vat-v_hold.target_amount_ex_vat,
              held_target_vat=held_target_vat-v_hold.target_amount_vat,
              held_target_inc_vat=held_target_inc_vat-v_hold.target_amount_inc_vat,
              updated_at_utc=v_now
          where work_id=v_hold.work_id and component_key=v_hold.component_key
            and held_source_ex_vat>=v_hold.source_reserved_ex_vat
            and held_target_ex_vat>=v_hold.target_amount_ex_vat
            and held_target_vat>=v_hold.target_amount_vat
            and held_target_inc_vat>=v_hold.target_amount_inc_vat;
        if not found then
          raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_POSITION_HOLD_MISMATCH';
        end if;
      end if;
            v_holds_released:=v_holds_released+1;
    elsif v_line.source_consumed_ex_vat<>0 or v_line.frozen_ex_vat<>0
          or v_line.frozen_vat<>0 or v_line.frozen_inc_vat<>0 then
      raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_POSITIVE_HOLD_MISSING';
    end if;
    v_seen:=v_seen+1;
    v_released:=v_released+1;
    v_cursor:=v_line.line_no;
  end loop;
  if v_released>v_request.expected_line_count
     or (v_seen=0 and v_released<v_request.expected_line_count) then
    raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_FROZEN_LINE_COUNT_MISMATCH';
  end if;
  update private.bpay_next_cancel_request
    set cursor_line_no=v_cursor,released_line_count=v_released
    where command_id=v_job.command_id;
  update private.bpay_next_job
    set cursor_key=v_cursor::text,applied_line_count=v_released,
        lease_until_utc=pg_catalog.clock_timestamp()+pg_catalog.make_interval(secs=>120)
    where id=p_job_id;
  update private.bpay_next_worker_control
    set financial_view_revision=financial_view_revision+1,updated_at_utc=v_now
    where candidate_id=v_candidate_id;
  if v_released=v_request.expected_line_count then
    if exists(select 1 from private.bpay_next_run_line l
              where l.run_worker_id=v_worker.id
                and l.line_no>coalesce(v_cursor,0))
       or v_run.cancelled_candidate_count>=v_run.selected_candidate_count then
      raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_COMPLETION_COUNT_MISMATCH';
    end if;
    -- Preserve projection money and every frozen/audit row. Retire only its
    -- execution eligibility; no reprice, deletion, case/effect or payment.
    update private.bpay_next_net_projection set retired_at_utc=v_now
      where run_worker_id=v_worker.id and retired_at_utc is null;
    update private.bpay_next_run_worker set status='CANCELLED'
      where id=v_worker.id;
    update private.bpay_next_pay_run
      set cancelled_candidate_count=cancelled_candidate_count+1,
          status=case when cancelled_candidate_count+1=selected_candidate_count
            then 'CANCELLED' else status end
      where id=v_run.id;
    update private.bpay_next_cancel_request
      set status='CANCELLED',finished_at_utc=v_now
      where command_id=v_job.command_id;
    perform private.bpay_next_apply_cancelled_week_v1(p_job_id);
    update private.bpay_next_job
      set status='DONE',phase='CANCELLED',lease_nonce=null,lease_until_utc=null
      where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE'
      where id=v_job.command_id;
    return pg_catalog.jsonb_build_object('phase','CANCELLED',
      'run_worker_id',v_worker.id,'cursor',v_cursor,
      'released_line_count',v_released,'rows_visited',v_seen,
      'holds_released',v_holds_released,'replay',false);
  end if;
  return pg_catalog.jsonb_build_object('phase','CANCELLING',
    'run_worker_id',v_worker.id,'cursor',v_cursor,
    'released_line_count',v_released,'rows_visited',v_seen,
    'holds_released',v_holds_released,'replay',false);
end
$function$;

alter function private.bpay_next_simple_cancel_block_v1(uuid,boolean) OWNER TO CURRENT_USER;
alter function private.bpay_next_accept_simple_cancel_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_claim_simple_cancel_job_v1(uuid,integer) OWNER TO CURRENT_USER;
alter function private.bpay_next_cancel_simple_worker_page_v1(uuid,uuid,bigint,bigint,integer)
  OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_simple_cancel_block_v1(uuid,boolean),
  private.bpay_next_accept_simple_cancel_v1(uuid,uuid),
  private.bpay_next_claim_simple_cancel_job_v1(uuid,integer),
  private.bpay_next_cancel_simple_worker_page_v1(uuid,uuid,bigint,bigint,integer)
  from public,anon,authenticated,service_role;



-- Captured case facts are immutable; mutable capacity is a separate fact.
-- Owner-only additive guards. This file is not the allocation/posting owner.



create or replace function private.bpay_next_case_selection_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_run_status text;v_page private.bpay_next_case_selection_page%rowtype;
  v_count integer;v_selected integer;v_min_item integer;v_max_item integer;
  v_min_selection bigint;v_max_selection bigint;
begin
  if tg_op='DELETE' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_DELETE_FORBIDDEN';
  end if;
  select status into strict v_run_status from private.bpay_next_pay_run
    where id=new.run_id for share;
  if v_run_status<>'PREPARING' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_RUN_NOT_PREPARING';
  end if;
  if tg_op='INSERT' then
    if new.status<>'OPEN' or new.page_count<>0 or new.item_count<>0
       or new.selected_count<>0 or new.excluded_count<>0 or new.sealed_at_utc is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_DIRECT_SEAL_FORBIDDEN';
    end if;
    return new;
  end if;
  if old.status='SEALED' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_SEALED_IMMUTABLE';
  end if;
  if (new.run_id,new.candidate_id,new.selection_revision)
     is distinct from (old.run_id,old.candidate_id,old.selection_revision)
     or new.page_count<old.page_count or new.item_count<old.item_count
     or new.selected_count<old.selected_count or new.excluded_count<old.excluded_count then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_IDENTITY_OR_COUNT_CHANGED';
  end if;
  if new.status='SEALED' and
     (new.page_count,new.item_count,new.selected_count,new.excluded_count)
       is distinct from (old.page_count,old.item_count,old.selected_count,old.excluded_count) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_SEAL_COUNT_CHANGED';
  end if;
  if new.status='SEALED' and exists(select 1 from private.bpay_next_case_selection_page
      where run_id=old.run_id and candidate_id=old.candidate_id
        and selection_revision=old.selection_revision and page_no=old.page_count+1) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_UNCOUNTED_PAGE';
  end if;
  if new.status='OPEN' then
    if new.page_count<>old.page_count+1 then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_PAGE_COUNT_INVALID';
    end if;
    select * into strict v_page from private.bpay_next_case_selection_page
      where run_id=old.run_id and candidate_id=old.candidate_id
        and selection_revision=old.selection_revision and page_no=new.page_count;
    -- Only this exact <=100-row page is checked. Final seal trusts its
    -- transactionally maintained counters, never recounts the entire run.
    select count(*)::integer,count(*) filter(where is_selected)::integer,
      min(item_no),max(item_no),min(selection_no),max(selection_no)
      into v_count,v_selected,v_min_item,v_max_item,v_min_selection,v_max_selection
      from private.bpay_next_case_selection_item
      where run_id=old.run_id and candidate_id=old.candidate_id
        and selection_revision=old.selection_revision and page_no=new.page_count;
    if v_count<>v_page.item_count or v_selected<>v_page.selected_count
       or v_min_item<>1 or v_max_item<>v_count
       or v_min_selection<>old.item_count+1 or v_max_selection<>old.item_count+v_count
       or v_page.first_selection_no<>old.item_count+1
       or (new.item_count,new.selected_count,new.excluded_count) is distinct from
         (old.item_count+v_page.item_count,old.selected_count+v_page.selected_count,
           old.excluded_count+v_page.excluded_count) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_PAGE_CONTENT_MISMATCH';
    end if;
  end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_selection_child_insert_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_selection private.bpay_next_case_selection%rowtype;v_items integer;
begin
  select s.* into strict v_selection from private.bpay_next_case_selection s
    where (s.run_id,s.candidate_id,s.selection_revision)=
      (new.run_id,new.candidate_id,new.selection_revision) for share;
  if v_selection.status<>'OPEN' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_LATE_CHILD_FORBIDDEN';
  end if;
  if new.page_no<>v_selection.page_count+1 then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_CHILD_PAGE_OUT_OF_ORDER';
  end if;
  if tg_table_name='bpay_next_case_selection_item' then
    select item_count into strict v_items from private.bpay_next_case_selection_page
      where run_id=new.run_id and candidate_id=new.candidate_id
        and selection_revision=new.selection_revision and page_no=new.page_no for share;
    if new.item_no>v_items then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_SELECTION_CHILD_ITEM_OUT_OF_RANGE';
    end if;
  end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_rule_insert_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
begin
  if new.original_funding_event_id is not null and
     (new.case_kind not in ('LOAN','ADVANCE') or not exists(
       select 1 from private.bpay_next_case_event e
       where e.id=new.original_funding_event_id and e.case_id=new.case_id
         and e.event_kind='FUNDED' and e.occurred_at_utc=new.original_funded_at_utc)) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_RULE_FUNDING_EVIDENCE_INVALID';
  end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_event_insert_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_result private.bpay_next_case_allocation_result%rowtype;
  v_instruction private.bpay_next_run_case_instruction%rowtype;
begin
  if new.event_kind in ('FUNDED','RECOVERED','PAID','SHORTFALL') then
    if new.instruction_id is null or new.allocation_result_id is null then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_EVENT_TYPED_RESULT_REQUIRED';
    end if;
    select * into strict v_result from private.bpay_next_case_allocation_result
      where id=new.allocation_result_id for share;
    select * into strict v_instruction from private.bpay_next_run_case_instruction
      where id=new.instruction_id for share;
    if v_result.pass_kind not in ('DRAFT','NET') then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_EVENT_PREVIEW_NOT_FINANCIAL';
    end if;
    if new.event_kind in ('RECOVERED','SHORTFALL') and
       v_result.pass_kind is distinct from (case when new.hold_purpose='NET_RECOVERY_CAPACITY'
         and v_instruction.target_pay_channel='PAYE' then 'NET' else 'DRAFT' end) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_EVENT_RECOVERY_STAGE_INVALID';
    end if;
    if new.event_kind='SHORTFALL' then
      if new.shortfall_source_ex_vat is distinct from
         v_instruction.nominal_source_ex_vat-v_result.allocated_source_ex_vat
         or new.cap_reason is distinct from v_result.cap_reason then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_EVENT_SHORTFALL_MISMATCH';
      end if;
    elsif (new.source_amount_ex_vat,new.target_amount_ex_vat,new.target_amount_vat,new.target_amount_inc_vat)
       is distinct from (v_result.allocated_source_ex_vat,v_result.allocated_target_ex_vat,
         v_result.allocated_target_vat,v_result.allocated_target_inc_vat) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_EVENT_RESULT_AMOUNT_MISMATCH';
    end if;
  end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_instruction_insert_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_worker_status text;v_run_status text;v_selection_status text;
  v_preparation_revision bigint;v_selection_revision bigint;
begin
  -- Serialize insertion with confirmation/cancellation and exact selection
  -- seal; no latest Timesheet/rate/history lookup or post-Draft enrichment.
  select status into strict v_run_status from private.bpay_next_pay_run
    where id=new.run_id for share;
  select status,preparation_revision,case_selection_revision
    into strict v_worker_status,v_preparation_revision,v_selection_revision
    from private.bpay_next_run_worker
    where id=new.run_worker_id and candidate_id=new.candidate_id
      and run_id=new.run_id for share;
  select status into strict v_selection_status from private.bpay_next_case_selection
    where run_id=new.run_id and candidate_id=new.candidate_id
      and selection_revision=new.selection_revision for share;
  if v_worker_status<>'PREPARING' or v_run_status<>'PREPARING'
     or v_selection_status<>'SEALED' or v_preparation_revision<>new.preparation_revision
     or v_selection_revision<>new.selection_revision then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_INSTRUCTION_CAPTURE_STATE_INVALID';
  end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_result_insert_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_status text;v_instruction private.bpay_next_run_case_instruction%rowtype;
begin
  select s.status into strict v_status from private.bpay_next_case_allocation_state s
    where s.id=new.state_id for share;
  if v_status<>'BUILDING' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_RESULT_LATE_INSERT_FORBIDDEN';
  end if;
  select * into strict v_instruction from private.bpay_next_run_case_instruction
    where id=new.instruction_id for share;
  if new.nominal_target_ex_vat is distinct from v_instruction.nominal_target_ex_vat
     or new.allocated_source_ex_vat>v_instruction.nominal_source_ex_vat
     or new.allocated_target_ex_vat>v_instruction.nominal_target_ex_vat
     or new.allocated_target_vat>v_instruction.nominal_target_vat
     or new.allocated_target_inc_vat>v_instruction.nominal_target_inc_vat then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_RESULT_FROZEN_AMOUNT_EXCEEDED';
  end if;
  if not private.bpay_next_case_result_quote_valid_v2(v_instruction,new) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_RESULT_SELECTED_QUOTE_MISMATCH';end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_hold_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_result private.bpay_next_case_allocation_result%rowtype;
begin
  if tg_op='DELETE' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_HOLD_DELETE_FORBIDDEN';
  end if;
  if tg_op='INSERT' then
    if new.status<>'ACTIVE' or new.instruction_id is null or new.allocation_result_id is null then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_HOLD_TYPED_ACTIVE_REQUIRED';
    end if;
    select * into strict v_result from private.bpay_next_case_allocation_result
      where id=new.allocation_result_id for share;
    if v_result.pass_kind not in ('DRAFT','NET')
       or (new.source_reserved_ex_vat,new.target_amount_ex_vat,new.target_amount_vat,new.target_amount_inc_vat)
         is distinct from (v_result.allocated_source_ex_vat,v_result.allocated_target_ex_vat,
           v_result.allocated_target_vat,v_result.allocated_target_inc_vat) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_HOLD_RESULT_AMOUNT_MISMATCH';
    end if;
    return new;
  end if;
  -- Resizing a NET capacity uses a new exact result/hold after releasing its
  -- own prior hold. Never rewrite an old captured allocation to hide money.
  if old.status<>'ACTIVE' or new.status not in ('RELEASED','REALISED')
     or old.finished_at_utc is not null or new.finished_at_utc is null
     or not pg_catalog.isfinite(new.finished_at_utc)
     or (pg_catalog.to_jsonb(new)-'status'-'projection_id'-'finished_at_utc')
       is distinct from (pg_catalog.to_jsonb(old)-'status'-'projection_id'-'finished_at_utc')
     or (old.projection_id is not null and new.projection_id is distinct from old.projection_id)
     or (new.status='RELEASED' and new.projection_id is distinct from old.projection_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_HOLD_TRANSITION_INVALID';
  end if;
  return new;
end;
$function$;

create or replace function private.bpay_next_case_capacity_use_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_hold private.bpay_next_case_hold%rowtype;
begin
  if tg_op='DELETE' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_CAPACITY_DELETE_FORBIDDEN';
  end if;
  select * into strict v_hold from private.bpay_next_case_hold
    where id=new.case_hold_id for share;
  if tg_op='INSERT' then
    if new.status<>'ACTIVE' or v_hold.status<>'ACTIVE'
       or new.source_amount_ex_vat is distinct from v_hold.source_reserved_ex_vat then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_CAPACITY_INITIAL_STATE_INVALID';
    end if;
  elsif old.status<>'ACTIVE' or new.status not in ('RELEASED','REALISED')
     or (pg_catalog.to_jsonb(new)-'status'-'realisation_event_id')
       is distinct from (pg_catalog.to_jsonb(old)-'status'-'realisation_event_id')
     or v_hold.status<>new.status then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_CAPACITY_TRANSITION_INVALID';
  end if;
  if new.status='REALISED' and not exists(select 1 from private.bpay_next_case_event e
      where e.id=new.realisation_event_id and e.instruction_id=v_hold.instruction_id
        and e.allocation_result_id=v_hold.allocation_result_id
        and e.event_kind in ('FUNDED','RECOVERED','PAID')
        and (e.source_amount_ex_vat,e.target_amount_ex_vat,e.target_amount_vat,e.target_amount_inc_vat)=
          (v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat)) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_CAPACITY_EVENT_MISMATCH';
  end if;
  return new;
end;
$function$;

do $install$
declare v_table text;
begin
  foreach v_table in array array['bpay_next_case_rule','bpay_next_run_case_instruction',
    'bpay_next_case_selection_page','bpay_next_case_selection_item','bpay_next_case_allocation_result'] loop
    execute pg_catalog.format('drop trigger if exists bpay_next_case_fact_immutable_v1 on private.%I',v_table);
    execute pg_catalog.format('create trigger bpay_next_case_fact_immutable_v1 before update or delete on private.%I for each row execute function private.bpay_next_effect_immutable_v1()',v_table);
  end loop;
  foreach v_table in array array['bpay_next_case_selection_page','bpay_next_case_selection_item'] loop
    execute pg_catalog.format('drop trigger if exists bpay_next_case_child_insert_v1 on private.%I',v_table);
    execute pg_catalog.format('create trigger bpay_next_case_child_insert_v1 before insert on private.%I for each row execute function private.bpay_next_case_selection_child_insert_guard_v1()',v_table);
  end loop;
end;
$install$;

drop trigger if exists bpay_next_case_selection_guard_v1 on private.bpay_next_case_selection;
create trigger bpay_next_case_selection_guard_v1 before insert or update or delete
  on private.bpay_next_case_selection for each row execute function private.bpay_next_case_selection_guard_v1();
drop trigger if exists bpay_next_case_instruction_insert_v1 on private.bpay_next_run_case_instruction;
create trigger bpay_next_case_instruction_insert_v1 before insert
  on private.bpay_next_run_case_instruction for each row execute function private.bpay_next_case_instruction_insert_guard_v1();
drop trigger if exists bpay_next_case_rule_insert_v1 on private.bpay_next_case_rule;
create trigger bpay_next_case_rule_insert_v1 before insert
  on private.bpay_next_case_rule for each row execute function private.bpay_next_case_rule_insert_guard_v1();
drop trigger if exists bpay_next_case_event_insert_v1 on private.bpay_next_case_event;
create trigger bpay_next_case_event_insert_v1 before insert
  on private.bpay_next_case_event for each row execute function private.bpay_next_case_event_insert_guard_v1();
drop trigger if exists bpay_next_case_result_insert_v1 on private.bpay_next_case_allocation_result;
create trigger bpay_next_case_result_insert_v1 before insert
  on private.bpay_next_case_allocation_result for each row execute function private.bpay_next_case_result_insert_guard_v1();
drop trigger if exists bpay_next_case_hold_guard_v1 on private.bpay_next_case_hold;
create trigger bpay_next_case_hold_guard_v1 before insert or update or delete
  on private.bpay_next_case_hold for each row execute function private.bpay_next_case_hold_guard_v1();
drop trigger if exists bpay_next_case_capacity_use_guard_v1 on private.bpay_next_case_capacity_use;
create trigger bpay_next_case_capacity_use_guard_v1 before insert or update or delete
  on private.bpay_next_case_capacity_use for each row execute function private.bpay_next_case_capacity_use_guard_v1();

alter function private.bpay_next_case_selection_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_selection_child_insert_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_instruction_insert_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_result_insert_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_hold_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_capacity_use_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_rule_insert_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_event_insert_guard_v1() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_case_selection_guard_v1(),
  private.bpay_next_case_selection_child_insert_guard_v1(),
  private.bpay_next_case_instruction_insert_guard_v1(),
  private.bpay_next_case_result_insert_guard_v1(),
  private.bpay_next_case_hold_guard_v1(),private.bpay_next_case_capacity_use_guard_v1(),
  private.bpay_next_case_rule_insert_guard_v1(),private.bpay_next_case_event_insert_guard_v1()
  from public,anon,authenticated,service_role;


-- Actual FINANCE_ALLOCATE continuation for PREPARE. Selected case capture,
-- same-channel PAYE valuation and age-ordered DRAFT allocation share the
-- existing Candidate lane. No legacy calculator/history or fictitious WORK.
-- This is NOT the later PAYE NET, posting, cancellation or return owner.



create or replace function private.bpay_next_prepare_case_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,
  p_expected_cursor bigint default null,p_limit integer default 100
) returns jsonb
language plpgsql security invoker
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_saved_cursor bigint;
  v_run private.bpay_next_pay_run%rowtype;
  v_control private.bpay_next_worker_control%rowtype;
  v_job private.bpay_next_job%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_selection private.bpay_next_case_selection%rowtype;
  v_state private.bpay_next_case_allocation_state%rowtype;
  v_channel private.bpay_next_case_allocation_channel%rowtype;
  v_week private.bpay_next_worker_week%rowtype;
  v_case private.bpay_next_finance_case%rowtype;
  v_component private.bpay_next_case_component%rowtype;
  v_rule private.bpay_next_case_rule%rowtype;
  v_period_rule private.bpay_next_case_rule%rowtype;
  v_origin private.bpay_next_case_create_request%rowtype;
  v_collection private.bpay_next_work_collection%rowtype;
  v_policy_id uuid;
  v_cmp private.bpay_next_source_comparison_receipt%rowtype;
  v_position private.bpay_next_position%rowtype;
  v_win private.bpay_next_valuation_policy_window%rowtype;
  v_snapshot jsonb;v_nominal_q jsonb;v_capacity_q jsonb;v_slice jsonb;
  v_source_taken numeric;v_taken_vat numeric;v_taken_inc numeric;v_gross_vat numeric;
  v_resolution_ref text;v_carry jsonb;
  v_automatic boolean;
  v_period private.bpay_next_case_period%rowtype;
  v_item record;v_prior record;v_value record;v_row record;
  v_instruction private.bpay_next_run_case_instruction%rowtype;
  v_floor numeric;v_outstanding numeric;v_case_outstanding numeric;
  v_nominal numeric;v_opening_due numeric;v_capacity numeric;v_taken numeric;v_e numeric;v_h numeric;
  v_next_e numeric;v_next_h numeric;
  v_gross numeric;v_week_start date;v_age timestamptz;v_age_key bigint;
  v_purpose text;v_explanation text;v_issue text;v_seen bigint:=0;
  v_result_id uuid;v_hold_id uuid;v_instruction_id uuid;v_has_more boolean;v_terminal boolean:=false;
  v_cap_reason text;v_affordability_reason text;v_capacity_reason text;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null or p_owner_epoch<1
     or p_expected_cursor<0 or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_PREPARE_INPUT_INVALID';
  end if;
  select rc.run_id,j.candidate_id into strict v_run_id,v_candidate
    from private.bpay_next_job j join private.bpay_next_run_command rc on rc.command_id=j.command_id
    where j.id=p_job_id and j.job_kind='PREPARE';
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  -- Same lock order as the real lane; root UPDATE fences confirmation/cancel.
  select r.* into strict v_run from private.bpay_next_pay_run r where r.id=v_run_id for update;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_candidate for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    where w.run_id=v_run_id and w.candidate_id=v_candidate for update;
  select s.* into v_state from private.bpay_next_case_allocation_state s where s.job_id=p_job_id
    and s.run_worker_id=v_worker.id and s.pass_kind='DRAFT' and s.projection_no=0 for update;
  if v_job.module_epoch<>v_epoch then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_PREPARE_OWNER_STALE';
  end if;
  if v_job.status='DONE' and v_job.phase='READY' and v_state.status='COMPLETE'
     and v_worker.status in ('READY','DRAFT','ISSUED','COMPLETE','CANCELLING','CANCELLED') then
    return pg_catalog.jsonb_build_object('done',true,'phase','READY','cursor',null,'rows_visited','0',
      'replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status);
  end if;
  if v_job.status='DONE' and v_job.phase='DONE' and v_worker.status='REVIEW'
     and v_worker.review_issue_code in ('CASE_SELECTION_REQUIRED','CASE_TARGET_UNSUPPORTED','CASE_INPUT_UNBOUND',
       'CASE_WEEK_BASIS_UNBOUND','CASE_RETURN_FLOOR_UNBOUND','CASE_SOURCE_PARTITION_REVIEW_REQUIRED','CASE_NO_PAYABLE_AMOUNT') then
    return pg_catalog.jsonb_build_object('done',true,'phase','REVIEW','cursor',null,'rows_visited','0',
      'replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status,'issue_code',v_worker.review_issue_code);
  end if;
  if v_run.status<>'PREPARING' or v_run.selection_state<>'SEALED' or v_job.status<>'LEASED'
     or v_job.phase<>'FINANCE_ALLOCATE' or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() or v_control.active_owner_epoch<>p_owner_epoch
     or v_worker.status<>'PREPARING' or v_worker.review_issue_code is not null
     or v_worker.financial_resolution_count<>0 then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_PREPARE_STATE_INVALID';
  end if;
  if v_worker.captured_position_count<>v_worker.captured_line_count+v_worker.captured_managed_position_count
     or v_worker.expected_managed_position_count<>v_worker.captured_managed_position_count
     or exists(select 1 from private.bpay_next_run_position where run_worker_id=v_worker.id
       and work_collection_id is not null and not managed_capture_completed) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_LINE_COUNT_MISMATCH';
  end if;
  if v_job.cursor_key is not null and v_job.cursor_key !~ '^[0-9]{1,19}$' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_CURSOR_CORRUPT';
  end if;
  v_saved_cursor:=coalesce(v_job.cursor_key::bigint,0);
  if coalesce(p_expected_cursor,0)<v_saved_cursor then
    -- Lost STEP reply: read back the persisted checkpoint without a second
    -- capture, hold, cursor spend or financial-view bump. Ahead is not replay.
    return pg_catalog.jsonb_build_object('done',false,'phase','FINANCE_ALLOCATE','cursor',v_job.cursor_key,
      'rows_visited','0','replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status);
  end if;
  if coalesce(p_expected_cursor,0)>v_saved_cursor then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_PREPARE_CURSOR_STALE';
  end if;
  -- Only a positively proved no-case context may retain the old owner path.
  if v_state.id is null and not exists(select 1 from private.bpay_next_finance_case c where c.candidate_id=v_candidate)
     and not exists(select 1 from private.bpay_next_case_selection s where s.run_id=v_run_id and s.candidate_id=v_candidate) then
    return private.bpay_next_complete_no_case_worker_v1(p_job_id,p_lease_nonce,p_owner_epoch);
  end if;

  <<prepare_page>>
  begin
    if v_state.id is null then
      select s.* into v_selection from private.bpay_next_case_selection s
        where s.run_id=v_run_id and s.candidate_id=v_candidate order by s.selection_revision desc limit 1;
      if v_selection.run_id is null or v_selection.status<>'SEALED' then
        v_issue:='CASE_SELECTION_REQUIRED';exit prepare_page;
      end if;
      if v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
         or v_worker.gross_inc_vat<>v_worker.gross_ex_vat+v_worker.gross_vat
         or (v_worker.target_pay_channel='PAYE' and v_worker.gross_vat<>0)
         or (v_worker.target_pay_channel='UMBRELLA' and (v_worker.target_umbrella_id is null
           or v_worker.target_umbrella_vat_chargeable is null or v_worker.entered_paye_net is not null
           or v_worker.net_request_revision<>0 or v_worker.net_projection_revision<>0)) then
        v_issue:='CASE_TARGET_UNSUPPORTED';exit prepare_page;
      end if;
      select c.min_take_home_wtd into strict v_floor from public.candidates c where c.id=v_candidate for share;
      if v_floor is null or v_floor::text in ('NaN','Infinity','-Infinity') or v_floor<0
         or v_floor<>pg_catalog.trunc(v_floor,2) then
        v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
      end if;
      v_week_start:=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1);
      -- Exact indexed metadata absence is required BEFORE establishing a new
      -- zero week. Missing prior NEW facts are unresolved, not zero/history SUM.
      if exists(select 1 from private.bpay_next_run_worker w
        join private.bpay_next_pay_run r on r.id=w.run_id
        where w.candidate_id=v_candidate and w.status in ('READY','DRAFT','ISSUED','COMPLETE')
          and r.pay_date>=v_week_start and r.pay_date<v_week_start+7
          and (r.pay_date,r.created_at_utc,w.id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and not exists(select 1 from private.bpay_next_worker_week_contribution x where x.original_run_worker_id=w.id)) then
        v_issue:='CASE_WEEK_BASIS_UNBOUND';exit prepare_page;
      end if;
      insert into private.bpay_next_worker_week(candidate_id,pay_week_start,period_revision,
        default_floor,default_floor_revision,resolved_arranged_take_home)
        values(v_candidate,v_week_start,1,v_floor,1,0) on conflict(candidate_id,pay_week_start) do nothing;
      select w.* into strict v_week from private.bpay_next_worker_week w
        where w.candidate_id=v_candidate and w.pay_week_start=v_week_start for update;
      if v_week.unresolved_contribution_count<>0 then v_issue:='CASE_WEEK_BASIS_UNBOUND';exit prepare_page;end if;
      if v_week.default_floor<>v_floor then
        update private.bpay_next_worker_week set default_floor=v_floor,default_floor_revision=default_floor_revision+1,
          period_revision=period_revision+1 where candidate_id=v_candidate and pay_week_start=v_week_start returning * into v_week;
      end if;
      update private.bpay_next_run_worker set case_selection_revision=v_selection.selection_revision where id=v_worker.id;
      v_worker.case_selection_revision:=v_selection.selection_revision;
      insert into private.bpay_next_case_allocation_state
        (run_worker_id,run_id,candidate_id,selection_revision,preparation_revision,pass_kind,projection_no,
         command_id,job_id,module_epoch,owner_epoch,financial_view_revision,status,weekly_binding_state,
         expected_instruction_count,initial_worker_take_home,remaining_worker_take_home,prepare_stage,
         captured_default_floor,captured_default_floor_revision,pay_week_start,captured_week_revision,captured_work_gross)
        values(v_worker.id,v_run_id,v_candidate,v_selection.selection_revision,v_worker.preparation_revision,'DRAFT',0,
         v_job.command_id,p_job_id,v_epoch,p_owner_epoch,v_control.financial_view_revision,'BUILDING','UNBOUND',
         v_selection.selected_count,v_worker.gross_ex_vat,v_worker.gross_ex_vat,'WEEK_CAPTURE',
         v_floor,v_week.default_floor_revision,v_week_start,v_week.period_revision,v_worker.gross_ex_vat)
        returning * into v_state;
      update private.bpay_next_case_allocation_state set captured_work_vat=v_worker.gross_vat where id=v_state.id;
      v_state.captured_work_vat:=v_worker.gross_vat;
      insert into private.bpay_next_case_allocation_channel(state_id,allocation_channel,initial_headroom,remaining_headroom)
        values(v_state.id,v_worker.target_pay_channel,v_worker.gross_ex_vat,v_worker.gross_ex_vat);
    else
      if v_state.status<>'BUILDING' or v_state.preparation_revision<>v_worker.preparation_revision
         or v_state.selection_revision<>v_worker.case_selection_revision or v_state.prepare_stage='NOT_CASE_PREPARE' then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_BINDING_MISMATCH';
      end if;
      -- Lease takeover does not reset the captured economic cursors/headroom.
      if v_state.owner_epoch<>p_owner_epoch then
        update private.bpay_next_case_allocation_state set owner_epoch=p_owner_epoch where id=v_state.id;
        v_state.owner_epoch:=p_owner_epoch;
      end if;
    end if;

    if v_state.prepare_stage='WEEK_CAPTURE' then
      for v_prior in select x.* from private.bpay_next_worker_week_contribution x
        where x.candidate_id=v_candidate and x.pay_week_start=v_state.pay_week_start
          and (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
            <(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and (v_state.prior_worker_cursor is null or
            (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
              >(v_state.prior_pay_date_cursor,v_state.prior_created_at_cursor,v_state.prior_worker_cursor))
        order by x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id limit p_limit
      loop
        v_seen:=v_seen+1;
        if v_prior.eligibility_state='UNBOUND' then
          v_issue:=case when v_prior.payment_state in ('RETURNED_OWED','REISSUED_PAID')
            then 'CASE_RETURN_FLOOR_UNBOUND' else 'CASE_WEEK_BASIS_UNBOUND' end;
          exit prepare_page;
        end if;
        v_state.captured_prior_take_home:=v_state.captured_prior_take_home+v_prior.eligible_arranged_amount;
        v_state.initial_worker_take_home:=v_state.initial_worker_take_home+v_prior.eligible_arranged_amount;
        v_state.remaining_worker_take_home:=v_state.remaining_worker_take_home+v_prior.eligible_arranged_amount;
        v_state.prior_pay_date_cursor:=v_prior.original_pay_date;
        v_state.prior_created_at_cursor:=v_prior.original_created_at_utc;
        v_state.prior_worker_cursor:=v_prior.original_run_worker_id;
      end loop;
      select exists(select 1 from private.bpay_next_worker_week_contribution x
        where x.candidate_id=v_candidate and x.pay_week_start=v_state.pay_week_start
          and (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and (v_state.prior_worker_cursor is null or (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
            >(v_state.prior_pay_date_cursor,v_state.prior_created_at_cursor,v_state.prior_worker_cursor))) into v_has_more;
      update private.bpay_next_case_allocation_state set captured_prior_take_home=v_state.captured_prior_take_home,
        initial_worker_take_home=v_state.initial_worker_take_home,remaining_worker_take_home=v_state.remaining_worker_take_home,
        prior_pay_date_cursor=v_state.prior_pay_date_cursor,prior_created_at_cursor=v_state.prior_created_at_cursor,
        prior_worker_cursor=v_state.prior_worker_cursor,weekly_binding_state=case when v_has_more then 'UNBOUND' else 'BOUND' end,
        prepare_stage=case when v_has_more then 'WEEK_CAPTURE' else 'INSTRUCTION_CAPTURE' end where id=v_state.id;
      exit prepare_page;
    end if;

    if v_state.prepare_stage='INSTRUCTION_CAPTURE' then
      for v_item in select i.* from private.bpay_next_case_selection_item i
        where i.run_id=v_run_id and i.candidate_id=v_candidate and i.selection_revision=v_state.selection_revision
          and i.is_selected and i.selection_no>v_state.instruction_capture_cursor order by i.selection_no limit p_limit
      loop
        v_seen:=v_seen+1;
        v_cmp:=null;v_position:=null;
        select c.* into v_collection from private.bpay_next_work_collection c
          where c.case_id=v_item.case_id and c.case_component_id=v_item.case_component_id and c.candidate_id=v_candidate;
        if v_collection.id is not null then
          select p.* into strict v_position from private.bpay_next_position p
            where p.work_id=v_collection.work_id and p.component_key=v_collection.component_key for update;
          if v_position.source_comparison_receipt_id is not null then
            select r.* into strict v_cmp from private.bpay_next_source_comparison_receipt r where r.id=v_position.source_comparison_receipt_id;
            v_cmp:=private.bpay_next_source_comparison_current_v2(v_cmp.source_binding_version_id,
              v_position.source_book_revision,v_position.source_comparison_receipt_id);
            if v_cmp.target_pay_channel<>v_worker.target_pay_channel
              or (v_cmp.target_pay_channel='UMBRELLA' and v_cmp.umbrella_vat_chargeable is distinct from v_worker.target_umbrella_vat_chargeable)
              or v_cmp.case_resolution is null
              or v_cmp.case_component_id<>v_item.case_component_id then
              v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;end if;
          end if;
        end if;
        select c.* into strict v_case from private.bpay_next_finance_case c where c.id=v_item.case_id and c.candidate_id=v_candidate for update;
        select c.* into strict v_component from private.bpay_next_case_component c
          where c.id=v_item.case_component_id and c.case_id=v_case.id and c.candidate_id=v_candidate for update;
        select r.* into v_rule from private.bpay_next_case_rule r where r.id=v_case.current_rule_id
          and r.case_id=v_case.id and r.candidate_id=v_candidate and r.rule_revision=v_case.current_rule_revision;
        select r.* into v_origin from private.bpay_next_case_create_request r where r.case_id=v_case.id and r.candidate_id=v_candidate;
        v_collection:=private.bpay_next_work_collection_origin_v1(v_case.id,v_component.id,v_candidate);
        v_automatic:=v_collection.id is not null;
        if v_rule.id is null or v_case.case_revision<1 or v_component.rule_id<>v_rule.id then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        if v_automatic then
          -- Genuine paid WORK origin, not a fabricated CASE_CREATE receipt.
          -- The immutable original paid policy and the exact applied position
          -- are authority; a newer queued WORK approval is not a reprice.
          if v_origin.command_id is not null then v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;end if;
          v_policy_id:=case when v_cmp.id is null then v_collection.original_valuation_policy_id else v_cmp.comparison_policy_id end;
        elsif v_origin.command_id is null
           or v_component.rule_id<>v_rule.id or v_origin.case_kind<>v_case.case_kind
           or v_origin.source_pay_channel<>v_component.source_pay_channel
           or v_origin.principal_source_ex_vat<>v_component.approved_source_ex_vat
           or (v_component.id<>v_origin.primary_component_id
             and (v_origin.recovery_component_id is null or v_component.id<>v_origin.recovery_component_id))
           or (v_component.id=v_origin.primary_component_id and v_component.instruction_kind<>
             case when v_case.case_kind in ('LOAN','ADVANCE') then 'PAYOUT'
               when v_case.case_kind='CREDIT' then 'CREDIT' else 'RECOVERY' end)
           or (v_component.id=v_origin.recovery_component_id and v_component.instruction_kind<>'RECOVERY') then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        else
          v_policy_id:=v_origin.valuation_policy_id;
        end if;
        if v_component.source_pay_channel not in ('PAYE','UMBRELLA')
          or ((v_component.source_pay_channel='UMBRELLA' or v_worker.target_pay_channel='UMBRELLA')
            and v_component.tax_treatment<>'TAXABLE') then
          v_issue:='CASE_TARGET_UNSUPPORTED';exit prepare_page;
        end if;
        v_explanation:='Exact approved case; same-channel PAYE current basis captured';
        v_outstanding:=case when v_component.case_kind in ('LOAN','ADVANCE') then v_component.funded_source_ex_vat
          else v_component.approved_source_ex_vat end-v_component.recovered_source_ex_vat-v_component.written_off_source_ex_vat;
        v_case_outstanding:=case when v_case.case_kind in ('LOAN','ADVANCE') then v_case.principal_funded
          else v_case.principal_approved end-v_case.principal_recovered-v_case.principal_written_off-v_case.principal_paid_credit;
        if v_component.instruction_kind='RECOVERY' then
          if v_automatic then
            -- Retained automatic OVERPAYMENT policy has no instalment. Its
            -- remaining principal already excludes realised recovery and W;
            -- capacity below subtracts each disjoint active hold only once.
            v_nominal:=least(v_outstanding,v_case_outstanding);
            v_explanation:='Exact original ordinary PAYE collection; remaining outstanding, no instalment';
          else
          if v_rule.weekly_due_source_ex_vat is null then v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;end if;
          if v_case.case_kind in ('LOAN','ADVANCE') and v_case.principal_funded>0
             and (v_rule.original_funding_event_id is null or v_rule.original_funded_at_utc is null) then
            v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
          end if;
          v_nominal:=case when v_state.pay_week_start>=v_rule.next_due_monday
            then least(v_rule.weekly_due_source_ex_vat,v_outstanding,v_case_outstanding) else 0 end;
          if v_case.case_kind in ('LOAN','ADVANCE') and v_case.principal_funded=0 then
            v_nominal:=0;v_explanation:='Approved loan/advance is unfunded; repayment not eligible';
          elsif v_state.pay_week_start<v_rule.next_due_monday then
            v_explanation:='Repayment schedule is not yet due in the pay-date week';
          end if;
          end if;
          v_purpose:=case when v_component.payroll_stage='GROSS_DEDUCT' then 'GROSS_RECOVERY' else 'NET_RECOVERY_CAPACITY' end;
        else
          v_outstanding:=v_component.approved_source_ex_vat-v_component.funded_source_ex_vat
            -v_component.paid_credit_source_ex_vat-v_component.written_off_source_ex_vat;
          v_case_outstanding:=v_case.principal_approved-v_case.principal_funded
            -v_case.principal_paid_credit-v_case.principal_written_off;
          v_nominal:=least(v_outstanding,v_case_outstanding);v_purpose:='PAYOUT';
        end if;
        -- Weekly due exists independently of this particular arrangement's
        -- eligibility. An early/paused selection must not make the whole
        -- week's legitimate opening due permanently zero for later pay dates.
        v_opening_due:=case when v_component.instruction_kind='RECOVERY' then v_nominal else 0 end;
        if v_case.status<>'OPEN' or (v_case.due_date is not null and v_case.due_date>v_run.pay_date) then
          v_nominal:=0;v_explanation:='Selected case is not currently open/due; no reservation';
        end if;
        if v_outstanding<0 or v_case_outstanding<0 or v_nominal<0 then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        -- Opening due is independent of later principal. Never subtract the
        -- same realised recovery twice or use max(overlapping counters).
        insert into private.bpay_next_case_period(case_component_id,case_id,candidate_id,pay_week_start,rule_id,
          period_revision,opening_outstanding_source_ex_vat,opening_due_source_ex_vat,work_collection_id)
          values(v_component.id,v_case.id,v_candidate,v_state.pay_week_start,v_rule.id,1,v_outstanding,
            v_opening_due,case when v_automatic then v_collection.id else null end)
          on conflict(case_component_id,pay_week_start) do nothing;
        select p.* into strict v_period from private.bpay_next_case_period p
          where p.case_component_id=v_component.id and p.pay_week_start=v_state.pay_week_start for update;
        if v_period.work_collection_id is distinct from (case when v_automatic then v_collection.id else null end) then
          v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
        end if;
        if v_period.rule_id<>v_rule.id then
          -- Genuine original funding advances an immutable loan rule solely
          -- to bind its age/evidence. It is NOT a schedule/policy reprice.
          select * into strict v_period_rule from private.bpay_next_case_rule where id=v_period.rule_id;
          if v_case.case_kind not in ('LOAN','ADVANCE') or v_rule.original_funding_event_id is null
             or (v_period_rule.case_id,v_period_rule.candidate_id,v_period_rule.case_kind,v_period_rule.case_subtype,
               v_period_rule.tax_treatment,v_period_rule.case_created_at_utc,v_period_rule.minimum_earnings_threshold,
               v_period_rule.take_home_floor_override,v_period_rule.weekly_due_source_ex_vat,v_period_rule.schedule_start_monday,
               v_period_rule.next_due_monday,v_period_rule.schedule_week_count)
               is distinct from (v_rule.case_id,v_rule.candidate_id,v_rule.case_kind,v_rule.case_subtype,
                 v_rule.tax_treatment,v_rule.case_created_at_utc,v_rule.minimum_earnings_threshold,v_rule.take_home_floor_override,
                 v_rule.weekly_due_source_ex_vat,v_rule.schedule_start_monday,v_rule.next_due_monday,v_rule.schedule_week_count)
             or not exists(select 1 from private.bpay_next_case_event e where e.id=v_rule.original_funding_event_id
               and e.case_id=v_case.id and e.event_kind='FUNDED' and e.occurred_at_utc=v_rule.original_funded_at_utc)
             or (v_period_rule.original_funding_event_id is not null and
               (v_period_rule.original_funding_event_id,v_period_rule.original_funded_at_utc)
                 is distinct from (v_rule.original_funding_event_id,v_rule.original_funded_at_utc)) then
            v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
          end if;
          if v_component.instruction_kind='RECOVERY' and v_period_rule.original_funding_event_id is null then
            if (v_period.opening_outstanding_source_ex_vat,v_period.opening_due_source_ex_vat,
                v_period.realised_recovery_source_ex_vat,v_period.active_unrealised_recovery_source_ex_vat,v_period.active_payout_source_ex_vat)
                is distinct from (0::numeric,0::numeric,0::numeric,0::numeric,0::numeric) then
              v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
            end if;
            -- Only this exact zero/unconsumed pay-week is made ready. Its
            -- frozen old zero instructions/results remain immutable and zero.
            update private.bpay_next_case_period set rule_id=v_rule.id,opening_outstanding_source_ex_vat=v_outstanding,
              opening_due_source_ex_vat=v_opening_due,period_revision=period_revision+1
              where case_component_id=v_component.id and pay_week_start=v_state.pay_week_start returning * into v_period;
          end if;
          -- A consumed funded period (or original payout period) retains its
          -- recorded opening rule and counters; only the new instruction's
          -- captured_rule_id/age advance to the genuine current funded rule.
        end if;
        v_capacity:=case when v_automatic then
          least(v_nominal,greatest(v_outstanding-v_component.active_recovery_source_ex_vat,0),
            greatest(v_case_outstanding-v_case.active_recovery_hold_amount,0))
          when v_component.instruction_kind='RECOVERY' then
          least(v_nominal,greatest(v_period.opening_due_source_ex_vat-v_period.realised_recovery_source_ex_vat
            -v_period.active_unrealised_recovery_source_ex_vat,0),
            greatest(v_outstanding-v_component.active_recovery_source_ex_vat,0),
            greatest(v_case_outstanding-v_case.active_recovery_hold_amount,0))
          else least(v_nominal,greatest(v_outstanding-v_component.active_payout_source_ex_vat,0),
            greatest(v_case_outstanding-v_case.active_payout_hold_amount,0)) end;
        if v_cmp.id is not null then
          select w.* into strict v_win from private.bpay_next_valuation_policy_window w
            where w.policy_id=v_cmp.comparison_policy_id and w.source_window_id=v_cmp.policy_window_id;
          v_snapshot:=jsonb_build_object('selected_mode',v_cmp.case_resolution->>'selected_mode',
            'source_pay_channel',v_component.source_pay_channel,'target_pay_channel',v_worker.target_pay_channel,
            'source_basis_ex_vat',(v_cmp.case_resolution->>'source_outstanding_ex_vat')::numeric,
            'selected_quote',v_cmp.case_resolution->'selected_quote','comparison_policy_id',v_cmp.comparison_policy_id,
            'policy_window_id',v_cmp.policy_window_id,'effective_pay_date',v_cmp.effective_pay_date,
            'erni_pct',v_win.erni_pct,'vat_rate_pct',v_win.vat_rate_pct,'umbrella_vat_chargeable',v_cmp.umbrella_vat_chargeable);
          v_nominal:=least(v_nominal,(v_snapshot->>'source_basis_ex_vat')::numeric);
          v_capacity:=least(v_capacity,v_nominal);
          v_resolution_ref:='SOURCE_COMPARISON:'||v_cmp.id::text;
          -- Capturing an instruction does not mutate the accepted Case basis.
          -- Only the actual hold operation below advances SOURCE J/revisions.
        else
          begin
            select x.* into strict v_value from private.bpay_next_value_source_for_target_v1(
              v_component.approved_source_ex_vat,v_component.source_pay_channel,v_worker.target_pay_channel,
              v_worker.target_umbrella_vat_chargeable,v_policy_id,v_run.pay_date) x;
          exception when check_violation then
            if sqlerrm in ('BPAY_NEXT_TARGET_POLICY_WINDOW_MISSING','BPAY_NEXT_TARGET_POLICY_WINDOW_AMBIGUOUS') then
              v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;else raise;end if;
          end;
          select w.* into strict v_win from private.bpay_next_valuation_policy_window w
            where w.policy_id=v_policy_id and w.source_window_id=v_value.policy_window_id;
          v_snapshot:=jsonb_build_object('selected_mode','SUGGESTED_EQUIVALENT_BASIS',
            'source_pay_channel',v_component.source_pay_channel,'target_pay_channel',v_worker.target_pay_channel,
            'source_basis_ex_vat',v_component.approved_source_ex_vat,
            'selected_quote',private.pay_finance_selected_quote_v1('SUGGESTED_EQUIVALENT_BASIS',
              v_component.approved_source_ex_vat,v_component.source_pay_channel,v_worker.target_pay_channel,
              null,null,null,v_win.erni_pct,v_win.vat_rate_pct,v_worker.target_umbrella_vat_chargeable),
            'comparison_policy_id',v_policy_id,'policy_window_id',v_value.policy_window_id,'effective_pay_date',v_run.pay_date,
            'erni_pct',v_win.erni_pct,'vat_rate_pct',v_win.vat_rate_pct,
            'umbrella_vat_chargeable',v_worker.target_umbrella_vat_chargeable);
          v_resolution_ref:=case when v_automatic then 'WORK_COLLECTION:'||v_collection.id::text||':'||v_worker.target_pay_channel
            else 'CASE_CREATE:'||v_origin.command_id::text||':'||v_worker.target_pay_channel end;
          update private.bpay_next_case_component set resolution_state='RESOLVED',target_pay_channel=v_worker.target_pay_channel,
            target_ex_vat=v_value.target_ex_vat,target_vat=v_value.target_vat,target_inc_vat=v_value.target_inc_vat,
            valuation_policy_id=v_policy_id,valuation_window_id=v_value.policy_window_id,resolution_ref=v_resolution_ref,
            component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp()
            where id=v_component.id returning * into v_component;
        end if;
        v_nominal_q:=private.bpay_next_case_quote_from_snapshot_v2(v_snapshot,v_nominal);
        v_capacity_q:=private.bpay_next_case_quote_from_snapshot_v2(v_snapshot,v_capacity);
        v_age:=coalesce(v_rule.original_funded_at_utc,v_rule.case_created_at_utc);
        -- A genuinely bound stored credit keeps its original creator age. The
        -- exact point sidecar is immutable, not a live legacy money read.
        if not v_automatic then
          select coalesce(o.original_created_at_utc,v_age) into v_age
            from (select 1) s left join private.bpay_next_stored_credit_origin o
              on o.command_id=v_component.id and o.candidate_id=v_candidate;
        end if;
        v_age_key:=(extract(epoch from v_age)*1000000)::bigint;
        insert into private.bpay_next_run_case_instruction
          (run_worker_id,run_id,candidate_id,selection_revision,preparation_revision,case_component_id,case_id,
           captured_case_revision,captured_component_revision,captured_period_revision,rule_id,rule_revision,
           case_kind,case_subtype,tax_treatment,instruction_kind,direction,payroll_stage,hold_purpose,
           age_key,debt_age_at_utc,component_ordinal,pay_week_start,source_pay_channel,target_pay_channel,allocation_channel,currency,
           nominal_source_ex_vat,nominal_target_ex_vat,nominal_target_vat,nominal_target_inc_vat,
           capacity_source_ex_vat,capacity_target_ex_vat,capacity_target_vat,capacity_target_inc_vat,
           minimum_earnings_threshold,take_home_floor_override,captured_default_floor,captured_default_floor_revision,
           resolved_take_home_floor,valuation_policy_id,valuation_window_id,resolution_ref,explanation,work_collection_id,
           selected_quote_snapshot,source_comparison_receipt_id,source_binding_version_id,canonical_source_work_id,
           canonical_source_component_key,source_approval_work_id,source_approval_revision_id,source_approval_component_key,
           source_approval_state,source_approved_line_id)
          values(v_worker.id,v_run_id,v_candidate,v_state.selection_revision,v_worker.preparation_revision,v_component.id,v_case.id,
           v_case.case_revision,v_component.component_revision,v_period.period_revision,v_rule.id,v_rule.rule_revision,
           v_component.case_kind,v_component.case_subtype,v_component.tax_treatment,v_component.instruction_kind,
           v_component.direction,v_component.payroll_stage,v_purpose,v_age_key,v_age,v_component.component_ordinal,
           v_state.pay_week_start,v_component.source_pay_channel,v_worker.target_pay_channel,v_worker.target_pay_channel,'GBP',
           v_nominal,(v_nominal_q->>'ex')::numeric,(v_nominal_q->>'vat')::numeric,(v_nominal_q->>'inc')::numeric,
           v_capacity,(v_capacity_q->>'ex')::numeric,(v_capacity_q->>'vat')::numeric,(v_capacity_q->>'inc')::numeric,
           v_rule.minimum_earnings_threshold,v_rule.take_home_floor_override,v_state.captured_default_floor,
           v_state.captured_default_floor_revision,coalesce(v_rule.take_home_floor_override,v_state.captured_default_floor),
           v_policy_id,(v_snapshot->>'policy_window_id')::uuid,v_resolution_ref,v_explanation,
           case when v_automatic then v_collection.id else null end,v_snapshot,
           v_cmp.id,v_cmp.source_binding_version_id,v_cmp.canonical_work_id,v_cmp.canonical_component_key,
           v_cmp.approval_work_id,v_cmp.approval_revision_id,v_cmp.approval_component_key,
           case when v_cmp.id is null then null else (select b.component_state from private.bpay_next_source_component_binding_version b
             where b.id=v_cmp.source_binding_version_id) end,v_cmp.approved_line_id)
          returning id into v_instruction_id;
        perform private.bpay_next_capture_instruction_destination_v1(v_instruction_id);
        v_state.instruction_capture_cursor:=v_item.selection_no;
        v_state.captured_instruction_count:=v_state.captured_instruction_count+1;
        if v_component.payroll_stage='NET_ADD' then v_state.payout_instruction_count:=v_state.payout_instruction_count+1;end if;
        update private.bpay_next_run_worker set case_instruction_count=case_instruction_count+1 where id=v_worker.id;
      end loop;
      select exists(select 1 from private.bpay_next_case_selection_item i where i.run_id=v_run_id
        and i.candidate_id=v_candidate and i.selection_revision=v_state.selection_revision and i.is_selected
        and i.selection_no>v_state.instruction_capture_cursor) into v_has_more;
      if not v_has_more and v_state.captured_instruction_count<>v_state.expected_instruction_count then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_CAPTURE_COUNT_MISMATCH';
      end if;
      update private.bpay_next_case_allocation_state set instruction_capture_cursor=v_state.instruction_capture_cursor,
        captured_instruction_count=v_state.captured_instruction_count,payout_instruction_count=v_state.payout_instruction_count,
        prepare_stage=case when v_has_more then 'INSTRUCTION_CAPTURE' else 'ALLOCATE' end where id=v_state.id;
      exit prepare_page;
    end if;

    if v_state.prepare_stage<>'ALLOCATE' or v_state.weekly_binding_state<>'BOUND' then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_ALLOCATION_NOT_BOUND';
    end if;
    select c.* into strict v_channel from private.bpay_next_case_allocation_channel c
      where c.state_id=v_state.id and c.allocation_channel=v_worker.target_pay_channel for update;
    v_e:=v_channel.remaining_headroom;v_h:=v_state.remaining_worker_take_home;
    for v_instruction in select i.* from private.bpay_next_run_case_instruction i
      where i.run_worker_id=v_worker.id and i.preparation_revision=v_worker.preparation_revision
        and i.selection_revision=v_state.selection_revision
        and (v_state.cursor_case_component_id is null or (i.age_key,i.case_id,i.component_ordinal,i.case_component_id)
          >(v_state.cursor_age_key,v_state.cursor_case_id,v_state.cursor_component_ordinal,v_state.cursor_case_component_id))
      order by i.age_key,i.case_id,i.component_ordinal,i.case_component_id limit p_limit
    loop
      v_seen:=v_seen+1;
      if v_instruction.hold_purpose='PAYOUT' then
        v_taken:=least(v_instruction.nominal_target_ex_vat,v_instruction.capacity_target_ex_vat);
        v_cap_reason:=null;v_affordability_reason:=null;
        v_capacity_reason:=case when v_instruction.capacity_target_ex_vat<v_instruction.nominal_target_ex_vat then 'CASE_CAPACITY' else null end;
        v_next_e:=v_e;v_next_h:=v_h;
      else
        select x.* into strict v_row from private.bpay_next_case_allocation_row_v1(v_instruction.case_kind,
          v_instruction.nominal_target_ex_vat,v_instruction.capacity_target_ex_vat,v_e,v_h,
          v_instruction.minimum_earnings_threshold,v_instruction.take_home_floor_override,v_instruction.captured_default_floor) x;
        v_taken:=v_row.taken_amount;v_cap_reason:=v_row.cap_reason;
        v_affordability_reason:=v_row.affordability_reason;v_capacity_reason:=v_row.capacity_reason;
        v_next_e:=v_row.next_channel_headroom;v_next_h:=v_row.next_worker_take_home;
      end if;
      begin
        v_slice:=private.bpay_next_case_source_slice_v2(v_instruction.selected_quote_snapshot,v_taken,v_instruction.capacity_source_ex_vat);
      exception when sqlstate '55000' then
        if sqlerrm='BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' then
          v_issue:='CASE_SOURCE_PARTITION_REVIEW_REQUIRED';exit prepare_page;else raise;end if;
      end;
      v_source_taken:=(v_slice->>'source')::numeric;v_taken_vat:=(v_slice->>'vat')::numeric;v_taken_inc:=(v_slice->>'inc')::numeric;
      insert into private.bpay_next_case_allocation_result
        (state_id,instruction_id,run_worker_id,candidate_id,preparation_revision,selection_revision,result_no,
         pass_kind,allocation_channel,hold_purpose,nominal_target_ex_vat,usable_capacity_target_ex_vat,
         allocated_source_ex_vat,allocated_target_ex_vat,allocated_target_vat,allocated_target_inc_vat,shortfall_target_ex_vat,
         cap_reason,affordability_reason,capacity_reason,channel_headroom_before,channel_headroom_after,worker_take_home_before,worker_take_home_after)
        values(v_state.id,v_instruction.id,v_worker.id,v_candidate,v_worker.preparation_revision,v_state.selection_revision,
         v_state.processed_instruction_count+1,'DRAFT',v_worker.target_pay_channel,v_instruction.hold_purpose,v_instruction.nominal_target_ex_vat,
         v_instruction.capacity_target_ex_vat,v_source_taken,v_taken,v_taken_vat,v_taken_inc,v_instruction.nominal_target_ex_vat-v_taken,
         v_cap_reason,v_affordability_reason,v_capacity_reason,v_e,v_next_e,v_h,v_next_h)
        returning id into v_result_id;
      if v_taken>0 then
        select c.* into strict v_case from private.bpay_next_finance_case c where c.id=v_instruction.case_id for update;
        select c.* into strict v_component from private.bpay_next_case_component c where c.id=v_instruction.case_component_id for update;
        select p.* into strict v_period from private.bpay_next_case_period p
          where p.case_component_id=v_component.id and p.pay_week_start=v_instruction.pay_week_start for update;
        insert into private.bpay_next_case_hold
          (run_worker_id,candidate_id,case_id,amount,status,instruction_id,allocation_result_id,allocation_pass_kind,
           case_component_id,purpose,pay_week_start,source_reserved_ex_vat,target_amount_ex_vat,target_amount_vat,target_amount_inc_vat)
          values(v_worker.id,v_candidate,v_case.id,v_source_taken,'ACTIVE',v_instruction.id,v_result_id,'DRAFT',
           v_component.id,v_instruction.hold_purpose,v_instruction.pay_week_start,v_source_taken,v_taken,v_taken_vat,v_taken_inc) returning id into v_hold_id;
        insert into private.bpay_next_case_capacity_use(case_hold_id,case_component_id,case_id,candidate_id,
          pay_week_start,purpose,status,source_amount_ex_vat)
          values(v_hold_id,v_component.id,v_case.id,v_candidate,v_instruction.pay_week_start,v_instruction.hold_purpose,'ACTIVE',v_source_taken);
        if v_instruction.hold_purpose='PAYOUT' then
          update private.bpay_next_case_component set active_payout_source_ex_vat=active_payout_source_ex_vat+v_source_taken,
            component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id;
          update private.bpay_next_finance_case set active_payout_hold_amount=active_payout_hold_amount+v_source_taken,
            active_hold_amount=active_hold_amount+v_source_taken,case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_case.id;
          update private.bpay_next_case_period set active_payout_source_ex_vat=active_payout_source_ex_vat+v_source_taken,
            period_revision=period_revision+1 where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start;
        else
          update private.bpay_next_case_component set active_recovery_source_ex_vat=active_recovery_source_ex_vat+v_source_taken,
            component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id;
          update private.bpay_next_finance_case set active_recovery_hold_amount=active_recovery_hold_amount+v_source_taken,
            active_hold_amount=active_hold_amount+v_source_taken,case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_case.id;
          update private.bpay_next_case_period set active_unrealised_recovery_source_ex_vat=active_unrealised_recovery_source_ex_vat+v_source_taken,
            period_revision=period_revision+1 where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start;
          v_state.recovered_source_total:=v_state.recovered_source_total+v_source_taken;
          v_state.recovered_target_total:=v_state.recovered_target_total+v_taken;
        end if;
        if v_instruction.source_comparison_receipt_id is not null then
          select p.* into strict v_position from private.bpay_next_position p
            where p.work_id=v_instruction.canonical_source_work_id and p.component_key=v_instruction.canonical_source_component_key for update;
          v_carry:=private.bpay_next_source_comparison_case_capacity_carry_v2(p_job_id,v_position.source_book_revision,
            v_position.source_comparison_receipt_id,v_hold_id,'CASE_RESERVE');
        end if;
        update private.bpay_next_run_worker set active_case_hold_count=active_case_hold_count+1 where id=v_worker.id;
      end if;
      if v_instruction.payroll_stage='GROSS_ADD' then
        v_state.allocated_gross_additions:=v_state.allocated_gross_additions+v_taken;
        v_state.allocated_gross_additions_vat:=v_state.allocated_gross_additions_vat+v_taken_vat;
      elsif v_instruction.payroll_stage='GROSS_DEDUCT' then
        v_state.allocated_gross_deductions:=v_state.allocated_gross_deductions+v_taken;
        v_state.allocated_gross_deductions_vat:=v_state.allocated_gross_deductions_vat+v_taken_vat;
      elsif v_instruction.payroll_stage='NET_ADD' then
        v_state.allocated_net_additions:=v_state.allocated_net_additions+v_taken;
        v_state.allocated_net_additions_vat:=v_state.allocated_net_additions_vat+v_taken_vat;
      else
        v_state.allocated_net_recoveries:=v_state.allocated_net_recoveries+v_taken;
        v_state.allocated_net_recoveries_vat:=v_state.allocated_net_recoveries_vat+v_taken_vat;
      end if;
      v_e:=v_next_e;v_h:=v_next_h;
      v_state.processed_instruction_count:=v_state.processed_instruction_count+1;
      v_state.cursor_age_key:=v_instruction.age_key;v_state.cursor_case_id:=v_instruction.case_id;
      v_state.cursor_component_ordinal:=v_instruction.component_ordinal;v_state.cursor_case_component_id:=v_instruction.case_component_id;
      update private.bpay_next_run_worker set case_allocated_count=case_allocated_count+1 where id=v_worker.id;
    end loop;
    update private.bpay_next_case_allocation_channel set remaining_headroom=v_e where state_id=v_state.id and allocation_channel=v_worker.target_pay_channel;
    update private.bpay_next_case_allocation_state set processed_instruction_count=v_state.processed_instruction_count,
      remaining_worker_take_home=v_h,recovered_source_total=v_state.recovered_source_total,recovered_target_total=v_state.recovered_target_total,
      cursor_age_key=v_state.cursor_age_key,cursor_case_id=v_state.cursor_case_id,cursor_component_ordinal=v_state.cursor_component_ordinal,
      cursor_case_component_id=v_state.cursor_case_component_id,allocated_gross_additions=v_state.allocated_gross_additions,
      allocated_gross_deductions=v_state.allocated_gross_deductions,allocated_net_additions=v_state.allocated_net_additions,
      allocated_gross_additions_vat=v_state.allocated_gross_additions_vat,
      allocated_gross_deductions_vat=v_state.allocated_gross_deductions_vat,
      allocated_net_additions_vat=v_state.allocated_net_additions_vat,
      allocated_net_recoveries=v_state.allocated_net_recoveries,allocated_net_recoveries_vat=v_state.allocated_net_recoveries_vat where id=v_state.id;
    select exists(select 1 from private.bpay_next_run_case_instruction i where i.run_worker_id=v_worker.id
      and i.preparation_revision=v_worker.preparation_revision and i.selection_revision=v_state.selection_revision
      and (v_state.cursor_case_component_id is null or (i.age_key,i.case_id,i.component_ordinal,i.case_component_id)
        >(v_state.cursor_age_key,v_state.cursor_case_id,v_state.cursor_component_ordinal,v_state.cursor_case_component_id))) into v_has_more;
    if not v_has_more then
      if v_state.processed_instruction_count<>v_state.expected_instruction_count then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_PREPARE_ALLOCATION_COUNT_MISMATCH';
      end if;
      v_gross:=v_state.captured_work_gross+v_state.allocated_gross_additions-v_state.allocated_gross_deductions;
      v_gross_vat:=v_state.captured_work_vat+v_state.allocated_gross_additions_vat-v_state.allocated_gross_deductions_vat;
      if v_gross_vat<0 or v_gross_vat>=10000000000000000 then v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;end if;
      if v_gross<0 or v_gross>=10000000000000000 or v_state.allocated_net_additions>=10000000000000000 then
        v_issue:='CASE_INPUT_UNBOUND';exit prepare_page;
      end if;
      -- Preserve certified-zero WORK/Source rows; case-only NET additions are
      -- real payable cash, not a made-up positive payroll gross or net.
      if v_worker.captured_line_count=0 and v_gross=0 and v_state.allocated_net_additions=0 then
        v_issue:='CASE_NO_PAYABLE_AMOUNT';exit prepare_page;
      end if;
      if v_worker.target_pay_channel='PAYE' and v_worker.captured_line_count=0 and v_gross=0 and v_state.payout_instruction_count>0 then
        insert into private.bpay_next_case_payout_basis(run_worker_id,candidate_id,preparation_revision,currency,
          beneficiary_kind,beneficiary_id,expected_instruction_count,captured_instruction_count,source_total_ex_vat,
          target_total_ex_vat,target_total_vat,target_total_inc_vat,status)
          values(v_worker.id,v_candidate,v_worker.preparation_revision,'GBP','CANDIDATE',v_candidate,
            v_state.payout_instruction_count,v_state.payout_instruction_count,v_state.allocated_net_additions,
            v_state.allocated_net_additions,0,v_state.allocated_net_additions,'SEALED');
      end if;
      select w.* into strict v_week from private.bpay_next_worker_week w
        where w.candidate_id=v_candidate and w.pay_week_start=v_state.pay_week_start for update;
      insert into private.bpay_next_worker_week_contribution(candidate_id,pay_week_start,original_run_worker_id,
        original_pay_date,original_created_at_utc,contribution_revision,basis_kind,original_gross_amount,
        payment_state,eligibility_state,eligible_arranged_amount,primary_binding_revision)
        values(v_candidate,v_state.pay_week_start,v_worker.id,v_run.pay_date,v_run.created_at_utc,1,'GROSS_FALLBACK',
          v_gross,'ARRANGED',case when v_gross>0 then 'ELIGIBLE' else 'EXCLUDED' end,v_gross,1);
      update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home+v_gross,
        period_revision=period_revision+1 where candidate_id=v_candidate and pay_week_start=v_state.pay_week_start;
      update private.bpay_next_case_allocation_state set status='COMPLETE',prepare_stage='COMPLETE',
        completed_at_utc=pg_catalog.transaction_timestamp() where id=v_state.id;
      update private.bpay_next_run_worker set gross_ex_vat=v_gross,gross_vat=v_gross_vat,gross_inc_vat=v_gross+v_gross_vat,
        status='READY',case_pending_binding_count=0 where id=v_worker.id;
      update private.bpay_next_job set status='DONE',phase='READY',cursor_key=null,lease_nonce=null,lease_until_utc=null,
        position_work_cursor=null,position_component_cursor=null where id=p_job_id;
      v_terminal:=true;
    end if;
  end prepare_page;

  if v_issue is not null then
    -- Candidate-wide issue: WORK FK remains NULL. Earlier frozen WORK and any
    -- already-created ACTIVE reservations remain exact and non-confirmable.
    update private.bpay_next_run_worker set status='REVIEW',review_issue_code=v_issue,review_issue_work_id=null,
      financial_resolution_count=financial_resolution_count+1,case_pending_binding_count=
        case when v_issue in ('CASE_SELECTION_REQUIRED','CASE_INPUT_UNBOUND','CASE_WEEK_BASIS_UNBOUND','CASE_RETURN_FLOOR_UNBOUND','CASE_SOURCE_PARTITION_REVIEW_REQUIRED') then 1 else 0 end
      where id=v_worker.id;
    if v_state.id is not null then
      update private.bpay_next_case_allocation_state set prepare_stage='REVIEW',weekly_binding_state='UNBOUND',
        instruction_capture_cursor=v_state.instruction_capture_cursor,captured_instruction_count=v_state.captured_instruction_count,
        payout_instruction_count=v_state.payout_instruction_count where id=v_state.id;
    end if;
    update private.bpay_next_job set status='DONE',phase='DONE',cursor_key=null,lease_nonce=null,lease_until_utc=null,
      position_work_cursor=null,position_component_cursor=null where id=p_job_id;
    v_terminal:=true;
  elsif not v_terminal then
    update private.bpay_next_job set cursor_key=(v_saved_cursor+1)::text where id=p_job_id;
  end if;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1,
    updated_at_utc=pg_catalog.transaction_timestamp() where candidate_id=v_candidate;
  return pg_catalog.jsonb_build_object('done',v_terminal,'phase',case when v_issue is not null then 'REVIEW'
    when v_terminal then 'READY' else 'FINANCE_ALLOCATE' end,'cursor',case when v_terminal then null else (v_saved_cursor+1)::text end,
    'rows_visited',v_seen::text,'replay',false,'run_worker_id',v_worker.id,
    'worker_status',case when v_issue is not null then 'REVIEW' when v_terminal then 'READY' else 'PREPARING' end)
    ||case when v_issue is not null then pg_catalog.jsonb_build_object('issue_code',v_issue) else '{}'::jsonb end;
end
$function$;

alter function private.bpay_next_prepare_case_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_prepare_case_page_v1(uuid,uuid,bigint,bigint,integer)
  from public,anon,authenticated,service_role;


-- Genuine ordered PAYE NET projection from the completed frozen case Draft.
-- The caller is the existing PAYE_NET_ENTRY lane, not a new calculator/job.
-- Gross instructions are unchanged; only own unpaid NET capacity is resized.



drop trigger if exists bpay_next_net_request_immutable_v1 on private.bpay_next_paye_net_request;
create trigger bpay_next_net_request_immutable_v1 before update or delete
  on private.bpay_next_paye_net_request for each row
  execute function private.bpay_next_effect_immutable_v1();

create or replace function private.bpay_next_accept_case_net_request_v1(
  p_command_id uuid,p_run_worker_id uuid,p_actor_user_id uuid,p_input_kind text,
  p_entered_paye_net numeric,p_expected_projection_revision bigint
) returns jsonb
language plpgsql security invoker
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_sequence bigint;
  v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_draft private.bpay_next_case_allocation_state%rowtype;
  v_prior private.bpay_next_paye_net_request%rowtype;
begin
  if p_command_id is null or p_run_worker_id is null or p_actor_user_id is null
     or p_input_kind is null or p_input_kind not in ('PAYE_MANUAL','CASE_PAYOUT')
     or p_expected_projection_revision is null or p_expected_projection_revision<0
     or p_expected_projection_revision=9223372036854775807
     or (p_input_kind='PAYE_MANUAL' and (p_entered_paye_net is null
       or p_entered_paye_net::text in ('NaN','Infinity','-Infinity') or p_entered_paye_net<0
       or p_entered_paye_net>=10000000000000000 or p_entered_paye_net<>pg_catalog.trunc(p_entered_paye_net,2)))
     or (p_input_kind='CASE_PAYOUT' and p_entered_paye_net is not null) then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_NET_INPUT_INVALID';
  end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control
    where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  if not exists(select 1 from public.tms_users u where u.id=p_actor_user_id
      and u.is_active is true and u.role::text='admin' for share) then
    raise exception using errcode='42501',message='BPAY_NEXT_CASE_NET_ACTOR_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bpay-next-case-net:'||p_command_id::text,0));
  select run_id,candidate_id into strict v_run_id,v_candidate from private.bpay_next_run_worker where id=p_run_worker_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_worker from private.bpay_next_run_worker where id=p_run_worker_id for update;
  select * into v_prior from private.bpay_next_paye_net_request where command_id=p_command_id;
  if found then
    if v_prior.run_worker_id<>p_run_worker_id or v_prior.actor_user_id is distinct from p_actor_user_id
       or v_prior.input_kind<>p_input_kind or v_prior.entered_paye_net is distinct from p_entered_paye_net
       or v_prior.expected_projection_revision is distinct from p_expected_projection_revision
       or v_prior.case_draft_state_id is null then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_REPLAY_CONFLICT';
    end if;
    select agency_sequence into strict v_sequence from private.bpay_next_command
      where id=p_command_id and command_kind='PAYE_NET_ENTRY';
    return pg_catalog.jsonb_build_object('sequence',v_sequence::text,'request_no',v_prior.request_no::text,
      'replay',true,'phase','ACCEPTED_PENDING_PROJECTION','run_worker_id',v_worker.id);
  end if;
  select s.* into strict v_draft from private.bpay_next_case_allocation_state s
    where s.run_worker_id=v_worker.id and s.preparation_revision=v_worker.preparation_revision
      and s.selection_revision=v_worker.case_selection_revision and s.pass_kind='DRAFT' and s.projection_no=0;
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null or v_worker.status<>'READY'
     or v_worker.target_pay_channel<>'PAYE' or v_worker.gross_vat<>0
     or v_worker.gross_ex_vat<>v_worker.gross_inc_vat or v_worker.gross_inc_vat<0
     or v_draft.status<>'COMPLETE' or v_draft.prepare_stage<>'COMPLETE'
     or v_worker.case_pending_binding_count<>0
     or v_worker.net_projection_revision<>p_expected_projection_revision
     or v_worker.net_request_revision<>v_worker.net_projection_revision
     or v_worker.realised_effect_count<>0
     or v_draft.captured_work_gross+v_draft.allocated_gross_additions-v_draft.allocated_gross_deductions<>v_worker.gross_inc_vat
     or exists(select 1 from private.bpay_next_cancel_request r where r.run_worker_id=v_worker.id
       and r.status in ('REQUESTED','CANCELLING'))
     or exists(select 1 from private.bpay_next_transfer t where t.run_worker_id=v_worker.id) then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_NET_NOT_ELIGIBLE';
  end if;
  if p_input_kind='PAYE_MANUAL' then
    if p_entered_paye_net>v_worker.gross_inc_vat or exists(select 1 from private.bpay_next_case_payout_basis
      where run_worker_id=v_worker.id and preparation_revision=v_worker.preparation_revision) then
      raise exception using errcode='55000',message='BPAY_NEXT_CASE_NET_PAYROLL_BASIS_INVALID';
    end if;
  else
    if p_expected_projection_revision<>0 or v_worker.captured_line_count<>0 or v_worker.gross_inc_vat<>0
       or not exists(select 1 from private.bpay_next_case_payout_basis b where b.run_worker_id=v_worker.id
         and b.preparation_revision=v_worker.preparation_revision and b.status='SEALED'
         and b.projection_id is null and b.target_total_inc_vat>0
         and b.target_total_inc_vat=v_draft.allocated_net_additions and b.beneficiary_id=v_worker.candidate_id) then
      raise exception using errcode='55000',message='BPAY_NEXT_CASE_PAYOUT_BASIS_INVALID';
    end if;
  end if;
  if p_expected_projection_revision>0 and not exists(select 1 from private.bpay_next_net_projection p
      where p.run_worker_id=v_worker.id and p.projection_no=p_expected_projection_revision
        and p.retired_at_utc is null and p.input_kind='PAYE_MANUAL') then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_PRIOR_PROJECTION_INVALID';
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'PAYE_NET_ENTRY');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no)
    values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_paye_net_request(command_id,run_worker_id,candidate_id,request_no,
    entered_paye_net,frozen_gross_inc_vat,input_kind,actor_user_id,case_draft_state_id,
    preparation_revision,selection_revision,expected_projection_revision)
    values(p_command_id,v_worker.id,v_worker.candidate_id,p_expected_projection_revision+1,
      p_entered_paye_net,v_worker.gross_inc_vat,p_input_kind,p_actor_user_id,v_draft.id,
      v_worker.preparation_revision,v_worker.case_selection_revision,p_expected_projection_revision);
  update private.bpay_next_run_worker set net_request_revision=p_expected_projection_revision+1 where id=v_worker.id;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1,
    updated_at_utc=pg_catalog.transaction_timestamp() where candidate_id=v_candidate;
  update private.bpay_next_command set expected_member_count=1,status='SEALED',sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('sequence',v_sequence::text,'request_no',(p_expected_projection_revision+1)::text,
    'replay',false,'phase','ACCEPTED_PENDING_PROJECTION','run_worker_id',v_worker.id);
end
$function$;

create or replace function private.bpay_next_accept_case_paye_net_v1(
  p_command_id uuid,p_run_worker_id uuid,p_actor_user_id uuid,p_entered_paye_net numeric,
  p_expected_projection_revision bigint
) returns jsonb language sql security invoker set search_path=pg_catalog,private
as $function$
  select private.bpay_next_accept_case_net_request_v1(p_command_id,p_run_worker_id,p_actor_user_id,
    'PAYE_MANUAL',p_entered_paye_net,p_expected_projection_revision)
$function$;
create or replace function private.bpay_next_accept_case_payout_projection_v1(
  p_command_id uuid,p_run_worker_id uuid,p_actor_user_id uuid,p_expected_projection_revision bigint
) returns jsonb language sql security invoker set search_path=pg_catalog,private
as $function$
  select private.bpay_next_accept_case_net_request_v1(p_command_id,p_run_worker_id,p_actor_user_id,
    'CASE_PAYOUT',null,p_expected_projection_revision)
$function$;

-- One exact projection read protects the maintained contribution from mixing
-- entered payroll net, bank cash, another worker and payout-only earnings.
create or replace function private.bpay_next_week_projection_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
declare v_projection private.bpay_next_net_projection%rowtype;
  v_destination private.bpay_next_net_destination_state%rowtype;v_eligible_cash numeric;
begin
  if new.accepted_projection_id is null then return new;end if;
  select * into strict v_projection from private.bpay_next_net_projection where id=new.accepted_projection_id;
  if v_projection.run_worker_id<>new.original_run_worker_id
     or not exists(select 1 from private.bpay_next_run_worker w
       where w.id=new.original_run_worker_id and w.candidate_id=new.candidate_id)
     or v_projection.cash_amount is distinct from new.accepted_bank_cash
     or (case when v_projection.umbrella_case_draft_state_id is not null then v_projection.gross_ex_vat
       else v_projection.gross_inc_vat end)<>new.original_gross_amount
     or (v_projection.input_kind='CASE_PAYOUT' and (new.basis_kind<>'GROSS_FALLBACK'
       or new.original_payroll_net is not null or new.eligibility_state<>'EXCLUDED' or new.eligible_arranged_amount<>0))
     or (v_projection.umbrella_case_draft_state_id is not null and (new.basis_kind<>'GROSS_FALLBACK'
       or new.original_payroll_net is not null or (not private.bpay_next_umbrella_case_projection_valid_v2(
         (select w from private.bpay_next_run_worker w where w.id=new.original_run_worker_id),v_projection)
         and not (new.payment_state='CANCELLED' and new.eligibility_state='EXCLUDED'
           and new.eligible_arranged_amount=0 and new.original_transfer_id is null
           and new.returned_cash_id is null and new.reissue_transfer_id is null
           and private.bpay_next_umbrella_case_cancelled_projection_valid_v2(
             (select w from private.bpay_next_run_worker w where w.id=new.original_run_worker_id),v_projection)))))
     or (v_projection.input_kind<>'CASE_PAYOUT' and v_projection.umbrella_case_draft_state_id is null
       and (new.basis_kind<>'PAYROLL_NET' or new.original_payroll_net is distinct from v_projection.entered_paye_net)) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ACCEPTED_PROJECTION_MISMATCH';
  end if;
  -- Unique projection lookup, never a current WORK/Timesheet or historical
  -- reconstruction. 1827 seals this exact fact BEFORE the contribution switch.
  -- Its NET allocation owner can still be BUILDING in the same transaction.
  v_eligible_cash:=case when v_projection.umbrella_case_draft_state_id is not null then
    v_projection.gross_ex_vat-(select s.allocated_net_recoveries from private.bpay_next_case_allocation_state s
      where s.id=v_projection.umbrella_case_draft_state_id) else v_projection.cash_amount end;
  select * into v_destination from private.bpay_next_net_destination_state
    where projection_id=v_projection.id;
  if found then
    if v_destination.run_worker_id<>new.original_run_worker_id
       or v_destination.projection_id is distinct from new.accepted_projection_id
       or v_destination.completed_at_utc is null
       or v_destination.external_leg_count<1 or v_destination.external_credit_count<1
       or v_destination.external_amount<=0 or v_destination.own_amount is null or v_destination.own_amount<0
       or v_destination.cash_amount is distinct from v_projection.cash_amount
       or v_destination.own_amount+v_destination.external_amount is distinct from v_destination.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_DESTINATION_BASIS_MISMATCH';
    end if;
    v_eligible_cash:=v_destination.own_amount;
  end if;
  if new.eligibility_state='ELIGIBLE'
     and new.eligible_arranged_amount is distinct from v_eligible_cash then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ELIGIBLE_DESTINATION_MISMATCH';
  end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_week_projection_guard_v1 on private.bpay_next_worker_week_contribution;
create trigger bpay_next_week_projection_guard_v1 before insert or update
  on private.bpay_next_worker_week_contribution for each row
  execute function private.bpay_next_week_projection_guard_v1();

create or replace function private.bpay_next_net_projection_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
begin
  if tg_op='DELETE' or old.retired_at_utc is not null or new.retired_at_utc is null
     or not pg_catalog.isfinite(new.retired_at_utc)
     or (pg_catalog.to_jsonb(new)-'retired_at_utc') is distinct from (pg_catalog.to_jsonb(old)-'retired_at_utc') then
    raise exception using errcode='23514',message='BPAY_NEXT_ACCEPTED_NET_PROJECTION_IMMUTABLE';
  end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_net_projection_guard_v1 on private.bpay_next_net_projection;
create trigger bpay_next_net_projection_guard_v1 before update or delete
  on private.bpay_next_net_projection for each row execute function private.bpay_next_net_projection_guard_v1();

create or replace function private.bpay_next_apply_case_paye_net_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,p_expected_cursor bigint default null,
  p_limit integer default 100
) returns jsonb
language plpgsql security invoker
set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_control_epoch bigint;v_checkpoint bigint;
  v_run private.bpay_next_pay_run%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_job private.bpay_next_job%rowtype;v_request private.bpay_next_paye_net_request%rowtype;
  v_draft private.bpay_next_case_allocation_state%rowtype;v_state private.bpay_next_case_allocation_state%rowtype;
  v_week private.bpay_next_worker_week%rowtype;v_prior private.bpay_next_worker_week_contribution%rowtype;
  v_contribution private.bpay_next_worker_week_contribution%rowtype;
  v_instruction private.bpay_next_run_case_instruction%rowtype;v_draft_result private.bpay_next_case_allocation_result%rowtype;
  v_own private.bpay_next_case_hold%rowtype;v_case private.bpay_next_finance_case%rowtype;
  v_component private.bpay_next_case_component%rowtype;v_period private.bpay_next_case_period%rowtype;
  v_channel private.bpay_next_case_allocation_channel%rowtype;
  v_seen integer:=0;v_more boolean;v_issue text;v_terminal boolean:=false;v_requires_week boolean;
  v_e numeric;v_h numeric;v_own_amount numeric;v_source_taken numeric;v_target_capacity numeric;v_slice jsonb;v_capacity_q jsonb;
  v_capacity numeric;v_taken numeric;v_cash numeric;v_own_cash numeric;
  v_outstanding numeric;v_case_outstanding numeric;v_row record;v_result_id uuid;v_hold_id uuid;v_projection_id uuid;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null or p_owner_epoch<1
     or (p_expected_cursor is not null and p_expected_cursor<1) or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_NET_PAGE_INPUT_INVALID';
  end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate from private.bpay_next_job j
    join private.bpay_next_paye_net_request r on r.command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=r.run_worker_id and w.candidate_id=j.candidate_id
    where j.id=p_job_id and r.case_draft_state_id is not null;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  select active_owner_epoch into strict v_control_epoch from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_paye_net_request where command_id=v_job.command_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_request.run_worker_id for update;
  select * into strict v_draft from private.bpay_next_case_allocation_state where id=v_request.case_draft_state_id;
  select * into v_state from private.bpay_next_case_allocation_state where job_id=p_job_id and pass_kind='NET' for update;
  if v_job.job_kind<>'PAYE_NET_ENTRY' or v_job.module_epoch<>v_epoch or v_job.candidate_id<>v_candidate
     or v_request.candidate_id<>v_candidate or v_draft.run_worker_id<>v_worker.id or v_draft.pass_kind<>'DRAFT'
     or v_draft.preparation_revision<>v_request.preparation_revision or v_draft.selection_revision<>v_request.selection_revision then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_JOB_SCOPE_INVALID';
  end if;
  -- An immutable completed receipt survives later lane owners and net saves.
  if v_job.status='DONE' and v_state.id is not null and v_state.net_stage in ('COMPLETE','REVIEW') then
    return pg_catalog.jsonb_build_object('phase',case when v_state.net_stage='COMPLETE' then 'PROJECTED' else 'REVIEW' end,
      'cursor',null,'rows_visited','0','replay',true,'projection_id',v_state.projection_id,
      'run_worker_id',v_worker.id,'issue_code',v_state.net_issue_code);
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'FINANCE_ALLOCATE' or v_job.lease_nonce<>p_lease_nonce
     or v_job.owner_epoch<>p_owner_epoch or v_control_epoch<>p_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() or v_run.status<>'DRAFT'
     or v_run.confirmed_at_utc is null or v_worker.status<>'READY'
     or v_worker.preparation_revision<>v_request.preparation_revision or v_worker.case_selection_revision<>v_request.selection_revision
     or v_worker.net_request_revision<>v_request.request_no or v_worker.net_projection_revision<>v_request.expected_projection_revision
     or v_worker.target_pay_channel<>'PAYE' or v_worker.gross_vat<>0 or v_worker.gross_inc_vat<>v_request.frozen_gross_inc_vat
     or v_worker.realised_effect_count<>0 or v_draft.status<>'COMPLETE' or v_draft.prepare_stage<>'COMPLETE'
     or exists(select 1 from private.bpay_next_cancel_request r join private.bpay_next_command c on c.id=r.command_id
       where r.run_worker_id=v_worker.id and (r.status='CANCELLING'
         or (r.status='REQUESTED' and c.agency_sequence<v_job.command_sequence)))
     or exists(select 1 from private.bpay_next_transfer t where t.run_worker_id=v_worker.id) then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_NET_OWNER_NOT_ELIGIBLE';
  end if;
  v_checkpoint:=v_job.cursor_key::bigint;
  if p_expected_cursor is distinct from v_checkpoint then
    if coalesce(p_expected_cursor,0)<coalesce(v_checkpoint,0) then
      return pg_catalog.jsonb_build_object('phase','FINANCE_ALLOCATE','cursor',v_job.cursor_key,'rows_visited','0',
        'replay',true,'projection_id',null,'run_worker_id',v_worker.id,'issue_code',null);
    end if;
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_NET_CURSOR_STALE';
  end if;

  <<net_page>>
  begin
    if v_state.id is null then
      select * into strict v_week from private.bpay_next_worker_week
        where candidate_id=v_candidate and pay_week_start=v_draft.pay_week_start for update;
      select exists(select 1 from private.bpay_next_run_case_instruction i
        join private.bpay_next_case_allocation_result a on a.instruction_id=i.id and a.state_id=v_draft.id
        where i.run_worker_id=v_worker.id and i.preparation_revision=v_request.preparation_revision
          and i.selection_revision=v_request.selection_revision and i.payroll_stage='NET_DEDUCT'
          and i.case_kind in ('LOAN','ADVANCE','MANUAL_DEBT') and a.allocated_source_ex_vat>0) into v_requires_week;
      insert into private.bpay_next_case_allocation_state(run_worker_id,run_id,candidate_id,selection_revision,preparation_revision,
        pass_kind,projection_no,command_id,job_id,module_epoch,owner_epoch,financial_view_revision,status,weekly_binding_state,
        expected_instruction_count,initial_worker_take_home,remaining_worker_take_home,pay_week_start,captured_week_revision,
        captured_work_gross,net_stage,net_requires_week_binding)
        values(v_worker.id,v_run_id,v_candidate,v_request.selection_revision,v_request.preparation_revision,'NET',v_request.request_no,
          v_job.command_id,v_job.id,v_epoch,p_owner_epoch,
          (select financial_view_revision from private.bpay_next_worker_control where candidate_id=v_candidate),'BUILDING',
          case when v_requires_week then 'UNBOUND' else 'NOT_AFFECTED' end,v_draft.expected_instruction_count,
          coalesce(v_request.entered_paye_net,0),coalesce(v_request.entered_paye_net,0),v_draft.pay_week_start,v_week.period_revision,
          v_draft.captured_work_gross,case when v_requires_week then 'WEEK_CAPTURE' else 'ALLOCATE' end,v_requires_week)
        returning * into v_state;
      insert into private.bpay_next_case_allocation_channel(state_id,allocation_channel,initial_headroom,remaining_headroom)
        values(v_state.id,'PAYE',coalesce(v_request.entered_paye_net,0),coalesce(v_request.entered_paye_net,0));
      -- Only arrangements BEFORE this run affect its floor. A later return
      -- cannot invalidate an earlier run merely through a whole-week counter.
      -- Exact prior UNBOUND rows are handled by the bounded week pages below.
      if v_requires_week and exists(
        select 1 from private.bpay_next_run_worker w join private.bpay_next_pay_run r on r.id=w.run_id
        where w.candidate_id=v_candidate and w.status in ('READY','DRAFT','ISSUED','COMPLETE')
          and r.pay_date>=v_draft.pay_week_start and r.pay_date<v_draft.pay_week_start+7
          and (r.pay_date,r.created_at_utc,w.id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and not exists(select 1 from private.bpay_next_worker_week_contribution x where x.original_run_worker_id=w.id)) then
        v_issue:='CASE_WEEK_BASIS_UNBOUND';exit net_page;
      end if;
    elsif v_state.status<>'BUILDING' or v_state.net_stage='NOT_CASE_NET' or v_state.projection_no<>v_request.request_no then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_STATE_INVALID';
    end if;
    if v_state.owner_epoch<>p_owner_epoch then
      update private.bpay_next_case_allocation_state set owner_epoch=p_owner_epoch where id=v_state.id;
    end if;
    select * into strict v_week from private.bpay_next_worker_week
      where candidate_id=v_candidate and pay_week_start=v_state.pay_week_start for update;
    if v_state.net_requires_week_binding and v_week.period_revision<>v_state.captured_week_revision then
      v_issue:='CASE_WEEK_BASIS_UNBOUND';exit net_page;
    end if;
    if v_state.net_stage='WEEK_CAPTURE' then
      for v_prior in select x.* from private.bpay_next_worker_week_contribution x
        where x.candidate_id=v_candidate and x.pay_week_start=v_state.pay_week_start
          and (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and (v_state.prior_worker_cursor is null or (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
            >(v_state.prior_pay_date_cursor,v_state.prior_created_at_cursor,v_state.prior_worker_cursor))
        order by x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id limit p_limit
      loop
        v_seen:=v_seen+1;
        if v_prior.eligibility_state='UNBOUND' then
          v_issue:=case when v_prior.payment_state in ('RETURNED_OWED','REISSUED_PAID') then 'CASE_RETURN_FLOOR_UNBOUND'
            else 'CASE_WEEK_BASIS_UNBOUND' end;exit net_page;
        end if;
        v_state.captured_prior_take_home:=v_state.captured_prior_take_home+v_prior.eligible_arranged_amount;
        v_state.initial_worker_take_home:=v_state.initial_worker_take_home+v_prior.eligible_arranged_amount;
        v_state.remaining_worker_take_home:=v_state.remaining_worker_take_home+v_prior.eligible_arranged_amount;
        v_state.prior_pay_date_cursor:=v_prior.original_pay_date;v_state.prior_created_at_cursor:=v_prior.original_created_at_utc;
        v_state.prior_worker_cursor:=v_prior.original_run_worker_id;
      end loop;
      select exists(select 1 from private.bpay_next_worker_week_contribution x
        where x.candidate_id=v_candidate and x.pay_week_start=v_state.pay_week_start
          and (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)<(v_run.pay_date,v_run.created_at_utc,v_worker.id)
          and (v_state.prior_worker_cursor is null or (x.original_pay_date,x.original_created_at_utc,x.original_run_worker_id)
            >(v_state.prior_pay_date_cursor,v_state.prior_created_at_cursor,v_state.prior_worker_cursor))) into v_more;
      update private.bpay_next_case_allocation_state set captured_prior_take_home=v_state.captured_prior_take_home,
        initial_worker_take_home=v_state.initial_worker_take_home,remaining_worker_take_home=v_state.remaining_worker_take_home,
        prior_pay_date_cursor=v_state.prior_pay_date_cursor,prior_created_at_cursor=v_state.prior_created_at_cursor,
        prior_worker_cursor=v_state.prior_worker_cursor,weekly_binding_state=case when v_more then 'UNBOUND' else 'BOUND' end,
        net_stage=case when v_more then 'WEEK_CAPTURE' else 'ALLOCATE' end where id=v_state.id;
      -- Week capture and allocation never share a >limit step.
      exit net_page;
    end if;
    if v_state.net_stage<>'ALLOCATE' or v_state.weekly_binding_state='UNBOUND' then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_ALLOCATION_UNBOUND';
    end if;
    select * into strict v_channel from private.bpay_next_case_allocation_channel
      where state_id=v_state.id and allocation_channel='PAYE' for update;
    v_e:=v_channel.remaining_headroom;v_h:=v_state.remaining_worker_take_home;
    for v_instruction in select i.* from private.bpay_next_run_case_instruction i
      where i.run_worker_id=v_worker.id and i.preparation_revision=v_request.preparation_revision
        and i.selection_revision=v_request.selection_revision
        and (v_state.cursor_case_component_id is null or (i.age_key,i.case_id,i.component_ordinal,i.case_component_id)
          >(v_state.cursor_age_key,v_state.cursor_case_id,v_state.cursor_component_ordinal,v_state.cursor_case_component_id))
      order by i.age_key,i.case_id,i.component_ordinal,i.case_component_id limit p_limit
    loop
      v_seen:=v_seen+1;
      select * into strict v_draft_result from private.bpay_next_case_allocation_result
        where state_id=v_draft.id and instruction_id=v_instruction.id;
      if v_instruction.target_pay_channel<>'PAYE' or v_instruction.allocation_channel<>'PAYE' or v_instruction.currency<>'GBP'
         or v_instruction.nominal_target_vat<>0 or v_draft_result.allocated_target_vat<>0
         or not private.bpay_next_case_result_quote_valid_v2(v_instruction,v_draft_result) then
        v_issue:='CASE_INPUT_UNBOUND';exit net_page;
      end if;
      select * into v_own from private.bpay_next_case_hold where instruction_id=v_instruction.id and status='ACTIVE' for update;
      v_own_amount:=coalesce(v_own.source_reserved_ex_vat,0);
      if v_own.id is not null and (v_own.run_worker_id<>v_worker.id or v_own.purpose<>v_instruction.hold_purpose
          or v_own.target_amount_vat<>0 or not exists(select 1 from private.bpay_next_case_capacity_use u
            where u.case_hold_id=v_own.id and u.status='ACTIVE' and u.source_amount_ex_vat=v_own_amount)) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_OWN_HOLD_INVALID';
      end if;
      if v_instruction.payroll_stage<>'NET_DEDUCT' then
        -- Gross deductions/additions and payout additions remain the exact
        -- Draft result/hold. They neither enter the kernel nor seed E/H.
        if v_own_amount<>v_draft_result.allocated_source_ex_vat
           or (v_own_amount>0 and (v_own.allocation_result_id<>v_draft_result.id or v_own.allocation_pass_kind<>'DRAFT')) then
          raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_FROZEN_GROSS_OR_ADDITION_CHANGED';
        end if;
        if v_instruction.payroll_stage='GROSS_ADD' then
          v_state.allocated_gross_additions:=v_state.allocated_gross_additions+v_draft_result.allocated_target_ex_vat;
        elsif v_instruction.payroll_stage='GROSS_DEDUCT' then
          v_state.allocated_gross_deductions:=v_state.allocated_gross_deductions+v_draft_result.allocated_target_ex_vat;
        elsif v_instruction.payroll_stage='NET_ADD' then
          v_state.allocated_net_additions:=v_state.allocated_net_additions+v_draft_result.allocated_target_inc_vat;
          perform private.bpay_next_accumulate_net_destination_v1(v_state.id,v_instruction.id,v_draft_result.id);
        else raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_STAGE_INVALID';end if;
      else
        select * into strict v_case from private.bpay_next_finance_case where id=v_instruction.case_id for update;
        select * into strict v_component from private.bpay_next_case_component where id=v_instruction.case_component_id for update;
        select * into strict v_period from private.bpay_next_case_period
          where case_component_id=v_instruction.case_component_id and pay_week_start=v_instruction.pay_week_start for update;
        if v_own_amount>v_component.active_recovery_source_ex_vat
           or v_own_amount>v_case.active_recovery_hold_amount
           or v_own_amount>v_period.active_unrealised_recovery_source_ex_vat
           or (v_own.id is not null and not (
             (v_request.expected_projection_revision=0 and v_own.allocation_pass_kind='DRAFT'
               and v_own.allocation_result_id=v_draft_result.id)
             or (v_request.expected_projection_revision>0 and v_own.allocation_pass_kind='NET' and exists(
               select 1 from private.bpay_next_case_allocation_result a
                 join private.bpay_next_case_allocation_state s on s.id=a.state_id
               where a.id=v_own.allocation_result_id and s.run_worker_id=v_worker.id
                 and s.pass_kind='NET' and s.projection_no=v_request.expected_projection_revision
                 and s.status='COMPLETE' and s.net_stage='COMPLETE' and s.projection_id is not null)))) then
          raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_SURVIVING_CAPACITY_INVALID';
        end if;
        -- Current disjoint CAPACITY only, never a current rule, valuation,
        -- schedule, nominal, tax, channel or changed-case fallback.
        v_outstanding:=case when v_instruction.case_kind in ('LOAN','ADVANCE') then v_component.funded_source_ex_vat
          else v_component.approved_source_ex_vat end-v_component.recovered_source_ex_vat-v_component.written_off_source_ex_vat;
        v_case_outstanding:=case when v_instruction.case_kind in ('LOAN','ADVANCE') then v_case.principal_funded
          else v_case.principal_approved end-v_case.principal_recovered-v_case.principal_written_off;
        v_capacity:=least(v_draft_result.allocated_source_ex_vat,
          greatest(v_period.opening_due_source_ex_vat-v_period.realised_recovery_source_ex_vat
            -v_period.active_unrealised_recovery_source_ex_vat+v_own_amount,0),
          greatest(v_outstanding-v_component.active_recovery_source_ex_vat+v_own_amount,0),
          greatest(v_case_outstanding-v_case.active_recovery_hold_amount+v_own_amount,0));
        if v_own_amount>v_draft_result.allocated_source_ex_vat then
          raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_DRAFT_CAPACITY_EXCEEDED';
        end if;
        if v_instruction.selected_quote_snapshot is null then v_target_capacity:=v_capacity;
        else
          v_capacity_q:=private.bpay_next_case_quote_from_snapshot_v2(v_instruction.selected_quote_snapshot,v_capacity);
          v_target_capacity:=(v_capacity_q->>'ex')::numeric;
        end if;
        select x.* into strict v_row from private.bpay_next_case_allocation_row_v1(v_instruction.case_kind,
          v_instruction.nominal_target_ex_vat,v_target_capacity,v_e,v_h,v_instruction.minimum_earnings_threshold,
          v_instruction.take_home_floor_override,v_instruction.captured_default_floor) x;
        v_taken:=v_row.taken_amount;
        if v_instruction.selected_quote_snapshot is null then v_source_taken:=v_taken;
        else
          begin
            v_slice:=private.bpay_next_case_source_slice_v2(v_instruction.selected_quote_snapshot,v_taken,v_capacity);
            v_source_taken:=(v_slice->>'source')::numeric;
          exception when sqlstate '55000' then
            if sqlerrm='BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' then
              v_issue:='CASE_INPUT_UNBOUND';exit net_page;else raise;end if;
          end;
        end if;
        -- 0310 requires release/new exact rows, not an amount rewrite. Old
        -- reservation and all three active counters move in this same page.
        if v_own.id is not null then
          update private.bpay_next_case_hold set status='RELEASED',finished_at_utc=pg_catalog.transaction_timestamp() where id=v_own.id;
          update private.bpay_next_case_capacity_use set status='RELEASED' where case_hold_id=v_own.id;
        end if;
        insert into private.bpay_next_case_allocation_result(state_id,instruction_id,run_worker_id,candidate_id,
          preparation_revision,selection_revision,result_no,pass_kind,allocation_channel,hold_purpose,nominal_target_ex_vat,
          usable_capacity_target_ex_vat,allocated_source_ex_vat,allocated_target_ex_vat,allocated_target_vat,allocated_target_inc_vat,
          shortfall_target_ex_vat,cap_reason,affordability_reason,capacity_reason,channel_headroom_before,channel_headroom_after,
          worker_take_home_before,worker_take_home_after)
          values(v_state.id,v_instruction.id,v_worker.id,v_candidate,v_request.preparation_revision,v_request.selection_revision,
            v_state.processed_instruction_count+1,'NET','PAYE','NET_RECOVERY_CAPACITY',v_instruction.nominal_target_ex_vat,
            v_target_capacity,v_source_taken,v_taken,0,v_taken,v_instruction.nominal_target_ex_vat-v_taken,v_row.cap_reason,
            v_row.affordability_reason,v_row.capacity_reason,v_e,v_row.next_channel_headroom,v_h,v_row.next_worker_take_home)
          returning id into v_result_id;
        v_hold_id:=null;
        if v_taken>0 then
          insert into private.bpay_next_case_hold(run_worker_id,candidate_id,case_id,amount,status,instruction_id,
            allocation_result_id,allocation_pass_kind,case_component_id,purpose,pay_week_start,source_reserved_ex_vat,
            target_amount_ex_vat,target_amount_vat,target_amount_inc_vat)
            values(v_worker.id,v_candidate,v_instruction.case_id,v_source_taken,'ACTIVE',v_instruction.id,v_result_id,'NET',
              v_instruction.case_component_id,'NET_RECOVERY_CAPACITY',v_instruction.pay_week_start,v_source_taken,v_taken,0,v_taken)
            returning id into v_hold_id;
          insert into private.bpay_next_case_capacity_use(case_hold_id,case_component_id,case_id,candidate_id,pay_week_start,
            purpose,status,source_amount_ex_vat) values(v_hold_id,v_instruction.case_component_id,v_instruction.case_id,v_candidate,
              v_instruction.pay_week_start,'NET_RECOVERY_CAPACITY','ACTIVE',v_source_taken);
        end if;
        update private.bpay_next_case_component set active_recovery_source_ex_vat=active_recovery_source_ex_vat-v_own_amount+v_source_taken,
          component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id;
        update private.bpay_next_finance_case set active_recovery_hold_amount=active_recovery_hold_amount-v_own_amount+v_source_taken,
          active_hold_amount=active_hold_amount-v_own_amount+v_source_taken,case_revision=case_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp() where id=v_case.id;
        update private.bpay_next_case_period set active_unrealised_recovery_source_ex_vat=active_unrealised_recovery_source_ex_vat-v_own_amount+v_source_taken,
          period_revision=period_revision+1 where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start;
        update private.bpay_next_run_worker set active_case_hold_count=active_case_hold_count
          -case when v_own.id is null then 0 else 1 end+case when v_taken>0 then 1 else 0 end where id=v_worker.id;
        v_state.recovered_source_total:=v_state.recovered_source_total+v_source_taken;
        v_state.recovered_target_total:=v_state.recovered_target_total+v_taken;
        v_e:=v_row.next_channel_headroom;v_h:=v_row.next_worker_take_home;
      end if;
      v_state.processed_instruction_count:=v_state.processed_instruction_count+1;
      v_state.cursor_age_key:=v_instruction.age_key;v_state.cursor_case_id:=v_instruction.case_id;
      v_state.cursor_component_ordinal:=v_instruction.component_ordinal;v_state.cursor_case_component_id:=v_instruction.case_component_id;
    end loop;
    update private.bpay_next_case_allocation_channel set remaining_headroom=v_e where state_id=v_state.id and allocation_channel='PAYE';
    update private.bpay_next_case_allocation_state set processed_instruction_count=v_state.processed_instruction_count,
      remaining_worker_take_home=v_h,recovered_source_total=v_state.recovered_source_total,recovered_target_total=v_state.recovered_target_total,
      cursor_age_key=v_state.cursor_age_key,cursor_case_id=v_state.cursor_case_id,cursor_component_ordinal=v_state.cursor_component_ordinal,
      cursor_case_component_id=v_state.cursor_case_component_id,allocated_gross_additions=v_state.allocated_gross_additions,
      allocated_gross_deductions=v_state.allocated_gross_deductions,allocated_net_additions=v_state.allocated_net_additions where id=v_state.id;
    select exists(select 1 from private.bpay_next_run_case_instruction i where i.run_worker_id=v_worker.id
      and i.preparation_revision=v_request.preparation_revision and i.selection_revision=v_request.selection_revision
      and (v_state.cursor_case_component_id is null or (i.age_key,i.case_id,i.component_ordinal,i.case_component_id)
        >(v_state.cursor_age_key,v_state.cursor_case_id,v_state.cursor_component_ordinal,v_state.cursor_case_component_id))) into v_more;
    if not v_more then
      if v_state.processed_instruction_count<>v_state.expected_instruction_count
         or (v_state.allocated_gross_additions,v_state.allocated_gross_deductions,v_state.allocated_net_additions)
           is distinct from (v_draft.allocated_gross_additions,v_draft.allocated_gross_deductions,v_draft.allocated_net_additions) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_FROZEN_TOTALS_MISMATCH';
      end if;
      v_cash:=coalesce(v_request.entered_paye_net,0)+v_state.allocated_net_additions-v_state.recovered_target_total;
      if v_cash<0 or v_cash>=10000000000000000 then
        raise exception using errcode='22023',message='BPAY_NEXT_CASE_NET_CASH_RANGE_INVALID';
      end if;
      select * into strict v_contribution from private.bpay_next_worker_week_contribution where original_run_worker_id=v_worker.id for update;
      if v_contribution.eligibility_state='UNBOUND' or v_contribution.payment_state<>'ARRANGED'
         or v_contribution.original_gross_amount<>v_request.frozen_gross_inc_vat then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_OWN_WEEK_BASIS_INVALID';
      end if;
      insert into private.bpay_next_net_projection(run_worker_id,request_command_id,projection_no,input_kind,
        gross_ex_vat,gross_vat,gross_inc_vat,entered_paye_net,accepted_recoveries,cash_amount,
        accepted_net_additions,accepted_gross_additions,accepted_gross_deductions)
        values(v_worker.id,v_job.command_id,v_request.request_no,v_request.input_kind,v_worker.gross_ex_vat,0,
          v_worker.gross_inc_vat,v_request.entered_paye_net,v_state.recovered_target_total,v_cash,
          v_state.allocated_net_additions,v_state.allocated_gross_additions,v_state.allocated_gross_deductions)
        returning id into v_projection_id;
      v_own_cash:=private.bpay_next_seal_net_destination_v1(v_state.id,v_projection_id);
      if v_request.expected_projection_revision>0 then
        update private.bpay_next_net_projection set retired_at_utc=pg_catalog.transaction_timestamp()
          where run_worker_id=v_worker.id and projection_no=v_request.expected_projection_revision and retired_at_utc is null;
        if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_NET_PRIOR_SWITCH_INVALID';end if;
      end if;
      update private.bpay_next_worker_week_contribution set
        basis_kind=case when v_request.input_kind='CASE_PAYOUT' then 'GROSS_FALLBACK' else 'PAYROLL_NET' end,
        original_payroll_net=v_request.entered_paye_net,accepted_projection_id=v_projection_id,accepted_bank_cash=v_cash,
        eligibility_state=case when v_request.input_kind='CASE_PAYOUT' then 'EXCLUDED' else 'ELIGIBLE' end,
        eligible_arranged_amount=case when v_request.input_kind='CASE_PAYOUT' then 0 else v_own_cash end,
        contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1
        where id=v_contribution.id;
      update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home
        -v_contribution.eligible_arranged_amount+case when v_request.input_kind='CASE_PAYOUT' then 0 else v_own_cash end,
        period_revision=period_revision+1 where candidate_id=v_candidate and pay_week_start=v_state.pay_week_start;
      if v_request.input_kind='CASE_PAYOUT' then
        update private.bpay_next_case_payout_basis set projection_id=v_projection_id
          where run_worker_id=v_worker.id and preparation_revision=v_request.preparation_revision and projection_id is null;
        if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_PAYOUT_SWITCH_INVALID';end if;
      end if;
      update private.bpay_next_case_allocation_state set status='COMPLETE',net_stage='COMPLETE',projection_id=v_projection_id,
        completed_at_utc=pg_catalog.transaction_timestamp() where id=v_state.id;
      update private.bpay_next_run_worker set entered_paye_net=v_request.entered_paye_net,
        net_projection_revision=v_request.request_no where id=v_worker.id;
      update private.bpay_next_job set status='DONE',phase='PROJECTED',cursor_key=null,lease_nonce=null,lease_until_utc=null where id=p_job_id;
      update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
      v_terminal:=true;
    end if;
  end net_page;
  if v_issue is not null then
    update private.bpay_next_case_allocation_state set net_stage='REVIEW',net_issue_code=v_issue,weekly_binding_state='UNBOUND',
      status='OUTDATED' where id=v_state.id;
    update private.bpay_next_run_worker set status='REVIEW',review_issue_code=v_issue,review_issue_work_id=null,
      case_pending_binding_count=1,financial_resolution_count=financial_resolution_count+1 where id=v_worker.id;
    update private.bpay_next_job set status='DONE',phase='DONE',cursor_key=null,lease_nonce=null,lease_until_utc=null where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
    v_terminal:=true;
  elsif not v_terminal then
    update private.bpay_next_job set cursor_key=(coalesce(v_checkpoint,0)+1)::text where id=p_job_id;
  end if;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1,
    updated_at_utc=pg_catalog.transaction_timestamp() where candidate_id=v_candidate;
  select * into strict v_job from private.bpay_next_job where id=p_job_id;
  return pg_catalog.jsonb_build_object('phase',case when v_issue is not null then 'REVIEW'
      when v_terminal then 'PROJECTED' else 'FINANCE_ALLOCATE' end,'cursor',v_job.cursor_key,
    'rows_visited',v_seen::text,'replay',false,'projection_id',v_projection_id,'run_worker_id',v_worker.id,'issue_code',v_issue);
end
$function$;

alter function private.bpay_next_accept_case_net_request_v1(uuid,uuid,uuid,text,numeric,bigint) OWNER TO CURRENT_USER;
alter function private.bpay_next_accept_case_paye_net_v1(uuid,uuid,uuid,numeric,bigint) OWNER TO CURRENT_USER;
alter function private.bpay_next_accept_case_payout_projection_v1(uuid,uuid,uuid,bigint) OWNER TO CURRENT_USER;
alter function private.bpay_next_apply_case_paye_net_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
alter function private.bpay_next_week_projection_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_net_projection_guard_v1() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_accept_case_net_request_v1(uuid,uuid,uuid,text,numeric,bigint),
  private.bpay_next_accept_case_paye_net_v1(uuid,uuid,uuid,numeric,bigint),
  private.bpay_next_accept_case_payout_projection_v1(uuid,uuid,uuid,bigint),
  private.bpay_next_apply_case_paye_net_page_v1(uuid,uuid,bigint,bigint,integer),
  private.bpay_next_week_projection_guard_v1(),private.bpay_next_net_projection_guard_v1() from public,anon,authenticated,service_role;


-- Original case transfer/member/post owners. The shared 0120/0130/0200
-- owners call these exact seams; no provider, old calculator or history scan.



create or replace function private.bpay_next_begin_case_transfer_v1(p_command_id uuid,p_run_worker_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_transfer private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_draft private.bpay_next_case_allocation_state%rowtype;v_net private.bpay_next_case_allocation_state%rowtype;
  v_destination private.bpay_next_net_destination_state%rowtype;v_cash numeric;
  v_sequence bigint;
begin
  if p_command_id is null or p_run_worker_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_TRANSFER_BEGIN_INPUT_INVALID';end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_command_id::text,0));
  select run_id into strict v_run_id from private.bpay_next_run_worker where id=p_run_worker_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control c join private.bpay_next_run_worker w on w.candidate_id=c.candidate_id
    where w.id=p_run_worker_id for update of c;
  select * into strict v_worker from private.bpay_next_run_worker where id=p_run_worker_id for update;
  select * into v_transfer from private.bpay_next_transfer where build_command_id=p_command_id;
  if found then
    if v_transfer.run_worker_id<>v_worker.id or v_transfer.candidate_id<>v_worker.candidate_id
       or (not exists(select 1 from private.bpay_next_case_transfer_build s where s.transfer_id=v_transfer.id)
         and not exists(select 1 from private.bpay_next_destination_group s where s.anchor_transfer_id=v_transfer.id)) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_BEGIN_REPLAY_CONFLICT';end if;
    select agency_sequence into strict v_sequence from private.bpay_next_command
      where id=p_command_id and command_kind='TRANSFER_BUILD' and module_epoch=v_epoch;
    return pg_catalog.jsonb_build_object('sequence',v_sequence::text,'transfer_id',v_transfer.id,
      'phase',v_transfer.status,'replay',true);
  end if;
  if v_worker.target_pay_channel='UMBRELLA' then
    perform private.bpay_next_capture_umbrella_case_projection_v2(v_worker.id);
    select * into strict v_worker from private.bpay_next_run_worker where id=p_run_worker_id;
  end if;
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null or v_worker.status<>'READY'
     or v_worker.target_pay_channel not in ('PAYE','UMBRELLA') or v_worker.case_selection_revision<1
     or v_worker.case_pending_binding_count<>0 or v_worker.realised_effect_count<>0
     or v_worker.net_projection_revision<1
     or (v_worker.target_pay_channel='PAYE' and v_worker.net_request_revision<>v_worker.net_projection_revision)
     or (v_worker.target_pay_channel='UMBRELLA' and v_worker.net_request_revision<>0)
     or exists(select 1 from private.bpay_next_cancel_request r where r.run_worker_id=v_worker.id
       and r.status in ('REQUESTED','CANCELLING'))
     or exists(select 1 from private.bpay_next_transfer t where t.run_worker_id=v_worker.id) then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_TRANSFER_NOT_ELIGIBLE';end if;
  select * into strict v_projection from private.bpay_next_net_projection
    where run_worker_id=v_worker.id and projection_no=v_worker.net_projection_revision and retired_at_utc is null;
  select * into strict v_draft from private.bpay_next_case_allocation_state where run_worker_id=v_worker.id
    and preparation_revision=v_worker.preparation_revision and selection_revision=v_worker.case_selection_revision
    and pass_kind='DRAFT' and projection_no=0 and status='COMPLETE';
  if v_worker.target_pay_channel='PAYE' then
    select * into strict v_net from private.bpay_next_case_allocation_state where projection_id=v_projection.id
      and run_worker_id=v_worker.id and pass_kind='NET' and status='COMPLETE' and net_stage='COMPLETE';
    if v_draft.processed_instruction_count<>v_worker.case_instruction_count
      or v_net.expected_instruction_count<>v_draft.expected_instruction_count
      or v_net.processed_instruction_count<>v_draft.processed_instruction_count
      or v_net.preparation_revision<>v_draft.preparation_revision or v_net.selection_revision<>v_draft.selection_revision
      or v_projection.input_kind not in ('PAYE_MANUAL','CASE_PAYOUT')
      or (v_projection.gross_ex_vat,v_projection.gross_vat,v_projection.gross_inc_vat,v_projection.entered_paye_net)
        is distinct from (v_worker.gross_ex_vat,v_worker.gross_vat,v_worker.gross_inc_vat,v_worker.entered_paye_net)
      or v_projection.cash_amount<0 or v_projection.request_command_id is null
      or not exists(select 1 from private.bpay_next_job j where j.id=v_net.job_id and j.status='DONE' and j.phase='PROJECTED') then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_PROJECTION_INVALID';end if;
  elsif not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_UM_PROJECTION_INVALID';
  end if;
  -- Zero cash is an internal financial envelope, never a bank instruction.
  select * into v_destination from private.bpay_next_net_destination_state where projection_id=v_projection.id;
  v_cash:=v_projection.cash_amount;
  if found then
    if v_destination.state_id<>v_net.id or v_destination.run_worker_id<>v_worker.id
       or v_destination.completed_at_utc is null or v_destination.cash_amount<>v_projection.cash_amount
       or v_destination.external_leg_count<1 or v_destination.external_amount<=0
       or v_destination.own_amount+v_destination.external_amount<>v_projection.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_DESTINATION_TRANSFER_PROJECTION_INVALID';end if;
    v_cash:=v_destination.own_amount;
  end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'TRANSFER_BUILD');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no) values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_transfer(run_worker_id,candidate_id,projection_id,build_command_id,transfer_no,
    beneficiary_kind,beneficiary_id,cash_amount,status,execution_kind)
    values(v_worker.id,v_worker.candidate_id,v_projection.id,p_command_id,1,
      case when v_worker.target_pay_channel='UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end,
      case when v_worker.target_pay_channel='UMBRELLA' then v_worker.target_umbrella_id else v_worker.candidate_id end,
      v_cash,'BUILDING',case when v_cash=0 then 'INTERNAL_ZERO' else 'BANK' end)
    returning * into v_transfer;
  if v_destination.state_id is not null then
    insert into private.bpay_next_destination_group(anchor_transfer_id,run_worker_id,candidate_id,projection_id,draft_state_id,
      net_state_id,preparation_revision,selection_revision,stage,expected_work_count,expected_case_count,expected_leg_count)
      values(v_transfer.id,v_worker.id,v_worker.candidate_id,v_projection.id,v_draft.id,v_net.id,
        v_worker.preparation_revision,v_worker.case_selection_revision,'WORK',v_worker.captured_line_count,
        v_draft.expected_instruction_count,v_destination.external_leg_count+1);
    insert into private.bpay_next_destination_group_leg(transfer_id,anchor_transfer_id,leg_kind) values(v_transfer.id,v_transfer.id,'OWN');
  else
    insert into private.bpay_next_case_transfer_build(transfer_id,run_worker_id,candidate_id,projection_id,draft_state_id,
      net_state_id,preparation_revision,selection_revision,stage,expected_work_count,expected_case_count,target_pay_channel)
      values(v_transfer.id,v_worker.id,v_worker.candidate_id,v_projection.id,v_draft.id,v_net.id,
        v_worker.preparation_revision,v_worker.case_selection_revision,'WORK',v_worker.captured_line_count,
        v_draft.expected_instruction_count,v_worker.target_pay_channel);
  end if;
  update private.bpay_next_command set expected_member_count=1,status='SEALED',sealed_at_utc=pg_catalog.transaction_timestamp()
    where id=p_command_id;
  return pg_catalog.jsonb_build_object('sequence',v_sequence::text,'transfer_id',v_transfer.id,'phase','BUILDING','replay',false);
end
$function$;

create or replace function private.bpay_next_case_transfer_build_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
declare v_transfer private.bpay_next_transfer%rowtype;v_draft private.bpay_next_case_allocation_state%rowtype;
  v_net private.bpay_next_case_allocation_state%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_projection private.bpay_next_net_projection%rowtype;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_BINDING_DELETE_FORBIDDEN';end if;
  if tg_op='INSERT' then
    select * into strict v_transfer from private.bpay_next_transfer where id=new.transfer_id;
    select * into strict v_draft from private.bpay_next_case_allocation_state where id=new.draft_state_id;
    select * into strict v_worker from private.bpay_next_run_worker where id=new.run_worker_id;
    select * into strict v_projection from private.bpay_next_net_projection where id=new.projection_id;
    if new.target_pay_channel='PAYE' then
      select * into strict v_net from private.bpay_next_case_allocation_state where id=new.net_state_id;
    elsif new.net_state_id is not null or v_worker.target_pay_channel<>'UMBRELLA'
      or not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_UM_BINDING_INVALID';end if;
    if v_transfer.status<>'BUILDING' or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
       or v_transfer.candidate_id<>new.candidate_id or v_transfer.projection_id<>new.projection_id
       or new.target_pay_channel<>v_worker.target_pay_channel
       or v_draft.pass_kind<>'DRAFT' or v_draft.status<>'COMPLETE'
       or v_draft.expected_instruction_count<>new.expected_case_count
       or (new.target_pay_channel='PAYE' and (v_net.pass_kind<>'NET' or v_net.status<>'COMPLETE'
         or v_net.net_stage<>'COMPLETE' or v_net.projection_id<>new.projection_id
         or v_net.expected_instruction_count<>new.expected_case_count))
       or new.stage<>'WORK' or new.checkpoint<>0 or new.processed_work_count<>0 or new.processed_case_count<>0
       or new.work_cursor is not null or new.cursor_age_key is not null
       or new.work_cash_total<>0 or new.gross_additions_total<>0 or new.gross_deductions_total<>0
       or new.net_additions_total<>0 or new.net_recoveries_total<>0 or new.completed_at_utc is not null then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_BINDING_INITIAL_INVALID';end if;
    return new;
  end if;
  if old.stage='COMPLETE'
     or (new.transfer_id,new.run_worker_id,new.candidate_id,new.projection_id,new.draft_state_id,new.net_state_id,
       new.preparation_revision,new.selection_revision,new.expected_work_count,new.expected_case_count,new.created_at_utc)
       is distinct from (old.transfer_id,old.run_worker_id,old.candidate_id,old.projection_id,old.draft_state_id,old.net_state_id,
         old.preparation_revision,old.selection_revision,old.expected_work_count,old.expected_case_count,old.created_at_utc)
     or new.target_pay_channel is distinct from old.target_pay_channel
     or new.checkpoint<>old.checkpoint+1 or new.processed_work_count<old.processed_work_count or new.processed_case_count<old.processed_case_count
     or new.work_cash_total<old.work_cash_total or new.gross_additions_total<old.gross_additions_total
     or new.gross_deductions_total<old.gross_deductions_total or new.net_additions_total<old.net_additions_total or new.net_recoveries_total<old.net_recoveries_total
     or (old.stage='WORK' and new.stage not in ('WORK','CASE'))
     or (old.stage='CASE' and new.stage not in ('CASE','FINAL')) or (old.stage='FINAL' and new.stage<>'COMPLETE')
     or (new.stage='COMPLETE' and (new.completed_at_utc is null or not pg_catalog.isfinite(new.completed_at_utc)))
     or (new.stage<>'COMPLETE' and new.completed_at_utc is not null) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_BINDING_TRANSITION_INVALID';end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_case_transfer_build_guard_v1 on private.bpay_next_case_transfer_build;
create trigger bpay_next_case_transfer_build_guard_v1 before insert or update or delete on private.bpay_next_case_transfer_build
  for each row execute function private.bpay_next_case_transfer_build_guard_v1();

create or replace function private.bpay_next_case_transfer_member_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
declare v_build private.bpay_next_case_transfer_build%rowtype;v_instruction private.bpay_next_run_case_instruction%rowtype;
  v_result private.bpay_next_case_allocation_result%rowtype;v_hold private.bpay_next_case_hold%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;v_line private.bpay_next_run_line%rowtype;v_signed numeric;
begin
  select * into v_build from private.bpay_next_case_transfer_build where transfer_id=new.transfer_id for share;
  if not found then
    v_build:=private.bpay_next_destination_build_binding_v1(new.transfer_id);
    if v_build.transfer_id is not null then
      if v_build.net_state_id is null or not exists(select 1 from private.bpay_next_run_worker w
        where w.id=v_build.run_worker_id and w.candidate_id=v_build.candidate_id and w.target_pay_channel='PAYE') then
        raise exception using errcode='23514',message='BPAY_NEXT_DESTINATION_MEMBER_CHANNEL_INVALID';end if;
      v_build.target_pay_channel:='PAYE';
      perform private.bpay_next_record_destination_member_v1(new);
    else
      if new.subject_kind='CASE' then raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_UNBOUND';end if;
      return new;
    end if;
  end if;
  if new.run_worker_id<>v_build.run_worker_id or v_build.stage='COMPLETE' or new.subject_kind='CASH_REISSUE' then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_SCOPE_INVALID';end if;
  if new.subject_kind='WORK' then
    select * into strict v_line from private.bpay_next_run_line where id=new.run_line_id;
    if v_build.stage<>'WORK' or v_line.run_worker_id<>v_build.run_worker_id or v_line.frozen_inc_vat<>new.signed_cash_contribution then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_WORK_MISMATCH';end if;
  elsif new.subject_kind='NET_ADJUSTMENT' then
    select * into strict v_projection from private.bpay_next_net_projection where id=v_build.projection_id;
    if v_build.target_pay_channel<>'PAYE' or v_build.stage<>'FINAL' or new.signed_cash_contribution is distinct from
      coalesce(v_projection.entered_paye_net,0)-v_projection.gross_inc_vat then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_PAYROLL_ADJUSTMENT_MISMATCH';end if;
  elsif new.subject_kind='CASE' then
    select * into strict v_instruction from private.bpay_next_run_case_instruction where id=new.case_instruction_id;
    select * into strict v_result from private.bpay_next_case_allocation_result where id=new.case_allocation_result_id;
    v_signed:=case when v_instruction.direction='DEDUCTION' then -v_result.allocated_target_inc_vat else v_result.allocated_target_inc_vat end;
    if v_build.stage<>'CASE' or v_instruction.run_worker_id<>v_build.run_worker_id
       or v_instruction.preparation_revision<>v_build.preparation_revision or v_instruction.selection_revision<>v_build.selection_revision
       or v_result.instruction_id<>v_instruction.id or new.signed_cash_contribution<>v_signed
       or v_instruction.target_pay_channel<>v_build.target_pay_channel
       or not private.bpay_next_case_result_quote_valid_v2(v_instruction,v_result)
       or v_result.state_id is distinct from (case when v_instruction.payroll_stage='NET_DEDUCT'
         and v_build.target_pay_channel='PAYE' then v_build.net_state_id else v_build.draft_state_id end) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_FROZEN_RESULT_MISMATCH';end if;
    if v_result.allocated_source_ex_vat=0 then
      if new.case_hold_id is not null then raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_ZERO_HOLD_FORBIDDEN';end if;
    else
      select * into strict v_hold from private.bpay_next_case_hold where id=new.case_hold_id;
      if v_hold.status<>'ACTIVE' or v_hold.run_worker_id<>v_build.run_worker_id or v_hold.instruction_id<>v_instruction.id
         or v_hold.allocation_result_id<>v_result.id
         or (v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat)
           is distinct from (v_result.allocated_source_ex_vat,v_result.allocated_target_ex_vat,v_result.allocated_target_vat,v_result.allocated_target_inc_vat) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_MEMBER_HOLD_MISMATCH';end if;
    end if;
  end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_case_transfer_member_guard_v1 on private.bpay_next_transfer_member;
create trigger bpay_next_case_transfer_member_guard_v1 before insert on private.bpay_next_transfer_member
  for each row execute function private.bpay_next_case_transfer_member_guard_v1();

create or replace function private.bpay_next_build_case_transfer_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,p_expected_cursor bigint,p_limit integer)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_checkpoint bigint;v_cursor bigint;
  v_run private.bpay_next_pay_run%rowtype;v_job private.bpay_next_job%rowtype;v_control private.bpay_next_worker_control%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_transfer private.bpay_next_transfer%rowtype;
  v_build private.bpay_next_case_transfer_build%rowtype;v_projection private.bpay_next_net_projection%rowtype;
  v_draft private.bpay_next_case_allocation_state%rowtype;v_line private.bpay_next_run_line%rowtype;
  v_instruction private.bpay_next_run_case_instruction%rowtype;v_result private.bpay_next_case_allocation_result%rowtype;
  v_hold private.bpay_next_case_hold%rowtype;v_seen integer:=0;v_more boolean;v_signed numeric;v_count bigint;v_sum numeric;v_adjustment numeric;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null or p_owner_epoch<1
     or p_limit is null or p_limit not between 1 and 100 or (p_expected_cursor is not null and p_expected_cursor<1) then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_TRANSFER_PAGE_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select w.run_id,j.candidate_id into strict v_run_id,v_candidate from private.bpay_next_job j
    join private.bpay_next_transfer t on t.build_command_id=j.command_id
    join private.bpay_next_case_transfer_build b on b.transfer_id=t.id
    join private.bpay_next_run_worker w on w.id=b.run_worker_id where j.id=p_job_id and j.candidate_id=w.candidate_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  select * into strict v_control from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w
    join private.bpay_next_transfer t on t.run_worker_id=w.id where t.build_command_id=v_job.command_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer where build_command_id=v_job.command_id for update;
  select * into strict v_build from private.bpay_next_case_transfer_build where transfer_id=v_transfer.id for update;
  select * into strict v_projection from private.bpay_next_net_projection where id=v_build.projection_id;
  select * into strict v_draft from private.bpay_next_case_allocation_state where id=v_build.draft_state_id;
  if v_job.job_kind<>'TRANSFER_BUILD' or v_job.module_epoch<>v_epoch or v_job.candidate_id<>v_build.candidate_id
     or v_transfer.run_worker_id<>v_build.run_worker_id or v_transfer.projection_id<>v_build.projection_id
     or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
     or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_candidate)
       or (v_worker.target_pay_channel='UMBRELLA' and v_transfer.beneficiary_kind='UMBRELLA'
         and v_transfer.beneficiary_id=v_worker.target_umbrella_id and v_transfer.candidate_id=v_candidate)) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_JOB_SCOPE_INVALID';end if;
  if v_job.status='DONE' and v_job.phase='MEMBERS_READY' and v_build.stage='COMPLETE' and v_transfer.status<>'BUILDING' then
    return pg_catalog.jsonb_build_object('phase','MEMBERS_READY','transfer_status',v_transfer.status,'transfer_id',v_transfer.id,
      'cursor',v_job.cursor_key,'member_count',v_transfer.member_count::text,'rows_visited','0','replay',true);
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'WORK' or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_control.active_owner_epoch<>p_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null or v_worker.status<>'READY'
     or v_worker.net_projection_revision<>v_projection.projection_no
     or (v_build.target_pay_channel='PAYE' and v_worker.net_request_revision<>v_projection.projection_no)
     or (v_build.target_pay_channel='UMBRELLA' and not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection))
     or v_projection.retired_at_utc is not null or v_transfer.status<>'BUILDING' or v_transfer.account_approval_ref is not null
     or v_worker.preparation_revision<>v_build.preparation_revision or v_worker.case_selection_revision<>v_build.selection_revision
     or v_transfer.cash_amount<>v_projection.cash_amount
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_CASE_TRANSFER_BUILD_NOT_ELIGIBLE';end if;
  v_checkpoint:=nullif(v_build.checkpoint,0);v_cursor:=nullif(v_job.cursor_key,'')::bigint;
  if v_cursor is distinct from v_checkpoint then raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_CHECKPOINT_MISMATCH';end if;
  if p_expected_cursor is distinct from v_checkpoint then
    if coalesce(p_expected_cursor,0)>coalesce(v_checkpoint,0) then
      raise exception using errcode='55000',message='BPAY_NEXT_CASE_TRANSFER_CURSOR_STALE';end if;
    return pg_catalog.jsonb_build_object('phase','BUILDING','transfer_id',v_transfer.id,'cursor',v_job.cursor_key,
      'member_count',v_transfer.member_count::text,'rows_visited','0','replay',true);
  end if;
  v_count:=v_transfer.member_count;v_sum:=v_transfer.member_cash_sum;
  if v_build.stage='WORK' then
    for v_line in select * from private.bpay_next_run_line where run_worker_id=v_worker.id
      and (v_build.work_cursor is null or line_no>v_build.work_cursor) order by line_no,id limit p_limit loop
      if v_line.target_pay_channel<>v_build.target_pay_channel or v_line.frozen_inc_vat<>v_line.frozen_ex_vat+v_line.frozen_vat
        or (v_build.target_pay_channel='PAYE' and v_line.frozen_vat<>0) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_WORK_BASIS_INVALID';end if;
      v_count:=v_count+1;v_sum:=v_sum+v_line.frozen_inc_vat;v_seen:=v_seen+1;
      insert into private.bpay_next_transfer_member(transfer_id,run_worker_id,member_no,subject_kind,run_line_id,signed_cash_contribution)
        values(v_transfer.id,v_worker.id,v_count,'WORK',v_line.id,v_line.frozen_inc_vat);
      v_build.processed_work_count:=v_build.processed_work_count+1;v_build.work_cash_total:=v_build.work_cash_total+v_line.frozen_inc_vat;
      v_build.work_cursor:=v_line.line_no;
    end loop;
    select exists(select 1 from private.bpay_next_run_line where run_worker_id=v_worker.id
      and (v_build.work_cursor is null or line_no>v_build.work_cursor)) into v_more;
    if not v_more then
      if v_build.processed_work_count<>v_build.expected_work_count or v_build.work_cash_total<>v_draft.captured_work_gross+v_draft.captured_work_vat then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_WORK_TOTAL_INVALID';end if;
      v_build.stage:='CASE';
    end if;
  elsif v_build.stage='CASE' then
    for v_instruction in select * from private.bpay_next_run_case_instruction where run_worker_id=v_worker.id
      and preparation_revision=v_build.preparation_revision and selection_revision=v_build.selection_revision
      and (v_build.cursor_case_component_id is null or (age_key,case_id,component_ordinal,case_component_id)
        >(v_build.cursor_age_key,v_build.cursor_case_id,v_build.cursor_component_ordinal,v_build.cursor_case_component_id))
      order by age_key,case_id,component_ordinal,case_component_id limit p_limit loop
      if v_instruction.target_pay_channel<>v_build.target_pay_channel
        or (v_build.target_pay_channel='PAYE' and v_instruction.nominal_target_vat<>0) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_CASE_BASIS_INVALID';end if;
      select * into strict v_result from private.bpay_next_case_allocation_result where instruction_id=v_instruction.id
        and state_id=case when v_instruction.payroll_stage='NET_DEDUCT' and v_build.target_pay_channel='PAYE'
          then v_build.net_state_id else v_build.draft_state_id end;
      if not private.bpay_next_case_result_quote_valid_v2(v_instruction,v_result) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_SELECTED_QUOTE_INVALID';end if;
      v_hold:=null;
      if v_result.allocated_source_ex_vat>0 then
        select * into strict v_hold from private.bpay_next_case_hold where allocation_result_id=v_result.id and status='ACTIVE' for share;
        if not exists(select 1 from private.bpay_next_case_capacity_use u where u.case_hold_id=v_hold.id and u.status='ACTIVE'
            and u.source_amount_ex_vat=v_result.allocated_source_ex_vat) then
          raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_CAPACITY_MISMATCH';end if;
      end if;
      v_signed:=case when v_instruction.direction='DEDUCTION' then -v_result.allocated_target_inc_vat else v_result.allocated_target_inc_vat end;
      v_count:=v_count+1;v_sum:=v_sum+v_signed;v_seen:=v_seen+1;
      insert into private.bpay_next_transfer_member(transfer_id,run_worker_id,member_no,subject_kind,case_hold_id,
        case_instruction_id,case_allocation_result_id,signed_cash_contribution)
        values(v_transfer.id,v_worker.id,v_count,'CASE',v_hold.id,v_instruction.id,v_result.id,v_signed);
      v_build.processed_case_count:=v_build.processed_case_count+1;
      if v_instruction.payroll_stage='GROSS_ADD' then v_build.gross_additions_total:=v_build.gross_additions_total+v_result.allocated_target_inc_vat;
      elsif v_instruction.payroll_stage='GROSS_DEDUCT' then v_build.gross_deductions_total:=v_build.gross_deductions_total+v_result.allocated_target_inc_vat;
      elsif v_instruction.payroll_stage='NET_ADD' then v_build.net_additions_total:=v_build.net_additions_total+v_result.allocated_target_inc_vat;
      else v_build.net_recoveries_total:=v_build.net_recoveries_total+v_result.allocated_target_inc_vat;end if;
      v_build.cursor_age_key:=v_instruction.age_key;v_build.cursor_case_id:=v_instruction.case_id;
      v_build.cursor_component_ordinal:=v_instruction.component_ordinal;v_build.cursor_case_component_id:=v_instruction.case_component_id;
    end loop;
    select exists(select 1 from private.bpay_next_run_case_instruction where run_worker_id=v_worker.id
      and preparation_revision=v_build.preparation_revision and selection_revision=v_build.selection_revision
      and (v_build.cursor_case_component_id is null or (age_key,case_id,component_ordinal,case_component_id)
        >(v_build.cursor_age_key,v_build.cursor_case_id,v_build.cursor_component_ordinal,v_build.cursor_case_component_id))) into v_more;
    if not v_more then
      if v_build.processed_case_count<>v_build.expected_case_count
         or (v_build.gross_additions_total,v_build.gross_deductions_total,v_build.net_additions_total,v_build.net_recoveries_total)
           is distinct from (v_projection.accepted_gross_additions,v_projection.accepted_gross_deductions,
             v_projection.accepted_net_additions,v_projection.accepted_recoveries) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_CASE_TOTAL_INVALID';end if;
      v_build.stage:='FINAL';
    end if;
  elsif v_build.stage='FINAL' then
    if v_build.work_cash_total+v_build.gross_additions_total-v_build.gross_deductions_total<>v_projection.gross_inc_vat then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_PAYROLL_GROSS_MISMATCH';end if;
    if v_build.target_pay_channel='PAYE' then
      v_adjustment:=coalesce(v_projection.entered_paye_net,0)-v_projection.gross_inc_vat;
      v_count:=v_count+1;v_sum:=v_sum+v_adjustment;v_seen:=1;
      insert into private.bpay_next_transfer_member(transfer_id,run_worker_id,member_no,subject_kind,signed_cash_contribution)
        values(v_transfer.id,v_worker.id,v_count,'NET_ADJUSTMENT',v_adjustment);
    end if;
    if v_count<>v_build.expected_work_count+v_build.expected_case_count+(case when v_build.target_pay_channel='PAYE' then 1 else 0 end)
      or v_sum<>v_projection.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_CASH_MISMATCH';end if;
    v_build.stage:='COMPLETE';v_build.completed_at_utc:=pg_catalog.transaction_timestamp();
  else raise exception using errcode='23514',message='BPAY_NEXT_CASE_TRANSFER_STAGE_INVALID';end if;
  update private.bpay_next_case_transfer_build set stage=v_build.stage,checkpoint=checkpoint+1,
    processed_work_count=v_build.processed_work_count,processed_case_count=v_build.processed_case_count,work_cursor=v_build.work_cursor,
    cursor_age_key=v_build.cursor_age_key,cursor_case_id=v_build.cursor_case_id,cursor_component_ordinal=v_build.cursor_component_ordinal,
    cursor_case_component_id=v_build.cursor_case_component_id,work_cash_total=v_build.work_cash_total,
    gross_additions_total=v_build.gross_additions_total,gross_deductions_total=v_build.gross_deductions_total,
    net_additions_total=v_build.net_additions_total,net_recoveries_total=v_build.net_recoveries_total,completed_at_utc=v_build.completed_at_utc
    where transfer_id=v_transfer.id returning checkpoint into v_cursor;
  update private.bpay_next_transfer set member_count=v_count,member_cash_sum=v_sum,
    status=case when v_build.stage='COMPLETE' then 'MEMBERS_READY' else 'BUILDING' end where id=v_transfer.id;
  update private.bpay_next_job set cursor_key=v_cursor::text,
    status=case when v_build.stage='COMPLETE' then 'DONE' else 'LEASED' end,
    phase=case when v_build.stage='COMPLETE' then 'MEMBERS_READY' else 'WORK' end,
    lease_nonce=case when v_build.stage='COMPLETE' then null else lease_nonce end,
    lease_until_utc=case when v_build.stage='COMPLETE' then null else lease_until_utc end where id=p_job_id;
  if v_build.stage='COMPLETE' then update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;end if;
  return pg_catalog.jsonb_build_object('phase',case when v_build.stage='COMPLETE' then 'MEMBERS_READY' else 'BUILDING' end,
    'transfer_id',v_transfer.id,'cursor',v_cursor::text,'member_count',v_count::text,'rows_visited',v_seen::text,'replay',false);
end
$function$;

-- Called only for the actual immutable CASE member being posted by 0200.
-- Manual principal is not a WORK effect. A captured typed automatic origin
-- links genuine RECOVERED SOURCE back to its immutable original WORK only.
create or replace function private.bpay_next_post_case_transfer_member_v1(p_job_id uuid,p_transfer_id uuid,p_member_no bigint)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare
  v_epoch bigint;v_job private.bpay_next_job%rowtype;v_request private.bpay_next_outcome_request%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;v_outcome private.bpay_next_transfer_outcome%rowtype;
  v_internal private.bpay_next_internal_receipt%rowtype;v_occurred_at timestamptz;
  v_member private.bpay_next_transfer_member%rowtype;v_build private.bpay_next_case_transfer_build%rowtype;
  v_instruction private.bpay_next_run_case_instruction%rowtype;v_result private.bpay_next_case_allocation_result%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_case private.bpay_next_finance_case%rowtype;
  v_component private.bpay_next_case_component%rowtype;v_pair private.bpay_next_case_component%rowtype;
  v_hold private.bpay_next_case_hold%rowtype;v_use private.bpay_next_case_capacity_use%rowtype;
  v_rule private.bpay_next_case_rule%rowtype;v_period_rule private.bpay_next_case_rule%rowtype;
  v_pair_period private.bpay_next_case_period%rowtype;v_origin private.bpay_next_case_create_request%rowtype;
  v_event_id uuid;v_new_rule_id uuid;v_kind text;v_amount numeric;v_signed numeric;
begin
  if p_job_id is null or p_transfer_id is null or p_member_no is null or p_member_no<1 then
    raise exception using errcode='22023',message='BPAY_NEXT_CASE_POST_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select * into strict v_job from private.bpay_next_job where id=p_job_id;
  select * into strict v_request from private.bpay_next_outcome_request where command_id=v_job.command_id and transfer_id=p_transfer_id;
  select * into strict v_transfer from private.bpay_next_transfer where id=p_transfer_id;
  select * into v_build from private.bpay_next_case_transfer_build where transfer_id=p_transfer_id;
  if not found then
    v_build:=private.bpay_next_destination_build_binding_v1(p_transfer_id);
    if v_build.transfer_id is null then raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_TRANSFER_UNBOUND';end if;
    if v_build.net_state_id is null or not exists(select 1 from private.bpay_next_run_worker w
      where w.id=v_build.run_worker_id and w.candidate_id=v_build.candidate_id and w.target_pay_channel='PAYE') then
      raise exception using errcode='23514',message='BPAY_NEXT_DESTINATION_POST_CHANNEL_INVALID';end if;
    v_build.target_pay_channel:='PAYE';
  end if;
  select * into strict v_member from private.bpay_next_transfer_member where transfer_id=p_transfer_id and member_no=p_member_no;
  if v_job.job_kind='INTERNAL_SETTLEMENT' then
    select * into strict v_internal from private.bpay_next_internal_receipt where id=v_request.internal_receipt_id;
    if v_request.outcome_id is not null or v_transfer.execution_kind<>'INTERNAL_ZERO' or v_transfer.cash_amount<>0
       or v_transfer.status<>'INTERNAL_PROCESSING' or v_internal.command_id<>v_job.command_id
       or v_internal.transfer_id<>v_transfer.id or v_internal.run_worker_id<>v_build.run_worker_id
       or v_internal.candidate_id<>v_build.candidate_id or v_internal.projection_id<>v_build.projection_id then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_INTERNAL_POST_SCOPE_INVALID';end if;
    v_occurred_at:=v_internal.occurred_at_utc;
  elsif v_job.job_kind='CSV_SETTLEMENT' then
    select * into strict v_outcome from private.bpay_next_transfer_outcome where id=v_request.outcome_id;
    if v_request.internal_receipt_id is not null or v_transfer.execution_kind<>'BANK'
       or v_transfer.status not in ('SETTLED','RETURNED') or v_outcome.transfer_id<>v_transfer.id
       or v_outcome.outcome_kind<>'SETTLED' or v_outcome.whole_transfer_amount<>v_transfer.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_BANK_POST_SCOPE_INVALID';end if;
    v_occurred_at:=v_outcome.occurred_at_utc;
  else raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_JOB_KIND_INVALID';end if;
  if v_job.module_epoch<>v_epoch or v_job.status<>'LEASED' or v_job.phase<>'MEMBERS'
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp() or v_job.candidate_id<>v_build.candidate_id
     or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
     or v_build.stage<>'COMPLETE' or v_member.subject_kind<>'CASE' or v_member.run_worker_id<>v_build.run_worker_id
     or v_occurred_at is null or not pg_catalog.isfinite(v_occurred_at)
     or not exists(select 1 from private.bpay_next_worker_control where candidate_id=v_job.candidate_id and active_owner_epoch=v_job.owner_epoch) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_SCOPE_INVALID';end if;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_build.run_worker_id for update;
  select * into strict v_instruction from private.bpay_next_run_case_instruction where id=v_member.case_instruction_id;
  select * into strict v_result from private.bpay_next_case_allocation_result where id=v_member.case_allocation_result_id;
  v_signed:=case when v_instruction.direction='DEDUCTION' then -v_result.allocated_target_inc_vat else v_result.allocated_target_inc_vat end;
  if v_instruction.run_worker_id<>v_worker.id or v_instruction.candidate_id<>v_worker.candidate_id
     or v_result.instruction_id<>v_instruction.id or v_member.signed_cash_contribution<>v_signed
     or v_result.state_id is distinct from (case when v_instruction.payroll_stage='NET_DEDUCT' and v_build.target_pay_channel='PAYE'
       then v_build.net_state_id else v_build.draft_state_id end)
     or v_instruction.target_pay_channel<>v_worker.target_pay_channel
     or not private.bpay_next_case_result_quote_valid_v2(v_instruction,v_result) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_FROZEN_RESULT_MISMATCH';end if;
  select * into strict v_case from private.bpay_next_finance_case where id=v_instruction.case_id for update;
  select * into strict v_component from private.bpay_next_case_component where id=v_instruction.case_component_id for update;
  perform 1 from private.bpay_next_case_period where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start for update;
  v_amount:=v_result.allocated_source_ex_vat;
  if v_amount>0 then
    select * into strict v_hold from private.bpay_next_case_hold where id=v_member.case_hold_id for update;
    select * into strict v_use from private.bpay_next_case_capacity_use where case_hold_id=v_hold.id for update;
    if v_hold.status<>'ACTIVE' or v_use.status<>'ACTIVE' or v_hold.allocation_result_id<>v_result.id
       or v_hold.instruction_id<>v_instruction.id or v_hold.run_worker_id<>v_worker.id
       or (v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat)
         is distinct from (v_amount,v_result.allocated_target_ex_vat,v_result.allocated_target_vat,v_result.allocated_target_inc_vat)
       or v_use.source_amount_ex_vat<>v_amount or v_worker.active_case_hold_count<1 then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_HOLD_MISMATCH';end if;
    v_kind:=case when v_instruction.instruction_kind='PAYOUT' then 'FUNDED'
      when v_instruction.instruction_kind='CREDIT' then 'PAID' else 'RECOVERED' end;
    v_event_id:=pg_catalog.gen_random_uuid();
    insert into private.bpay_next_case_event(id,case_id,operation_id,operation_item_id,event_kind,original_transfer_id,occurred_at_utc,
      funded_delta,recovered_delta,paid_credit_delta,instruction_id,allocation_result_id,run_worker_id,candidate_id,case_component_id,
      event_case_kind,hold_purpose,pay_week_start,source_amount_ex_vat,target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,shortfall_source_ex_vat)
      values(v_event_id,v_case.id,v_job.command_id,v_hold.id,v_kind,v_transfer.id,v_occurred_at,
        case when v_kind='FUNDED' then v_amount else 0 end,case when v_kind='RECOVERED' then v_amount else 0 end,
        case when v_kind='PAID' then v_amount else 0 end,v_instruction.id,v_result.id,v_worker.id,v_worker.candidate_id,v_component.id,
        v_instruction.case_kind,v_instruction.hold_purpose,v_instruction.pay_week_start,v_amount,v_result.allocated_target_ex_vat,
        v_result.allocated_target_vat,v_result.allocated_target_inc_vat,0);
    if v_kind='FUNDED' then
      select * into strict v_origin from private.bpay_next_case_create_request where case_id=v_case.id
        and primary_component_id=v_component.id and recovery_component_id is not null;
      select * into strict v_pair from private.bpay_next_case_component where id=v_origin.recovery_component_id for update;
      select * into strict v_rule from private.bpay_next_case_rule where id=v_case.current_rule_id;
      if v_pair.case_id<>v_case.id or v_pair.instruction_kind<>'RECOVERY' or v_pair.case_kind<>v_instruction.case_kind
         or v_occurred_at<v_rule.case_created_at_utc then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_FUNDING_ORIGIN_INVALID';end if;
      v_new_rule_id:=v_rule.id;
      if v_rule.original_funding_event_id is null then
        v_new_rule_id:=pg_catalog.gen_random_uuid();
        insert into private.bpay_next_case_rule(id,case_id,candidate_id,rule_revision,case_kind,case_subtype,tax_treatment,
          case_created_at_utc,original_funded_at_utc,original_funding_event_id,minimum_earnings_threshold,take_home_floor_override,
          weekly_due_source_ex_vat,schedule_start_monday,next_due_monday,schedule_week_count)
          values(v_new_rule_id,v_case.id,v_worker.candidate_id,v_rule.rule_revision+1,v_rule.case_kind,v_rule.case_subtype,v_rule.tax_treatment,
            v_rule.case_created_at_utc,v_occurred_at,v_event_id,v_rule.minimum_earnings_threshold,v_rule.take_home_floor_override,
            v_rule.weekly_due_source_ex_vat,v_rule.schedule_start_monday,v_rule.next_due_monday,v_rule.schedule_week_count);
      end if;
      update private.bpay_next_case_component set funded_source_ex_vat=funded_source_ex_vat+v_amount,
        active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,rule_id=v_new_rule_id,
        component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp()
        where id=v_component.id and active_payout_source_ex_vat>=v_amount;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_FUNDING_COMPONENT_CAPACITY_INVALID';end if;
      -- Mirrored payout/recovery components describe ONE funded principal.
      update private.bpay_next_case_component set funded_source_ex_vat=funded_source_ex_vat+v_amount,
        rule_id=v_new_rule_id,component_revision=component_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_pair.id;
      -- Exact creation-owned zero period only; never rewrite consumed opening
      -- facts or scan previously captured pay weeks to manufacture due.
      select * into strict v_pair_period from private.bpay_next_case_period where case_component_id=v_pair.id
        and pay_week_start=v_origin.input_start_monday for update;
      select * into strict v_period_rule from private.bpay_next_case_rule where id=v_pair_period.rule_id;
      if v_period_rule.original_funding_event_id is null
         and (v_period_rule.case_id,v_period_rule.candidate_id,v_period_rule.case_kind,v_period_rule.case_subtype,
           v_period_rule.tax_treatment,v_period_rule.case_created_at_utc,v_period_rule.minimum_earnings_threshold,
           v_period_rule.take_home_floor_override,v_period_rule.weekly_due_source_ex_vat,v_period_rule.schedule_start_monday,
           v_period_rule.next_due_monday,v_period_rule.schedule_week_count)
           is not distinct from (v_rule.case_id,v_rule.candidate_id,v_rule.case_kind,v_rule.case_subtype,
             v_rule.tax_treatment,v_rule.case_created_at_utc,v_rule.minimum_earnings_threshold,v_rule.take_home_floor_override,
             v_rule.weekly_due_source_ex_vat,v_rule.schedule_start_monday,v_rule.next_due_monday,v_rule.schedule_week_count)
         and (v_pair_period.opening_outstanding_source_ex_vat,v_pair_period.opening_due_source_ex_vat,
           v_pair_period.realised_recovery_source_ex_vat,v_pair_period.active_unrealised_recovery_source_ex_vat,v_pair_period.active_payout_source_ex_vat)
           is not distinct from (0::numeric,0::numeric,0::numeric,0::numeric,0::numeric) then
        update private.bpay_next_case_period set rule_id=v_new_rule_id,
          opening_outstanding_source_ex_vat=v_pair.funded_source_ex_vat+v_amount,
          opening_due_source_ex_vat=least(v_rule.weekly_due_source_ex_vat,v_pair.funded_source_ex_vat+v_amount),period_revision=period_revision+1
          where case_component_id=v_pair.id and pay_week_start=v_origin.input_start_monday;
      end if;
      update private.bpay_next_finance_case set principal_funded=principal_funded+v_amount,
        active_payout_hold_amount=active_payout_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
        current_rule_id=v_new_rule_id,current_rule_revision=case when v_new_rule_id=v_rule.id then v_rule.rule_revision else v_rule.rule_revision+1 end,
        case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp()
        where id=v_case.id and active_payout_hold_amount>=v_amount and active_hold_amount>=v_amount;
    elsif v_kind='PAID' then
      update private.bpay_next_case_component set paid_credit_source_ex_vat=paid_credit_source_ex_vat+v_amount,
        active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,component_revision=component_revision+1,
        updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id and active_payout_source_ex_vat>=v_amount;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CREDIT_COMPONENT_CAPACITY_INVALID';end if;
      update private.bpay_next_finance_case set principal_paid_credit=principal_paid_credit+v_amount,
        active_payout_hold_amount=active_payout_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
        case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp()
        where id=v_case.id and active_payout_hold_amount>=v_amount and active_hold_amount>=v_amount;
    else
      update private.bpay_next_case_component set recovered_source_ex_vat=recovered_source_ex_vat+v_amount,
        active_recovery_source_ex_vat=active_recovery_source_ex_vat-v_amount,component_revision=component_revision+1,
        updated_at_utc=pg_catalog.transaction_timestamp() where id=v_component.id and active_recovery_source_ex_vat>=v_amount;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_RECOVERY_COMPONENT_CAPACITY_INVALID';end if;
      update private.bpay_next_finance_case set principal_recovered=principal_recovered+v_amount,
        active_recovery_hold_amount=active_recovery_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
        case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp()
        where id=v_case.id and active_recovery_hold_amount>=v_amount and active_hold_amount>=v_amount;
    end if;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_PRINCIPAL_CAPACITY_INVALID';end if;
    if v_kind in ('FUNDED','PAID') then
      update private.bpay_next_case_period set active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,
        period_revision=period_revision+1 where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start
          and active_payout_source_ex_vat>=v_amount;
    else
      update private.bpay_next_case_period set active_unrealised_recovery_source_ex_vat=active_unrealised_recovery_source_ex_vat-v_amount,
        realised_recovery_source_ex_vat=realised_recovery_source_ex_vat+v_amount,period_revision=period_revision+1
        where case_component_id=v_component.id and pay_week_start=v_instruction.pay_week_start and active_unrealised_recovery_source_ex_vat>=v_amount;
    end if;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_PERIOD_CAPACITY_INVALID';end if;
    update private.bpay_next_case_hold set status='REALISED',finished_at_utc=pg_catalog.transaction_timestamp(),
      projection_id=case when purpose='NET_RECOVERY_CAPACITY' then v_build.projection_id else projection_id end where id=v_hold.id;
    update private.bpay_next_case_capacity_use set status='REALISED',realisation_event_id=v_event_id where case_hold_id=v_hold.id;
    update private.bpay_next_run_worker set active_case_hold_count=active_case_hold_count-1,realised_effect_count=realised_effect_count+1 where id=v_worker.id;
    if v_kind='RECOVERED' and v_instruction.work_collection_id is not null then
      perform private.bpay_next_apply_work_collection_recovery_v1(p_job_id,v_event_id);
    end if;
  elsif v_member.case_hold_id is not null then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_POST_ZERO_HOLD_FORBIDDEN';
  end if;
  if v_instruction.instruction_kind='RECOVERY' and v_result.shortfall_target_ex_vat>0 then
    insert into private.bpay_next_case_event(case_id,operation_id,operation_item_id,event_kind,original_transfer_id,occurred_at_utc,
      instruction_id,allocation_result_id,run_worker_id,candidate_id,case_component_id,event_case_kind,hold_purpose,pay_week_start,
      source_amount_ex_vat,target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,shortfall_source_ex_vat,cap_reason)
      values(v_case.id,v_job.command_id,v_result.id,'SHORTFALL',v_transfer.id,v_occurred_at,v_instruction.id,v_result.id,
        v_worker.id,v_worker.candidate_id,v_component.id,v_instruction.case_kind,v_instruction.hold_purpose,v_instruction.pay_week_start,
        0,0,0,0,v_instruction.nominal_source_ex_vat-v_amount,v_result.cap_reason);
  end if;
end
$function$;

alter function private.bpay_next_begin_case_transfer_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_case_transfer_member_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_case_transfer_build_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_build_case_transfer_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
alter function private.bpay_next_post_case_transfer_member_v1(uuid,uuid,bigint) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_begin_case_transfer_v1(uuid,uuid),private.bpay_next_case_transfer_member_guard_v1(),
  private.bpay_next_case_transfer_build_guard_v1(),
  private.bpay_next_build_case_transfer_page_v1(uuid,uuid,bigint,bigint,integer),private.bpay_next_post_case_transfer_member_v1(uuid,uuid,bigint)
  from public,anon,authenticated,service_role;


-- One maintained original weekly contribution follows its actual owned outcome.
-- No history scan/backfill, earnings reprice, payroll/principal inverse or bank
-- action. B1 remains UNBOUND for returned payroll, not non-earnings CASE_PAYOUT.
-- Install additive 0440 before first use of the CASE_PAYOUT return branch.



create or replace function private.bpay_next_apply_week_outcome_v1(
  p_job_id uuid,p_return_cash_id uuid default null
) returns void
language plpgsql security definer set search_path=pg_catalog,private,public
as $function$
declare
  v_job private.bpay_next_job%rowtype;
  v_control private.bpay_next_worker_control%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;
  v_original private.bpay_next_transfer%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;
  v_outcome private.bpay_next_transfer_outcome%rowtype;
  v_settlement private.bpay_next_outcome_request%rowtype;
  v_return private.bpay_next_return_request%rowtype;
  v_cash private.bpay_next_return_cash%rowtype;
  v_week private.bpay_next_worker_week%rowtype;
  v_prior private.bpay_next_worker_week_contribution%rowtype;
  v_run private.bpay_next_pay_run%rowtype;
  v_epoch bigint;v_worker_id uuid;v_candidate uuid;v_transfer_id uuid;
  v_outcome_id uuid;v_posted boolean;v_next_state text;v_payout boolean;
  v_old_resolved numeric;v_unresolved_delta integer:=0;
  v_leg private.bpay_next_destination_group_leg%rowtype;
  v_destination private.bpay_next_net_destination_state%rowtype;
begin
  if p_job_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_WEEK_OUTCOME_INPUT_INVALID';
  end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id;
  if v_job.job_kind='CSV_SETTLEMENT' then
    select r.* into strict v_settlement from private.bpay_next_outcome_request r where r.command_id=v_job.command_id;
    v_worker_id:=v_settlement.run_worker_id;v_candidate:=v_settlement.candidate_id;
    v_transfer_id:=v_settlement.transfer_id;v_outcome_id:=v_settlement.outcome_id;
    if p_return_cash_id is not null then
      raise exception using errcode='22023',message='BPAY_NEXT_WEEK_SETTLEMENT_CASH_ARGUMENT_INVALID';
    end if;
  elsif v_job.job_kind='CSV_RETURN' then
    select r.* into strict v_return from private.bpay_next_return_request r where r.command_id=v_job.command_id;
    v_worker_id:=v_return.run_worker_id;v_candidate:=v_return.candidate_id;
    v_transfer_id:=v_return.transfer_id;v_outcome_id:=v_return.outcome_id;
    if p_return_cash_id is null then
      raise exception using errcode='22023',message='BPAY_NEXT_WEEK_RETURN_CASH_REQUIRED';
    end if;
  else raise exception using errcode='23514',message='BPAY_NEXT_WEEK_OUTCOME_JOB_KIND_INVALID';end if;
  -- Same order as the posting caller, also safe for an owner-only first-use
  -- probe: header -> Candidate control -> job -> worker -> transfer/cash -> week.
  select r.* into strict v_run from private.bpay_next_pay_run r
    join private.bpay_next_run_worker w on w.run_id=r.id where w.id=v_worker_id for update of r;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_candidate for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w where w.id=v_worker_id for update;
  select t.* into strict v_transfer from private.bpay_next_transfer t where t.id=v_transfer_id for update;
  select o.* into strict v_outcome from private.bpay_next_transfer_outcome o where o.id=v_outcome_id;
  if v_job.job_kind='CSV_SETTLEMENT' then
    select r.* into strict v_settlement from private.bpay_next_outcome_request r where r.command_id=v_job.command_id;
    v_posted:=v_settlement.posting_complete and v_settlement.posted_member_count=v_transfer.member_count;
  else
    select r.* into strict v_return from private.bpay_next_return_request r where r.command_id=v_job.command_id;
    v_posted:=v_return.posting_complete;
  end if;
  if v_job.module_epoch<>v_epoch or v_job.candidate_id<>v_candidate
     or v_worker.candidate_id<>v_candidate or v_worker.run_id<>v_run.id
     or v_transfer.candidate_id<>v_candidate or v_transfer.run_worker_id<>v_worker.id
     or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE'
         and v_transfer.beneficiary_id=v_candidate)
       or (v_worker.target_pay_channel='UMBRELLA' and (v_worker.case_selection_revision=0 or exists(
         select 1 from private.bpay_next_net_projection p where p.id=coalesce(v_transfer.projection_id,
           (select projection_id from private.bpay_next_transfer where id=v_transfer.original_transfer_id))
           and private.bpay_next_umbrella_case_projection_valid_v2(v_worker,p)))
         and v_worker.target_umbrella_id is not null and v_transfer.beneficiary_kind='UMBRELLA'
         and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
     or v_outcome.transfer_id<>v_transfer.id or v_outcome.whole_transfer_amount<>v_transfer.cash_amount
     or v_outcome.outcome_kind<>(case when v_job.job_kind='CSV_SETTLEMENT' then 'SETTLED' else 'RETURNED' end)
     or v_posted is not true then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_OUTCOME_SCOPE_INVALID';
  end if;
  select t.* into strict v_original from private.bpay_next_transfer t
    where t.id=coalesce(v_transfer.original_transfer_id,v_transfer.id) for update;
  if v_original.original_transfer_id is not null or v_original.return_cash_id is not null
     or v_original.run_worker_id<>v_worker.id or v_original.candidate_id<>v_candidate
     or v_original.beneficiary_kind is distinct from v_transfer.beneficiary_kind
     or v_original.beneficiary_id is distinct from v_transfer.beneficiary_id then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ORIGINAL_TRANSFER_INVALID';
  end if;
  if v_job.job_kind='CSV_RETURN' or v_transfer.return_cash_id is not null then
    select c.* into strict v_cash from private.bpay_next_return_cash c
      where c.id=coalesce(p_return_cash_id,v_transfer.return_cash_id) for update;
    if v_cash.original_transfer_id<>v_original.id or v_cash.candidate_id<>v_candidate
       or v_cash.amount_owed<>v_original.cash_amount
       or (v_transfer.return_cash_id is not null and v_transfer.return_cash_id<>v_cash.id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RETURN_CASH_NOT_EXACT';
    end if;
  end if;
  -- The posting transition and this helper commit atomically. A delayed old
  -- DONE helper is readback, not adoption/backfill of its old reissue pointer.
  if v_job.status='DONE' then return;end if;
  if v_job.status<>'LEASED' or v_job.lease_nonce is null
     or v_job.owner_epoch<>v_control.active_owner_epoch
     or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_transfer.status not in ('SETTLED','RETURNED')
     or (v_job.job_kind='CSV_RETURN' and v_transfer.status<>'RETURNED') then
    raise exception using errcode='55000',message='BPAY_NEXT_WEEK_OUTCOME_OWNER_INVALID';
  end if;
  if v_worker.target_pay_channel<>'PAYE' and not (v_worker.target_pay_channel='UMBRELLA'
    and v_worker.case_selection_revision>0
    and private.bpay_next_umbrella_case_completed_transfer_valid_v2(v_worker,v_original)) then return;end if;
  v_leg:=private.bpay_next_destination_execution_leg_v1(v_original.id);
  if v_leg.transfer_id is not null then
    -- One-off cash is not the Candidate's own weekly take-home contribution.
    -- Its exact receipt still posts its CASE members through the normal owner.
    if v_leg.leg_kind='ONEOFF' then return;end if;
    select n.* into strict v_destination from private.bpay_next_destination_group g
      join private.bpay_next_net_destination_state n on n.state_id=g.net_state_id
      where g.anchor_transfer_id=v_leg.anchor_transfer_id;
  end if;
  select w.* into v_week from private.bpay_next_worker_week w
    where w.candidate_id=v_candidate
      and w.pay_week_start=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1) for update;
  select x.* into v_prior from private.bpay_next_worker_week_contribution x
    where x.original_run_worker_id=v_worker.id for update;
  if v_prior.id is null then
    if v_worker.case_selection_revision<>0 then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CASE_CONTRIBUTION_MISSING';
    end if;
    -- An explicitly unbound no-case READY floor has no contribution. Do not
    -- reconstruct one from a now-paid transfer or guess its earlier earnings.
    raise notice 'BPAY_NEXT_WEEK_ORIGINAL_CONTRIBUTION_UNBOUND';return;
  end if;
  select p.* into strict v_projection from private.bpay_next_net_projection p where p.id=v_original.projection_id;
  if v_week.candidate_id is null or v_prior.candidate_id<>v_candidate
     or v_prior.pay_week_start<>v_week.pay_week_start
     or v_prior.original_pay_date<>v_run.pay_date or v_prior.original_created_at_utc<>v_run.created_at_utc
     or v_prior.original_gross_amount<>(case when v_projection.umbrella_case_draft_state_id is not null
       then v_projection.gross_ex_vat else v_projection.gross_inc_vat end)
     or v_prior.accepted_projection_id is distinct from v_projection.id
     or v_prior.accepted_bank_cash is distinct from v_projection.cash_amount
     or v_projection.run_worker_id<>v_worker.id
     or v_original.cash_amount<>(case when v_leg.transfer_id is null then v_projection.cash_amount else v_destination.own_amount end)
     or (v_prior.original_transfer_id is not null and v_prior.original_transfer_id<>v_original.id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ORIGINAL_CONTRIBUTION_NOT_EXACT';
  end if;
  v_payout:=v_projection.input_kind='CASE_PAYOUT';
  if v_payout and (v_prior.basis_kind<>'GROSS_FALLBACK' or v_prior.original_gross_amount<>0
     or v_prior.original_payroll_net is not null or v_prior.eligibility_state<>'EXCLUDED'
     or v_prior.eligible_arranged_amount is distinct from 0::numeric) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_NON_EARNINGS_BASIS_INVALID';
  end if;
  if v_job.job_kind='CSV_SETTLEMENT' and v_transfer.original_transfer_id is null then
    -- RETURNED may already be RECEIVED: original payroll posting still comes
    -- first. The ordered return owner will later publish the actual cash FK.
    if v_prior.payment_state='PAID' and v_prior.original_transfer_id=v_original.id then return;end if;
    if v_prior.payment_state<>'ARRANGED' or v_prior.eligibility_state='UNBOUND' then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_ORIGINAL_SETTLEMENT_STATE_INVALID';
    end if;
    update private.bpay_next_worker_week_contribution set payment_state='PAID',original_transfer_id=v_original.id,
      contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
    update private.bpay_next_worker_week set period_revision=period_revision+1
      where candidate_id=v_candidate and pay_week_start=v_week.pay_week_start;
    return;
  end if;
  if v_prior.original_transfer_id is distinct from v_original.id
     or (v_prior.returned_cash_id is not null and v_prior.returned_cash_id<>v_cash.id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RETURN_ORIGINAL_NOT_PAID';
  end if;
  if v_job.job_kind='CSV_SETTLEMENT' then
    v_next_state:='REISSUED_PAID';
    if v_prior.payment_state='REISSUED_PAID' and v_prior.reissue_transfer_id=v_transfer.id then return;end if;
    if v_prior.payment_state<>'RETURNED_OWED' or v_prior.returned_cash_id is distinct from v_cash.id
       or v_cash.amount_reissued_paid<v_transfer.cash_amount then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_REISSUE_SETTLEMENT_STATE_INVALID';
    end if;
  else
    v_next_state:='RETURNED_OWED';
    if v_prior.payment_state='RETURNED_OWED' and v_prior.returned_cash_id=v_cash.id
       and (v_transfer.original_transfer_id is null or v_prior.reissue_transfer_id=v_transfer.id) then return;end if;
    if (v_transfer.original_transfer_id is null and v_prior.payment_state<>'PAID')
       or (v_transfer.original_transfer_id is not null and
         (v_prior.payment_state<>'REISSUED_PAID' or v_prior.reissue_transfer_id is distinct from v_transfer.id)) then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RETURN_PAYMENT_STATE_INVALID';
    end if;
  end if;
  v_old_resolved:=coalesce(v_prior.eligible_arranged_amount,0);
  if not v_payout and v_prior.eligibility_state<>'UNBOUND' then v_unresolved_delta:=1;end if;
  update private.bpay_next_worker_week_contribution set payment_state=v_next_state,returned_cash_id=v_cash.id,
    reissue_transfer_id=case when v_transfer.original_transfer_id is not null then v_transfer.id else reissue_transfer_id end,
    eligibility_state=case when v_payout then 'EXCLUDED' else 'UNBOUND' end,
    eligible_arranged_amount=case when v_payout then 0 else null end,
    contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
  update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home-v_old_resolved,
    unresolved_contribution_count=unresolved_contribution_count+v_unresolved_delta,period_revision=period_revision+1
    where candidate_id=v_candidate and pay_week_start=v_week.pay_week_start
      and resolved_arranged_take_home>=v_old_resolved;
  if not found then raise exception using errcode='23514',message='BPAY_NEXT_WEEK_RESOLVED_DELTA_INVALID';end if;
end
$function$;

create or replace function private.bpay_next_apply_cancelled_week_v1(p_job_id uuid)
returns void language plpgsql security definer set search_path=pg_catalog,private,public
as $function$
declare
  v_job private.bpay_next_job%rowtype;v_request private.bpay_next_cancel_request%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_run private.bpay_next_pay_run%rowtype;
  v_control private.bpay_next_worker_control%rowtype;v_week private.bpay_next_worker_week%rowtype;
  v_prior private.bpay_next_worker_week_contribution%rowtype;v_transfer private.bpay_next_transfer%rowtype;
  v_case_cancel private.bpay_next_case_cancel_binding%rowtype;
  v_group private.bpay_next_destination_group%rowtype;v_group_cancel private.bpay_next_destination_cancel%rowtype;
  v_epoch bigint;v_transfer_count integer:=0;v_old_resolved numeric;v_old_unresolved integer;
begin
  if p_job_id is null then raise exception using errcode='22023',message='BPAY_NEXT_WEEK_CANCEL_INPUT_INVALID';end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id;
  if v_job.job_kind<>'SIMPLE_CANCEL' then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CANCEL_JOB_KIND_INVALID';
  end if;
  select r.* into strict v_request from private.bpay_next_cancel_request r where r.command_id=v_job.command_id;
  select r.* into strict v_run from private.bpay_next_pay_run r
    join private.bpay_next_run_worker w on w.run_id=r.id where w.id=v_request.run_worker_id for update of r;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_request.candidate_id for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w where w.id=v_request.run_worker_id for update;
  if v_job.job_kind<>'SIMPLE_CANCEL' or v_job.module_epoch<>v_epoch
     or v_job.candidate_id<>v_worker.candidate_id or v_request.candidate_id<>v_worker.candidate_id
     or v_request.status<>'CANCELLED' or v_worker.status<>'CANCELLED'
     or v_request.released_line_count<>v_request.expected_line_count
     or v_job.applied_line_count<>v_request.released_line_count
     or v_worker.realised_effect_count<>0 or v_worker.financial_resolution_count<>0
     then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CANCEL_SCOPE_INVALID';
  end if;
  if v_worker.case_selection_revision>0 then
    select b.* into strict v_case_cancel from private.bpay_next_case_cancel_binding b
      where b.command_id=v_job.command_id;
    if v_case_cancel.run_worker_id<>v_worker.id or v_case_cancel.candidate_id<>v_worker.candidate_id
       or v_case_cancel.preparation_revision<>v_worker.preparation_revision
       or v_case_cancel.selection_revision<>v_worker.case_selection_revision
       or v_case_cancel.status<>'CANCELLED' or v_case_cancel.stage<>'COMPLETE'
       or v_case_cancel.expected_work_count<>v_request.expected_line_count
       or v_case_cancel.released_work_count<>v_request.released_line_count
       or v_case_cancel.expected_case_hold_count is null
       or v_case_cancel.released_case_hold_count<>v_case_cancel.expected_case_hold_count
       or v_worker.active_case_hold_count<>0
       or v_request.cursor_line_no is distinct from v_case_cancel.checkpoint
       or v_job.cursor_key is distinct from v_case_cancel.checkpoint::text
       or exists(select 1 from private.bpay_next_case_hold h
           where h.run_worker_id=v_worker.id and h.status='ACTIVE') then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CASE_CANCEL_BINDING_INVALID';
    end if;
  end if;
  if v_job.status='DONE' then return;end if;
  if v_job.status<>'LEASED' or v_job.phase<>'RELEASE' or v_job.lease_nonce is null
     or v_job.owner_epoch<>v_control.active_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_control.pending_outcome_count<>0 then
    raise exception using errcode='55000',message='BPAY_NEXT_WEEK_CANCEL_OWNER_INVALID';
  end if;
  select g.* into v_group from private.bpay_next_destination_group g where g.run_worker_id=v_worker.id;
  if found then
    -- The guarded certificate counts exact <=100-row CHECK and FINAL ranges.
    -- Do not scan every sibling again or use an arbitrary counter as authority.
    select c.* into strict v_group_cancel from private.bpay_next_destination_cancel c where c.command_id=v_job.command_id;
    if v_worker.case_selection_revision<1 or v_group.candidate_id<>v_worker.candidate_id
       or v_group.stage<>'COMPLETE' or v_group.sealed_leg_count<>v_group.expected_leg_count
       or v_group_cancel.anchor_transfer_id<>v_group.anchor_transfer_id
       or v_group_cancel.expected_leg_count<>v_group.expected_leg_count
       or v_group_cancel.checked_leg_count<>v_group_cancel.expected_leg_count
       or v_group_cancel.cancelled_leg_count<>v_group_cancel.expected_leg_count
       or v_group_cancel.check_cursor is null or v_group_cancel.cancel_cursor is null
       or v_group_cancel.check_cursor<>v_group_cancel.cancel_cursor
       or v_case_cancel.transfer_id is distinct from v_group.anchor_transfer_id
       or v_case_cancel.projection_id is distinct from v_group.projection_id
       or v_case_cancel.net_state_id is distinct from v_group.net_state_id then
      raise exception using errcode='23514',message='BPAY_NEXT_WEEK_DESTINATION_CANCEL_CERTIFICATE_INVALID';
    end if;
  else
    -- Ordinary no-split scope retains its exact one-original-transfer guard.
    for v_transfer in select t.* from private.bpay_next_transfer t where t.run_worker_id=v_worker.id
      order by t.transfer_no limit 2 for update
    loop
      v_transfer_count:=v_transfer_count+1;
      if v_transfer_count>1 or v_transfer.status<>'CANCELLED' or v_transfer.original_transfer_id is not null
         or v_transfer.return_cash_id is not null or v_transfer.candidate_id<>v_worker.candidate_id
         or v_transfer.account_approval_ref is not null
         or exists(select 1 from private.bpay_next_csv_instruction i where i.transfer_id=v_transfer.id)
         or exists(select 1 from private.bpay_next_transfer_outcome o where o.transfer_id=v_transfer.id) then
        raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CANCEL_TRANSFER_PROTECTED';
      end if;
    end loop;
  end if;
  select w.* into v_week from private.bpay_next_worker_week w where w.candidate_id=v_worker.candidate_id
    and w.pay_week_start=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1) for update;
  select x.* into v_prior from private.bpay_next_worker_week_contribution x where x.original_run_worker_id=v_worker.id for update;
  if v_prior.id is null then raise notice 'BPAY_NEXT_WEEK_CANCEL_CONTRIBUTION_UNBOUND';return;end if;
  if v_week.candidate_id is null or v_prior.candidate_id<>v_worker.candidate_id
     or v_prior.pay_week_start<>v_week.pay_week_start or v_prior.original_pay_date<>v_run.pay_date
     or v_prior.original_created_at_utc<>v_run.created_at_utc or v_prior.original_gross_amount<>(case when v_worker.target_pay_channel='UMBRELLA' and v_worker.case_selection_revision>0
       then v_worker.gross_ex_vat else v_worker.gross_inc_vat end)
     or v_prior.original_transfer_id is not null or v_prior.returned_cash_id is not null or v_prior.reissue_transfer_id is not null then
    raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CANCEL_CONTRIBUTION_NOT_EXACT';
  end if;
  if v_prior.payment_state='CANCELLED' and v_prior.eligibility_state='EXCLUDED' and v_prior.eligible_arranged_amount=0 then return;end if;
  if v_prior.payment_state<>'ARRANGED' then raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CANCEL_NOT_UNPAID';end if;
  v_old_resolved:=coalesce(v_prior.eligible_arranged_amount,0);
  v_old_unresolved:=case when v_prior.eligibility_state='UNBOUND' then 1 else 0 end;
  update private.bpay_next_worker_week_contribution set payment_state='CANCELLED',eligibility_state='EXCLUDED',eligible_arranged_amount=0,
    contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
  update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home-v_old_resolved,
    unresolved_contribution_count=unresolved_contribution_count-v_old_unresolved,period_revision=period_revision+1
    where candidate_id=v_worker.candidate_id and pay_week_start=v_week.pay_week_start
      and resolved_arranged_take_home>=v_old_resolved and unresolved_contribution_count>=v_old_unresolved;
  if not found then raise exception using errcode='23514',message='BPAY_NEXT_WEEK_CANCEL_DELTA_INVALID';end if;
end
$function$;
alter function private.bpay_next_apply_week_outcome_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_apply_cancelled_week_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_apply_week_outcome_v1(uuid,uuid),
  private.bpay_next_apply_cancelled_week_v1(uuid) from public,anon,authenticated,service_role;



-- Actual ordered original CASE cancellation. Main0260 dispatches here using
-- the worker's immutable case selection, not live Candidate cases. Shared
--0430 completes the maintained weekly contribution in the FINAL transaction.



create or replace function private.bpay_next_case_cancel_block_v1(p_run_worker_id uuid,p_allow_pending boolean default false)
returns text language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_worker private.bpay_next_run_worker%rowtype;v_transfer private.bpay_next_transfer%rowtype;v_count integer:=0;
 v_group private.bpay_next_destination_group%rowtype;
begin
  select * into strict v_worker from private.bpay_next_run_worker where id=p_run_worker_id;
  if v_worker.status<>'READY' or v_worker.case_selection_revision<1 or v_worker.target_pay_channel not in ('PAYE','UMBRELLA')
     or v_worker.gross_inc_vat<0 or v_worker.gross_inc_vat<>v_worker.gross_ex_vat+v_worker.gross_vat
     or (v_worker.target_pay_channel='PAYE' and (v_worker.target_umbrella_id is not null or v_worker.gross_vat<>0
       or v_worker.net_projection_revision>v_worker.net_request_revision))
     or (v_worker.target_pay_channel='UMBRELLA' and (v_worker.target_umbrella_id is null
       or v_worker.target_umbrella_vat_chargeable is null or v_worker.entered_paye_net is not null
       or v_worker.net_request_revision<>0 or (v_worker.net_projection_revision<>0 and not exists(
         select 1 from private.bpay_next_net_projection p where p.run_worker_id=v_worker.id
           and p.projection_no=v_worker.net_projection_revision and private.bpay_next_umbrella_case_projection_valid_v2(v_worker,p)))))
     or v_worker.case_pending_binding_count<>0 then
    return 'BPAY_NEXT_CANCEL_CASE_GROUP_NOT_DRAFT';end if;
  if v_worker.realised_effect_count<>0 or v_worker.financial_resolution_count<>0
     or exists(select 1 from private.bpay_next_worker_control where candidate_id=v_worker.candidate_id and pending_outcome_count<>0) then
    return 'BPAY_NEXT_CANCEL_GROUP_REALISED_OR_PENDING_OUTCOME';end if;
  if not exists(select 1 from private.bpay_next_case_allocation_state where run_worker_id=v_worker.id
      and preparation_revision=v_worker.preparation_revision and selection_revision=v_worker.case_selection_revision
      and pass_kind='DRAFT' and projection_no=0 and status='COMPLETE' and prepare_stage='COMPLETE'
      and expected_instruction_count=v_worker.case_instruction_count and processed_instruction_count=v_worker.case_instruction_count) then
    return 'BPAY_NEXT_CANCEL_CASE_BINDING_INVALID';end if;
  if p_allow_pending is not true and v_worker.target_pay_channel='PAYE'
    and v_worker.net_request_revision<>v_worker.net_projection_revision then
    return 'BPAY_NEXT_CANCEL_PROJECTION_PENDING';end if;
  select * into v_group from private.bpay_next_destination_group where run_worker_id=v_worker.id;
  if found then
    if v_group.candidate_id<>v_worker.candidate_id
      or (p_allow_pending is not true and v_group.stage<>'COMPLETE') then
      return 'BPAY_NEXT_CANCEL_DESTINATION_GROUP_NOT_READY';end if;
    -- Do not examine a whole transfer group here. The ordered job performs an
    -- indexed <=100-leg CHECK phase before changing worker state/releasing holds.
    return null;
  end if;
  if p_allow_pending is true and exists(select 1 from private.bpay_next_net_projection p
      join private.bpay_next_net_destination_state d on d.projection_id=p.id
      join private.bpay_next_transfer t on t.projection_id=p.id and t.run_worker_id=v_worker.id
      join private.bpay_next_command c on c.id=t.build_command_id
      where p.run_worker_id=v_worker.id and p.projection_no=v_worker.net_projection_revision and p.retired_at_utc is null
        and d.run_worker_id=v_worker.id and d.completed_at_utc is not null and d.external_leg_count>0
        and t.original_transfer_id is null and t.status='BUILDING' and c.command_kind='TRANSFER_BUILD'
        and c.status in ('SEALED','ENROLLING','COMPLETE')) then
    -- Genuine earlier accepted builder has not created its group yet. Existing
    -- Candidate command ordering finishes it before SIMPLE_CANCEL can claim.
    return null;
  end if;
  for v_transfer in select * from private.bpay_next_transfer where run_worker_id=v_worker.id order by transfer_no limit 2 loop
    v_count:=v_count+1;
    if v_count>1 then return 'BPAY_NEXT_CANCEL_MULTI_TRANSFER_UNSUPPORTED';end if;
    if v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
       or v_transfer.candidate_id<>v_worker.candidate_id
       or not ((v_worker.target_pay_channel='PAYE' and v_transfer.beneficiary_kind='CANDIDATE' and v_transfer.beneficiary_id=v_worker.candidate_id)
         or (v_worker.target_pay_channel='UMBRELLA' and v_transfer.beneficiary_kind='UMBRELLA'
           and v_transfer.beneficiary_id=v_worker.target_umbrella_id))
       or not exists(select 1 from private.bpay_next_case_transfer_build where transfer_id=v_transfer.id and run_worker_id=v_worker.id) then
      return 'BPAY_NEXT_CANCEL_REISSUE_OR_NON_CANDIDATE_UNSUPPORTED';end if;
    if v_transfer.status not in ('MEMBERS_READY','DRAFT','SCHEDULED')
       and not (p_allow_pending is true and v_transfer.status='BUILDING') then
      return 'BPAY_NEXT_CANCEL_TRANSFER_PROTECTED';end if;
    if v_transfer.account_approval_ref is not null
       or exists(select 1 from private.bpay_next_csv_instruction where transfer_id=v_transfer.id)
       or exists(select 1 from private.bpay_next_transfer_outcome where transfer_id=v_transfer.id)
       or exists(select 1 from private.bpay_next_internal_receipt where transfer_id=v_transfer.id) then
      return 'BPAY_NEXT_CANCEL_INSTRUCTION_OR_OUTCOME_PROTECTED';end if;
  end loop;
  return null;
end
$function$;

create or replace function private.bpay_next_accept_case_cancel_v1(p_command_id uuid,p_run_worker_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_epoch bigint;v_run_id uuid;v_run private.bpay_next_pay_run%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_request private.bpay_next_cancel_request%rowtype;v_draft private.bpay_next_case_allocation_state%rowtype;
  v_sequence bigint;v_block text;
begin
  if p_command_id is null or p_run_worker_id is null then raise exception using errcode='22023',message='BPAY_NEXT_CASE_CANCEL_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_command_id::text,0));
  select run_id into strict v_run_id from private.bpay_next_run_worker where id=p_run_worker_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control c join private.bpay_next_run_worker w on w.candidate_id=c.candidate_id where w.id=p_run_worker_id for update of c;
  select * into strict v_worker from private.bpay_next_run_worker where id=p_run_worker_id for update;
  select * into v_request from private.bpay_next_cancel_request where command_id=p_command_id;
  if found then
    if v_request.run_worker_id<>v_worker.id or v_request.candidate_id<>v_worker.candidate_id
       or not exists(select 1 from private.bpay_next_case_cancel_binding where command_id=p_command_id and run_worker_id=v_worker.id) then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_REPLAY_CONFLICT';end if;
    select agency_sequence into strict v_sequence from private.bpay_next_command where id=p_command_id and command_kind='SIMPLE_CANCEL' and module_epoch=v_epoch;
    return pg_catalog.jsonb_build_object('sequence',v_sequence,'run_worker_id',v_worker.id,'phase',v_request.status,
      'cursor',v_request.cursor_line_no,'released_line_count',v_request.released_line_count,'blocked_code',v_request.blocked_code,'replay',true);
  end if;
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null or v_run.selection_state<>'SEALED'
     or exists(select 1 from private.bpay_next_cancel_request where run_worker_id=v_worker.id and status in ('REQUESTED','CANCELLING')) then
    raise exception using errcode='55000',message='BPAY_NEXT_CANCEL_NOT_ELIGIBLE';end if;
  v_block:=private.bpay_next_case_cancel_block_v1(v_worker.id,true);
  if v_block is not null then raise exception using errcode='55000',message=v_block;end if;
  select * into strict v_draft from private.bpay_next_case_allocation_state where run_worker_id=v_worker.id
    and preparation_revision=v_worker.preparation_revision and selection_revision=v_worker.case_selection_revision
    and pass_kind='DRAFT' and projection_no=0 and status='COMPLETE';
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'SIMPLE_CANCEL');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no) values(p_command_id,v_worker.candidate_id,1);
  insert into private.bpay_next_cancel_request(command_id,run_worker_id,candidate_id,expected_line_count,status)
    values(p_command_id,v_worker.id,v_worker.candidate_id,v_worker.captured_line_count,'REQUESTED');
  insert into private.bpay_next_case_cancel_binding(command_id,run_worker_id,candidate_id,draft_state_id,
    preparation_revision,selection_revision,status,stage,expected_work_count)
    values(p_command_id,v_worker.id,v_worker.candidate_id,v_draft.id,v_worker.preparation_revision,v_worker.case_selection_revision,
      'REQUESTED','INTENT',v_worker.captured_line_count);
  update private.bpay_next_command set expected_member_count=1,status='SEALED',sealed_at_utc=pg_catalog.transaction_timestamp() where id=p_command_id;
  return pg_catalog.jsonb_build_object('sequence',v_sequence,'run_worker_id',v_worker.id,'phase','REQUESTED','cursor',null,'released_line_count',0,'replay',false);
end
$function$;

create or replace function private.bpay_next_case_cancel_binding_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
declare v_request private.bpay_next_cancel_request%rowtype;v_draft private.bpay_next_case_allocation_state%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_projection private.bpay_next_net_projection%rowtype;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_BINDING_DELETE_FORBIDDEN';end if;
  if tg_op='INSERT' then
    select * into strict v_request from private.bpay_next_cancel_request where command_id=new.command_id;
    select * into strict v_draft from private.bpay_next_case_allocation_state where id=new.draft_state_id;
    if new.status<>'REQUESTED' or new.stage<>'INTENT' or new.checkpoint<>0 or new.released_work_count<>0
       or new.released_case_hold_count<>0 or new.work_cursor is not null or new.case_hold_cursor is not null
       or v_request.status<>'REQUESTED' or v_request.run_worker_id<>new.run_worker_id or v_request.candidate_id<>new.candidate_id
       or v_request.expected_line_count<>new.expected_work_count or v_draft.pass_kind<>'DRAFT'
       or v_draft.status<>'COMPLETE' or v_draft.prepare_stage<>'COMPLETE' then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_BINDING_INITIAL_INVALID';end if;
    return new;
  end if;
  if old.status in ('CANCELLED','BLOCKED')
     or (new.command_id,new.run_worker_id,new.candidate_id,new.draft_state_id,new.preparation_revision,new.selection_revision,new.expected_work_count,new.created_at_utc)
       is distinct from (old.command_id,old.run_worker_id,old.candidate_id,old.draft_state_id,old.preparation_revision,old.selection_revision,old.expected_work_count,old.created_at_utc)
     or new.checkpoint<>old.checkpoint+1 or new.released_work_count<old.released_work_count or new.released_case_hold_count<old.released_case_hold_count
     or (old.work_cursor is not null and (new.work_cursor is null or new.work_cursor<old.work_cursor))
     or (old.case_hold_cursor is not null and (new.case_hold_cursor is null or new.case_hold_cursor<old.case_hold_cursor))
     or (old.stage='INTENT' and new.stage not in ('WORK','CASE','BLOCKED')
       and not (new.stage='INTENT' and new.status='REQUESTED' and exists(select 1 from private.bpay_next_destination_cancel p
         where p.command_id=new.command_id and p.checked_leg_count>0 and p.checked_leg_count<p.expected_leg_count)))
     or (old.stage='WORK' and new.stage not in ('WORK','CASE')) or (old.stage='CASE' and new.stage not in ('CASE','FINAL'))
     or (old.stage='FINAL' and new.stage<>'COMPLETE'
       and not (new.stage='FINAL' and new.status='CANCELLING' and exists(select 1 from private.bpay_next_destination_cancel p
         where p.command_id=new.command_id and p.checked_leg_count=p.expected_leg_count
           and p.cancelled_leg_count>0 and p.cancelled_leg_count<p.expected_leg_count)))
     or (old.status='CANCELLING' and (new.expected_case_hold_count,new.accepted_projection_revision,new.projection_id,new.net_state_id,new.umbrella_draft_state_id,new.transfer_id,new.started_at_utc)
       is distinct from (old.expected_case_hold_count,old.accepted_projection_revision,old.projection_id,old.net_state_id,old.umbrella_draft_state_id,old.transfer_id,old.started_at_utc)) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_BINDING_TRANSITION_INVALID';end if;
  if new.accepted_projection_revision>0 then
    select * into strict v_worker from private.bpay_next_run_worker where id=new.run_worker_id;
    select * into strict v_projection from private.bpay_next_net_projection where id=new.projection_id;
    if v_worker.target_pay_channel='UMBRELLA' then
      if new.net_state_id is not null or new.umbrella_draft_state_id is distinct from new.draft_state_id
        or v_projection.umbrella_case_draft_state_id is distinct from new.umbrella_draft_state_id
        or v_projection.projection_no<>new.accepted_projection_revision
        or v_worker.net_projection_revision<>new.accepted_projection_revision or v_worker.status<>new.status
        or not private.bpay_next_umbrella_case_projection_snapshot_valid_v2(v_worker,v_projection)
        or not ((new.status='CANCELLING' and v_projection.retired_at_utc is null)
          or (new.status='CANCELLED' and v_projection.retired_at_utc is not null
            and v_projection.retired_at_utc is not distinct from new.finished_at_utc)) then
        raise exception 'BPAY_NEXT_UM_CASE_CANCEL_TYPED_PROJECTION_INVALID' using errcode='23514';end if;
    elsif v_worker.target_pay_channel<>'PAYE' or new.umbrella_draft_state_id is not null or new.net_state_id is null then
      raise exception 'BPAY_NEXT_CASE_CANCEL_CHANNEL_OWNER_INVALID' using errcode='23514';
    end if;
  end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_case_cancel_binding_guard_v1 on private.bpay_next_case_cancel_binding;
create trigger bpay_next_case_cancel_binding_guard_v1 before insert or update or delete on private.bpay_next_case_cancel_binding
  for each row execute function private.bpay_next_case_cancel_binding_guard_v1();

create or replace function private.bpay_next_cancel_case_worker_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,p_expected_cursor bigint,p_limit integer)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_checkpoint bigint;v_seen integer:=0;v_holds integer:=0;v_block text;v_more boolean;
  v_run private.bpay_next_pay_run%rowtype;v_control private.bpay_next_worker_control%rowtype;v_job private.bpay_next_job%rowtype;
  v_request private.bpay_next_cancel_request%rowtype;v_worker private.bpay_next_run_worker%rowtype;v_binding private.bpay_next_case_cancel_binding%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;v_net private.bpay_next_case_allocation_state%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;v_line private.bpay_next_run_line%rowtype;v_work_hold private.bpay_next_hold%rowtype;
  v_hold private.bpay_next_case_hold%rowtype;v_use private.bpay_next_case_capacity_use%rowtype;
  v_instruction private.bpay_next_run_case_instruction%rowtype;v_result private.bpay_next_case_allocation_result%rowtype;
  v_case private.bpay_next_finance_case%rowtype;v_component private.bpay_next_case_component%rowtype;
  v_period private.bpay_next_case_period%rowtype;v_amount numeric;v_now timestamptz:=pg_catalog.transaction_timestamp();
  v_group private.bpay_next_destination_group%rowtype;v_group_page jsonb;v_group_started boolean:=false;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null or p_owner_epoch<1 or p_limit is null or p_limit not between 1 and 100
     or (p_expected_cursor is not null and p_expected_cursor<1) then raise exception using errcode='22023',message='BPAY_NEXT_CASE_CANCEL_PAGE_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select w.run_id,j.candidate_id into strict v_run_id,v_candidate from private.bpay_next_job j
    join private.bpay_next_cancel_request r on r.command_id=j.command_id join private.bpay_next_run_worker w on w.id=r.run_worker_id
    where j.id=p_job_id and j.candidate_id=w.candidate_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  select * into strict v_control from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_cancel_request where command_id=v_job.command_id for update;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_request.run_worker_id for update;
  select * into strict v_binding from private.bpay_next_case_cancel_binding where command_id=v_job.command_id for update;
  if v_job.job_kind<>'SIMPLE_CANCEL' or v_job.module_epoch<>v_epoch or v_job.candidate_id<>v_binding.candidate_id
     or v_request.run_worker_id<>v_binding.run_worker_id or v_worker.candidate_id<>v_binding.candidate_id
     or v_worker.preparation_revision<>v_binding.preparation_revision or v_worker.case_selection_revision<>v_binding.selection_revision
     or v_request.expected_line_count<>v_binding.expected_work_count or v_request.released_line_count<>v_binding.released_work_count
     or v_job.applied_line_count<>v_binding.released_work_count
     or coalesce(v_request.cursor_line_no,0)<>v_binding.checkpoint or v_job.cursor_key is distinct from nullif(v_binding.checkpoint,0)::text
     or not exists(select 1 from private.bpay_next_command where id=v_job.command_id and command_kind='SIMPLE_CANCEL'
       and agency_sequence=v_job.command_sequence and module_epoch=v_epoch and expected_member_count=1 and enrolled_member_count=1) then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_SCOPE_INVALID';end if;
  if v_job.status='DONE' and v_request.status in ('CANCELLED','BLOCKED') and v_binding.status=v_request.status then
    return pg_catalog.jsonb_build_object('phase',v_request.status,'run_worker_id',v_worker.id,'cursor',v_job.cursor_key,
      'released_line_count',v_request.released_line_count,'blocked_code',v_request.blocked_code,'rows_visited',0,'holds_released',0,'replay',true);
  end if;
  if v_job.status<>'LEASED' or v_job.phase not in ('NEW','RELEASE') or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_control.active_owner_epoch<>p_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or exists(select 1 from private.bpay_next_job where candidate_id=v_candidate and command_sequence<v_job.command_sequence and status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_CANCEL_PAGE_LEASE_INVALID';end if;
  if coalesce(p_expected_cursor,0)<>v_binding.checkpoint then
    if coalesce(p_expected_cursor,0)>v_binding.checkpoint then raise exception using errcode='55000',message='BPAY_NEXT_CASE_CANCEL_CURSOR_STALE';end if;
    return pg_catalog.jsonb_build_object('phase',v_request.status,'run_worker_id',v_worker.id,'cursor',v_job.cursor_key,
      'released_line_count',v_request.released_line_count,'rows_visited',0,'holds_released',0,'replay',true);
  end if;
  select * into v_group from private.bpay_next_destination_group where run_worker_id=v_worker.id;
  if v_binding.status='REQUESTED' then
    if v_job.phase<>'NEW' or v_request.status<>'REQUESTED' then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_INTENT_INVALID';end if;
    v_block:=private.bpay_next_case_cancel_block_v1(v_worker.id,false);
    if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null or v_worker.captured_line_count<>v_binding.expected_work_count then
      v_block:='BPAY_NEXT_CANCEL_DRAFT_CHANGED';end if;
    if v_block is null and v_group.anchor_transfer_id is not null then
      v_group_page:=private.bpay_next_check_destination_cancel_page_v1(p_job_id,p_limit);
      v_block:=v_group_page->>'blocked_code';v_seen:=(v_group_page->>'rows_visited')::integer;
      if v_block is null and (v_group_page->>'complete')::boolean is not true then
        update private.bpay_next_case_cancel_binding set checkpoint=checkpoint+1 where command_id=v_job.command_id
          returning checkpoint into v_checkpoint;
        update private.bpay_next_cancel_request set cursor_line_no=v_checkpoint where command_id=v_job.command_id;
        update private.bpay_next_job set cursor_key=v_checkpoint::text,
          lease_until_utc=pg_catalog.clock_timestamp()+pg_catalog.make_interval(secs=>120) where id=p_job_id;
        return pg_catalog.jsonb_build_object('phase','REQUESTED','run_worker_id',v_worker.id,'cursor',v_checkpoint,
          'released_line_count',0,'rows_visited',v_seen,'holds_released',0,'replay',false);
      end if;
      v_group_started:=true;
    end if;
    if v_block is not null then
      update private.bpay_next_case_cancel_binding set status='BLOCKED',stage='BLOCKED',checkpoint=checkpoint+1,blocked_code=v_block,finished_at_utc=v_now
        where command_id=v_job.command_id returning checkpoint into v_checkpoint;
      update private.bpay_next_cancel_request set status='BLOCKED',blocked_code=v_block,finished_at_utc=v_now,cursor_line_no=v_checkpoint where command_id=v_job.command_id;
      update private.bpay_next_job set status='DONE',phase='BLOCKED',cursor_key=v_checkpoint::text,last_error_code=v_block,lease_nonce=null,lease_until_utc=null where id=p_job_id;
      update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
      return pg_catalog.jsonb_build_object('phase','BLOCKED','run_worker_id',v_worker.id,'cursor',v_checkpoint,
        'released_line_count',0,'blocked_code',v_block,'rows_visited',v_seen,'holds_released',0,'replay',false);
    end if;
    v_binding.accepted_projection_revision:=v_worker.net_projection_revision;
    if v_worker.net_projection_revision>0 then
      select * into strict v_projection from private.bpay_next_net_projection where run_worker_id=v_worker.id
        and projection_no=v_worker.net_projection_revision and retired_at_utc is null;
      if v_worker.target_pay_channel='UMBRELLA' then
        if not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection)
          or v_projection.umbrella_case_draft_state_id is distinct from v_binding.draft_state_id then
          raise exception 'BPAY_NEXT_UM_CASE_CANCEL_DRAFT_BINDING_INVALID' using errcode='23514';end if;
        v_binding.umbrella_draft_state_id:=v_binding.draft_state_id;v_binding.net_state_id:=null;
      else
        select * into strict v_net from private.bpay_next_case_allocation_state where projection_id=v_projection.id and run_worker_id=v_worker.id
          and pass_kind='NET' and status='COMPLETE' and net_stage='COMPLETE';
        if v_net.preparation_revision<>v_binding.preparation_revision or v_net.selection_revision<>v_binding.selection_revision
          or v_projection.input_kind not in ('PAYE_MANUAL','CASE_PAYOUT') then
          raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_NET_BINDING_INVALID';end if;
        v_binding.net_state_id:=v_net.id;
      end if;
      v_binding.projection_id:=v_projection.id;
    end if;
    if v_group.anchor_transfer_id is not null then
      v_binding.transfer_id:=v_group.anchor_transfer_id;
    else
      select * into v_transfer from private.bpay_next_transfer where run_worker_id=v_worker.id for update;
      if found then v_binding.transfer_id:=v_transfer.id;update private.bpay_next_transfer set status='CANCELLED' where id=v_transfer.id;end if;
    end if;
    v_binding.expected_case_hold_count:=v_worker.active_case_hold_count;v_binding.started_at_utc:=v_now;
    v_binding.status:='CANCELLING';v_binding.stage:='WORK';
    update private.bpay_next_run_worker set status='CANCELLING' where id=v_worker.id;
    update private.bpay_next_cancel_request set status='CANCELLING',started_at_utc=v_now where command_id=v_job.command_id;
    update private.bpay_next_job set phase='RELEASE' where id=p_job_id;
    v_worker.status:='CANCELLING';v_request.status:='CANCELLING';
  end if;
  if v_binding.status<>'CANCELLING' or v_worker.status<>'CANCELLING' or v_request.status<>'CANCELLING'
     or v_run.status<>'DRAFT' or v_worker.realised_effect_count<>0 or v_worker.financial_resolution_count<>0 or v_control.pending_outcome_count<>0
     or (v_worker.target_pay_channel='PAYE' and v_worker.net_request_revision<>v_binding.accepted_projection_revision)
     or (v_worker.target_pay_channel='UMBRELLA' and v_worker.net_request_revision<>0)
     or v_worker.net_projection_revision<>v_binding.accepted_projection_revision then
    raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_FENCE_BROKEN';end if;
  if v_group_started then
    -- This STEP examined only the CHECK page. WORK release starts next STEP;
    -- do not combine two independent <=100-row phases into a 200-row call.
    null;
  elsif v_binding.stage='WORK' then
    for v_line in select * from private.bpay_next_run_line where run_worker_id=v_worker.id and line_no>coalesce(v_binding.work_cursor,0)
      order by line_no,id limit p_limit loop
      select * into v_work_hold from private.bpay_next_hold where run_line_id=v_line.id for update;
      if found then
        if v_work_hold.status<>'ACTIVE' or (v_work_hold.work_id,v_work_hold.component_key,v_work_hold.source_reserved_ex_vat,
          v_work_hold.target_amount_ex_vat,v_work_hold.target_amount_vat,v_work_hold.target_amount_inc_vat)
          is distinct from (v_line.work_id,v_line.component_key,v_line.source_consumed_ex_vat,v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat) then
          raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_HOLD_NOT_EXACT_ACTIVE';end if;
        update private.bpay_next_hold set status='RELEASED',finished_at_utc=v_now where id=v_work_hold.id;
        if not private.bpay_next_source_comparison_carry_known_work_v2(p_job_id,v_line.id,'RELEASE',v_work_hold.id) then
          update private.bpay_next_position set held_source_ex_vat=held_source_ex_vat-v_work_hold.source_reserved_ex_vat,
            held_target_ex_vat=held_target_ex_vat-v_work_hold.target_amount_ex_vat,held_target_vat=held_target_vat-v_work_hold.target_amount_vat,
            held_target_inc_vat=held_target_inc_vat-v_work_hold.target_amount_inc_vat,updated_at_utc=v_now
            where work_id=v_work_hold.work_id and component_key=v_work_hold.component_key and held_source_ex_vat>=v_work_hold.source_reserved_ex_vat
              and held_target_ex_vat>=v_work_hold.target_amount_ex_vat and held_target_vat>=v_work_hold.target_amount_vat and held_target_inc_vat>=v_work_hold.target_amount_inc_vat;
          if not found then raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_POSITION_HOLD_MISMATCH';end if;
        end if;
        v_holds:=v_holds+1;
      elsif (v_line.source_consumed_ex_vat,v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat) is distinct from (0::numeric,0::numeric,0::numeric,0::numeric) then
        raise exception using errcode='23514',message='BPAY_NEXT_CANCEL_POSITIVE_HOLD_MISSING';end if;
      v_binding.work_cursor:=v_line.line_no;v_binding.released_work_count:=v_binding.released_work_count+1;v_seen:=v_seen+1;
    end loop;
    select exists(select 1 from private.bpay_next_run_line where run_worker_id=v_worker.id and line_no>coalesce(v_binding.work_cursor,0)) into v_more;
    if not v_more then
      if v_binding.released_work_count<>v_binding.expected_work_count then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_WORK_COUNT_INVALID';end if;
      v_binding.stage:='CASE';
    end if;
  elsif v_binding.stage='CASE' then
    for v_hold in select * from private.bpay_next_case_hold where run_worker_id=v_worker.id and status='ACTIVE'
      and (v_binding.case_hold_cursor is null or id>v_binding.case_hold_cursor) order by id limit p_limit loop
      select * into strict v_instruction from private.bpay_next_run_case_instruction where id=v_hold.instruction_id;
      select * into strict v_result from private.bpay_next_case_allocation_result where id=v_hold.allocation_result_id;
      select * into strict v_case from private.bpay_next_finance_case where id=v_hold.case_id for update;
      select * into strict v_component from private.bpay_next_case_component where id=v_hold.case_component_id for update;
      select * into strict v_period from private.bpay_next_case_period where case_component_id=v_hold.case_component_id and pay_week_start=v_hold.pay_week_start for update;
      perform 1 from private.bpay_next_case_hold where id=v_hold.id for update;
      select * into strict v_use from private.bpay_next_case_capacity_use where case_hold_id=v_hold.id for update;
      if v_instruction.run_worker_id<>v_worker.id or v_instruction.preparation_revision<>v_binding.preparation_revision
         or v_instruction.selection_revision<>v_binding.selection_revision or v_result.instruction_id<>v_instruction.id
         or v_result.state_id is distinct from (case when v_worker.target_pay_channel='PAYE'
           and v_instruction.payroll_stage='NET_DEDUCT' and v_binding.accepted_projection_revision>0
           then v_binding.net_state_id else v_binding.draft_state_id end)
         or v_hold.allocation_pass_kind<>v_result.pass_kind or v_use.status<>'ACTIVE' or v_use.realisation_event_id is not null
         or v_use.source_amount_ex_vat<>v_hold.source_reserved_ex_vat
         or (v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat)
           is distinct from (v_result.allocated_source_ex_vat,v_result.allocated_target_ex_vat,v_result.allocated_target_vat,v_result.allocated_target_inc_vat) then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_HOLD_BINDING_INVALID';end if;
      v_amount:=v_hold.source_reserved_ex_vat;
      if v_hold.purpose='PAYOUT' then
        update private.bpay_next_case_component set active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,
          component_revision=component_revision+1,updated_at_utc=v_now where id=v_component.id and active_payout_source_ex_vat>=v_amount;
        if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_COMPONENT_CAPACITY_INVALID';end if;
        update private.bpay_next_finance_case set active_payout_hold_amount=active_payout_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
          case_revision=case_revision+1,updated_at_utc=v_now where id=v_case.id and active_payout_hold_amount>=v_amount and active_hold_amount>=v_amount;
      else
        update private.bpay_next_case_component set active_recovery_source_ex_vat=active_recovery_source_ex_vat-v_amount,
          component_revision=component_revision+1,updated_at_utc=v_now where id=v_component.id and active_recovery_source_ex_vat>=v_amount;
        if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_COMPONENT_CAPACITY_INVALID';end if;
        update private.bpay_next_finance_case set active_recovery_hold_amount=active_recovery_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
          case_revision=case_revision+1,updated_at_utc=v_now where id=v_case.id and active_recovery_hold_amount>=v_amount and active_hold_amount>=v_amount;
      end if;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_CASE_CAPACITY_INVALID';end if;
      if v_hold.purpose='PAYOUT' then
        update private.bpay_next_case_period set active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,period_revision=period_revision+1
          where case_component_id=v_component.id and pay_week_start=v_hold.pay_week_start and active_payout_source_ex_vat>=v_amount;
      else
        update private.bpay_next_case_period set active_unrealised_recovery_source_ex_vat=active_unrealised_recovery_source_ex_vat-v_amount,period_revision=period_revision+1
          where case_component_id=v_component.id and pay_week_start=v_hold.pay_week_start and active_unrealised_recovery_source_ex_vat>=v_amount;
      end if;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_PERIOD_CAPACITY_INVALID';end if;
      update private.bpay_next_case_hold set status='RELEASED',finished_at_utc=v_now where id=v_hold.id;
      update private.bpay_next_case_capacity_use set status='RELEASED' where case_hold_id=v_hold.id;
      update private.bpay_next_run_worker set active_case_hold_count=active_case_hold_count-1 where id=v_worker.id and active_case_hold_count>0;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_WORKER_HOLD_COUNT_INVALID';end if;
      if v_instruction.work_collection_id is not null then
        perform private.bpay_next_reconcile_cancelled_work_collection_v1(p_job_id,v_hold.id);
      end if;
      v_binding.case_hold_cursor:=v_hold.id;v_binding.released_case_hold_count:=v_binding.released_case_hold_count+1;v_seen:=v_seen+1;v_holds:=v_holds+1;
    end loop;
    select exists(select 1 from private.bpay_next_case_hold where run_worker_id=v_worker.id and status='ACTIVE') into v_more;
    if not v_more then
      if v_binding.released_case_hold_count<>v_binding.expected_case_hold_count
         or (select active_case_hold_count from private.bpay_next_run_worker where id=v_worker.id)<>0 then
        raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_CASE_COUNT_INVALID';end if;
      v_binding.stage:='FINAL';
    elsif v_seen=0 then raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_CASE_CURSOR_INVALID';end if;
  elsif v_binding.stage='FINAL' then
    if v_binding.released_work_count<>v_binding.expected_work_count or v_binding.released_case_hold_count<>v_binding.expected_case_hold_count
       or v_worker.active_case_hold_count<>0 or exists(select 1 from private.bpay_next_case_hold where run_worker_id=v_worker.id and status='ACTIVE')
       or v_run.cancelled_candidate_count>=v_run.selected_candidate_count then
      raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_FINAL_COUNT_INVALID';end if;
    if v_group.anchor_transfer_id is not null then
      v_group_page:=private.bpay_next_finish_destination_cancel_page_v1(p_job_id,p_limit);
      v_seen:=(v_group_page->>'rows_visited')::integer;
    end if;
    if v_group.anchor_transfer_id is null or (v_group_page->>'complete')::boolean is true then
      if v_binding.projection_id is not null then update private.bpay_next_net_projection set retired_at_utc=v_now where id=v_binding.projection_id and retired_at_utc is null;end if;
      update private.bpay_next_run_worker set status='CANCELLED' where id=v_worker.id;
      update private.bpay_next_pay_run set cancelled_candidate_count=cancelled_candidate_count+1,
        status=case when cancelled_candidate_count+1=selected_candidate_count then 'CANCELLED' else status end where id=v_run.id;
      v_binding.status:='CANCELLED';v_binding.stage:='COMPLETE';v_binding.finished_at_utc:=v_now;
      if v_group.anchor_transfer_id is null then v_seen:=1;end if;
    end if;
  else raise exception using errcode='23514',message='BPAY_NEXT_CASE_CANCEL_STAGE_INVALID';end if;
  update private.bpay_next_case_cancel_binding set status=v_binding.status,stage=v_binding.stage,checkpoint=checkpoint+1,
    released_work_count=v_binding.released_work_count,work_cursor=v_binding.work_cursor,expected_case_hold_count=v_binding.expected_case_hold_count,
    released_case_hold_count=v_binding.released_case_hold_count,case_hold_cursor=v_binding.case_hold_cursor,
    accepted_projection_revision=v_binding.accepted_projection_revision,projection_id=v_binding.projection_id,net_state_id=v_binding.net_state_id,
    umbrella_draft_state_id=v_binding.umbrella_draft_state_id,
    transfer_id=v_binding.transfer_id,started_at_utc=v_binding.started_at_utc,finished_at_utc=v_binding.finished_at_utc
    where command_id=v_job.command_id returning checkpoint into v_checkpoint;
  update private.bpay_next_cancel_request set status=v_binding.status,cursor_line_no=v_checkpoint,released_line_count=v_binding.released_work_count,
    finished_at_utc=v_binding.finished_at_utc where command_id=v_job.command_id;
  update private.bpay_next_job set cursor_key=v_checkpoint::text,applied_line_count=v_binding.released_work_count,
    lease_until_utc=pg_catalog.clock_timestamp()+pg_catalog.make_interval(secs=>120) where id=p_job_id;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1,updated_at_utc=v_now where candidate_id=v_candidate;
  if v_binding.status='CANCELLED' then
    perform private.bpay_next_apply_cancelled_week_v1(p_job_id);
    update private.bpay_next_job set status='DONE',phase='CANCELLED',lease_nonce=null,lease_until_utc=null where id=p_job_id;
    update private.bpay_next_command set status='COMPLETE' where id=v_job.command_id;
  end if;
  return pg_catalog.jsonb_build_object('phase',v_binding.status,'run_worker_id',v_worker.id,'cursor',v_checkpoint,
    'released_line_count',v_binding.released_work_count,'rows_visited',v_seen,'holds_released',v_holds,'replay',false);
end
$function$;
alter function private.bpay_next_case_cancel_block_v1(uuid,boolean) OWNER TO CURRENT_USER;
alter function private.bpay_next_accept_case_cancel_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_case_cancel_binding_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_cancel_case_worker_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_case_cancel_block_v1(uuid,boolean),private.bpay_next_accept_case_cancel_v1(uuid,uuid),
  private.bpay_next_case_cancel_binding_guard_v1(),private.bpay_next_cancel_case_worker_page_v1(uuid,uuid,bigint,bigint,integer)
  from public,anon,authenticated,service_role;


-- Genuine zero-cash accounting: an owned internal receipt, not a CSV or bank
-- outcome. Actual frozen member posting is the existing bounded0200 owner.
-- No history, provider, payroll reprice, principal inverse or cash-return row.



create or replace function private.bpay_next_internal_receipt_guard_v1()
returns trigger language plpgsql security invoker set search_path=pg_catalog,private,public
as $function$
declare
  v_transfer private.bpay_next_transfer%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_projection private.bpay_next_net_projection%rowtype;v_command private.bpay_next_command%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
begin
  if tg_op<>'INSERT' then raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_RECEIPT_IMMUTABLE';end if;
  select * into strict v_transfer from private.bpay_next_transfer where id=new.transfer_id;
  select * into strict v_worker from private.bpay_next_run_worker where id=new.run_worker_id;
  select * into strict v_projection from private.bpay_next_net_projection where id=new.projection_id;
  select * into strict v_command from private.bpay_next_command where id=new.command_id;
  v_leg:=private.bpay_next_destination_execution_leg_v1(new.transfer_id);
  if v_transfer.execution_kind<>'INTERNAL_ZERO' or v_transfer.status<>'MEMBERS_READY'
     or v_transfer.cash_amount<>0 or v_transfer.member_cash_sum<>0 or v_transfer.member_count<1
     or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
     or v_transfer.run_worker_id<>v_worker.id or v_transfer.candidate_id<>v_worker.candidate_id
     or v_transfer.projection_id<>v_projection.id or v_projection.run_worker_id<>v_worker.id
     or new.candidate_id<>v_worker.candidate_id
     or (v_projection.cash_amount<>0 and (v_leg.transfer_id is null or v_leg.leg_kind<>'OWN'))
     or v_projection.retired_at_utc is not null or v_worker.status<>'READY' or (v_worker.target_pay_channel<>'PAYE'
       and not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection))
     or v_worker.net_projection_revision<>v_projection.projection_no or (v_worker.target_pay_channel='PAYE' and v_worker.net_request_revision<>v_projection.projection_no)
     or v_command.command_kind<>'INTERNAL_SETTLEMENT' or v_command.status<>'RECEIVED'
     or v_command.module_epoch is distinct from (select owner_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT')
     or new.occurred_at_utc<>pg_catalog.transaction_timestamp() or new.received_at_utc<>pg_catalog.transaction_timestamp()
     or not exists(select 1 from public.tms_users u where u.id=new.actor_user_id and u.is_active is true
       and u.role::text='admin' and (u.payment_authoriser is true or u.payment_golden_key is true))
     or not exists(select 1 from private.bpay_next_pay_run r where r.id=v_worker.run_id and r.status='DRAFT' and r.confirmed_at_utc is not null)
     or not exists(select 1 from private.bpay_next_job j where j.command_id=v_transfer.build_command_id
       and j.candidate_id=v_worker.candidate_id and j.job_kind='TRANSFER_BUILD' and j.status='DONE' and j.phase='MEMBERS_READY')
     or exists(select 1 from private.bpay_next_csv_instruction where transfer_id=v_transfer.id)
     or exists(select 1 from private.bpay_next_transfer_outcome where transfer_id=v_transfer.id)
     or exists(select 1 from private.bpay_next_cancel_request where run_worker_id=v_worker.id and status in ('REQUESTED','CANCELLING')) then
    raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_RECEIPT_BINDING_INVALID';end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_internal_receipt_guard_v1 on private.bpay_next_internal_receipt;
create trigger bpay_next_internal_receipt_guard_v1 before insert or update or delete on private.bpay_next_internal_receipt
  for each row execute function private.bpay_next_internal_receipt_guard_v1();

create or replace function private.bpay_next_internal_request_guard_v1()
returns trigger language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_receipt private.bpay_next_internal_receipt%rowtype;v_transfer private.bpay_next_transfer%rowtype;
begin
  if tg_op='DELETE' then
    if old.internal_receipt_id is not null then raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_REQUEST_IMMUTABLE';end if;
    return old;
  end if;
  if tg_op='UPDATE' and (old.internal_receipt_id is not null or new.internal_receipt_id is not null) then
    if (pg_catalog.to_jsonb(new)-array['posted_member_count','posting_complete'])
       is distinct from (pg_catalog.to_jsonb(old)-array['posted_member_count','posting_complete'])
       or old.posting_complete or new.posted_member_count<=old.posted_member_count then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_REQUEST_PROGRESS_INVALID';end if;
  end if;
  if new.internal_receipt_id is null then return new;end if;
  select * into strict v_receipt from private.bpay_next_internal_receipt where id=new.internal_receipt_id;
  select * into strict v_transfer from private.bpay_next_transfer where id=new.transfer_id;
  if new.outcome_id is not null or (new.command_id,new.transfer_id,new.run_worker_id,new.candidate_id,new.actor_user_id)
       is distinct from (v_receipt.command_id,v_receipt.transfer_id,v_receipt.run_worker_id,v_receipt.candidate_id,v_receipt.actor_user_id)
     or new.posted_member_count>v_transfer.member_count or new.posting_complete<>(new.posted_member_count=v_transfer.member_count)
     or (tg_op='INSERT' and (new.posted_member_count<>0 or new.posting_complete or v_transfer.status<>'MEMBERS_READY'))
     or (tg_op='UPDATE' and v_transfer.status<>'INTERNAL_PROCESSING') then
    raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_REQUEST_BINDING_INVALID';end if;
  if tg_op='UPDATE' and not exists(select 1 from private.bpay_next_job j
       join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id
       where j.command_id=new.command_id and j.candidate_id=new.candidate_id and j.job_kind='INTERNAL_SETTLEMENT'
         and j.status='LEASED' and j.phase='MEMBERS' and j.lease_nonce is not null
         and j.lease_until_utc>pg_catalog.clock_timestamp() and j.owner_epoch=c.active_owner_epoch) then
    raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_REQUEST_OWNER_INVALID';end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_internal_request_guard_v1 on private.bpay_next_outcome_request;
create trigger bpay_next_internal_request_guard_v1 before insert or update or delete on private.bpay_next_outcome_request
  for each row execute function private.bpay_next_internal_request_guard_v1();

create or replace function private.bpay_next_receive_internal_settlement_v1(
  p_command_id uuid,p_transfer_id uuid,p_actor_user_id uuid
) returns jsonb language plpgsql security invoker set search_path=pg_catalog,private,public
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_sequence bigint;
  v_run private.bpay_next_pay_run%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;v_projection private.bpay_next_net_projection%rowtype;
  v_receipt private.bpay_next_internal_receipt%rowtype;v_request private.bpay_next_outcome_request%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
begin
  if p_command_id is null or p_transfer_id is null or p_actor_user_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_INTERNAL_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bpay-next-internal:'||p_command_id::text,0));
  select w.run_id,w.candidate_id into strict v_run_id,v_candidate from private.bpay_next_transfer t
    join private.bpay_next_run_worker w on w.id=t.run_worker_id where t.id=p_transfer_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select w.* into strict v_worker from private.bpay_next_run_worker w join private.bpay_next_transfer t on t.run_worker_id=w.id
    where t.id=p_transfer_id for update of w;
  select * into strict v_transfer from private.bpay_next_transfer where id=p_transfer_id for update;
  if not exists(select 1 from public.tms_users u where u.id=p_actor_user_id and u.is_active is true and u.role::text='admin'
      and (u.payment_authoriser is true or u.payment_golden_key is true) for share) then
    raise exception using errcode='42501',message='BPAY_NEXT_INTERNAL_ACTOR_NOT_AUTHORISED';end if;
  select * into v_receipt from private.bpay_next_internal_receipt where command_id=p_command_id;
  if found then
    if v_receipt.transfer_id<>p_transfer_id or v_receipt.run_worker_id<>v_worker.id
       or v_receipt.candidate_id<>v_candidate or v_receipt.actor_user_id<>p_actor_user_id then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_RECEIPT_REPLAY_CONFLICT';end if;
    select * into strict v_request from private.bpay_next_outcome_request where command_id=p_command_id and internal_receipt_id=v_receipt.id;
    select agency_sequence into strict v_sequence from private.bpay_next_command where id=p_command_id
      and command_kind='INTERNAL_SETTLEMENT' and module_epoch=v_epoch;
    return pg_catalog.jsonb_build_object('command_id',p_command_id,'transfer_id',p_transfer_id,
      'internal_receipt_id',v_receipt.id,'sequence',v_sequence::text,'phase',case when v_request.posting_complete then 'POSTED' else 'ACCEPTED_PENDING_POSTING' end,
      'posting_complete',v_request.posting_complete,'replay',true);
  end if;
  if exists(select 1 from private.bpay_next_internal_receipt where transfer_id=p_transfer_id)
     or exists(select 1 from private.bpay_next_outcome_request where command_id=p_command_id or transfer_id=p_transfer_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_RECEIPT_CONFLICT';end if;
  select * into strict v_projection from private.bpay_next_net_projection where id=v_transfer.projection_id;
  v_leg:=private.bpay_next_destination_execution_leg_v1(p_transfer_id);
  if v_run.status<>'DRAFT' or v_run.confirmed_at_utc is null or v_worker.status<>'READY' or (v_worker.target_pay_channel<>'PAYE'
       and not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection))
     or v_transfer.execution_kind<>'INTERNAL_ZERO' or v_transfer.status<>'MEMBERS_READY' or v_transfer.cash_amount<>0
     or v_transfer.member_count<1 or v_transfer.member_cash_sum<>0 or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
     or (v_projection.cash_amount<>0 and (v_leg.transfer_id is null or v_leg.leg_kind<>'OWN'))
     or v_projection.run_worker_id<>v_worker.id or v_projection.retired_at_utc is not null
     or (v_worker.target_pay_channel='PAYE' and v_worker.net_request_revision<>v_projection.projection_no) or v_worker.net_projection_revision<>v_projection.projection_no
     or exists(select 1 from private.bpay_next_cancel_request where run_worker_id=v_worker.id and status in ('REQUESTED','CANCELLING'))
     or exists(select 1 from private.bpay_next_csv_instruction where transfer_id=p_transfer_id)
     or exists(select 1 from private.bpay_next_transfer_outcome where transfer_id=p_transfer_id) then
    raise exception using errcode='55000',message='BPAY_NEXT_INTERNAL_NOT_ELIGIBLE';end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'INTERNAL_SETTLEMENT');
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no) values(p_command_id,v_candidate,1);
  insert into private.bpay_next_internal_receipt(command_id,transfer_id,run_worker_id,candidate_id,projection_id,actor_user_id)
    values(p_command_id,p_transfer_id,v_worker.id,v_candidate,v_projection.id,p_actor_user_id) returning * into v_receipt;
  insert into private.bpay_next_outcome_request(command_id,internal_receipt_id,transfer_id,run_worker_id,candidate_id,actor_user_id)
    values(p_command_id,v_receipt.id,p_transfer_id,v_worker.id,v_candidate,p_actor_user_id);
  update private.bpay_next_transfer set status='INTERNAL_PROCESSING' where id=p_transfer_id;
  update private.bpay_next_command set expected_member_count=1,status='SEALED',sealed_at_utc=pg_catalog.transaction_timestamp() where id=p_command_id;
  return pg_catalog.jsonb_build_object('command_id',p_command_id,'transfer_id',p_transfer_id,
    'internal_receipt_id',v_receipt.id,'sequence',v_sequence::text,'phase','ACCEPTED_PENDING_POSTING','posting_complete',false,'replay',false);
end
$function$;

--0200 calls after its final real member and request progress update, in the
-- same transaction. It is not an alternative unbounded posting owner.
create or replace function private.bpay_next_complete_internal_zero_v1(p_job_id uuid,p_final_cursor bigint)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare
  v_epoch bigint;v_run_id uuid;v_candidate uuid;v_last_member bigint;
  v_job private.bpay_next_job%rowtype;v_control private.bpay_next_worker_control%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_run private.bpay_next_pay_run%rowtype;
  v_transfer private.bpay_next_transfer%rowtype;v_request private.bpay_next_outcome_request%rowtype;
  v_receipt private.bpay_next_internal_receipt%rowtype;v_projection private.bpay_next_net_projection%rowtype;
  v_week private.bpay_next_worker_week%rowtype;v_prior private.bpay_next_worker_week_contribution%rowtype;
  v_leg private.bpay_next_destination_group_leg%rowtype;
begin
  if p_job_id is null or p_final_cursor is null or p_final_cursor<1 then
    raise exception using errcode='22023',message='BPAY_NEXT_INTERNAL_COMPLETE_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select w.run_id,r.candidate_id into strict v_run_id,v_candidate from private.bpay_next_job j
    join private.bpay_next_outcome_request r on r.command_id=j.command_id
    join private.bpay_next_run_worker w on w.id=r.run_worker_id where j.id=p_job_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  select * into strict v_control from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_request from private.bpay_next_outcome_request where command_id=v_job.command_id for update;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_request.run_worker_id for update;
  select * into strict v_transfer from private.bpay_next_transfer where id=v_request.transfer_id for update;
  select * into strict v_receipt from private.bpay_next_internal_receipt where id=v_request.internal_receipt_id;
  select * into strict v_projection from private.bpay_next_net_projection where id=v_receipt.projection_id;
  v_leg:=private.bpay_next_destination_execution_leg_v1(v_transfer.id);
  select member_no into strict v_last_member from private.bpay_next_transfer_member where transfer_id=v_transfer.id order by member_no desc limit 1;
  if v_job.job_kind<>'INTERNAL_SETTLEMENT' or v_job.module_epoch<>v_epoch or v_job.candidate_id<>v_candidate
     or v_receipt.command_id<>v_job.command_id or v_receipt.transfer_id<>v_transfer.id
     or v_receipt.run_worker_id<>v_worker.id or v_receipt.candidate_id<>v_candidate or v_request.outcome_id is not null
     or v_transfer.execution_kind<>'INTERNAL_ZERO' or v_transfer.cash_amount<>0 or v_transfer.member_cash_sum<>0
     or v_transfer.original_transfer_id is not null or v_transfer.return_cash_id is not null
     or v_transfer.projection_id<>v_projection.id or v_projection.run_worker_id<>v_worker.id
     or (v_projection.cash_amount<>0 and (v_leg.transfer_id is null or v_leg.leg_kind<>'OWN'))
     or v_request.posting_complete is not true or v_request.posted_member_count<>v_transfer.member_count
     or v_last_member<>p_final_cursor or v_last_member<>v_transfer.member_count then
    raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_COMPLETE_SCOPE_INVALID';end if;
  if v_job.status='DONE' then
    if v_job.phase<>'COMPLETE' or v_transfer.status<>'INTERNAL_SETTLED'
       or (v_leg.transfer_id is null and v_worker.status<>'COMPLETE')
       or (v_leg.transfer_id is not null and v_worker.status not in ('READY','COMPLETE')) then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_COMPLETE_REPLAY_INVALID';end if;
    return;
  end if;
  if v_job.status<>'LEASED' or v_job.phase<>'MEMBERS' or v_job.lease_nonce is null
     or v_job.owner_epoch<>v_control.active_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or v_transfer.status<>'INTERNAL_PROCESSING' or v_worker.status<>'READY' or (v_worker.target_pay_channel<>'PAYE'
       and not private.bpay_next_umbrella_case_projection_valid_v2(v_worker,v_projection))
     or v_projection.retired_at_utc is not null or (v_worker.target_pay_channel='PAYE' and v_worker.net_request_revision<>v_projection.projection_no)
     or v_worker.net_projection_revision<>v_projection.projection_no
     or (v_leg.transfer_id is null and v_worker.active_case_hold_count<>0)
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_INTERNAL_COMPLETE_OWNER_INVALID';end if;
  select * into v_week from private.bpay_next_worker_week where candidate_id=v_candidate
    and pay_week_start=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1) for update;
  select * into v_prior from private.bpay_next_worker_week_contribution where original_run_worker_id=v_worker.id for update;
  if v_prior.id is null then
    if v_worker.case_selection_revision<>0 then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_CASE_WEEK_MISSING';end if;
    -- A missing genuine no-case floor remains explicitly unbound; no backfill.
    raise notice 'BPAY_NEXT_INTERNAL_WEEK_CONTRIBUTION_UNBOUND';
  else
    if v_week.candidate_id is null or v_prior.candidate_id<>v_candidate or v_prior.pay_week_start<>v_week.pay_week_start
       or v_prior.original_pay_date<>v_run.pay_date or v_prior.original_created_at_utc<>v_run.created_at_utc
       or v_prior.original_gross_amount<>(case when v_projection.umbrella_case_draft_state_id is not null
         then v_projection.gross_ex_vat else v_projection.gross_inc_vat end)
       or v_prior.original_payroll_net is distinct from v_projection.entered_paye_net
       or v_prior.accepted_projection_id is distinct from v_projection.id
       or v_prior.accepted_bank_cash is distinct from v_projection.cash_amount
       or v_prior.payment_state<>'ARRANGED' or v_prior.eligibility_state='UNBOUND'
       or v_prior.original_transfer_id is not null or v_prior.returned_cash_id is not null or v_prior.reissue_transfer_id is not null
       or (v_projection.input_kind='CASE_PAYOUT' and (v_prior.basis_kind<>'GROSS_FALLBACK'
         or v_prior.original_gross_amount<>0 or v_prior.original_payroll_net is not null
         or v_prior.eligibility_state<>'EXCLUDED' or v_prior.eligible_arranged_amount is distinct from 0::numeric))
       or (v_projection.umbrella_case_draft_state_id is not null and (v_prior.basis_kind<>'GROSS_FALLBACK'
         or v_prior.original_payroll_net is not null or v_prior.eligible_arranged_amount is distinct from 0::numeric))
       or (v_projection.input_kind<>'CASE_PAYOUT' and v_projection.umbrella_case_draft_state_id is null
         and (v_prior.basis_kind<>'PAYROLL_NET' or v_prior.eligibility_state not in ('ELIGIBLE','EXCLUDED')
           or v_prior.eligible_arranged_amount is distinct from 0::numeric)) then
      raise exception using errcode='23514',message='BPAY_NEXT_INTERNAL_WEEK_NOT_EXACT';end if;
    update private.bpay_next_worker_week_contribution set payment_state='PAID',original_transfer_id=v_transfer.id,
      contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
    -- Its accepted zero cash was already included. Do not add payroll net or
    -- zero a shared weekly aggregate while another Candidate arrangement exists.
    update private.bpay_next_worker_week set period_revision=period_revision+1
      where candidate_id=v_candidate and pay_week_start=v_week.pay_week_start;
  end if;
  update private.bpay_next_transfer set status='INTERNAL_SETTLED' where id=v_transfer.id;
  -- Split OWN zero finishes only this leg. The original-leg counter in0200
  -- completes the worker after external CASE holds have actually posted.
  if v_leg.transfer_id is null then update private.bpay_next_run_worker set status='COMPLETE' where id=v_worker.id;end if;
end
$function$;

alter function private.bpay_next_internal_receipt_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_internal_request_guard_v1() OWNER TO CURRENT_USER;
alter function private.bpay_next_receive_internal_settlement_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_complete_internal_zero_v1(uuid,bigint) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_internal_receipt_guard_v1(),private.bpay_next_internal_request_guard_v1(),
  private.bpay_next_receive_internal_settlement_v1(uuid,uuid,uuid),private.bpay_next_complete_internal_zero_v1(uuid,bigint)
  from public,anon,authenticated,service_role;


-- Actual pre-confirmation expiry, with fenced metadata enrollment and ordered
-- bounded WORK/CASE release. No Draft/payment/CSV/provider/internal expiry.



create or replace function private.bpay_next_preparation_expiry_fenced_v1(p_run_id uuid,p_prepare_command_id uuid)
returns boolean language sql stable security invoker set search_path=pg_catalog,private
as $function$
  select exists(select 1 from private.bpay_next_pay_run r
    join private.bpay_next_preparation_expiry_request x on x.run_id=r.id
    where r.id=p_run_id and r.status in ('CANCELLING','CANCELLED') and r.confirmed_at_utc is null
      and x.status in ('CANCELLING','EXPIRED') and x.original_prepare_command_id=p_prepare_command_id
      and x.captured_deadline=r.preparation_expires_at_utc
      and x.selection_count=r.selection_count and x.selection_page_count=r.selection_page_count
      and x.expected_candidate_count=r.selected_candidate_count
      and r.review_revision=x.selection_review_revision+1
      and (r.status='CANCELLING' or (x.status='EXPIRED' and x.completed_candidate_count=x.expected_candidate_count
        and x.enrolled_candidate_count=x.expected_candidate_count)))
$function$;

create or replace function private.bpay_next_accept_preparation_expiry_v1(
  p_command_id uuid,p_run_id uuid,p_actor_user_id uuid,p_expected_deadline timestamptz,
  p_observed_now timestamptz default null)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private,public
as $function$
declare v_epoch bigint;v_run private.bpay_next_pay_run%rowtype;
  v_request private.bpay_next_preparation_expiry_request%rowtype;v_sequence bigint;v_prepare uuid;v_now timestamptz;
begin
  if p_command_id is null or p_run_id is null or p_expected_deadline is null
     or not pg_catalog.isfinite(p_expected_deadline)
     or (p_observed_now is not null and not pg_catalog.isfinite(p_observed_now)) then
    raise exception using errcode='22023',message='BPAY_NEXT_EXPIRY_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bpay-next-preparation-expiry:'||p_command_id::text,0));
  select * into strict v_run from private.bpay_next_pay_run where id=p_run_id for update;
  select * into v_request from private.bpay_next_preparation_expiry_request where command_id=p_command_id;
  if found then
    if v_request.run_id<>p_run_id or v_request.actor_user_id is distinct from p_actor_user_id
       or v_request.captured_deadline<>p_expected_deadline
       or not exists(select 1 from private.bpay_next_command where id=p_command_id
         and command_kind='PREPARATION_EXPIRY' and module_epoch=v_epoch) then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_REPLAY_CONFLICT';end if;
    select agency_sequence into strict v_sequence from private.bpay_next_command where id=p_command_id;
    return pg_catalog.jsonb_build_object('command_id',p_command_id,'run_id',p_run_id,'sequence',v_sequence::text,
      'phase',v_request.status,'expected_candidates',v_request.expected_candidate_count::text,
      'completed_candidates',v_request.completed_candidate_count::text,'replay',true);
  end if;
  -- Public wrappers MUST pass NULL, never a browser/request-supplied clock.
  -- Obtain real time after waiting for this same header as confirmation.
  -- The private ungranted operand permits labelled native 72h clock vectors.
  v_now:=coalesce(p_observed_now,pg_catalog.clock_timestamp());
  if p_actor_user_id is not null and not exists(select 1 from public.tms_users
      where id=p_actor_user_id and is_active is true and role::text='admin' for share) then
    raise exception using errcode='42501',message='BPAY_NEXT_EXPIRY_ACTOR_FORBIDDEN';end if;
  if v_run.confirmed_at_utc is not null or v_run.status not in ('PREPARING','REVIEW') then
    raise exception using errcode='55000',message='BPAY_NEXT_EXPIRY_NOT_UNCONFIRMED';end if;
  if v_run.preparation_expires_at_utc is null then
    raise exception using errcode='55000',message='BPAY_NEXT_EXPIRY_DEADLINE_UNBOUND';end if;
  if v_run.preparation_expires_at_utc<>p_expected_deadline then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_DEADLINE_CONFLICT';end if;
  if v_now<v_run.preparation_expires_at_utc then
    raise exception using errcode='55000',message='BPAY_NEXT_EXPIRY_NOT_DUE';end if;
  if exists(select 1 from private.bpay_next_preparation_expiry_request where run_id=p_run_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_RUN_ALREADY_BOUND';end if;
  select command_id into v_prepare from private.bpay_next_run_command where run_id=p_run_id;
  if v_prepare is not null and not exists(select 1 from private.bpay_next_command
      where id=v_prepare and command_kind='PREPARE' and module_epoch=v_epoch
        and status in ('ENROLLING','SEALED') and expected_member_count=v_run.selected_candidate_count) then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_PREPARE_BINDING_INVALID';end if;
  v_sequence:=private.bpay_next_receive_command_v1(p_command_id,'PREPARATION_EXPIRY');
  insert into private.bpay_next_preparation_expiry_request(command_id,run_id,original_prepare_command_id,
    captured_deadline,selection_count,selection_page_count,selection_review_revision,expected_candidate_count,
    initiator_kind,actor_user_id,accepted_at_utc,status,finished_at_utc)
    values(p_command_id,p_run_id,v_prepare,p_expected_deadline,v_run.selection_count,v_run.selection_page_count,v_run.review_revision,
      v_run.selected_candidate_count,case when p_actor_user_id is null then 'SYSTEM' else 'OFFICE' end,p_actor_user_id,v_now,
      case when v_run.selected_candidate_count=0 then 'EXPIRED' else 'CANCELLING' end,
      case when v_run.selected_candidate_count=0 then v_now else null end);
  update private.bpay_next_pay_run set status=case when selected_candidate_count=0 then 'CANCELLED' else 'CANCELLING' end,
    review_revision=review_revision+1 where id=p_run_id;
  update private.bpay_next_command set expected_member_count=v_run.selected_candidate_count,
    status=case when v_run.selected_candidate_count=0 then 'COMPLETE' else 'ENROLLING' end,
    sealed_at_utc=case when v_run.selected_candidate_count=0 then v_now else null end where id=p_command_id;
  return pg_catalog.jsonb_build_object('command_id',p_command_id,'run_id',p_run_id,'sequence',v_sequence::text,
    'phase',case when v_run.selected_candidate_count=0 then 'EXPIRED' else 'CANCELLING' end,
    'expected_candidates',v_run.selected_candidate_count::text,'completed_candidates','0','replay',false);
end
$function$;

-- Called ONLY by the existing ordered1430 enroller, one Candidate per call.
-- The root fence has already stopped every PREPARE financial writer. Retiring
-- an unfinished original job here is metadata, not bypassing another command.
create or replace function private.bpay_next_enroll_preparation_expiry_one_v1(p_command_id uuid)
returns uuid language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_run_id uuid;v_epoch bigint;v_run private.bpay_next_pay_run%rowtype;
  v_request private.bpay_next_preparation_expiry_request%rowtype;v_command private.bpay_next_command%rowtype;
  v_original private.bpay_next_job%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_candidate uuid;v_member bigint;v_job uuid;v_state uuid;
begin
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select run_id into strict v_run_id from private.bpay_next_preparation_expiry_request where command_id=p_command_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for share;
  select * into strict v_request from private.bpay_next_preparation_expiry_request where command_id=p_command_id for update;
  select * into strict v_command from private.bpay_next_command where id=p_command_id for update;
  if v_command.command_kind<>'PREPARATION_EXPIRY' or v_command.module_epoch<>v_epoch
     or v_command.expected_member_count<>v_request.expected_candidate_count
     or v_command.enrolled_member_count<>v_request.enrolled_candidate_count
     or v_run.confirmed_at_utc is not null or v_run.preparation_expires_at_utc<>v_request.captured_deadline
     or v_run.selection_count<>v_request.selection_count or v_run.selection_page_count<>v_request.selection_page_count
     or v_run.selected_candidate_count<>v_request.expected_candidate_count
     or v_run.review_revision<>v_request.selection_review_revision+1 then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_ENROLLMENT_SCOPE_INVALID';end if;
  if v_request.expected_candidate_count=0 then
    if v_run.status<>'CANCELLED' or v_request.status<>'EXPIRED' or v_command.status<>'COMPLETE' then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_EMPTY_NOT_COMPLETE';end if;
    return null;
  end if;
  if v_run.status<>'CANCELLING' or v_request.status<>'CANCELLING' or v_command.status<>'ENROLLING'
     or v_request.enrolled_candidate_count>=v_request.expected_candidate_count then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_NOT_ENROLLABLE';end if;
  v_member:=v_request.enrolled_candidate_count+1;
  select candidate_id into strict v_candidate from private.bpay_next_selection_candidate where run_id=v_run_id and member_no=v_member;
  if v_request.original_prepare_command_id is not null then
    select * into strict v_original from private.bpay_next_job where command_id=v_request.original_prepare_command_id
      and candidate_id=v_candidate and job_kind='PREPARE' for update;
    if v_original.module_epoch<>v_epoch then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_ORIGINAL_JOB_INVALID';end if;
    if v_original.status<>'DONE' then
      update private.bpay_next_job set status='DONE',phase='EXPIRED',lease_nonce=null,lease_until_utc=null,
        last_error_code='BPAY_NEXT_PREPARATION_EXPIRED' where id=v_original.id;
    end if;
  end if;
  select * into v_worker from private.bpay_next_run_worker where run_id=v_run_id and candidate_id=v_candidate;
  if v_worker.id is not null then
    if v_original.id is null or v_worker.status not in ('PREPARING','REVIEW','READY') then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WORKER_NOT_PREPARATION';end if;
    select id into v_state from private.bpay_next_case_allocation_state where run_worker_id=v_worker.id
      and preparation_revision=v_worker.preparation_revision and selection_revision=v_worker.case_selection_revision
      and pass_kind='DRAFT' and projection_no=0;
  end if;
  insert into private.bpay_next_command_member(command_id,candidate_id,member_no) values(p_command_id,v_candidate,v_member);
  insert into private.bpay_next_job(command_id,command_sequence,module_epoch,candidate_id,job_kind,status,phase,owner_epoch)
    values(p_command_id,v_command.agency_sequence,v_epoch,v_candidate,'PREPARATION_EXPIRY','READY','NEW',1) returning id into v_job;
  insert into private.bpay_next_preparation_expiry_worker(command_id,candidate_id,run_id,member_no,job_id,run_worker_id,
    original_job_id,original_job_status,original_job_phase,original_job_cursor,original_position_work_cursor,
    original_position_component_cursor,original_applied_line_count,original_worker_status,original_review_issue_code,
    original_review_issue_work_id,preparation_revision,selection_revision,draft_state_id,expected_work_count,expected_case_hold_count,status,stage)
    values(p_command_id,v_candidate,v_run_id,v_member,v_job,v_worker.id,v_original.id,v_original.status,v_original.phase,v_original.cursor_key,
      v_original.position_work_cursor,v_original.position_component_cursor,v_original.applied_line_count,v_worker.status,
      v_worker.review_issue_code,v_worker.review_issue_work_id,v_worker.preparation_revision,v_worker.case_selection_revision,v_state,
      coalesce(v_worker.captured_line_count,0),coalesce(v_worker.active_case_hold_count,0),'READY','NEW');
  update private.bpay_next_preparation_expiry_request set enrolled_candidate_count=v_member where command_id=p_command_id;
  update private.bpay_next_command set enrolled_member_count=v_member,
    status=case when v_member=expected_member_count then 'SEALED' else 'ENROLLING' end,
    sealed_at_utc=case when v_member=expected_member_count then pg_catalog.clock_timestamp() else null end where id=p_command_id;
  return v_job;
end
$function$;

create or replace function private.bpay_next_claim_preparation_expiry_job_v1(p_job_id uuid,p_lease_seconds integer default 120)
returns table(lease_nonce uuid,owner_epoch bigint) language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_epoch bigint;v_run_id uuid;v_candidate uuid;v_job private.bpay_next_job%rowtype;
  v_run private.bpay_next_pay_run%rowtype;v_nonce uuid;v_owner bigint;
begin
  if p_job_id is null or p_lease_seconds is null or p_lease_seconds not between 1 and 120 then
    raise exception using errcode='22023',message='BPAY_NEXT_EXPIRY_LEASE_INPUT_INVALID';end if;
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select run_id,candidate_id into strict v_run_id,v_candidate from private.bpay_next_preparation_expiry_worker where job_id=p_job_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  insert into private.bpay_next_worker_control(candidate_id) values(v_candidate) on conflict(candidate_id) do nothing;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  if v_run.status<>'CANCELLING' or v_run.confirmed_at_utc is not null or v_job.job_kind<>'PREPARATION_EXPIRY'
     or v_job.module_epoch<>v_epoch or v_job.status not in ('READY','LEASED')
     or (v_job.status='LEASED' and v_job.lease_until_utc>pg_catalog.clock_timestamp()) then
    raise exception using errcode='55000',message='BPAY_NEXT_EXPIRY_JOB_NOT_CLAIMABLE';end if;
  if exists(select 1 from private.bpay_next_job where candidate_id=v_candidate and command_sequence<v_job.command_sequence and status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_EARLIER_WORKER_COMMAND_PENDING';end if;
  update private.bpay_next_worker_control set active_owner_epoch=active_owner_epoch+1,updated_at_utc=pg_catalog.clock_timestamp()
    where candidate_id=v_candidate returning active_owner_epoch into v_owner;
  v_nonce:=pg_catalog.gen_random_uuid();
  update private.bpay_next_job set status='LEASED',owner_epoch=v_owner,lease_nonce=v_nonce,
    lease_until_utc=pg_catalog.clock_timestamp()+pg_catalog.make_interval(secs=>p_lease_seconds),attempt_count=attempt_count+1 where id=p_job_id;
  lease_nonce:=v_nonce;owner_epoch:=v_owner;return next;
end
$function$;

create or replace function private.bpay_next_apply_expired_week_v1(p_job_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_binding private.bpay_next_preparation_expiry_worker%rowtype;v_run private.bpay_next_pay_run%rowtype;
  v_worker private.bpay_next_run_worker%rowtype;v_week private.bpay_next_worker_week%rowtype;
  v_prior private.bpay_next_worker_week_contribution%rowtype;v_old numeric;v_unbound bigint;
begin
  select * into strict v_binding from private.bpay_next_preparation_expiry_worker where job_id=p_job_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_binding.run_id;
  if v_binding.status<>'EXPIRED' or v_binding.stage<>'COMPLETE' or v_run.status<>'CANCELLING' or v_run.confirmed_at_utc is not null
     or not exists(select 1 from private.bpay_next_job j join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id
       where j.id=p_job_id and j.job_kind='PREPARATION_EXPIRY' and j.status='LEASED' and j.phase='RELEASE'
         and j.command_id=v_binding.command_id and j.cursor_key=v_binding.checkpoint::text
         and j.owner_epoch=c.active_owner_epoch and j.lease_until_utc>pg_catalog.clock_timestamp()) then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WEEK_SCOPE_INVALID';end if;
  if v_binding.run_worker_id is null then return;end if;
  select * into strict v_worker from private.bpay_next_run_worker where id=v_binding.run_worker_id;
  if v_worker.status<>'CANCELLED' or v_worker.realised_effect_count<>0 or v_worker.active_case_hold_count<>0
     or v_worker.preparation_revision<>v_binding.preparation_revision or v_worker.case_selection_revision<>v_binding.selection_revision then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WEEK_WORKER_INVALID';end if;
  select * into v_week from private.bpay_next_worker_week where candidate_id=v_binding.candidate_id
    and pay_week_start=v_run.pay_date-(extract(isodow from v_run.pay_date)::integer-1) for update;
  select * into v_prior from private.bpay_next_worker_week_contribution where original_run_worker_id=v_worker.id for update;
  if v_prior.id is null then
    if v_binding.original_worker_status='READY' and v_binding.selection_revision>0 then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_READY_WEEK_FACT_MISSING';end if;
    -- A partial non-READY preparation never published an arrangement. The
    -- genuine no-case READY owner also intentionally preserves absence when
    -- PAYE floor input is unbound, or the target is not PAYE. Preserve that
    -- absence; no zero contribution, live-policy guess or backfill is made.
    return;
  end if;
  if v_week.candidate_id is null or v_prior.candidate_id<>v_binding.candidate_id or v_prior.pay_week_start<>v_week.pay_week_start
     or v_prior.original_pay_date<>v_run.pay_date or v_prior.original_created_at_utc<>v_run.created_at_utc
     or v_prior.original_gross_amount<>(case when v_worker.target_pay_channel='UMBRELLA' and v_worker.case_selection_revision>0
       then v_worker.gross_ex_vat else v_worker.gross_inc_vat end) or v_prior.original_transfer_id is not null
     or exists(select 1 from private.bpay_next_internal_receipt where run_worker_id=v_worker.id)
     or v_prior.returned_cash_id is not null or v_prior.reissue_transfer_id is not null then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WEEK_FACT_NOT_EXACT';end if;
  if v_prior.payment_state='CANCELLED' and v_prior.eligibility_state='EXCLUDED' and v_prior.eligible_arranged_amount=0 then return;end if;
  if v_prior.payment_state<>'ARRANGED' then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WEEK_NOT_UNPAID';end if;
  v_old:=coalesce(v_prior.eligible_arranged_amount,0);v_unbound:=case when v_prior.eligibility_state='UNBOUND' then 1 else 0 end;
  update private.bpay_next_worker_week_contribution set payment_state='CANCELLED',eligibility_state='EXCLUDED',eligible_arranged_amount=0,
    contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=v_prior.id;
  update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home-v_old,
    unresolved_contribution_count=unresolved_contribution_count-v_unbound,period_revision=period_revision+1
    where candidate_id=v_binding.candidate_id and pay_week_start=v_week.pay_week_start
      and resolved_arranged_take_home>=v_old and unresolved_contribution_count>=v_unbound;
  if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WEEK_DELTA_INVALID';end if;
end
$function$;

-- Exact automatic WORK hold-release authority. The nullable third operand is
-- for the collection guard's same typed point path, not a job payload. The
-- caller supplies a real hold PK; the guard resolves it through UNIQUE
-- (run_worker_id,preparation_revision,case_component_id), UNIQUE(state_id,
-- instruction_id), UNIQUE(allocation_result_id), and capacity-use PK.
-- PREPARATION_EXPIRY is neither confirmed-Draft cancellation nor recovery.
create or replace function private.bpay_next_expired_work_collection_scope_v1(
  p_job_id uuid,p_collection_id uuid,p_case_hold_id uuid default null
) returns boolean language sql volatile security invoker set search_path=pg_catalog,private
as $function$
  select exists(select 1 from private.bpay_next_job j
    join private.bpay_next_module_control m on m.id=1 and m.active_owner='NEXT' and m.owner_epoch=j.module_epoch
    join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id and c.active_owner_epoch=j.owner_epoch
    join private.bpay_next_preparation_expiry_worker x on x.job_id=j.id and x.command_id=j.command_id and x.candidate_id=j.candidate_id
    join private.bpay_next_preparation_expiry_request q on q.command_id=x.command_id and q.run_id=x.run_id
    join private.bpay_next_command command on command.id=j.command_id and command.command_kind='PREPARATION_EXPIRY'
      and command.module_epoch=j.module_epoch and command.agency_sequence=j.command_sequence
    join private.bpay_next_job original on original.id=x.original_job_id and original.command_id=q.original_prepare_command_id
      and original.candidate_id=x.candidate_id and original.module_epoch=j.module_epoch and original.job_kind='PREPARE' and original.status='DONE'
    join private.bpay_next_pay_run r on r.id=x.run_id
    join private.bpay_next_run_worker w on w.id=x.run_worker_id and w.run_id=x.run_id and w.candidate_id=x.candidate_id
    join private.bpay_next_work_collection b on b.id=p_collection_id and b.candidate_id=x.candidate_id
    join private.bpay_next_run_case_instruction i on i.run_worker_id=w.id and i.preparation_revision=x.preparation_revision
      and i.case_component_id=b.case_component_id and i.case_id=b.case_id and i.work_collection_id=b.id
      and i.selection_revision=x.selection_revision and i.valuation_policy_id=b.original_valuation_policy_id
    join private.bpay_next_case_allocation_state s on s.id=x.draft_state_id and s.run_worker_id=w.id
      and s.candidate_id=x.candidate_id and s.preparation_revision=x.preparation_revision and s.selection_revision=x.selection_revision
      and s.job_id=x.original_job_id and s.pass_kind='DRAFT' and s.projection_no=0
    join private.bpay_next_case_allocation_result a on a.state_id=s.id and a.instruction_id=i.id and a.pass_kind='DRAFT'
    join private.bpay_next_case_hold h on h.allocation_result_id=a.id and h.instruction_id=i.id
      and h.run_worker_id=w.id and h.case_id=b.case_id and h.case_component_id=b.case_component_id and h.candidate_id=x.candidate_id
    join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id
    where j.id=p_job_id and j.job_kind='PREPARATION_EXPIRY' and j.status='LEASED' and j.phase='RELEASE'
      and j.lease_nonce is not null and j.lease_until_utc>pg_catalog.clock_timestamp()
      and j.cursor_key is not distinct from nullif(x.checkpoint,0)::text
      and x.status='RELEASING' and x.stage='CASE' and x.expected_case_hold_count>0
      and x.released_case_hold_count<x.expected_case_hold_count
      and q.status='CANCELLING' and q.accepted_at_utc>=q.captured_deadline
      and q.captured_deadline=r.preparation_expires_at_utc and r.preparation_expires_at_utc=r.created_at_utc+interval '72 hours'
      and r.status='CANCELLING' and r.confirmed_at_utc is null and r.review_revision=q.selection_review_revision+1
      and (r.selection_count,r.selection_page_count,r.selected_candidate_count)
        is not distinct from (q.selection_count,q.selection_page_count,q.expected_candidate_count)
      and (command.expected_member_count,command.enrolled_member_count)
        is not distinct from (q.expected_candidate_count,q.enrolled_candidate_count)
      and q.original_prepare_command_id=(select command_id from private.bpay_next_run_command where run_id=r.id)
      and w.status='CANCELLING' and w.preparation_revision=x.preparation_revision and w.case_selection_revision=x.selection_revision
      and w.realised_effect_count=0 and w.net_request_revision=0 and w.net_projection_revision=0
      and i.case_kind='OVERPAYMENT' and i.tax_treatment='TAXABLE' and i.source_pay_channel='PAYE' and i.target_pay_channel='PAYE'
      and i.instruction_kind='RECOVERY' and i.direction='DEDUCTION' and i.payroll_stage='GROSS_DEDUCT' and i.hold_purpose='GROSS_RECOVERY'
      and h.status='RELEASED' and h.allocation_pass_kind='DRAFT' and h.projection_id is null
      and h.finished_at_utc>=q.accepted_at_utc and (x.case_hold_cursor is null or h.id>x.case_hold_cursor)
      and (p_case_hold_id is null or h.id=p_case_hold_id)
      and u.status='RELEASED' and u.realisation_event_id is null and u.source_amount_ex_vat=h.source_reserved_ex_vat
      and (h.source_reserved_ex_vat,h.target_amount_ex_vat,h.target_amount_vat,h.target_amount_inc_vat)
        is not distinct from (a.allocated_source_ex_vat,a.allocated_target_ex_vat,a.allocated_target_vat,a.allocated_target_inc_vat)
      and not exists(select 1 from private.bpay_next_transfer where run_worker_id=w.id)
      and not exists(select 1 from private.bpay_next_net_projection where run_worker_id=w.id)
      and not exists(select 1 from private.bpay_next_job earlier where earlier.candidate_id=j.candidate_id
        and earlier.command_sequence<j.command_sequence and earlier.status<>'DONE'))
$function$;

create or replace function private.bpay_next_reconcile_expired_work_collection_v1(p_job_id uuid,p_case_hold_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_basis private.bpay_next_work_collection%rowtype;
begin
  select b.* into strict v_basis from private.bpay_next_case_hold h
    join private.bpay_next_run_case_instruction i on i.id=h.instruction_id
    join private.bpay_next_work_collection b on b.id=i.work_collection_id
      and b.case_id=h.case_id and b.case_component_id=h.case_component_id and b.candidate_id=h.candidate_id
    where h.id=p_case_hold_id;
  -- Comparison path preserves the ONE actual0510 released hold; core owns its exact qualified expiry scope.
  if exists(select 1 from private.bpay_next_position p where p.work_id=v_basis.work_id
    and p.component_key=v_basis.component_key and p.source_comparison_receipt_id is not null) then
    perform private.bpay_next_reconcile_source_comparison_case_release_v2(p_job_id,p_case_hold_id);
    return;
  end if;
  if not private.bpay_next_expired_work_collection_scope_v1(p_job_id,v_basis.id,p_case_hold_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_EXPIRY_SCOPE_INVALID';end if;
  -- No financial disposition: the existing liability formula sees the exact
  -- released H and the maintained applied A/R/W. It never changes R, frozen
  -- evidence or an original cash receipt.1519 must explicitly admit this owner.
  perform private.bpay_next_reconcile_work_collection_v1(p_job_id,v_basis.work_id,v_basis.component_key,null);
end
$function$;

create or replace function private.bpay_next_expire_preparation_worker_page_v1(
  p_job_id uuid,p_lease_nonce uuid,p_owner_epoch bigint,p_expected_checkpoint bigint,p_limit integer)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_epoch bigint;v_run_id uuid;v_candidate uuid;v_seen integer:=0;v_work_holds integer:=0;v_case_released integer:=0;v_more boolean;
  v_run private.bpay_next_pay_run%rowtype;v_control private.bpay_next_worker_control%rowtype;v_job private.bpay_next_job%rowtype;
  v_binding private.bpay_next_preparation_expiry_worker%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_line private.bpay_next_run_line%rowtype;v_hold private.bpay_next_hold%rowtype;
  v_case_hold private.bpay_next_case_hold%rowtype;v_use private.bpay_next_case_capacity_use%rowtype;
  v_instruction private.bpay_next_run_case_instruction%rowtype;v_result private.bpay_next_case_allocation_result%rowtype;
  v_amount numeric;v_now timestamptz;v_checkpoint bigint;
begin
  if p_job_id is null or p_lease_nonce is null or p_owner_epoch is null or p_owner_epoch<1
     or p_limit is null or p_limit not between 1 and 100 or (p_expected_checkpoint is not null and p_expected_checkpoint<1) then
    raise exception using errcode='22023',message='BPAY_NEXT_EXPIRY_PAGE_INPUT_INVALID';end if;
  select owner_epoch into v_epoch from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select run_id,candidate_id into strict v_run_id,v_candidate from private.bpay_next_preparation_expiry_worker where job_id=p_job_id;
  select * into strict v_run from private.bpay_next_pay_run where id=v_run_id for update;
  select * into strict v_control from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  select * into strict v_job from private.bpay_next_job where id=p_job_id for update;
  select * into strict v_binding from private.bpay_next_preparation_expiry_worker where job_id=p_job_id for update;
  if v_binding.run_worker_id is not null then select * into strict v_worker from private.bpay_next_run_worker where id=v_binding.run_worker_id for update;end if;
  if v_job.job_kind<>'PREPARATION_EXPIRY' or v_job.module_epoch<>v_epoch or v_job.command_id<>v_binding.command_id
     or v_job.candidate_id<>v_candidate or v_job.cursor_key is distinct from nullif(v_binding.checkpoint,0)::text
     or not exists(select 1 from private.bpay_next_command c join private.bpay_next_preparation_expiry_request x on x.command_id=c.id
       where c.id=v_job.command_id and c.command_kind='PREPARATION_EXPIRY' and c.agency_sequence=v_job.command_sequence
         and c.module_epoch=v_epoch and x.run_id=v_run_id and x.captured_deadline=v_run.preparation_expires_at_utc
         and x.expected_candidate_count=c.expected_member_count and x.enrolled_candidate_count=c.enrolled_member_count
         and v_run.review_revision=x.selection_review_revision+1) then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_PAGE_SCOPE_INVALID';end if;
  if v_job.status='DONE' and v_job.phase='EXPIRED' and v_binding.status='EXPIRED' and v_binding.stage='COMPLETE' then
    return pg_catalog.jsonb_build_object('phase','EXPIRED','cursor',v_job.cursor_key,'rows_visited','0',
      'work_released','0','case_holds_released','0',
      'run_worker_id',v_binding.run_worker_id,'replay',true);end if;
  if v_run.status<>'CANCELLING' or v_run.confirmed_at_utc is not null or v_job.status<>'LEASED'
     or v_job.phase not in ('NEW','RELEASE') or v_job.lease_nonce<>p_lease_nonce or v_job.owner_epoch<>p_owner_epoch
     or v_control.active_owner_epoch<>p_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or exists(select 1 from private.bpay_next_job where candidate_id=v_candidate and command_sequence<v_job.command_sequence and status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_EXPIRY_PAGE_LEASE_INVALID';end if;
  if coalesce(p_expected_checkpoint,0)<>v_binding.checkpoint then
    if coalesce(p_expected_checkpoint,0)>v_binding.checkpoint then raise exception using errcode='55000',message='BPAY_NEXT_EXPIRY_CURSOR_AHEAD';end if;
    return pg_catalog.jsonb_build_object('phase','RELEASE','cursor',v_job.cursor_key,'rows_visited','0',
      'work_released','0','case_holds_released','0',
      'run_worker_id',v_binding.run_worker_id,'replay',true);end if;
  -- Never put completion before its accepted receipt, including labelled
  -- owner-only simulated-clock vectors. Public receipts use the real clock.
  v_now:=greatest(pg_catalog.clock_timestamp(),(select accepted_at_utc from private.bpay_next_preparation_expiry_request where command_id=v_binding.command_id));
  if v_binding.status='READY' then
    if v_job.phase<>'NEW' or v_binding.stage<>'NEW' then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_START_INVALID';end if;
    if v_worker.id is not null then
      if v_worker.status<>v_binding.original_worker_status or v_worker.captured_line_count<>v_binding.expected_work_count
         or v_worker.active_case_hold_count<>v_binding.expected_case_hold_count or v_worker.preparation_revision<>v_binding.preparation_revision
         or v_worker.case_selection_revision<>v_binding.selection_revision or v_worker.realised_effect_count<>0
         or v_worker.net_projection_revision<>0 or v_worker.net_request_revision<>0
         or exists(select 1 from private.bpay_next_transfer where run_worker_id=v_worker.id)
         or exists(select 1 from private.bpay_next_net_projection where run_worker_id=v_worker.id) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_GROUP_NOT_UNCONFIRMED';end if;
      -- The original issue is immutable in this exact expiry binding. Clear
      -- only the current status diagnostic to satisfy the existing REVIEW CK.
      -- Financial resolution counts, captured money and evidence stay intact.
      update private.bpay_next_run_worker set status='CANCELLING',review_issue_code=null,review_issue_work_id=null where id=v_worker.id;
      v_worker.status:='CANCELLING';
    end if;
    v_binding.status:='RELEASING';v_binding.stage:='WORK';v_binding.started_at_utc:=v_now;
    update private.bpay_next_job set phase='RELEASE' where id=p_job_id;
  end if;
  if v_binding.status<>'RELEASING' or (v_worker.id is not null and (v_worker.status<>'CANCELLING'
      or v_worker.realised_effect_count<>0 or v_worker.captured_line_count<>v_binding.expected_work_count)) then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_FENCE_BROKEN';end if;
  if v_binding.stage='WORK' then
    for v_line in select * from private.bpay_next_run_line where run_worker_id=v_binding.run_worker_id
      and line_no>coalesce(v_binding.work_cursor,0) order by line_no,id limit p_limit loop
      select * into v_hold from private.bpay_next_hold where run_line_id=v_line.id for update;
      if found then
        if v_hold.status<>'ACTIVE' or v_hold.work_id<>v_line.work_id or v_hold.component_key<>v_line.component_key
           or (v_hold.source_reserved_ex_vat,v_hold.target_amount_ex_vat,v_hold.target_amount_vat,v_hold.target_amount_inc_vat)
             is distinct from (v_line.source_consumed_ex_vat,v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat) then
          raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WORK_HOLD_NOT_EXACT';end if;
        update private.bpay_next_hold set status='RELEASED',finished_at_utc=v_now where id=v_hold.id;
        if not private.bpay_next_source_comparison_carry_known_work_v2(
          p_job_id,v_line.id,'RELEASE',v_hold.id) then
          update private.bpay_next_position set held_source_ex_vat=held_source_ex_vat-v_hold.source_reserved_ex_vat,
            held_target_ex_vat=held_target_ex_vat-v_hold.target_amount_ex_vat,held_target_vat=held_target_vat-v_hold.target_amount_vat,
            held_target_inc_vat=held_target_inc_vat-v_hold.target_amount_inc_vat,updated_at_utc=v_now
            where work_id=v_hold.work_id and component_key=v_hold.component_key and held_source_ex_vat>=v_hold.source_reserved_ex_vat
              and held_target_ex_vat>=v_hold.target_amount_ex_vat and held_target_vat>=v_hold.target_amount_vat and held_target_inc_vat>=v_hold.target_amount_inc_vat;
          if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WORK_POSITION_MISMATCH';end if;
        end if;
        v_work_holds:=v_work_holds+1;
      elsif (v_line.source_consumed_ex_vat,v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat) is distinct from (0::numeric,0::numeric,0::numeric,0::numeric) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_POSITIVE_HOLD_MISSING';end if;
      v_binding.work_cursor:=v_line.line_no;v_binding.released_work_count:=v_binding.released_work_count+1;v_seen:=v_seen+1;
    end loop;
    select exists(select 1 from private.bpay_next_run_line where run_worker_id=v_binding.run_worker_id and line_no>coalesce(v_binding.work_cursor,0)) into v_more;
    if not v_more then
      if v_binding.released_work_count<>v_binding.expected_work_count then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WORK_COUNT_INVALID';end if;
      v_binding.stage:='CASE';end if;
  elsif v_binding.stage='CASE' then
    for v_case_hold in select * from private.bpay_next_case_hold where run_worker_id=v_binding.run_worker_id and status='ACTIVE'
      and (v_binding.case_hold_cursor is null or id>v_binding.case_hold_cursor) order by id limit p_limit loop
      select * into strict v_instruction from private.bpay_next_run_case_instruction where id=v_case_hold.instruction_id;
      select * into strict v_result from private.bpay_next_case_allocation_result where id=v_case_hold.allocation_result_id;
      perform 1 from private.bpay_next_finance_case where id=v_case_hold.case_id for update;
      perform 1 from private.bpay_next_case_component where id=v_case_hold.case_component_id for update;
      perform 1 from private.bpay_next_case_period where case_component_id=v_case_hold.case_component_id and pay_week_start=v_case_hold.pay_week_start for update;
      perform 1 from private.bpay_next_case_hold where id=v_case_hold.id for update;
      select * into strict v_use from private.bpay_next_case_capacity_use where case_hold_id=v_case_hold.id for update;
      if v_instruction.run_worker_id<>v_binding.run_worker_id or v_instruction.preparation_revision<>v_binding.preparation_revision
         or v_instruction.selection_revision<>v_binding.selection_revision or v_case_hold.candidate_id<>v_candidate
         or v_case_hold.allocation_pass_kind<>'DRAFT' or v_result.pass_kind<>'DRAFT'
         or v_result.instruction_id<>v_instruction.id or v_result.state_id is distinct from v_binding.draft_state_id
         or v_case_hold.projection_id is not null or v_use.status<>'ACTIVE' or v_use.realisation_event_id is not null
         or v_use.source_amount_ex_vat<>v_case_hold.source_reserved_ex_vat
         or (v_case_hold.source_reserved_ex_vat,v_case_hold.target_amount_ex_vat,v_case_hold.target_amount_vat,v_case_hold.target_amount_inc_vat)
           is distinct from (v_result.allocated_source_ex_vat,v_result.allocated_target_ex_vat,v_result.allocated_target_vat,v_result.allocated_target_inc_vat) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_HOLD_NOT_EXACT';end if;
      v_amount:=v_case_hold.source_reserved_ex_vat;
      if v_case_hold.purpose='PAYOUT' then
        update private.bpay_next_case_component set active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,
          component_revision=component_revision+1,updated_at_utc=v_now where id=v_case_hold.case_component_id and active_payout_source_ex_vat>=v_amount;
        if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_COMPONENT_CAPACITY_INVALID';end if;
        update private.bpay_next_finance_case set active_payout_hold_amount=active_payout_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
          case_revision=case_revision+1,updated_at_utc=v_now where id=v_case_hold.case_id and active_payout_hold_amount>=v_amount and active_hold_amount>=v_amount;
      else
        update private.bpay_next_case_component set active_recovery_source_ex_vat=active_recovery_source_ex_vat-v_amount,
          component_revision=component_revision+1,updated_at_utc=v_now where id=v_case_hold.case_component_id and active_recovery_source_ex_vat>=v_amount;
        if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_COMPONENT_CAPACITY_INVALID';end if;
        update private.bpay_next_finance_case set active_recovery_hold_amount=active_recovery_hold_amount-v_amount,active_hold_amount=active_hold_amount-v_amount,
          case_revision=case_revision+1,updated_at_utc=v_now where id=v_case_hold.case_id and active_recovery_hold_amount>=v_amount and active_hold_amount>=v_amount;
      end if;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_CAPACITY_INVALID';end if;
      if v_case_hold.purpose='PAYOUT' then
        update private.bpay_next_case_period set active_payout_source_ex_vat=active_payout_source_ex_vat-v_amount,period_revision=period_revision+1
          where case_component_id=v_case_hold.case_component_id and pay_week_start=v_case_hold.pay_week_start and active_payout_source_ex_vat>=v_amount;
      else
        update private.bpay_next_case_period set active_unrealised_recovery_source_ex_vat=active_unrealised_recovery_source_ex_vat-v_amount,period_revision=period_revision+1
          where case_component_id=v_case_hold.case_component_id and pay_week_start=v_case_hold.pay_week_start and active_unrealised_recovery_source_ex_vat>=v_amount;
      end if;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_PERIOD_INVALID';end if;
      update private.bpay_next_case_hold set status='RELEASED',finished_at_utc=v_now where id=v_case_hold.id;
      update private.bpay_next_case_capacity_use set status='RELEASED' where case_hold_id=v_case_hold.id;
      update private.bpay_next_run_worker set active_case_hold_count=active_case_hold_count-1 where id=v_worker.id and active_case_hold_count>0;
      if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_HOLD_COUNT_INVALID';end if;
      if v_instruction.work_collection_id is not null then
        perform private.bpay_next_reconcile_expired_work_collection_v1(p_job_id,v_case_hold.id);
      end if;
      v_binding.case_hold_cursor:=v_case_hold.id;v_binding.released_case_hold_count:=v_binding.released_case_hold_count+1;v_seen:=v_seen+1;v_case_released:=v_case_released+1;
    end loop;
    select exists(select 1 from private.bpay_next_case_hold where run_worker_id=v_binding.run_worker_id and status='ACTIVE') into v_more;
    if not v_more then
      if v_binding.released_case_hold_count<>v_binding.expected_case_hold_count
         or (v_worker.id is not null and (select active_case_hold_count from private.bpay_next_run_worker where id=v_worker.id)<>0) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_COUNT_INVALID';end if;
      v_binding.stage:='FINAL';
    elsif v_seen=0 then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CASE_CURSOR_INVALID';end if;
  elsif v_binding.stage='FINAL' then
    if v_binding.released_work_count<>v_binding.expected_work_count or v_binding.released_case_hold_count<>v_binding.expected_case_hold_count
       or exists(select 1 from private.bpay_next_case_hold where run_worker_id=v_binding.run_worker_id and status='ACTIVE') then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_FINAL_COUNT_INVALID';end if;
    if v_worker.id is not null then update private.bpay_next_run_worker set status='CANCELLED' where id=v_worker.id;end if;
    v_binding.stage:='COMPLETE';v_binding.status:='EXPIRED';v_binding.finished_at_utc:=v_now;v_seen:=1;
  else raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_STAGE_INVALID';end if;
  update private.bpay_next_preparation_expiry_worker set status=v_binding.status,stage=v_binding.stage,checkpoint=checkpoint+1,
    released_work_count=v_binding.released_work_count,released_case_hold_count=v_binding.released_case_hold_count,
    work_cursor=v_binding.work_cursor,case_hold_cursor=v_binding.case_hold_cursor,started_at_utc=v_binding.started_at_utc,
    finished_at_utc=v_binding.finished_at_utc where job_id=p_job_id returning checkpoint into v_checkpoint;
  update private.bpay_next_job set cursor_key=v_checkpoint::text,applied_line_count=v_binding.released_work_count,
    lease_until_utc=pg_catalog.clock_timestamp()+interval '120 seconds' where id=p_job_id;
  update private.bpay_next_worker_control set financial_view_revision=financial_view_revision+1,updated_at_utc=v_now where candidate_id=v_candidate;
  if v_binding.status='EXPIRED' then
    perform private.bpay_next_apply_expired_week_v1(p_job_id);
    update private.bpay_next_job set status='DONE',phase='EXPIRED',lease_nonce=null,lease_until_utc=null where id=p_job_id;
    update private.bpay_next_preparation_expiry_request set completed_candidate_count=completed_candidate_count+1,
      status=case when completed_candidate_count+1=expected_candidate_count and enrolled_candidate_count=expected_candidate_count then 'EXPIRED' else status end,
      finished_at_utc=case when completed_candidate_count+1=expected_candidate_count and enrolled_candidate_count=expected_candidate_count then v_now else null end
      where command_id=v_binding.command_id and completed_candidate_count<enrolled_candidate_count;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_PARENT_COUNT_INVALID';end if;
    update private.bpay_next_pay_run set cancelled_candidate_count=cancelled_candidate_count+1,
      status=case when cancelled_candidate_count+1=selected_candidate_count then 'CANCELLED' else 'CANCELLING' end
      where id=v_run_id and cancelled_candidate_count<selected_candidate_count;
    if not found then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_RUN_COUNT_INVALID';end if;
    if exists(select 1 from private.bpay_next_preparation_expiry_request where command_id=v_binding.command_id and status='EXPIRED') then
      update private.bpay_next_command set status='COMPLETE' where id=v_binding.command_id;end if;
  end if;
  return pg_catalog.jsonb_build_object('phase',case when v_binding.status='EXPIRED' then 'EXPIRED' else 'RELEASE' end,
    'cursor',v_checkpoint::text,'rows_visited',v_seen::text,'work_released',v_work_holds::text,
    'case_holds_released',v_case_released::text,'run_worker_id',v_binding.run_worker_id,'replay',false);
end
$function$;

-- Retained PREPARE queue messages cannot resurrect a stopped capture. Original
-- DONE receipts/cursors remain stored; expose current expiry truth separately.
create or replace function private.bpay_next_expired_prepare_receipt_v1(p_job_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_job private.bpay_next_job%rowtype;v_run private.bpay_next_pay_run%rowtype;
  v_request private.bpay_next_preparation_expiry_request%rowtype;v_worker private.bpay_next_run_worker%rowtype;
  v_binding private.bpay_next_preparation_expiry_worker%rowtype;
begin
  select * into strict v_job from private.bpay_next_job where id=p_job_id and job_kind='PREPARE';
  select r.* into strict v_run from private.bpay_next_pay_run r join private.bpay_next_run_command rc on rc.run_id=r.id
    where rc.command_id=v_job.command_id;
  select * into strict v_request from private.bpay_next_preparation_expiry_request where run_id=v_run.id
    and original_prepare_command_id=v_job.command_id;
  if v_job.status<>'DONE' then raise exception using errcode='55000',message='BPAY_NEXT_PREPARATION_EXPIRING';end if;
  if v_run.status not in ('CANCELLING','CANCELLED') or v_run.confirmed_at_utc is not null
     or v_request.captured_deadline<>v_run.preparation_expires_at_utc
     or not private.bpay_next_preparation_expiry_fenced_v1(v_run.id,v_job.command_id)
     or v_job.phase not in ('EXPIRED','READY','DONE')
     or not exists(select 1 from private.bpay_next_command where id=v_request.command_id
       and command_kind='PREPARATION_EXPIRY' and module_epoch=v_job.module_epoch)
     or not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' and owner_epoch=v_job.module_epoch) then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRED_PREPARE_RECEIPT_SCOPE_INVALID';end if;
  select * into v_worker from private.bpay_next_run_worker where run_id=v_run.id and candidate_id=v_job.candidate_id;
  select * into v_binding from private.bpay_next_preparation_expiry_worker where command_id=v_request.command_id and candidate_id=v_job.candidate_id;
  if v_binding.job_id is not null and v_binding.original_job_id is distinct from v_job.id then
    raise exception using errcode='23514',message='BPAY_NEXT_EXPIRED_PREPARE_RECEIPT_JOB_MISMATCH';end if;
  return pg_catalog.jsonb_build_object('done',true,'phase','EXPIRED','cursor',v_job.cursor_key,
    'work_cursor',v_job.position_work_cursor,'component_cursor',v_job.position_component_cursor,'rows_visited','0',
    'replay',true,'run_worker_id',v_worker.id,'worker_status',v_worker.status,
    'issue_code',coalesce(v_worker.review_issue_code,v_binding.original_review_issue_code),
    'issue_work_id',coalesce(v_worker.review_issue_work_id,v_binding.original_review_issue_work_id));
end
$function$;

create or replace function private.bpay_next_preparation_expiry_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
declare v_run private.bpay_next_pay_run%rowtype;v_request private.bpay_next_preparation_expiry_request%rowtype;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_EVIDENCE_DELETE_FORBIDDEN';end if;
  if tg_table_name='bpay_next_pay_run' then
    if tg_op='INSERT' then
      if new.preparation_expires_at_utc is null or new.preparation_expires_at_utc<>new.created_at_utc+interval '72 hours' then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_CAPTURED_DEADLINE_REQUIRED';end if;
    elsif (new.created_at_utc,new.preparation_expires_at_utc) is distinct from (old.created_at_utc,old.preparation_expires_at_utc) then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_DEADLINE_IMMUTABLE';end if;
    if new.status='CANCELLING' or (tg_op='UPDATE' and old.status='CANCELLING') then
      if new.confirmed_at_utc is not null or new.status not in ('CANCELLING','CANCELLED')
         or not exists(select 1 from private.bpay_next_preparation_expiry_request where run_id=new.id
           and captured_deadline=new.preparation_expires_at_utc and selection_count=new.selection_count
           and selection_page_count=new.selection_page_count and expected_candidate_count=new.selected_candidate_count
           and new.review_revision=selection_review_revision+1) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_HEADER_FENCE_INVALID';end if;
    end if;
    return new;
  end if;
  if tg_op='INSERT' then
    if tg_table_name='bpay_next_preparation_expiry_request' then
      select * into strict v_run from private.bpay_next_pay_run where id=new.run_id;
      if v_run.status not in ('PREPARING','REVIEW') or v_run.confirmed_at_utc is not null
         or new.captured_deadline is distinct from v_run.preparation_expires_at_utc
         or (new.selection_count,new.selection_page_count,new.selection_review_revision,new.expected_candidate_count)
           is distinct from (v_run.selection_count,v_run.selection_page_count,v_run.review_revision,v_run.selected_candidate_count)
         or new.enrolled_candidate_count<>0 or new.completed_candidate_count<>0
         or not exists(select 1 from private.bpay_next_command where id=new.command_id and command_kind='PREPARATION_EXPIRY' and status='RECEIVED')
         or new.original_prepare_command_id is distinct from (select command_id from private.bpay_next_run_command where run_id=new.run_id) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_REQUEST_INITIAL_INVALID';end if;
    else
      select * into strict v_request from private.bpay_next_preparation_expiry_request where command_id=new.command_id;
      select * into strict v_run from private.bpay_next_pay_run where id=new.run_id;
      if v_run.status<>'CANCELLING' or v_run.confirmed_at_utc is not null or v_request.status<>'CANCELLING'
         or new.run_id<>v_request.run_id or new.member_no<>v_request.enrolled_candidate_count+1
         or new.status<>'READY' or new.stage<>'NEW' or new.checkpoint<>0
         or new.released_work_count<>0 or new.released_case_hold_count<>0 or new.work_cursor is not null or new.case_hold_cursor is not null
         or not exists(select 1 from private.bpay_next_selection_candidate where run_id=new.run_id and candidate_id=new.candidate_id and member_no=new.member_no)
         or not exists(select 1 from private.bpay_next_job where id=new.job_id and command_id=new.command_id and candidate_id=new.candidate_id
           and job_kind='PREPARATION_EXPIRY' and status='READY' and phase='NEW')
         or (v_request.original_prepare_command_id is null) is distinct from (new.original_job_id is null)
         or (new.original_job_id is not null and not exists(select 1 from private.bpay_next_job where id=new.original_job_id
           and command_id=v_request.original_prepare_command_id and candidate_id=new.candidate_id and job_kind='PREPARE' and status='DONE'))
         or (new.run_worker_id is not null and not exists(select 1 from private.bpay_next_run_worker where id=new.run_worker_id
           and run_id=new.run_id and candidate_id=new.candidate_id and status=new.original_worker_status
           and preparation_revision=new.preparation_revision and case_selection_revision=new.selection_revision
           and captured_line_count=new.expected_work_count and active_case_hold_count=new.expected_case_hold_count
           and review_issue_code is not distinct from new.original_review_issue_code and review_issue_work_id is not distinct from new.original_review_issue_work_id)) then
        raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WORKER_INITIAL_INVALID';end if;
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_preparation_expiry_request' then
    if old.status='EXPIRED' or (pg_catalog.to_jsonb(new)-'enrolled_candidate_count'-'completed_candidate_count'-'status'-'finished_at_utc')
       is distinct from (pg_catalog.to_jsonb(old)-'enrolled_candidate_count'-'completed_candidate_count'-'status'-'finished_at_utc')
       or new.enrolled_candidate_count not between old.enrolled_candidate_count and old.enrolled_candidate_count+1
       or new.completed_candidate_count not between old.completed_candidate_count and old.completed_candidate_count+1 then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_REQUEST_TRANSITION_INVALID';end if;
  else
    if old.status='EXPIRED' or (pg_catalog.to_jsonb(new)-'checkpoint'-'status'-'stage'-'released_work_count'-'released_case_hold_count'-'work_cursor'-'case_hold_cursor'-'started_at_utc'-'finished_at_utc')
       is distinct from (pg_catalog.to_jsonb(old)-'checkpoint'-'status'-'stage'-'released_work_count'-'released_case_hold_count'-'work_cursor'-'case_hold_cursor'-'started_at_utc'-'finished_at_utc')
       or new.checkpoint<>old.checkpoint+1 or new.released_work_count<old.released_work_count or new.released_case_hold_count<old.released_case_hold_count
       or (old.work_cursor is not null and (new.work_cursor is null or new.work_cursor<old.work_cursor))
       or (old.case_hold_cursor is not null and (new.case_hold_cursor is null or new.case_hold_cursor<old.case_hold_cursor))
       or (old.started_at_utc is not null and new.started_at_utc is distinct from old.started_at_utc)
       or (old.stage='NEW' and new.stage not in ('WORK','CASE')) or (old.stage='WORK' and new.stage not in ('WORK','CASE'))
       or (old.stage='CASE' and new.stage not in ('CASE','FINAL')) or (old.stage='FINAL' and new.stage<>'COMPLETE') then
      raise exception using errcode='23514',message='BPAY_NEXT_EXPIRY_WORKER_TRANSITION_INVALID';end if;
  end if;
  return new;
end
$function$;
drop trigger if exists bpay_next_preparation_expiry_guard_v1 on private.bpay_next_pay_run;
create trigger bpay_next_preparation_expiry_guard_v1 before insert or update or delete on private.bpay_next_pay_run
  for each row execute function private.bpay_next_preparation_expiry_guard_v1();
drop trigger if exists bpay_next_preparation_expiry_guard_v1 on private.bpay_next_preparation_expiry_request;
create trigger bpay_next_preparation_expiry_guard_v1 before insert or update or delete on private.bpay_next_preparation_expiry_request
  for each row execute function private.bpay_next_preparation_expiry_guard_v1();
drop trigger if exists bpay_next_preparation_expiry_guard_v1 on private.bpay_next_preparation_expiry_worker;
create trigger bpay_next_preparation_expiry_guard_v1 before insert or update or delete on private.bpay_next_preparation_expiry_worker
  for each row execute function private.bpay_next_preparation_expiry_guard_v1();
alter function private.bpay_next_preparation_expiry_fenced_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_accept_preparation_expiry_v1(uuid,uuid,uuid,timestamptz,timestamptz) OWNER TO CURRENT_USER;
alter function private.bpay_next_enroll_preparation_expiry_one_v1(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_claim_preparation_expiry_job_v1(uuid,integer) OWNER TO CURRENT_USER;
alter function private.bpay_next_apply_expired_week_v1(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_expired_work_collection_scope_v1(uuid,uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_reconcile_expired_work_collection_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_expire_preparation_worker_page_v1(uuid,uuid,bigint,bigint,integer) OWNER TO CURRENT_USER;
alter function private.bpay_next_expired_prepare_receipt_v1(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_preparation_expiry_guard_v1() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_preparation_expiry_fenced_v1(uuid,uuid),
  private.bpay_next_accept_preparation_expiry_v1(uuid,uuid,uuid,timestamptz,timestamptz),
  private.bpay_next_enroll_preparation_expiry_one_v1(uuid),private.bpay_next_claim_preparation_expiry_job_v1(uuid,integer),
  private.bpay_next_apply_expired_week_v1(uuid),private.bpay_next_expire_preparation_worker_page_v1(uuid,uuid,bigint,bigint,integer),
  private.bpay_next_expired_work_collection_scope_v1(uuid,uuid,uuid),private.bpay_next_reconcile_expired_work_collection_v1(uuid,uuid),
  private.bpay_next_expired_prepare_receipt_v1(uuid),private.bpay_next_preparation_expiry_guard_v1()
  from public,anon,authenticated,service_role;


-- A8 late shared Source factual evidence / retired financial projection boundary.
-- Retains complete latest Source owners and their LEGACY assertions. NEXT and
-- DISABLED keep the same server-owned transaction token, current head and exact
-- immutable receipt, but prove zero legacy queue/scope effects instead of
-- manufacturing a legacy dirty job. Source inventory/provenance/financial
-- producers, protected decisions, and exact replay remain their real owners.
-- Coordinate with0550's sole shared-token exclusion; every other old financial
-- table stays physically fenced. Never install this as a token-only workaround.



create or replace function private.bpay_next_source_factual_contract_v1(
  p_frame uuid,p_token uuid,p_root_ids uuid[],p_context text
)
returns jsonb language plpgsql volatile security definer
set search_path=pg_catalog,private,pg_temp
as $function$
declare
  v_frame uuid;
  v_sealed boolean;
  v_state text;
  v_generation bigint;
begin
  if private.bpay_next_legacy_callback_enabled_v1()
     or p_frame is null or p_token is null
     or p_context is null or p_context not in ('PUBLICATION','WITHDRAWAL')
     or p_root_ids is null or cardinality(p_root_ids) not between 1 and 2
     or array_position(p_root_ids,null::uuid) is not null
     or not private.weekly_source_uuid_array_is_distinct_v1(p_root_ids)
     or pg_catalog.to_regclass('pg_temp.ws_observation_frame_v1') is null
     or pg_catalog.to_regclass('pg_temp.ws_observation_rows_v1') is null then
    raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_FACTUAL_CONTRACT_REQUIRED';
  end if;
  select f.frame_id,f.sealed into v_frame,v_sealed
    from pg_temp.ws_observation_frame_v1 f where f.singleton;
  if not found or v_frame is distinct from p_frame or v_sealed is distinct from false then
    raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_FACTUAL_FRAME_MISMATCH';
  end if;
  -- Exact native PK evidence, not a scope-generation/history reconstruction.
  select t.state,t.allocated_generation into v_state,v_generation
    from public.banking_pay_scope_change_transactions t where t.tx_token=p_token for share;
  if not found or v_state is distinct from 'PENDING' or v_generation is not null
     or nullif(pg_catalog.current_setting('cloudtms.banking_pay_scope_tx_token',true),'')::uuid
        is distinct from p_token then
    raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_FACTUAL_TOKEN_NOT_OPEN';
  end if;
  -- The protected observer attributes actual INSERT/UPDATE/DELETE effects to
  -- this invocation, independent of each row's claimed Candidate or token.
  -- A reused controlling token may produce no new TOKEN INSERT in this frame.
  if exists(select 1 from pg_temp.ws_observation_rows_v1 e
      where e.frame_id=p_frame and
        (e.deleted or (e.kind='TOKEN' and e.row_id is distinct from p_token)))
     or exists(select 1 from pg_temp.ws_observation_rows_v1 e
       where e.frame_id=p_frame and e.kind in ('JOB','SCOPE','REGISTRY')) then
    raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_LEGACY_EFFECT_OBSERVED';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok',true,'skipped',true,'skip_reason','FINANCIAL_OWNER_NOT_LEGACY',
    'context',p_context,'candidate_count',0,'timesheet_count',0,
    'registry_inserted_count',0,'registry_updated_count',0,
    'state_inserted_count',0,'state_updated_count',0,
    'job_inserted_count',0,'job_coalesced_count',0,
    'scope_change_tx_token',p_token,'declared_root_ids',pg_catalog.to_jsonb(p_root_ids),
    'complete_scope_job_count',0,'whole_candidate_job_count',0,'jobs','[]'::jsonb);
end;
$function$;
alter function private.bpay_next_source_factual_contract_v1(uuid,uuid,uuid[],text) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_factual_contract_v1(uuid,uuid,uuid[],text)
  from public,anon,authenticated,service_role;

do $a8_source_existing$
begin
  if pg_catalog.to_regprocedure('private.weekly_source_entitlement_publish_core_v1(jsonb,text,jsonb,uuid,text,uuid,jsonb,jsonb)') is null
     or pg_catalog.to_regprocedure('public.weekly_source_first_authorisation_withdraw_v1(uuid,uuid,text,uuid)') is null then
    raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_FACTUAL_BASELINE_MISSING';
  end if;
end;
$a8_source_existing$;

-- Retained complete authority: supabase/repeatable/26092026_0203_banking_pay_stage2_workbench_draft_v1.sql
CREATE OR REPLACE FUNCTION private.weekly_source_entitlement_publish_core_v1(p_request jsonb, p_publication_mode text, p_lock_result jsonb, p_pending_bundle_id uuid, p_worker_id text, p_worker_run_id uuid, p_census jsonb, p_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  -- BEGIN A8 SOURCE MODE DECLARATION
  v_legacy_financial_owner boolean;
  -- END A8 SOURCE MODE DECLARATION
  v_mode text;
  v_canonical jsonb;
  v_digest bytea;
  v_now timestamptz;
  v_err_message text;
  v_err_detail text;
  v_err_state text;
  v_bundle record;
  v_pending record;
  v_receipt record;
  v_decision_bundle_id uuid;
  v_bundle_revision bigint;
  v_candidate_id uuid;
  v_decision_id uuid;
  v_member_root_ids uuid[];
  v_member_family_booking_ids text[];
  v_member_root_versions integer[];
  v_head_ids uuid[];
  v_expected_head_ids uuid[]:=array[]::uuid[];
  v_current_head_ids uuid[]:=array[]::uuid[];
  v_prior_head_ids uuid[]:=array[]::uuid[];
  v_head_revisions bigint[]:=array[]::bigint[];
  v_n integer;
  v_i integer;
  v_control jsonb;
  v_family jsonb;
  v_member_timesheet_ids uuid[]:=array[]::uuid[];
  v_entitlement jsonb;
  v_choice jsonb;
  v_component jsonb;
  v_component_sha bytea;
  v_component_ids uuid[];
  v_before_ids uuid[];
  v_after_1 uuid[]:=array[]::uuid[];
  v_after_2 uuid[]:=array[]::uuid[];
  v_before_1 uuid[]:=array[]::uuid[];
  v_before_2 uuid[]:=array[]::uuid[];
  v_moved uuid[]:=array[]::uuid[];
  -- WP-06c review F1: the CONTENT hash the SOURCE authority holds for every
  -- component of member 1's before-position, keyed by component_id.  It is what
  -- a MOVED component must still equal on the destination side.
  v_source_component_hashes jsonb:='{}'::jsonb;
  v_destination_reprice jsonb;
  v_moved_found integer;
  v_inventory_pairs jsonb;
  v_component_hashes jsonb;
  v_head_revision bigint;
  v_token uuid;
  v_invalidation jsonb;
  v_rows integer;
  v_live_generations integer;
  v_family_live_generations integer;
  v_family_members uuid[];
  v_any_generations integer;
  v_any_heads integer;
  v_target_auth jsonb;
  v_target_authorise_result jsonb;
  v_review jsonb;
  v_source_generation_digest bytea;
  v_contract_choice_digest bytea;
  v_before_inventory jsonb;
  v_before_inventory_digest bytea;
  v_acceptance_digest bytea;
  v_before_source text[]:=array[]::text[];
  v_next_pair boolean:=false;
  v_before_source_event_ids uuid[]:=array[]::uuid[];
  v_before_financial_snapshot_ids uuid[]:=array[]::uuid[];
  v_before_auth public.weekly_source_root_authorisations%rowtype;
  v_before_financial public.timesheets_financials%rowtype;
  v_before_auth_count integer;
  v_pair_detail_count integer;
  v_pair_worked_count integer;
  v_effective jsonb;
  v_blank jsonb;
  v_observation_frame uuid;
  v_token_recheck uuid;
  v_declared_scope uuid[];
  v_normalised jsonb;
  v_offending jsonb;
  v_accepted_app jsonb;
  -- The single Local producer is qualified once against its genuine sealed
  -- receipt/context; neither a PROTECTED label nor absent Final is authority.
  v_local_publication_qualified boolean:=false;
  v_local_context jsonb;
  v_local_request jsonb;
  v_local_detail_count integer;
  v_local_worked_count integer;
  v_result_heads jsonb:='[]'::jsonb;
  v_lineage_rows integer:=0;
begin
  -- Service-only, exactly as public.weekly_source_timesheet_lineage_ensure_atomic_v1.
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  -- Shape validation and the one canonical digest.  Nothing has been written,
  -- so a malformed request is returned rather than raised.
  begin
    v_mode:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_publication_mode,'')));
    if v_mode not in ('IMMEDIATE','DEFERRED') then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_publication_mode','reason','EXPECTED_IMMEDIATE_OR_DEFERRED')::text;
    end if;
    -- proof/32 section 9 and H2-038: both Worker fields are required when the
    -- mode is DEFERRED and null when it is IMMEDIATE.
    if (v_mode='DEFERRED')<>(p_worker_id is not null and p_worker_run_id is not null)
       or (v_mode='IMMEDIATE' and (p_worker_id is not null or p_worker_run_id is not null)) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_worker_id','reason','WORKER_FIELDS_MUST_MATCH_MODE')::text;
    end if;
    if pg_catalog.jsonb_typeof(coalesce(p_census,'{}'::jsonb))<>'object'
       or pg_catalog.jsonb_typeof(coalesce(p_proof,'{}'::jsonb))<>'object' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_census','reason','EXPECTED_OBJECT')::text;
    end if;
    v_canonical:=private.weekly_source_publication_request_canonical_v1(
      p_request,v_mode,p_pending_bundle_id);
    v_digest:=private.weekly_source_publication_request_digest_v1(v_canonical);
  -- Review finding F10: catching only `invalid_parameter_value` let a malformed
  -- request RAISE instead of returning - an impossible calendar date (22008),
  -- an integer outside the range (22003) and a non-uuid in the control scope
  -- (22P02) all escaped.  Nothing has been written at this point, so every one
  -- of them is a returned refusal, and WP-08b no longer counts a caller's typo
  -- as a technical failure on its way to MANUAL_REVIEW.
  exception when invalid_parameter_value
              or datetime_field_overflow
              or invalid_datetime_format
              or numeric_value_out_of_range
              or invalid_text_representation then
    get stacked diagnostics v_err_message=message_text, v_err_detail=pg_exception_detail,
                            v_err_state=returned_sqlstate;
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code',case when v_err_state='22023' then v_err_message
                  else 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID' end,
      'retryable',false,
      'detail',case when coalesce(v_err_detail,'') ~ '^\{' then v_err_detail::jsonb
                    else pg_catalog.jsonb_build_object(
                           'reason','REQUEST_VALUE_COULD_NOT_BE_PARSED',
                           'sqlstate',v_err_state,'message',v_err_message) end);
  end;

  v_now:=pg_catalog.clock_timestamp();
  v_control:=coalesce(p_request->'control','{}'::jsonb);
  v_decision_bundle_id:=(v_canonical->>'decision_bundle_id')::uuid;
  v_bundle_revision:=(v_canonical->>'bundle_revision')::bigint;
  v_candidate_id:=(v_canonical->>'candidate_id')::uuid;
  v_decision_id:=(v_canonical->>'decision_id')::uuid;

  select pg_catalog.array_agg(root_element.value::uuid order by root_element.ordinality)
    into v_member_root_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_root_ids')
         with ordinality as root_element(value,ordinality);
  select pg_catalog.array_agg(booking_element.value order by booking_element.ordinality)
    into v_member_family_booking_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_family_booking_ids')
         with ordinality as booking_element(value,ordinality);
  select pg_catalog.array_agg(version_element.value::integer order by version_element.ordinality)
    into v_member_root_versions
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_root_versions')
         with ordinality as version_element(value,ordinality);
  select pg_catalog.array_agg(head_element.value::uuid order by head_element.ordinality)
    into v_head_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'head_ids')
         with ordinality as head_element(value,ordinality);
  v_n:=pg_catalog.cardinality(v_member_root_ids);

  -- H2-032: no duplicate root and no duplicate head id.  The receipt relation
  -- repeats both rules; refusing here keeps the failure a refusal rather than a
  -- rolled-back transaction.
  if not private.weekly_source_uuid_array_is_distinct_v1(v_member_root_ids)
     or not private.weekly_source_uuid_array_is_distinct_v1(v_head_ids) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DUPLICATE_ROOT_OR_HEAD_ID'));
  end if;
  if v_n=2 and pg_catalog.btrim(v_member_family_booking_ids[1])
              =pg_catalog.btrim(v_member_family_booking_ids[2]) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','MEMBERS_SHARE_ONE_FAMILY'));
  end if;

  -- ---- 1. exact receipt replay, before any mutation (proof/32 section 8.1) --
  -- The digest is only an index lookup: every immutable receipt field is
  -- compared before a replay may be returned (H2-032).
  select * into v_receipt
    from private.weekly_source_entitlement_publication_receipts as receipt_row
   where receipt_row.request_digest=v_digest;
  if found then
    if v_receipt.decision_bundle_id<>v_decision_bundle_id
       or v_receipt.bundle_revision<>v_bundle_revision
       or v_receipt.candidate_id<>v_candidate_id
       or v_receipt.member_root_ids is distinct from v_member_root_ids
       or v_receipt.member_family_booking_ids is distinct from v_member_family_booking_ids
       or v_receipt.member_root_versions is distinct from v_member_root_versions
       or v_receipt.head_ids is distinct from v_head_ids
       or v_receipt.decision_id<>v_decision_id
       or v_receipt.publication_mode<>v_mode
       or v_receipt.pending_bundle_id is distinct from p_pending_bundle_id then
      -- Round-5 ruling A1 control 5: "conflicting replay and a tampered row are
      -- PERMANENT integrity failures and go DIRECTLY to manual review; they are
      -- not retried ten times".  The same digest over different immutable
      -- receipt fields means two different economic decisions share one money
      -- identity, which no amount of retrying can resolve.  `retryable:false`
      -- alone only stops the immediate retry; the disposition below is what
      -- tells the deferred release owner to route the bundle to MANUAL_REVIEW
      -- at once instead of counting it as one of its ten technical failures.
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REPLAY_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','A_COMMITTED_RECEIPT_CARRIES_THIS_DIGEST_WITH_DIFFERENT_IMMUTABLE_FIELDS',
          'receipt_id',v_receipt.id,
          'request_digest',pg_catalog.encode(v_digest,'hex')));
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'published',true,'replayed',true,
      'receipt',private.weekly_source_publication_receipt_json_v1(v_receipt.id));
  end if;

  -- Fresh publication admission precedes even the module SHARE hidden inside
  -- the callback-mode helper. Exact immutable receipt replay above is exempt.
  perform private.weekly_source_pay_query_admit_v2();

  -- BEGIN A8 SOURCE MODE CAPTURE
  v_legacy_financial_owner:=private.bpay_next_legacy_callback_enabled_v1();

  -- END A8 SOURCE MODE CAPTURE
  -- ---- 2. the immutable accepted decision bundle -------------------------
  select * into v_bundle
    from public.weekly_source_entitlement_decision_bundles as bundle_row
   where bundle_row.decision_bundle_id=v_decision_bundle_id
     and bundle_row.bundle_revision=v_bundle_revision
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_NOT_FOUND',
        'decision_bundle_id',v_decision_bundle_id,'bundle_revision',v_bundle_revision));
  end if;
  if v_bundle.candidate_id<>v_candidate_id
     or v_bundle.decision_id<>v_decision_id
     or v_bundle.proposed_head_ids is distinct from v_head_ids
     or (v_bundle.bundle_kind='SINGLE_ROOT')<>(v_n=1)
     or (v_bundle.bundle_kind='CROSS_CONTRACT_A_B')<>(v_n=2) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_DISAGREES_WITH_REQUEST',
        'bundle_kind',v_bundle.bundle_kind,'member_count',v_n));
  end if;
  if v_bundle.state not in ('PROPOSED','COMMITTED') then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_NOT_LIVE',
        'state',v_bundle.state));
  end if;
  -- Review finding F7.  The replay check above runs BEFORE the bundle lock and
  -- matches on the digest, so a SECOND, DIFFERENT request under an already
  -- COMMITTED bundle revision used to pass every pre-write check and be stopped
  -- only by the head primary key, as a raised 23505 that WP-08b would count as
  -- a technical failure.  A committed revision has had its one publication:
  -- anything that is not that exact request is refused here, with a code.
  if v_bundle.state='COMMITTED'
     and not exists (
       select 1
         from private.weekly_source_entitlement_publication_receipts as receipt_row
        where receipt_row.decision_bundle_id=v_decision_bundle_id
          and receipt_row.bundle_revision=v_bundle_revision
          and receipt_row.request_digest=v_digest) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_BUNDLE_REVISION_ALREADY_PUBLISHED','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','THIS_BUNDLE_REVISION_HAS_ALREADY_PUBLISHED_A_DIFFERENT_REQUEST',
        'decision_bundle_id',v_decision_bundle_id,'bundle_revision',v_bundle_revision));
  end if;

  -- ---- 2a0. DEFERRED mode is not trusted on the census (review U5) ---------
  -- The core's contract is "the caller ran the census", but a frozen root must
  -- never publish (24 section 4.4; proof/32 section 7, last bullet), and the
  -- reviewer executed a DEFERRED release that published with
  -- p_census = {"result":"FROZEN"} and a p_pending_bundle_id naming no row at
  -- all.  So the one step where the answer decides whether money moves is
  -- checked here as well as by the caller.
  if v_mode='DEFERRED' then
    if coalesce(p_census->>'result','')<>'RELEASABLE' then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_CENSUS_NOT_RELEASABLE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','A_DEFERRED_RELEASE_MAY_ONLY_PUBLISH_ON_A_RELEASABLE_CENSUS',
          'census_result',coalesce(p_census->'result','null'::jsonb)));
    end if;
    select * into v_pending
      from public.weekly_source_pending_entitlement_bundles as pending_row
     where pending_row.id=p_pending_bundle_id
       and pending_row.decision_bundle_id=v_decision_bundle_id
       and pending_row.bundle_revision=v_bundle_revision
       and pending_row.candidate_id=v_candidate_id
     for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','NO_PENDING_BUNDLE_ROW_FOR_THIS_DECISION_BUNDLE_AND_REVISION',
          'pending_bundle_id',p_pending_bundle_id,
          'decision_bundle_id',v_decision_bundle_id,
          'bundle_revision',v_bundle_revision));
    end if;
    -- Decision D10.  The migration cannot bind the pending bundle's stored
    -- request to its stored digest, because such a trigger would have to call
    -- the canonical encoder, which lives in a repeatable, and migrations are
    -- applied first: a rebuild from empty would fail.  The safety therefore
    -- belongs here, where the decision to move money is actually made.  Under
    -- the lock already held, the stored request and the stored digest are
    -- verified TOGETHER, and against the request being released.
    --
    -- Round-5 ruling A1 control 3 is exactly this: "release must lock the row,
    -- recalculate the digest from the stored canonical request and refuse
    -- BEFORE EFFECTS on any mismatch".  The row is locked `for update` above,
    -- the digest is recomputed by this coordinator from the stored request, and
    -- both refusals below happen before the first write.  Control 5 adds that a
    -- tampered row is a PERMANENT integrity failure that goes DIRECTLY to
    -- manual review, so each one carries the disposition the deferred release
    -- owner must honour instead of counting a technical failure.
    if private.weekly_source_publication_request_digest_v1(
         private.weekly_source_publication_request_canonical_v1(
           v_pending.request_json,'DEFERRED',p_pending_bundle_id))
       is distinct from v_pending.request_digest then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','THE_STORED_REQUEST_DOES_NOT_MATCH_ITS_STORED_DIGEST',
          'pending_bundle_id',p_pending_bundle_id,
          'stored_digest',pg_catalog.encode(v_pending.request_digest,'hex'),
          'recomputed_digest',pg_catalog.encode(
            private.weekly_source_publication_request_digest_v1(
              private.weekly_source_publication_request_canonical_v1(
                v_pending.request_json,'DEFERRED',p_pending_bundle_id)),'hex')));
    end if;
    if v_pending.request_digest is distinct from v_digest then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','THE_REQUEST_BEING_RELEASED_IS_NOT_THE_ONE_THAT_WAS_SAVED',
          'pending_bundle_id',p_pending_bundle_id,
          'stored_digest',pg_catalog.encode(v_pending.request_digest,'hex'),
          'release_digest',pg_catalog.encode(v_digest,'hex')));
    end if;
  end if;

  -- ---- 2b. the accepted decision BINDS what is published (review U1) -------
  -- 24 section 4.5 step 2 and file 26 Gate 5 step 4 require the coordinator to
  -- revalidate "the current source revision, Contract choices, Candidate,
  -- Client, week, approval digest and the immutable identity of every moved
  -- component".  Quoting the right bundle id, decision id and head ids is not
  -- enough: the request must equal the accepted decision in every identity the
  -- bundle row carries, or a caller could publish a different root, Contract,
  -- week and amount of money under the Office decision's identity and actor.
  v_choice:=(
    select choice_element.value
      from pg_catalog.jsonb_array_elements(
             v_canonical->'financial_request'->'contract_choices') as choice_element(value)
     where (choice_element.value->>'root_ordinal')::integer=1);
  if v_member_root_ids[1] is distinct from v_bundle.source_root_timesheet_id
     or v_member_family_booking_ids[1] is distinct from v_bundle.source_root_family_booking_id
     or (v_choice->>'contract_id')::uuid is distinct from v_bundle.source_contract_id then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','SOURCE_ROOT_DISAGREES_WITH_ACCEPTED_DECISION',
        'accepted_root',v_bundle.source_root_timesheet_id,'requested_root',v_member_root_ids[1],
        'accepted_family',v_bundle.source_root_family_booking_id,
        'requested_family',v_member_family_booking_ids[1],
        'accepted_contract',v_bundle.source_contract_id,
        'requested_contract',v_choice->'contract_id'));
  end if;
  v_choice:=null;
  if v_n=2 then
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=2);
    if v_member_root_ids[2] is distinct from v_bundle.target_root_timesheet_id
       or v_member_family_booking_ids[2] is distinct from v_bundle.target_root_family_booking_id
       or (v_choice->>'contract_id')::uuid is distinct from v_bundle.target_contract_id then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','TARGET_ROOT_DISAGREES_WITH_ACCEPTED_DECISION',
          'accepted_root',v_bundle.target_root_timesheet_id,'requested_root',v_member_root_ids[2],
          'accepted_family',v_bundle.target_root_family_booking_id,
          'requested_family',v_member_family_booking_ids[2],
          'accepted_contract',v_bundle.target_contract_id,
          'requested_contract',v_choice->'contract_id'));
    end if;
    v_choice:=null;
  elsif v_bundle.target_root_timesheet_id is not null
     or v_bundle.target_root_family_booking_id is not null
     or v_bundle.target_contract_id is not null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','SINGLE_ROOT_BUNDLE_CARRIES_A_TARGET_ROOT'));
  end if;

  -- The week is the accepted decision's, and it is also each root Timesheet's
  -- own week and Contract.  One ordinary root per Candidate, Contract and week
  -- (contract section 5) only means anything if the week is checked.
  for v_i in 1..v_n loop
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=v_i);
    if (v_choice->>'week_ending_date')::date is distinct from v_bundle.week_ending_date
       or not exists (
         select 1
           from public.timesheets as root_row
          where root_row.timesheet_id=v_member_root_ids[v_i]
            and root_row.week_ending_date=v_bundle.week_ending_date
            and root_row.contract_id=(v_choice->>'contract_id')::uuid) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','WEEK_OR_CONTRACT_DISAGREES_WITH_ACCEPTED_DECISION',
          'root_ordinal',v_i,'accepted_week',v_bundle.week_ending_date,
          'requested_week',v_choice->'week_ending_date',
          'requested_contract',v_choice->'contract_id'));
    end if;
    -- The Candidate must actually OWN the root.  The reviewer published a head,
    -- a receipt and an invalidation under a second Candidate for a root it did
    -- not own: the installed invalidator's ownership rule fires only when a
    -- current TSFIN row exists, so the coordinator checks the Contract itself
    -- rather than leaving it to I-1 or to Banking Pay.
    if not exists (
      select 1
        from public.contracts as contract_row
       where contract_row.id=(v_choice->>'contract_id')::uuid
         and contract_row.candidate_id=v_candidate_id) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','CANDIDATE_DOES_NOT_OWN_THE_ROOT',
          'root_ordinal',v_i,'candidate_id',v_candidate_id,
          'contract_id',v_choice->'contract_id'));
    end if;
    v_choice:=null;
  end loop;

  -- The three approval digests the bundle row carries, recomputed here with the
  -- one canonical encoder.  These are mode-independent by construction, so the
  -- same values bind an immediate publication and a deferred release.
  v_source_generation_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'source_revision');
  v_contract_choice_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'contract_choices');
  v_before_inventory:=private.weekly_source_publication_before_inventory_v1(v_control,v_n);
  v_before_inventory_digest:=private.weekly_source_publication_request_digest_v1(v_before_inventory);
  -- The acceptance digest: the canonical request in IMMEDIATE mode with no
  -- pending bundle.  publication_mode and pending_bundle_id are digest fields
  -- (proof/32 section 9), so the digest the RECEIPT carries changes with the
  -- mode and cannot be the one stored on the accepted decision.  The bundle
  -- row's request_digest is therefore always taken in IMMEDIATE/null, which is
  -- what the proposal composer can compute at proposal time, before any pending
  -- bundle exists.  Written into interfaces\PUBLICATION_REQUEST_SHAPE.md.
  v_acceptance_digest:=private.weekly_source_publication_request_digest_v1(
    private.weekly_source_publication_request_canonical_v1(p_request,'IMMEDIATE',null::uuid));
  if v_bundle.source_revision_digest is distinct from v_source_generation_digest
     or v_bundle.contract_choice_digest is distinct from v_contract_choice_digest
     or v_bundle.before_inventory_digest is distinct from v_before_inventory_digest
     or v_bundle.request_digest is distinct from v_acceptance_digest then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','APPROVAL_DIGESTS_DISAGREE_WITH_ACCEPTED_DECISION',
        'source_revision_digest_matches',
          v_bundle.source_revision_digest is not distinct from v_source_generation_digest,
        'contract_choice_digest_matches',
          v_bundle.contract_choice_digest is not distinct from v_contract_choice_digest,
        'before_inventory_digest_matches',
          v_bundle.before_inventory_digest is not distinct from v_before_inventory_digest,
        'request_digest_matches',
          v_bundle.request_digest is not distinct from v_acceptance_digest));
  end if;

  -- ---- 2a. the current source revision (24 section 4.5 step 2; R7) --------
  -- "revalidate the current source revision".  A head built from a superseded
  -- or merely prepared final revision must never become current.
  if v_canonical#>>'{financial_request,source_revision,origin_kind}'='PROTECTED_LOCAL_DECISION_V1' then
    -- A genuine no-Final Office decision has its own closed factual producer.
    -- Do not borrow the accepted-Final APP exception or relax a Final check.
    if v_n<>1 or v_legacy_financial_owner is true
       or (select active_owner from private.bpay_next_module_control where id=1)
            is distinct from 'NEXT'
       or pg_catalog.to_regprocedure(
         'private.weekly_source_local_publication_context_v2(uuid,uuid,uuid)') is null
       or pg_catalog.to_regprocedure(
         'private.weekly_source_entitlement_proposal_request_v2(uuid,jsonb,text,uuid,bigint,uuid,uuid,jsonb,text)') is null
       or pg_catalog.to_regprocedure(
         'private.bpay_next_capture_local_source_detail_v1(uuid,uuid,bigint,uuid,uuid,uuid,jsonb)') is null then
      return pg_catalog.jsonb_build_object('ok',false,'published',false,'replayed',false,
        'code','WEEKLY_PROTECTED_LOCAL_PUBLICATION_OWNER_NOT_READY','retryable',false);
    end if;
    v_local_context:=private.weekly_source_local_publication_context_v2(
      (v_canonical#>>'{financial_request,source_revision,publication_request_id}')::uuid,
      (v_canonical#>>'{financial_request,source_revision,generation_id}')::uuid,
      v_member_root_ids[1]);
    if v_local_context is null
       or (v_local_context->>'actor_user_id')::uuid is distinct from v_bundle.decided_by_user_id
       or (v_local_context->>'agency_id')::uuid is distinct from v_bundle.agency_id then
      return pg_catalog.jsonb_build_object('ok',false,'published',false,'replayed',false,
        'code','WEEKLY_PROTECTED_LOCAL_PUBLICATION_CONTEXT_STALE','retryable',false);
    end if;
    -- The existing Source constructor verifies the real receipt, generation,
    -- complete vector, immutable before-origin and whole-components digest.
    -- Canonicalise under THIS actual immediate/deferred mode and pending UUID.
    -- Family-bound K/K+1/K+2 qualification remains solely in the Source context.
    v_local_request:=private.weekly_source_entitlement_proposal_request_v2(
      v_member_root_ids[1],v_canonical#>'{financial_request,source_revision}',
      'PROTECTED',v_decision_bundle_id,v_bundle_revision,v_head_ids[1],v_decision_id,
      v_canonical#>'{financial_request,member_entitlements,0,components}','UNCHANGED');
    if private.weekly_source_publication_request_canonical_v1(
         v_local_request,v_mode,p_pending_bundle_id) is distinct from v_canonical
       or private.weekly_source_publication_before_inventory_v1(
         v_local_request->'control',1) is distinct from v_before_inventory then
      return pg_catalog.jsonb_build_object('ok',false,'published',false,'replayed',false,
        'code','WEEKLY_PROTECTED_LOCAL_PUBLICATION_REQUEST_MISMATCH','retryable',false);
    end if;
    v_local_publication_qualified:=true;
  else
  if not exists (
    select 1
      from public.weekly_source_final_revisions as revision_row
     where revision_row.id=(v_canonical->'financial_request'->'source_revision'->>'final_revision_id')::uuid
       and revision_row.source_cycle_id=(v_canonical->'financial_request'->'source_revision'->>'source_cycle_id')::uuid
       and revision_row.revision_number=(v_canonical->'financial_request'->'source_revision'->>'revision_number')::integer
       and revision_row.state='CURRENT'
       and pg_catalog.encode(revision_row.manifest_hash,'hex')
           =(v_canonical->'financial_request'->'source_revision'->>'manifest_hash')
       and pg_catalog.encode(revision_row.policy_fingerprint,'hex')
           =(v_canonical->'financial_request'->'source_revision'->>'policy_fingerprint')
  ) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_SOURCE_REVISION_STALE','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'source_revision',v_canonical->'financial_request'->'source_revision'));
  end if;
  end if;

  -- ---- 3. member identity against the I-1 lock result ---------------------
  -- proof/32 section 4.0 integrity gate; proof/34 section 6: after first
  -- authorisation an unexpected rotation is an INTEGRITY FAILURE, never a stale
  -- rebuild.  This coordinator never rebuilds anything.
  if p_lock_result is null
     or pg_catalog.jsonb_typeof(p_lock_result)<>'object'
     or coalesce((p_lock_result->>'ok')::boolean,false) is not true
     or coalesce(p_lock_result->>'gate','')<>'GRANTED' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','LOCK_RESULT_NOT_GRANTED'));
  end if;

  for v_i in 1..v_n loop
    select family_element.value into v_family
      from pg_catalog.jsonb_array_elements(p_lock_result->'families') as family_element(value)
     where family_element.value->>'requested_timesheet_id'=v_member_root_ids[v_i]::text;
    if v_family is null
       or coalesce((v_family->>'requested_is_canonical')::boolean,false) is not true
       or coalesce((v_family->>'family_is_current')::boolean,false) is not true
       or (v_family->>'canonical_timesheet_id')::uuid is distinct from v_member_root_ids[v_i]
       or (v_family->>'canonical_version')::integer is distinct from v_member_root_versions[v_i]
       or pg_catalog.btrim(coalesce(v_family->>'family_booking_id',''))
          is distinct from pg_catalog.btrim(v_member_family_booking_ids[v_i]) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'requested_timesheet_id',v_member_root_ids[v_i],
          'lock_result_family',v_family));
    end if;
    select v_member_timesheet_ids||coalesce(
             pg_catalog.array_agg(member_element.value::uuid),array[]::uuid[])
      into v_member_timesheet_ids
      from pg_catalog.jsonb_array_elements_text(
             coalesce(v_family->'member_timesheet_ids','[]'::jsonb)) as member_element(value);

    -- WP-01a review U1: `root_family_booking_id` is free text on the head row and
    -- nothing in the schema ties it to the root's real booking_id, so the
    -- coordinator validates it itself.  The raw value must equal
    -- public.timesheets.booking_id of the canonical root BYTE FOR BYTE: the
    -- trimmed form is the lock and index key (proof/32 section 6 step 2), not an
    -- identity, and a differently cased or unrelated string would take a
    -- different advisory lock from the one protecting the uniqueness index.
    if not exists (
      select 1
        from public.timesheets as root_row
       where root_row.timesheet_id=v_member_root_ids[v_i]
         and root_row.booking_id=v_member_family_booking_ids[v_i]
         and root_row.version=v_member_root_versions[v_i]
         and root_row.is_current) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','FAMILY_BOOKING_ID_DOES_NOT_MATCH_THE_ROOT',
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'declared_family_booking_id',v_member_family_booking_ids[v_i],
          'declared_version',v_member_root_versions[v_i]));
    end if;
    v_family:=null;
  end loop;

  -- ---- 4. compare-and-swap on each member's expected current head ---------
  -- jsonb_array_elements_text turns a JSON null into a SQL NULL, which is
  -- exactly "the caller believes this root has no committed head yet".
  select pg_catalog.array_agg(expected_element.value::uuid
                              order by expected_element.ordinality)
    into v_expected_head_ids
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_control->'expected_current_head_ids','[]'::jsonb))
         with ordinality as expected_element(value,ordinality);
  if coalesce(pg_catalog.cardinality(v_expected_head_ids),0)<>v_n then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','EXPECTED_CURRENT_HEAD_IDS_NOT_ALIGNED'));
  end if;

  for v_i in 1..v_n loop
    -- One committed current head per root across both authority kinds
    -- (24 section 4.3), read under lock (H2-024).
    --
    -- WP-01a review U1: "at most one committed current head" is a partial unique
    -- index on the TRIMMED family string only, so it is not a schema guarantee
    -- for a physical root.  The coordinator therefore counts the rows itself,
    -- refuses more than one as an integrity failure rather than choosing one,
    -- and asserts that the head it found belongs to the canonical root I-1
    -- resolved.  It never falls back to stale TSFIN (27 section 5.1).
    select pg_catalog.count(*)::integer into v_rows
      from public.weekly_source_entitlement_heads as head_row
     where pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(v_member_family_booking_ids[v_i])
       and head_row.state='COMMITTED_CURRENT';
    if v_rows>1 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','MORE_THAN_ONE_COMMITTED_CURRENT_HEAD',
          'root_ordinal',v_i,'committed_current_heads',v_rows));
    end if;
    v_current_head_ids:=v_current_head_ids||(
      select head_row.id
        from public.weekly_source_entitlement_heads as head_row
       where pg_catalog.btrim(head_row.root_family_booking_id)
             =pg_catalog.btrim(v_member_family_booking_ids[v_i])
         and head_row.state='COMMITTED_CURRENT'
         for update);
    if v_current_head_ids[v_i] is not null
       and not exists (
         select 1
           from public.weekly_source_entitlement_heads as head_row
          where head_row.id=v_current_head_ids[v_i]
            and head_row.root_timesheet_id=v_member_root_ids[v_i]) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','COMMITTED_HEAD_BELONGS_TO_ANOTHER_PHYSICAL_ROOT',
          'root_ordinal',v_i,'current_head_id',v_current_head_ids[v_i]));
    end if;
    -- The MIRROR of the guard above, and the same defect class as WP-06 review
    -- finding F2: the family key found no head, but the PHYSICAL root carries
    -- one.  Since schema change S8 removed unique(root_timesheet_id) from the
    -- family relation, nothing keyed on the physical id is unique any more, so
    -- the two identities really can disagree.  Falling through here would take a
    -- TSFIN — or an unproved — before-position for a root that demonstrably HAS
    -- a committed head, understating the effective entitlement, which is exactly
    -- how a residual turns into an overpayment.  It costs one indexed lookup
    -- (weekly_source_entitlement_heads_committed_root_uq), so it is checked
    -- rather than assumed, and it is checked HERE so it covers the I-7 branch
    -- and the no-I-7 branch alike.
    if v_current_head_ids[v_i] is null
       and exists (
         select 1
           from public.weekly_source_entitlement_heads as head_row
          where head_row.root_timesheet_id=v_member_root_ids[v_i]
            and head_row.state='COMMITTED_CURRENT') then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','COMMITTED_HEAD_EXISTS_FOR_THE_PHYSICAL_ROOT_BUT_NOT_THE_DECLARED_FAMILY',
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'declared_family_booking_id',v_member_family_booking_ids[v_i],
          'physical_root_head_id',(
            select head_row.id
              from public.weekly_source_entitlement_heads as head_row
             where head_row.root_timesheet_id=v_member_root_ids[v_i]
               and head_row.state='COMMITTED_CURRENT')));
    end if;
    if v_current_head_ids[v_i] is distinct from v_expected_head_ids[v_i] then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_HEAD_CAS_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,
          'expected_current_head_id',v_expected_head_ids[v_i],
          'actual_current_head_id',v_current_head_ids[v_i]));
    end if;
    select coalesce(pg_catalog.max(head_row.head_revision),0)+1
      into v_head_revision
      from public.weekly_source_entitlement_heads as head_row
     where pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(v_member_family_booking_ids[v_i]);
    v_head_revisions:=v_head_revisions||v_head_revision;
    v_prior_head_ids:=v_prior_head_ids||(
      select head_row.id
        from public.weekly_source_entitlement_heads as head_row
       where pg_catalog.btrim(head_row.root_family_booking_id)
             =pg_catalog.btrim(v_member_family_booking_ids[v_i])
       order by head_row.head_revision desc
       limit 1);
  end loop;

  -- Same saved0105 certificate, before retained own-B content admission.
  v_destination_reprice:=private.weekly_source_destination_reprice_verify_v1(v_canonical,v_control);
  -- ---- 5. the complete post-decision head proofs (H2-024) -----------------
  -- Bind both exact before positions while the existing Candidate/family
  -- locks still protect them. The later detail helper never follows a mutable
  -- Banking work pointer or reselects an upload. Non-NEXT paths are unchanged.
  if v_n=2 and pg_catalog.to_regclass('private.bpay_next_module_control') is not null then
    select m.active_owner='NEXT' into v_next_pair
      from private.bpay_next_module_control m where m.id=1 for share;
  end if;
  if v_next_pair is true then
    perform a.id from public.weekly_source_root_authorisations a
      where a.root_timesheet_id=any(v_member_root_ids)
        and a.withdrawn_at_utc is null
      order by a.root_timesheet_id,a.id for update;
  end if;
  for v_i in 1..v_n loop
    v_before_auth:=null;
    v_before_financial:=null;
    if v_next_pair is true then
      select pg_catalog.count(*)::integer into v_before_auth_count
        from public.weekly_source_root_authorisations a
        where a.root_timesheet_id=v_member_root_ids[v_i]
          and a.withdrawn_at_utc is null;
      if v_before_auth_count>1 then
        raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_BEFORE_AUTH_NOT_EXACT';
      end if;
      if v_before_auth_count=1 then
        select a.* into strict v_before_auth
          from public.weekly_source_root_authorisations a
          where a.root_timesheet_id=v_member_root_ids[v_i]
            and a.withdrawn_at_utc is null;
        if v_before_auth.family_booking_id is distinct from v_member_family_booking_ids[v_i]
           or v_before_auth.timesheet_version is distinct from v_member_root_versions[v_i]
           or v_before_auth.current_entitlement_head_id is distinct from v_current_head_ids[v_i] then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_BEFORE_AUTH_NOT_EXACT';
        end if;
      end if;
    end if;
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    select coalesce(pg_catalog.array_agg(
             (component_element.value->>'component_id')::uuid
             order by (component_element.value->>'component_ordinal')::integer),
             array[]::uuid[])
      into v_component_ids
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value);

    select coalesce(pg_catalog.array_agg(before_element.value::uuid),array[]::uuid[])
      into v_before_ids
      from pg_catalog.jsonb_array_elements_text(
             coalesce((select position_element.value->'component_ids'
                         from pg_catalog.jsonb_array_elements(
                                coalesce(v_control->'before_positions','[]'::jsonb)) as position_element(value)
                        where (position_element.value->>'root_ordinal')::integer=v_i),
                      'null'::jsonb)) as before_element(value);
    if (select position_element.value
          from pg_catalog.jsonb_array_elements(
                 coalesce(v_control->'before_positions','[]'::jsonb)) as position_element(value)
         where (position_element.value->>'root_ordinal')::integer=v_i) is null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','BEFORE_POSITION_MISSING','root_ordinal',v_i));
    end if;

    -- A head may never contain an adjustment, whatever key it arrives under
    -- (24 section 5; WB-007, WB-013; review U3 case H6c).  component_kind,
    -- economic_key_type and origin are free text on the relation, so the
    -- coordinator allowlists the kind and refuses the adjustment vocabulary
    -- outright rather than trusting the absence of an `adjustment_id` key.
    v_offending:=(
      select component_element.value
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where (component_element.value->>'component_kind') not in
               ('WORKED_TIME','ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE')
          or component_element.value->>'component_kind' ~* 'ADJUST|ADVANCE'
          or component_element.value->>'economic_key_type' ~* 'ADJUST|ADVANCE'
          or component_element.value->>'origin' ~* 'ADJUST|ADVANCE'
       limit 1);
    if v_offending is not null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_COMPONENT_KIND_FORBIDDEN','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'component',v_offending,
          'permitted_kinds',pg_catalog.jsonb_build_array(
            'WORKED_TIME','ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE')));
    end if;
    v_offending:=null;

    -- H2-024: "each before-position is read from the single committed effective
    -- authority under lock".  Three cases, and only the third is ever accepted
    -- without a server-side read (review U3).
    if v_current_head_ids[v_i] is not null then
      if v_next_pair is true then
        if v_before_auth.id is null then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_BEFORE_AUTH_NOT_EXACT';
        end if;
        v_before_source_event_ids:=pg_catalog.array_append(
          v_before_source_event_ids,v_current_head_ids[v_i]);
        v_before_financial_snapshot_ids:=pg_catalog.array_append(
          v_before_financial_snapshot_ids,null::uuid);
      end if;
      -- (1) A committed head exists: the declared position must equal its
      -- component set EXACTLY, and every RETAINED component must be
      -- byte-identical - the committed row stores component_sha256, so
      -- re-pricing a component that is merely "kept by id" is detectable and
      -- is refused (review U3 cases H10 and H4c).
      if exists (
        select 1
          from (select component_row.component_id
                  from public.weekly_source_entitlement_head_components as component_row
                 where component_row.head_id=v_current_head_ids[v_i]
                except
                select pg_catalog.unnest(v_before_ids)) as missing_from_declared
        union all
        select 1
          from (select pg_catalog.unnest(v_before_ids)
                except
                select component_row.component_id
                  from public.weekly_source_entitlement_head_components as component_row
                 where component_row.head_id=v_current_head_ids[v_i]) as extra_in_declared
      ) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_MISMATCH','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'current_head_id',v_current_head_ids[v_i]));
      end if;
      -- `component_sha256` is a CONTENT identity and deliberately excludes
      -- `component_ordinal`: the ordinal is the component's position inside a
      -- head, and a component that is retained while another moves out from in
      -- front of it legitimately changes position.  Position is still covered,
      -- by `inventory_digest` (the ordered ordinal/id pairs) and by
      -- `entitlement_digest` (the content hashes in ordinal order).
      v_offending:=(
        select pg_catalog.jsonb_build_object(
                 'component_id',component_element.value->'component_id',
                 'committed_sha256',pg_catalog.encode(committed_row.component_sha256,'hex'),
                 'requested_sha256',pg_catalog.encode(
                   private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),'hex'))
          from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
          join public.weekly_source_entitlement_head_components as committed_row
            on committed_row.head_id=v_current_head_ids[v_i]
           and committed_row.component_id=(component_element.value->>'component_id')::uuid
         where committed_row.component_sha256
               is distinct from private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value))
           and not (v_n=2 and v_i=2 and exists(select 1
             from pg_catalog.jsonb_array_elements(coalesce(v_destination_reprice->'components','[]'::jsonb)) witness(value)
             where witness.value->>'component_id'=component_element.value->>'component_id'
               and witness.value->>'before_root_ordinal'='2'
               and witness.value->>'before_root_timesheet_id'=v_member_root_ids[2]::text
               and witness.value->>'before_head_id'=committed_row.head_id::text
               and witness.value->>'before_component_sha256'=pg_catalog.encode(committed_row.component_sha256,'hex')
               and witness.value->'after_content' is not distinct from
                 private.weekly_source_publication_component_content_v1(component_element.value)))
         limit 1);
      v_accepted_app:=null;
      if v_offending is not null and v_mode='IMMEDIATE' and v_n=1 and v_i=1
         and v_canonical#>>'{financial_request,source_revision,origin_kind}'='CURRENT_FINAL_SOURCE_V1'
         and v_canonical#>>'{financial_request,source_revision,accepted_action_id}' is not null
         and pg_catalog.to_regprocedure(
           'private.weekly_source_accepted_publication_action_verify_v1(uuid,uuid,bigint,bytea,uuid)') is not null then
        -- Only the actual accepted APP witness permits a same-component
        -- replacement. The complete locked before-position remains checked.
        v_accepted_app:=private.weekly_source_accepted_publication_action_verify_v1(
          (v_canonical#>>'{financial_request,source_revision,accepted_action_id}')::uuid,
          v_decision_bundle_id,v_bundle_revision,v_digest,v_member_root_ids[1]);
      end if;
      if v_offending is not null and not (v_local_publication_qualified is true or (
           (v_accepted_app->'ok') is not distinct from 'true'::jsonb
           and (v_accepted_app->>'code') is not distinct from 'OK'
           and (v_accepted_app->>'action_id') is not distinct from
             v_canonical#>>'{financial_request,source_revision,accepted_action_id}'
           and (v_accepted_app->>'accepted_canonical_sha256') is not distinct from
             pg_catalog.encode(v_digest,'hex'))) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_RETAINED_COMPONENT_CHANGED','retryable',false,
          'detail',pg_catalog.jsonb_build_object('root_ordinal',v_i,'component',v_offending));
      end if;
      v_offending:=null;
      -- WP-06c review F1: member 1 is the SOURCE of a cross-Contract move, so
      -- its committed head is the authority for what every MOVED component
      -- actually held.  The content hashes are taken here, under the same lock
      -- and from the same rows the retained check just used, and are compared
      -- against the destination side after the set proofs.
      if v_i=1 then
        select coalesce(pg_catalog.jsonb_object_agg(
                 committed_row.component_id::text,
                 pg_catalog.encode(committed_row.component_sha256,'hex')),'{}'::jsonb)
          into v_source_component_hashes
          from public.weekly_source_entitlement_head_components as committed_row
         where committed_row.head_id=v_current_head_ids[v_i];
      end if;
      v_before_source:=v_before_source||'HEAD'::text;

    elsif pg_catalog.to_regprocedure(
            'private.weekly_source_effective_inventory_v1(uuid)') is not null then
      if v_next_pair is true then
        -- Name and lock the actual current snapshot BEFORE the one I7 read.
        -- A genuinely blank new B may have no snapshot; no other missing
        -- before position is treated as an approved zero.
        begin
          select f.* into strict v_before_financial
            from public.timesheets_financials f
            where f.timesheet_id=v_member_root_ids[v_i] and f.is_current=true
            for share;
        exception when no_data_found then
          v_before_financial:=null;
        end;
      end if;
      -- (2) No head yet, but interface I-7 exists (decision D9, built by WP-06):
      -- the before-position is derived SERVER-SIDE from the single committed
      -- effective authority - the ordinary financial snapshot - under the same
      -- locks, and the declared position must equal it.
      v_effective:=private.weekly_source_effective_inventory_v1(v_member_root_ids[v_i]);
      if coalesce(pg_catalog.jsonb_typeof(v_effective),'')<>'object' then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_EFFECTIVE_INVENTORY_INVALID'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_EFFECTIVE_INVENTORY_INVALID',
                  'root_ordinal',v_i,'result',v_effective)::text;
      end if;
      -- I-7 answers `ok:false` with an EMPTY components array when it cannot
      -- resolve the root.  Reading that as "the root holds nothing" would turn
      -- an integrity failure into a silent certified-zero publication, so the
      -- refusal is honoured before the sets are compared at all.
      if coalesce((v_effective->>'ok')::boolean,false) is not true then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','INTERFACE_I7_REFUSED_THE_ROOT',
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'effective_inventory',v_effective));
      end if;
      -- I-7 is reached ONLY when the family key above found no committed head,
      -- so the only authority it can legitimately report here is the ordinary
      -- financial snapshot.  If it reports a HEAD, the two keyings disagree
      -- about the same root — the shape of WP-06 review finding F2, in whichever
      -- direction the disagreement runs — and the coordinator must not pick a
      -- winner between them.  It refuses, cheaply, on a field it already holds.
      if v_effective->>'authority' is distinct from 'TSFIN' then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','INTERFACE_I7_REPORTS_AN_AUTHORITY_THE_FAMILY_KEY_DOES_NOT',
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'declared_family_booking_id',v_member_family_booking_ids[v_i],
            'i7_authority',v_effective->'authority','i7_head_id',v_effective->'head_id'));
      end if;
      if v_next_pair is true then
        if v_before_financial.id is not null and (
             v_before_financial.timesheet_version is distinct from v_member_root_versions[v_i]
             or v_before_financial.is_stale is distinct from false
             or not exists(select 1 from public.contracts c
               join public.timesheets t on t.contract_id=c.id
               where t.timesheet_id=v_member_root_ids[v_i]
                 and c.candidate_id=v_candidate_id
                 and v_before_financial.candidate_id=c.candidate_id
                 and v_before_financial.client_id=c.client_id)) then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_BEFORE_FINANCIAL_NOT_EXACT';
        end if;
        if v_before_auth.id is not null then
          if v_before_financial.id is null
             or v_before_financial.authorised_at_utc is null
             or v_effective#>'{approval_basis,coverage_complete}' is distinct from 'true'::jsonb
             or v_effective#>>'{approval_basis,origin,kind}' is distinct from 'INITIAL_AUTHORISED_TSFIN_V1'
             or v_effective#>>'{approval_basis,origin,root_authorisation_id}' is distinct from v_before_auth.id::text
             or v_effective#>>'{approval_basis,origin,financial_snapshot_id}' is distinct from v_before_financial.id::text
             or v_effective#>>'{approval_basis,scope,root_timesheet_id}' is distinct from v_member_root_ids[v_i]::text
             or v_effective#>>'{approval_basis,scope,family_booking_id}' is distinct from v_member_family_booking_ids[v_i]
             or v_effective#>>'{approval_basis,scope,root_version}' is distinct from v_member_root_versions[v_i]::text then
            raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_BEFORE_FINANCIAL_NOT_EXACT';
          end if;
        elsif v_i<>2
           or pg_catalog.jsonb_typeof(v_control->'target_root_authorisation') is distinct from 'object'
           or v_control#>>'{target_root_authorisation,timesheet_id}' is distinct from v_member_root_ids[v_i]::text
           or (v_before_financial.id is null
             and pg_catalog.jsonb_array_length(v_effective->'components')<>0) then
          raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_BEFORE_FINANCIAL_NOT_EXACT';
        end if;
        v_before_source_event_ids:=pg_catalog.array_append(v_before_source_event_ids,v_before_auth.id);
        v_before_financial_snapshot_ids:=pg_catalog.array_append(v_before_financial_snapshot_ids,v_before_financial.id);
      end if;
      if exists (
        select 1
          from (select (effective_element.value->>'component_id')::uuid as component_id
                  from pg_catalog.jsonb_array_elements(
                         coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)
                except
                select pg_catalog.unnest(v_before_ids)) as missing_from_declared
        union all
        select 1
          from (select pg_catalog.unnest(v_before_ids)
                except
                select (effective_element.value->>'component_id')::uuid
                  from pg_catalog.jsonb_array_elements(
                         coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)) as extra_in_declared
      ) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_MISMATCH','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'authority',v_effective->'authority',
            'reason','DECLARED_POSITION_DIFFERS_FROM_THE_EFFECTIVE_INVENTORY'));
      end if;
      -- I-7 also carries each component's content hash, so a component RETAINED
      -- from a head-less root gets the same byte-identity guarantee as one
      -- retained from a committed head (review finding U3(a), extended).
      v_offending:=(
        select pg_catalog.jsonb_build_object(
                 'component_id',component_element.value->'component_id',
                 'effective_sha256',effective_element.value->'component_sha256',
                 'requested_sha256',pg_catalog.encode(
                   private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(
                       component_element.value)),'hex'))
          from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
          join pg_catalog.jsonb_array_elements(
                 coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)
            on effective_element.value->>'component_id'=component_element.value->>'component_id'
         where effective_element.value->>'component_sha256'
               is distinct from pg_catalog.encode(
                 private.weekly_source_publication_request_digest_v1(
                   private.weekly_source_publication_component_content_v1(
                     component_element.value)),'hex')
         limit 1);
      v_accepted_app:=null;
      if v_offending is not null and v_mode='IMMEDIATE' and v_n=1 and v_i=1
         and v_canonical#>>'{financial_request,source_revision,origin_kind}'='CURRENT_FINAL_SOURCE_V1'
         and v_canonical#>>'{financial_request,source_revision,accepted_action_id}' is not null
         and pg_catalog.to_regprocedure(
           'private.weekly_source_accepted_publication_action_verify_v1(uuid,uuid,bigint,bytea,uuid)') is not null then
        -- The headless TSFIN/I7 path has the same exact accepted authority;
        -- no KEEP, move, deferred or Source-local decision borrows it.
        v_accepted_app:=private.weekly_source_accepted_publication_action_verify_v1(
          (v_canonical#>>'{financial_request,source_revision,accepted_action_id}')::uuid,
          v_decision_bundle_id,v_bundle_revision,v_digest,v_member_root_ids[1]);
      end if;
      if v_offending is not null and not (v_local_publication_qualified is true or (
           (v_accepted_app->'ok') is not distinct from 'true'::jsonb
           and (v_accepted_app->>'code') is not distinct from 'OK'
           and (v_accepted_app->>'action_id') is not distinct from
             v_canonical#>>'{financial_request,source_revision,accepted_action_id}'
           and (v_accepted_app->>'accepted_canonical_sha256') is not distinct from
             pg_catalog.encode(v_digest,'hex'))) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_RETAINED_COMPONENT_CHANGED','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'authority',v_effective->'authority',
            'component',v_offending));
      end if;
      v_offending:=null;
      -- WP-06c review F1, the head-less source: I-7 carries each component's
      -- own content hash, computed through this file's canonicaliser, content
      -- projection and encoder, so it is directly comparable with a committed
      -- head row's `component_sha256` and with the destination side.
      if v_i=1 then
        select coalesce(pg_catalog.jsonb_object_agg(
                 effective_element.value->>'component_id',
                 effective_element.value->'component_sha256'),'{}'::jsonb)
          into v_source_component_hashes
          from pg_catalog.jsonb_array_elements(
                 coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value);
      end if;
      v_before_source:=v_before_source||'I7'::text;

    else
      -- (3) No head and no I-7.  The declared position cannot be proved, so it
      -- is never recorded as if it were.  An A-to-B bundle is REFUSED rather
      -- than published on an unverified before-position, because that is where
      -- "minus only the moved components" and "keeps every existing component"
      -- would otherwise rest on the caller's word (review U3 case G1-a).
      if v_n=2 then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_UNPROVABLE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'reason','NO_COMMITTED_HEAD_AND_INTERFACE_I7_IS_NOT_INSTALLED',
            'required_owner','private.weekly_source_effective_inventory_v1(uuid)'));
      end if;
      v_before_source:=v_before_source||'DECLARED_UNPROVED'::text;
    end if;

    if v_i=1 then
      v_after_1:=v_component_ids; v_before_1:=v_before_ids;
    else
      v_after_2:=v_component_ids; v_before_2:=v_before_ids;
    end if;
    v_entitlement:=null;
  end loop;

  select coalesce(pg_catalog.array_agg(moved_element.value::uuid),array[]::uuid[])
    into v_moved
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_control->'moved_component_ids','[]'::jsonb)) as moved_element(value);

  if v_n=1 then
    if pg_catalog.cardinality(v_moved)>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','MOVED_SET_ON_SINGLE_ROOT_BUNDLE'));
    end if;
  else
    -- "an already-authorised B keeps EVERY existing component" (24 section 4.5
    -- step 3).  This is tested FIRST so that a B which loses one gets the exact
    -- code the interface documents.  Placed after the combined set proof it was
    -- unreachable, because `B-after = B-before union moved` already implies
    -- `B-before is a subset of B-after` (review finding F12).
    if pg_catalog.cardinality(
         private.weekly_source_uuid_set_difference_v1(v_before_2,v_after_2))>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_TARGET_COMPONENT_DROPPED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'dropped',pg_catalog.to_jsonb(
            private.weekly_source_uuid_set_difference_v1(v_before_2,v_after_2))));
    end if;
    -- 24 section 4.5 step 3 and H2-024, proved in the same transaction.
    if pg_catalog.cardinality(v_moved)=0
       or not private.weekly_source_uuid_array_is_distinct_v1(v_moved)
       or private.weekly_source_uuid_set_equals_v1(
            v_before_1,private.weekly_source_uuid_set_union_v1(v_after_1,v_moved)) is not true
       or pg_catalog.cardinality(private.weekly_source_uuid_set_intersect_v1(v_after_1,v_moved))>0
       or pg_catalog.cardinality(private.weekly_source_uuid_set_intersect_v1(v_before_2,v_moved))>0
       or private.weekly_source_uuid_set_equals_v1(
            v_after_2,private.weekly_source_uuid_set_union_v1(v_before_2,v_moved)) is not true then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'a_before',pg_catalog.to_jsonb(v_before_1),'a_after',pg_catalog.to_jsonb(v_after_1),
          'b_before',pg_catalog.to_jsonb(v_before_2),'b_after',pg_catalog.to_jsonb(v_after_2),
          'moved',pg_catalog.to_jsonb(v_moved)));
    end if;

    -- Round-5 ruling, Part E, "Partial Contract-to-Contract move":
    --
    --   "Not in scope for this release.  The supported operation is the
    --    whole-entitlement move.  A requested partial move must take the named
    --    fail-closed path and explain that partial movement is unsupported; it
    --    must not approximate the move."
    --
    -- THE DEFINITION IS THE WHOLE OF THE RULE.  A move is WHOLE when the source
    -- member retains nothing after it, and PARTIAL otherwise.  Three statements
    -- of that are available here and they are the SAME statement, because the
    -- set proofs immediately above have already established
    -- `A_after = A_before \ moved`:
    --
    --   (i)   A-after is empty                     -> cardinality(v_after_1)=0
    --   (ii)  every component of A-before moved    -> moved = A_before
    --   (iii) member 1 is certified zero           -> the declared flag, which
    --         the coordinator re-checks against `component_count` below and
    --         which the head relation's own CHECK enforces
    --
    -- (i) is the one tested, because it is read from what the request actually
    -- carries rather than from a flag the caller sets.  (ii) is asserted
    -- alongside it: if the two ever disagreed, the set proofs above would have
    -- been wrong, so the disagreement is itself refused rather than resolved.
    --
    -- This is a SCOPE gate, so it is tested before the content proof below: a
    -- partial move is refused for being partial, in plain English, not for a
    -- hash mismatch it may not even have.  It is a returned refusal before the
    -- first write, exactly like every other check in this section.
    if pg_catalog.cardinality(v_after_1)>0
       or private.weekly_source_uuid_set_equals_v1(v_moved,v_before_1) is not true then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PARTIAL_MOVE_UNSUPPORTED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','ONLY_A_WHOLE_ENTITLEMENT_MOVE_IS_SUPPORTED_IN_THIS_RELEASE',
          'message','This bundle moves only part of the entitlement from one Contract '
                  ||'to the other and leaves the rest behind. Moving part of an '
                  ||'entitlement is not supported in this release: a Contract-to-Contract '
                  ||'amendment must move the whole entitlement, so that the old Contract '
                  ||'is left holding nothing. Nothing has been published. Either move '
                  ||'every component of the old Contract''s entitlement, or leave the '
                  ||'entitlement where it is.',
          'definition','A move is WHOLE when the source root retains nothing after it.',
          'a_before',pg_catalog.to_jsonb(v_before_1),
          'a_after',pg_catalog.to_jsonb(v_after_1),
          'a_after_component_count',pg_catalog.cardinality(v_after_1),
          'moved',pg_catalog.to_jsonb(v_moved),
          'moved_is_the_whole_source_position',
            private.weekly_source_uuid_set_equals_v1(v_moved,v_before_1)));
    end if;

    -- WP-06c review finding F1 (HIGH).  Everything above proves the move by
    -- IDENTITY.  A moved component's CONTENT was never compared with anything:
    -- it is absent from A-after and from B-before, so neither retained-component
    -- check above joins it, and a request composed outside the builder could
    -- re-price a shift on its way from A to B and be published with a receipt
    -- (executed: 85.50 -> 850.50 and 4.25 -> 40 hours).  The coordinator is the
    -- last gate before an entitlement is published, so it verifies rather than
    -- trusts: every moved component must still equal, byte for byte, what the
    -- SOURCE authority actually held - A's committed head row's
    -- `component_sha256` where A has a head, else interface I-7's own content
    -- hash for the same component.  `24 section 4.5` step 3 is "B-after is B's
    -- previously effective complete entitlement plus only those component(s)" -
    -- THOSE components, not components with those identities.
    --
    -- The comparison uses the same content projection as the retained checks, so
    -- `component_ordinal`, `movement_id` and `movement_group_id` - the three
    -- things a move legitimately changes - are excluded, and nothing else is.
    -- A moved component the source authority does not carry at all has a null
    -- hash here and is refused by the same test (`is distinct from`).
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=2);
    select pg_catalog.count(*)::integer into v_moved_found
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
     where (component_element.value->>'component_id')::uuid=any(v_moved);
    if v_moved_found<>pg_catalog.cardinality(v_moved) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','THE_DESTINATION_DOES_NOT_CARRY_EACH_MOVED_COMPONENT_EXACTLY_ONCE',
          'moved',pg_catalog.to_jsonb(v_moved),
          'moved_components_in_b_after',v_moved_found));
    end if;
    v_offending:=(
      select pg_catalog.jsonb_build_object(
               'component_id',component_element.value->'component_id',
               'source_authority',v_before_source[1],
               'source_sha256',pg_catalog.to_jsonb(
                 v_source_component_hashes->>(component_element.value->>'component_id')),
               'requested_sha256',pg_catalog.encode(
                 private.weekly_source_publication_request_digest_v1(
                   private.weekly_source_publication_component_content_v1(
                     component_element.value)),'hex'))
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where (component_element.value->>'component_id')::uuid=any(v_moved)
         and (v_source_component_hashes->>(component_element.value->>'component_id'))
             is distinct from pg_catalog.encode(
               private.weekly_source_publication_request_digest_v1(
                 private.weekly_source_publication_component_content_v1(
                   component_element.value)),'hex')
         and not exists (select 1 from pg_catalog.jsonb_array_elements(
           coalesce(v_destination_reprice->'components','[]'::jsonb)) witness(value)
           where witness.value->>'component_id'=component_element.value->>'component_id'
             and pg_catalog.encode(private.weekly_source_publication_request_digest_v1(
               private.weekly_source_publication_component_content_v1(witness.value->'before_component')),'hex')
                 is not distinct from v_source_component_hashes->>(component_element.value->>'component_id')
             and witness.value->'after_content' is not distinct from
               private.weekly_source_publication_component_content_v1(component_element.value))
       limit 1);
    if v_offending is not null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVED_COMPONENT_CHANGED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',2,'component',v_offending));
    end if;
    v_offending:=null;
    v_entitlement:=null;
  end if;

  -- Movement identity: every moved component carries movement_id in its
  -- destination head and no retained component carries one.
  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    if exists (
      select 1
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where ((component_element.value->>'component_id')::uuid=any(v_moved)
              and v_i=2
              and component_element.value->'movement_id'='null'::jsonb)
          or (not ((component_element.value->>'component_id')::uuid=any(v_moved) and v_i=2)
              and component_element.value->'movement_id'<>'null'::jsonb)
    ) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVEMENT_IDENTITY_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('root_ordinal',v_i));
    end if;
    v_entitlement:=null;
  end loop;

  -- ---- 6. the target root's authorisation state ---------------------------
  v_target_auth:=case when pg_catalog.jsonb_typeof(coalesce(v_control->'target_root_authorisation','null'::jsonb))='object'
                      then v_control->'target_root_authorisation' end;
  v_review:=case when pg_catalog.jsonb_typeof(coalesce(v_control->'whole_root_office_review','null'::jsonb))='object'
                 then v_control->'whole_root_office_review' end;

  for v_i in 1..v_n loop
    -- Decision D8: the authorisation record is per ROOT and lives in
    -- public.weekly_source_root_authorisations, keyed on the physical
    -- root_timesheet_id, with at most one live generation per root.  It is no
    -- longer the per-source-row lineage binding.
    select pg_catalog.count(*)::integer into v_live_generations
      from public.weekly_source_root_authorisations as authorisation_row
     where authorisation_row.root_timesheet_id=v_member_root_ids[v_i]
       and authorisation_row.withdrawn_at_utc is null;

    -- WP-07 review finding F2, answered from THIS side of the seam.  The
    -- authorisation record is keyed on the PHYSICAL root_timesheet_id, and since
    -- schema change S8 removed the physical uniqueness a single family can hold
    -- several of them.  A test that counts only the canonical root's own
    -- generations lets a ROTATED family whose NON-CANONICAL member is already
    -- authorised be authorised a second time; the root is then payable and
    -- carries two live generations, which every withdrawal path treats as an
    -- impossible state, so it can never be withdrawn again.
    --
    -- The "is it already authorised?" test is therefore over the whole FAMILY:
    -- every member Timesheet the lock result carries for this root, and the
    -- family booking id the authorisation row itself records.  The coordinator
    -- does not rely on interface I-6 having been widened to match — that is
    -- precisely the assumption this finding punished.
    select coalesce(pg_catalog.array_agg(member_element.value::uuid),array[]::uuid[])
      into v_family_members
      from pg_catalog.jsonb_array_elements(p_lock_result->'families') as family_element(value)
     cross join pg_catalog.jsonb_array_elements_text(
                  coalesce(family_element.value->'member_timesheet_ids','[]'::jsonb))
                as member_element(value)
     where family_element.value->>'requested_timesheet_id'=v_member_root_ids[v_i]::text;
    select pg_catalog.count(*)::integer into v_family_live_generations
      from public.weekly_source_root_authorisations as authorisation_row
     where authorisation_row.withdrawn_at_utc is null
       and (authorisation_row.root_timesheet_id=v_member_root_ids[v_i]
            or authorisation_row.root_timesheet_id=any(v_family_members)
            or pg_catalog.btrim(authorisation_row.family_booking_id)
               =pg_catalog.btrim(v_member_family_booking_ids[v_i]));

    if v_i=2 and v_target_auth is not null then
      -- 24 section 4.5 step 4: only a genuinely new, never-authorised B root is
      -- created and authorised here, and it is never authorised silently.
      if v_family_live_generations>0 then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ALREADY_AUTHORISED','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'live_generations',v_family_live_generations,
            'live_generations_on_this_physical_root',v_live_generations,
            'root_timesheet_id',v_member_root_ids[v_i],
            'family_booking_id',v_member_family_booking_ids[v_i],
            'family_member_timesheet_ids',pg_catalog.to_jsonb(v_family_members)));
      end if;
      if (v_target_auth->>'timesheet_id')::uuid is distinct from v_member_root_ids[2] then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','TARGET_AUTHORISATION_TIMESHEET_MISMATCH'));
      end if;

      -- Review U2.  "Unknown to Weekly Source" is NOT the same as "blank": a B
      -- Timesheet that already existed, was never touched by Weekly Source and
      -- carries its own unrelated shifts satisfied the old test and was
      -- authorised silently, which 24 section 4.5 step 4, file 26 Gate 5 step 6,
      -- 27 section 8 step 6 and H2-024 all forbid.  B is now treated as
      -- genuinely new only when it is provably blank as well as unknown.
      v_blank:=private.weekly_source_publication_target_root_blank_v1(
        v_member_root_ids[2],v_member_family_booking_ids[2]);
      if coalesce((v_blank->>'blank')::boolean,false) is not true then
        -- The whole-root Office review is the only way past this, and it is a
        -- real control or it is nothing: a genuine boolean true, an existing
        -- reviewer, a time, bound to the accepted decision, and PERSISTED on
        -- the accepted decision so the act can be shown afterwards.  The three
        -- identity columns now exist on the bundle relation, so the check is
        -- the real one: the ACCEPTED DECISION must carry the review, and the
        -- request must quote exactly what it carries.
        if v_bundle.whole_root_review_required is not true
           or v_bundle.whole_root_reviewed_by_user_id is null
           or v_bundle.whole_root_reviewed_at_utc is null then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','THE_ACCEPTED_DECISION_CARRIES_NO_WHOLE_ROOT_OFFICE_REVIEW',
              'blank_check',v_blank,
              'decision_bundle_id',v_decision_bundle_id,
              'bundle_revision',v_bundle_revision));
        end if;
        -- The request's own review object: a real boolean, a real reviewer, a
        -- real time, and bound to this accepted decision.
        if v_review is null
           or pg_catalog.jsonb_typeof(v_review->'reviewed')<>'boolean'
           or (v_review->'reviewed')::boolean is not true
           or (v_review->>'reviewed_by_user_id') is null
           or (v_review->>'reviewed_at_utc') is null
           or (v_review->>'decision_id')::uuid is distinct from v_decision_id then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','WHOLE_ROOT_OFFICE_REVIEW_MISSING_OR_MALFORMED',
              'blank_check',v_blank,'review',v_review));
        end if;
        -- And it must be the review the ACCEPTED DECISION carries, not one the
        -- caller invented for this request.  The reviewer's existence is the
        -- bundle column's own foreign key, so it is proved by the row, not
        -- re-checked here.
        if (v_review->>'reviewed_by_user_id')::uuid
             is distinct from v_bundle.whole_root_reviewed_by_user_id
           or (v_review->>'reviewed_at_utc')::timestamptz
                is distinct from v_bundle.whole_root_reviewed_at_utc then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','REVIEW_IS_NOT_THE_ONE_ON_THE_ACCEPTED_DECISION',
              'accepted_reviewer',v_bundle.whole_root_reviewed_by_user_id,
              'requested_reviewer',v_review->'reviewed_by_user_id'));
        end if;
      end if;
    elsif v_live_generations=0 then
      -- A head over a root Weekly Source has not authorised would never reach
      -- payroll, so it is refused rather than written (decision D8: the live
      -- authorisation row is the test).
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_TARGET_NOT_AUTHORISED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'family_booking_id',v_member_family_booking_ids[v_i]));
    end if;
  end loop;

  -- =========================================================================
  -- Everything from here writes.  Every failure below RAISES and rolls the
  -- whole transaction back: no head, pointer, invalidation, dirty job, B
  -- authorisation or receipt may survive (R11; 26 Gate 5 pass condition).
  -- =========================================================================

  -- Observe exact writes in this invocation, not differences against global history.
  v_observation_frame:=private.weekly_source_observation_begin_v1();

  -- ---- 7. stage every member head and its complete component inventory ----
  v_source_generation_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'source_revision');

  -- BEGIN A8 SOURCE HEAD INVENTORY BUILD TIMING
  -- A staged parent necessarily precedes its complete component INSERT. Defer
  -- ONLY the parent's inventory check across this genuine multi-row build;
  -- component checks and cache invalidation remain unchanged. Receipt timing
  -- is separately checked around the actual activation/receipt construction.
  set constraints public.weekly_source_entitlement_head_inventory_assert deferred;
  -- END A8 SOURCE HEAD INVENTORY BUILD TIMING
  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=v_i);

    select coalesce(pg_catalog.jsonb_agg(
             pg_catalog.jsonb_build_object(
               'component_ordinal',component_element.value->'component_ordinal',
               'component_id',component_element.value->'component_id')
             order by (component_element.value->>'component_ordinal')::integer),'[]'::jsonb),
           coalesce(pg_catalog.jsonb_agg(
             pg_catalog.to_jsonb(pg_catalog.encode(
               private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),'hex'))
             order by (component_element.value->>'component_ordinal')::integer),'[]'::jsonb)
      into v_inventory_pairs,v_component_hashes
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value);

    insert into public.weekly_source_entitlement_heads(
      id,authority_kind,agency_id,candidate_id,contract_id,week_ending_date,
      root_timesheet_id,root_family_booking_id,root_timesheet_version,head_revision,
      prior_head_id,state,certified_zero,component_count,entitlement_digest,inventory_digest,
      source_generation_digest,source_origin_json,decision_bundle_id,bundle_revision,decision_id,
      decided_by_user_id,staged_at_utc,created_at_utc
    ) values (
      v_head_ids[v_i],
      v_entitlement->>'authority_kind',
      v_bundle.agency_id,
      v_candidate_id,
      (v_choice->>'contract_id')::uuid,
      (v_choice->>'week_ending_date')::date,
      v_member_root_ids[v_i],
      v_member_family_booking_ids[v_i],
      v_member_root_versions[v_i],
      v_head_revisions[v_i],
      v_prior_head_ids[v_i],
      'STAGED',
      (v_entitlement->>'certified_zero')::boolean,
      (v_entitlement->>'component_count')::integer,
      -- entitlement_digest: the complete economic content of the head.
      private.weekly_source_publication_request_digest_v1(
        pg_catalog.jsonb_build_object(
          'authority_kind',v_entitlement->'authority_kind',
          'certified_zero',v_entitlement->'certified_zero',
          'component_count',v_entitlement->'component_count',
          'components',v_component_hashes)),
      -- inventory_digest: which components the head contains, identity only.
      private.weekly_source_publication_request_digest_v1(
        pg_catalog.jsonb_build_object('components',v_inventory_pairs)),
      v_source_generation_digest,
      -- Retain the exact canonical origin already hashed above. No current
      -- Final lookup or later reconstruction can replace this sealed evidence.
      v_canonical->'financial_request'->'source_revision',
      v_decision_bundle_id,v_bundle_revision,v_decision_id,
      v_bundle.decided_by_user_id,v_now,v_now);

    insert into public.weekly_source_entitlement_head_components(
      head_id,component_ordinal,component_id,component_kind,economic_key_type,
      economic_key_value,component_member_identity,segment_id,segment_key,
      segment_stable_key,work_date,reference_number,hours_day,hours_night,hours_sat,
      hours_sun,hours_bh,additional_code_raw,unit_count,unit_pay_rate,unit_charge_rate,
      expense_code,pay_ex_vat,charge_ex_vat,exclude_from_pay,origin,
      decision_bundle_id,bundle_revision,movement_id,movement_group_id,
      component_sha256,created_at_utc)
    select
      v_head_ids[v_i],
      (component_element.value->>'component_ordinal')::integer,
      (component_element.value->>'component_id')::uuid,
      component_element.value->>'component_kind',
      component_element.value->>'economic_key_type',
      component_element.value->>'economic_key_value',
      component_element.value->>'component_member_identity',
      component_element.value->>'segment_id',
      component_element.value->>'segment_key',
      component_element.value->>'segment_stable_key',
      (component_element.value->>'work_date')::date,
      component_element.value->>'reference_number',
      (component_element.value->>'hours_day')::numeric,
      (component_element.value->>'hours_night')::numeric,
      (component_element.value->>'hours_sat')::numeric,
      (component_element.value->>'hours_sun')::numeric,
      (component_element.value->>'hours_bh')::numeric,
      component_element.value->>'additional_code_raw',
      (component_element.value->>'unit_count')::numeric,
      (component_element.value->>'unit_pay_rate')::numeric,
      (component_element.value->>'unit_charge_rate')::numeric,
      component_element.value->>'expense_code',
      (component_element.value->>'pay_ex_vat')::numeric,
      (component_element.value->>'charge_ex_vat')::numeric,
      (component_element.value->>'exclude_from_pay')::boolean,
      component_element.value->>'origin',
      v_decision_bundle_id,v_bundle_revision,
      (component_element.value->>'movement_id')::uuid,
      (component_element.value->>'movement_group_id')::uuid,
      private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),
      v_now
    from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
    order by (component_element.value->>'component_ordinal')::integer;

    v_entitlement:=null; v_choice:=null;
  end loop;

  -- BEGIN A8 SOURCE HEAD INVENTORY COMPLETE CHECK
  -- Prove exact component_count and certified_zero using the unchanged
  -- constraint assertion BEFORE any B authorisation or head activation.
  set constraints public.weekly_source_entitlement_head_inventory_assert immediate;
  -- END A8 SOURCE HEAD INVENTORY COMPLETE CHECK
  if v_local_publication_qualified is true then
    -- Actual staged complete inventory exists now. Capture only this sealed
    -- producer's approved detail before activation, auth pointer or I1 work.
    v_local_detail_count:=private.bpay_next_capture_local_source_detail_v1(
      v_head_ids[1],v_decision_bundle_id,v_bundle_revision,v_member_root_ids[1],
      (v_canonical#>>'{financial_request,source_revision,publication_request_id}')::uuid,
      (v_canonical#>>'{financial_request,source_revision,generation_id}')::uuid,
      v_local_context||pg_catalog.jsonb_build_object(
        'qualified_transaction_id',pg_catalog.pg_current_xact_id()::text));
    select pg_catalog.count(*)::integer into v_local_worked_count
      from public.weekly_source_entitlement_head_components c
      where c.head_id=v_head_ids[1] and c.component_kind='WORKED_TIME';
    if v_local_detail_count is distinct from v_local_worked_count then
      raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_LOCAL_DETAIL_NOT_COMPLETE';
    end if;
  end if;
  if v_next_pair is true then
    -- Both real successor inventories now exist. Complete their immutable
    -- chosen detail before I6, activation, pointer changes, receipt and I1.
    -- Existing exact target-authorisation/signature/whole-root review guards
    -- above remain the canonical command authority; the private helper binds
    -- the actual staged roots and exact before facts, not a invented request.
    v_pair_detail_count:=private.bpay_next_capture_source_pair_before_detail_v1(
      v_decision_bundle_id,v_bundle_revision,
      v_before_source_event_ids,v_before_financial_snapshot_ids);
    select pg_catalog.count(*)::integer into v_pair_worked_count
      from public.weekly_source_entitlement_head_components c
      where c.head_id=any(v_head_ids) and c.component_kind='WORKED_TIME';
    if v_pair_detail_count is distinct from v_pair_worked_count then
      raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_PAIR_DETAIL_NOT_COMPLETE';
    end if;
  end if;
  -- ---- 8. interface I-6 for a genuinely new B root ------------------------
  -- After staging and before the single invalidation.  I-6 calls the UNCHANGED
  -- ordinary Authorise owner exactly once and inserts the lineage generation of
  -- proof/34 section 4.  It is late-bound: WP-07 owns it.
  if v_target_auth is not null then
    v_target_authorise_result:=private.weekly_source_first_authorise_core_v1(
      v_member_root_ids[2],
      v_target_auth->>'expected_row_signature',
      (v_target_auth->>'actor_user_id')::uuid,
      p_lock_result);
    if coalesce((v_target_authorise_result->>'ok')::boolean,false) is not true then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_TARGET_AUTHORISATION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_TARGET_AUTHORISATION_FAILED',
                'first_authorise_result',v_target_authorise_result)::text;
    end if;
  end if;

  -- ---- 9. activate every head together ------------------------------------
  -- 24 section 5.1: pass the same transaction token and scalar head/currentness
  -- evidence used by the publication receipt.  The token is taken before
  -- activation so the head, the invalidation and the receipt all carry it.
  v_token:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token is null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_SCOPE_TOKEN_UNAVAILABLE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_SCOPE_TOKEN_UNAVAILABLE')::text;
  end if;

  -- BEGIN A8 SOURCE HEAD RECEIPT BUILD TIMING
  -- Activation must precede the one real immutable publication receipt below.
  -- Defer ONLY this head/receipt assertion across that exact construction;
  -- never accept a published head until the same named check succeeds.
  set constraints public.weekly_source_entitlement_head_receipt_assert deferred;
  -- END A8 SOURCE HEAD RECEIPT BUILD TIMING
  -- Notification reads the exact certified HEAD only after this coordinator has
  -- completed every aligned auth pointer, receipt and bundle. Defer ONLY its
  -- existing HEAD event; financial activation/order and all refusals stay intact.
  set constraints public.weekly_source_candidate_hours_push_head deferred;
  for v_i in 1..v_n loop
    if v_current_head_ids[v_i] is not null then
      update public.weekly_source_entitlement_heads
         set state='SUPERSEDED',
             superseded_at_utc=v_now,
             superseded_by_head_id=v_head_ids[v_i]
       where id=v_current_head_ids[v_i];
    end if;
  end loop;
  for v_i in 1..v_n loop
    update public.weekly_source_entitlement_heads
       set state='COMMITTED_CURRENT',
           committed_at_utc=v_now,
           publication_receipt_digest=v_digest,
           scope_change_tx_token=v_token
     where id=v_head_ids[v_i];
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_HEAD_ACTIVATION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_HEAD_ACTIVATION_FAILED',
                'head_id',v_head_ids[v_i],'rows',v_rows)::text;
    end if;
  end loop;

  -- ---- 10. current_entitlement_head_id on the live ROOT AUTHORISATION ------
  -- Decision D8 (WP-01c): the authorisation record, and therefore this pointer,
  -- is per ROOT in public.weekly_source_root_authorisations, not on the
  -- per-source-row lineage binding.  proof/34 section 4: written by the
  -- head-publication coordinator only, and nothing else on the generation row
  -- is touched.  The relation's own partial unique index gives at most one live
  -- generation per root, so exactly one row must move.
  for v_i in 1..v_n loop
    update public.weekly_source_root_authorisations
       set current_entitlement_head_id=v_head_ids[v_i]
     where root_timesheet_id=v_member_root_ids[v_i]
       and withdrawn_at_utc is null;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_ROOT_AUTHORISATION_POINTER_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_ROOT_AUTHORISATION_POINTER_FAILED',
                'root_ordinal',v_i,
                'root_timesheet_id',v_member_root_ids[v_i],
                'live_authorisation_rows_updated',v_rows)::text;
    end if;
    v_lineage_rows:=v_lineage_rows+v_rows;
  end loop;

  -- BEGIN A8 SOURCE LEGACY BRANCH
  IF v_legacy_financial_owner THEN
  -- END A8 SOURCE LEGACY BRANCH
  -- ---- 11. ONE bounded Workbench invalidation -----------------------------
  -- proof/32 section 8 step 3 and H2-036: exactly once, after every head and
  -- any B creation/Authorise, with the complete aligned Candidate/root pairs
  -- and the transaction token, success required before the receipt.  The
  -- ordinary Authorise trigger may queue a strict-subset job for the same
  -- Candidate under the same token; that is the accepted option 1 outcome and
  -- Weekly Source neither suppresses it nor folds it.
  v_invalidation:=private.pay_workbench_scope_invalidate_v1(
    p_candidate_ids=>pg_catalog.array_fill(v_candidate_id,array[v_n]),
    p_timesheet_ids=>v_member_root_ids,
    p_reason=>'WEEKLY_SOURCE_ENTITLEMENT_HEAD_PUBLICATION',
    p_scope_change_tx_token=>v_token,
    p_payload_json=>pg_catalog.jsonb_build_object(
      'weekly_source_publication',pg_catalog.jsonb_build_object(
        'decision_bundle_id',v_decision_bundle_id,
        'bundle_revision',v_bundle_revision,
        'publication_mode',v_mode,
        'request_digest',pg_catalog.encode(v_digest,'hex'),
        'head_ids',pg_catalog.to_jsonb(v_head_ids),
        'head_revisions',pg_catalog.to_jsonb(v_head_revisions))));
  -- `<>` on a missing key yields NULL, the IF does not fire, and the receipt is
  -- written anyway.  An invalidation result that does not say it covered
  -- exactly one Candidate must FAIL, so this is `is distinct from` (review
  -- finding, lower severity 1: executed with a wrapper that stripped the key,
  -- and the publication went through).
  if coalesce((v_invalidation->>'ok')::boolean,false) is not true
     or (v_invalidation->>'candidate_count')::integer is distinct from 1
     or (v_invalidation->>'scope_change_tx_token')::uuid is distinct from v_token
     or coalesce((v_invalidation->>'job_inserted_count')::integer,0)
        +coalesce((v_invalidation->>'job_coalesced_count')::integer,0)<1 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_FAILED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_FAILED',
              'invalidation',v_invalidation)::text;
  end if;

  -- ---- 11a. the R25 invalidation contract (HANDOVER 2 round 4, ruling 6) ---
  -- Restated R25: EVERY invalidation and dirty job created for this Candidate
  -- in this transaction - the explicit call, the ordinary Authorise route and
  -- every registered DIRTY_TRIGGER:<table>:<op> path - must carry the same
  -- token UUID and the same generation, and every non-complete job's scope,
  -- after the installed rotation normaliser, must be an exact subset of the
  -- declared aligned scope for that Candidate.  A different Candidate, an
  -- outside root or a token disagreement is a CONTRACT FAILURE, not extra
  -- harmless work, and rolls the whole transaction back.  Checked here, after
  -- the one explicit invalidation and BEFORE the receipt.
  --
  -- Ruling 6 point 1: calling the token owner again counts as the same token
  -- only if the returned UUID equals the controlling transaction token.
  v_token_recheck:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token_recheck is distinct from v_token then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','CONTROLLING_TOKEN_CHANGED_INSIDE_THE_TRANSACTION',
              'controlling_token',v_token,'recheck_token',v_token_recheck)::text;
  end if;

  -- The declared complete aligned scope for this Candidate, expanded through
  -- the INSTALLED rotation normaliser (call-only, contract section 2).
  v_normalised:=public._pay_workbench_normalise_timesheet_rotation_scope_payload(
    v_member_root_ids,array[]::uuid[]);
  select coalesce(pg_catalog.array_agg(distinct scope_element.value::uuid),array[]::uuid[])
    into v_declared_scope
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_normalised->'family_timesheet_ids',
                    coalesce(v_normalised->'canonical_timesheet_ids',
                             pg_catalog.to_jsonb(v_member_root_ids)))) as scope_element(value);
  v_declared_scope:=private.weekly_source_uuid_set_union_v1(v_declared_scope,v_member_root_ids);

  -- At most one new scope-change transaction, and it is the controlling token.
  if exists (
    select 1 from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from public.banking_pay_scope_change_transactions native
        where native.tx_token=effect.row_id offset 0) as scope_tx_row
     where effect.frame_id=v_observation_frame and effect.kind='TOKEN' and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
       where observed.frame_id=v_observation_frame and observed.kind='TOKEN'
         and observed.row_id=scope_tx_row.tx_token)
       and scope_tx_row.tx_token is distinct from v_token) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_SECOND_SCOPE_CHANGE_TOKEN_WAS_CREATED_IN_THIS_TRANSACTION')::text;
  end if;

  -- Every job this transaction queued: same token, same (absent) generation,
  -- this Candidate, and a scope inside the declared aligned scope.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
             'job_id',job_row.id,'job_type',job_row.job_type,
             'candidate_id',job_row.candidate_id,
             'scope_change_tx_token',job_row.scope_change_tx_token,
             'scope_change_generation',job_row.scope_change_generation,
             'targeted_timesheet_ids',job_row.payload_json->'targeted_timesheet_ids',
             'reason',job_row.payload_json->'reason')
      from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from public.banking_pay_workbench_jobs native
        where native.id=effect.row_id offset 0) as job_row
     where effect.frame_id=v_observation_frame and effect.kind='JOB' and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
       where observed.frame_id=v_observation_frame and observed.kind='JOB'
         and observed.row_id=job_row.id)
       and (
         job_row.scope_change_tx_token is distinct from v_token
         -- A18/R25 (PRE-EXISTING fix): a generation is tolerated ONLY on a still-QUEUED dirty-apply job for this
         -- Candidate that an EARLIER committed transaction created and this transaction's enqueue coalesced into.
         -- Its token is already this transaction's, and its generation is one already allocated, so the deferred
         -- finaliser lifts it with GREATEST to THIS transaction's generation at COMMIT and clears the token; the job
         -- then runs after COMMIT over exactly the declared targets (subset and complete-scope checks unchanged).
         -- A RUNNING job, a foreign token, another Candidate/job type or an unallocated generation still fails.
         or (job_row.scope_change_generation is not null
             and not (job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
                      and job_row.status='QUEUED'
                      and job_row.candidate_id=v_candidate_id
                      and job_row.scope_change_tx_token=v_token
                      and job_row.scope_change_generation<=coalesce((
                            select generation_counter.seq
                              from public.app_change_counters as generation_counter
                             where generation_counter.entity_key='pay_candidate_scope_generation'),0)))
         or (job_row.candidate_id is not null and job_row.candidate_id<>v_candidate_id)
         or exists (
           select 1
             from pg_catalog.jsonb_array_elements_text(
                    coalesce(job_row.payload_json->'targeted_timesheet_ids','[]'::jsonb)) as target(value)
            where not (target.value::uuid=any(v_declared_scope)))
         or exists (
           select 1
             from pg_catalog.jsonb_array_elements_text(
                    coalesce(job_row.payload_json->'linked_timesheet_ids','[]'::jsonb)) as linked(value)
            where not (linked.value::uuid=any(v_declared_scope))))
     limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_JOB_QUEUED_IN_THIS_TRANSACTION_BREAKS_THE_R25_CONTRACT',
              'controlling_token',v_token,
              'declared_scope',pg_catalog.to_jsonb(v_declared_scope),
              'job',v_offending)::text;
  end if;

  -- Validate every captured scope-state write, including reused rows and
  -- writes carrying an incorrect Candidate or token. No historical snapshot.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
             'timesheet_id',scope_state_row.timesheet_id,
             'candidate_id',scope_state_row.candidate_id,
             'last_scope_change_tx_token',scope_state_row.last_scope_change_tx_token,
             'last_dirty_reason',scope_state_row.last_dirty_reason)
      from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from private.banking_pay_workbench_timesheet_scope_state native
        where native.timesheet_id=effect.row_id offset 0) as scope_state_row
     where effect.frame_id=v_observation_frame and effect.kind='SCOPE'
       and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
         where observed.frame_id=v_observation_frame and observed.kind='SCOPE'
           and observed.row_id=scope_state_row.timesheet_id)
       and (scope_state_row.candidate_id is distinct from v_candidate_id
         or scope_state_row.last_scope_change_tx_token is distinct from v_token
         or not (scope_state_row.timesheet_id=any(v_declared_scope)))
     limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_SCOPE_STATE_ROW_OUTSIDE_THE_DECLARED_ALIGNED_SCOPE_WAS_DIRTIED',
              'declared_scope',pg_catalog.to_jsonb(v_declared_scope),
              'scope_state',v_offending)::text;
  end if;

  -- Registry-only writes are part of the same proof, even with no Timesheet
  -- or enqueue. Preserve missing/deleted observations and probe by native PK.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
      'candidate_id',effect.row_id,'deleted',effect.deleted,
      'last_scope_change_tx_token',registry_row.last_scope_change_tx_token,
      'reason',case
        when effect.deleted or registry_row.candidate_id is null then 'REGISTRY_ROW_MISSING_OR_DELETED'
        when registry_row.candidate_id is distinct from v_candidate_id then 'REGISTRY_FOR_A_DIFFERENT_CANDIDATE'
        else 'REGISTRY_CARRIES_A_DIFFERENT_TOKEN' end)
    from pg_temp.ws_observation_rows_v1 as effect
    left join lateral (
      select native.candidate_id,native.last_scope_change_tx_token
      from private.banking_pay_workbench_candidate_scope_registry native
      where native.candidate_id=effect.row_id offset 0
    ) as registry_row on true
    where effect.frame_id=v_observation_frame and effect.kind='REGISTRY'
      and (effect.deleted or registry_row.candidate_id is null
        or registry_row.candidate_id is distinct from v_candidate_id
        or registry_row.last_scope_change_tx_token is distinct from v_token)
    order by effect.row_id limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',detail=pg_catalog.jsonb_build_object(
        'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
        'reason',v_offending->>'reason','registry',v_offending)::text;
  end if;

  -- Exactly one effective complete-scope dirty result per Candidate and token
  -- (ruling 6 point 6).
  if (select pg_catalog.count(*)
        from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from public.banking_pay_workbench_jobs native
        where native.id=effect.row_id offset 0) as job_row
       where effect.frame_id=v_observation_frame and effect.kind='JOB'
         and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
           where observed.frame_id=v_observation_frame and observed.kind='JOB'
             and observed.row_id=job_row.id)
         and job_row.candidate_id=v_candidate_id
         and job_row.scope_change_tx_token=v_token
         and job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
         and job_row.status in ('QUEUED','RUNNING')
         and private.weekly_source_uuid_set_equals_v1(
               (select coalesce(pg_catalog.array_agg(distinct target.value::uuid),array[]::uuid[])
                  from pg_catalog.jsonb_array_elements_text(
                         coalesce(job_row.payload_json->'targeted_timesheet_ids','[]'::jsonb)) as target(value)),
               v_member_root_ids))<>1 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','NOT_EXACTLY_ONE_COMPLETE_SCOPE_JOB_FOR_THE_CANDIDATE_UNDER_THIS_TOKEN')::text;
  end if;

  -- No new Workbench effect may appear after the positive proof and before return.
  perform private.weekly_source_observation_seal_v1();
  -- BEGIN A8 SOURCE FACTUAL BRANCH
  ELSE
    v_token_recheck:=public.pay_workbench_scope_change_tx_token_v1();
    if v_token_recheck is distinct from v_token then
      raise exception using errcode='55000',message='WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
        detail=pg_catalog.jsonb_build_object('reason','CONTROLLING_TOKEN_CHANGED_INSIDE_THE_TRANSACTION')::text;
    end if;
    v_invalidation:=private.bpay_next_source_factual_contract_v1(
      v_observation_frame,v_token,v_member_root_ids,'PUBLICATION');
    perform private.weekly_source_observation_seal_v1();
  END IF;
  -- END A8 SOURCE FACTUAL BRANCH
  -- ---- 12. exactly one immutable receipt ----------------------------------
  insert into private.weekly_source_entitlement_publication_receipts(
    decision_bundle_id,pending_bundle_id,bundle_revision,request_digest,publication_mode,
    candidate_id,member_root_ids,member_family_booking_ids,member_root_versions,head_ids,
    scope_change_tx_token,decision_id,decided_by_user_id,released_by_worker_id,
    released_by_worker_run_id,census_json,proof_json,created_at_utc
  ) values (
    v_decision_bundle_id,p_pending_bundle_id,v_bundle_revision,v_digest,v_mode,
    v_candidate_id,v_member_root_ids,v_member_family_booking_ids,v_member_root_versions,
    v_head_ids,v_token,v_decision_id,v_bundle.decided_by_user_id,p_worker_id,
    p_worker_run_id,coalesce(p_census,'{}'::jsonb),coalesce(p_proof,'{}'::jsonb),v_now)
  returning * into v_receipt;

  -- BEGIN A8 SOURCE HEAD RECEIPT COMPLETE CHECK
  -- Match every activated head to the genuine receipt's bundle, digest,
  -- controlling token and exact head membership BEFORE acceptance/return.
  set constraints public.weekly_source_entitlement_head_receipt_assert immediate;
  -- END A8 SOURCE HEAD RECEIPT COMPLETE CHECK
  if v_bundle.state='PROPOSED' then
    update public.weekly_source_entitlement_decision_bundles
       set state='COMMITTED',committed_at_utc=v_now
     where decision_bundle_id=v_decision_bundle_id
       and bundle_revision=v_bundle_revision;
  end if;

  -- The same automatic HEAD trigger now sees the complete approved publication.
  -- Its original privacy/reconciliation/dedupe/withhold semantics are unchanged.
  set constraints public.weekly_source_candidate_hours_push_head immediate;

  for v_i in 1..v_n loop
    v_result_heads:=v_result_heads||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'root_ordinal',v_i,
        'head_id',v_head_ids[v_i],
        'head_revision',v_head_revisions[v_i],
        'prior_head_id',v_prior_head_ids[v_i],
        'superseded_head_id',v_current_head_ids[v_i],
        'root_timesheet_id',v_member_root_ids[v_i],
        'family_booking_id',v_member_family_booking_ids[v_i],
        'root_timesheet_version',v_member_root_versions[v_i]));
  end loop;

  perform private.weekly_source_observation_end_v1(v_observation_frame);
  return pg_catalog.jsonb_build_object(
    'ok',true,'published',true,'replayed',false,
    'receipt',private.weekly_source_publication_receipt_json_v1(v_receipt.id),
    'heads',v_result_heads,
    'scope_change_tx_token',v_token,
    'invalidation',v_invalidation,
    'root_authorisations_pointed',v_lineage_rows,
    'before_position_source',pg_catalog.to_jsonb(v_before_source),
    'declared_aligned_scope',pg_catalog.to_jsonb(v_declared_scope),
    'member_timesheet_ids',pg_catalog.to_jsonb(v_member_timesheet_ids));
end;
$function$;

-- Retained complete authority: supabase/repeatable/22092026_1052_weekly_source_operation_local_validation_v1.sql
CREATE OR REPLACE FUNCTION public.weekly_source_first_authorisation_withdraw_v1(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  -- BEGIN A8 SOURCE MODE DECLARATION
  v_legacy_financial_owner boolean;
  -- END A8 SOURCE MODE DECLARATION
  v_signature text;
  -- BEGIN QUALIFIED INTERNAL SIGNATURE HANDOFF
  v_handoff_before jsonb;
  v_handoff_after jsonb;
  v_handoff_week uuid;
  v_handoff_signature text;
  -- END QUALIFIED INTERNAL SIGNATURE HANDOFF
  v_actor public.tms_users%rowtype;
  v_recorded jsonb;
  v_context jsonb;
  v_candidate_id uuid;
  v_lock jsonb;
  v_census jsonb;
  v_members uuid[];
  v_verdict jsonb;
  v_canonical uuid;
  v_authorisation jsonb;
  v_authorisation_id uuid;
  v_token uuid;
  v_token_again uuid;
  v_observation_frame uuid;
  v_unauthorise jsonb;
  v_invalidation jsonb;
  v_contract jsonb;
  v_protected jsonb;
  v_head jsonb;
  v_head_id uuid;
  v_head_locked uuid;
  v_head_lock_count integer;
  v_receipt_id uuid;
  v_canonical_request jsonb;
  v_digest bytea;
  v_now timestamptz;
  v_rows integer;
  v_result jsonb;
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  v_signature:=nullif(pg_catalog.btrim(coalesce(p_expected_row_signature,'')),'');
  if p_timesheet_id is null or p_actor_user_id is null or v_signature is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'withdrawn',false,'replayed',false,
      'code','WEEKLY_SOURCE_UNAUTHORISE_REQUEST_INVALID','retryable',false,
      'reason','TIMESHEET_ACTOR_AND_EXPECTED_ROW_SIGNATURE_REQUIRED');
  end if;

  select * into v_actor from public.tms_users where id=p_actor_user_id;
  if not found or not coalesce(v_actor.is_active,false) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'withdrawn',false,'replayed',false,
      'code','WEEKLY_SOURCE_UNAUTHORISE_ACTOR_INVALID','retryable',false,
      'reason','ACTOR_NOT_FOUND_OR_INACTIVE');
  end if;

  -- ---- section 5 step 1 / ruling A3 step 5: exact replay first, before the
  -- gate and the locks.  An exact replay returns the durable receipt's own
  -- recorded result and calls nothing.  A CONFLICTING replay -- the same replay
  -- identity presented with a different physical Timesheet expectation -- and a
  -- receipt that no longer rebuilds to its own digest both refuse, permanently,
  -- for manual review, and write no lifecycle row.
  v_recorded:=private.weekly_source_first_authorisation_withdrawal_recorded_v1(
    p_timesheet_id,v_signature,p_expected_timesheet_id);
  if v_recorded is not null then
    if coalesce((v_recorded->>'ok')::boolean,false) is not true then
      -- A conflicting replay writes its refusal audit, so it is not the
      -- immutable successful-receipt exemption from fresh admission.
      perform private.weekly_source_pay_query_admit_v2();
      perform public._audit_insert(
        'timesheets',p_timesheet_id::text,
        'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL_REFUSED',
        null,
        pg_catalog.jsonb_build_object(
          'expected_row_signature',v_signature,
          'expected_timesheet_id',p_expected_timesheet_id,
          'code',v_recorded->>'code','reason',v_recorded->>'reason',
          'receipt_id',v_recorded->>'receipt_id',
          'stage','REPLAY'),
        'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL',p_actor_user_id);
      return v_recorded;
    end if;
    return v_recorded||pg_catalog.jsonb_build_object('replayed',true);
  end if;

  -- Fresh withdrawal precedes callback-mode/module and family locks, and
  -- every later refusal audit. No query check is added to frozen payments.
  perform private.weekly_source_pay_query_admit_v2();

  -- BEGIN A8 SOURCE MODE CAPTURE
  v_legacy_financial_owner:=private.bpay_next_legacy_callback_enabled_v1();

  -- END A8 SOURCE MODE CAPTURE
  -- One plain read so the gate can be pinned to a Candidate.  No write.
  v_context:=private.weekly_source_first_authorisation_context_v1(p_timesheet_id);
  if coalesce((v_context->>'ok')::boolean,false) is not true then
    perform public._audit_insert(
      'timesheets',p_timesheet_id::text,
      'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL_REFUSED',
      null,
      pg_catalog.jsonb_build_object(
        'expected_row_signature',v_signature,
        'expected_timesheet_id',p_expected_timesheet_id,
        'code',v_context->>'code','reason',v_context->>'reason',
        'stage','IDENTITY'),
      'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL',p_actor_user_id);
    return v_context||pg_catalog.jsonb_build_object('withdrawn',false,'replayed',false);
  end if;
  v_candidate_id:=(v_context->>'candidate_id')::uuid;

  -- ---- ruling A3 step 1, first half: the Candidate serial gate, then the
  -- rotation lock set, both through interface I-1 in the deadlock-free order of
  -- proof/34 section 5.
  v_lock:=private.weekly_source_lock_and_resolve_families_v1(
    v_candidate_id,
    array[p_timesheet_id]::uuid[],
    'WORKBENCH_CANDIDATE_FIRST_AUTHORISATION_WITHDRAWAL',
    pg_catalog.gen_random_uuid(),
    'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL');
  if coalesce((v_lock->>'ok')::boolean,false) is not true then
    return v_lock||pg_catalog.jsonb_build_object('withdrawn',false,'replayed',false);
  end if;

  -- ---- ruling A3 step 1, second half: the currentness guards.  The live
  -- root-authorisation row and any committed current head of the family are
  -- taken FOR UPDATE, by PREDICATE rather than by an id read earlier, so a
  -- publication that committed while this call was resolving identity is seen
  -- and locked rather than missed.  Heads are locked after the family and
  -- Timesheet locks, matching the publication coordinator's own order.
  v_context:=private.weekly_source_first_authorisation_context_v1(p_timesheet_id);
  if coalesce((v_context->>'ok')::boolean,false) is not true then
    perform public._audit_insert(
      'timesheets',p_timesheet_id::text,
      'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL_REFUSED',
      null,
      pg_catalog.jsonb_build_object(
        'expected_row_signature',v_signature,
        'code',v_context->>'code','reason',v_context->>'reason',
        'stage','IDENTITY_UNDER_LOCK'),
      'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL',p_actor_user_id);
    return v_context||pg_catalog.jsonb_build_object('withdrawn',false,'replayed',false);
  end if;

  v_canonical:=(v_context->>'canonical_timesheet_id')::uuid;
  v_authorisation:=v_context->'authorisation';
  select pg_catalog.array_agg(member_element.value::uuid)
    into v_members
  from pg_catalog.jsonb_array_elements_text(v_context->'member_timesheet_ids')
    as member_element(value);
  v_members:=coalesce(v_members,array[]::uuid[]);

  if pg_catalog.jsonb_typeof(coalesce(v_authorisation,'null'::jsonb))='object' then
    v_authorisation_id:=(v_authorisation->>'id')::uuid;
    perform 1
    from public.weekly_source_root_authorisations as authorisation_row
    where authorisation_row.id=v_authorisation_id
      and authorisation_row.withdrawn_at_utc is null
    for update;
  end if;

  -- Explicit cardinality, never `limit 1`: two committed current heads for one
  -- family is impossible under the partial unique index, and if it ever happened
  -- W11 refuses on the count rather than this statement picking one.
  -- `FOR UPDATE` cannot appear in the same query level as an aggregate, so the
  -- lock is taken in a CTE and counted outside it.
  with locked_head as (
    select head_row.id
    from public.weekly_source_entitlement_heads as head_row
    where head_row.state='COMMITTED_CURRENT'
      and (pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(coalesce(v_context->>'family_booking_id',''))
           or head_row.root_timesheet_id=any(v_members))
    for update
  )
  select pg_catalog.count(*)::integer,pg_catalog.min(locked_head.id::text)::uuid
    into v_head_lock_count,v_head_locked
  from locked_head;

  -- W1 to W11 under those locks, over the complete family.
  v_census:=private.weekly_source_freeze_census_v1(v_candidate_id,v_members);
  v_verdict:=private.weekly_source_first_authorisation_withdraw_checks_v1(
    v_context,v_census,p_expected_timesheet_id,v_signature);

  if coalesce((v_verdict->>'ok')::boolean,false) is not true then
    -- UNA-010: refused with no lifecycle write and an audit row.
    perform public._audit_insert(
      'timesheets',p_timesheet_id::text,
      'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL_REFUSED',
      null,
      pg_catalog.jsonb_build_object(
        'expected_row_signature',v_signature,
        'expected_timesheet_id',p_expected_timesheet_id,
        'candidate_id',v_candidate_id,
        'family_booking_id',v_context->>'family_booking_id',
        'canonical_timesheet_id',v_canonical,
        'code',v_verdict->>'code',
        'refusal_nature',v_verdict->>'refusal_nature',
        'refusal_message',v_verdict->>'refusal_message',
        'failed_checks',v_verdict->'failed_checks',
        'census_result',v_verdict->>'census_result',
        'stage','CHECKS'),
      'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL',p_actor_user_id);
    return pg_catalog.jsonb_build_object(
      'ok',false,'withdrawn',false,'replayed',false,
      'code',v_verdict->>'code',
      'refusal_nature',v_verdict->>'refusal_nature',
      'refusal_message',v_verdict->>'refusal_message',
      'retryable',coalesce((v_verdict->>'retryable')::boolean,false),
      -- An INTEGRITY refusal is the package's "Office review" disposition, and
      -- round 5 section A5 requires the finance-case write-off in particular to
      -- be routed to review rather than presented as a retry.
      'review_required',coalesce(v_verdict->>'refusal_nature','')='INTEGRITY',
      'timesheet_id',p_timesheet_id,
      'canonical_timesheet_id',v_canonical,
      'family_booking_id',v_context->>'family_booking_id',
      'checks',v_verdict->'checks',
      'failed_checks',v_verdict->'failed_checks',
      'census_result',v_verdict->>'census_result',
      'census_class_counts',v_verdict->'census_class_counts');
  end if;

  -- The head the verdict decided may be superseded, re-proved against the row
  -- this transaction actually holds FOR UPDATE.  A disagreement means the head
  -- moved between the lock and the verdict, which cannot happen under these
  -- locks; it fails closed rather than being written through.
  v_head:=case when pg_catalog.jsonb_typeof(coalesce(v_verdict->'head_supersession','null'::jsonb))='object'
               then v_verdict->'head_supersession' end;
  v_head_id:=(v_head->>'head_id')::uuid;
  if v_head_id is distinct from v_head_locked
     or v_head_lock_count is distinct from (case when v_head_id is null then 0 else 1 end) then
    raise exception 'WEEKLY_SOURCE_UNAUTHORISE_HEAD_LOCK_DISAGREEMENT'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_UNAUTHORISE_HEAD_LOCK_DISAGREEMENT',
              'locked_head_id',v_head_locked,
              'locked_head_count',v_head_lock_count,
              'verdict_head_id',v_head_id)::text;
  end if;

  -- ---- ruling A3 step 4: the controlling transaction token is established
  -- before the unauthorisation so that the ordinary Unauthorise trigger route
  -- and every registered DIRTY_TRIGGER path share it (round 4 ruling 6 point 1).
  v_token:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token is null then
    raise exception 'WEEKLY_SOURCE_INVALIDATION_TOKEN_MISSING'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_INVALIDATION_TOKEN_MISSING',
              'context','WITHDRAWAL')::text;
  end if;

  v_observation_frame:=private.weekly_source_observation_begin_v1();

  -- ---------------------------------------------------------------------
  -- ORDERING RULE — WHY THE WRITES BELOW MUST NOT BE SEPARATED
  -- (WP-03 handoff N16, carried into WP-07b and kept by WP-07c.)
  --
  -- The rule, in plain English.  The Timesheet must never be observable as
  -- UNAUTHORISED while its Weekly Source authorisation record is still LIVE,
  -- and the entitlement head must never be observable as SUPERSEDED while the
  -- Timesheet is still authorised.  Those facts are what
  -- `private.weekly_source_managed_root_guard_v1` and the Gate 4 Workbench
  -- selector read, and a reader that saw a contradictory pair would be told
  -- something untrue about a root.  So all of them must be written in ONE
  -- transaction -- unless they are provably unobservable apart, which is the
  -- case here.
  --
  -- Why the present order is SAFE, and it is a property of PostgreSQL rather
  -- than of this code:
  --
  --   * every write below is in ONE transaction, and this owner has NO
  --     exception handler anywhere, so there is no sub-transaction that could
  --     commit one without the others;
  --   * PostgreSQL offers no dirty read at any isolation level — READ
  --     UNCOMMITTED is mapped to READ COMMITTED — so no concurrent session can
  --     see the order of statements inside this transaction.  Proved at READ
  --     COMMITTED and REPEATABLE READ, in both directions;
  --   * the one remaining way the window could be seen is an IN-TRANSACTION
  --     reader: a trigger that calls the managed-root guard or the selector
  --     while this owner runs.  Every non-internal trigger on
  --     `public.timesheets`, `public.timesheets_financials`,
  --     `public.contract_weeks` and `public.weekly_source_entitlement_heads`
  --     was enumerated and NONE calls
  --     `private.weekly_source_managed_root_guard_v1`,
  --     `…_guard_decision_v1` or the Gate 4 selector.  That matches open ruling
  --     OR-2, which explicitly does NOT build a trigger-level backstop on those
  --     tables.
  --
  -- WHAT WOULD BREAK IT, and therefore what must not be done without reordering
  -- first:
  --
  --   1. splitting this sequence across two transactions, or introducing an
  --      intermediate COMMIT, an autonomous transaction or a dblink/background
  --      call between any two of the writes;
  --   2. adding an `EXCEPTION` handler around any of them, which puts it in a
  --      sub-transaction that can roll back on its own;
  --   3. OPEN RULING OR-2 being decided the other way — that is, a guard
  --      trigger being attached to `public.timesheets` or
  --      `public.timesheets_financials`.  The order would then be observable
  --      INSIDE this transaction and reordering becomes MANDATORY, not merely
  --      prudent: the withdrawal marks would have to be written before the call
  --      to `public.timesheet_unauthorise_atomic` below.
  --
  -- Section 16 of this package's verifier is the executed guard on points 1 and
  -- 2: it fails if these writes stop sharing one transaction, if an exception
  -- handler appears, or if a concurrent reader can ever see a live
  -- authorisation record on an unauthorised Timesheet.
  -- ---------------------------------------------------------------------
  -- WP-24, 18 September 2026.  POINT 3 ABOVE HAS NOW HAPPENED, so the
  -- reordering this note calls MANDATORY is done here rather than left prudent.
  --
  -- Gate 13 hostile review finding F1 (CRITICAL) proved that the ORDINARY
  -- Unauthorise owner, which the Office's own `/unauthorise` route calls, left a
  -- committed entitlement head current on a managed root and paid it in place of
  -- what the Office authorised next: GBP 90.00 / 9 h paid against GBP 140.00 /
  -- 14 h authorised, executed with the real Gate 4 selector.  The fix is a
  -- BEFORE UPDATE guard trigger on `public.timesheets.authorised_at_server`
  -- (`supabase/repeatable/17092026_1400_weekly_source_ordinary_authorisation_guard_v1.sql`),
  -- which HANDOVER 2 round-5 Part D authorises when it rules OR-2 CONFIRMED:
  -- "If the guard attaches to Timesheet, financial or contract-week writes, the
  -- withdrawal owner obeys the same canonical lock order as Part A3."
  --
  -- That trigger IS the in-transaction reader point 3 names, so the order below
  -- became observable INSIDE this transaction and the withdrawal marks now go
  -- FIRST.  Nothing else about this sequence changes: it is still one
  -- transaction, still has no exception handler anywhere, and the two invariants
  -- at the head of this note are both STRENGTHENED rather than weakened - the
  -- Timesheet is now never observable as unauthorised while its authorisation
  -- record is live even to an in-transaction reader, and the head is still
  -- superseded only after the Timesheet has been unauthorised.
  --
  -- It is also what ruling A3 itself describes: "marks the authorisation
  -- withdrawn" is step 2 and the head supersession is step 3, so the two halves
  -- of step 2 are now adjacent and both precede step 3.
  --
  -- `v_now` moves up with the marks it stamps.  It is read after this point by
  -- the protected-hours withdrawal, the replay receipt and the supersession, and
  -- by nothing before it.
  -- ---------------------------------------------------------------------
  v_now:=pg_catalog.clock_timestamp();

  -- Ruling A3 step 2, second half (now written FIRST): the withdrawal marks on
  -- the live root-authorisation generation and nothing else on it; the head
  -- pointer is cleared in the SAME statement.
  --
  -- Decision D8 and proof/36 section 5.6.  The check constraint
  -- `withdrawn_at_utc IS NULL OR current_entitlement_head_id IS NULL` is
  -- evaluated on the finished row, so a two-statement version fails; this one
  -- does not.
  --
  -- WP-24: this is also the STATE that tells this owner apart from an ordinary
  -- Unauthorise at the guard trigger below.  Decision D8 makes `managed` the
  -- conjunction of a LIVE generation and a currently authorised Timesheet, so
  -- once this statement has run the root is not managed and the guard permits
  -- the unauthorisation that follows.  An ordinary Unauthorise never runs this
  -- statement, so its generation is still live and it is refused.  The guard
  -- asks nothing about who is calling.
  -- BEGIN BEFORE INTERNAL WITHDRAWAL SIGNATURE
  -- W1-W11 already certified the caller under the existing complete lock set.
  -- Reuse that context's week and require it to remain the caller's exact state.
  v_handoff_week:=(v_context->>'contract_week_id')::uuid;
  v_handoff_before:=public.timesheet_lifecycle_guard_signature_v1(
    v_canonical,v_handoff_week,true);
  if v_handoff_before->>'ok' is distinct from 'true'
     or pg_catalog.jsonb_typeof(v_handoff_before->'payload') is distinct from 'object'
     or v_handoff_before->>'current_timesheet_id' is distinct from v_canonical::text
     or v_handoff_before->>'backend_row_signature' is distinct from v_signature
     or v_handoff_before->>'backend_row_signature' is distinct from
        pg_catalog.md5((v_handoff_before->'payload')::text) then
    raise exception 'WEEKLY_SOURCE_WITHDRAWAL_SIGNATURE_HANDOFF_INVALID' using errcode='55000';
  end if;
  -- END BEFORE INTERNAL WITHDRAWAL SIGNATURE
  update public.weekly_source_root_authorisations
     set withdrawn_at_utc=v_now,
         withdrawn_by_user_id=p_actor_user_id,
         current_entitlement_head_id=null
   where id=v_authorisation_id
     and withdrawn_at_utc is null;
  get diagnostics v_rows=row_count;
  if v_rows<>1 then
    raise exception 'WEEKLY_SOURCE_ROOT_AUTHORISATION_WITHDRAWAL_FAILED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_ROOT_AUTHORISATION_WITHDRAWAL_FAILED',
              'root_authorisation_id',v_authorisation_id,
              'rows',v_rows)::text;
  end if;

  -- Ruling A3 step 2, first half: the UNCHANGED owner, exactly once, requiring
  -- {ok:true}.
  -- BEGIN AFTER INTERNAL WITHDRAWAL SIGNATURE
  -- Only this owner's certified Source-basis transition may change the handoff.
  -- Preserve the original caller token for W1-W11, replay, receipt and audit.
  v_handoff_after:=public.timesheet_lifecycle_guard_signature_v1(
    v_canonical,v_handoff_week,true);
  v_handoff_signature:=nullif(pg_catalog.btrim(coalesce(
    v_handoff_after->>'backend_row_signature','')),'');
  if v_handoff_after->>'ok' is distinct from 'true'
     or pg_catalog.jsonb_typeof(v_handoff_after->'payload') is distinct from 'object'
     or v_handoff_signature is null
     or v_handoff_signature is distinct from pg_catalog.md5((v_handoff_after->'payload')::text)
     or ((v_handoff_before->'payload')-'weekly_source_category_basis')
        is distinct from ((v_handoff_after->'payload')-'weekly_source_category_basis') then
    raise exception 'WEEKLY_SOURCE_WITHDRAWAL_SIGNATURE_HANDOFF_UNSAFE' using errcode='55000';
  end if;
  -- END AFTER INTERNAL WITHDRAWAL SIGNATURE
  v_unauthorise:=public.timesheet_unauthorise_atomic(
    p_timesheet_id=>v_canonical,
    p_expected_timesheet_id=>v_canonical,
    p_actor_user_id=>p_actor_user_id,
    p_expected_row_signature=>v_handoff_signature);

  if coalesce((v_unauthorise->>'ok')::boolean,false) is not true then
    raise exception 'WEEKLY_SOURCE_UNAUTHORISE_OWNER_REFUSED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_UNAUTHORISE_OWNER_REFUSED',
              'timesheet_id',v_canonical,
              'owner_result',v_unauthorise)::text;
  end if;

  -- BEGIN A8 SOURCE LEGACY BRANCH
  IF v_legacy_financial_owner THEN
  -- END A8 SOURCE LEGACY BRANCH
  -- Ruling A3 step 4: one aligned invalidation for the pair (Candidate,
  -- canonical root) only, and success required.  HANDOVER 2 round 3 answer 10:
  -- not every physical family member; the installed normaliser expands the pair
  -- to the full physical rotation family.
  v_invalidation:=private.pay_workbench_scope_invalidate_v1(
    p_candidate_ids=>array[v_candidate_id]::uuid[],
    p_timesheet_ids=>array[v_canonical]::uuid[],
    p_reason=>'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL',
    p_scope_change_tx_token=>v_token,
    p_payload_json=>pg_catalog.jsonb_build_object(
      'weekly_source_first_authorisation_withdrawal',pg_catalog.jsonb_build_object(
        'timesheet_id',v_canonical,
        'family_booking_id',v_context->>'family_booking_id',
        'authorisation_generation',v_authorisation->>'authorisation_generation',
        'superseded_head_id',v_head_id,
        'expected_row_signature',v_signature)));

  if coalesce((v_invalidation->>'ok')::boolean,false) is not true
     or (v_invalidation->>'candidate_count')::integer<>1
     or (v_invalidation->>'scope_change_tx_token')::uuid is distinct from v_token
     or coalesce((v_invalidation->>'job_inserted_count')::integer,0)
        +coalesce((v_invalidation->>'job_coalesced_count')::integer,0)<1 then
    raise exception 'WEEKLY_SOURCE_UNAUTHORISE_INVALIDATION_FAILED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_UNAUTHORISE_INVALIDATION_FAILED',
              'invalidation',v_invalidation)::text;
  end if;

  -- BEGIN A8 SOURCE FACTUAL BRANCH
  END IF;

  -- END A8 SOURCE FACTUAL BRANCH
  v_token_again:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token_again is distinct from v_token then
    raise exception 'WEEKLY_SOURCE_INVALIDATION_CONTRACT_FAILED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_INVALIDATION_CONTRACT_FAILED',
              'reason','TRANSACTION_TOKEN_CHANGED',
              'context','WITHDRAWAL')::text;
  end if;


  -- WP-24: ruling A3 step 2's withdrawal marks USED TO SIT HERE.  They are now
  -- written before the call to `public.timesheet_unauthorise_atomic` above, for
  -- the reason given in full at that point: the guard trigger on
  -- `public.timesheets.authorised_at_server` is the in-transaction reader that
  -- the ORDERING RULE note lists as making this reordering mandatory.  Nothing
  -- was added or removed - the same single statement, with the same three
  -- assignments and the same one-row assertion, in a different place.

  -- proof/36 section 5 step 7: the approved protected-hours decision, marked
  -- withdrawn and never deleted.
  v_protected:=private.weekly_source_first_authorisation_withdraw_protected_v1(
    v_members,p_actor_user_id,v_now);

  -- BEGIN A8 SOURCE LEGACY BRANCH
  IF v_legacy_financial_owner THEN
  -- END A8 SOURCE LEGACY BRANCH
  v_contract:=private.weekly_source_invalidation_contract_assert_v1(
    v_candidate_id,array[v_canonical]::uuid[],v_token,'WITHDRAWAL',array[]::uuid[]);
  -- BEGIN A8 SOURCE FACTUAL BRANCH
  ELSE
    v_contract:=private.bpay_next_source_factual_contract_v1(
      v_observation_frame,v_token,array[v_canonical]::uuid[],'WITHDRAWAL');
    v_invalidation:=v_contract;
    perform private.weekly_source_observation_seal_v1();
  END IF;
  -- END A8 SOURCE FACTUAL BRANCH


  -- ---- ruling A3 step 5: the durable replay receipt, and step 3: the head
  -- supersession that points at it.
  --
  -- The receipt id is generated first so that the recorded result and the
  -- returned result are the SAME object: an exact replay hands back exactly
  -- what this call returned, receipt id and supersession included.
  v_receipt_id:=pg_catalog.gen_random_uuid();
  v_canonical_request:=private.weekly_source_withdrawal_canonical_request_v1(
    (v_head->>'agency_id')::uuid,
    v_candidate_id,
    (v_context->>'contract_id')::uuid,
    v_canonical,
    v_context->>'family_booking_id',
    (v_context->>'canonical_version')::integer,
    p_timesheet_id,
    p_expected_timesheet_id,
    v_authorisation_id,
    (v_authorisation->>'authorisation_generation')::integer,
    v_signature,
    v_head_id,
    (v_head->>'head_revision')::bigint);
  v_digest:=private.weekly_source_publication_request_digest_v1(v_canonical_request);

  v_result:=pg_catalog.jsonb_build_object(
    'ok',true,'withdrawn',true,'replayed',false,
    -- WP-12 handoff N2 reads the response as
    -- `{ ok, withdrawn, code, refusal_nature, refusal_message, retryable }`, so
    -- the SUCCESS shape carries those keys as explicit nulls rather than
    -- omitting them.  An absent key and a null key are different things to a
    -- browser, and the screen should never have to tell them apart.
    'code',null::text,
    'refusal_nature',null::text,
    'refusal_message',null::text,
    'retryable',false,
    'review_required',false,
    'timesheet_id',p_timesheet_id,
    'canonical_timesheet_id',v_canonical,
    'family_booking_id',v_context->>'family_booking_id',
    'timesheet_version',(v_context->>'canonical_version')::integer,
    'candidate_id',v_candidate_id,
    'expected_row_signature',v_signature,
    'root_authorisation_id',v_authorisation_id,
    'authorisation_generation',(v_authorisation->>'authorisation_generation')::integer,
    'entitlement_head_cleared',(v_authorisation->>'current_entitlement_head_id')::uuid,
    'withdrawn_at_utc',v_now,
    'withdrawn_by_user_id',p_actor_user_id,
    'scope_change_tx_token',v_token,
    'withdrawal_receipt_id',v_receipt_id,
    'request_digest',pg_catalog.encode(v_digest,'hex'),
    'head_superseded',v_head_id is not null,
    'head_supersession',case when v_head_id is null then null
      else pg_catalog.jsonb_build_object(
        'head_id',v_head_id,
        'head_revision',(v_head->>'head_revision')::bigint,
        'state_before',v_head->>'state_before',
        'state_after','SUPERSEDED',
        'superseded_reason','FIRST_AUTHORISATION_WITHDRAWN',
        'certified_zero',(v_head->>'certified_zero')::boolean,
        'component_count',(v_head->>'component_count')::integer,
        'predecessor_link_receipt_id',v_receipt_id) end,
    'invalidation',pg_catalog.jsonb_build_object(
      'ok',true,
      'candidate_count',(v_invalidation->>'candidate_count')::integer,
      'job_inserted_count',coalesce((v_invalidation->>'job_inserted_count')::integer,0),
      'job_coalesced_count',coalesce((v_invalidation->>'job_coalesced_count')::integer,0)),
    'invalidation_contract',v_contract,
    'protected_hours',v_protected,
    'unauthorise_result',pg_catalog.jsonb_build_object(
      'ok',true,
      'operation',v_unauthorise->>'operation',
      'timesheet_id',v_unauthorise->>'timesheet_id',
      'contract_week_id',v_unauthorise->>'contract_week_id',
      'processing_status',v_unauthorise->>'processing_status'),
    'checks',v_verdict->'checks',
    'census_result',v_verdict->>'census_result',
    'census_class_counts',v_verdict->'census_class_counts');

  insert into private.weekly_source_first_authorisation_withdrawal_receipts(
    id,agency_id,candidate_id,contract_id,root_timesheet_id,root_family_booking_id,
    root_timesheet_version,requested_timesheet_id,expected_timesheet_id,
    root_authorisation_id,authorisation_generation,expected_row_signature,
    request_digest,predecessor_head_id,predecessor_head_revision,
    predecessor_head_state_before,predecessor_head_certified_zero,head_superseded,
    scope_change_tx_token,withdrawn_at_utc,withdrawn_by_user_id,checks_json,result_json
  ) values (
    v_receipt_id,
    (v_head->>'agency_id')::uuid,
    v_candidate_id,
    (v_context->>'contract_id')::uuid,
    v_canonical,
    v_context->>'family_booking_id',
    (v_context->>'canonical_version')::integer,
    p_timesheet_id,
    p_expected_timesheet_id,
    v_authorisation_id,
    (v_authorisation->>'authorisation_generation')::integer,
    v_signature,
    v_digest,
    v_head_id,
    (v_head->>'head_revision')::bigint,
    case when v_head_id is null then null else v_head->>'state_before' end,
    case when v_head_id is null then null else (v_head->>'certified_zero')::boolean end,
    v_head_id is not null,
    v_token,
    v_now,
    p_actor_user_id,
    coalesce(v_verdict->'checks','[]'::jsonb),
    v_result);

  -- Ruling A3 step 3.  This is the ONLY statement in the Weekly Source
  -- withdrawal path that writes a head row, and it can only be reached when
  -- W1 to W11 have all passed, which means no Draft dependency, payment item,
  -- reservation, bank transfer, execution, provider attempt, settlement,
  -- remittance, recovery, invoice or other committed financial effect stands
  -- against the head or the root.  It sets the explicit reason and the link to
  -- the receipt whose `predecessor_head_id` is the immutable link back; both are
  -- frozen from here on by
  -- `private.weekly_source_entitlement_head_withdrawal_supersession_guard_v1`,
  -- which also makes reviving the head impossible.
  --
  -- The head's own `scope_change_tx_token` and `publication_receipt_digest` are
  -- deliberately NOT touched: they are the publication's evidence, and the
  -- deferred `weekly_source_entitlement_head_receipt_assert` re-runs on this
  -- update and would refuse if they moved.
  if v_head_id is not null then
    update public.weekly_source_entitlement_heads
       set state='SUPERSEDED',
           superseded_at_utc=v_now,
           superseded_reason='FIRST_AUTHORISATION_WITHDRAWN',
           superseded_by_withdrawal_id=v_receipt_id
     where id=v_head_id
       and state='COMMITTED_CURRENT';
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_UNAUTHORISE_HEAD_SUPERSESSION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_UNAUTHORISE_HEAD_SUPERSESSION_FAILED',
                'head_id',v_head_id,'rows',v_rows)::text;
    end if;

    -- Prove the post-state inside the transaction rather than asserting it in
    -- prose: no committed current head may survive for this family.
    select pg_catalog.count(*)::integer into v_rows
    from public.weekly_source_entitlement_heads as head_row
    where head_row.state='COMMITTED_CURRENT'
      and (pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(coalesce(v_context->>'family_booking_id',''))
           or head_row.root_timesheet_id=any(v_members));
    if v_rows<>0 then
      raise exception 'WEEKLY_SOURCE_UNAUTHORISE_HEAD_STILL_CURRENT'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_UNAUTHORISE_HEAD_STILL_CURRENT',
                'head_id',v_head_id,'remaining',v_rows)::text;
    end if;
  end if;

  -- proof/36 section 5 step 4: the withdrawal recorded through the existing
  -- audit owner as well, so the previous authorisation and the withdrawal are
  -- both visible in Audit.  The durable replay copy is the receipt above; this
  -- is the human record and no longer the replay source (WP-07b finding F4).
  perform public._audit_insert(
    'timesheets',v_canonical::text,
    'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWN',
    pg_catalog.jsonb_build_object(
      'authorised_at_server',v_context#>>'{root,authorised_at_server}',
      'current_entitlement_head_id',v_authorisation->>'current_entitlement_head_id',
      'authorisation_generation',(v_authorisation->>'authorisation_generation')::integer),
    pg_catalog.jsonb_build_object(
      'expected_row_signature',v_signature,
      'expected_timesheet_id',p_expected_timesheet_id,
      'requested_timesheet_id',p_timesheet_id,
      'withdrawal_receipt_id',v_receipt_id,
      'result',v_result),
    'WEEKLY_SOURCE_FIRST_AUTHORISATION_WITHDRAWAL',p_actor_user_id);

  perform private.weekly_source_observation_end_v1(v_observation_frame);
  return v_result;
end;
$function$;

notify pgrst, 'reload schema';


-- A8 Source transaction-local cleanup timing and first-authorise tail repair.
-- Install AFTER all earlier Source / Banking Pay repeatables (including1709,
--0202,0505,0555,0556):0557 is the final authority for these TWO identities.
-- No private first-authorise core, protected withdrawal, token producer,
-- inventory assertion, trigger, schema, grants or financial policy is replaced.
-- Complete accepted0202 public body and0505 inventory are retained below;
-- only the marked additions differ. CREATE OR REPLACE preserves existing ACL.



do $installed$
begin
  if to_regprocedure('private.bpay_next_source_current_lock_inventory_v1(uuid,integer,uuid,uuid,uuid,date,date)') is null
     or to_regprocedure('public.weekly_source_first_authorise_v1(uuid,uuid,text,uuid)') is null
     or to_regprocedure('private.bpay_source_authorise_identity_v1(uuid)') is null
     or to_regprocedure('private.bpay_source_authorise_lock_v1(uuid,uuid,uuid)') is null
     or to_regprocedure('private.bpay_next_stage_source_current_v1(uuid,uuid,uuid)') is null
     or to_regprocedure('private.bpay_next_publish_source_staged_pair_v1(uuid[],uuid[],uuid[])') is null
     or not exists(select 1 from pg_catalog.pg_trigger t
       where t.tgrelid='private.bpay_next_source_current_lock_operations'::regclass
         and t.tgname='bp_next_source_lock_operation_cleanup'
         and t.tgfoid='private.bpay_next_source_lock_operation_cleanup_assert_v1()'::regprocedure
         and t.tgdeferrable and t.tginitdeferred and t.tgenabled='O'
         and not t.tgisinternal) then
    raise exception 'BPAY_NEXT_SOURCE_BOUNDARY_DEPENDENCY_MISSING' using errcode='55000';
  end if;
end $installed$;

create or replace function private.bpay_next_source_current_lock_inventory_v1(
  p_upload uuid,p_generation integer,p_old_revision uuid,p_group uuid,p_client uuid,p_start date,p_end date
) returns uuid language plpgsql security definer
set search_path=pg_catalog,private,public as $f$
declare v_operation uuid;v_publication uuid;v_key record;v_page uuid[];v_after uuid;v_result jsonb;
begin
  -- Inert for the retained default LEGACY / DISABLED paths. The module row
  -- share lock keeps one actual writer's ownership decision stable to COMMIT.
  perform 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if not found then return null;end if;
  if p_group is null or p_client is null or (p_upload is null)<>(p_generation is null)
    or (p_upload is null and p_old_revision is null) then
    raise exception 'BPAY_NEXT_SOURCE_LOCK_OPERATION_INPUT_INVALID' using errcode='22023';end if;
  if p_upload is not null then
    select p.id into strict v_publication from public.weekly_source_projection_publications p
      join public.weekly_source_uploads u on u.id=p.upload_id
      join public.weekly_source_cycles c on c.id=u.source_cycle_id
      where u.id=p_upload and c.source_group_id=p_group and p.state in ('CURRENT','CORRECTION_READY')
        and coalesce(p.projection_generation,p.authority_scope_version::integer)=p_generation
        and u.confirmed_coverage_start_local_date is not distinct from p_start
        and u.confirmed_coverage_end_local_date is not distinct from p_end
        and (u.correction_session_id is null or exists(select 1 from public.weekly_final_source_correction_sessions s
          where s.id=u.correction_session_id and s.expected_current_final_revision_id=p_old_revision));
  end if;
  -- BEGIN A8 SOURCE OPERATION CLEANUP TIMING
  -- This row is transaction-local and the genuine outer Source owner removes
  -- it before returning. An IMMEDIATE caller cannot require that removal at
  -- this inner INSERT. Defer ONLY its own cleanup assertion; an orphan still
  -- fails at COMMIT or an explicit named IMMEDIATE check.
  set constraints private.bp_next_source_lock_operation_cleanup deferred;
  -- END A8 SOURCE OPERATION CLEANUP TIMING
  insert into private.bpay_next_source_current_lock_operations(upload_id,projection_publication_id,generation,old_revision_id,
    source_group_id,client_id,coverage_start,coverage_end)
    values(p_upload,v_publication,p_generation,p_old_revision,p_group,p_client,p_start,p_end) returning id into v_operation;
  if exists(select 1 from private.bpay_next_source_current_inventory_v1(p_upload,p_generation,p_old_revision,p_group,p_client,p_start,p_end) i
    left join public.timesheets t on t.timesheet_id=i.root_timesheet_id
    where t.timesheet_id is null or t.booking_id is null or btrim(t.booking_id)='') then
    raise exception 'BPAY_NEXT_SOURCE_LOCK_ROOT_UNBOUND' using errcode='55000';end if;
  insert into private.bpay_next_source_current_lock_members(operation_id,root_timesheet_id,raw_booking_id,canonical_booking_id)
    select v_operation,t.timesheet_id,t.booking_id,btrim(t.booking_id)
    from private.bpay_next_source_current_inventory_v1(p_upload,p_generation,p_old_revision,p_group,p_client,p_start,p_end) i
    join public.timesheets t on t.timesheet_id=i.root_timesheet_id;
  for v_key in select m.canonical_booking_id as canonical,m.raw_booking_id as raw
    from private.bpay_next_source_current_lock_members m where m.operation_id=v_operation
    order by m.canonical_booking_id,m.raw_booking_id,m.root_timesheet_id loop
    perform pg_advisory_xact_lock(hashtext(v_key.canonical));
    if v_key.raw<>v_key.canonical then perform pg_advisory_xact_lock(hashtext(v_key.raw));end if;
  end loop;
  perform private.bpay_next_source_current_lock_recheck_v1(v_operation);
  loop
    select array_agg(x.root_timesheet_id order by x.root_timesheet_id) into v_page from (
      select m.root_timesheet_id from private.bpay_next_source_current_lock_members m where m.operation_id=v_operation
        and (v_after is null or m.root_timesheet_id>v_after) order by m.root_timesheet_id limit 100
    ) x;
    exit when v_page is null;
    v_result:=private.weekly_source_lock_family_rows_v1(v_page,null);
    if coalesce((v_result->>'ok')::boolean,false) is not true then
      raise exception '%',v_result->>'code' using errcode='55000',detail=v_result::text;end if;
    v_after:=v_page[cardinality(v_page)];
  end loop;
  perform private.bpay_next_source_current_lock_recheck_v1(v_operation);
  return v_operation;
end $f$;

CREATE OR REPLACE FUNCTION public.weekly_source_first_authorise_v1(p_timesheet_id uuid, p_expected_timesheet_id uuid, p_expected_row_signature text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_context jsonb;
  v_lock jsonb;
  v_core jsonb;
  v_canonical uuid;
  -- BEGIN A8 SOURCE FIRST AUTHORISE DECLARATIONS
  v_work uuid;
  v_revision uuid;
  v_event uuid;
  -- END A8 SOURCE FIRST AUTHORISE DECLARATIONS
begin
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  if p_timesheet_id is null or p_actor_user_id is null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_FIRST_AUTHORISE_REQUEST_INVALID',
      'retryable',false,'reason','TIMESHEET_AND_ACTOR_REQUIRED');
  end if;

  -- One plain read before the gate, because the gate is pinned to a Candidate.
  -- Nothing is written by it and the identity is re-resolved under the locks.
  v_context:=private.bpay_source_authorise_identity_v1(p_timesheet_id);
  if coalesce((v_context->>'ok')::boolean,false) is not true then
    return v_context;
  end if;

  -- BEGIN QUERY V2 FIRST AUTHORISE ADMISSION
  -- Admit before the first Source/Candidate lock; contention remains exact
  -- 55P03, not a financial REVIEW or an automatic owner retry.
  perform private.weekly_source_pay_query_admit_v2();
  -- END QUERY V2 FIRST AUTHORISE ADMISSION

  v_lock:=private.bpay_source_authorise_lock_v1(
    (v_context->>'candidate_id')::uuid,p_timesheet_id,pg_catalog.gen_random_uuid());
  if coalesce((v_lock->>'ok')::boolean,false) is not true then
    return v_lock;
  end if;

  select (family_element.value->>'canonical_timesheet_id')::uuid
    into v_canonical
  from pg_catalog.jsonb_array_elements(coalesce(v_lock->'families','[]'::jsonb))
    as family_element(value)
  where (family_element.value->>'requested_timesheet_id')::uuid=p_timesheet_id;

  if p_expected_timesheet_id is not null
     and p_expected_timesheet_id is distinct from v_canonical then
    return pg_catalog.jsonb_build_object(
      'ok',false,'code','WEEKLY_SOURCE_TIMESHEET_ROTATED_BEFORE_AUTHORISATION',
      'retryable',false,'timesheet_id',p_timesheet_id,
      'canonical_timesheet_id',v_canonical);
  end if;

  v_core:=private.weekly_source_first_authorise_core_v1(
    p_timesheet_id,p_expected_row_signature,p_actor_user_id,v_lock);
  -- BEGIN A8 SOURCE FIRST AUTHORISE NEXT TAIL
  -- Capture only after the real outer first-authorise owner succeeds. The
  -- unchanged private core also runs inside two-root head publication and must
  -- never publish an intermediate B revision.
  if coalesce((v_core->>'ok')::boolean,false) is true
     and (select active_owner from private.bpay_next_module_control
          where id=1)='NEXT' then
    v_event:=(v_core->>'root_authorisation_id')::uuid;
    select s.work_id,s.revision_id into strict v_work,v_revision
      from private.bpay_next_stage_source_current_v1(
        p_timesheet_id,v_event,null) s;
    perform * from private.bpay_next_publish_source_staged_pair_v1(
      array[v_work],array[v_revision],array[v_event]);
    -- Metadata only, after the real outer stage/publication; no position or
    -- financial seed while the queued POSITION_APPLY is still incomplete.
    perform * from private.bpay_next_initial_tsfin_bind_v1(v_event);
  end if;
  -- END A8 SOURCE FIRST AUTHORISE NEXT TAIL
  return v_core||pg_catalog.jsonb_build_object('gate',v_lock->>'gate');
end;
$function$;

notify pgrst, 'reload schema';



-- Closed Office preparation boundary; service JWT plus existing active admin.
-- No arbitrary owner, money, actor override, old session or worker drain.
-- Selection/current approval pages are pre-Draft; review pages use frozen rows.



create or replace function private.bpay_next_preparation_authority_v1(p_actor_user_id uuid)
returns void language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
begin
  if coalesce(pg_catalog.current_setting('request.jwt.claim.role',true),
    nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role'
    or p_actor_user_id is null or not exists(select 1 from public.tms_users u
      where u.id=p_actor_user_id and u.is_active is true and u.role::text='admin' for share) then
    raise exception using errcode='42501',message='BPAY_NEXT_PREPARATION_FORBIDDEN';
  end if;
  if not exists(select 1 from private.bpay_next_module_control m where m.id=1 and m.active_owner='NEXT' for share) then
    raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';
  end if;
end
$function$;

-- Exact key/scalar validation shared only by these two closed wrappers.
create or replace function private.bpay_next_preparation_args_v1(p_args jsonb,p_keys text[])
returns void language plpgsql security invoker
set search_path=pg_catalog
as $function$
declare v_key text;v_type text;v_text text;
begin
  if p_args is null or pg_catalog.jsonb_typeof(p_args) is distinct from 'object'
    or pg_catalog.octet_length(p_args::text)>32768
    or (select count(*) from pg_catalog.jsonb_object_keys(p_args))<>pg_catalog.cardinality(p_keys)
    or exists(select 1 from pg_catalog.jsonb_object_keys(p_args) k where not(k=any(p_keys))) then
    raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
  end if;
  foreach v_key in array p_keys loop
    v_type:=pg_catalog.jsonb_typeof(p_args->v_key);v_text:=p_args->>v_key;
    if v_key in ('choices','approved_line_ids','component_ids','selected') then
      if v_type is distinct from 'array' or pg_catalog.jsonb_array_length(p_args->v_key) not between 1 and 100 then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key='limit' then
      if v_type is distinct from 'number' or v_text!~'^[0-9]{1,3}$' or v_text::integer not between 1 and 100 then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key like 'after_%' and v_type='null' then
      continue;
    elsif v_type is distinct from 'string' then
      raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
    elsif v_key like '%_id' then
      if v_text!~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key in ('pay_date','after_week') then
      if v_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not pg_catalog.isfinite(v_text::date)
        or v_text::date::text<>v_text then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key='pay_channel' then
      if v_text not in ('PAYE','UMBRELLA') then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    elsif v_key='after_bucket' then
      if v_text not in ('DAY','NIGHT','SAT','SUN','BH') then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    else
      if v_text!~'^(0|[1-9][0-9]{0,18})$' or v_text::numeric>9223372036854775807
        or (v_key in ('page_no','selection_revision','review_revision') and v_text='0') then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
    end if;
  end loop;
end
$function$;

create or replace function public.bpay_next_preparation_intake_v1(p_actor_user_id uuid,p_action text,p_args jsonb)
returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_keys text[];v_run uuid;v_work uuid;v_revision uuid;v_candidate uuid;v_result jsonb;v_output jsonb;
  v_ids uuid[];v_selected boolean[];v_entry jsonb;v_header private.bpay_next_pay_run%rowtype;
begin
  perform private.bpay_next_preparation_authority_v1(p_actor_user_id);
  v_keys:=case p_action
    when 'CREATE' then array['run_id','pay_date']
    when 'WORK_PAGE' then array['run_id','page_no','choices']
    when 'COMPONENT_PAGE' then array['run_id','work_id','expected_revision_id','page_no','approved_line_ids']
    when 'COMPONENT_SEAL' then array['run_id','work_id','expected_revision_id','expected_pages','expected_count']
    when 'CASE_PAGE' then array['run_id','candidate_id','selection_revision','page_no','request_id','component_ids','selected']
    when 'CASE_SEAL' then array['run_id','candidate_id','selection_revision','expected_pages','expected_items']
    when 'SEAL_ENQUEUE' then array['run_id','command_id','expected_pages','expected_count']
    when 'REVIEW' then array['run_id']
    when 'CONFIRM' then array['run_id','review_revision'] else null end;
  if v_keys is null then raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  perform private.bpay_next_preparation_args_v1(p_args,v_keys);
  v_run:=(p_args->>'run_id')::uuid;v_work:=(p_args->>'work_id')::uuid;
  v_revision:=(p_args->>'expected_revision_id')::uuid;v_candidate:=(p_args->>'candidate_id')::uuid;
  if p_action in ('COMPONENT_PAGE','CASE_PAGE') then
    for v_entry in select value from pg_catalog.jsonb_array_elements(
      p_args->case when p_action='CASE_PAGE' then 'component_ids' else 'approved_line_ids' end) loop
      if pg_catalog.jsonb_typeof(v_entry) is distinct from 'string'
        or (v_entry#>>'{}')!~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
      v_ids:=pg_catalog.array_append(v_ids,(v_entry#>>'{}')::uuid);
    end loop;
    if p_action='CASE_PAGE' then
      if pg_catalog.jsonb_array_length(p_args->'selected')<>pg_catalog.cardinality(v_ids) then
        raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
      end if;
      for v_entry in select value from pg_catalog.jsonb_array_elements(p_args->'selected') loop
        if pg_catalog.jsonb_typeof(v_entry) is distinct from 'boolean' then
          raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
        end if;
        v_selected:=pg_catalog.array_append(v_selected,(v_entry#>>'{}')::boolean);
      end loop;
    end if;
  end if;
  case p_action
  when 'CREATE' then
    v_result:=private.bpay_next_create_preparation_v1(v_run,p_actor_user_id,(p_args->>'pay_date')::date);
    select r.* into strict v_header from private.bpay_next_pay_run r where r.id=v_run;
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'status',v_result->>'status',
      'selection_state',v_result->>'selection_state','selection_count',v_header.selection_count::text,
      'selected_candidate_count',v_header.selected_candidate_count::text);
  when 'WORK_PAGE' then
    v_output:=private.bpay_next_append_work_choices_v1(v_run,(p_args->>'page_no')::bigint,p_args->'choices');
  when 'COMPONENT_PAGE' then
    v_output:=private.bpay_next_append_component_selection_page_v1(v_run,v_work,v_revision,(p_args->>'page_no')::bigint,v_ids);
  when 'COMPONENT_SEAL' then
    v_output:=private.bpay_next_seal_component_selection_v1(v_run,v_work,v_revision,
      (p_args->>'expected_pages')::bigint,(p_args->>'expected_count')::bigint);
  when 'CASE_PAGE' then
    v_result:=private.bpay_next_append_case_selection_page_v1(v_run,v_candidate,(p_args->>'selection_revision')::bigint,
      (p_args->>'page_no')::bigint,(p_args->>'request_id')::uuid,v_ids,v_selected);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'candidate_id',v_candidate,
      'selection_revision',p_args->>'selection_revision','page_no',v_result->>'page_no',
      'item_count',v_result->>'item_count','replay',v_result->'replay');
  when 'CASE_SEAL' then
    v_result:=private.bpay_next_seal_case_selection_v1(v_run,v_candidate,(p_args->>'selection_revision')::bigint,
      (p_args->>'expected_pages')::bigint,(p_args->>'expected_items')::bigint);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'candidate_id',v_candidate,
      'selection_revision',v_result->>'selection_revision','sealed',v_result->'sealed',
      'selected_count',v_result->>'selected_count','excluded_count',v_result->>'excluded_count','replay',v_result->'replay');
  when 'SEAL_ENQUEUE' then
    perform private.bpay_next_seal_selection_v1(v_run,(p_args->>'expected_pages')::bigint,(p_args->>'expected_count')::bigint);
    v_result:=private.bpay_next_enqueue_preparation_v1(v_run,(p_args->>'command_id')::uuid);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'command_id',v_result->>'command_id',
      'agency_sequence',v_result->>'agency_sequence','replay',v_result->'replay');
  when 'REVIEW' then
    v_result:=private.bpay_next_review_simple_run_v1(v_run);
    select r.* into strict v_header from private.bpay_next_pay_run r where r.id=v_run;
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'phase',v_result->>'phase','reason',v_result->>'reason',
      'review_revision',v_header.review_revision::text,'all_ready',v_result->'all_ready',
      'replay',coalesce(v_result->'replay','false'::jsonb));
  when 'CONFIRM' then
    v_result:=private.bpay_next_confirm_simple_run_v1(v_run,(p_args->>'review_revision')::bigint);
    v_output:=pg_catalog.jsonb_build_object('run_id',v_run,'phase',v_result->>'phase',
      'review_revision',v_result->>'review_revision','replay',v_result->'replay','drafts',v_result->'drafts');
  end case;
  if pg_catalog.octet_length(v_output::text)>120000 then
    raise exception using errcode='54000',message='BPAY_NEXT_PREPARATION_RESPONSE_TOO_LARGE';
  end if;
  return v_output;
end
$function$;

create or replace function public.bpay_next_preparation_page_v1(p_actor_user_id uuid,p_kind text,p_args jsonb)
returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_keys text[];v_work uuid;v_revision uuid;v_line uuid;v_shift uuid;v_limit integer;
  v_row jsonb;v_page jsonb[];v_rows jsonb:='[]'::jsonb;v_n integer:=0;v_complete boolean:=true;
begin
  perform private.bpay_next_preparation_authority_v1(p_actor_user_id);
  v_keys:=case p_kind
    when 'COMPONENTS' then array['work_id','expected_revision_id','after_line_no','limit']
    when 'WORK_CHOICES' then array['run_id','after_work_id','limit']
    when 'SELECTED_COMPONENTS' then array['run_id','work_id','after_selection_no','limit']
    when 'CHANNEL_DRAFTS' then array['run_id']
    when 'CHANNEL_WORKERS' then array['run_id','pay_channel','after_candidate_id','limit']
    when 'CHANNEL_STATUS' then array['run_id','pay_channel','run_worker_id','after_transfer_no','limit']
    when 'WORKERS' then array['run_id','after_candidate_id','limit']
    when 'REVISION_COMPARISON' then array['run_worker_id','after_work_id','limit']
    when 'LINES' then array['run_worker_id','after_line_no','limit']
    when 'SHIFTS' then array['work_id','expected_revision_id','approved_line_id','after_detail_no','limit']
    when 'BREAKS' then array['work_id','expected_revision_id','approved_line_id','shift_detail_id','after_break_no','limit']
    when 'RATES' then array['work_id','expected_revision_id','approved_line_id','after_bucket','limit']
    when 'CURRENT_WORK' then array['candidate_id','after_week','after_work_id','limit']
    when 'CURRENT_CASES' then array['candidate_id','after_case_id','limit']
    when 'CURRENT_STORED_CREDITS' then array['candidate_id','after_legacy_case_id','limit']
    when 'CASE_COMPONENTS' then array['candidate_id','case_id','after_component_ordinal','limit']
    when 'STATUS' then array['run_id','run_worker_id','after_transfer_no','limit']
    when 'RETURN_CASH' then array['run_id','run_worker_id','after_transfer_no','limit'] else null end;
  if v_keys is null then raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';end if;
  perform private.bpay_next_preparation_args_v1(p_args,v_keys);
  v_work:=(p_args->>'work_id')::uuid;v_revision:=(p_args->>'expected_revision_id')::uuid;
  v_line:=(p_args->>'approved_line_id')::uuid;v_shift:=(p_args->>'shift_detail_id')::uuid;v_limit:=(p_args->>'limit')::integer;
  if p_kind='CHANNEL_DRAFTS' then
    return private.bpay_next_channel_drafts_page_v1((p_args->>'run_id')::uuid);
  elsif p_kind='CHANNEL_WORKERS' then
    return private.bpay_next_channel_worker_page_v1((p_args->>'run_id')::uuid,
      p_args->>'pay_channel',(p_args->>'after_candidate_id')::uuid,v_limit);
  elsif p_kind='CHANNEL_STATUS' then
    if p_args->'after_transfer_no'<>'null'::jsonb and ((p_args->>'after_transfer_no')::numeric<1
      or (p_args->>'after_transfer_no')::numeric>2147483647) then
      raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
    end if;
    return private.bpay_next_channel_status_page_v1((p_args->>'run_id')::uuid,p_args->>'pay_channel',
      (p_args->>'run_worker_id')::uuid,(p_args->>'after_transfer_no')::integer,v_limit);
  end if;
  -- Only the two exact factual0580 owners; no competing reader or financial
  -- history/calculation path. CURRENT_WORK does not certify payability.
  if p_kind='CURRENT_WORK' then
    return private.bpay_next_current_work_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'after_week')::date,(p_args->>'after_work_id')::uuid,v_limit);
  elsif p_kind='CURRENT_CASES' then
    return private.bpay_next_current_case_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'after_case_id')::uuid,v_limit);
  elsif p_kind='CURRENT_STORED_CREDITS' then
    -- Factual, exact-Candidate possible origins only; binding revalidates the
    -- retained creator/component/account facts. This is not pay eligibility.
    -- Closed raw reply includes scan_cursor from the bounded raw window;
    -- filtering can produce an empty nonterminal page without restarting it.
    return private.bpay_next_current_stored_credit_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'after_legacy_case_id')::uuid,v_limit);
  elsif p_kind='CASE_COMPONENTS' then
    return private.bpay_next_current_case_component_page_v1((p_args->>'candidate_id')::uuid,
      (p_args->>'case_id')::uuid,(p_args->>'after_component_ordinal')::bigint,v_limit);
  elsif p_kind in ('STATUS','RETURN_CASH') then
    if p_args->'after_transfer_no'<>'null'::jsonb and ((p_args->>'after_transfer_no')::numeric<1
      or (p_args->>'after_transfer_no')::numeric>2147483647) then
      raise exception using errcode='22023',message='BPAY_NEXT_PREPARATION_REQUEST_INVALID';
    end if;
    if p_kind='RETURN_CASH' then
      return private.bpay_next_return_cash_page_v1((p_args->>'run_id')::uuid,
        (p_args->>'run_worker_id')::uuid,(p_args->>'after_transfer_no')::integer,v_limit);
    end if;
    return private.bpay_next_worker_status_page_v1((p_args->>'run_id')::uuid,
      (p_args->>'run_worker_id')::uuid,(p_args->>'after_transfer_no')::integer,v_limit);
  end if;
  if p_kind in ('COMPONENTS','SHIFTS','BREAKS','RATES') then
    if not exists(select 1 from private.bpay_next_work w
      join private.bpay_next_work_revision r on r.work_id=w.id and r.id=v_revision
      where w.id=v_work and w.approval_state='APPROVED' and w.current_revision_id=v_revision
        and w.applied_revision_id=v_revision and r.sealed_at_utc is not null and r.approved_at_utc is not null) then
      raise exception using errcode='55000',message='BPAY_NEXT_CHOICE_REVISION_NOT_CURRENT';
    end if;
    if p_kind<>'COMPONENTS' and not exists(select 1 from private.bpay_next_approved_line l where l.id=v_line and l.revision_id=v_revision) then
      raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_LINE_NOT_IN_REVISION';
    end if;
    if p_kind='BREAKS' and not exists(select 1 from private.bpay_next_shift_detail s where s.id=v_shift and s.approved_line_id=v_line) then
      raise exception using errcode='23514',message='BPAY_NEXT_CHOICE_LINE_NOT_IN_REVISION';
    end if;
  elsif p_kind in ('WORK_CHOICES','SELECTED_COMPONENTS') then
    perform 1 from private.bpay_next_pay_run r where r.id=(p_args->>'run_id')::uuid;
    if not found then raise exception using errcode='P0002',message='BPAY_NEXT_PREPARATION_NOT_FOUND';end if;
    if p_kind='SELECTED_COMPONENTS' then
      perform 1 from private.bpay_next_work_choice c where c.run_id=(p_args->>'run_id')::uuid and c.work_id=v_work;
      if not found then raise exception using errcode='P0002',message='BPAY_NEXT_PREPARATION_NOT_FOUND';end if;
    end if;
  end if;
  -- Each branch is a <=100 indexed relational page. A byte boundary ends
  -- before an entire row, never truncates facts; callers resume its last key.
  -- CASE evaluates only its chosen subquery, so unrelated review owners are
  -- never called with NULL scope. Each subquery orders/limits BEFORE packing.
  select case p_kind
    when 'COMPONENTS' then array(
      select pg_catalog.jsonb_build_object(
        'approved_line_id',l.id,'line_no',l.line_no::text,'component_key',l.component_key,'component_kind',l.component_kind,
        'work_date',l.work_date,'source_pay_channel',r.source_pay_channel,'approved_source_ex_vat',l.source_pay_ex_vat::text,
        'realised_source_ex_vat',display.realised_source_ex_vat::text,'held_source_ex_vat',display.held_source_ex_vat::text,
        'residual_source_ex_vat',display.residual_source_ex_vat::text,
        'position_ready',display.position_ready) as value
        from private.bpay_next_approved_line l join private.bpay_next_work_revision r on r.id=l.revision_id
        join private.bpay_next_work w on w.id=r.work_id
        cross join lateral private.bpay_next_source_comparison_component_display_v2(
          w.candidate_id,w.id,r.id,l.id) display
        where l.revision_id=v_revision and l.line_no>coalesce((p_args->>'after_line_no')::bigint,0)
        order by l.line_no,l.id limit v_limit)
    when 'WORK_CHOICES' then array(
      select pg_catalog.jsonb_build_object('work_id',c.work_id,'expected_revision_id',c.expected_revision_id,
        'selection_mode',c.selection_mode,'selection_state',c.selection_state,'page_count',c.page_count::text,'component_count',c.component_count::text)
        from private.bpay_next_work_choice c where c.run_id=(p_args->>'run_id')::uuid
          and ((p_args->>'after_work_id') is null or c.work_id>(p_args->>'after_work_id')::uuid)
        order by c.work_id limit v_limit)
    when 'SELECTED_COMPONENTS' then array(
      select pg_catalog.jsonb_build_object('selection_no',c.selection_no::text,
        'approved_line_id',c.approved_line_id,'expected_revision_id',c.expected_revision_id,'component_key',c.component_key)
        from private.bpay_next_selected_component c where c.run_id=(p_args->>'run_id')::uuid and c.work_id=v_work
          and c.selection_no>coalesce((p_args->>'after_selection_no')::bigint,0)
        order by c.selection_no limit v_limit)
    when 'WORKERS' then array(
      select pg_catalog.jsonb_build_object('run_worker_id',w.run_worker_id,'candidate_id',w.candidate_id,
        'worker_status',w.worker_status,'frozen_ex_vat',w.frozen_ex_vat::text,'frozen_vat',w.frozen_vat::text,
        'frozen_inc_vat',w.frozen_inc_vat::text,'review_issue_code',w.review_issue_code)
        from private.bpay_next_simple_review_worker_page_v1((p_args->>'run_id')::uuid,(p_args->>'after_candidate_id')::uuid,v_limit) w
        order by w.candidate_id limit v_limit)
    when 'REVISION_COMPARISON' then array(
      select pg_catalog.jsonb_build_object('run_work_id',w.run_work_id,'work_id',w.work_id,'original_timesheet_id',w.original_timesheet_id,
        'captured_revision_id',w.captured_revision_id,'current_revision_id',w.current_revision_id,'newer_approval_available',w.newer_approval_available)
        from private.bpay_next_simple_revision_comparison_page_v1((p_args->>'run_worker_id')::uuid,(p_args->>'after_work_id')::uuid,v_limit) w
        order by w.work_id limit v_limit)
    when 'LINES' then array(
      select pg_catalog.jsonb_build_object('run_line_id',l.run_line_id,'line_no',l.line_no::text,
        'original_timesheet_id',l.original_timesheet_id,'captured_revision_id',l.captured_revision_id,'component_key',l.component_key,
        'component_kind',l.component_kind,'work_date',l.work_date,'source_pay_channel',l.source_pay_channel,'target_pay_channel',l.target_pay_channel,
        'source_consumed_ex_vat',l.source_consumed_ex_vat::text,'frozen_ex_vat',l.frozen_ex_vat::text,'frozen_vat',l.frozen_vat::text,'frozen_inc_vat',l.frozen_inc_vat::text)
        from private.bpay_next_simple_review_line_page_v1((p_args->>'run_worker_id')::uuid,(p_args->>'after_line_no')::bigint,v_limit) l
        order by l.line_no limit v_limit)
    when 'SHIFTS' then array(
      select pg_catalog.jsonb_build_object('shift_detail_id',s.id,'detail_no',s.detail_no::text,'work_date',s.work_date,
        'shift_start_at',s.shift_start_at,'shift_end_at',s.shift_end_at,'shift_start_local',s.shift_start_local,'shift_end_local',s.shift_end_local,
        'shift_overnight',s.shift_overnight,'submitted_minutes',s.submitted_minutes::text,'approved_minutes',s.approved_minutes::text,
        'approved_hours',s.approved_hours::text,'detail_label',s.detail_label,'segment_pay_ex_vat',s.segment_pay_ex_vat::text,'pay_excluded',s.pay_excluded,
        'hours_day',s.hours_day::text,'hours_night',s.hours_night::text,'hours_sat',s.hours_sat::text,'hours_sun',s.hours_sun::text,'hours_bh',s.hours_bh::text)
        from private.bpay_next_shift_detail s where s.approved_line_id=v_line and s.detail_no>coalesce((p_args->>'after_detail_no')::bigint,0)
        order by s.detail_no limit v_limit)
    when 'BREAKS' then array(
      select pg_catalog.jsonb_build_object('break_detail_id',b.id,'break_no',b.break_no::text,'break_start_at',b.break_start_at,
        'break_end_at',b.break_end_at,'break_start_local',b.break_start_local,'break_end_local',b.break_end_local,'break_minutes',b.break_minutes::text)
        from private.bpay_next_break_detail b where b.shift_detail_id=v_shift and b.break_no>coalesce((p_args->>'after_break_no')::bigint,0)
        order by b.break_no limit v_limit)
    when 'RATES' then array(
      select pg_catalog.jsonb_build_object('rate_detail_id',r.id,'bucket',r.bucket,'approved_hours',r.approved_hours::text,'source_pay_rate',r.source_pay_rate::text)
        from private.bpay_next_rate_detail r where r.approved_line_id=v_line
          and ((p_args->>'after_bucket') is null or r.bucket>p_args->>'after_bucket')
        order by r.bucket limit v_limit)
  end into v_page;
  foreach v_row in array v_page
  loop
    if pg_catalog.octet_length((v_rows||pg_catalog.jsonb_build_array(v_row))::text)>120000 then
      if v_n=0 then raise exception using errcode='54000',message='BPAY_NEXT_PREPARATION_RESPONSE_TOO_LARGE';end if;
      v_complete:=false;exit;
    end if;
    v_rows:=v_rows||pg_catalog.jsonb_build_array(v_row);v_n:=v_n+1;
  end loop;
  if v_n=v_limit then v_complete:=false;end if;
  return pg_catalog.jsonb_build_object('rows',v_rows,'complete',v_complete);
end
$function$;

alter function private.bpay_next_preparation_authority_v1(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_preparation_args_v1(jsonb,text[]) OWNER TO CURRENT_USER;
alter function public.bpay_next_preparation_intake_v1(uuid,text,jsonb) OWNER TO CURRENT_USER;
alter function public.bpay_next_preparation_page_v1(uuid,text,jsonb) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_preparation_authority_v1(uuid),
  private.bpay_next_preparation_args_v1(jsonb,text[]),
  public.bpay_next_preparation_intake_v1(uuid,text,jsonb),public.bpay_next_preparation_page_v1(uuid,text,jsonb)
  from public,anon,authenticated,service_role;
grant execute on function public.bpay_next_preparation_intake_v1(uuid,text,jsonb),
  public.bpay_next_preparation_page_v1(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';


-- Current ordinary / genuine head-bound Source PAYE WORK collection and exact original recovery/cancel
-- links. No history lookup, manual schedule, forgiveness or frozen repricing.





-- This point reader validates the applied/captured economic observation, not
-- WORK.current_revision_id. A later accepted approval may queue behind the
-- frozen PREPARE owner without invalidating its immutable offer.
create or replace function private.bpay_next_work_collection_origin_v1(
  p_case_id uuid,p_component_id uuid,p_candidate_id uuid
) returns private.bpay_next_work_collection
language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_basis private.bpay_next_work_collection%rowtype;v_cmp uuid;
begin
  select p.source_comparison_receipt_id into v_cmp from private.bpay_next_work_collection b
    join private.bpay_next_position p on p.work_id=b.work_id and p.component_key=b.component_key
    where b.case_id=p_case_id and b.case_component_id=p_component_id and b.candidate_id=p_candidate_id;
  if v_cmp is not null then
    return private.bpay_next_source_comparison_collection_origin_v2(v_cmp,p_candidate_id);
  end if;
  select b.* into v_basis from private.bpay_next_work_collection b
    join private.bpay_next_position p on p.work_id=b.work_id and p.component_key=b.component_key
    join private.bpay_next_work_revision r on r.id=p.applied_revision_id and r.work_id=b.work_id
    join private.bpay_next_work_revision original on original.id=b.original_revision_id and original.work_id=b.work_id
    join private.bpay_next_work work on work.id=b.work_id and work.candidate_id=b.candidate_id
    join private.bpay_next_approved_line original_line on original_line.id=b.original_approved_line_id
      and original_line.revision_id=original.id and original_line.component_key=b.component_key
    join private.bpay_next_finance_case c on c.id=b.case_id and c.candidate_id=b.candidate_id
    join private.bpay_next_case_component x on x.id=b.case_component_id and x.case_id=c.id and x.candidate_id=c.candidate_id
    join private.bpay_next_case_rule rule on rule.id=x.rule_id and rule.case_id=c.id and rule.candidate_id=c.candidate_id
    where b.case_id=p_case_id and b.case_component_id=p_component_id and b.candidate_id=p_candidate_id
      and b.id=b.case_id and b.id=b.case_component_id and b.paid_basis_qualified
      and b.qualification_state='READY' and b.original_source_pay_channel='PAYE' and b.original_tax_treatment='TAXABLE'
      and (b.observed_revision_id,b.observed_approved_source_ex_vat,b.observed_realised_source_ex_vat)
        is not distinct from (p.applied_revision_id,p.approved_source_ex_vat,p.realised_source_ex_vat)
      and p.source_basis_channel='PAYE' and p.approved_source_ex_vat>=0 and p.realised_source_ex_vat>=0
      and (p.realised_target_ex_vat,p.realised_target_vat,p.realised_target_inc_vat)
        is not distinct from (p.realised_source_ex_vat,0::numeric,p.realised_source_ex_vat)
      and ((work.work_kind='ORDINARY' and original.source_kind='ORDINARY' and r.source_kind='ORDINARY')
        or (work.work_kind='SOURCE' and original_line.component_kind='WORK'
          and original_line.source_component_id is not null
          and b.component_key='SOURCE:'||original_line.source_component_id::text
          and ((original.source_kind='SOURCE' and original.source_event_id is not null
            and (original.source_head_id is null or original.source_event_id=original.source_head_id)) or (original.source_kind='PROTECTED'
            and original.source_head_id is not null and original.source_event_id=original.source_head_id))
          and ((r.source_kind='SOURCE' and r.source_event_id is not null
            and (r.source_head_id is null or r.source_event_id=r.source_head_id)) or (r.source_kind='PROTECTED'
            and r.source_head_id is not null and r.source_event_id=r.source_head_id))))
      and r.source_pay_channel='PAYE' and r.sealed_at_utc is not null
      and ((r.detail_kind=original.detail_kind and exists(select 1 from private.bpay_next_approved_line a
        where a.revision_id=r.id and a.component_key=b.component_key and a.component_kind='WORK'
          and a.tax_treatment='TAXABLE' and a.source_pay_ex_vat=p.approved_source_ex_vat
          and (work.work_kind='ORDINARY' or a.source_component_id=original_line.source_component_id)))
        or (r.certified_zero and r.approved_source_ex_vat=0 and r.expected_line_count=0 and p.approved_source_ex_vat=0))
      and c.case_kind='OVERPAYMENT' and c.tax_treatment='TAXABLE' and c.principal_funded=0
      and x.case_kind='OVERPAYMENT' and x.case_subtype='OVERPAYMENT' and x.tax_treatment='TAXABLE'
      and x.source_pay_channel='PAYE' and x.instruction_kind='RECOVERY' and x.direction='DEDUCTION'
      and x.payroll_stage='GROSS_DEDUCT' and x.component_key='RECOVERY' and x.component_ordinal=1
      and c.current_rule_id=rule.id and c.current_rule_revision=rule.rule_revision and rule.id=b.id
      and rule.weekly_due_source_ex_vat is null
      and (c.principal_approved,c.principal_recovered,c.principal_written_off,c.active_recovery_hold_amount)
        is not distinct from (x.approved_source_ex_vat,x.recovered_source_ex_vat,x.written_off_source_ex_vat,x.active_recovery_source_ex_vat);
  return v_basis;
end
$function$;

-- Captured managed rows are real typed positions; they can only transition
-- once through ALLOCATE. The separate worker counters conserve both lanes.
create or replace function private.bpay_next_work_collection_capture_guard_v1()
returns trigger language plpgsql set search_path=pg_catalog,private
as $function$
declare v_basis private.bpay_next_work_collection%rowtype;v_cmp private.bpay_next_source_comparison_receipt%rowtype;
  v_binding private.bpay_next_source_component_binding_version%rowtype;v_zero boolean;
begin
  if tg_table_name='bpay_next_run_position' and tg_op in ('INSERT','UPDATE') and new.source_comparison_receipt_id is not null
    and (new.work_collection_id is not null or new.managed_capture_completed or
      (new.approved_line_id is null and new.selected_residual_ex_vat=0)) then
    select * into strict v_cmp from private.bpay_next_source_comparison_receipt where id=new.source_comparison_receipt_id;
    select * into strict v_binding from private.bpay_next_source_component_binding_version where id=v_cmp.source_binding_version_id;
    v_zero:=v_binding.component_state='REMOVED' and v_cmp.approved_line_id is null
      and new.approved_line_id is null and new.work_collection_id is null
      and (v_cmp.approved_source_ex_vat,v_cmp.comparable_paid_ex_vat,v_cmp.comparable_held_ex_vat,v_cmp.selected_residual_ex_vat)
        =(0::numeric,0::numeric,0::numeric,0::numeric)
      and (v_cmp.case_basis is null or ((v_cmp.case_basis->>'J')::numeric=0
        and (v_cmp.case_basis->>'P')::numeric=(v_cmp.case_basis->>'K')::numeric+(v_cmp.case_basis->>'W')::numeric))
      and v_cmp.case_basis is not distinct from private.bpay_next_source_comparison_case_basis_snapshot_v2(v_cmp.canonical_work_id,v_cmp.canonical_component_key);
    if v_cmp.qualification_state<>'READY' or new.needs_financial_resolution
      or (new.source_binding_version_id,new.canonical_source_work_id,new.canonical_source_component_key,new.source_book_revision,
        new.work_id,new.component_key,new.captured_revision_id,new.approved_line_id,new.source_pay_channel,
        new.approved_source_ex_vat,new.comparable_paid_ex_vat,new.comparable_held_ex_vat,new.selected_residual_ex_vat,new.residual_source_ex_vat)
        is distinct from (v_cmp.source_binding_version_id,v_cmp.canonical_work_id,v_cmp.canonical_component_key,v_cmp.source_book_revision,
          v_cmp.approval_work_id,v_cmp.approval_component_key,v_cmp.approval_revision_id,v_cmp.approved_line_id,v_cmp.target_pay_channel,
          v_cmp.approved_source_ex_vat,v_cmp.comparable_paid_ex_vat,v_cmp.comparable_held_ex_vat,v_cmp.selected_residual_ex_vat,v_cmp.selected_residual_ex_vat)
      or not exists(select 1 from private.bpay_next_position p where p.work_id=v_cmp.canonical_work_id
        and p.component_key=v_cmp.canonical_component_key and p.source_comparison_receipt_id=v_cmp.id
        and private.bpay_next_source_comparison_book_certified_v2(p)) then
      raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CAPTURE_INVALID' using errcode='23514';end if;
    if not coalesce(v_zero,false) then
      v_basis:=private.bpay_next_source_comparison_collection_origin_v2(v_cmp.id,v_cmp.candidate_id);
      if new.work_collection_id is distinct from v_basis.id or new.work_collection_revision is distinct from v_basis.reconcile_revision
        or v_cmp.selected_residual_ex_vat>=0 or v_cmp.comparable_paid_ex_vat<=v_cmp.approved_source_ex_vat then
        raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CAPTURE_ORIGIN_INVALID' using errcode='23514';end if;
    end if;
    if tg_op='INSERT' then
      if new.managed_capture_completed then raise exception 'BPAY_NEXT_COLLECTION_CAPTURE_IMMUTABLE';end if;
    elsif old.managed_capture_completed or not new.managed_capture_completed
      or (to_jsonb(new)-'managed_capture_completed') is distinct from (to_jsonb(old)-'managed_capture_completed') then
      raise exception 'BPAY_NEXT_COLLECTION_CAPTURE_IMMUTABLE';end if;
  if not exists(select 1 from private.bpay_next_run_work rw
    join private.bpay_next_run_worker w on w.id=rw.run_worker_id and w.status='PREPARING'
    join private.bpay_next_run_command rc on rc.run_id=w.run_id
    join private.bpay_next_job j on j.command_id=rc.command_id and j.candidate_id=w.candidate_id
    join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id and c.active_owner_epoch=j.owner_epoch
    join private.bpay_next_module_control m on m.id=1 and m.active_owner='NEXT' and m.owner_epoch=j.module_epoch
    where rw.id=new.run_work_id and rw.run_worker_id=new.run_worker_id and rw.work_id=new.work_id
      and rw.captured_revision_id=new.captured_revision_id and j.job_kind='PREPARE' and j.status='LEASED'
      and j.phase=case when tg_op='INSERT' then 'RESERVE' else 'ALLOCATE' end
      and j.lease_until_utc>pg_catalog.clock_timestamp()) then
    raise exception using errcode='55000',message='BPAY_NEXT_COLLECTION_CAPTURE_OWNER_STALE';
  end if;
    return new;
  end if;
  if tg_table_name='bpay_next_case_period' then
    if tg_op='UPDATE' then
      if new.work_collection_id is distinct from old.work_collection_id then
        raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_PERIOD_ORIGIN_IMMUTABLE';
      end if;
      if new.work_collection_id is not null and
         ((new.case_component_id,new.case_id,new.candidate_id,new.pay_week_start,new.rule_id,
           new.opening_outstanding_source_ex_vat,new.opening_due_source_ex_vat)
           is distinct from (old.case_component_id,old.case_id,old.candidate_id,old.pay_week_start,old.rule_id,
             old.opening_outstanding_source_ex_vat,old.opening_due_source_ex_vat)
          or new.period_revision<>old.period_revision+1
          or new.realised_recovery_source_ex_vat<old.realised_recovery_source_ex_vat
          or new.active_payout_source_ex_vat<>0
          or not exists(select 1 from private.bpay_next_case_component x
            join private.bpay_next_finance_case c on c.id=x.case_id and c.candidate_id=x.candidate_id
            where x.id=new.case_component_id and x.id=new.work_collection_id
              and x.case_id=new.case_id and x.candidate_id=new.candidate_id
              and x.recovered_source_ex_vat>=new.realised_recovery_source_ex_vat
              and x.active_recovery_source_ex_vat>=new.active_unrealised_recovery_source_ex_vat
              and (c.principal_approved,c.principal_recovered,c.principal_written_off,c.active_recovery_hold_amount)
                is not distinct from (x.approved_source_ex_vat,x.recovered_source_ex_vat,x.written_off_source_ex_vat,x.active_recovery_source_ex_vat))) then
        raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_PERIOD_COUNTER_INVALID';
      end if;
      return new;
    end if;
    if new.work_collection_id is null then
      if exists(select 1 from private.bpay_next_work_collection b where b.case_id=new.case_id) then
        raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_PERIOD_ORIGIN_REQUIRED';
      end if;
      return new;
    end if;
    v_basis:=private.bpay_next_work_collection_origin_v1(new.case_id,new.case_component_id,new.candidate_id);
    if v_basis.id is distinct from new.work_collection_id then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_PERIOD_ORIGIN_INVALID';
    end if;
    return new;
  end if;
  if tg_table_name='bpay_next_run_case_instruction' then
    if new.work_collection_id is null then
      if exists(select 1 from private.bpay_next_work_collection b where b.case_id=new.case_id) then
        raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_INSTRUCTION_ORIGIN_REQUIRED';
      end if;
      return new;
    end if;
    v_basis:=private.bpay_next_work_collection_origin_v1(new.case_id,new.case_component_id,new.candidate_id);
    if v_basis.id is distinct from new.work_collection_id
       or (new.source_comparison_receipt_id is null and new.valuation_policy_id is distinct from v_basis.original_valuation_policy_id)
       or (new.source_comparison_receipt_id is not null and not exists(
         select 1 from private.bpay_next_source_comparison_receipt r
         where r.id=new.source_comparison_receipt_id and r.candidate_id=new.candidate_id and r.work_collection_id=v_basis.id
           and r.case_id=new.case_id and r.case_component_id=new.case_component_id
           and r.source_binding_version_id=new.source_binding_version_id and r.comparison_policy_id=new.valuation_policy_id
           and r.target_pay_channel=new.target_pay_channel and r.case_basis->>'case_source_channel'=new.source_pay_channel)) then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_INSTRUCTION_ORIGIN_INVALID';
    end if;
    return new;
  end if;
  if tg_op<>'INSERT' then
    if tg_op<>'UPDATE' or old.work_collection_id is null or old.managed_capture_completed
       or not new.managed_capture_completed
       or (pg_catalog.to_jsonb(new)-'managed_capture_completed')
         is distinct from (pg_catalog.to_jsonb(old)-'managed_capture_completed') then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_IMMUTABLE';
    end if;
  elsif new.work_collection_id is null then
    return new;
  else
    select b.* into strict v_basis from private.bpay_next_work_collection b where b.id=new.work_collection_id;
    v_basis:=private.bpay_next_work_collection_origin_v1(v_basis.case_id,v_basis.case_component_id,v_basis.candidate_id);
    if v_basis.id is distinct from new.work_collection_id or new.managed_capture_completed
       or new.work_collection_revision is distinct from v_basis.reconcile_revision
       or (new.captured_revision_id,new.approved_source_ex_vat,new.realised_source_ex_vat)
         is distinct from (v_basis.observed_revision_id,v_basis.observed_approved_source_ex_vat,v_basis.observed_realised_source_ex_vat)
       or new.source_pay_channel<>'PAYE' or new.source_basis_channel is distinct from 'PAYE'
       or (new.held_source_ex_vat,new.held_target_ex_vat,new.held_target_vat,new.held_target_inc_vat)
         is distinct from (0::numeric,0::numeric,0::numeric,0::numeric) then
      raise exception using errcode='23514',message='BPAY_NEXT_COLLECTION_CAPTURE_ORIGIN_INVALID';
    end if;
  end if;
  if not exists(select 1 from private.bpay_next_run_work rw
    join private.bpay_next_run_worker w on w.id=rw.run_worker_id and w.status='PREPARING'
    join private.bpay_next_run_command rc on rc.run_id=w.run_id
    join private.bpay_next_job j on j.command_id=rc.command_id and j.candidate_id=w.candidate_id
    join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id and c.active_owner_epoch=j.owner_epoch
    join private.bpay_next_module_control m on m.id=1 and m.active_owner='NEXT' and m.owner_epoch=j.module_epoch
    where rw.id=new.run_work_id and rw.run_worker_id=new.run_worker_id and rw.work_id=new.work_id
      and rw.captured_revision_id=new.captured_revision_id and j.job_kind='PREPARE' and j.status='LEASED'
      and j.phase=case when tg_op='INSERT' then 'RESERVE' else 'ALLOCATE' end
      and j.lease_until_utc>pg_catalog.clock_timestamp()) then
    raise exception using errcode='55000',message='BPAY_NEXT_COLLECTION_CAPTURE_OWNER_STALE';
  end if;
  return new;
end
$function$;

create or replace function private.bpay_next_work_collection_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
declare v_effect private.bpay_next_financial_effect%rowtype;
  v_line private.bpay_next_run_line%rowtype;
begin
  if tg_op='DELETE' then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_DELETE_FORBIDDEN';
  end if;
  if tg_op='UPDATE' then
    if (new.id,new.work_id,new.component_key,new.candidate_id,new.original_effect_id,
        new.original_run_line_id,new.original_revision_id,new.original_approved_line_id,
        new.original_transfer_id,new.original_source_pay_channel,new.original_tax_treatment,
        new.original_valuation_policy_id,new.created_at_utc)
       is distinct from
       (old.id,old.work_id,old.component_key,old.candidate_id,old.original_effect_id,
        old.original_run_line_id,old.original_revision_id,old.original_approved_line_id,
        old.original_transfer_id,old.original_source_pay_channel,old.original_tax_treatment,
        old.original_valuation_policy_id,old.created_at_utc)
       or (old.case_id is not null and (new.case_id,new.case_component_id)
           is distinct from (old.case_id,old.case_component_id))
       or (not old.paid_basis_qualified and new.paid_basis_qualified)
       or new.reconcile_revision<>old.reconcile_revision+1 then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_BASIS_IMMUTABLE';
    end if;
  elsif new.reconcile_revision<>1 or new.case_id is not null
      or new.last_effect_id is distinct from new.original_effect_id then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_INITIAL_STATE_INVALID';
  end if;
  select e.* into strict v_effect from private.bpay_next_financial_effect e where e.id=new.original_effect_id;
  select l.* into strict v_line from private.bpay_next_run_line l where l.id=new.original_run_line_id;
  if tg_op='INSERT' and not exists(select 1 from private.bpay_next_job j
      where j.id=new.last_job_id and j.command_id=v_effect.operation_id
        and j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT')) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_INITIAL_OWNER_INVALID';
  end if;
  if v_effect.effect_kind<>'PAYROLL_SETTLED' or v_effect.source_disposition_ex_vat<=0
     or (v_effect.work_id,v_effect.component_key,v_effect.candidate_id,v_effect.original_transfer_id)
       is distinct from (new.work_id,new.component_key,new.candidate_id,new.original_transfer_id)
     or (v_line.work_id,v_line.component_key,v_line.captured_revision_id,v_line.approved_line_id,
         v_line.source_pay_channel,v_line.valuation_policy_id)
       is distinct from (new.work_id,new.component_key,new.original_revision_id,new.original_approved_line_id,
         new.original_source_pay_channel,new.original_valuation_policy_id)
     or (v_line.target_pay_channel<>'PAYE' and not private.bpay_next_work_collection_source_original_v2(new))
     or (v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat)
       is distinct from (v_line.source_consumed_ex_vat,v_line.frozen_ex_vat,v_line.frozen_vat,v_line.frozen_inc_vat)
     or not exists(select 1 from private.bpay_next_hold h
       where h.id=v_effect.operation_item_id and h.run_line_id=v_line.id and h.status='REALISED'
         and h.source_reserved_ex_vat=v_effect.source_disposition_ex_vat
         and h.source_reserved_ex_vat=v_line.source_consumed_ex_vat)
     or not exists(select 1 from private.bpay_next_approved_line a
       join private.bpay_next_work_revision r on r.id=a.revision_id
       join private.bpay_next_work w on w.id=r.work_id
       where a.id=new.original_approved_line_id and a.component_kind='WORK'
         and a.tax_treatment is not distinct from new.original_tax_treatment
         and w.id=new.work_id and a.component_key=new.component_key
         and ((r.source_kind='ORDINARY' and w.work_kind='ORDINARY')
           or (w.work_kind='SOURCE' and a.source_component_id is not null
             and a.component_key='SOURCE:'||a.source_component_id::text
             and ((r.source_kind='SOURCE' and r.source_event_id is not null
               and (r.source_head_id is null or r.source_event_id=r.source_head_id)) or (r.source_kind='PROTECTED'
               and r.source_head_id is not null and r.source_event_id=r.source_head_id)))))
     or not exists(select 1 from private.bpay_next_transfer_member m
       where m.transfer_id=new.original_transfer_id and m.run_line_id=v_line.id and m.subject_kind='WORK'
         and m.signed_cash_contribution=v_line.frozen_inc_vat) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_ORIGINAL_BASIS_INVALID';
  end if;
  if new.case_id is not null and
     (new.case_id<>new.id or new.case_component_id<>new.id or not exists(
       select 1 from private.bpay_next_finance_case c
       join private.bpay_next_case_component x on x.id=new.case_component_id and x.case_id=c.id
       join private.bpay_next_case_rule r on r.id=x.rule_id and r.case_id=c.id
       where c.id=new.case_id and c.candidate_id=new.candidate_id
         and c.case_kind='OVERPAYMENT' and c.tax_treatment='TAXABLE' and c.principal_funded=0
         and c.principal_approved=x.approved_source_ex_vat
         and c.principal_recovered=x.recovered_source_ex_vat
         and c.principal_written_off=x.written_off_source_ex_vat
         and c.active_recovery_hold_amount=x.active_recovery_source_ex_vat
         and x.candidate_id=c.candidate_id and x.component_key='RECOVERY' and x.component_ordinal=1
         and x.case_kind='OVERPAYMENT' and x.tax_treatment='TAXABLE'
         and (x.source_pay_channel='PAYE' or (private.bpay_next_work_collection_source_original_v2(new)
           and exists(select 1 from private.bpay_next_position p join private.bpay_next_source_comparison_receipt cmp on cmp.id=p.source_comparison_receipt_id
             where p.work_id=new.work_id and p.component_key=new.component_key and cmp.candidate_id=new.candidate_id
               and (cmp.target_pay_channel=x.source_pay_channel or cmp.case_basis->>'case_source_channel'=x.source_pay_channel))))
         and x.instruction_kind='RECOVERY' and x.payroll_stage='GROSS_DEDUCT'
         and c.current_rule_id=r.id and c.current_rule_revision=r.rule_revision
         and r.id=new.id and r.case_kind='OVERPAYMENT' and r.weekly_due_source_ex_vat is null)) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_CASE_OWNER_INVALID';
  end if;
  if not exists(select 1 from private.bpay_next_job j
     join private.bpay_next_worker_control c on c.candidate_id=j.candidate_id
     join private.bpay_next_module_control m on m.id=1 and m.active_owner='NEXT'
     where j.id=new.last_job_id and j.candidate_id=new.candidate_id
       and j.job_kind in ('POSITION_APPLY','CSV_SETTLEMENT','INTERNAL_SETTLEMENT','SIMPLE_CANCEL','PREPARATION_EXPIRY')
       and j.status='LEASED' and j.module_epoch=m.owner_epoch
       and j.owner_epoch=c.active_owner_epoch and j.lease_until_utc>pg_catalog.clock_timestamp()
       and ((j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') and j.phase='MEMBERS'
         and private.bpay_next_work_collection_source_original_v2(new)
         and exists(select 1 from private.bpay_next_position p
           join private.bpay_next_source_comparison_receipt cmp on cmp.id=p.source_comparison_receipt_id
           join private.bpay_next_financial_effect actual_effect on actual_effect.id=cmp.operation_effect_id
           where p.work_id=new.work_id and p.component_key=new.component_key
             and cmp.operation_job_id=j.id and cmp.operation_effect_id=new.last_effect_id
             and cmp.receipt_kind in ('SETTLE','CASE_RECOVERY') and cmp.candidate_id=new.candidate_id
             and actual_effect.operation_id=j.command_id and actual_effect.candidate_id=new.candidate_id
             and actual_effect.canonical_source_work_id=new.work_id and actual_effect.canonical_source_component_key=new.component_key
             and private.bpay_next_source_comparison_book_certified_v2(p)))
         or (j.job_kind='POSITION_APPLY' and j.phase in ('NEW','REMOVED') and new.last_effect_id is null
         and exists(select 1 from private.bpay_next_publication p where p.command_id=j.command_id
           and p.work_id=new.work_id and p.candidate_id=new.candidate_id
           and p.revision_id=new.observed_revision_id and p.status in ('QUEUED','APPLYING')))
         or (j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') and j.phase='MEMBERS'
           and exists(select 1 from private.bpay_next_financial_effect e
             join private.bpay_next_outcome_request r on r.command_id=j.command_id
             where e.id=new.last_effect_id and e.operation_id=j.command_id and e.effect_kind='PAYROLL_SETTLED'
               and e.work_id=new.work_id and e.component_key=new.component_key and e.candidate_id=new.candidate_id
               and e.original_transfer_id=r.transfer_id and e.source_disposition_ex_vat>0))
         or (j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') and j.phase='MEMBERS'
           and exists(select 1 from private.bpay_next_financial_effect e
             join private.bpay_next_case_event ce on ce.id=e.operation_item_id and ce.operation_id=j.command_id
             join private.bpay_next_run_case_instruction i on i.id=ce.instruction_id and i.work_collection_id=new.id
             join private.bpay_next_case_hold h on h.id=ce.operation_item_id and h.status='REALISED'
             join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='REALISED' and u.realisation_event_id=ce.id
             join private.bpay_next_outcome_request r on r.command_id=j.command_id and r.transfer_id=ce.original_transfer_id
             where e.id=new.last_effect_id and e.operation_id=j.command_id and e.effect_kind='WORK_COLLECTION_RECOVERED'
               and ce.event_kind='RECOVERED' and ce.case_id=new.case_id and ce.case_component_id=new.case_component_id
               and e.work_id=new.work_id and e.component_key=new.component_key and e.candidate_id=new.candidate_id
               and e.original_transfer_id=ce.original_transfer_id
               and (e.source_disposition_ex_vat,e.target_amount_ex_vat,e.target_amount_vat,e.target_amount_inc_vat)
                 is not distinct from (-ce.source_amount_ex_vat,-ce.target_amount_ex_vat,-ce.target_amount_vat,-ce.target_amount_inc_vat)))
         or (j.job_kind='PREPARATION_EXPIRY' and j.phase='RELEASE' and new.last_effect_id is null
           and (private.bpay_next_expired_work_collection_scope_v1(j.id,new.id,null)
             or (private.bpay_next_work_collection_source_original_v2(new) and exists(
               select 1 from private.bpay_next_position p
               join private.bpay_next_source_comparison_receipt cmp on cmp.id=p.source_comparison_receipt_id
               where p.work_id=new.work_id and p.component_key=new.component_key and cmp.work_collection_id=new.id
                 and cmp.receipt_kind='CASE_RELEASE' and cmp.operation_job_id=j.id and cmp.operation_case_hold_id is not null
                 and private.bpay_next_source_comparison_book_certified_v2(p)
                 and private.bpay_next_source_comparison_expired_case_scope_v2(j.id,new.id,cmp.operation_case_hold_id)))))
         or (j.job_kind='SIMPLE_CANCEL' and j.phase='RELEASE' and new.last_effect_id is null
           and exists(select 1 from private.bpay_next_case_cancel_binding cb
             join private.bpay_next_cancel_request r on r.command_id=cb.command_id and r.status='CANCELLING'
             join private.bpay_next_run_worker w on w.id=cb.run_worker_id and w.status='CANCELLING'
             join private.bpay_next_case_hold h on h.run_worker_id=w.id and h.status='RELEASED'
             join private.bpay_next_run_case_instruction i on i.id=h.instruction_id and i.work_collection_id=new.id
             join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='RELEASED'
             where cb.command_id=j.command_id and cb.candidate_id=new.candidate_id
               and cb.status='CANCELLING' and cb.stage='CASE'
               and i.case_id=new.case_id and i.case_component_id=new.case_component_id)))) then
    raise exception using errcode='55000',message='BPAY_NEXT_WORK_COLLECTION_OWNER_STALE';
  end if;
  if not exists(select 1 from private.bpay_next_position p
      where p.work_id=new.work_id and p.component_key=new.component_key
        and (p.applied_revision_id,p.approved_source_ex_vat,p.realised_source_ex_vat)
          is not distinct from (new.observed_revision_id,new.observed_approved_source_ex_vat,new.observed_realised_source_ex_vat)) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_OBSERVATION_INVALID';
  end if;
  return new;
end
$function$;

create or replace function private.bpay_next_work_collection_case_identity_guard_v1()
returns trigger language plpgsql
set search_path=pg_catalog,private
as $function$
begin
  if tg_table_name='bpay_next_finance_case' then
    if exists(select 1 from private.bpay_next_work_collection where case_id=old.id) and
       (new.id,new.candidate_id,new.case_kind,new.tax_treatment,new.current_rule_id,new.current_rule_revision)
         is distinct from (old.id,old.candidate_id,old.case_kind,old.tax_treatment,old.current_rule_id,old.current_rule_revision) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_CASE_IDENTITY_IMMUTABLE';
    end if;
  elsif exists(select 1 from private.bpay_next_work_collection where case_component_id=old.id) and
     (new.id,new.case_id,new.candidate_id,new.component_key,new.component_ordinal,new.rule_id,
       new.case_kind,new.case_subtype,new.tax_treatment,new.instruction_kind,new.direction,
       new.payroll_stage,new.source_pay_channel,new.currency)
       is distinct from
     (old.id,old.case_id,old.candidate_id,old.component_key,old.component_ordinal,old.rule_id,
       old.case_kind,old.case_subtype,old.tax_treatment,old.instruction_kind,old.direction,
       old.payroll_stage,old.source_pay_channel,old.currency) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_COMPONENT_IDENTITY_IMMUTABLE';
  end if;
  return new;
end
$function$;

create or replace function private.bpay_next_reconcile_work_collection_v1(
  p_job_id uuid,p_work_id uuid,p_component_key text,p_effect_id uuid default null
) returns void
language plpgsql security invoker
set search_path=pg_catalog,private
as $function$
declare
  v_epoch bigint;v_candidate uuid;v_control private.bpay_next_worker_control%rowtype;
  v_job private.bpay_next_job%rowtype;v_work private.bpay_next_work%rowtype;
  v_position private.bpay_next_position%rowtype;v_revision private.bpay_next_work_revision%rowtype;
  v_original_revision private.bpay_next_work_revision%rowtype;
  v_original_approved private.bpay_next_approved_line%rowtype;
  v_basis private.bpay_next_work_collection%rowtype;v_effect private.bpay_next_financial_effect%rowtype;
  v_line private.bpay_next_run_line%rowtype;v_approved private.bpay_next_approved_line%rowtype;
  v_case private.bpay_next_finance_case%rowtype;v_component private.bpay_next_case_component%rowtype;
  v_state text;v_qualified boolean;v_capturable boolean;v_supported_paid boolean;
  v_original_detail text;v_whole_zero boolean;v_paired_origin boolean;
  v_principal numeric;v_delta numeric;v_event text;
begin
  if p_job_id is null or p_work_id is null or p_component_key is null
     or pg_catalog.char_length(p_component_key) not between 1 and 256 then
    raise exception using errcode='22023',message='BPAY_NEXT_WORK_COLLECTION_INPUT_INVALID';
  end if;
  -- Parent owners already hold run (when applicable), Candidate control and
  -- job, in that order. These reentrant locks never acquire another run.
  select m.owner_epoch into v_epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if v_epoch is null then raise exception using errcode='55000',message='BPAY_NEXT_MODULE_NOT_ACTIVE';end if;
  select j.candidate_id into strict v_candidate from private.bpay_next_job j where j.id=p_job_id;
  select c.* into strict v_control from private.bpay_next_worker_control c where c.candidate_id=v_candidate for update;
  select j.* into strict v_job from private.bpay_next_job j where j.id=p_job_id for update;
  if v_job.status<>'LEASED' or v_job.module_epoch<>v_epoch
     or v_job.owner_epoch<>v_control.active_owner_epoch or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or exists(select 1 from private.bpay_next_job j where j.candidate_id=v_candidate
       and j.command_sequence<v_job.command_sequence and j.status<>'DONE') then
    raise exception using errcode='55000',message='BPAY_NEXT_WORK_COLLECTION_OWNER_STALE';
  end if;
  -- A comparison posting owns its actual B/C scalar; canonical A remains original origin.
  -- The same genuine leased1519 entry routes to its current flat canonical comparison.
  if p_effect_id is not null then
    select e.* into strict v_effect from private.bpay_next_financial_effect e where e.id=p_effect_id;
    if v_effect.canonical_source_work_id is not null and exists(select 1 from private.bpay_next_position p
      where p.work_id=v_effect.canonical_source_work_id and p.component_key=v_effect.canonical_source_component_key
        and p.source_comparison_receipt_id is not null) then
      perform private.bpay_next_reconcile_source_comparison_collection_v2(p_job_id,
        v_effect.canonical_source_work_id,v_effect.canonical_source_component_key,p_effect_id);
      return;
    end if;
  elsif exists(select 1 from private.bpay_next_position p where p.work_id=p_work_id
    and p.component_key=p_component_key and p.source_comparison_receipt_id is not null) then
    perform private.bpay_next_reconcile_source_comparison_collection_v2(p_job_id,p_work_id,p_component_key,null);
    return;
  end if;
  select w.* into strict v_work from private.bpay_next_work w where w.id=p_work_id and w.candidate_id=v_candidate;
  select p.* into strict v_position from private.bpay_next_position p
    where p.work_id=p_work_id and p.component_key=p_component_key for update;
  if v_job.job_kind='POSITION_APPLY' then
    if p_effect_id is not null or v_job.phase not in ('NEW','REMOVED') or not exists(
      select 1 from private.bpay_next_publication p where p.command_id=v_job.command_id
        and p.work_id=p_work_id and p.candidate_id=v_candidate and p.status in ('QUEUED','APPLYING')
        and p.revision_id=v_position.applied_revision_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_POSITION_SCOPE_INVALID';
    end if;
  elsif v_job.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') then
    if p_effect_id is null or v_job.phase<>'MEMBERS' then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_SETTLEMENT_SCOPE_INVALID';
    end if;
    select e.* into strict v_effect from private.bpay_next_financial_effect e where e.id=p_effect_id;
    if v_effect.effect_kind='WORK_COLLECTION_RECOVERED' then
      -- The negative WORK disposition is exactly the genuine posted CASE
      -- recovery, never a caller supplied negative or a cash-return inverse.
      if not exists(select 1 from private.bpay_next_work_collection b
        join private.bpay_next_case_event ce on ce.id=v_effect.operation_item_id and ce.case_id=b.case_id
        join private.bpay_next_run_case_instruction i on i.id=ce.instruction_id and i.work_collection_id=b.id
        join private.bpay_next_case_hold h on h.id=ce.operation_item_id and h.status='REALISED'
        join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='REALISED' and u.realisation_event_id=ce.id
        join private.bpay_next_outcome_request r on r.command_id=v_job.command_id and r.transfer_id=ce.original_transfer_id
        where b.work_id=p_work_id and b.component_key=p_component_key and b.candidate_id=v_candidate
          and ce.operation_id=v_job.command_id and ce.event_kind='RECOVERED'
          and ce.case_component_id=b.case_component_id and ce.source_amount_ex_vat>0
          and v_effect.operation_id=v_job.command_id and v_effect.work_id=b.work_id
          and v_effect.component_key=b.component_key and v_effect.candidate_id=b.candidate_id
          and v_effect.case_id=b.case_id and v_effect.original_transfer_id=ce.original_transfer_id
          and (v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat)
            is not distinct from (-ce.source_amount_ex_vat,-ce.target_amount_ex_vat,-ce.target_amount_vat,-ce.target_amount_inc_vat)) then
        raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_SCOPE_INVALID';
      end if;
      v_capturable:=false;v_supported_paid:=true;
    else
    select l.* into strict v_line from private.bpay_next_hold h
      join private.bpay_next_run_line l on l.id=h.run_line_id
      join private.bpay_next_outcome_request r on r.command_id=v_job.command_id
      join private.bpay_next_transfer t on t.id=r.transfer_id
      where h.id=v_effect.operation_item_id and h.status='REALISED'
        and l.run_worker_id=r.run_worker_id and l.work_id=p_work_id and l.component_key=p_component_key
        and t.id=v_effect.original_transfer_id and t.candidate_id=v_candidate
        and t.original_transfer_id is null and t.return_cash_id is null
        and ((v_job.job_kind='CSV_SETTLEMENT' and t.execution_kind='BANK' and t.status in ('SETTLED','RETURNED'))
          or (v_job.job_kind='INTERNAL_SETTLEMENT' and t.execution_kind='INTERNAL_ZERO' and t.status='INTERNAL_PROCESSING'));
    if v_effect.operation_id<>v_job.command_id or v_effect.effect_kind<>'PAYROLL_SETTLED'
       or (v_effect.work_id,v_effect.component_key,v_effect.candidate_id)
         is distinct from (p_work_id,p_component_key,v_candidate)
       or v_effect.source_disposition_ex_vat<>v_line.source_consumed_ex_vat
       or v_effect.source_disposition_ex_vat<=0 then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_EFFECT_SCOPE_INVALID';
    end if;
    select a.* into strict v_approved from private.bpay_next_approved_line a where a.id=v_line.approved_line_id;
    -- Original ordinary or genuine Source PAYE -> PAYE WORK only. NULL
    -- tax is capturable as exact UNBOUND evidence, never inferred taxable.
    -- Do not return before checking an existing link: a later unsupported
    -- actual posting invalidates its paid qualification, not the payment.
    v_capturable:=v_work.work_kind='ORDINARY' and v_approved.component_kind='WORK'
      and v_line.source_pay_channel='PAYE' and v_line.target_pay_channel='PAYE'
      and exists(select 1 from private.bpay_next_work_revision r
        where r.id=v_line.captured_revision_id and r.source_kind='ORDINARY');
    -- PROTECTED is admitted only for 1550's actual committed-head branch;
    -- 0345's independent/headless protected target is not this authority.
    v_capturable:=v_capturable or (v_work.work_kind='SOURCE' and v_approved.component_kind='WORK'
      and v_approved.source_component_id is not null
      and v_approved.component_key='SOURCE:'||v_approved.source_component_id::text
      and v_line.source_pay_channel='PAYE' and v_line.target_pay_channel='PAYE'
      and exists(select 1 from private.bpay_next_work_revision r
        where r.id=v_line.captured_revision_id and r.work_id=v_work.id
          and ((r.source_kind='SOURCE' and r.source_event_id is not null
            and (r.source_head_id is null or r.source_event_id=r.source_head_id)) or (r.source_kind='PROTECTED'
            and r.source_head_id is not null and r.source_event_id=r.source_head_id))));
    -- Initial genuine Source UM original is captured at its actual settlement,
    -- before any comparison exists. Never enumerate/backfill historical payment.
    v_capturable:=v_capturable or (v_work.work_kind='SOURCE' and v_approved.component_kind='WORK'
      and v_approved.tax_treatment='TAXABLE' and v_line.source_binding_version_id is not null
      and v_line.canonical_source_work_id=p_work_id and v_line.canonical_source_component_key=p_component_key
      and v_line.source_pay_channel in ('PAYE','UMBRELLA') and v_line.target_pay_channel=v_line.source_pay_channel
      and exists(select 1 from private.bpay_next_position p where p.work_id=p_work_id and p.component_key=p_component_key
        and p.source_book_state='READY' and p.source_basis_channel=v_line.source_pay_channel
        and p.realised_source_ex_vat=v_effect.source_disposition_ex_vat
        and (case when v_line.source_pay_channel='PAYE' then
          (p.native_realised_paye,p.native_realised_umbrella)=(v_effect.source_disposition_ex_vat,0::numeric) and p.native_held_umbrella=0
          else (p.native_realised_umbrella,p.native_realised_paye)=(v_effect.source_disposition_ex_vat,0::numeric) and p.native_held_paye=0 end)));
    v_supported_paid:=v_capturable and v_approved.tax_treatment is not distinct from 'TAXABLE';
    end if;
  elsif v_job.job_kind='SIMPLE_CANCEL' then
    if p_effect_id is not null or v_job.phase<>'RELEASE' or not exists(
      select 1 from private.bpay_next_work_collection b
      join private.bpay_next_case_cancel_binding cb on cb.command_id=v_job.command_id and cb.candidate_id=b.candidate_id
      join private.bpay_next_cancel_request r on r.command_id=cb.command_id and r.status='CANCELLING'
      join private.bpay_next_run_worker w on w.id=cb.run_worker_id and w.status='CANCELLING'
      join private.bpay_next_case_hold h on h.run_worker_id=w.id and h.status='RELEASED'
      join private.bpay_next_run_case_instruction i on i.id=h.instruction_id and i.work_collection_id=b.id
      join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='RELEASED'
      where b.work_id=p_work_id and b.component_key=p_component_key and b.candidate_id=v_candidate
        and cb.status='CANCELLING' and cb.stage='CASE'
        and i.case_id=b.case_id and i.case_component_id=b.case_component_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_CANCEL_SCOPE_INVALID';
    end if;
  elsif v_job.job_kind='PREPARATION_EXPIRY' then
    if p_effect_id is not null or v_job.phase<>'RELEASE' or not exists(
      select 1 from private.bpay_next_work_collection b
      where b.work_id=p_work_id and b.component_key=p_component_key and b.candidate_id=v_candidate
        and private.bpay_next_expired_work_collection_scope_v1(p_job_id,b.id,null)) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_EXPIRY_SCOPE_INVALID';
    end if;
  else
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_JOB_KIND_INVALID';
  end if;
  select b.* into v_basis from private.bpay_next_work_collection b
    where b.work_id=p_work_id and b.component_key=p_component_key for update;
  if not found then
    -- An unpaid hold is not realised money. Existing pre-install paid rows
    -- have no invented basis/backfill; future actual settlement captures it.
    if p_effect_id is null or not v_capturable then return;end if;
    insert into private.bpay_next_work_collection
      (work_id,component_key,candidate_id,original_effect_id,original_run_line_id,
       original_revision_id,original_approved_line_id,original_transfer_id,
       original_source_pay_channel,original_tax_treatment,paid_basis_qualified,original_valuation_policy_id,
       qualification_state,observed_revision_id,observed_approved_source_ex_vat,observed_realised_source_ex_vat,last_job_id,last_effect_id)
      values(p_work_id,p_component_key,v_candidate,p_effect_id,v_line.id,v_line.captured_revision_id,
        v_line.approved_line_id,v_effect.original_transfer_id,v_line.source_pay_channel,v_approved.tax_treatment,
        v_approved.tax_treatment is not distinct from 'TAXABLE'
          and v_position.realised_source_ex_vat=v_effect.source_disposition_ex_vat,v_line.valuation_policy_id,
        'CURRENT_APPROVAL_UNBOUND',v_position.applied_revision_id,v_position.approved_source_ex_vat,
        v_position.realised_source_ex_vat,p_job_id,p_effect_id) returning * into v_basis;
  elsif v_basis.last_job_id=p_job_id and
      not (p_effect_id is not null and v_effect.effect_kind='WORK_COLLECTION_RECOVERED'
        and v_basis.last_effect_id is distinct from p_effect_id) then
    if (v_basis.observed_revision_id,v_basis.observed_approved_source_ex_vat,v_basis.observed_realised_source_ex_vat,v_basis.last_effect_id)
       is distinct from (v_position.applied_revision_id,v_position.approved_source_ex_vat,v_position.realised_source_ex_vat,p_effect_id) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_SAME_JOB_CHANGED';
    end if;
    return;
  end if;
  v_qualified:=v_basis.paid_basis_qualified;
  if p_effect_id is not null and not v_supported_paid then v_qualified:=false;end if;
  select r.* into strict v_revision from private.bpay_next_work_revision r where r.id=v_position.applied_revision_id;
  select r.detail_kind into strict v_original_detail from private.bpay_next_work_revision r
    where r.id=v_basis.original_revision_id and r.work_id=p_work_id;
  select r.* into strict v_original_revision from private.bpay_next_work_revision r
    where r.id=v_basis.original_revision_id and r.work_id=p_work_id;
  select a.* into strict v_original_approved from private.bpay_next_approved_line a
    where a.id=v_basis.original_approved_line_id and a.revision_id=v_original_revision.id;
  v_paired_origin:=(v_work.work_kind='ORDINARY' and v_original_revision.source_kind='ORDINARY'
      and v_revision.source_kind='ORDINARY')
    or (v_work.work_kind='SOURCE' and v_original_approved.component_kind='WORK'
      and v_original_approved.source_component_id is not null
      and p_component_key='SOURCE:'||v_original_approved.source_component_id::text
      and ((v_original_revision.source_kind='SOURCE' and v_original_revision.source_event_id is not null
        and (v_original_revision.source_head_id is null
        or v_original_revision.source_event_id=v_original_revision.source_head_id)) or (v_original_revision.source_kind='PROTECTED'
        and v_original_revision.source_head_id is not null
        and v_original_revision.source_event_id=v_original_revision.source_head_id))
      and ((v_revision.source_kind='SOURCE' and v_revision.source_event_id is not null
        and (v_revision.source_head_id is null
        or v_revision.source_event_id=v_revision.source_head_id)) or (v_revision.source_kind='PROTECTED'
        and v_revision.source_head_id is not null and v_revision.source_event_id=v_revision.source_head_id)));
  -- Absence of a DAY key does not prove removal: an AGGREGATE or another
  -- business-date component may retain the entitlement. This first slice
  -- qualifies unchanged typed identity only. A genuinely sealed, certified
  -- whole-base empty zero is the sole missing-key exception; reconciliation
  -- across representations remains explicitly UNBOUND, not discarded.
  v_whole_zero:=v_revision.sealed_at_utc is not null and v_revision.certified_zero
    and v_revision.approved_source_ex_vat=0 and v_revision.expected_line_count=0;
  if v_basis.original_tax_treatment is distinct from 'TAXABLE' then v_state:='ORIGINAL_TAX_UNBOUND';
  elsif not v_qualified then v_state:='PAID_BASIS_UNBOUND';
  elsif v_job.job_kind not in ('SIMPLE_CANCEL','PREPARATION_EXPIRY') and v_effect.effect_kind is distinct from 'WORK_COLLECTION_RECOVERED'
      and (v_work.approval_state<>'APPROVED'
        or v_work.current_revision_id is distinct from v_position.applied_revision_id) then
    v_state:='CURRENT_APPROVAL_UNBOUND';
  elsif v_paired_origin is not true or v_revision.source_pay_channel<>'PAYE'
      or v_position.source_basis_channel is distinct from 'PAYE'
      or (not v_whole_zero and (v_revision.detail_kind<>v_original_detail
        or not exists(select 1 from private.bpay_next_approved_line a
          where a.revision_id=v_revision.id and a.component_key=p_component_key
            and a.component_kind='WORK' and a.tax_treatment='TAXABLE'
            and (v_work.work_kind='ORDINARY'
              or a.source_component_id=v_original_approved.source_component_id)))) then
    v_state:='CURRENT_SOURCE_UNBOUND';
  elsif v_position.approved_source_ex_vat<0 or v_position.realised_source_ex_vat<0 then v_state:='SIGNED_SOURCE_UNBOUND';
  else v_state:='READY';end if;
  if v_work.work_kind='SOURCE' and v_revision.source_head_id is not null and not exists (
    select 1 from private.bpay_next_source_component_binding b
      join private.bpay_next_source_component_binding_version v on v.id=b.current_binding_version_id
      join private.weekly_source_entitlement_publication_receipts receipt on receipt.id=v.source_receipt_id
      join public.weekly_source_entitlement_decision_bundles bundle on bundle.decision_bundle_id=v.decision_bundle_id
        and bundle.bundle_revision=v.bundle_revision and bundle.state='COMMITTED'
      join public.weekly_source_entitlement_heads head on head.id=v.head_id and head.state='COMMITTED_CURRENT'
      join public.weekly_source_root_authorisations auth on auth.current_entitlement_head_id=head.id
        and auth.root_timesheet_id=head.root_timesheet_id and auth.withdrawn_at_utc is null
      join private.bpay_next_publication publication on publication.command_id=v.publication_command_id_1
        and publication.work_id=v.approval_work_id and publication.revision_id=v.approval_revision_id
        and publication.candidate_id=v_candidate
      where b.canonical_work_id=p_work_id and b.canonical_component_key=p_component_key
        and v.approval_work_id=p_work_id and v.approval_component_key=p_component_key
        and v.approval_revision_id=v_position.applied_revision_id
        and v.head_id=v_revision.source_head_id and v_revision.source_event_id=v.head_id
        and v.publication_command_id_2 is null and v.candidate_id=v_candidate
        and v.approval_source_channel='PAYE' and v.tax_treatment='TAXABLE'
        and receipt.decision_bundle_id=v.decision_bundle_id and receipt.bundle_revision=v.bundle_revision
        and receipt.request_digest=v.request_digest and pg_catalog.cardinality(receipt.head_ids)=1
        and receipt.head_ids[1]=v.head_id and v_work.current_revision_id=v.approval_revision_id
        and ((v_job.job_kind='POSITION_APPLY' and publication.command_id=v_job.command_id
              and publication.status in ('QUEUED','APPLYING'))
          or (v_job.job_kind<>'POSITION_APPLY' and publication.status='APPLIED' and publication.phase='DONE'))
  ) then v_state:='CURRENT_SOURCE_UNBOUND';end if;
  if v_state='READY' then
    if v_basis.case_id is null then
      v_principal:=greatest(v_position.realised_source_ex_vat-v_position.approved_source_ex_vat,0);
      if v_principal>0 then
        insert into private.bpay_next_finance_case
          (id,candidate_id,case_kind,tax_treatment,status,principal_approved,order_key,case_revision)
          values(v_basis.id,v_candidate,'OVERPAYMENT','TAXABLE','OPEN',v_principal,v_job.command_sequence,1);
        insert into private.bpay_next_case_rule
          (id,case_id,candidate_id,rule_revision,case_kind,case_subtype,tax_treatment,case_created_at_utc)
          values(v_basis.id,v_basis.id,v_candidate,1,'OVERPAYMENT','OVERPAYMENT','TAXABLE',pg_catalog.transaction_timestamp());
        update private.bpay_next_finance_case set current_rule_id=v_basis.id,current_rule_revision=1 where id=v_basis.id;
        insert into private.bpay_next_case_component
          (id,case_id,candidate_id,component_key,component_ordinal,component_revision,rule_id,
           case_kind,case_subtype,tax_treatment,instruction_kind,direction,payroll_stage,
           source_pay_channel,currency,approved_source_ex_vat,resolution_state)
          values(v_basis.id,v_basis.id,v_candidate,'RECOVERY',1,1,v_basis.id,
            'OVERPAYMENT','OVERPAYMENT','TAXABLE','RECOVERY','DEDUCTION','GROSS_DEDUCT','PAYE','GBP',v_principal,'REVIEW');
        v_basis.case_id:=v_basis.id;v_basis.case_component_id:=v_basis.id;v_delta:=v_principal;v_event:='APPROVED';
      end if;
    else
      select c.* into strict v_case from private.bpay_next_finance_case c where c.id=v_basis.case_id for update;
      select c.* into strict v_component from private.bpay_next_case_component c where c.id=v_basis.case_component_id for update;
      if (v_case.principal_approved,v_case.principal_recovered,v_case.principal_written_off,v_case.active_recovery_hold_amount)
         is distinct from (v_component.approved_source_ex_vat,v_component.recovered_source_ex_vat,
           v_component.written_off_source_ex_vat,v_component.active_recovery_source_ex_vat) then
        raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_BALANCE_MISMATCH';
      end if;
      -- R is actual SOURCE disposition, never held money/bank cash. Genuine
      -- future recovery must lower R with its own signed effect. Forgiveness
      -- W is separate; protected H is not repriced or released by an approval.
      v_principal:=v_case.principal_recovered+v_case.principal_written_off+
        greatest(v_position.realised_source_ex_vat-v_position.approved_source_ex_vat-v_case.principal_written_off,
          v_case.active_recovery_hold_amount,0);
      v_delta:=v_principal-v_case.principal_approved;
      if v_delta<>0 then
        update private.bpay_next_finance_case set principal_approved=v_principal,
          status=case when v_principal=principal_recovered+principal_written_off then 'CLOSED'
            when status='PAUSED' then 'PAUSED' else 'OPEN' end,
          case_revision=case_revision+1,updated_at_utc=pg_catalog.transaction_timestamp() where id=v_basis.case_id;
        update private.bpay_next_case_component set approved_source_ex_vat=v_principal,
          component_revision=component_revision+1,resolution_state='REVIEW',
          target_pay_channel=null,target_ex_vat=null,target_vat=null,target_inc_vat=null,
          valuation_policy_id=null,valuation_window_id=null,resolution_ref=null,
          updated_at_utc=pg_catalog.transaction_timestamp() where id=v_basis.case_component_id;
        v_event:='CORRECTED';
      elsif v_principal=v_case.principal_recovered+v_case.principal_written_off and v_case.status<>'CLOSED' then
        update private.bpay_next_finance_case set status='CLOSED',case_revision=case_revision+1,
          updated_at_utc=pg_catalog.transaction_timestamp() where id=v_basis.case_id;
      end if;
    end if;
    if v_event is not null then
      insert into private.bpay_next_case_event
        (case_id,operation_id,operation_item_id,event_kind,approved_delta,original_transfer_id,original_effect_id)
        values(v_basis.case_id,v_job.command_id,v_basis.id,v_event,v_delta,
          v_basis.original_transfer_id,v_basis.original_effect_id);
    end if;
  end if;
  -- First insert records exact basis; this single follow-up records the
  -- observation/case under the same actual owner transaction. No view counter
  -- is independently incremented: existing position/posting owners do that.
  update private.bpay_next_work_collection set case_id=v_basis.case_id,case_component_id=v_basis.case_component_id,
    paid_basis_qualified=v_qualified,qualification_state=v_state,observed_revision_id=v_position.applied_revision_id,
    observed_approved_source_ex_vat=v_position.approved_source_ex_vat,
    observed_realised_source_ex_vat=v_position.realised_source_ex_vat,
    reconcile_revision=reconcile_revision+1,last_job_id=p_job_id,last_effect_id=p_effect_id,
    updated_at_utc=pg_catalog.transaction_timestamp()
    where id=v_basis.id;
end
$function$;

-- 0410 has already posted exactly this frozen CASE result and changed its
-- hold/use to REALISED. Apply its single negative SOURCE disposition to the
-- linked original WORK; no bank outcome/return is itself a recovery.
create or replace function private.bpay_next_apply_work_collection_recovery_v1(p_job_id uuid,p_case_event_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_job private.bpay_next_job%rowtype;v_event private.bpay_next_case_event%rowtype;
  v_basis private.bpay_next_work_collection%rowtype;v_instruction private.bpay_next_run_case_instruction%rowtype;
  v_effect private.bpay_next_financial_effect%rowtype;v_effect_id uuid;
  v_source_line private.bpay_next_run_line%rowtype;
  v_book private.bpay_next_position%rowtype;v_cmp private.bpay_next_source_comparison_receipt%rowtype;
  v_output private.bpay_next_source_comparison_receipt%rowtype;
  v_mapping private.bpay_next_source_comparison_case_hold_mapping%rowtype;
  v_binding uuid;v_input_cmp uuid;v_local_work uuid;v_local_key text;v_retained boolean;
begin
  select * into strict v_job from private.bpay_next_job where id=p_job_id;
  select * into strict v_event from private.bpay_next_case_event where id=p_case_event_id;
  select * into strict v_instruction from private.bpay_next_run_case_instruction where id=v_event.instruction_id;
  select * into strict v_basis from private.bpay_next_work_collection where id=v_instruction.work_collection_id;
  -- Exact real-operation replay is resolved before mutable current-basis/hold maps.
  select * into v_effect from private.bpay_next_financial_effect where operation_id=v_job.command_id
    and operation_item_id=v_event.id and effect_kind='WORK_COLLECTION_RECOVERED';
  if found and v_effect.source_comparison_receipt_id is not null then
    if v_job.candidate_id<>v_basis.candidate_id or v_event.event_kind<>'RECOVERED'
      or (v_effect.candidate_id,v_effect.case_id,v_effect.original_transfer_id,v_effect.operation_item_id,
        v_effect.canonical_source_work_id,v_effect.canonical_source_component_key,v_effect.native_source_channel,
        v_effect.source_case_event_id,v_effect.source_case_instruction_id,v_effect.source_case_result_id,
        v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat)
        is distinct from (v_basis.candidate_id,v_basis.case_id,v_event.original_transfer_id,v_event.id,
          v_basis.work_id,v_basis.component_key,v_instruction.target_pay_channel,v_event.id,v_instruction.id,v_event.allocation_result_id,
          -v_event.target_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_RECOVERY_REPLAY_CONFLICT';end if;
    if v_instruction.source_comparison_receipt_id is not null then
      if (v_effect.work_id,v_effect.component_key,v_effect.source_binding_version_id,v_effect.source_comparison_receipt_id,
          v_effect.source_comparison_basis_review_id,v_effect.source_comparison_case_hold_id)
        is distinct from (v_instruction.source_approval_work_id,v_instruction.source_approval_component_key,
          v_instruction.source_binding_version_id,v_instruction.source_comparison_receipt_id,null::uuid,null::uuid) then
        raise exception 'BPAY_NEXT_COMPARISON_CASE_RECOVERY_REPLAY_CONFLICT';end if;
    elsif (v_effect.work_id,v_effect.component_key,v_effect.source_comparison_case_hold_id)
        is distinct from (v_basis.work_id,v_basis.component_key,v_event.operation_item_id)
      or not exists(select 1 from private.bpay_next_source_comparison_case_hold_mapping m
        join private.bpay_next_source_comparison_receipt input on input.id=v_effect.source_comparison_receipt_id
        where m.basis_review_id=v_effect.source_comparison_basis_review_id and m.case_hold_id=v_effect.source_comparison_case_hold_id
          and m.instruction_id=v_instruction.id and m.allocation_result_id=v_event.allocation_result_id
          and m.native_target_channel=v_instruction.target_pay_channel and m.native_target_ex_vat=v_event.target_amount_ex_vat
          and input.basis_review_id=m.basis_review_id and input.source_binding_version_id=v_effect.source_binding_version_id) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_RECOVERY_REPLAY_CONFLICT';end if;
    select * into strict v_output from private.bpay_next_source_comparison_receipt where receipt_kind='CASE_RECOVERY' and operation_identity=v_effect.id;
    perform private.bpay_next_source_comparison_carry_v2(p_job_id,v_output.source_book_revision_before,
      v_output.previous_comparison_id,'CASE_RECOVERY',v_effect.id);
    return;
  end if;
  select * into strict v_book from private.bpay_next_position
    where work_id=v_basis.work_id and component_key=v_basis.component_key;
  if v_instruction.source_comparison_receipt_id is not null or v_book.source_comparison_receipt_id is not null then
    -- 0410 already posted the real SOURCE Case counters and marked hold/use REALISED.
    -- Existing Candidate control serializes this with Source publication before WORK/book/Case locks.
    perform 1 from private.bpay_next_worker_control where candidate_id=v_basis.candidate_id for update;
    perform 1 from private.bpay_next_work where id=v_basis.work_id for update;
    select * into strict v_book from private.bpay_next_position
      where work_id=v_basis.work_id and component_key=v_basis.component_key for update;
    select * into strict v_cmp from private.bpay_next_source_comparison_receipt where id=v_book.source_comparison_receipt_id;
    if v_job.job_kind not in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') or v_job.phase<>'MEMBERS' or v_job.status<>'LEASED'
      or v_job.candidate_id<>v_basis.candidate_id or v_job.lease_until_utc<=clock_timestamp()
      or (v_event.operation_id,v_event.case_id,v_event.case_component_id,v_event.candidate_id)
        is distinct from (v_job.command_id,v_basis.case_id,v_basis.case_component_id,v_basis.candidate_id)
      or v_event.event_kind<>'RECOVERED' or v_event.source_amount_ex_vat<=0 or v_event.target_amount_ex_vat<=0
      or not private.bpay_next_source_comparison_book_certified_v2(v_book)
      or not exists(select 1 from private.bpay_next_module_control m join private.bpay_next_worker_control c
        on c.candidate_id=v_basis.candidate_id where m.id=1 and m.active_owner='NEXT' and m.owner_epoch=v_job.module_epoch
          and c.active_owner_epoch=v_job.owner_epoch)
      or not exists(select 1 from private.bpay_next_case_hold h
        join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='REALISED' and u.realisation_event_id=v_event.id
        join private.bpay_next_case_allocation_result ar on ar.id=v_event.allocation_result_id and ar.instruction_id=v_instruction.id
        join private.bpay_next_outcome_request outcome on outcome.command_id=v_job.command_id and outcome.transfer_id=v_event.original_transfer_id
        join private.bpay_next_transfer_member member on member.transfer_id=outcome.transfer_id and member.case_hold_id=h.id
          and member.case_instruction_id=v_instruction.id and member.case_allocation_result_id=ar.id
        where h.id=v_event.operation_item_id and h.status='REALISED' and h.instruction_id=v_instruction.id
          and h.source_reserved_ex_vat=v_event.source_amount_ex_vat and h.run_worker_id=outcome.run_worker_id
          and (ar.allocated_source_ex_vat,ar.allocated_target_ex_vat,ar.allocated_target_vat,ar.allocated_target_inc_vat)
            =(v_event.source_amount_ex_vat,v_event.target_amount_ex_vat,v_event.target_amount_vat,v_event.target_amount_inc_vat)) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_RECOVERY_ACTUAL_SCOPE_INVALID' using errcode='23514';end if;
    v_retained:=v_instruction.source_comparison_receipt_id is null;
    if v_retained then
      select * into strict v_mapping from private.bpay_next_source_comparison_case_hold_mapping
        where basis_review_id=v_cmp.basis_review_id and case_hold_id=v_event.operation_item_id;
      if (v_mapping.instruction_id,v_mapping.allocation_result_id,v_mapping.native_target_channel,v_mapping.native_target_ex_vat)
        is distinct from (v_instruction.id,v_event.allocation_result_id,v_instruction.target_pay_channel,v_event.target_amount_ex_vat) then
        raise exception 'BPAY_NEXT_COMPARISON_RETAINED_CASE_HOLD_PROOF_INVALID';end if;
      v_binding:=v_cmp.source_binding_version_id;v_input_cmp:=v_cmp.id;
      v_local_work:=v_basis.work_id;v_local_key:=v_basis.component_key;
    else
      v_binding:=v_instruction.source_binding_version_id;v_input_cmp:=v_instruction.source_comparison_receipt_id;
      v_local_work:=v_instruction.source_approval_work_id;v_local_key:=v_instruction.source_approval_component_key;
      if (v_instruction.canonical_source_work_id,v_instruction.canonical_source_component_key)
        is distinct from (v_basis.work_id,v_basis.component_key) then raise exception 'BPAY_NEXT_COMPARISON_CASE_INSTRUCTION_CANONICAL_INVALID';end if;
    end if;
    insert into private.bpay_next_financial_effect(operation_id,operation_item_id,effect_kind,candidate_id,
      work_id,component_key,case_id,original_timesheet_id,original_transfer_id,source_disposition_ex_vat,
      target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,occurred_at_utc,source_run_line_id,
      source_binding_version_id,canonical_source_work_id,canonical_source_component_key,native_source_channel,
      source_case_event_id,source_comparison_receipt_id,source_case_instruction_id,source_case_result_id,
      source_comparison_basis_review_id,source_comparison_case_hold_id)
      select v_job.command_id,v_event.id,'WORK_COLLECTION_RECOVERED',v_basis.candidate_id,
        v_local_work,v_local_key,v_basis.case_id,w.original_timesheet_id,v_event.original_transfer_id,
        -v_event.target_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat,
        v_event.occurred_at_utc,null,v_binding,v_basis.work_id,v_basis.component_key,v_instruction.target_pay_channel,
        v_event.id,v_input_cmp,v_instruction.id,v_event.allocation_result_id,
        case when v_retained then v_cmp.basis_review_id else null end,
        case when v_retained then v_event.operation_item_id else null end
      from private.bpay_next_work w where w.id=v_local_work and w.candidate_id=v_basis.candidate_id
      on conflict(operation_id,operation_item_id,effect_kind) do nothing returning id into v_effect_id;
    if v_effect_id is null then
      select * into strict v_effect from private.bpay_next_financial_effect where operation_id=v_job.command_id
        and operation_item_id=v_event.id and effect_kind='WORK_COLLECTION_RECOVERED';
      -- Retained replay uses its exact effect's saved INPUT basis, not a later move.
      if v_retained then v_binding:=v_effect.source_binding_version_id;v_input_cmp:=v_effect.source_comparison_receipt_id;end if;
      if (v_effect.candidate_id,v_effect.work_id,v_effect.component_key,v_effect.case_id,v_effect.original_transfer_id,
        v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat,
        v_effect.source_run_line_id,v_effect.source_binding_version_id,v_effect.canonical_source_work_id,v_effect.canonical_source_component_key,
        v_effect.native_source_channel,v_effect.source_case_event_id,v_effect.source_comparison_receipt_id,v_effect.source_case_instruction_id,v_effect.source_case_result_id)
        is distinct from (v_basis.candidate_id,v_local_work,v_local_key,v_basis.case_id,v_event.original_transfer_id,
          -v_event.target_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat,
          null::uuid,v_binding,v_basis.work_id,v_basis.component_key,v_instruction.target_pay_channel,v_event.id,v_input_cmp,v_instruction.id,v_event.allocation_result_id)
        or (v_retained and (v_effect.source_comparison_case_hold_id is distinct from v_event.operation_item_id
          or not exists(select 1 from private.bpay_next_source_comparison_case_hold_mapping mapping
            where mapping.basis_review_id=v_effect.source_comparison_basis_review_id and mapping.case_hold_id=v_event.operation_item_id
              and mapping.instruction_id=v_instruction.id and mapping.allocation_result_id=v_event.allocation_result_id)))
        or (not v_retained and (v_effect.source_comparison_basis_review_id is not null or v_effect.source_comparison_case_hold_id is not null)) then
        raise exception 'BPAY_NEXT_COMPARISON_CASE_RECOVERY_REPLAY_CONFLICT';end if;
      select * into strict v_output from private.bpay_next_source_comparison_receipt where receipt_kind='CASE_RECOVERY' and operation_identity=v_effect.id;
      perform private.bpay_next_source_comparison_carry_v2(p_job_id,v_output.source_book_revision_before,
        v_output.previous_comparison_id,'CASE_RECOVERY',v_effect.id);
      return;
    end if;
    -- carry owns exactly the actual target-channel signed-native debit and legitimate
    -- B/C local scalar. Retained old Case hold is native-only: A seed cash stays frozen.
    perform private.bpay_next_source_comparison_carry_v2(p_job_id,v_book.source_book_revision,v_cmp.id,'CASE_RECOVERY',v_effect_id);
    perform private.bpay_next_reconcile_work_collection_v1(p_job_id,v_basis.work_id,v_basis.component_key,v_effect_id);
    return;
  end if;
  if v_job.job_kind not in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') or v_job.phase<>'MEMBERS' or v_job.status<>'LEASED'
     or v_job.candidate_id<>v_basis.candidate_id or v_job.lease_until_utc<=pg_catalog.clock_timestamp()
     or (v_event.operation_id,v_event.case_id,v_event.case_component_id,v_event.candidate_id)
       is distinct from (v_job.command_id,v_basis.case_id,v_basis.case_component_id,v_basis.candidate_id)
     or v_event.event_kind<>'RECOVERED' or v_event.source_amount_ex_vat<=0
     or v_instruction.valuation_policy_id<>v_basis.original_valuation_policy_id
     or (v_event.source_amount_ex_vat,v_event.target_amount_ex_vat,v_event.target_amount_vat,v_event.target_amount_inc_vat)
       is distinct from (v_event.recovered_delta,v_event.recovered_delta,0::numeric,v_event.recovered_delta)
     or not exists(select 1 from private.bpay_next_module_control m
       join private.bpay_next_worker_control c on c.candidate_id=v_basis.candidate_id
       where m.id=1 and m.active_owner='NEXT' and m.owner_epoch=v_job.module_epoch and c.active_owner_epoch=v_job.owner_epoch)
     or not exists(select 1 from private.bpay_next_case_hold h
       join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='REALISED' and u.realisation_event_id=v_event.id
       join private.bpay_next_outcome_request r on r.command_id=v_job.command_id and r.transfer_id=v_event.original_transfer_id
       join private.bpay_next_transfer_member member on member.transfer_id=r.transfer_id and member.case_hold_id=h.id
         and member.case_instruction_id=v_instruction.id and member.case_allocation_result_id=v_event.allocation_result_id
       where h.id=v_event.operation_item_id and h.status='REALISED' and h.instruction_id=v_instruction.id
         and h.source_reserved_ex_vat=v_event.source_amount_ex_vat and h.run_worker_id=r.run_worker_id) then
    raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_SCOPE_INVALID';
  end if;
  select * into strict v_source_line from private.bpay_next_run_line where id=v_basis.original_run_line_id;
  insert into private.bpay_next_financial_effect(operation_id,operation_item_id,effect_kind,candidate_id,
    work_id,component_key,case_id,original_timesheet_id,original_transfer_id,source_disposition_ex_vat,
    target_amount_ex_vat,target_amount_vat,target_amount_inc_vat,occurred_at_utc,source_run_line_id,
    source_binding_version_id,canonical_source_work_id,canonical_source_component_key,native_source_channel,source_case_event_id)
    select v_job.command_id,v_event.id,'WORK_COLLECTION_RECOVERED',v_basis.candidate_id,
      v_basis.work_id,v_basis.component_key,v_basis.case_id,w.original_timesheet_id,v_event.original_transfer_id,
      -v_event.source_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat,v_event.occurred_at_utc,
      case when v_source_line.source_binding_version_id is null then null else v_source_line.id end,
      v_source_line.source_binding_version_id,v_source_line.canonical_source_work_id,v_source_line.canonical_source_component_key,
      case when v_source_line.source_binding_version_id is null then null else v_source_line.source_pay_channel end,
      case when v_source_line.source_binding_version_id is null then null else v_event.id end
      from private.bpay_next_work w where w.id=v_basis.work_id
    on conflict(operation_id,operation_item_id,effect_kind) do nothing returning id into v_effect_id;
  if v_effect_id is null then
    select * into strict v_effect from private.bpay_next_financial_effect where operation_id=v_job.command_id
      and operation_item_id=v_event.id and effect_kind='WORK_COLLECTION_RECOVERED';
    if (v_effect.candidate_id,v_effect.work_id,v_effect.component_key,v_effect.case_id,v_effect.original_transfer_id,
        v_effect.source_disposition_ex_vat,v_effect.target_amount_ex_vat,v_effect.target_amount_vat,v_effect.target_amount_inc_vat)
      is distinct from (v_basis.candidate_id,v_basis.work_id,v_basis.component_key,v_basis.case_id,v_event.original_transfer_id,
        -v_event.source_amount_ex_vat,-v_event.target_amount_ex_vat,-v_event.target_amount_vat,-v_event.target_amount_inc_vat) then
      raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_REPLAY_CONFLICT';
    end if;
    if (v_effect.source_run_line_id,v_effect.source_binding_version_id,v_effect.canonical_source_work_id,
        v_effect.canonical_source_component_key,v_effect.native_source_channel,v_effect.source_case_event_id)
      is distinct from (case when v_source_line.source_binding_version_id is null then null else v_source_line.id end,
        v_source_line.source_binding_version_id,v_source_line.canonical_source_work_id,v_source_line.canonical_source_component_key,
        case when v_source_line.source_binding_version_id is null then null else v_source_line.source_pay_channel end,
        case when v_source_line.source_binding_version_id is null then null else v_event.id end) then
      raise exception using errcode='23514',message='BPAY_NEXT_SOURCE_BOOK_EFFECT_REPLAY_CONFLICT';
    end if;
    return;
  end if;
  update private.bpay_next_position set realised_source_ex_vat=realised_source_ex_vat-v_event.source_amount_ex_vat,
    realised_target_ex_vat=realised_target_ex_vat-v_event.target_amount_ex_vat,
    realised_target_vat=realised_target_vat-v_event.target_amount_vat,
    realised_target_inc_vat=realised_target_inc_vat-v_event.target_amount_inc_vat,
    updated_at_utc=pg_catalog.transaction_timestamp()
    where work_id=v_basis.work_id and component_key=v_basis.component_key and source_basis_channel='PAYE'
      and realised_source_ex_vat>=v_event.source_amount_ex_vat
      and (realised_target_ex_vat,realised_target_vat,realised_target_inc_vat)
        is not distinct from (realised_source_ex_vat,0::numeric,realised_source_ex_vat);
  if not found then raise exception using errcode='23514',message='BPAY_NEXT_WORK_COLLECTION_RECOVERY_POSITION_INVALID';end if;
  perform private.bpay_next_reconcile_work_collection_v1(p_job_id,v_basis.work_id,v_basis.component_key,v_effect_id);
end
$function$;

create or replace function private.bpay_next_reconcile_cancelled_work_collection_v1(p_job_id uuid,p_case_hold_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare v_basis private.bpay_next_work_collection%rowtype;
begin
  select b.* into strict v_basis from private.bpay_next_case_hold h
    join private.bpay_next_run_case_instruction i on i.id=h.instruction_id
    join private.bpay_next_work_collection b on b.id=i.work_collection_id and b.case_id=h.case_id and b.case_component_id=h.case_component_id
    join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='RELEASED'
    join private.bpay_next_case_cancel_binding cb on cb.run_worker_id=h.run_worker_id and cb.command_id=(select command_id from private.bpay_next_job where id=p_job_id)
    where h.id=p_case_hold_id and h.status='RELEASED' and cb.status='CANCELLING' and cb.stage='CASE';
  -- Cancellation is not a financial disposition. Keep its exact physical hold.
  if exists(select 1 from private.bpay_next_position p where p.work_id=v_basis.work_id
    and p.component_key=v_basis.component_key and p.source_comparison_receipt_id is not null) then
    perform private.bpay_next_reconcile_source_comparison_case_release_v2(p_job_id,p_case_hold_id);
    return;
  end if;
  -- Ordinary/unwitnessed R and all frozen CSV/advice values stay unchanged.
  perform private.bpay_next_reconcile_work_collection_v1(p_job_id,v_basis.work_id,v_basis.component_key,null);
end
$function$;

drop trigger if exists bpay_next_work_collection_guard_v1 on private.bpay_next_work_collection;
create trigger bpay_next_work_collection_guard_v1 before insert or update or delete
on private.bpay_next_work_collection for each row execute function private.bpay_next_work_collection_guard_v1();
drop trigger if exists bpay_next_work_collection_truncate_guard_v1 on private.bpay_next_work_collection;
create trigger bpay_next_work_collection_truncate_guard_v1 before truncate
on private.bpay_next_work_collection for each statement execute function private.bpay_next_effect_immutable_v1();
drop trigger if exists bpay_next_work_collection_case_identity_guard_v1 on private.bpay_next_finance_case;
create trigger bpay_next_work_collection_case_identity_guard_v1 before update
on private.bpay_next_finance_case for each row execute function private.bpay_next_work_collection_case_identity_guard_v1();
drop trigger if exists bpay_next_work_collection_component_identity_guard_v1 on private.bpay_next_case_component;
create trigger bpay_next_work_collection_component_identity_guard_v1 before update
on private.bpay_next_case_component for each row execute function private.bpay_next_work_collection_case_identity_guard_v1();

drop trigger if exists bpay_next_work_collection_capture_guard_v1 on private.bpay_next_run_position;
create trigger bpay_next_work_collection_capture_guard_v1 before insert or update or delete
on private.bpay_next_run_position for each row execute function private.bpay_next_work_collection_capture_guard_v1();
drop trigger if exists bpay_next_work_collection_instruction_guard_v1 on private.bpay_next_run_case_instruction;
create trigger bpay_next_work_collection_instruction_guard_v1 before insert
on private.bpay_next_run_case_instruction for each row execute function private.bpay_next_work_collection_capture_guard_v1();
drop trigger if exists bpay_next_work_collection_period_guard_v1 on private.bpay_next_case_period;
