-- Exact Source receipt -> original financial identity. This is metadata
-- registration, not payment, repricing, a quote, or a ready-position assertion.
-- Complete successor of 03102026_1570; the earlier definition is unchanged.





create or replace function private.bpay_next_source_receipt_publish_v1()
returns trigger
language plpgsql security definer
set search_path = pg_catalog, private, public
as $function$
declare
  v_n integer;
  v_member record;
  v_stage record;
  v_work_ids uuid[]:=array[]::uuid[];
  v_revision_ids uuid[]:=array[]::uuid[];
  v_event_ids uuid[]:=array[]::uuid[];
  v_component record;
  v_binding record;
  v_joined_witness private.weekly_source_destination_reprice_witness_v1%rowtype;
begin
  if (select active_owner from private.bpay_next_module_control
      where id=1 for share)<>'NEXT' then
    return new;
  end if;
  v_n:=pg_catalog.cardinality(new.member_root_ids);
  if v_n not between 1 and 2
     or v_n<>pg_catalog.cardinality(new.head_ids)
     or v_n<>pg_catalog.cardinality(new.member_family_booking_ids) then
    raise exception using errcode='23514',
      message='BPAY_NEXT_SOURCE_RECEIPT_SCOPE_INVALID';
  end if;
  -- The real receipt is now inserted; this is not a guessed publication ID.
  select w.* into v_joined_witness from private.weekly_source_destination_reprice_witness_v1 w
    where w.decision_bundle_id=new.decision_bundle_id and w.bundle_revision=new.bundle_revision
      and w.context_json->>'joined_review_schema'='SOURCE_DESTINATION_PAY_FINANCIAL_REVIEW_V2';
  -- Every Source owner reaches this insertion after its source locks.  Sort
  -- the exact receipt members before touching any Banking Pay work row so
  -- opposite request-array order cannot reverse the two-root lock order.
  for v_member in
    select new.member_root_ids[i] as root_id,
           new.head_ids[i] as head_id,
           new.member_family_booking_ids[i] as booking_id
      from pg_catalog.generate_subscripts(new.member_root_ids,1) as i
      order by new.member_family_booking_ids[i],new.member_root_ids[i]
  loop
    select * into strict v_stage
      from private.bpay_next_stage_source_current_v1(
        v_member.root_id,v_member.head_id,v_member.head_id);
    if (select w.candidate_id from private.bpay_next_work w
        where w.id=v_stage.work_id) is distinct from new.candidate_id then
      raise exception using errcode='23514',
        message='BPAY_NEXT_SOURCE_RECEIPT_CANDIDATE_MISMATCH';
    end if;
    v_work_ids:=pg_catalog.array_append(v_work_ids,v_stage.work_id);
    v_revision_ids:=pg_catalog.array_append(v_revision_ids,v_stage.revision_id);
    v_event_ids:=pg_catalog.array_append(v_event_ids,v_member.head_id);
  end loop;
  -- Staging already serialises this Candidate on worker_control. Discover and
  -- acquire the direct original A plus exact current member union BEFORE any
  -- agency clock receipt, including a repeated A -> B -> C move. No ancestry
  -- traversal, payment SUM, position creation or history rebuild is permitted.
  perform * from private.bpay_next_source_binding_lockset_v1(new.id);
  perform * from private.bpay_next_publish_source_staged_pair_v1(
    v_work_ids,v_revision_ids,v_event_ids);
  -- Publication tuples now exist. Bind every affected actual current/prior
  -- component, including an immediate initial-base removal, to its immutable
  -- original identity. The same transaction owns receipt/activation/job writes;
  -- an incomplete registration cannot leave a successful half-published Save.
  for v_component in
    select c.source_component_id
      from private.bpay_next_source_binding_components_v1(new.id) c
      order by c.source_component_id
  loop
    select * into strict v_binding
      from private.bpay_next_source_component_bind_v1(
        new.id,v_component.source_component_id);
    if v_binding.qualification_state is distinct from 'REGISTERED'
       or v_binding.binding_version_id is null
       or v_binding.canonical_work_id is null
       or v_binding.canonical_component_key is distinct from
            'SOURCE:'||v_component.source_component_id::text then
      raise exception using errcode='55000',
        message='BPAY_NEXT_SOURCE_RECEIPT_BINDING_NOT_REGISTERED';
    end if;
    -- Only after real REGISTERED binding. The financial owner promotes the
    -- same accepted pending basis/current snapshot; no APPLIED status is made up.
    if v_joined_witness.id is not null and exists(select 1
      from pg_catalog.jsonb_array_elements(v_joined_witness.context_json#>'{financial_plan,components}') c
      where c->>'source_component_id'=v_component.source_component_id::text) then
      perform private.bpay_next_source_comparison_register_review_v2(
        new.id,v_component.source_component_id,v_joined_witness.id);
    end if;
  end loop;
  -- REGISTERED does not mean POSITION_APPLY has finished, the book has been
  -- seeded, a quote has been accepted, or candidate pay is ready to capture.
  return new;
end
$function$;

alter function private.bpay_next_source_receipt_publish_v1() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_receipt_publish_v1()
  from public,anon,authenticated,service_role;

-- Retain the same real attachment. A changed UPGRADE closure must reassert it,
-- not rely on replaying an unchanged historical trigger definition.
drop trigger if exists bpay_next_source_receipt_publish_v1
  on private.weekly_source_entitlement_publication_receipts;
create trigger bpay_next_source_receipt_publish_v1
after insert on private.weekly_source_entitlement_publication_receipts
for each row execute function private.bpay_next_source_receipt_publish_v1();



-- Repeatable CloudTMS function/view authority: banking_pay_next_initial_tsfin_daily_evidence_v1
-- Use CREATE OR REPLACE and preserve owner, security, search_path, and ACL contracts.





-- Owner-only metadata qualification. No caller money, position, hold or effect write.
-- The existing I-1 and immutable Banking revision remain the financial authorities.
create or replace function private.bpay_next_initial_tsfin_certificate_v1(p_root_authorisation_id uuid)
returns jsonb language plpgsql security definer
set search_path=pg_catalog,private,public
as $function$
declare
  a public.weekly_source_root_authorisations%rowtype;
  t public.timesheets%rowtype;f public.timesheets_financials%rowtype;
  w private.bpay_next_work%rowtype;r private.bpay_next_work_revision%rowtype;
  p private.bpay_next_publication%rowtype;c public.contracts%rowtype;
  inventory jsonb;basis jsonb;origin jsonb;details jsonb;n integer;epoch bigint;
begin
  if p_root_authorisation_id is null then
    raise exception 'BPAY_NEXT_INITIAL_AUTH_ID_REQUIRED' using errcode='22023';end if;
  select m.owner_epoch into epoch from private.bpay_next_module_control m
    where m.id=1 and m.active_owner='NEXT' for share;
  if epoch is null then raise exception 'BPAY_NEXT_BINDING_NEXT_REQUIRED' using errcode='55000';end if;
  select x.* into strict a from public.weekly_source_root_authorisations x where x.id=p_root_authorisation_id;
  select x.* into strict t from public.timesheets x where x.timesheet_id=a.root_timesheet_id;
  select x.* into strict c from public.contracts x where x.id=t.contract_id;
  select x.* into strict r from private.bpay_next_work_revision x where x.source_event_id=a.id;
  select x.* into strict w from private.bpay_next_work x where x.id=r.work_id;
  select x.* into strict f from public.timesheets_financials x where x.id=r.financial_snapshot_id;
  select x.* into strict p from private.bpay_next_publication x
    where x.command_id=private.bpay_next_source_command_id_v1(a.id);
  if a.withdrawn_at_utc is not null or a.current_entitlement_head_id is not null
     or exists(select 1 from public.weekly_source_entitlement_heads h where btrim(h.root_family_booking_id)=btrim(t.booking_id))
     or t.is_current is distinct from true or t.authorised_at_server is null
     or t.revoked_at is not null or t.archived_at_utc is not null
     or (a.family_booking_id,a.timesheet_version) is distinct from (t.booking_id,t.version)
     or (w.work_kind,w.candidate_id,w.contract_id,w.original_timesheet_id,w.booking_id,w.week_ending_date,w.current_revision_id)
       is distinct from ('SOURCE'::text,c.candidate_id,c.id,t.timesheet_id,t.booking_id,t.week_ending_date,r.id)
     or w.approval_state is distinct from 'APPROVED'
     or (r.source_kind,r.source_head_id,r.source_event_id,r.physical_timesheet_id,r.physical_timesheet_version,r.week_ending_date)
       is distinct from ('SOURCE'::text,null::uuid,a.id,t.timesheet_id,t.version,t.week_ending_date)
     or r.approved_at_utc is null or r.sealed_at_utc is null
     or f.is_current is distinct from true or f.is_stale is distinct from false or f.authorised_at_utc is null
     or (f.timesheet_id,f.timesheet_version,f.candidate_id,f.client_id)
       is distinct from (t.timesheet_id,t.version,w.candidate_id,c.client_id)
     or (p.work_id,p.revision_id,p.candidate_id,p.revision_no)
       is distinct from (w.id,r.id,w.candidate_id,r.revision_no)
     or not exists(select 1 from private.bpay_next_command command
       join private.bpay_next_command_member member on member.command_id=command.id and member.candidate_id=w.candidate_id
       where command.id=p.command_id and command.command_kind='POSITION_APPLY'
         and command.module_epoch=epoch and command.status in ('SEALED','COMPLETE')
         and command.sealed_at_utc is not null and command.expected_member_count=1 and member.member_no=1
         -- INITIAL_METADATA_PHASE_V2_BEGIN: no fabricated enrollment/job.
         and ((command.status='SEALED' and command.enrolled_member_count=0
           and p.status='QUEUED' and p.phase='NEW' and p.applied_at_utc is null
           and not exists(select 1 from private.bpay_next_job job where job.command_id=command.id))
          or (command.status='COMPLETE' and command.enrolled_member_count=1
           and p.status='APPLIED' and p.phase='DONE' and p.applied_at_utc is not null
           and (select count(*) from private.bpay_next_job job where job.command_id=command.id)=1
           and exists(select 1 from private.bpay_next_job job
             join private.bpay_next_worker_control ctl on ctl.candidate_id=job.candidate_id
             where job.command_id=command.id and job.candidate_id=w.candidate_id
               and job.job_kind='POSITION_APPLY' and job.command_sequence=command.agency_sequence
               and job.module_epoch=command.module_epoch and job.status='DONE' and job.phase='DONE'
               and job.owner_epoch>0 and job.owner_epoch<=ctl.active_owner_epoch
               and job.lease_nonce is null and job.lease_until_utc is null)))
         -- INITIAL_METADATA_PHASE_V2_END
       )
  then raise exception 'BPAY_NEXT_INITIAL_AUTH_NOT_CURRENT' using errcode='55000';end if;
  inventory:=private.weekly_source_effective_inventory_v1(t.timesheet_id);
  basis:=inventory->'approval_basis';origin:=basis->'origin';
  details:=jsonb_build_object('segments',f.invoice_breakdown_json->'segments','additional_units',f.additional_units_json,
    'actual_schedule',f.actual_schedule_json,'rate_source_refs',f.rate_source_refs_json);
  if inventory->>'ok' is distinct from 'true' or inventory->>'authority' is distinct from 'TSFIN'
     or inventory->>'head_id' is not null or jsonb_typeof(inventory->'components') is distinct from 'array'
     or jsonb_typeof(basis) is distinct from 'object' or basis->'coverage_complete' is distinct from 'true'::jsonb
     or basis is distinct from private.weekly_source_inventory_approval_basis_v2(t.timesheet_id,inventory)
     or origin is distinct from jsonb_build_object('kind','INITIAL_AUTHORISED_TSFIN_V1',
       'root_authorisation_id',a.id,'financial_snapshot_id',f.id,'authorisation_generation',a.authorisation_generation,
       'root_timesheet_id',t.timesheet_id,'root_version',t.version::text,'authorised_row_signature',a.authorised_row_signature,
       'financial_snapshot_digest',encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_APPROVED_FINANCIAL_SNAPSHOT_V2',
         jsonb_build_object('policy',f.policy_snapshot_json,'details',details,'components',inventory->'components')),'hex'),
       'inventory_digest',basis->>'inventory_digest','entitlement_digest',basis->>'entitlement_digest')
     or basis->>'detail_digest' is distinct from encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_APPROVED_DETAIL_V2',details),'hex')
     or basis->>'policy_fingerprint' is distinct from encode(private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_APPROVED_POLICY_V2',f.policy_snapshot_json),'hex')
     or r.source_inventory_digest is distinct from decode(basis->>'inventory_digest','hex')
     or r.approved_source_ex_vat is distinct from (basis->>'approved_pay_ex_vat')::numeric
     or r.expected_line_count is distinct from jsonb_array_length(inventory->'components')
  then raise exception 'BPAY_NEXT_INITIAL_I1_CERTIFICATE_REQUIRED' using errcode='55000';end if;
  select count(*) into n from private.bpay_next_approved_line l where l.revision_id=r.id;
  if n<>r.expected_line_count or exists(select 1 from jsonb_array_elements(inventory->'components') component
      left join private.bpay_next_approved_line l on l.revision_id=r.id
        and l.source_component_id=(component.value->>'component_id')::uuid
        and l.component_key='SOURCE:'||(component.value->>'component_id')
      where l.id is null or l.line_no is distinct from (component.value->>'component_ordinal')::integer
        or l.evidence_ref is distinct from 'source-component:'||(component.value->>'component_id')||'#'||(component.value->>'component_sha256')
        or l.source_pay_ex_vat is distinct from case when (component.value->>'exclude_from_pay')::boolean then 0 else (component.value->>'pay_ex_vat')::numeric end
        or l.component_kind is distinct from case component.value->>'component_kind' when 'WORKED_TIME' then 'WORK' when 'ADDITIONAL_UNIT' then 'ADDITIONAL' else 'EXPENSE' end
        or l.tax_treatment is distinct from case when component.value->>'component_kind'='WORKED_TIME' then 'TAXABLE'::text else null::text end)
  then raise exception 'BPAY_NEXT_INITIAL_SEALED_COMPONENTS_MISMATCH' using errcode='23514';end if;
  return jsonb_build_object('candidate_id',w.candidate_id,'work_id',w.id,'revision_id',r.id,'command_id',p.command_id,
    'source_channel',r.source_pay_channel,'origin',origin,'basis',basis,'components',inventory->'components',
    'certificate_digest',encode(private.weekly_source_sha256_jsonb_v1('BPAY_NEXT_INITIAL_TSFIN_CERTIFICATE_V1',basis),'hex'));
end
$function$;

create or replace function private.bpay_next_initial_tsfin_bind_v1(p_root_authorisation_id uuid)
returns table(binding_version_id uuid,canonical_work_id uuid,canonical_component_key text,binding_revision bigint,qualification_state text)
language plpgsql security definer set search_path=pg_catalog,private,public
as $function$
declare
  v_candidate uuid;v_work uuid;cert jsonb;origin jsonb;basis jsonb;component jsonb;
  l private.bpay_next_approved_line%rowtype;b private.bpay_next_source_component_binding%rowtype;
  v private.bpay_next_source_component_binding_version%rowtype;revision private.bpay_next_work_revision%rowtype;
  id_new uuid;digest bytea;n integer;
begin
  if p_root_authorisation_id is null then raise exception 'BPAY_NEXT_INITIAL_AUTH_ID_REQUIRED' using errcode='22023';end if;
  perform 1 from private.bpay_next_module_control where id=1 and active_owner='NEXT' for share;
  if not found then raise exception 'BPAY_NEXT_BINDING_NEXT_REQUIRED' using errcode='55000';end if;
  select w.candidate_id,w.id into v_candidate,v_work
    from private.bpay_next_work_revision r join private.bpay_next_work w on w.id=r.work_id
    where r.source_event_id=p_root_authorisation_id;
  if not found then raise exception 'BPAY_NEXT_INITIAL_REVISION_REQUIRED' using errcode='55000';end if;
  select r.* into strict revision from private.bpay_next_work_revision r where r.source_event_id=p_root_authorisation_id;
  perform 1 from private.bpay_next_worker_control where candidate_id=v_candidate for update;
  if not found then raise exception 'BPAY_NEXT_SOURCE_BOOK_CONTROL_REQUIRED' using errcode='55000';end if;
  perform 1 from private.bpay_next_work where id=v_work and candidate_id=v_candidate for update;
  perform 1 from private.bpay_next_work_revision where id=revision.id and work_id=v_work for share;
  -- Exact stored replay precedes current I-1 discovery and NEVER advances the pointer.
  select count(*) into n from private.bpay_next_source_component_binding_version x
    where x.initial_root_authorisation_id=p_root_authorisation_id;
  if n>0 then
    if n<>revision.expected_line_count then raise exception 'BPAY_NEXT_INITIAL_PARTIAL_REPLAY' using errcode='23514';end if;
    for v in select x.* from private.bpay_next_source_component_binding_version x
      where x.initial_root_authorisation_id=p_root_authorisation_id order by x.canonical_component_key collate "C"
    loop
      if v.origin_kind<>'INITIAL_AUTHORISED_TSFIN_V1' or v.canonical_work_id<>v_work or v.approval_revision_id<>revision.id then
        raise exception 'BPAY_NEXT_INITIAL_REPLAY_CONFLICT' using errcode='23514';end if;
      select x.* into strict b from private.bpay_next_source_component_binding x
        where x.canonical_work_id=v.canonical_work_id and x.canonical_component_key=v.canonical_component_key;
      binding_version_id:=v.id;canonical_work_id:=v.canonical_work_id;canonical_component_key:=v.canonical_component_key;
      binding_revision:=v.binding_revision;qualification_state:=case when b.current_binding_version_id=v.id then 'REGISTERED' else 'SUPERSEDED' end;
      return next;
    end loop;return;
  end if;
  cert:=private.bpay_next_initial_tsfin_certificate_v1(p_root_authorisation_id);
  origin:=cert->'origin';basis:=cert->'basis';
  -- Empty genuine I-1 inventory creates no invented component/binding/position.
  for component in select value from jsonb_array_elements(cert->'components') order by value->>'component_id'
  loop
    select x.* into strict l from private.bpay_next_approved_line x
      where x.revision_id=revision.id and x.source_component_id=(component->>'component_id')::uuid;
    if exists(select 1 from private.bpay_next_source_component_binding x where x.candidate_id=v_candidate and x.source_component_id=l.source_component_id) then
      raise exception 'BPAY_NEXT_INITIAL_COMPONENT_ALREADY_BOUND' using errcode='23514';end if;
    id_new:=gen_random_uuid();
    digest:=sha256(convert_to(jsonb_build_array('INITIAL_AUTHORISED_TSFIN_V1',v_work,l.component_key,
      revision.id,l.id,p_root_authorisation_id,cert->>'certificate_digest',cert->>'command_id',component->>'component_sha256')::text,'UTF8'));
    insert into private.bpay_next_source_component_binding_version
      (id,canonical_work_id,canonical_component_key,candidate_id,source_component_id,binding_revision,
       approval_work_id,approval_revision_id,approval_component_key,approved_line_id,component_state,
       approval_source_channel,tax_treatment,classification_line_id,component_sha256,
       publication_command_id_1,publication_work_id_1,publication_revision_id_1,binding_digest,
       origin_kind,initial_root_authorisation_id,initial_financial_snapshot_id,initial_root_timesheet_id,
       initial_root_version,initial_authorisation_generation,initial_authorised_row_signature,
       initial_financial_snapshot_digest,initial_inventory_digest,initial_entitlement_digest,
       initial_detail_digest,initial_policy_digest,initial_certificate_digest)
    values(id_new,v_work,l.component_key,v_candidate,l.source_component_id,1,v_work,revision.id,l.component_key,l.id,'PRESENT',
      revision.source_pay_channel,l.tax_treatment,l.id,decode(component->>'component_sha256','hex'),
      (cert->>'command_id')::uuid,v_work,revision.id,digest,'INITIAL_AUTHORISED_TSFIN_V1',p_root_authorisation_id,
      (origin->>'financial_snapshot_id')::uuid,(origin->>'root_timesheet_id')::uuid,(origin->>'root_version')::integer,
      (origin->>'authorisation_generation')::integer,origin->>'authorised_row_signature',
      decode(origin->>'financial_snapshot_digest','hex'),decode(basis->>'inventory_digest','hex'),decode(basis->>'entitlement_digest','hex'),
      decode(basis->>'detail_digest','hex'),decode(basis->>'policy_fingerprint','hex'),decode(cert->>'certificate_digest','hex'));
    insert into private.bpay_next_source_component_binding
      (canonical_work_id,canonical_component_key,candidate_id,source_component_id,canonical_revision_id,canonical_line_id,current_binding_version_id,binding_revision)
    values(v_work,l.component_key,v_candidate,l.source_component_id,revision.id,l.id,id_new,1);
    binding_version_id:=id_new;canonical_work_id:=v_work;canonical_component_key:=l.component_key;binding_revision:=1;
    qualification_state:='REGISTERED';return next;
  end loop;
end
$function$;

-- Only a current initial version calls I-1. A superseded initial version is
-- handled before this dispatch by the existing snapshot's pointer check.
create or replace function private.bpay_next_initial_tsfin_bound_assert_v1(p_binding_version_id uuid)
returns void language plpgsql security definer set search_path=pg_catalog,private,public
as $function$
declare v private.bpay_next_source_component_binding_version%rowtype;l private.bpay_next_approved_line%rowtype;
  cert jsonb;origin jsonb;basis jsonb;component jsonb;
begin
  select x.* into strict v from private.bpay_next_source_component_binding_version x where x.id=p_binding_version_id;
  if v.origin_kind is distinct from 'INITIAL_AUTHORISED_TSFIN_V1' then
    raise exception 'BPAY_NEXT_INITIAL_ORIGIN_REQUIRED' using errcode='23514';end if;
  cert:=private.bpay_next_initial_tsfin_certificate_v1(v.initial_root_authorisation_id);origin:=cert->'origin';basis:=cert->'basis';
  select value into strict component from jsonb_array_elements(cert->'components') x(value)
    where (value->>'component_id')::uuid=v.source_component_id;
  select x.* into strict l from private.bpay_next_approved_line x
    where x.revision_id=(cert->>'revision_id')::uuid and x.source_component_id=v.source_component_id;
  if (v.candidate_id,v.canonical_work_id,v.approval_work_id,v.approval_revision_id,v.publication_command_id_1,
      v.initial_financial_snapshot_id,v.initial_root_timesheet_id,v.initial_root_version,v.initial_authorisation_generation,
      v.initial_authorised_row_signature,v.initial_financial_snapshot_digest,v.initial_inventory_digest,v.initial_entitlement_digest,
      v.initial_detail_digest,v.initial_policy_digest,v.initial_certificate_digest,v.component_sha256)
    is distinct from ((cert->>'candidate_id')::uuid,(cert->>'work_id')::uuid,(cert->>'work_id')::uuid,(cert->>'revision_id')::uuid,
      (cert->>'command_id')::uuid,(origin->>'financial_snapshot_id')::uuid,(origin->>'root_timesheet_id')::uuid,
      (origin->>'root_version')::integer,(origin->>'authorisation_generation')::integer,origin->>'authorised_row_signature',
      decode(origin->>'financial_snapshot_digest','hex'),decode(basis->>'inventory_digest','hex'),decode(basis->>'entitlement_digest','hex'),
      decode(basis->>'detail_digest','hex'),decode(basis->>'policy_fingerprint','hex'),decode(cert->>'certificate_digest','hex'),
      decode(component->>'component_sha256','hex'))
     or (v.approved_line_id,v.classification_line_id,v.canonical_component_key,v.approval_component_key,
         v.approval_source_channel,v.tax_treatment,v.publication_work_id_1,v.publication_revision_id_1)
       is distinct from (l.id,l.id,l.component_key,l.component_key,cert->>'source_channel',l.tax_treatment,
         (cert->>'work_id')::uuid,(cert->>'revision_id')::uuid)
     or v.binding_digest is distinct from sha256(convert_to(jsonb_build_array('INITIAL_AUTHORISED_TSFIN_V1',v.canonical_work_id,
       v.canonical_component_key,v.approval_revision_id,v.approved_line_id,v.initial_root_authorisation_id,
       cert->>'certificate_digest',cert->>'command_id',component->>'component_sha256')::text,'UTF8'))
  then raise exception 'BPAY_NEXT_INITIAL_CAPTURE_CERTIFICATE_CHANGED' using errcode='23514';end if;
end
$function$;

alter function private.bpay_next_initial_tsfin_certificate_v1(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_initial_tsfin_bind_v1(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_initial_tsfin_bound_assert_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_initial_tsfin_certificate_v1(uuid),private.bpay_next_initial_tsfin_bind_v1(uuid),
  private.bpay_next_initial_tsfin_bound_assert_v1(uuid) from public,anon,authenticated,service_role;

-- Read and freeze actual DAILY authority; this function calculates no money.
create or replace function private.bpay_next_daily_approval_evidence_v1(p_financial_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = pg_catalog, public, private
as $function$
declare
  v_tf public.timesheets_financials%rowtype;
  v_ts public.timesheets%rowtype;
  v_contract public.contracts%rowtype;
  v_context record;
  v_date date;
  v_rates jsonb;
  v_selected jsonb;
  v_paye jsonb;
  v_umbrella jsonb;
  v_rows jsonb;
  v_bucket record;
begin
  select tf.* into strict v_tf from public.timesheets_financials tf where tf.id=p_financial_id;
  select t.* into strict v_ts from public.timesheets t where t.timesheet_id=v_tf.timesheet_id;
  if v_ts.sheet_scope is distinct from 'DAILY'::public.timesheet_scope_enum
     or v_ts.line_type::text is distinct from 'HOURS'
     or v_ts.is_current is distinct from true or v_ts.archived_at_utc is not null or v_ts.revoked_at is not null
     or v_ts.is_adjustment is true or v_ts.parent_timesheet_id is not null or v_ts.correction_id is not null
     or nullif(btrim(v_ts.adjustment_origin),'') is not null or nullif(btrim(v_ts.correction_kind),'') is not null
     or nullif(btrim(v_ts.booking_id),'') is null
     or v_tf.is_current is distinct from true or v_tf.is_stale is distinct from false
     or v_tf.timesheet_version is distinct from v_ts.version
     or v_tf.authorised_at_utc is null or v_ts.authorised_at_server is null
     or v_tf.basis::text is distinct from 'SELF_REPORTED'
     or v_tf.candidate_id is null or v_tf.client_id is null or nullif(btrim(v_tf.role),'') is null
     or upper(v_tf.pay_method) not in ('PAYE','UMBRELLA') or v_tf.pay_method is null
     or v_tf.has_rate_issue is distinct from false or v_tf.has_pay_channel_issue is distinct from false
     or v_tf.invoice_breakdown_json->>'mode' is distinct from 'AGGREGATE'
     or jsonb_typeof(v_tf.policy_snapshot_json) is distinct from 'object'
     or jsonb_typeof(v_tf.rate_source_refs_json) is distinct from 'object'
     or v_tf.worked_start_iso is null or v_tf.worked_end_iso is null or v_tf.worked_end_iso<=v_tf.worked_start_iso
     or (v_tf.worked_start_iso,v_tf.worked_end_iso,v_tf.break_start_iso,v_tf.break_end_iso,v_tf.break_minutes)
        is distinct from (v_ts.worked_start_iso,v_ts.worked_end_iso,v_ts.break_start_iso,v_ts.break_end_iso,v_ts.break_minutes)
     or (v_tf.break_start_iso is null)<>(v_tf.break_end_iso is null)
     or (v_tf.break_start_iso is not null and v_tf.break_end_iso<=v_tf.break_start_iso)
     or v_tf.break_minutes<0
     or v_tf.additional_units_json is distinct from '{}'::jsonb
     or v_tf.additional_pay_ex_vat is distinct from 0::numeric
     or coalesce(v_tf.expenses_pay_ex_vat,0)<>0 or coalesce(v_tf.mileage_pay_ex_vat,0)<>0
     or coalesce(v_tf.mileage_units,0)<>0 or coalesce(v_tf.travel_pay_ex_vat,0)<>0
     or coalesce(v_tf.accommodation_pay_ex_vat,0)<>0 or coalesce(v_tf.other_pay_ex_vat,0)<>0 then
    raise exception using errcode='23514',message='BPAY_NEXT_DAILY_APPROVAL_PROVENANCE_REQUIRED';
  end if;
  -- A real contracted DAILY retains its existing Contract identity. This
  -- does not turn a Contract edit into authorisation or manufacture a Contract
  -- for a contractless Daily. Both paths require the same authorised TF below.
  if v_ts.contract_id is not null then
    select c.* into strict v_contract from public.contracts c where c.id=v_ts.contract_id;
    if v_contract.candidate_id is distinct from v_tf.candidate_id
       or v_contract.client_id is distinct from v_tf.client_id then
      raise exception using errcode='23514',message='BPAY_NEXT_DAILY_CONTRACT_IDENTITY_CONFLICT';
    end if;
  end if;
  -- The existing canonical context resolves the factual Candidate and Office
  -- financial Client. No latest-history lookup or Rota re-admission.
  select ctx.* into strict v_context
    from public.tsfin_load_context_batch(array[v_ts.timesheet_id]) ctx;
  if v_context.effective_timesheet_id is distinct from v_ts.timesheet_id
     or (v_context.out_cur_fin->>'id') is distinct from v_tf.id::text
     or (v_context.out_candidate->>'id') is distinct from v_tf.candidate_id::text
     or v_context.out_client_id is distinct from v_tf.client_id then
    raise exception using errcode='23514',message='BPAY_NEXT_DAILY_CONTEXT_IDENTITY_CONFLICT';
  end if;
  v_date:=(v_tf.worked_start_iso at time zone 'Europe/London')::date;
  if v_ts.week_ending_date is distinct from v_date+(7-extract(isodow from v_date)::integer) then
    raise exception using errcode='23514',message='BPAY_NEXT_DAILY_WORK_DATE_CONFLICT';
  end if;
  -- Both channels use the SAME existing dated override/default resolver.
  -- The opposite channel remains unavailable when that authority returns NULL.
  select jsonb_object_agg(r.rate_type,to_jsonb(r)) into v_rates
    from public.tsfin_resolve_rates_batch(jsonb_build_array(
      jsonb_build_object('k',v_ts.timesheet_id,'candidate_id',v_tf.candidate_id,
        'client_id',v_tf.client_id,'role',v_tf.role,'band',v_tf.band,'date',v_date,'rate_type','PAYE'),
      jsonb_build_object('k',v_ts.timesheet_id,'candidate_id',v_tf.candidate_id,
        'client_id',v_tf.client_id,'role',v_tf.role,'band',v_tf.band,'date',v_date,'rate_type','UMBRELLA')
    )) r;
  v_selected:=v_rates->upper(v_tf.pay_method);
  if v_selected is null or coalesce(v_selected->>'source_kind','') not in ('CANDIDATE_OVERRIDE','CLIENT_DEFAULT')
     or private._candidate_daily_rate_contract_v1(v_selected) is distinct from
        private._candidate_daily_rate_contract_v1(jsonb_build_object(
          'source_kind',v_tf.rate_source_refs_json->>'kind',
          'override_id',v_tf.rate_source_refs_json->>'override_id',
          'default_id',v_tf.rate_source_refs_json->>'default_id',
          'rate_type',v_tf.rate_source_refs_json->>'rate_type',
          'pay_day',v_tf.pay_day,'pay_night',v_tf.pay_night,'pay_sat',v_tf.pay_sat,'pay_sun',v_tf.pay_sun,'pay_bh',v_tf.pay_bh,
          'charge_day',v_tf.charge_day,'charge_night',v_tf.charge_night,'charge_sat',v_tf.charge_sat,
          'charge_sun',v_tf.charge_sun,'charge_bh',v_tf.charge_bh
        )) then
    raise exception using errcode='40001',message='BPAY_NEXT_DAILY_RATE_AUTHORITY_STALE';
  end if;
  v_paye:=v_rates->'PAYE'; v_umbrella:=v_rates->'UMBRELLA';
  if (v_paye-array['k','rate_type','source_kind','override_id','pay_day','pay_night','pay_sat','pay_sun','pay_bh'])
     is distinct from
     (v_umbrella-array['k','rate_type','source_kind','override_id','pay_day','pay_night','pay_sat','pay_sun','pay_bh']) then
    raise exception using errcode='23514',message='BPAY_NEXT_DAILY_CHANNEL_CONTEXT_CONFLICT';
  end if;
  for v_bucket in select x.value from jsonb_each(v_rates) channel
    cross join lateral jsonb_each(channel.value) x
    where x.key in ('pay_day','pay_night','pay_sat','pay_sun','pay_bh',
                    'charge_day','charge_night','charge_sat','charge_sun','charge_bh')
  loop
    if v_bucket.value<>'null'::jsonb and
       ((v_bucket.value#>>'{}')::numeric<>round((v_bucket.value#>>'{}')::numeric,6)
        or (v_bucket.value#>>'{}')::numeric<0
        or abs((v_bucket.value#>>'{}')::numeric)>=1000000000000) then
      raise exception using errcode='22003',message='BPAY_NEXT_DAILY_AVAILABLE_RATE_PRECISION_INVALID';
    end if;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('rate_family','STANDARD','rate_code',b.code,
      'unit_label',nullif(btrim(v_contract.bucket_labels_json->>lower(b.code)),''),
      'paye_rate',(v_paye->>b.pay_key)::numeric,
      'umbrella_rate',(v_umbrella->>b.pay_key)::numeric,'charge_rate',(v_paye->>b.charge_key)::numeric)
      order by b.code),'[]'::jsonb) into v_rows
    from (values ('DAY'::text,'pay_day'::text,'charge_day'::text),
      ('NIGHT','pay_night','charge_night'),('SAT','pay_sat','charge_sat'),
      ('SUN','pay_sun','charge_sun'),('BH','pay_bh','charge_bh')) b(code,pay_key,charge_key)
    where (v_paye->>b.pay_key) is not null or (v_umbrella->>b.pay_key) is not null
       or (v_paye->>b.charge_key) is not null;
  return jsonb_build_object('contract_version','BPAY_NEXT_DAILY_APPROVAL_EVIDENCE_V1',
    'timesheet_id',v_ts.timesheet_id,'timesheet_version',v_ts.version,'financial_id',v_tf.id,
    'booking_id',v_ts.booking_id,'candidate_id',v_tf.candidate_id,'client_id',v_tf.client_id,
    'work_date',v_date,'role',v_tf.role,'band',v_tf.band,
    'policy_snapshot_json',v_tf.policy_snapshot_json,'rate_source_refs_json',v_tf.rate_source_refs_json,
    'resolved_channels',v_rates,'rates',v_rows);
end
$function$;
alter function private.bpay_next_daily_approval_evidence_v1(uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_daily_approval_evidence_v1(uuid)
  from public,anon,authenticated,service_role;



-- E-only V2 proposed functions, acceptance-time snapshot correction.
-- Frozen V1 is preserved. No W/DB adoption or installed-state proof.



-- Validate the closed, complete saved stage snapshot. Only immutable helper
-- inputs from this certificate are used for integrity rederivation: never
-- current Contract, TSFIN, Candidate, Client or settings rows.
create or replace function private.weekly_source_destination_stage_snapshot_check_v1(p_snapshot jsonb)
returns void language plpgsql immutable
set search_path to 'pg_catalog','private','pg_temp'
as $function$
declare v_inputs jsonb; v_metadata jsonb; v_metadata_inputs jsonb; v_row jsonb; v_key text; v_expected jsonb;
begin
  perform private.weekly_source_publication_require_keys_v1(p_snapshot,array[
    'schema_version','root_timesheet_id','root_timesheet_version','root_booking_id',
    'candidate_id','client_id','contract_id','financial_snapshot_id','destination_pay_channel',
    'metadata','metadata_inputs','rate_inputs','rate_schedule'],'destination.stage_snapshot');
  v_inputs:=p_snapshot->'rate_inputs'; v_metadata:=p_snapshot->'metadata';
  v_metadata_inputs:=p_snapshot->'metadata_inputs';
  perform private.weekly_source_publication_require_keys_v1(v_inputs,array[
    'rates_json','bucket_labels_json','additional_rates_json','mileage_pay_rate','mileage_charge_rate',
    'mileage_fallback_inputs'],'destination.stage_rate_inputs');
  perform private.weekly_source_publication_require_keys_v1(v_inputs->'mileage_fallback_inputs',array[
    'financial_snapshot_id','financial_pay_rate','financial_charge_rate','contract_pay_rate',
    'contract_charge_rate','candidate_pay_rate','client_charge_rate'],'destination.stage_mileage_inputs');
  perform private.weekly_source_publication_require_keys_v1(v_metadata,array[
    'candidate_display_name','candidate_reference','client_display_name','job_title','band_label',
    'timesheet_reference'],'destination.stage_metadata');
  perform private.weekly_source_publication_require_keys_v1(p_snapshot->'metadata_inputs',array[
    'candidate_display_name','candidate_first_name','candidate_last_name','candidate_tms_ref',
    'client_name','contract_role','contract_band','timesheet_reference'],'destination.stage_metadata_inputs');
  if p_snapshot->>'schema_version' is distinct from 'WEEKLY_SOURCE_DESTINATION_STAGE_SNAPSHOT_V1'
     or coalesce(p_snapshot->>'destination_pay_channel','') not in ('PAYE','UMBRELLA')
     or nullif(p_snapshot->>'root_timesheet_id','') is null
     or nullif(p_snapshot->>'candidate_id','') is null
     or nullif(p_snapshot->>'client_id','') is null
     or nullif(p_snapshot->>'contract_id','') is null
     or coalesce(p_snapshot->>'root_timesheet_version','')!~'^[0-9]+$'
     or nullif(p_snapshot->>'root_booking_id','') is null
     or jsonb_typeof(p_snapshot->'rate_schedule') is distinct from 'array'
     or jsonb_array_length(p_snapshot->'rate_schedule') not between 5 and 11 then
    raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_SNAPSHOT_INVALID' using errcode='23514'; end if;
  foreach v_key in array array['candidate_display_name','candidate_reference','client_display_name',
      'job_title','band_label','timesheet_reference'] loop
    if jsonb_typeof(v_metadata->v_key) not in ('string','null') then
      raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_METADATA_INVALID' using errcode='23514'; end if;
  end loop;
  foreach v_key in array array['candidate_display_name','candidate_first_name','candidate_last_name',
      'candidate_tms_ref','client_name','contract_role','contract_band','timesheet_reference'] loop
    if jsonb_typeof(v_metadata_inputs->v_key) not in ('string','null') then
      raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_METADATA_INPUT_INVALID' using errcode='23514'; end if;
  end loop;
  if v_metadata is distinct from jsonb_build_object('candidate_display_name',coalesce(
      nullif(btrim(v_metadata_inputs->>'candidate_display_name'),''),
      nullif(btrim(concat_ws(' ',v_metadata_inputs->>'candidate_first_name',v_metadata_inputs->>'candidate_last_name')),''),
      p_snapshot->>'candidate_id'),
      'candidate_reference',v_metadata_inputs->>'candidate_tms_ref','client_display_name',v_metadata_inputs->>'client_name',
      'job_title',v_metadata_inputs->>'contract_role','band_label',v_metadata_inputs->>'contract_band',
      'timesheet_reference',v_metadata_inputs->>'timesheet_reference') then
    raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_METADATA_NOT_EXACT' using errcode='23514'; end if;
  for v_row in select value from jsonb_array_elements(p_snapshot->'rate_schedule') loop
    perform private.weekly_source_publication_require_keys_v1(v_row,array[
      'rate_family','rate_code','unit_label','paye_rate','umbrella_rate','charge_rate'],'destination.stage_rate_row');
    if jsonb_typeof(v_row->'rate_family') is distinct from 'string'
       or jsonb_typeof(v_row->'rate_code') is distinct from 'string'
       or jsonb_typeof(v_row->'unit_label') not in ('string','null')
       or (v_row->>'unit_label' is not null and octet_length(v_row->>'unit_label')>512)
       or not ((v_row->>'rate_family'='STANDARD' and v_row->>'rate_code' in ('DAY','NIGHT','SAT','SUN','BH'))
         or (v_row->>'rate_family'='ADDITIONAL' and v_row->>'rate_code' ~ '^EX[1-5]$')
         or (v_row->>'rate_family'='MILEAGE' and v_row->>'rate_code'='MILE')) then
      raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_RATE_ROW_INVALID' using errcode='23514'; end if;
    foreach v_key in array array['paye_rate','umbrella_rate','charge_rate'] loop
      if jsonb_typeof(v_row->v_key) not in ('number','null') or
         (v_row->>v_key is not null and ((v_row->>v_key)::numeric<0
           or (v_row->>v_key)::numeric>=1000000000000
           or (v_row->>v_key)::numeric is distinct from round((v_row->>v_key)::numeric,6))) then
        raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_RATE_INVALID' using errcode='23514'; end if;
    end loop;
    if v_row->'paye_rate'='null'::jsonb and v_row->'umbrella_rate'='null'::jsonb and v_row->'charge_rate'='null'::jsonb then
      raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_RATE_EMPTY' using errcode='23514'; end if;
  end loop;
  -- Exact output of the existing immutable rate-row owner, in canonical order.
  -- This is a frozen-input integrity check, not a release-time pricing read.
  select jsonb_agg(to_jsonb(r) order by r.rate_family,r.rate_code) into v_expected
    from private.bpay_next_contract_rate_rows_v1(v_inputs->'rates_json',
      nullif(v_inputs->'bucket_labels_json','null'::jsonb),nullif(v_inputs->'additional_rates_json','null'::jsonb),
      (v_inputs->>'mileage_pay_rate')::numeric,(v_inputs->>'mileage_charge_rate')::numeric) r;
  if p_snapshot->'rate_schedule' is distinct from v_expected
     or exists(select 1 from jsonb_array_elements(p_snapshot->'rate_schedule') r
       group by r->>'rate_family',r->>'rate_code' having count(*)<>1)
     or (select count(*) from jsonb_array_elements(p_snapshot->'rate_schedule') r
       where r->>'rate_family'='STANDARD' and (r->>'charge_rate')::numeric>0
         and (r->>case when p_snapshot->>'destination_pay_channel'='PAYE' then 'paye_rate' else 'umbrella_rate' end)::numeric>0)<>5
     or p_snapshot->'financial_snapshot_id' is distinct from v_inputs#>'{mileage_fallback_inputs,financial_snapshot_id}'
     or (v_inputs->>'mileage_pay_rate')::numeric is distinct from coalesce(
       (v_inputs#>>'{mileage_fallback_inputs,financial_pay_rate}')::numeric,
       (v_inputs#>>'{mileage_fallback_inputs,contract_pay_rate}')::numeric,
       (v_inputs#>>'{mileage_fallback_inputs,candidate_pay_rate}')::numeric)
     or (v_inputs->>'mileage_charge_rate')::numeric is distinct from coalesce(
       (v_inputs#>>'{mileage_fallback_inputs,financial_charge_rate}')::numeric,
       (v_inputs#>>'{mileage_fallback_inputs,contract_charge_rate}')::numeric,
       (v_inputs#>>'{mileage_fallback_inputs,client_charge_rate}')::numeric) then
    raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_SCHEDULE_NOT_EXACT' using errcode='23514'; end if;
end;
$function$;

-- Genuine read-only rate/fact loader. The accepted before-position is the
-- existing I-7 authority; rebuilding with the existing pair constructor is the
-- exact request/currentness proof, not a caller's HEAD or hash assertion.
create or replace function private.weekly_source_destination_reprice_context_v1(
  p_actor uuid,p_base_request jsonb
) returns jsonb language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_base jsonb; v_rebuilt jsonb; v_source jsonb; v_target jsonb; v_inventory jsonb;
  v_before jsonb; v_component jsonb; v_components jsonb:='[]'::jsonb;
  v_roots uuid[]; v_moved uuid[]; v_head uuid; v_root public.timesheets%rowtype;
  v_contract public.contracts%rowtype; v_detail private.bpay_next_source_chosen_detail%rowtype;
  v_tf public.timesheets_financials%rowtype; v_candidate public.candidates%rowtype; v_client public.clients%rowtype;
  v_stage jsonb; v_schedule jsonb;
  v_e public.weekly_source_row_economic_snapshots%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_final public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype; v_group public.weekly_source_groups%rowtype;
  v_policy jsonb; v_settings jsonb; v_profile text; v_key text; v_prefix text; v_pay jsonb; v_charge jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
      nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  v_base:=private.weekly_source_publication_request_canonical_v1(p_base_request,'IMMEDIATE',null);
  if p_actor is null or v_base#>'{financial_request,contract_choices,1,destination_reprice}' is not null
     or jsonb_array_length(v_base->'member_root_ids')<>2
     or p_base_request#>>'{control,bundle_kind}' is distinct from 'CROSS_CONTRACT_A_B'
     or v_base#>>'{financial_request,source_revision,origin_kind}' is not null then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BASE_INVALID' using errcode='22023'; end if;
  v_roots:=array[(v_base#>>'{member_root_ids,0}')::uuid,(v_base#>>'{member_root_ids,1}')::uuid];
  select array_agg((value#>>'{}')::uuid order by value#>>'{}') into v_moved
    from jsonb_array_elements(p_base_request#>'{control,moved_component_ids}');
  v_source:=v_base#>'{financial_request,member_entitlements,0}';
  v_target:=v_base#>'{financial_request,member_entitlements,1}';
  select * into strict v_root from public.timesheets where timesheet_id=v_roots[2];
  select * into strict v_contract from public.contracts where id=v_root.contract_id;
  -- These are the actual1550 inputs, read under this one STABLE pricing
  -- statement. No invented fallback, rows, rates, clocks or bucket units.
  select * into v_tf from public.timesheets_financials
    where timesheet_id=v_root.timesheet_id and is_current=true;
  select * into strict v_candidate from public.candidates where id=v_contract.candidate_id;
  select * into strict v_client from public.clients where id=v_contract.client_id;
  select jsonb_agg(to_jsonb(r) order by r.rate_family,r.rate_code) into v_schedule
    from private.bpay_next_contract_rate_rows_v1(v_contract.rates_json,v_contract.bucket_labels_json,
      v_contract.additional_rates_json,
      coalesce(v_tf.mileage_pay_rate,v_contract.mileage_pay_rate,v_candidate.mileage_pay_rate),
      coalesce(v_tf.mileage_charge_rate,v_contract.mileage_charge_rate,v_client.mileage_charge_rate)) r;
  v_stage:=jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_STAGE_SNAPSHOT_V1',
    'root_timesheet_id',v_root.timesheet_id,'root_timesheet_version',v_root.version,'root_booking_id',v_root.booking_id,
    'candidate_id',v_contract.candidate_id,'client_id',v_contract.client_id,'contract_id',v_contract.id,
    'financial_snapshot_id',v_tf.id,'destination_pay_channel',v_contract.pay_method_snapshot,
    'metadata',jsonb_build_object('candidate_display_name',coalesce(nullif(btrim(v_candidate.display_name),''),
      nullif(btrim(concat_ws(' ',v_candidate.first_name,v_candidate.last_name)),''),v_candidate.id::text),
      'candidate_reference',v_candidate.tms_ref,'client_display_name',v_client.name,
      'job_title',v_contract.role,'band_label',v_contract.band,'timesheet_reference',v_root.reference_number),
    'metadata_inputs',jsonb_build_object('candidate_display_name',v_candidate.display_name,
      'candidate_first_name',v_candidate.first_name,'candidate_last_name',v_candidate.last_name,
      'candidate_tms_ref',v_candidate.tms_ref,'client_name',v_client.name,'contract_role',v_contract.role,
      'contract_band',v_contract.band,'timesheet_reference',v_root.reference_number),
    'rate_inputs',jsonb_build_object('rates_json',v_contract.rates_json,'bucket_labels_json',v_contract.bucket_labels_json,
      'additional_rates_json',v_contract.additional_rates_json,
      'mileage_pay_rate',coalesce(v_tf.mileage_pay_rate,v_contract.mileage_pay_rate,v_candidate.mileage_pay_rate),
      'mileage_charge_rate',coalesce(v_tf.mileage_charge_rate,v_contract.mileage_charge_rate,v_client.mileage_charge_rate),
      'mileage_fallback_inputs',jsonb_build_object('financial_snapshot_id',v_tf.id,
        'financial_pay_rate',v_tf.mileage_pay_rate,'financial_charge_rate',v_tf.mileage_charge_rate,
        'contract_pay_rate',v_contract.mileage_pay_rate,'contract_charge_rate',v_contract.mileage_charge_rate,
        'candidate_pay_rate',v_candidate.mileage_pay_rate,'client_charge_rate',v_client.mileage_charge_rate)),
    'rate_schedule',v_schedule);
  perform private.weekly_source_destination_stage_snapshot_check_v1(v_stage);
  if v_contract.candidate_id is distinct from (v_base->>'candidate_id')::uuid
     or v_contract.pay_method_snapshot is null
     or v_contract.pay_method_snapshot not in ('PAYE','UMBRELLA') then
    raise exception 'WEEKLY_SOURCE_DESTINATION_RATE_OWNER_INVALID' using errcode='23514'; end if;
  v_rebuilt:=private.weekly_source_entitlement_proposal_cross_contract_request_v1(
    v_roots[1],v_roots[2],(v_base#>>'{financial_request,source_revision,final_revision_id}')::uuid,
    (v_base->>'decision_bundle_id')::uuid,(v_base->>'bundle_revision')::bigint,
    (v_base#>>'{head_ids,0}')::uuid,(v_base#>>'{head_ids,1}')::uuid,(v_base->>'decision_id')::uuid,
    v_moved,v_source->>'authority_kind',v_target->>'authority_kind',
    v_base#>>'{financial_request,contract_choices,0,selection_method}',
    v_base#>>'{financial_request,contract_choices,1,selection_method}',
    case when p_base_request#>'{control,target_root_authorisation}'<>'null'::jsonb then p_actor end,
    case when p_base_request#>'{control,whole_root_office_review}'<>'null'::jsonb then p_actor end,
    (p_base_request#>>'{control,whole_root_office_review,reviewed_at_utc}')::timestamptz);
  if private.weekly_source_publication_request_canonical_v1(v_rebuilt,'IMMEDIATE',null) is distinct from v_base
     or v_rebuilt->'control' is distinct from p_base_request->'control' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BEFORE_CHANGED' using errcode='40001'; end if;
  select * into strict v_final from public.weekly_source_final_revisions
    where id=(v_base#>>'{financial_request,source_revision,final_revision_id}')::uuid and state='CURRENT';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_final.source_cycle_id;
  select * into strict v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  perform private.weekly_source_office_authority_v1(p_actor,'APPROVE_PROTECTED_PAY',v_group.id,
    v_contract.client_id,v_cycle.finalisation_week_ending);
  perform private.weekly_source_office_authority_v1(p_actor,'APPROVE_PROTECTED_PAY',v_group.id,
    (select c.client_id from public.contracts c join public.timesheets t on t.contract_id=c.id
      where t.timesheet_id=v_roots[1]),v_cycle.finalisation_week_ending);
  v_inventory:=private.weekly_source_effective_inventory_v1(v_roots[1]);
  v_head:=(v_inventory->>'head_id')::uuid;
  -- V1 positively supports genuine chosen HEAD economics only. Initial TSFIN,
  -- amount-led components and later bucket/policy changes are explicit OPEN
  -- obligations, never implicitly priced with invented hourly equivalence.
  if v_head is null then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_INITIAL_DETAIL_OWNER_REQUIRED' using errcode='55000'; end if;
  for v_before in select value from jsonb_array_elements(v_inventory->'components')
    order by value->>'component_id'
  loop
    v_component:=private.weekly_source_publication_component_canonical_v1(v_before-'component_sha256','destination.before');
    if v_component->>'component_kind' is distinct from 'WORKED_TIME'
       or v_component->'unit_count'<>'null'::jsonb or v_component->'unit_pay_rate'<>'null'::jsonb then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_COMPONENT_POLICY_REQUIRED' using errcode='55000',
        detail=jsonb_build_object('component_id',v_component->>'component_id','component_kind',v_component->>'component_kind')::text;
    end if;
    select * into strict v_detail from private.bpay_next_source_chosen_detail
      where head_id=v_head and component_id=(v_component->>'component_id')::uuid;
    if v_detail.component_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
         private.weekly_source_publication_component_content_v1(v_component))
       or v_detail.detail_sha256 is distinct from sha256(convert_to(v_detail.detail_json::text,'UTF8'))
       or nullif(v_detail.detail_json->>'economic_snapshot_id','') is null then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_ECONOMIC_ORIGIN_REQUIRED' using errcode='23514'; end if;
    select * into strict v_e from public.weekly_source_row_economic_snapshots
      where id=(v_detail.detail_json->>'economic_snapshot_id')::uuid;
    select * into strict v_row from public.weekly_source_upload_rows where id=v_e.upload_row_id;
    select p.profile_code into strict v_profile from public.weekly_source_uploads u
      join public.weekly_source_format_profiles p on p.id=u.source_format_profile_id where u.id=v_row.upload_id;
    if v_e.work_event_id::text is distinct from v_component->>'component_member_identity'
       or v_e.candidate_id is distinct from v_contract.candidate_id
       or v_detail.detail_json->>'work_date' is distinct from v_component->>'work_date'
       or (v_detail.detail_json->>'break_minutes')::integer is distinct from v_e.break_minutes
       or to_char(v_row.start_at_local,'HH24:MI') is distinct from v_detail.detail_json->>'start'
       or to_char(v_row.end_at_local,'HH24:MI') is distinct from v_detail.detail_json->>'end'
       or v_row.work_date::text is distinct from v_component->>'work_date' then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_WORK_FACTS_CHANGED' using errcode='23514'; end if;
    v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,(v_component->>'work_date')::date);
    v_settings:=private._contract_settings_effective_core_v1(v_contract.client_id,v_contract.id,
      (v_component->>'work_date')::date,'IMPORT',null);
    if v_policy->>'weekly_rate_classification_method' is distinct from v_e.rate_method then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BUCKET_POLICY_REVIEW_REQUIRED' using errcode='55000'; end if;
    v_prefix:=case when v_contract.pay_method_snapshot='PAYE' then 'paye_' else 'umb_' end;
    v_pay:='{}'::jsonb; v_charge:='{}'::jsonb;
    foreach v_key in array array['day','night','sat','sun','bh'] loop
      if coalesce(v_contract.rates_json->>(v_prefix||v_key),'')!~'^[+]?[0-9]+([.][0-9]{1,6})?$'
         or coalesce(v_contract.rates_json->>('charge_'||v_key),'')!~'^[+]?[0-9]+([.][0-9]{1,6})?$'
         or (v_contract.rates_json->>(v_prefix||v_key))::numeric<=0
         or (v_contract.rates_json->>('charge_'||v_key))::numeric<=0 then
        raise exception 'WEEKLY_SOURCE_DESTINATION_RATE_AUTHORITY_INCOMPLETE' using errcode='55000'; end if;
      v_pay:=v_pay||jsonb_build_object(v_key,(v_contract.rates_json->>(v_prefix||v_key))::numeric);
      v_charge:=v_charge||jsonb_build_object(v_key,(v_contract.rates_json->>('charge_'||v_key))::numeric);
      if coalesce((v_component->>('hours_'||v_key))::numeric,0) is distinct from
        (to_jsonb(v_e)->>('hours_'||v_key))::numeric then
        raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BUCKET_FACTS_CHANGED' using errcode='23514'; end if;
    end loop;
    v_components:=v_components||jsonb_build_array(jsonb_build_object(
      'component',v_component,'before_component_sha256',encode(v_detail.component_sha256,'hex'),
      'before_detail',v_detail.detail_json,'before_detail_sha256',encode(v_detail.detail_sha256,'hex'),
      'original_economic_snapshot_id',v_e.id,'original_calculation_fingerprint',encode(v_e.calculation_fingerprint,'hex'),
      'original_economic',v_e.canonical_result_json,
      'server_row',jsonb_build_object('profile_id',v_profile,'start_at_local',to_char(v_row.start_at_local,'YYYY-MM-DD"T"HH24:MI:SS'),
        'end_at_local',to_char(v_row.end_at_local,'YYYY-MM-DD"T"HH24:MI:SS'),'break_minutes',v_e.break_minutes,
        'actual_net_minutes',v_e.paid_minutes,'source_shift_charge_pence',v_row.source_shift_charge_pence::text),
      'destination_contract',jsonb_build_object('contract_id',v_contract.id,'pay_type',v_contract.pay_method_snapshot,
        'updated_at',v_contract.updated_at,'rates_json',v_contract.rates_json,'additional_rates_json',v_contract.additional_rates_json,
        -- The real owner includes a read-time clock outside its fingerprint.
        -- Retain every authority fact; only that non-economic clock is omitted
        -- so two unchanged reads can share one exact review digest.
        'effective_policy',v_policy,'settings_authority',v_settings-'resolved_at_utc'),
      'destination_pay_rates',v_pay,'destination_charge_rates',v_charge));
  end loop;
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_RATE_CONTEXT_V1',
    'actor_user_id',p_actor,'agency_id',v_group.agency_id,'base_request',p_base_request,
    'before_canonical',v_base,'destination_pay_channel',v_contract.pay_method_snapshot,
    'stage_snapshot',v_stage,'components',v_components);
end;
$function$;

-- Preserve V1 quote rederivation: actual destination rates times the existing
-- genuine canonical rounded bucket-hours, not a new minutes/60 arithmetic.
-- JS calculator identity alone is never an admission witness.
create or replace function private.weekly_source_destination_reprice_quote_v1(
  p_context jsonb,p_calculations jsonb
) returns jsonb language plpgsql immutable
set search_path to 'pg_catalog','private','pg_temp'
as $function$
declare
  v_items jsonb:='[]'::jsonb; v_target jsonb:='[]'::jsonb; v_item jsonb; v_calc jsonb; v_e jsonb;
  v_original jsonb; v_component jsonb; v_after jsonb; v_request jsonb; v_detail jsonb;
  v_key text; v_pay numeric; v_charge numeric; v_sign integer; v_review jsonb; v_count integer;
  v_price jsonb; v_price_expected jsonb; v_source_pence bigint; v_calculated_pence bigint;
  v_difference bigint; v_result text; v_needs_acceptance boolean; v_acceptance text;
begin
  if jsonb_typeof(p_calculations) is distinct from 'array'
     or jsonb_array_length(p_calculations) is distinct from jsonb_array_length(p_context->'components') then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CALCULATION_INCOMPLETE' using errcode='22023'; end if;
  for v_item in select value from jsonb_array_elements(p_context->'components') order by value#>>'{component,component_id}' loop
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_calc from jsonb_array_elements(p_calculations)
      where value->>'component_id'=v_item#>>'{component,component_id}';
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CALCULATION_INCOMPLETE' using errcode='22023'; end if;
    perform private.weekly_source_publication_require_keys_v1(v_calc,array['component_id','economic_snapshot','price_comparison'],'destination.calculation');
    v_e:=v_calc->'economic_snapshot'; v_original:=v_item->'original_economic'; v_component:=v_item->'component';
    perform private.weekly_source_publication_require_keys_v1(v_e,array[
      'schema_version','calculator_version','source_mode','rate_method','sign','paid_minutes','break_minutes',
      'bucket_minutes','hours','pay_rates','charge_rates','total_pay_pence','calculated_charge_pence']
      ||case when v_e ? 'break_allocation' then array['break_allocation'] else array[]::text[] end,'destination.economic_snapshot');
    if v_e->>'schema_version' is distinct from 'WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1'
       or v_e->>'calculator_version' is distinct from 'WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1'
       or v_e->'source_mode' is distinct from v_original->'source_mode'
       or v_e->'rate_method' is distinct from v_original->'rate_method'
       or v_e->'sign' is distinct from v_original->'sign'
       or v_e->'paid_minutes' is distinct from v_original->'paid_minutes'
       or v_e->'break_minutes' is distinct from v_original->'break_minutes'
       or v_e->'bucket_minutes' is distinct from v_original->'bucket_minutes'
       or v_e->'hours' is distinct from v_original->'hours'
       or coalesce(v_e->'break_allocation','null'::jsonb) is distinct from coalesce(v_original->'break_allocation','null'::jsonb)
       or v_e->'pay_rates' is distinct from v_item->'destination_pay_rates'
       or v_e->'charge_rates' is distinct from v_item->'destination_charge_rates'
       or coalesce(v_e->>'total_pay_pence','')!~'^-?[0-9]{1,12}$'
       or coalesce(v_e->>'calculated_charge_pence','')!~'^-?[0-9]{1,12}$' then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CALCULATION_NOT_GENUINE' using errcode='23514'; end if;
    v_pay:=0; v_charge:=0; v_sign:=(v_original->>'sign')::integer;
    foreach v_key in array array['day','night','sat','sun','bh'] loop
      v_pay:=v_pay+abs((v_original#>>array['hours',v_key])::numeric)*(v_item#>>array['destination_pay_rates',v_key])::numeric;
      v_charge:=v_charge+abs((v_original#>>array['hours',v_key])::numeric)*(v_item#>>array['destination_charge_rates',v_key])::numeric;
    end loop;
    v_pay:=round(v_pay,2)*v_sign; v_charge:=round(v_charge,2)*v_sign;
    if (v_e->>'total_pay_pence')::bigint is distinct from (v_pay*100)::bigint
       or (v_e->>'calculated_charge_pence')::bigint is distinct from (v_charge*100)::bigint then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_TOTAL_NOT_REDERIVED' using errcode='23514'; end if;
    -- Re-derive the existing actual comparator's signed-pence classification.
    -- It is shown and accepted with the whole vector, not silently discarded
    -- when a destination charge differs from immutable source invoice facts.
    v_price:=v_calc->'price_comparison';
    perform private.weekly_source_publication_require_keys_v1(v_price,array['source_mode','result',
      'requires_office_acceptance','acceptance_kind','calculated_comparison_charge_pence',
      'source_validation_charge_pence','invoice_presentation_charge_pence','amount_authority',
      'canonical_pay_pence','signed_difference_pence'],'destination.price_comparison');
    v_calculated_pence:=(v_e->>'calculated_charge_pence')::bigint;
    if v_e->>'source_mode'='NHSP_WEEKLY' then
      if coalesce(v_item#>>'{server_row,source_shift_charge_pence}','')!~'^-?[0-9]{1,12}$' then
        raise exception 'NHSP_SOURCE_CHARGE_INVALID' using errcode='23514'; end if;
      v_source_pence:=(v_item#>>'{server_row,source_shift_charge_pence}')::bigint;
      if v_calculated_pence=0 and v_source_pence<>0 then
        raise exception 'NHSP_CALCULATED_CHARGE_ZERO_INVALID' using errcode='23514'; end if;
      if (v_source_pence>0 and v_calculated_pence<0) or (v_source_pence<0 and v_calculated_pence>0) then
        raise exception 'NHSP_SOURCE_CHARGE_SIGN_INVALID' using errcode='23514'; end if;
      v_difference:=v_source_pence-v_calculated_pence;
      v_result:=case when v_source_pence<>0 and v_calculated_pence<>0 and v_difference=0 then 'EXACT'
        when v_source_pence<>0 and v_calculated_pence<>0 and abs(v_difference)=1 then 'SOURCE_ROUNDING_EQUIVALENT'
        when v_source_pence=0 and v_calculated_pence<>0 then 'ZERO_SOURCE_CHARGE' else 'MISMATCH' end;
      v_needs_acceptance:=v_result in ('MISMATCH','ZERO_SOURCE_CHARGE');
      v_acceptance:=case when v_result='ZERO_SOURCE_CHARGE' then 'ACCEPTED_ZERO'
        when v_result='MISMATCH' then 'ACCEPTED_DISPARITY' end;
      v_price_expected:=jsonb_build_object('source_mode','NHSP_WEEKLY','result',v_result,
        'requires_office_acceptance',v_needs_acceptance,'acceptance_kind',v_acceptance,
        'calculated_comparison_charge_pence',v_calculated_pence::text,'source_validation_charge_pence',v_source_pence::text,
        'invoice_presentation_charge_pence',v_source_pence::text,'amount_authority','VALIDATED_SOURCE_PENCE',
        'canonical_pay_pence',v_e->>'total_pay_pence','signed_difference_pence',v_difference::text);
    else
      v_price_expected:=jsonb_build_object('source_mode','HEALTHROSTER_WEEKLY','result','NOT_APPLICABLE',
        'requires_office_acceptance',false,'acceptance_kind',null,
        'calculated_comparison_charge_pence',v_calculated_pence::text,'source_validation_charge_pence',null,
        'invoice_presentation_charge_pence',v_calculated_pence::text,'amount_authority','CLOUDTMS_CALCULATION',
        'canonical_pay_pence',v_e->>'total_pay_pence','signed_difference_pence',null);
    end if;
    if v_price is distinct from v_price_expected then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_PRICE_COMPARISON_NOT_REDERIVED' using errcode='23514'; end if;
    -- Stable work identity, quantity, exclusions and original charge remain
    -- exact. Destination charge calculation is informational, never invoice
    -- or Source billing-movement authority.
    v_after:=v_component||jsonb_build_object('pay_ex_vat',v_pay::numeric(12,2)::text);
    v_detail:=v_item->'before_detail'||jsonb_build_object('rates',v_item->'destination_pay_rates',
      'source_component_sha256',encode(private.weekly_source_publication_request_digest_v1(
        private.weekly_source_publication_component_content_v1(v_after)),'hex'),
      'destination_reprice',jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1',
        'destination_contract_id',v_item#>>'{destination_contract,contract_id}',
        'destination_pay_channel',p_context->>'destination_pay_channel',
        'original_economic_snapshot_id',v_item->>'original_economic_snapshot_id',
        'before_component_sha256',v_item->>'before_component_sha256',
        'before_detail_sha256',v_item->>'before_detail_sha256'));
    if octet_length(v_detail::text)>4096 then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_DETAIL_LIMIT' using errcode='22023'; end if;
    v_items:=v_items||jsonb_build_array(jsonb_build_object('component_id',v_component->>'component_id',
      'before_component',v_component,'after_content',private.weekly_source_publication_component_content_v1(v_after),
      'detail',v_detail,'economic_snapshot',v_e,'price_comparison',v_price_expected));
  end loop;
  v_request:=p_context->'base_request';
  for v_component in select value from jsonb_array_elements(v_request#>'{financial_request,member_entitlements,1,components}')
    order by (value->>'component_ordinal')::integer loop
    select value into v_item from jsonb_array_elements(v_items) where value->>'component_id'=v_component->>'component_id';
    v_target:=v_target||jsonb_build_array(case when v_item is null then v_component else
      v_component||jsonb_build_object('pay_ex_vat',v_item#>'{after_content,pay_ex_vat}') end);
  end loop;
  v_request:=jsonb_set(v_request,'{financial_request,member_entitlements,1,components}',v_target);
  v_review:=jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_V1',
    'context',p_context,'calculated_components',v_items,'complete_destination_components',v_target);
  return jsonb_build_object('review',v_review,'review_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_V1',v_review),'hex'),'request',v_request,'components',v_items);
end;
$function$;

create or replace function public.weekly_source_destination_reprice_preview_v1(
  p_actor uuid,p_base_request jsonb,p_calculations jsonb default null
) returns jsonb language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare v_context jsonb;
begin
  v_context:=private.weekly_source_destination_reprice_context_v1(p_actor,p_base_request);
  if p_calculations is null then return jsonb_build_object('ok',true,'context',v_context); end if;
  return jsonb_build_object('ok',true,'quote',private.weekly_source_destination_reprice_quote_v1(v_context,p_calculations));
end;
$function$;

-- Exact new or exact replay; review time is server-owned. I-1 family locks,
-- genuine proposal recorder, freeze/census and publication retain authority.
create or replace function public.weekly_source_destination_reprice_accept_v1(
  p_actor uuid,p_base_request jsonb,p_calculations jsonb,p_review_sha256 text,
  p_idempotency_key text,p_reason text
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_input bytea; v_saved private.weekly_source_destination_reprice_witness_v1%rowtype;
  v_context jsonb; v_quote jsonb; v_request jsonb; v_lock jsonb; v_roots uuid[];
  v_id uuid; v_time timestamptz; v_record jsonb; v_result jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
      nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor is null or char_length(btrim(coalesce(p_reason,''))) not between 1 and 2000
     or char_length(coalesce(p_idempotency_key,'')) not between 16 and 200
     or coalesce(p_review_sha256,'')!~'^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_ACCEPT_INVALID' using errcode='22023'; end if;
  v_input:=private.weekly_source_sha256_jsonb_v1('WEEKLY_SOURCE_DESTINATION_REPRICE_ACCEPT_V1',jsonb_build_object(
    'actor',p_actor,'base',p_base_request,'calculations',p_calculations,'review',p_review_sha256,'reason',p_reason));
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1 where idempotency_key=p_idempotency_key;
  if found then
    if v_saved.input_sha256 is distinct from v_input or v_saved.actor_user_id is distinct from p_actor then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_REPLAY_CONFLICT' using errcode='22023'; end if;
    v_result:=private.weekly_source_entitlement_publish_immediate_v1(v_saved.accepted_request_json);
    return jsonb_build_object('witness_id',v_saved.id,'source_publication',v_result,'financial_comparison_resolved',false);
  end if;
  -- A new decision must see a fresh post-I1 statement snapshot. Historical
  -- exact replay above does not acquire today's economics or this new gate.
  if current_setting('transaction_isolation') is distinct from 'read committed' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_READ_COMMITTED_REQUIRED' using errcode='25001'; end if;
  v_roots:=array[(p_base_request#>>'{member_root_ids,0}')::uuid,(p_base_request#>>'{member_root_ids,1}')::uuid];
  v_lock:=private.weekly_source_lock_and_resolve_families_v1((p_base_request->>'candidate_id')::uuid,v_roots,
    'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',gen_random_uuid(),'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if v_lock->>'ok' is distinct from 'true' or v_lock->>'gate' is distinct from 'GRANTED' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_UNAVAILABLE' using errcode='55000'; end if;
  -- Re-enter the exact replay after I-1. This is a bounded single reread,
  -- never a replay using today's rates or a second independent decision.
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1 where idempotency_key=p_idempotency_key;
  if found then
    if v_saved.input_sha256 is distinct from v_input or v_saved.actor_user_id is distinct from p_actor then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_REPLAY_CONFLICT' using errcode='22023'; end if;
    v_result:=private.weekly_source_entitlement_publish_immediate_v1(v_saved.accepted_request_json);
    return jsonb_build_object('witness_id',v_saved.id,'source_publication',v_result,'financial_comparison_resolved',false);
  end if;
  -- Exactly ONE fresh STABLE context SELECT after I1 and its replay reread.
  -- Pricing descendants and full stage helper inputs use this statement's
  -- snapshot; the nested lifecycle signature(false) is not globally STABLE.
  -- Existing I1/currentwork/publisher guards retain work currentness. This is
  -- accepted-at-this-read pricing, never latest-at-release pricing.
  select private.weekly_source_destination_reprice_context_v1(p_actor,p_base_request) into v_context;
  v_quote:=private.weekly_source_destination_reprice_quote_v1(v_context,p_calculations);
  if v_quote->>'review_sha256' is distinct from p_review_sha256 then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_STALE' using errcode='40001'; end if;
  v_id:=gen_random_uuid(); v_time:=transaction_timestamp(); v_request:=v_quote->'request';
  v_request:=jsonb_set(v_request,'{financial_request,contract_choices,1,destination_reprice}',jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1','witness_id',v_id,'review_sha256',p_review_sha256));
  -- Whole own-B acknowledgement is accepted at the same exact shown digest;
  -- the recorder persists the existing actor/time columns and replay checks.
  v_request:=jsonb_set(v_request,'{control,whole_root_office_review}',jsonb_build_object(
    'reviewed',true,'reviewed_by_user_id',p_actor,'reviewed_at_utc',v_time,'decision_id',v_request->>'decision_id'));
  insert into private.weekly_source_destination_reprice_witness_v1(id,decision_bundle_id,bundle_revision,
    idempotency_key,input_sha256,actor_user_id,reason,context_json,economic_snapshots_json,review_sha256,
    accepted_request_json,accepted_request_sha256,accepted_control_sha256,accepted_at_utc)
  values(v_id,(v_request->>'decision_bundle_id')::uuid,(v_request->>'bundle_revision')::bigint,p_idempotency_key,
    v_input,p_actor,p_reason,v_context,v_quote->'components',decode(p_review_sha256,'hex'),v_request,
    private.weekly_source_publication_request_digest_v1(private.weekly_source_publication_request_canonical_v1(v_request,'IMMEDIATE',null)),
    sha256(convert_to((v_request->'control')::text,'UTF8')),v_time);
  v_record:=private.weekly_source_entitlement_proposal_record_v1(v_request,(v_context->>'agency_id')::uuid,
    (v_request#>>'{financial_request,contract_choices,0,contract_id}')::uuid,
    (v_request#>>'{financial_request,contract_choices,0,week_ending_date}')::date,p_actor);
  if v_record->>'ok' is distinct from 'true' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_PROPOSAL_NOT_RECORDED' using errcode='55000'; end if;
  v_result:=private.weekly_source_entitlement_publish_immediate_v1(v_request);
  return jsonb_build_object('witness_id',v_id,'review_sha256',p_review_sha256,
    'source_publication',v_result,'financial_comparison_resolved',false);
end;
$function$;

-- The chosen detail captures the new pay rates over exactly the old clocks
-- and bucket facts. Full immutable calculation/policy lives in the single
-- Source witness; the detail stores its exact ID/digest, not a copied import.
create or replace function private.weekly_source_destination_reprice_detail_v1(
  p_bundle uuid,p_revision bigint,p_component jsonb,p_origin integer
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare v_saved private.weekly_source_destination_reprice_witness_v1%rowtype; v_item jsonb;
begin
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1
    where decision_bundle_id=p_bundle and bundle_revision=p_revision;
  if not found then return null; end if;
  select value into v_item from jsonb_array_elements(v_saved.economic_snapshots_json)
    where value->>'component_id'=p_component->>'component_id';
  if v_item is null then return null; end if;
  if p_origin<>1 or not exists(select 1 from public.weekly_source_entitlement_head_components c
      where c.head_id=(v_saved.accepted_request_json#>>'{head_ids,1}')::uuid
        and c.component_id=(p_component->>'component_id')::uuid)
     or private.weekly_source_publication_component_content_v1(p_component) is distinct from v_item->'after_content' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_DETAIL_NOT_EXACT' using errcode='23514'; end if;
  perform private.weekly_source_destination_reprice_verify_v1(
    private.weekly_source_publication_request_canonical_v1(v_saved.accepted_request_json,'IMMEDIATE',null),
    v_saved.accepted_request_json->'control');
  return jsonb_set(v_item->'detail','{destination_reprice}',(v_item#>'{detail,destination_reprice}')||
    jsonb_build_object('witness_id',v_saved.id,'review_sha256',encode(v_saved.review_sha256,'hex')));
end;
$function$;

-- Called inside the winning publisher after its existing immutable receipt
-- replay and before its first write. Deferred mode verifies immutable accepted
-- IMMEDIATE economics only; the actual publisher retains live work guards.
create or replace function private.weekly_source_destination_reprice_verify_v1(
  p_canonical jsonb,p_control jsonb
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_saved private.weekly_source_destination_reprice_witness_v1%rowtype;
  v_request jsonb; v_calculations jsonb; v_quote jsonb; v_expected jsonb;
begin
  if p_canonical#>'{financial_request,contract_choices,1,destination_reprice}' is null then return null; end if;
  select * into strict v_saved from private.weekly_source_destination_reprice_witness_v1
    where id=(p_canonical#>>'{financial_request,contract_choices,1,destination_reprice,witness_id}')::uuid for share;
  v_request:=jsonb_set(jsonb_set(p_canonical,'{publication_mode}','"IMMEDIATE"'::jsonb),'{pending_bundle_id}','null'::jsonb);
  if v_saved.review_sha256 is distinct from decode(p_canonical#>>'{financial_request,contract_choices,1,destination_reprice,review_sha256}','hex')
     or v_saved.accepted_request_sha256 is distinct from private.weekly_source_publication_request_digest_v1(v_request)
     or v_saved.accepted_control_sha256 is distinct from sha256(convert_to(p_control::text,'UTF8'))
     or v_saved.accepted_request_json->'control' is distinct from p_control
     or not exists(select 1 from public.weekly_source_entitlement_decision_bundles b
       where b.decision_bundle_id=v_saved.decision_bundle_id and b.bundle_revision=v_saved.bundle_revision
         and b.decided_by_user_id=v_saved.actor_user_id and b.whole_root_review_required
         and b.whole_root_reviewed_by_user_id=v_saved.actor_user_id
         and b.whole_root_reviewed_at_utc=v_saved.accepted_at_utc) then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_WITNESS_NOT_EXACT' using errcode='23514'; end if;
  -- Re-derive the accepted review and output from immutable certificate
  -- inputs. There is deliberately NO fresh mutable context/rate/settings read.
  perform private.weekly_source_destination_stage_snapshot_check_v1(v_saved.context_json->'stage_snapshot');
  select jsonb_agg(jsonb_build_object('component_id',value->>'component_id',
      'economic_snapshot',value->'economic_snapshot','price_comparison',value->'price_comparison')
      order by value->>'component_id') into v_calculations
    from jsonb_array_elements(v_saved.economic_snapshots_json);
  v_quote:=private.weekly_source_destination_reprice_quote_v1(v_saved.context_json,v_calculations);
  v_expected:=jsonb_set(v_quote->'request','{financial_request,contract_choices,1,destination_reprice}',
    jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1','witness_id',v_saved.id,
      'review_sha256',encode(v_saved.review_sha256,'hex')));
  v_expected:=jsonb_set(v_expected,'{control,whole_root_office_review}',jsonb_build_object(
    -- Preserve the actual accepted JSON time representation across session
    -- timezone changes; its typed instant is checked against server time below.
    'reviewed',true,'reviewed_by_user_id',v_saved.actor_user_id,
    'reviewed_at_utc',v_saved.accepted_request_json#>'{control,whole_root_office_review,reviewed_at_utc}',
    'decision_id',v_expected->>'decision_id'));
  if v_saved.context_json->>'actor_user_id' is distinct from v_saved.actor_user_id::text
     or (v_saved.accepted_request_json#>>'{control,whole_root_office_review,reviewed_at_utc}')::timestamptz
       is distinct from v_saved.accepted_at_utc
     or v_saved.context_json#>>'{stage_snapshot,destination_pay_channel}' is distinct from
       v_saved.context_json->>'destination_pay_channel'
     or v_saved.context_json#>>'{stage_snapshot,root_timesheet_id}' is distinct from
       v_saved.accepted_request_json#>>'{member_root_ids,1}'
     or v_saved.context_json#>>'{stage_snapshot,contract_id}' is distinct from
       v_saved.accepted_request_json#>>'{financial_request,contract_choices,1,contract_id}'
     or v_saved.context_json#>>'{stage_snapshot,candidate_id}' is distinct from
       v_saved.accepted_request_json->>'candidate_id'
     or v_quote->>'review_sha256' is distinct from encode(v_saved.review_sha256,'hex')
     or v_quote->'components' is distinct from v_saved.economic_snapshots_json
     or v_expected is distinct from v_saved.accepted_request_json
     or v_saved.decision_bundle_id is distinct from (v_expected->>'decision_bundle_id')::uuid
     or v_saved.bundle_revision is distinct from (v_expected->>'bundle_revision')::bigint
     or v_saved.accepted_request_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
       private.weekly_source_publication_request_canonical_v1(v_expected,'IMMEDIATE',null))
     or v_saved.accepted_control_sha256 is distinct from sha256(convert_to((v_expected->'control')::text,'UTF8')) then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CERTIFICATE_CORRUPT' using errcode='23514'; end if;
  return jsonb_build_object('witness_id',v_saved.id,'review_sha256',encode(v_saved.review_sha256,'hex'),
    'components',v_saved.economic_snapshots_json,'destination_pay_channel',v_saved.context_json->>'destination_pay_channel');
end;
$function$;

-- Exact point lookup for1550; ordinary/first-authorisation paths return NULL.
-- Do not discover a latest rate owner or search historical heads/effects.
create or replace function private.weekly_source_destination_reprice_stage_snapshot_v1(
  p_root uuid,p_head uuid
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_head public.weekly_source_entitlement_heads%rowtype;
  v_saved private.weekly_source_destination_reprice_witness_v1%rowtype; v_stage jsonb;
begin
  if p_head is null then return null; end if;
  select * into v_head from public.weekly_source_entitlement_heads where id=p_head;
  if not found then return null; end if; -- the unchanged1550 HEAD guard rejects it
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1
    where decision_bundle_id=v_head.decision_bundle_id and bundle_revision=v_head.bundle_revision;
  if not found then return null; end if;
  if p_root::text=v_saved.accepted_request_json#>>'{member_root_ids,0}'
     and p_head::text=v_saved.accepted_request_json#>>'{head_ids,0}' then return null; end if;
  v_stage:=v_saved.context_json->'stage_snapshot';
  if p_root::text is distinct from v_saved.accepted_request_json#>>'{member_root_ids,1}'
     or p_head::text is distinct from v_saved.accepted_request_json#>>'{head_ids,1}'
     or v_head.root_timesheet_id is distinct from p_root
     or v_head.state is distinct from 'COMMITTED_CURRENT'
     or v_stage->>'root_timesheet_id' is distinct from p_root::text
     or v_stage->>'root_booking_id' is distinct from v_head.root_family_booking_id
     or (v_stage->>'root_timesheet_version')::integer is distinct from v_head.root_timesheet_version
     or (v_stage->>'candidate_id')::uuid is distinct from v_head.candidate_id
     or (v_stage->>'contract_id')::uuid is distinct from v_head.contract_id then
    raise exception 'WEEKLY_SOURCE_DESTINATION_STAGE_LINEAGE_NOT_EXACT' using errcode='23514'; end if;
  perform private.weekly_source_destination_reprice_verify_v1(
    private.weekly_source_publication_request_canonical_v1(v_saved.accepted_request_json,'IMMEDIATE',null),
    v_saved.accepted_request_json->'control');
  return v_stage;
end;
$function$;

alter function private.weekly_source_destination_reprice_context_v1(uuid,jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_destination_stage_snapshot_check_v1(jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_destination_reprice_stage_snapshot_v1(uuid,uuid) OWNER TO CURRENT_USER;
alter function private.weekly_source_destination_reprice_quote_v1(jsonb,jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_destination_reprice_verify_v1(jsonb,jsonb) OWNER TO CURRENT_USER;
alter function private.weekly_source_destination_reprice_detail_v1(uuid,bigint,jsonb,integer) OWNER TO CURRENT_USER;
alter function public.weekly_source_destination_reprice_preview_v1(uuid,jsonb,jsonb) OWNER TO CURRENT_USER;
alter function public.weekly_source_destination_reprice_accept_v1(uuid,jsonb,jsonb,text,text,text) OWNER TO CURRENT_USER;
revoke all on function private.weekly_source_destination_reprice_context_v1(uuid,jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_destination_stage_snapshot_check_v1(jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_destination_reprice_stage_snapshot_v1(uuid,uuid) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_destination_reprice_quote_v1(jsonb,jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_destination_reprice_verify_v1(jsonb,jsonb) from public,anon,authenticated,service_role;
revoke all on function private.weekly_source_destination_reprice_detail_v1(uuid,bigint,jsonb,integer) from public,anon,authenticated,service_role;
revoke all on function public.weekly_source_destination_reprice_preview_v1(uuid,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.weekly_source_destination_reprice_accept_v1(uuid,jsonb,jsonb,text,text,text) from public,anon,authenticated;
grant execute on function public.weekly_source_destination_reprice_preview_v1(uuid,jsonb,jsonb) to service_role;
grant execute on function public.weekly_source_destination_reprice_accept_v1(uuid,jsonb,jsonb,text,text,text) to service_role;
notify pgrst,'reload schema';


-- E-only joint Source/Banking precommit helper candidate. No installation.
-- Source owner has already rederived the full planned request with its real quote.
-- Uses 1157 selected quote only; no alternate financial calculator or history sum.



create or replace function private.bpay_next_source_comparison_case_quote_snapshot_v2(
  p_context jsonb,p_selection jsonb,p_paid numeric,p_entitlement numeric)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,private,public
as $function$
declare cb jsonb:=p_context->'case_basis';ch jsonb;choice jsonb;cc jsonb:=p_selection->'case_choice';
  maps jsonb:='[]';q jsonb;wq jsonb;oq jsonb;s numeric;w numeric;j numeric:=0;o numeric;p numeric;counted integer;
  mode text;native_j numeric:=0;
begin
  if cb is null or cb='null'::jsonb then
    if cc is distinct from 'null'::jsonb or p_selection->'case_hold_choices' is distinct from '[]'::jsonb then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_SELECTION_SCOPE_INVALID' using errcode='22023';end if;
    return jsonb_build_object('case_resolution',null,'case_hold_mappings',maps);
  end if;
  if jsonb_typeof(cc) is distinct from 'object' or jsonb_typeof(p_selection->'case_hold_choices') is distinct from 'array' then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_SELECTION_REVIEW_REQUIRED' using errcode='55000';end if;
  perform private.weekly_source_publication_require_keys_v1(cc,array[
    'selected_mode','source_outstanding_ex_vat','manual_amount_ex_vat','manual_written_off_amount_ex_vat'],'financial.case_choice');
  mode:=cc->>'selected_mode';s:=(cc->>'source_outstanding_ex_vat')::numeric;
  if mode not in ('SUGGESTED_EQUIVALENT_BASIS','MANUAL_AMOUNT') or mode is null or s is null
    or s<0 or s<>round(s,2) or s>=10000000000000000
    or (mode='SUGGESTED_EQUIVALENT_BASIS' and
      (cc->'manual_amount_ex_vat' is distinct from 'null'::jsonb or cc->'manual_written_off_amount_ex_vat' is distinct from 'null'::jsonb))
    or (mode='MANUAL_AMOUNT' and ((cc->>'manual_amount_ex_vat')::numeric is null
      or (cc->>'manual_written_off_amount_ex_vat')::numeric is null
      or (cc->>'manual_amount_ex_vat')::numeric<0 or (cc->>'manual_written_off_amount_ex_vat')::numeric<0
      or (cc->>'manual_amount_ex_vat')::numeric<>round((cc->>'manual_amount_ex_vat')::numeric,2)
      or (cc->>'manual_written_off_amount_ex_vat')::numeric<>round((cc->>'manual_written_off_amount_ex_vat')::numeric,2)
      or ((cb->>'W')::numeric=0 and (cc->>'manual_written_off_amount_ex_vat')::numeric<>0))) then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_ACCEPTED_CHOICE_REQUIRED' using errcode='55000';end if;
  wq:=private.pay_finance_selected_quote_v1(mode::public.pay_finance_component_resolution_mode_enum,
    (cb->>'W')::numeric,cb->>'case_source_channel',p_context#>>'{policy,target_pay_channel}',null,null,
    (cc->>'manual_written_off_amount_ex_vat')::numeric,(p_context#>>'{policy,erni_pct}')::numeric,
    (p_context#>>'{policy,vat_rate_pct}')::numeric,(p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
  w:=(wq->>'ex')::numeric;
  for ch in select value from jsonb_array_elements(p_context->'active_case_holds') order by value->>'case_hold_id' loop
    select count(*)::integer,jsonb_agg(value)->0 into counted,choice from jsonb_array_elements(p_selection->'case_hold_choices')
      where value->>'case_hold_id'=ch->>'case_hold_id';
    if counted<>1 then raise exception 'BPAY_NEXT_COMPARISON_CASE_HOLD_MAPPING_REVIEW_REQUIRED' using errcode='55000';end if;
    perform private.weekly_source_publication_require_keys_v1(choice,
      array['case_hold_id','selected_mode','manual_amount_ex_vat'],'financial.case_hold_choice');
    if choice->>'selected_mode' not in ('SUGGESTED_EQUIVALENT_BASIS','MANUAL_AMOUNT') or choice->>'selected_mode' is null
      or (choice->>'selected_mode'='SUGGESTED_EQUIVALENT_BASIS' and choice->'manual_amount_ex_vat' is distinct from 'null'::jsonb)
      or (choice->>'selected_mode'='MANUAL_AMOUNT' and ((choice->>'manual_amount_ex_vat')::numeric is null
        or (choice->>'manual_amount_ex_vat')::numeric<0
        or (choice->>'manual_amount_ex_vat')::numeric<>round((choice->>'manual_amount_ex_vat')::numeric,2))) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_HOLD_MAPPING_REVIEW_REQUIRED' using errcode='55000';end if;
    q:=private.pay_finance_selected_quote_v1((choice->>'selected_mode')::public.pay_finance_component_resolution_mode_enum,
      (ch->>'native_target_ex_vat')::numeric,ch->>'native_target_channel',p_context#>>'{policy,target_pay_channel}',null,null,
      (choice->>'manual_amount_ex_vat')::numeric,(p_context#>>'{policy,erni_pct}')::numeric,
      (p_context#>>'{policy,vat_rate_pct}')::numeric,(p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
    j:=j+(q->>'ex')::numeric;native_j:=native_j+(ch->>'source_reserved_ex_vat')::numeric;
    maps:=maps||jsonb_build_array(jsonb_build_object('case_hold_id',ch->>'case_hold_id','comparable_recovery_ex_vat',(q->>'ex')::numeric));
  end loop;
  if jsonb_array_length(p_selection->'case_hold_choices')<>jsonb_array_length(maps) or native_j<>(cb->>'J')::numeric then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_HOLD_MAPPING_REVIEW_REQUIRED' using errcode='55000';end if;
  o:=greatest(p_paid-p_entitlement-w,j,0);
  oq:=private.pay_finance_selected_quote_v1(mode::public.pay_finance_component_resolution_mode_enum,s,
    cb->>'case_source_channel',p_context#>>'{policy,target_pay_channel}',null,null,(cc->>'manual_amount_ex_vat')::numeric,
    (p_context#>>'{policy,erni_pct}')::numeric,(p_context#>>'{policy,vat_rate_pct}')::numeric,
    (p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
  if (oq->>'ex')::numeric is distinct from o or w is null or w<0 or j<0 or o is null
    or abs(o)>=10000000000000000 or abs(w)>=10000000000000000 or abs(j)>=10000000000000000 then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_ROUNDED_QUOTE_REVIEW_REQUIRED' using errcode='55000';end if;
  p:=(cb->>'K')::numeric+(cb->>'W')::numeric+greatest(s,(cb->>'J')::numeric);
  return jsonb_build_object('case_hold_mappings',maps,'case_resolution',jsonb_build_object(
    'case_source_channel',cb->>'case_source_channel','source_outstanding_ex_vat',s,'source_principal_ex_vat',p,
    'target_outstanding_ex_vat',o,'target_written_off_ex_vat',w,'target_active_capacity_ex_vat',j,'selected_mode',mode,
    'target_pay_channel',p_context#>>'{policy,target_pay_channel}','comparison_policy_id',p_context#>>'{policy,comparison_policy_id}',
    'policy_window_id',p_context#>>'{policy,policy_window_id}','effective_pay_date',p_context#>>'{policy,effective_pay_date}',
    'umbrella_vat_chargeable',p_context#>'{policy,umbrella_vat_chargeable}','selected_quote',oq,'written_off_quote',wq,
    'choice',cc,'rounding_proof',jsonb_build_object('source',s,'quoted_target',oq->'ex','required_target',o,'exact',true)));
end $function$;

create or replace function private.bpay_next_source_comparison_quote_snapshot_v2(p_context jsonb,p_selection jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path=pg_catalog,private,public
as $function$
declare
  v_mode text:=p_selection->>'selected_mode'; v_q jsonb; v_qs jsonb:='[]'; v_h jsonb; v_choice jsonb;
  v_paid numeric:=0; v_held numeric:=0; v_amount numeric; v_channel text; v_units numeric;
  v_current jsonb:=p_context->'current_comparison'; v_reuse boolean:=false; v_count integer;
begin
  perform private.weekly_source_publication_require_keys_v1(p_selection,array[
    'component_id','selected_mode','effective_pay_date','umbrella_vat_chargeable',
    'manual_paid_amount_ex_vat','manual_replacement_rate','paid_partition','hold_choices','case_choice','case_hold_choices','reason'],'financial.selection');
  if p_selection->>'component_id' is distinct from p_context->>'component_id'
    or p_selection->>'effective_pay_date' is distinct from p_context#>>'{policy,effective_pay_date}'
    or p_selection->'umbrella_vat_chargeable' is distinct from p_context#>'{policy,umbrella_vat_chargeable}'
    or char_length(btrim(coalesce(p_selection->>'reason',''))) not between 1 and 1024 then
    raise exception 'BPAY_NEXT_COMPARISON_SELECTION_SCOPE_INVALID' using errcode='22023';
  end if;
  if (v_mode<>'MANUAL_AMOUNT' and p_selection->'manual_paid_amount_ex_vat' is distinct from 'null'::jsonb)
    or (v_mode<>'MANUAL_REPLACEMENT_RATE' and
      (p_selection->'manual_replacement_rate' is distinct from 'null'::jsonb or p_selection->'paid_partition' is distinct from 'null'::jsonb))
    or (v_mode in ('REUSE_CURRENT','NATIVE_IDENTITY','SUGGESTED_EQUIVALENT_BASIS') and p_selection->'hold_choices' is distinct from '[]'::jsonb)
    or (v_mode='MANUAL_REPLACEMENT_RATE' and
      ((p_selection->>'manual_replacement_rate')::numeric is null or (p_selection->>'manual_replacement_rate')::numeric<=0
       or (p_selection->>'manual_replacement_rate')::numeric>=10000000000000000))
    or (v_mode='MANUAL_AMOUNT' and
      ((p_selection->>'manual_paid_amount_ex_vat')::numeric is null
       or (p_selection->>'manual_paid_amount_ex_vat')::numeric<>round((p_selection->>'manual_paid_amount_ex_vat')::numeric,2))) then
    raise exception 'BPAY_NEXT_COMPARISON_SELECTION_INPUT_INVALID' using errcode='22023';
  end if;
  if v_mode='REUSE_CURRENT' then
    if v_current is null or v_current='null'::jsonb
      or (v_current->>'qualification_state' is distinct from 'READY' and (
        v_current->>'qualification_state' is distinct from 'REVIEW'
        or v_current->>'review_issue_code' is distinct from 'CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED'
        or v_current->>'credit_qualification_state' is distinct from 'READY'
        or (v_current->>'comparable_paid_ex_vat')::numeric is null
        or (v_current->>'comparable_held_ex_vat')::numeric is null
        or (v_current->>'comparable_held_ex_vat')::numeric<0))
      or v_current->'basis' is distinct from p_context->'policy' then
      raise exception 'BPAY_NEXT_COMPARISON_CURRENT_BASIS_REVIEW_REQUIRED' using errcode='55000';
    end if;
    v_reuse:=true; v_mode:=v_current->>'selected_mode';
    if v_mode='MANUAL_REPLACEMENT_RATE' and v_current->>'quantity_partition_qualified' is distinct from 'true' then
      raise exception 'BPAY_NEXT_COMPARISON_PARTITION_REVIEW_REQUIRED' using errcode='55000';
    end if;
    v_paid:=(v_current->>'comparable_paid_ex_vat')::numeric;
    v_held:=(v_current->>'comparable_held_ex_vat')::numeric;
    for v_h in select value from jsonb_array_elements(p_context->'active_holds') order by value->>'hold_id' loop
      if v_h->'existing_comparable_reserved_ex_vat' is null or v_h->'existing_comparable_reserved_ex_vat'='null'::jsonb then
        raise exception 'BPAY_NEXT_COMPARISON_HELD_MAPPING_REVIEW_REQUIRED' using errcode='55000';
      end if;
      v_qs:=v_qs||jsonb_build_array(jsonb_build_object('hold_id',v_h->>'hold_id',
        'comparable_reserved_ex_vat',(v_h->>'existing_comparable_reserved_ex_vat')::numeric));
    end loop;
    if coalesce((select sum((value->>'comparable_reserved_ex_vat')::numeric) from jsonb_array_elements(v_qs)),0)<>v_held then
      raise exception 'BPAY_NEXT_COMPARISON_HELD_MAPPING_REVIEW_REQUIRED' using errcode='55000';
    end if;
  else
    if v_mode not in ('NATIVE_IDENTITY','SUGGESTED_EQUIVALENT_BASIS','MANUAL_REPLACEMENT_RATE','MANUAL_AMOUNT') or v_mode is null then
      raise exception 'BPAY_NEXT_COMPARISON_ACCEPTED_CHOICE_REQUIRED' using errcode='55000';
    end if;
    if v_mode='MANUAL_AMOUNT' and p_context->>'component_semantics' is distinct from 'AMOUNT_LED' then
      raise exception 'BPAY_NEXT_COMPARISON_MANUAL_AMOUNT_RATE_BEARING_FORBIDDEN' using errcode='22023';
    end if;
    if v_mode='NATIVE_IDENTITY' and
      (case when p_context#>>'{policy,target_pay_channel}'='PAYE'
        then (p_context->>'native_realised_umbrella')::numeric<>0 or (p_context->>'native_held_umbrella')::numeric<>0
        else (p_context->>'native_realised_paye')::numeric<>0 or (p_context->>'native_held_paye')::numeric<>0 end) then
      raise exception 'BPAY_NEXT_COMPARISON_IDENTITY_CHANNEL_INVALID' using errcode='23514';
    end if;
    if v_mode='MANUAL_REPLACEMENT_RATE' and (p_context->>'component_semantics' is distinct from 'RATE_BEARING'
      or p_selection->'paid_partition' is distinct from p_context->'paid_partition'
      or (p_context->'paid_partition'='null'::jsonb and
        ((p_context->>'native_realised_paye')::numeric<>0 or (p_context->>'native_realised_umbrella')::numeric<>0))) then
      raise exception 'BPAY_NEXT_COMPARISON_PARTITION_REVIEW_REQUIRED' using errcode='55000';
    end if;
    if v_mode='MANUAL_AMOUNT' then
      v_q:=private.pay_finance_selected_quote_v1('MANUAL_AMOUNT',(p_context->>'native_realised_paye')::numeric+
        (p_context->>'native_realised_umbrella')::numeric,p_context->>'seed_source_channel',
        p_context#>>'{policy,target_pay_channel}',null,null,(p_selection->>'manual_paid_amount_ex_vat')::numeric,
        (p_context#>>'{policy,erni_pct}')::numeric,(p_context#>>'{policy,vat_rate_pct}')::numeric,
        (p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
      v_paid:=(v_q->>'ex')::numeric;
    elsif v_mode='MANUAL_REPLACEMENT_RATE' then
      v_units:=coalesce((p_context#>>'{paid_partition,units}')::numeric,0);
      v_q:=private.pay_finance_selected_quote_v1('MANUAL_REPLACEMENT_RATE',
        (p_context->>'native_realised_paye')::numeric+(p_context->>'native_realised_umbrella')::numeric,
        p_context->>'seed_source_channel',p_context#>>'{policy,target_pay_channel}',v_units,
        (p_selection->>'manual_replacement_rate')::numeric,null,
        (p_context#>>'{policy,erni_pct}')::numeric,(p_context#>>'{policy,vat_rate_pct}')::numeric,
        (p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
      v_paid:=(v_q->>'ex')::numeric;
    else
      foreach v_channel in array array['PAYE','UMBRELLA'] loop
        v_amount:=(p_context->>case when v_channel='PAYE' then 'native_realised_paye' else 'native_realised_umbrella' end)::numeric;
        v_q:=private.pay_finance_selected_quote_v1('SUGGESTED_EQUIVALENT_BASIS',v_amount,v_channel,
          p_context#>>'{policy,target_pay_channel}',null,null,null,(p_context#>>'{policy,erni_pct}')::numeric,
          (p_context#>>'{policy,vat_rate_pct}')::numeric,(p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
        v_paid:=v_paid+(v_q->>'ex')::numeric;
      end loop;
    end if;
    if jsonb_typeof(p_selection->'hold_choices') is distinct from 'array' then
      raise exception 'BPAY_NEXT_COMPARISON_HELD_SELECTION_INVALID' using errcode='22023';
    end if;
    for v_h in select value from jsonb_array_elements(p_context->'active_holds') order by value->>'hold_id' loop
      if v_mode in ('MANUAL_AMOUNT','MANUAL_REPLACEMENT_RATE') then
        select count(*)::integer,jsonb_agg(value)->0 into v_count,v_choice
          from jsonb_array_elements(p_selection->'hold_choices') where value->>'hold_id'=v_h->>'hold_id';
        if v_count<>1 then raise exception 'BPAY_NEXT_COMPARISON_HELD_MAPPING_REVIEW_REQUIRED' using errcode='55000'; end if;
        perform private.weekly_source_publication_require_keys_v1(v_choice,
          array['hold_id','manual_amount_ex_vat','partition'],'financial.hold_choice');
        if v_mode='MANUAL_AMOUNT' and ((v_choice->>'manual_amount_ex_vat')::numeric is null
          or (v_choice->>'manual_amount_ex_vat')::numeric<0
          or (v_choice->>'manual_amount_ex_vat')::numeric<>round((v_choice->>'manual_amount_ex_vat')::numeric,2)) then
          raise exception 'BPAY_NEXT_COMPARISON_HELD_SELECTION_INVALID' using errcode='22023';
        end if;
        if v_mode='MANUAL_REPLACEMENT_RATE' and (v_h->'partition'='null'::jsonb or v_choice->'partition' is distinct from v_h->'partition') then
          raise exception 'BPAY_NEXT_COMPARISON_PARTITION_REVIEW_REQUIRED' using errcode='55000';
        end if;
      end if;
      v_q:=private.pay_finance_selected_quote_v1(
        case when v_mode='NATIVE_IDENTITY' then 'SUGGESTED_EQUIVALENT_BASIS' else v_mode end::public.pay_finance_component_resolution_mode_enum,
        (v_h->>'native_reserved_ex_vat')::numeric,v_h->>'native_source_channel',p_context#>>'{policy,target_pay_channel}',
        (v_h#>>'{partition,units}')::numeric,(p_selection->>'manual_replacement_rate')::numeric,
        (v_choice->>'manual_amount_ex_vat')::numeric,(p_context#>>'{policy,erni_pct}')::numeric,
        (p_context#>>'{policy,vat_rate_pct}')::numeric,(p_context#>>'{policy,umbrella_vat_chargeable}')::boolean);
      if (v_q->>'ex')::numeric<0 then raise exception 'BPAY_NEXT_COMPARISON_HELD_SELECTION_INVALID' using errcode='22023'; end if;
      v_held:=v_held+(v_q->>'ex')::numeric;
      v_qs:=v_qs||jsonb_build_array(jsonb_build_object('hold_id',v_h->>'hold_id',
        'comparable_reserved_ex_vat',(v_q->>'ex')::numeric));
    end loop;
    if v_mode in ('MANUAL_AMOUNT','MANUAL_REPLACEMENT_RATE') and
      jsonb_array_length(p_selection->'hold_choices')<>jsonb_array_length(v_qs) then
      raise exception 'BPAY_NEXT_COMPARISON_HELD_SELECTION_INVALID' using errcode='22023';
    end if;
  end if;
  if v_paid is null or v_paid<>round(v_paid,2) or abs(v_paid)>=10000000000000000
    or v_held is null or v_held<>round(v_held,2) or v_held<0 or v_held>=10000000000000000 then
    raise exception 'BPAY_NEXT_COMPARISON_QUOTE_INVALID' using errcode='22023';
  end if;
  return jsonb_build_object('selected_mode',v_mode,'selection_method',case when v_reuse then 'REUSE_CURRENT' else 'ACCEPTED_CHOICE' end,
    'quantity_partition_qualified',v_mode='MANUAL_REPLACEMENT_RATE',
    'comparable_paid_ex_vat',v_paid,'comparable_held_ex_vat',v_held,'hold_mappings',v_qs);
end
$function$;

create or replace function private.bpay_next_source_comparison_validate_plan_snapshot_v2(
  p_planned_request jsonb,p_financial_context jsonb,p_financial_plan jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path=pg_catalog,private,public
as $function$
declare v_c jsonb; v_p jsonb; v_component jsonb; v_quote jsonb;v_case_quote jsonb; v_n numeric; v_count integer; v_hash text;
  v_expected text[];v_actual text[];v_moved text[];v_own text[];v_scope jsonb;v_key text;v_hp numeric;v_hu numeric;
begin
  if p_financial_context->>'schema_version' is distinct from 'BPAY_NEXT_SOURCE_FINANCIAL_CONTEXT_V3'
    or p_financial_plan->>'schema_version' is distinct from 'BPAY_NEXT_SOURCE_FINANCIAL_PLAN_V3'
    or p_financial_context->>'planned_request_sha256' is distinct from
      encode(private.weekly_source_sha256_jsonb_v1('BPAY_NEXT_SOURCE_PLANNED_REQUEST_V2',p_planned_request),'hex')
    or p_financial_plan->>'planned_request_sha256' is distinct from p_financial_context->>'planned_request_sha256'
    or p_financial_plan->>'candidate_id' is distinct from p_planned_request->>'candidate_id'
    or jsonb_typeof(p_financial_context->'components') is distinct from 'array'
    or jsonb_typeof(p_financial_plan->'components') is distinct from 'array'
    or jsonb_array_length(p_financial_context->'components')<>jsonb_array_length(p_financial_plan->'components') then
    raise exception 'BPAY_NEXT_COMPARISON_PLAN_SNAPSHOT_INVALID' using errcode='23514';
  end if;
  -- Moved A identity remains Source's existing meaning. Own B is not a move.
  select array_agg(value#>>'{}' order by value#>>'{}') into v_moved
    from jsonb_array_elements(p_planned_request#>'{control,moved_component_ids}');
  select array_agg(value->>'component_id' order by value->>'component_id') into v_expected
    from jsonb_array_elements(p_planned_request#>'{financial_request,member_entitlements,1,components}');
  select array_agg(value->>'component_id' order by value->>'component_id') into v_actual
    from jsonb_array_elements(p_financial_context->'components');
  select coalesce(array_agg(item order by item),'{}'::text[]) into v_own
    from unnest(v_expected) item where not (item=any(v_moved));
  v_scope:=jsonb_build_object('schema_version','BPAY_NEXT_SOURCE_FINANCIAL_SCOPE_V3',
    'moved_component_ids',to_jsonb(v_moved),'own_b_component_ids',to_jsonb(v_own),
    'comparison_component_ids',to_jsonb(v_expected));
  if v_moved is null or v_expected is null or v_expected is distinct from v_actual
    or cardinality(v_moved)<>(select count(distinct item) from unnest(v_moved) item)
    or cardinality(v_expected)<>(select count(distinct item) from unnest(v_expected) item)
    or not (v_moved<@v_expected)
    or p_financial_context->'financial_scope' is distinct from v_scope then
    raise exception 'BPAY_NEXT_COMPARISON_WHOLE_VECTOR_INVALID' using errcode='23514';
  end if;
  for v_c in select value from jsonb_array_elements(p_financial_context->'components') order by value->>'component_id' loop
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_p
      from jsonb_array_elements(p_financial_plan->'components') where value->>'source_component_id'=v_c->>'component_id';
    if v_count<>1 then raise exception 'BPAY_NEXT_COMPARISON_PLAN_COMPONENT_INVALID' using errcode='23514'; end if;
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_component
      from jsonb_array_elements(p_planned_request#>'{financial_request,member_entitlements,1,components}')
      where value->>'component_id'=v_c->>'component_id';
    if v_count<>1 then raise exception 'BPAY_NEXT_COMPARISON_PLANNED_VECTOR_INVALID' using errcode='23514'; end if;
    foreach v_key in array array['native_realised_paye','native_realised_umbrella','native_held_paye','native_held_umbrella'] loop
      if jsonb_typeof(v_c->v_key) is distinct from 'number' or (v_c->>v_key)::numeric<>round((v_c->>v_key)::numeric,2)
        or abs((v_c->>v_key)::numeric)>=10000000000000000
        or (v_key in ('native_held_paye','native_held_umbrella') and (v_c->>v_key)::numeric<0) then
        raise exception 'BPAY_NEXT_COMPARISON_NATIVE_SNAPSHOT_INVALID' using errcode='23514';
      end if;
    end loop;
    select coalesce(sum((value->>'native_reserved_ex_vat')::numeric) filter(where value->>'native_source_channel'='PAYE'),0),
      coalesce(sum((value->>'native_reserved_ex_vat')::numeric) filter(where value->>'native_source_channel'='UMBRELLA'),0)
      into v_hp,v_hu from jsonb_array_elements(v_c->'active_holds');
    if (v_hp,v_hu) is distinct from ((v_c->>'native_held_paye')::numeric,(v_c->>'native_held_umbrella')::numeric) then
      raise exception 'BPAY_NEXT_COMPARISON_HELD_SNAPSHOT_INVALID' using errcode='23514';
    end if;
    v_n:=(v_component->>'pay_ex_vat')::numeric;
    v_quote:=private.bpay_next_source_comparison_quote_snapshot_v2(v_c,v_p#>'{plan,quote_json,selection}');
    v_case_quote:=private.bpay_next_source_comparison_case_quote_snapshot_v2(v_c,v_p#>'{plan,quote_json,selection}',
      (v_quote->>'comparable_paid_ex_vat')::numeric,v_n);
    if v_p->'context' is distinct from v_c or v_p#>'{plan,quote_json,context}' is distinct from v_c
      or v_p#>'{plan,quote_json,quote}' is distinct from v_quote
      or v_p#>>'{plan,target_pay_channel}' is distinct from v_c#>>'{policy,target_pay_channel}'
      or v_p#>'{plan,comparison_policy_id}' is distinct from v_c#>'{policy,comparison_policy_id}'
      or v_p#>'{plan,policy_window_id}' is distinct from v_c#>'{policy,policy_window_id}'
      or v_p#>'{plan,effective_pay_date}' is distinct from v_c#>'{policy,effective_pay_date}'
      or v_p#>'{plan,umbrella_vat_chargeable}' is distinct from v_c#>'{policy,umbrella_vat_chargeable}'
      or v_p#>'{plan,target_umbrella_id}' is distinct from v_c#>'{policy,target_umbrella_id}'
      or v_p#>'{plan,selected_mode}' is distinct from v_quote->'selected_mode'
      or v_p#>'{plan,quantity_partition_qualified}' is distinct from v_quote->'quantity_partition_qualified'
      or v_p#>'{plan,comparable_paid_ex_vat}' is distinct from v_quote->'comparable_paid_ex_vat'
      or v_p#>'{plan,comparable_held_ex_vat}' is distinct from v_quote->'comparable_held_ex_vat'
      or v_p#>'{plan,hold_mappings}' is distinct from v_quote->'hold_mappings'
      or v_p#>'{plan,case_resolution}' is distinct from v_case_quote->'case_resolution'
      or v_p#>'{plan,case_hold_mappings}' is distinct from v_case_quote->'case_hold_mappings'
      or (v_p#>>'{plan,approved_source_ex_vat}')::numeric is distinct from v_n
      or (v_p#>>'{plan,selected_residual_ex_vat}')::numeric is distinct from
        v_n-(v_quote->>'comparable_paid_ex_vat')::numeric-(v_quote->>'comparable_held_ex_vat')::numeric
      or (v_p#>>'{plan,paid_excess_ex_vat}')::numeric is distinct from greatest((v_quote->>'comparable_paid_ex_vat')::numeric-v_n,0)
      or v_p#>>'{plan,basis_sha256}' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
        'BPAY_NEXT_SOURCE_COMPARISON_BASIS_V2',jsonb_build_object('policy',v_c->'policy','selected_mode',v_quote->>'selected_mode',
          'selection',v_p#>'{plan,quote_json,selection}')),'hex') then
      raise exception 'BPAY_NEXT_COMPARISON_PLAN_NOT_REDERIVED' using errcode='23514';
    end if;
  end loop;
  v_hash:=encode(private.weekly_source_sha256_jsonb_v1('BPAY_NEXT_SOURCE_FINANCIAL_PLAN_V3',
    jsonb_build_object('financial_context',p_financial_context,'financial_plan',p_financial_plan)),'hex');
  return jsonb_build_object('ok',true,'financial_plan_digest',v_hash);
end
$function$;

create or replace function private.bpay_next_source_comparison_plan_v2(p_actor uuid,p_planned_request jsonb,p_selections jsonb,p_target_channel text)
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,private,public
as $function$
declare
  v_request jsonb; v_inventory jsonb;v_inventory_a jsonb;v_inventory_b jsonb;v_scope jsonb;v_entry record;
  v_moved uuid[];v_actual uuid[];v_own uuid[];v_all uuid[];v_destination uuid[];v_component jsonb;v_original jsonb;
  v_context jsonb; v_contexts jsonb:='[]'; v_plan jsonb; v_plans jsonb:='[]'; v_selection jsonb; v_quote jsonb;v_case_quote jsonb;
  v_binding private.bpay_next_source_component_binding%rowtype;
  v_version private.bpay_next_source_component_binding_version%rowtype;
  v_book private.bpay_next_position%rowtype; v_old private.bpay_next_source_comparison_receipt%rowtype;
  v_line private.bpay_next_approved_line%rowtype; v_seed_line private.bpay_next_approved_line%rowtype;
  v_seed_effect private.bpay_next_financial_effect%rowtype; v_rates jsonb; v_partition jsonb;
  v_paid_origin private.bpay_next_work_collection%rowtype;v_paid_effect_id uuid;v_paid_line_id uuid;
  v_paid_channel text;v_partition_kind text;
  v_final public.weekly_source_final_revisions%rowtype; v_cycle public.weekly_source_cycles%rowtype; v_group public.weekly_source_groups%rowtype;
  v_policy uuid; v_window private.bpay_next_valuation_policy_window%rowtype; v_winners bigint;
  v_target text; v_date date; v_vat boolean; v_real_vat boolean;v_recipient uuid; v_h record; v_holds jsonb; v_hpartition jsonb; v_last uuid;
  v_page integer; v_hp numeric; v_hu numeric; v_units numeric; v_rate_count integer; v_count integer;
  v_existing numeric; v_basis uuid; v_old_json jsonb;v_cb jsonb;v_cholds jsonb;v_ch record;v_cj numeric; v_p numeric; v_hamount numeric; v_n numeric;
  v_fc jsonb; v_fp jsonb; v_valid jsonb; v_method text; v_class text; v_hash text;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;
  v_request:=private.weekly_source_publication_request_canonical_v1(p_planned_request,'IMMEDIATE',null);
  if p_actor is null or p_planned_request#>>'{control,bundle_kind}' is distinct from 'CROSS_CONTRACT_A_B'
    or jsonb_array_length(v_request->'member_root_ids')<>2
    or jsonb_typeof(p_selections) is distinct from 'array'
    or jsonb_array_length(v_request#>'{financial_request,member_entitlements,0,components}')<>0 then
    raise exception 'BPAY_NEXT_COMPARISON_WHOLE_PAIR_REQUIRED' using errcode='22023';
  end if;
  select f.* into strict v_final from public.weekly_source_final_revisions f
    where f.id=(v_request#>>'{financial_request,source_revision,final_revision_id}')::uuid and f.state='CURRENT';
  select c.* into strict v_cycle from public.weekly_source_cycles c where c.id=v_final.source_cycle_id;
  select g.* into strict v_group from public.weekly_source_groups g where g.id=v_cycle.source_group_id;
  perform private.weekly_source_office_authority_v1(p_actor,'APPROVE_PROTECTED_PAY',v_group.id,
    (select client_id from public.contracts where id=(v_request#>>'{financial_request,contract_choices,0,contract_id}')::uuid),v_cycle.finalisation_week_ending);
  perform private.weekly_source_office_authority_v1(p_actor,'APPROVE_PROTECTED_PAY',v_group.id,
    (select client_id from public.contracts where id=(v_request#>>'{financial_request,contract_choices,1,contract_id}')::uuid),v_cycle.finalisation_week_ending);
  v_inventory_a:=private.weekly_source_effective_inventory_v1((v_request#>>'{member_root_ids,0}')::uuid);
  v_inventory_b:=private.weekly_source_effective_inventory_v1((v_request#>>'{member_root_ids,1}')::uuid);
  if v_inventory_a->>'ok' is distinct from 'true' or v_inventory_b->>'ok' is distinct from 'true'
    or jsonb_typeof(v_inventory_a->'components') is distinct from 'array'
    or jsonb_typeof(v_inventory_b->'components') is distinct from 'array' then
    raise exception 'BPAY_NEXT_COMPARISON_CURRENT_INVENTORY_REVIEW_REQUIRED' using errcode='55000';
  end if;
  select array_agg((value#>>'{}')::uuid order by value#>>'{}') into v_moved
    from jsonb_array_elements(p_planned_request#>'{control,moved_component_ids}');
  select array_agg((value->>'component_id')::uuid order by value->>'component_id') into v_actual
    from jsonb_array_elements(v_inventory_a->'components');
  select coalesce(array_agg((value->>'component_id')::uuid order by value->>'component_id'),'{}'::uuid[]) into v_own
    from jsonb_array_elements(v_inventory_b->'components');
  select array_agg(item order by item) into v_all from unnest(v_actual||v_own) item;
  select array_agg((value->>'component_id')::uuid order by value->>'component_id') into v_destination
    from jsonb_array_elements(v_request#>'{financial_request,member_entitlements,1,components}');
  if v_moved is null or v_moved is distinct from v_actual or (v_actual&&v_own)
    or cardinality(v_all)<>(select count(distinct item) from unnest(v_all) item)
    or v_all is distinct from v_destination
    or cardinality(v_all) is distinct from jsonb_array_length(p_selections)
    or (select count(distinct value->>'component_id') from jsonb_array_elements(p_selections))<>cardinality(v_all) then
    raise exception 'BPAY_NEXT_COMPARISON_WHOLE_VECTOR_INVALID' using errcode='23514';
  end if;
  v_scope:=jsonb_build_object('schema_version','BPAY_NEXT_SOURCE_FINANCIAL_SCOPE_V3',
    'moved_component_ids',to_jsonb(v_moved),'own_b_component_ids',to_jsonb(v_own),
    'comparison_component_ids',to_jsonb(v_all));
  if p_target_channel not in ('PAYE','UMBRELLA') or p_target_channel is null then
    raise exception 'BPAY_NEXT_COMPARISON_POLICY_INPUT_INVALID' using errcode='22023';
  end if;
  if p_target_channel='UMBRELLA' then
    select c.umbrella_id,u.vat_chargeable into strict v_recipient,v_real_vat
      from public.candidates c left join public.umbrellas u on u.id=c.umbrella_id
      where c.id=(v_request->>'candidate_id')::uuid;
    if v_recipient is null or v_real_vat is null then
      raise exception 'BPAY_NEXT_COMPARISON_UMBRELLA_RECIPIENT_REVIEW_REQUIRED' using errcode='55000';
    end if;
  else v_recipient:=null;v_real_vat:=false;end if;
  select current_policy_id into strict v_policy from private.bpay_next_valuation_policy_control where id=1;
  for v_entry in
    select scoped.component,scoped.member_index from (
      select value as component,0 as member_index from jsonb_array_elements(v_inventory_a->'components')
      union all
      select value as component,1 as member_index from jsonb_array_elements(v_inventory_b->'components')
    ) scoped order by scoped.component->>'component_id'
  loop
    v_original:=v_entry.component;
    v_inventory:=case when v_entry.member_index=0 then v_inventory_a else v_inventory_b end;
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_selection from jsonb_array_elements(p_selections)
      where value->>'component_id'=v_original->>'component_id';
    if v_count<>1 then raise exception 'BPAY_NEXT_COMPARISON_SELECTION_SCOPE_INVALID' using errcode='22023'; end if;
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_component
      from jsonb_array_elements(v_request#>'{financial_request,member_entitlements,1,components}')
      where value->>'component_id'=v_original->>'component_id';
    if v_count<>1 then raise exception 'BPAY_NEXT_COMPARISON_PLANNED_VECTOR_INVALID' using errcode='23514'; end if;
    select b.* into strict v_binding from private.bpay_next_source_component_binding b
      where b.candidate_id=(v_request->>'candidate_id')::uuid and b.source_component_id=(v_original->>'component_id')::uuid;
    select v.* into strict v_version from private.bpay_next_source_component_binding_version v where v.id=v_binding.current_binding_version_id;
    select p.* into strict v_book from private.bpay_next_position p
      where p.work_id=v_binding.canonical_work_id and p.component_key=v_binding.canonical_component_key;
    if v_book.source_book_state<>'READY' or v_book.source_book_revision<1 or v_version.component_state<>'PRESENT'
      or v_version.tax_treatment is null or v_version.head_id::text is distinct from v_inventory->>'head_id'
      or v_version.approval_component_key is distinct from v_binding.canonical_component_key then
      raise exception 'BPAY_NEXT_COMPARISON_CURRENT_BOOK_REVIEW_REQUIRED' using errcode='55000';
    end if;
    select a.* into strict v_line from private.bpay_next_approved_line a where a.id=v_version.approved_line_id;
    v_class:=case when v_original->>'component_kind'='WORKED_TIME' or
      (v_original->'unit_count' is not null and v_original->'unit_count'<>'null'::jsonb) then 'RATE_BEARING'
      when v_original->>'component_kind' in ('SOURCE_FIXED_EXPENSE','EXPENSE') then 'AMOUNT_LED' else 'UNQUALIFIED' end;
    if v_class='UNQUALIFIED' or v_line.tax_treatment is distinct from v_version.tax_treatment then
      raise exception 'BPAY_NEXT_COMPARISON_CLASSIFICATION_REVIEW_REQUIRED' using errcode='55000';
    end if;
    -- Source wrapper supplies this exact genuine accepted pricing-context channel.
    -- The pure planned request deliberately has no invented channel extension.
    v_target:=p_target_channel;
    v_date:=(v_selection->>'effective_pay_date')::date; v_vat:=v_real_vat;
    if (v_selection->>'umbrella_vat_chargeable')::boolean is distinct from v_real_vat then
      raise exception 'BPAY_NEXT_COMPARISON_VAT_RECIPIENT_CHANGED' using errcode='40001';
    end if;
    if v_version.tax_treatment<>'TAXABLE' and v_selection->>'selected_mode'<>'REUSE_CURRENT' then
      raise exception 'BPAY_NEXT_COMPARISON_NON_TAXABLE_POLICY_REVIEW_REQUIRED' using errcode='55000';
    end if;
    if v_target not in ('PAYE','UMBRELLA') or v_target is null or not isfinite(v_date)
      or v_date is null or v_vat is null or (v_target='PAYE' and v_vat) then
      raise exception 'BPAY_NEXT_COMPARISON_POLICY_INPUT_INVALID' using errcode='22023'; end if;
    select w.* into v_window from private.bpay_next_valuation_policy_window w where w.policy_id=v_policy
      and v_date>=w.date_from and v_date<=coalesce(w.date_to,'infinity'::date)
      order by w.date_from desc,w.source_window_id desc limit 1;
    if not found then raise exception 'BPAY_NEXT_TARGET_POLICY_WINDOW_MISSING' using errcode='23514'; end if;
    select count(*) into v_winners from private.bpay_next_valuation_policy_window w
      where w.policy_id=v_policy and w.date_from=v_window.date_from and v_date<=coalesce(w.date_to,'infinity'::date);
    if v_winners<>1 then raise exception 'BPAY_NEXT_TARGET_POLICY_WINDOW_AMBIGUOUS' using errcode='23514'; end if;
    v_old_json:='null'::jsonb; v_basis:=null;
    if v_book.source_comparison_receipt_id is not null then
      select r.* into strict v_old from private.bpay_next_source_comparison_receipt r where r.id=v_book.source_comparison_receipt_id;
      if v_old.source_book_revision<>v_book.source_book_revision or
        (v_old.native_realised_paye,v_old.native_realised_umbrella,v_old.native_held_paye,v_old.native_held_umbrella)
        is distinct from (v_book.native_realised_paye,v_book.native_realised_umbrella,v_book.native_held_paye,v_book.native_held_umbrella)
        or v_old.comparison_revision<>v_book.source_comparison_revision then
        raise exception 'BPAY_NEXT_COMPARISON_CURRENT_SNAPSHOT_INVALID' using errcode='23514'; end if;
      v_basis:=v_old.basis_review_id;
      v_old_json:=jsonb_build_object('id',v_old.id,'qualification_state',v_old.qualification_state,'selected_mode',v_old.selected_mode,
        'basis',jsonb_build_object('target_pay_channel',v_old.target_pay_channel,'comparison_policy_id',v_old.comparison_policy_id,
          'policy_window_id',v_old.policy_window_id,'effective_pay_date',v_old.effective_pay_date,'umbrella_vat_chargeable',v_old.umbrella_vat_chargeable,
          'target_umbrella_id',v_old.quote_json#>'{context,policy,target_umbrella_id}',
          'erni_pct',v_window.erni_pct,'vat_rate_pct',v_window.vat_rate_pct),
        'quantity_partition_qualified',coalesce((v_old.quote_json#>>'{quote,quantity_partition_qualified}')::boolean,false),
        'comparable_paid_ex_vat',v_old.comparable_paid_ex_vat,'comparable_held_ex_vat',v_old.comparable_held_ex_vat);
      if v_old.qualification_state='REVIEW'
        and v_old.review_issue_code='CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED' then
        v_old_json:=private.bpay_next_source_comparison_review_credit_snapshot_v2(v_old.id,v_book.source_book_revision);
        if v_old_json is null or v_old_json='null'::jsonb
          or v_old_json->>'id' is distinct from v_old.id::text
          or v_old_json->>'qualification_state' is distinct from 'REVIEW'
          or v_old_json->>'review_issue_code' is distinct from 'CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED'
          or v_old_json->>'credit_qualification_state' is distinct from 'READY' then
          raise exception 'BPAY_NEXT_COMPARISON_REVIEW_WORK_CREDIT_UNPROVED' using errcode='55000';
        end if;
      end if;
    end if;
    v_partition:='null'::jsonb;
    -- Paid origin is separate from the immutable approval seed. A normal
    -- ZERO-seeded book's first actual payment is the indexed flat collection.
    -- Only the full immutable actual line and exact native conservation qualify units.
    v_paid_effect_id:=v_book.source_book_seed_effect_id;v_paid_line_id:=v_book.source_book_seed_line_id;
    v_paid_channel:=v_book.source_book_seed_channel;v_partition_kind:='EXACT_FULL_PAID_SEED';
    if v_paid_effect_id is null then
      select origin.* into v_paid_origin from private.bpay_next_work_collection origin
        where origin.work_id=v_binding.canonical_work_id and origin.component_key=v_binding.canonical_component_key
          and origin.candidate_id=v_binding.candidate_id;
      if found and v_paid_origin.paid_basis_qualified and
        private.bpay_next_work_collection_source_original_v2(v_paid_origin) then
        v_paid_effect_id:=v_paid_origin.original_effect_id;v_paid_line_id:=v_paid_origin.original_approved_line_id;
        v_paid_channel:=v_paid_origin.original_source_pay_channel;v_partition_kind:='EXACT_FULL_PAID_ORIGIN';
      end if;
    end if;
    if v_paid_effect_id is not null and v_paid_line_id is not null then
      select a.* into strict v_seed_line from private.bpay_next_approved_line a where a.id=v_paid_line_id;
      select f.* into strict v_seed_effect from private.bpay_next_financial_effect f where f.id=v_paid_effect_id;
      select jsonb_agg(jsonb_build_object('bucket',d.bucket,'units',d.approved_hours,'pay_rate',d.source_pay_rate,
        'charge_rate',s.charge_rate) order by d.bucket),sum(d.approved_hours),count(*)::integer
        into v_rates,v_units,v_rate_count from private.bpay_next_rate_detail d
        join private.bpay_next_rate_schedule s on s.revision_id=v_seed_line.revision_id and s.rate_family='STANDARD' and s.rate_code=d.bucket
        where d.approved_line_id=v_seed_line.id and d.source_pay_rate is not null and s.charge_rate is not null
          and d.approved_hours>=0 and d.source_pay_rate>0 and s.charge_rate>0;
      if v_rate_count=v_seed_line.expected_rate_detail_count and v_rate_count>0 and v_units>0
        and v_seed_effect.source_disposition_ex_vat=v_seed_line.source_pay_ex_vat and v_seed_effect.source_disposition_ex_vat>0
        and v_seed_line.source_component_id=v_binding.source_component_id
        and (case when v_paid_channel='PAYE' then
          v_book.native_realised_paye=v_seed_effect.source_disposition_ex_vat and v_book.native_realised_umbrella=0
          else v_book.native_realised_umbrella=v_seed_effect.source_disposition_ex_vat and v_book.native_realised_paye=0 end)
        and v_book.native_held_paye=0 and v_book.native_held_umbrella=0 then
        v_partition:=jsonb_build_object('kind',v_partition_kind,'effect_id',v_seed_effect.id,'approved_line_id',v_seed_line.id,
          'source_pay_channel',v_paid_channel,
          'source_amount_ex_vat',v_seed_effect.source_disposition_ex_vat,'units',v_units,'buckets',v_rates);
      end if;
    end if;
    v_holds:='[]'; v_last:=null; v_hp:=0; v_hu:=0;
    loop
      v_page:=0;
      -- Existing ACTIVE (work,key,id) index and basis/hold mapping PK; no historical financial rows.
      for v_h in
        select h.id,h.run_line_id,h.work_id,h.component_key,h.source_reserved_ex_vat,l.source_pay_channel,l.approved_line_id,
          l.source_consumed_ex_vat from private.bpay_next_hold h join private.bpay_next_run_line l on l.id=h.run_line_id
        where h.status='ACTIVE' and h.component_key=v_binding.canonical_component_key
          and h.work_id in (v_binding.canonical_work_id,v_version.approval_work_id) and (v_last is null or h.id>v_last)
        union
        select h.id,h.run_line_id,h.work_id,h.component_key,h.source_reserved_ex_vat,l.source_pay_channel,l.approved_line_id,
          l.source_consumed_ex_vat from private.bpay_next_source_comparison_hold_mapping m
          join private.bpay_next_hold h on h.id=m.hold_id join private.bpay_next_run_line l on l.id=h.run_line_id
        where m.basis_review_id=v_basis and h.status='ACTIVE' and (v_last is null or h.id>v_last)
        order by id limit 64
      loop
        v_page:=v_page+1; v_last:=v_h.id; v_hpartition:='null'::jsonb;
        if v_h.source_reserved_ex_vat<>v_h.source_consumed_ex_vat or v_h.source_reserved_ex_vat<=0 then
          raise exception 'BPAY_NEXT_COMPARISON_ACTIVE_HOLD_INVALID' using errcode='23514'; end if;
        select a.* into strict v_seed_line from private.bpay_next_approved_line a where a.id=v_h.approved_line_id;
        select jsonb_agg(jsonb_build_object('bucket',d.bucket,'units',d.approved_hours,'pay_rate',d.source_pay_rate,
          'charge_rate',s.charge_rate) order by d.bucket),sum(d.approved_hours),count(*)::integer
          into v_rates,v_units,v_rate_count from private.bpay_next_rate_detail d
          join private.bpay_next_rate_schedule s on s.revision_id=v_seed_line.revision_id and s.rate_family='STANDARD' and s.rate_code=d.bucket
          where d.approved_line_id=v_seed_line.id and d.source_pay_rate is not null and s.charge_rate is not null
            and d.approved_hours>=0 and d.source_pay_rate>0 and s.charge_rate>0;
        if v_rate_count=v_seed_line.expected_rate_detail_count and v_rate_count>0 and v_units>0
          and v_h.source_reserved_ex_vat=v_seed_line.source_pay_ex_vat and v_seed_line.source_component_id=v_binding.source_component_id then
          v_hpartition:=jsonb_build_object('kind','EXACT_FULL_HELD_LINE','hold_id',v_h.id,'approved_line_id',v_seed_line.id,
            'source_amount_ex_vat',v_h.source_reserved_ex_vat,'units',v_units,'buckets',v_rates);
        end if;
        select m.comparable_reserved_ex_vat into v_existing from private.bpay_next_source_comparison_hold_mapping m
          where m.basis_review_id=v_basis and m.hold_id=v_h.id;
        v_holds:=v_holds||jsonb_build_array(jsonb_build_object('hold_id',v_h.id,'run_line_id',v_h.run_line_id,
          'work_id',v_h.work_id,'component_key',v_h.component_key,'native_source_channel',v_h.source_pay_channel,
          'native_reserved_ex_vat',v_h.source_reserved_ex_vat,'partition',v_hpartition,'existing_comparable_reserved_ex_vat',v_existing));
        if octet_length(v_holds::text)>32768 then
          raise exception 'BPAY_NEXT_COMPARISON_HELD_CERTIFICATE_CAPACITY_REVIEW_REQUIRED' using errcode='55000'; end if;
        if v_h.source_pay_channel='PAYE' then v_hp:=v_hp+v_h.source_reserved_ex_vat; else v_hu:=v_hu+v_h.source_reserved_ex_vat; end if;
      end loop;
      exit when v_page=0;
    end loop;
    if (v_hp,v_hu) is distinct from (v_book.native_held_paye,v_book.native_held_umbrella) then
      raise exception 'BPAY_NEXT_COMPARISON_HELD_OWNER_SCOPE_REVIEW_REQUIRED' using errcode='55000'; end if;
    v_cb:=private.bpay_next_source_comparison_case_basis_snapshot_v2(v_binding.canonical_work_id,v_binding.canonical_component_key);
    v_cholds:='[]';v_last:=null;v_cj:=0;
    if v_cb is not null and v_cb<>'null'::jsonb then
      loop
        v_page:=0;
        for v_ch in select h.id,h.instruction_id,h.allocation_result_id,h.source_reserved_ex_vat,h.target_amount_ex_vat,
          h.target_amount_vat,h.target_amount_inc_vat,i.source_pay_channel,i.target_pay_channel
          from private.bpay_next_case_hold h
          join private.bpay_next_run_case_instruction i on i.id=h.instruction_id
          join private.bpay_next_case_allocation_result ar on ar.id=h.allocation_result_id and ar.instruction_id=i.id
          where h.case_id=(v_cb->>'case_id')::uuid and h.case_component_id=(v_cb->>'case_component_id')::uuid
            and h.status='ACTIVE' and h.purpose in ('GROSS_RECOVERY','NET_RECOVERY_CAPACITY')
            and (v_last is null or h.id>v_last)
            and h.candidate_id=(v_request->>'candidate_id')::uuid and i.case_id=h.case_id
            and i.case_component_id=h.case_component_id and i.candidate_id=h.candidate_id
            and ar.allocated_source_ex_vat=h.source_reserved_ex_vat
            and (ar.allocated_target_ex_vat,ar.allocated_target_vat,ar.allocated_target_inc_vat)
              =(h.target_amount_ex_vat,h.target_amount_vat,h.target_amount_inc_vat)
          order by h.id limit 64
        loop
          v_page:=v_page+1;v_last:=v_ch.id;v_cj:=v_cj+v_ch.source_reserved_ex_vat;
          if v_ch.source_pay_channel is distinct from v_cb->>'case_source_channel' then
            raise exception 'BPAY_NEXT_COMPARISON_CASE_HOLD_BASIS_REVIEW_REQUIRED' using errcode='55000';end if;
          v_cholds:=v_cholds||jsonb_build_array(jsonb_build_object('case_hold_id',v_ch.id,'instruction_id',v_ch.instruction_id,
            'allocation_result_id',v_ch.allocation_result_id,'source_reserved_ex_vat',v_ch.source_reserved_ex_vat,
            'native_target_channel',v_ch.target_pay_channel,'native_target_ex_vat',v_ch.target_amount_ex_vat,
            'native_target_vat',v_ch.target_amount_vat,'native_target_inc_vat',v_ch.target_amount_inc_vat));
          if octet_length(v_cholds::text)>32768 then
            raise exception 'BPAY_NEXT_COMPARISON_HELD_CERTIFICATE_CAPACITY_REVIEW_REQUIRED' using errcode='55000';end if;
        end loop;
        exit when v_page=0;
      end loop;
      if v_cj is distinct from (v_cb->>'J')::numeric then
        raise exception 'BPAY_NEXT_COMPARISON_CASE_HOLD_OWNER_SCOPE_REVIEW_REQUIRED' using errcode='55000';end if;
    end if;
    v_context:=jsonb_build_object('case_basis',v_cb,'active_case_holds',v_cholds,'component_id',v_original->>'component_id','candidate_id',v_request->>'candidate_id',
      'canonical_work_id',v_binding.canonical_work_id,'canonical_component_key',v_binding.canonical_component_key,
      'source_binding_version_id',v_version.id,'source_book_revision',v_book.source_book_revision,
      'source_comparison_receipt_id',v_book.source_comparison_receipt_id,'source_comparison_revision',v_book.source_comparison_revision,
      'native_realised_paye',v_book.native_realised_paye,'native_realised_umbrella',v_book.native_realised_umbrella,
      'native_held_paye',v_book.native_held_paye,'native_held_umbrella',v_book.native_held_umbrella,
      'seed_source_channel',v_book.source_book_seed_channel,'tax_treatment',v_version.tax_treatment,'component_semantics',v_class,
      'original_component',v_original,'paid_partition',v_partition,'active_holds',v_holds,'current_comparison',v_old_json,
      'policy',jsonb_build_object('target_pay_channel',v_target,'comparison_policy_id',v_policy,'policy_window_id',v_window.source_window_id,
        'effective_pay_date',v_date,'umbrella_vat_chargeable',v_vat,'target_umbrella_id',v_recipient,
        'erni_pct',v_window.erni_pct,'vat_rate_pct',v_window.vat_rate_pct));
    v_quote:=private.bpay_next_source_comparison_quote_snapshot_v2(v_context,v_selection);
    v_p:=(v_quote->>'comparable_paid_ex_vat')::numeric; v_hamount:=(v_quote->>'comparable_held_ex_vat')::numeric;
    v_n:=(v_component->>'pay_ex_vat')::numeric;
    v_case_quote:=private.bpay_next_source_comparison_case_quote_snapshot_v2(v_context,v_selection,v_p,v_n);
    v_plan:=(v_context->'policy')-'erni_pct'-'vat_rate_pct'||jsonb_build_object(
      'selected_mode',v_quote->>'selected_mode','quantity_partition_qualified',v_quote->'quantity_partition_qualified',
      'comparable_paid_ex_vat',v_p,'comparable_held_ex_vat',v_hamount,
      'approved_source_ex_vat',v_n,'selected_residual_ex_vat',v_n-v_p-v_hamount,'paid_excess_ex_vat',greatest(v_p-v_n,0),
      'hold_mappings',v_quote->'hold_mappings','case_resolution',v_case_quote->'case_resolution',
      'case_hold_mappings',v_case_quote->'case_hold_mappings','reason',v_selection->>'reason',
      'quote_json',jsonb_build_object('schema_version','BPAY_NEXT_SOURCE_SELECTED_QUOTE_V2','context',v_context,'selection',v_selection,'quote',v_quote),
      'basis_sha256',encode(private.weekly_source_sha256_jsonb_v1('BPAY_NEXT_SOURCE_COMPARISON_BASIS_V2',
        jsonb_build_object('policy',v_context->'policy','selected_mode',v_quote->>'selected_mode','selection',v_selection)),'hex'));
    if octet_length((v_plan->'quote_json')::text)>32768 then
      raise exception 'BPAY_NEXT_COMPARISON_HELD_CERTIFICATE_CAPACITY_REVIEW_REQUIRED' using errcode='55000'; end if;
    v_contexts:=v_contexts||jsonb_build_array(v_context);
    v_plans:=v_plans||jsonb_build_array(jsonb_build_object('source_component_id',v_original->>'component_id','context',v_context,'plan',v_plan));
  end loop;
  v_hash:=encode(private.weekly_source_sha256_jsonb_v1('BPAY_NEXT_SOURCE_PLANNED_REQUEST_V2',p_planned_request),'hex');
  v_fc:=jsonb_build_object('schema_version','BPAY_NEXT_SOURCE_FINANCIAL_CONTEXT_V3','candidate_id',v_request->>'candidate_id',
    'actor_user_id',p_actor,'planned_request_sha256',v_hash,'financial_scope',v_scope,'components',v_contexts);
  v_fp:=jsonb_build_object('schema_version','BPAY_NEXT_SOURCE_FINANCIAL_PLAN_V3','candidate_id',v_request->>'candidate_id',
    'planned_request_sha256',v_hash,'components',v_plans);
  v_valid:=private.bpay_next_source_comparison_validate_plan_snapshot_v2(p_planned_request,v_fc,v_fp);
  return jsonb_build_object('financial_context',v_fc,'financial_plan',v_fp,'financial_plan_digest',v_valid->>'financial_plan_digest');
end
$function$;

create or replace function private.bpay_next_source_comparison_register_review_v2(
  p_source_receipt_id uuid,p_source_component_id uuid,p_review_certificate_id uuid)
returns uuid language plpgsql volatile security definer
set search_path=pg_catalog,private,public
as $function$
declare v_w private.weekly_source_destination_reprice_witness_v1%rowtype;
  v_r private.weekly_source_entitlement_publication_receipts%rowtype;
  v_b private.bpay_next_source_component_binding_version%rowtype;
  v_a private.bpay_next_approved_line%rowtype; v_request jsonb; v_item jsonb; v_component jsonb;
  v_context jsonb; v_plan jsonb; v_valid jsonb; v_count integer;
begin
  select w.* into strict v_w from private.weekly_source_destination_reprice_witness_v1 w where w.id=p_review_certificate_id;
  select r.* into strict v_r from private.weekly_source_entitlement_publication_receipts r where r.id=p_source_receipt_id;
  select b.* into strict v_b from private.bpay_next_source_component_binding_version b
    where b.source_receipt_id=p_source_receipt_id and b.source_component_id=p_source_component_id;
  v_request:=v_w.accepted_request_json;
  -- Remove only the certificate pointer and server decision-time acknowledgement:
  -- financial snapshot binds the exact server-priced pre-accept quote.request.
  v_request:=v_request#-'{financial_request,contract_choices,1,destination_reprice}';
  v_request:=jsonb_set(v_request,'{control,whole_root_office_review}',v_w.context_json#>'{base_request,control,whole_root_office_review}');
  v_valid:=private.bpay_next_source_comparison_validate_plan_snapshot_v2(v_request,
    v_w.context_json->'financial_context',v_w.context_json->'financial_plan');
  if v_valid->>'financial_plan_digest' is distinct from v_w.context_json->>'financial_plan_digest'
    or (v_r.decision_bundle_id,v_r.bundle_revision,v_r.candidate_id,v_r.decided_by_user_id)
      is distinct from (v_w.decision_bundle_id,v_w.bundle_revision,(v_w.accepted_request_json->>'candidate_id')::uuid,v_w.actor_user_id)
    or v_b.request_digest is distinct from v_r.request_digest or v_b.decision_bundle_id<>v_r.decision_bundle_id
    or v_b.bundle_revision<>v_r.bundle_revision or v_b.component_state<>'PRESENT'
    or not exists(select 1 from private.bpay_next_source_component_binding b where b.current_binding_version_id=v_b.id
      and b.canonical_work_id=v_b.canonical_work_id and b.canonical_component_key=v_b.canonical_component_key)
    or not exists(select 1 from public.weekly_source_entitlement_heads h where h.id=v_b.head_id
      and h.state='COMMITTED_CURRENT' and h.id=any(v_r.head_ids) and h.decision_bundle_id=v_r.decision_bundle_id
      and h.bundle_revision=v_r.bundle_revision)
    or not exists(select 1 from public.weekly_source_entitlement_decision_bundles b
      where b.decision_bundle_id=v_w.decision_bundle_id and b.bundle_revision=v_w.bundle_revision and b.state in ('PROPOSED','COMMITTED')
        and b.decided_by_user_id=v_w.actor_user_id and b.whole_root_reviewed_by_user_id=v_w.actor_user_id) then
    raise exception 'BPAY_NEXT_COMPARISON_SOURCE_CERTIFICATE_SCOPE_INVALID' using errcode='23514';
  end if;
  select count(*)::integer,jsonb_agg(value)->0 into v_count,v_item
    from jsonb_array_elements(v_w.context_json#>'{financial_plan,components}') where value->>'source_component_id'=p_source_component_id::text;
  if v_count<>1 then raise exception 'BPAY_NEXT_COMPARISON_PLAN_COMPONENT_INVALID' using errcode='23514'; end if;
  v_context:=v_item->'context';v_plan:=v_item->'plan';
  select count(*)::integer,jsonb_agg(value)->0 into v_count,v_component
    from jsonb_array_elements(v_w.accepted_request_json#>'{financial_request,member_entitlements,1,components}')
    where value->>'component_id'=p_source_component_id::text;
  select a.* into strict v_a from private.bpay_next_approved_line a where a.id=v_b.approved_line_id;
  if v_count<>1 or v_b.canonical_work_id::text is distinct from v_context->>'canonical_work_id'
    or v_b.canonical_component_key is distinct from v_context->>'canonical_component_key'
    or v_b.approval_source_channel is distinct from v_plan->>'target_pay_channel'
    or v_a.source_pay_ex_vat is distinct from (v_plan->>'approved_source_ex_vat')::numeric
    or v_a.source_pay_ex_vat is distinct from (v_component->>'pay_ex_vat')::numeric
    or v_a.source_component_id is distinct from p_source_component_id
    or v_a.tax_treatment is distinct from v_context->>'tax_treatment'
    or v_b.component_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
      private.weekly_source_publication_component_content_v1(v_component)) then
    raise exception 'BPAY_NEXT_COMPARISON_ACTUAL_APPROVAL_NOT_PLANNED' using errcode='23514';
  end if;
  -- Core locks current canonical position and proves exact input revisions/native
  -- tuple, or the same accepted PENDING basis carried by actual known operations.
  -- No future APPLIED status is fabricated here; preparation owns that later gate.
  return private.bpay_next_source_comparison_register_core_v2(v_b.id,p_review_certificate_id,v_context,v_plan);
end
$function$;

alter function private.bpay_next_source_comparison_case_quote_snapshot_v2(jsonb,jsonb,numeric,numeric) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_quote_snapshot_v2(jsonb,jsonb) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_validate_plan_snapshot_v2(jsonb,jsonb,jsonb) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_plan_v2(uuid,jsonb,jsonb,text) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_register_review_v2(uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_case_quote_snapshot_v2(jsonb,jsonb,numeric,numeric),
  private.bpay_next_source_comparison_quote_snapshot_v2(jsonb,jsonb),
  private.bpay_next_source_comparison_validate_plan_snapshot_v2(jsonb,jsonb,jsonb),
  private.bpay_next_source_comparison_plan_v2(uuid,jsonb,jsonb,text),
  private.bpay_next_source_comparison_register_review_v2(uuid,uuid,uuid) from public,anon,authenticated,service_role;


-- E-only joined Source/Banking successor. Source V2 prerequisite is frozen.
-- Same0105 certificate; no future HEAD/binding, balances or alternate pricing.



-- A closed server-owned annotation, not arbitrary caller JSON additions.
create or replace function private.weekly_source_destination_joined_source_context_v2(p_context jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path=pg_catalog,private as $function$
declare v_joined boolean:=p_context ? 'joined_review_schema'; v_source jsonb;
begin
  perform private.weekly_source_publication_require_keys_v1(p_context,array[
    'schema_version','actor_user_id','agency_id','base_request','before_canonical',
    'destination_pay_channel','stage_snapshot','components']
    ||case when v_joined then array['financial_context','financial_plan','financial_plan_digest',
      'financial_selections','joined_review_schema'] else array[]::text[] end,'destination.joined_context');
  if v_joined and p_context->>'joined_review_schema' is distinct from 'SOURCE_DESTINATION_PAY_FINANCIAL_REVIEW_V2' then
    raise exception 'WEEKLY_SOURCE_JOINED_REVIEW_SCHEMA_INVALID' using errcode='22023'; end if;
  v_source:=p_context-array['financial_context','financial_plan','financial_plan_digest','financial_selections','joined_review_schema'];
  if v_source->>'schema_version' is distinct from 'WEEKLY_SOURCE_DESTINATION_RATE_CONTEXT_V1' then
    raise exception 'WEEKLY_SOURCE_JOINED_CONTEXT_INVALID' using errcode='22023'; end if;
  return v_source;
end $function$;

-- Cold additive complete-destination successor. Every genuine moved-A and
-- own-B HEAD component is priced and financially selected in the SAME review.
-- V2 financial packets were E-only, never installed/accepted in this rollout;
-- only exact V3 financial context/plan is admitted. No historical subsystem.
-- Pure frozen review/integrity composition. No current rates, settings, books,
-- effects, held children or binding discovery is performed by this function.
create or replace function private.weekly_source_destination_financial_frozen_review_v2(
  p_context jsonb,p_source_quote jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path=pg_catalog,private as $function$
declare v_source jsonb; v_valid jsonb; v_review jsonb; v_item jsonb; v_selection jsonb; v_count integer;
  v_moved jsonb;v_own jsonb;v_combined jsonb;v_planned_ids jsonb;v_control_ids jsonb;
begin
  v_source:=private.weekly_source_destination_joined_source_context_v2(p_context);
  if p_context->>'joined_review_schema' is distinct from 'SOURCE_DESTINATION_PAY_FINANCIAL_REVIEW_V2'
     or jsonb_typeof(p_context->'financial_selections') is distinct from 'array'
     or coalesce(p_context->>'financial_plan_digest','')!~'^[0-9a-f]{64}$'
     or p_source_quote#>'{review,context}' is distinct from v_source
     or p_source_quote->>'review_sha256' is distinct from encode(private.weekly_source_sha256_jsonb_v1(
       'WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_V1',p_source_quote->'review'),'hex') then
    raise exception 'WEEKLY_SOURCE_JOINED_REVIEW_NOT_EXACT' using errcode='23514'; end if;
  perform private.weekly_source_publication_require_keys_v1(p_context->'financial_context',array[
    'schema_version','candidate_id','actor_user_id','planned_request_sha256','financial_scope','components'],'destination.financial_context');
  perform private.weekly_source_publication_require_keys_v1(p_context->'financial_plan',array[
    'schema_version','candidate_id','planned_request_sha256','components'],'destination.financial_plan');
  perform private.weekly_source_publication_require_keys_v1(p_context#>'{financial_context,financial_scope}',array[
    'schema_version','moved_component_ids','own_b_component_ids','comparison_component_ids'],'destination.financial_scope');
  select coalesce(jsonb_agg(c#>'{component,component_id}' order by c#>>'{component,component_id}'), '[]'::jsonb)
    into v_moved from jsonb_array_elements(v_source->'components') c where c->>'before_root_ordinal'='1';
  select coalesce(jsonb_agg(c#>'{component,component_id}' order by c#>>'{component,component_id}'), '[]'::jsonb)
    into v_own from jsonb_array_elements(v_source->'components') c where c->>'before_root_ordinal'='2';
  select coalesce(jsonb_agg(c#>'{component,component_id}' order by c#>>'{component,component_id}'), '[]'::jsonb)
    into v_combined from jsonb_array_elements(v_source->'components') c;
  select coalesce(jsonb_agg(c->'component_id' order by c->>'component_id'), '[]'::jsonb)
    into v_planned_ids from jsonb_array_elements(p_source_quote#>'{request,financial_request,member_entitlements,1,components}') c;
  select coalesce(jsonb_agg(c order by c#>>'{}'), '[]'::jsonb)
    into v_control_ids from jsonb_array_elements(p_source_quote#>'{request,control,moved_component_ids}') c;
  if p_context#>>'{financial_context,schema_version}' is distinct from 'BPAY_NEXT_SOURCE_FINANCIAL_CONTEXT_V3'
     or p_context#>>'{financial_plan,schema_version}' is distinct from 'BPAY_NEXT_SOURCE_FINANCIAL_PLAN_V3'
     or p_context#>>'{financial_context,financial_scope,schema_version}' is distinct from 'BPAY_NEXT_SOURCE_FINANCIAL_SCOPE_V3'
     or p_context#>'{financial_context,financial_scope,moved_component_ids}' is distinct from v_moved
     or p_context#>'{financial_context,financial_scope,own_b_component_ids}' is distinct from v_own
     or p_context#>'{financial_context,financial_scope,comparison_component_ids}' is distinct from v_combined
     or v_control_ids is distinct from v_moved or v_planned_ids is distinct from v_combined
     or exists(select 1 from jsonb_array_elements(v_source->'components') c
       where c->>'before_root_ordinal' not in ('1','2') or c->>'before_root_ordinal' is null
         or c->>'before_root_timesheet_id' is distinct from
           v_source#>>array['base_request','member_root_ids',((c->>'before_root_ordinal')::integer-1)::text]) then
    raise exception 'WEEKLY_SOURCE_JOINED_COMPLETE_DESTINATION_SCOPE_INVALID' using errcode='23514';end if;
  v_valid:=private.bpay_next_source_comparison_validate_plan_snapshot_v2(p_source_quote->'request',
    p_context->'financial_context',p_context->'financial_plan');
  if v_valid->'ok' is distinct from 'true'::jsonb
     or v_valid->>'financial_plan_digest' is distinct from p_context->>'financial_plan_digest'
     or p_context#>>'{financial_context,actor_user_id}' is distinct from v_source->>'actor_user_id'
     or p_context#>>'{financial_context,candidate_id}' is distinct from p_source_quote#>>'{request,candidate_id}'
     or jsonb_array_length(p_context->'financial_selections') is distinct from
       jsonb_array_length(p_context#>'{financial_plan,components}') then
    raise exception 'WEEKLY_SOURCE_JOINED_FINANCIAL_SNAPSHOT_INVALID' using errcode='23514'; end if;
  for v_item in select value from jsonb_array_elements(p_context#>'{financial_plan,components}')
    order by value->>'source_component_id' loop
    perform private.weekly_source_publication_require_keys_v1(v_item,array[
      'source_component_id','context','plan'],'destination.financial_plan_component');
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_selection
      from jsonb_array_elements(p_context->'financial_selections')
      where value->>'component_id'=v_item->>'source_component_id';
    if v_count<>1 or v_selection is distinct from v_item#>'{plan,quote_json,selection}'
       or v_item#>>'{plan,target_pay_channel}' is distinct from v_source->>'destination_pay_channel' then
      raise exception 'WEEKLY_SOURCE_JOINED_SELECTION_NOT_BOUND' using errcode='23514'; end if;
  end loop;
  v_review:=jsonb_build_object('schema_version','SOURCE_DESTINATION_PAY_FINANCIAL_REVIEW_V2',
    'source_review',p_source_quote->'review','financial_context',p_context->'financial_context',
    'financial_plan',p_context->'financial_plan','financial_plan_digest',p_context->>'financial_plan_digest',
    'financial_selections',p_context->'financial_selections');
  return jsonb_build_object('review',v_review,'review_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'SOURCE_DESTINATION_PAY_FINANCIAL_REVIEW_V2',v_review),'hex'));
end $function$;

-- Genuine pricing comes from the existing Source quote.request ONLY. Financial
-- book/policy selection is captured in the planner's one STABLE statement,
-- using the exact accepted Source channel, never a mutable Contract fallback.
create or replace function private.weekly_source_destination_financial_quote_v2(
  p_source_context jsonb,p_calculations jsonb,p_financial_selections jsonb)
returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,private,public as $function$
declare v_source jsonb; v_source_quote jsonb; v_financial jsonb; v_context jsonb; v_joined jsonb;
begin
  v_source:=private.weekly_source_destination_joined_source_context_v2(p_source_context);
  if p_source_context ? 'joined_review_schema' then
    raise exception 'WEEKLY_SOURCE_JOINED_SOURCE_CONTEXT_REQUIRED' using errcode='22023'; end if;
  v_source_quote:=private.weekly_source_destination_reprice_quote_v1(v_source,p_calculations);
  select private.bpay_next_source_comparison_plan_v2((v_source->>'actor_user_id')::uuid,
    v_source_quote->'request',p_financial_selections,v_source->>'destination_pay_channel') into v_financial;
  perform private.weekly_source_publication_require_keys_v1(v_financial,array[
    'financial_context','financial_plan','financial_plan_digest'],'destination.financial_planner_result');
  v_context:=v_source||v_financial||jsonb_build_object('financial_selections',p_financial_selections,
    'joined_review_schema','SOURCE_DESTINATION_PAY_FINANCIAL_REVIEW_V2');
  v_joined:=private.weekly_source_destination_financial_frozen_review_v2(v_context,v_source_quote);
  return v_source_quote||v_joined||jsonb_build_object('context',v_context);
end $function$;

create or replace function public.weekly_source_destination_financial_preview_v2(
  p_actor uuid,p_base_request jsonb,p_calculations jsonb default null,p_financial_selections jsonb default null)
returns jsonb language plpgsql stable security definer
set search_path=public,private,pg_catalog,pg_temp as $function$
declare v_context jsonb;
begin
  v_context:=private.weekly_source_destination_reprice_context_v1(p_actor,p_base_request);
  if p_calculations is null then return jsonb_build_object('ok',true,'context',v_context); end if;
  return jsonb_build_object('ok',true,'quote',private.weekly_source_destination_financial_quote_v2(
    v_context,p_calculations,p_financial_selections),'financial_review_accepted',false);
end $function$;

-- Complete versioned acceptance; existing Source V2 public v1 entry is untouched.
create or replace function public.weekly_source_destination_financial_accept_v2(
  p_actor uuid,p_base_request jsonb,p_calculations jsonb,p_financial_selections jsonb,p_review_sha256 text,
  p_idempotency_key text,p_reason text
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_input bytea; v_saved private.weekly_source_destination_reprice_witness_v1%rowtype;
  v_context jsonb; v_source_context jsonb; v_quote jsonb; v_plan_item jsonb; v_request jsonb; v_lock jsonb; v_roots uuid[];
  v_id uuid; v_time timestamptz; v_record jsonb; v_result jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
      nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor is null or char_length(btrim(coalesce(p_reason,''))) not between 1 and 2000
     or char_length(coalesce(p_idempotency_key,'')) not between 16 and 200
     or coalesce(p_review_sha256,'')!~'^[0-9a-f]{64}$' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_ACCEPT_INVALID' using errcode='22023'; end if;
  v_input:=private.weekly_source_sha256_jsonb_v1('SOURCE_DESTINATION_PAY_FINANCIAL_ACCEPT_V2',jsonb_build_object(
    'actor',p_actor,'base',p_base_request,'calculations',p_calculations,'financial_selections',p_financial_selections,
    'review',p_review_sha256,'reason',p_reason));
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1 where idempotency_key=p_idempotency_key;
  if found then
    if v_saved.input_sha256 is distinct from v_input or v_saved.actor_user_id is distinct from p_actor then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_REPLAY_CONFLICT' using errcode='22023'; end if;
    v_result:=private.weekly_source_entitlement_publish_immediate_v1(v_saved.accepted_request_json);
    if v_result->'ok' is distinct from 'true'::jsonb or not (
      v_result->'published' is not distinct from 'true'::jsonb or (v_result->>'code' is not distinct from 'WEEKLY_SOURCE_PUBLICATION_DEFERRED_PENDING_FREEZE'
        and v_result->>'pending_bundle_verified' is not null and v_result#>'{pending,ok}' is not distinct from 'true'::jsonb)) then
      raise exception 'WEEKLY_SOURCE_JOINED_PUBLICATION_NOT_ACCEPTED' using errcode='55000',detail=v_result::text;
    end if;
    return jsonb_build_object('witness_id',v_saved.id,'source_publication',v_result,'financial_comparison_resolved',false,'financial_review_accepted',true);
  end if;
  -- A new decision must see a fresh post-I1 statement snapshot. Historical
  -- exact replay above does not acquire today's economics or this new gate.
  if current_setting('transaction_isolation') is distinct from 'read committed' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_READ_COMMITTED_REQUIRED' using errcode='25001'; end if;
  v_roots:=array[(p_base_request#>>'{member_root_ids,0}')::uuid,(p_base_request#>>'{member_root_ids,1}')::uuid];
  v_lock:=private.weekly_source_lock_and_resolve_families_v1((p_base_request->>'candidate_id')::uuid,v_roots,
    'WORKBENCH_CANDIDATE_ENTITLEMENT_PUBLICATION',gen_random_uuid(),'WEEKLY_SOURCE_ENTITLEMENT_PUBLICATION');
  if v_lock->>'ok' is distinct from 'true' or v_lock->>'gate' is distinct from 'GRANTED' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_UNAVAILABLE' using errcode='55000'; end if;
  -- Re-enter the exact replay after I-1. This is a bounded single reread,
  -- never a replay using today's rates or a second independent decision.
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1 where idempotency_key=p_idempotency_key;
  if found then
    if v_saved.input_sha256 is distinct from v_input or v_saved.actor_user_id is distinct from p_actor then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_REPLAY_CONFLICT' using errcode='22023'; end if;
    v_result:=private.weekly_source_entitlement_publish_immediate_v1(v_saved.accepted_request_json);
    if v_result->'ok' is distinct from 'true'::jsonb or not (
      v_result->'published' is not distinct from 'true'::jsonb or (v_result->>'code' is not distinct from 'WEEKLY_SOURCE_PUBLICATION_DEFERRED_PENDING_FREEZE'
        and v_result->>'pending_bundle_verified' is not null and v_result#>'{pending,ok}' is not distinct from 'true'::jsonb)) then
      raise exception 'WEEKLY_SOURCE_JOINED_PUBLICATION_NOT_ACCEPTED' using errcode='55000',detail=v_result::text;
    end if;
    return jsonb_build_object('witness_id',v_saved.id,'source_publication',v_result,'financial_comparison_resolved',false,'financial_review_accepted',true);
  end if;
  -- Exactly ONE fresh STABLE context SELECT after I1 and its replay reread.
  -- Pricing descendants and full stage helper inputs use this statement's
  -- snapshot; the nested lifecycle signature(false) is not globally STABLE.
  -- Existing I1/currentwork/publisher guards retain work currentness. This is
  -- accepted-at-this-read pricing, never latest-at-release pricing.
  select private.weekly_source_destination_reprice_context_v1(p_actor,p_base_request) into v_source_context;
  select private.weekly_source_destination_financial_quote_v2(v_source_context,p_calculations,p_financial_selections) into v_quote;
  v_context:=v_quote->'context';
  if v_quote->>'review_sha256' is distinct from p_review_sha256 then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_STALE' using errcode='40001'; end if;
  v_id:=gen_random_uuid(); v_time:=transaction_timestamp(); v_request:=v_quote->'request';
  v_request:=jsonb_set(v_request,'{financial_request,contract_choices,1,destination_reprice}',jsonb_build_object(
    'schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1','witness_id',v_id,'review_sha256',p_review_sha256));
  -- Whole own-B acknowledgement is accepted at the same exact shown digest;
  -- the recorder persists the existing actor/time columns and replay checks.
  v_request:=jsonb_set(v_request,'{control,whole_root_office_review}',jsonb_build_object(
    'reviewed',true,'reviewed_by_user_id',p_actor,'reviewed_at_utc',v_time,'decision_id',v_request->>'decision_id'));
  insert into private.weekly_source_destination_reprice_witness_v1(id,decision_bundle_id,bundle_revision,
    idempotency_key,input_sha256,actor_user_id,reason,context_json,economic_snapshots_json,review_sha256,
    accepted_request_json,accepted_request_sha256,accepted_control_sha256,accepted_at_utc)
  values(v_id,(v_request->>'decision_bundle_id')::uuid,(v_request->>'bundle_revision')::bigint,p_idempotency_key,
    v_input,p_actor,p_reason,v_context,v_quote->'components',decode(p_review_sha256,'hex'),v_request,
    private.weekly_source_publication_request_digest_v1(private.weekly_source_publication_request_canonical_v1(v_request,'IMMEDIATE',null)),
    sha256(convert_to((v_request->'control')::text,'UTF8')),v_time);
  -- ONE accepted family per component, on the REAL CURRENT input binding.
  -- Pending N is planned; observed N/native balances remain actual. Register
  -- under the real owner locks before I4; a changed book rolls back this pair.
  for v_plan_item in select value from jsonb_array_elements(v_context#>'{financial_plan,components}')
    order by value->>'source_component_id' loop
    perform private.bpay_next_source_comparison_register_pending_core_v2(v_id,v_plan_item->'context',v_plan_item->'plan');
  end loop;
  v_record:=private.weekly_source_entitlement_proposal_record_v1(v_request,(v_context->>'agency_id')::uuid,
    (v_request#>>'{financial_request,contract_choices,0,contract_id}')::uuid,
    (v_request#>>'{financial_request,contract_choices,0,week_ending_date}')::date,p_actor);
  if v_record->>'ok' is distinct from 'true' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_PROPOSAL_NOT_RECORDED' using errcode='55000'; end if;
  v_result:=private.weekly_source_entitlement_publish_immediate_v1(v_request);
  -- Only the existing verified I5 pending save is an accepted non-publication.
  -- Ordinary publisher refusal cannot commit a stranded PENDING comparison.
  if v_result->'ok' is distinct from 'true'::jsonb or not (
    v_result->'published' is not distinct from 'true'::jsonb or (v_result->>'code' is not distinct from 'WEEKLY_SOURCE_PUBLICATION_DEFERRED_PENDING_FREEZE'
      and v_result->>'pending_bundle_verified' is not null and v_result#>'{pending,ok}' is not distinct from 'true'::jsonb)) then
    raise exception 'WEEKLY_SOURCE_JOINED_PUBLICATION_NOT_ACCEPTED' using errcode='55000',detail=v_result::text;
  end if;
  return jsonb_build_object('witness_id',v_id,'review_sha256',p_review_sha256,
    'source_publication',v_result,'financial_comparison_resolved',false,'financial_review_accepted',true);
end;
$function$;

-- Complete winning verifier successor. Pure Source witnesses retain their
-- original integrity branch; joined witnesses strip ONLY the five known keys
-- and pure-validate the frozen financial snapshot, never current economics.
create or replace function private.weekly_source_destination_reprice_verify_v1(
  p_canonical jsonb,p_control jsonb
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_saved private.weekly_source_destination_reprice_witness_v1%rowtype;
  v_request jsonb; v_calculations jsonb; v_quote jsonb; v_expected jsonb;
  v_source_context jsonb; v_joined jsonb; v_expected_review_sha256 text;
begin
  if p_canonical#>'{financial_request,contract_choices,1,destination_reprice}' is null then return null; end if;
  select * into strict v_saved from private.weekly_source_destination_reprice_witness_v1
    where id=(p_canonical#>>'{financial_request,contract_choices,1,destination_reprice,witness_id}')::uuid for share;
  v_request:=jsonb_set(jsonb_set(p_canonical,'{publication_mode}','"IMMEDIATE"'::jsonb),'{pending_bundle_id}','null'::jsonb);
  if v_saved.review_sha256 is distinct from decode(p_canonical#>>'{financial_request,contract_choices,1,destination_reprice,review_sha256}','hex')
     or v_saved.accepted_request_sha256 is distinct from private.weekly_source_publication_request_digest_v1(v_request)
     or v_saved.accepted_control_sha256 is distinct from sha256(convert_to(p_control::text,'UTF8'))
     or v_saved.accepted_request_json->'control' is distinct from p_control
     or not exists(select 1 from public.weekly_source_entitlement_decision_bundles b
       where b.decision_bundle_id=v_saved.decision_bundle_id and b.bundle_revision=v_saved.bundle_revision
         and b.decided_by_user_id=v_saved.actor_user_id and b.whole_root_review_required
         and b.whole_root_reviewed_by_user_id=v_saved.actor_user_id
         and b.whole_root_reviewed_at_utc=v_saved.accepted_at_utc) then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_WITNESS_NOT_EXACT' using errcode='23514'; end if;
  -- Re-derive the accepted review and output from immutable certificate
  -- inputs. There is deliberately NO fresh mutable context/rate/settings read.
  perform private.weekly_source_destination_stage_snapshot_check_v1(v_saved.context_json->'stage_snapshot');
  select jsonb_agg(jsonb_build_object('component_id',value->>'component_id',
      'economic_snapshot',value->'economic_snapshot','price_comparison',value->'price_comparison')
      order by value->>'component_id') into v_calculations
    from jsonb_array_elements(v_saved.economic_snapshots_json);
  v_source_context:=private.weekly_source_destination_joined_source_context_v2(v_saved.context_json);
  v_quote:=private.weekly_source_destination_reprice_quote_v1(v_source_context,v_calculations);
  v_expected_review_sha256:=v_quote->>'review_sha256';
  if v_saved.context_json ? 'joined_review_schema' then
    v_joined:=private.weekly_source_destination_financial_frozen_review_v2(v_saved.context_json,v_quote);
    v_expected_review_sha256:=v_joined->>'review_sha256';
  end if;
  v_expected:=jsonb_set(v_quote->'request','{financial_request,contract_choices,1,destination_reprice}',
    jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1','witness_id',v_saved.id,
      'review_sha256',encode(v_saved.review_sha256,'hex')));
  v_expected:=jsonb_set(v_expected,'{control,whole_root_office_review}',jsonb_build_object(
    -- Preserve the actual accepted JSON time representation across session
    -- timezone changes; its typed instant is checked against server time below.
    'reviewed',true,'reviewed_by_user_id',v_saved.actor_user_id,
    'reviewed_at_utc',v_saved.accepted_request_json#>'{control,whole_root_office_review,reviewed_at_utc}',
    'decision_id',v_expected->>'decision_id'));
  if v_saved.context_json->>'actor_user_id' is distinct from v_saved.actor_user_id::text
     or (v_saved.accepted_request_json#>>'{control,whole_root_office_review,reviewed_at_utc}')::timestamptz
       is distinct from v_saved.accepted_at_utc
     or v_saved.context_json#>>'{stage_snapshot,destination_pay_channel}' is distinct from
       v_saved.context_json->>'destination_pay_channel'
     or v_saved.context_json#>>'{stage_snapshot,root_timesheet_id}' is distinct from
       v_saved.accepted_request_json#>>'{member_root_ids,1}'
     or v_saved.context_json#>>'{stage_snapshot,contract_id}' is distinct from
       v_saved.accepted_request_json#>>'{financial_request,contract_choices,1,contract_id}'
     or v_saved.context_json#>>'{stage_snapshot,candidate_id}' is distinct from
       v_saved.accepted_request_json->>'candidate_id'
     or v_expected_review_sha256 is distinct from encode(v_saved.review_sha256,'hex')
     or v_quote->'components' is distinct from v_saved.economic_snapshots_json
     or v_expected is distinct from v_saved.accepted_request_json
     or v_saved.decision_bundle_id is distinct from (v_expected->>'decision_bundle_id')::uuid
     or v_saved.bundle_revision is distinct from (v_expected->>'bundle_revision')::bigint
     or v_saved.accepted_request_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
       private.weekly_source_publication_request_canonical_v1(v_expected,'IMMEDIATE',null))
     or v_saved.accepted_control_sha256 is distinct from sha256(convert_to((v_expected->'control')::text,'UTF8')) then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CERTIFICATE_CORRUPT' using errcode='23514'; end if;
  return jsonb_build_object('witness_id',v_saved.id,'review_sha256',encode(v_saved.review_sha256,'hex'),
    'components',v_saved.economic_snapshots_json,'destination_pay_channel',v_saved.context_json->>'destination_pay_channel');
end;
$function$;

create or replace function private.weekly_source_destination_reprice_context_v1(
  p_actor uuid,p_base_request jsonb
) returns jsonb language plpgsql stable security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare
  v_base jsonb; v_rebuilt jsonb; v_source jsonb; v_target jsonb; v_inventory jsonb;
  v_before jsonb; v_component jsonb; v_components jsonb:='[]'::jsonb;
  v_before_root_ordinal integer;
  v_roots uuid[]; v_moved uuid[]; v_head uuid; v_root public.timesheets%rowtype;
  v_contract public.contracts%rowtype; v_detail private.bpay_next_source_chosen_detail%rowtype;
  v_tf public.timesheets_financials%rowtype; v_candidate public.candidates%rowtype; v_client public.clients%rowtype;
  v_stage jsonb; v_schedule jsonb;
  v_e public.weekly_source_row_economic_snapshots%rowtype;
  v_row public.weekly_source_upload_rows%rowtype;
  v_final public.weekly_source_final_revisions%rowtype;
  v_cycle public.weekly_source_cycles%rowtype; v_group public.weekly_source_groups%rowtype;
  v_policy jsonb; v_settings jsonb; v_profile text; v_key text; v_prefix text; v_pay jsonb; v_charge jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),
      nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','')<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  v_base:=private.weekly_source_publication_request_canonical_v1(p_base_request,'IMMEDIATE',null);
  if p_actor is null or v_base#>'{financial_request,contract_choices,1,destination_reprice}' is not null
     or jsonb_array_length(v_base->'member_root_ids')<>2
     or p_base_request#>>'{control,bundle_kind}' is distinct from 'CROSS_CONTRACT_A_B'
     or v_base#>>'{financial_request,source_revision,origin_kind}' is not null then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BASE_INVALID' using errcode='22023'; end if;
  v_roots:=array[(v_base#>>'{member_root_ids,0}')::uuid,(v_base#>>'{member_root_ids,1}')::uuid];
  select array_agg((value#>>'{}')::uuid order by value#>>'{}') into v_moved
    from jsonb_array_elements(p_base_request#>'{control,moved_component_ids}');
  v_source:=v_base#>'{financial_request,member_entitlements,0}';
  v_target:=v_base#>'{financial_request,member_entitlements,1}';
  select * into strict v_root from public.timesheets where timesheet_id=v_roots[2];
  select * into strict v_contract from public.contracts where id=v_root.contract_id;
  -- These are the actual1550 inputs, read under this one STABLE pricing
  -- statement. No invented fallback, rows, rates, clocks or bucket units.
  select * into v_tf from public.timesheets_financials
    where timesheet_id=v_root.timesheet_id and is_current=true;
  select * into strict v_candidate from public.candidates where id=v_contract.candidate_id;
  select * into strict v_client from public.clients where id=v_contract.client_id;
  select jsonb_agg(to_jsonb(r) order by r.rate_family,r.rate_code) into v_schedule
    from private.bpay_next_contract_rate_rows_v1(v_contract.rates_json,v_contract.bucket_labels_json,
      v_contract.additional_rates_json,
      coalesce(v_tf.mileage_pay_rate,v_contract.mileage_pay_rate,v_candidate.mileage_pay_rate),
      coalesce(v_tf.mileage_charge_rate,v_contract.mileage_charge_rate,v_client.mileage_charge_rate)) r;
  v_stage:=jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_STAGE_SNAPSHOT_V1',
    'root_timesheet_id',v_root.timesheet_id,'root_timesheet_version',v_root.version,'root_booking_id',v_root.booking_id,
    'candidate_id',v_contract.candidate_id,'client_id',v_contract.client_id,'contract_id',v_contract.id,
    'financial_snapshot_id',v_tf.id,'destination_pay_channel',v_contract.pay_method_snapshot,
    'metadata',jsonb_build_object('candidate_display_name',coalesce(nullif(btrim(v_candidate.display_name),''),
      nullif(btrim(concat_ws(' ',v_candidate.first_name,v_candidate.last_name)),''),v_candidate.id::text),
      'candidate_reference',v_candidate.tms_ref,'client_display_name',v_client.name,
      'job_title',v_contract.role,'band_label',v_contract.band,'timesheet_reference',v_root.reference_number),
    'metadata_inputs',jsonb_build_object('candidate_display_name',v_candidate.display_name,
      'candidate_first_name',v_candidate.first_name,'candidate_last_name',v_candidate.last_name,
      'candidate_tms_ref',v_candidate.tms_ref,'client_name',v_client.name,'contract_role',v_contract.role,
      'contract_band',v_contract.band,'timesheet_reference',v_root.reference_number),
    'rate_inputs',jsonb_build_object('rates_json',v_contract.rates_json,'bucket_labels_json',v_contract.bucket_labels_json,
      'additional_rates_json',v_contract.additional_rates_json,
      'mileage_pay_rate',coalesce(v_tf.mileage_pay_rate,v_contract.mileage_pay_rate,v_candidate.mileage_pay_rate),
      'mileage_charge_rate',coalesce(v_tf.mileage_charge_rate,v_contract.mileage_charge_rate,v_client.mileage_charge_rate),
      'mileage_fallback_inputs',jsonb_build_object('financial_snapshot_id',v_tf.id,
        'financial_pay_rate',v_tf.mileage_pay_rate,'financial_charge_rate',v_tf.mileage_charge_rate,
        'contract_pay_rate',v_contract.mileage_pay_rate,'contract_charge_rate',v_contract.mileage_charge_rate,
        'candidate_pay_rate',v_candidate.mileage_pay_rate,'client_charge_rate',v_client.mileage_charge_rate)),
    'rate_schedule',v_schedule);
  perform private.weekly_source_destination_stage_snapshot_check_v1(v_stage);
  if v_contract.candidate_id is distinct from (v_base->>'candidate_id')::uuid
     or v_contract.pay_method_snapshot is null
     or v_contract.pay_method_snapshot not in ('PAYE','UMBRELLA') then
    raise exception 'WEEKLY_SOURCE_DESTINATION_RATE_OWNER_INVALID' using errcode='23514'; end if;
  v_rebuilt:=private.weekly_source_entitlement_proposal_cross_contract_request_v1(
    v_roots[1],v_roots[2],(v_base#>>'{financial_request,source_revision,final_revision_id}')::uuid,
    (v_base->>'decision_bundle_id')::uuid,(v_base->>'bundle_revision')::bigint,
    (v_base#>>'{head_ids,0}')::uuid,(v_base#>>'{head_ids,1}')::uuid,(v_base->>'decision_id')::uuid,
    v_moved,v_source->>'authority_kind',v_target->>'authority_kind',
    v_base#>>'{financial_request,contract_choices,0,selection_method}',
    v_base#>>'{financial_request,contract_choices,1,selection_method}',
    case when p_base_request#>'{control,target_root_authorisation}'<>'null'::jsonb then p_actor end,
    case when p_base_request#>'{control,whole_root_office_review}'<>'null'::jsonb then p_actor end,
    (p_base_request#>>'{control,whole_root_office_review,reviewed_at_utc}')::timestamptz);
  if private.weekly_source_publication_request_canonical_v1(v_rebuilt,'IMMEDIATE',null) is distinct from v_base
     or v_rebuilt->'control' is distinct from p_base_request->'control' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BEFORE_CHANGED' using errcode='40001'; end if;
  select * into strict v_final from public.weekly_source_final_revisions
    where id=(v_base#>>'{financial_request,source_revision,final_revision_id}')::uuid and state='CURRENT';
  select * into strict v_cycle from public.weekly_source_cycles where id=v_final.source_cycle_id;
  select * into strict v_group from public.weekly_source_groups where id=v_cycle.source_group_id;
  perform private.weekly_source_office_authority_v1(p_actor,'APPROVE_PROTECTED_PAY',v_group.id,
    v_contract.client_id,v_cycle.finalisation_week_ending);
  perform private.weekly_source_office_authority_v1(p_actor,'APPROVE_PROTECTED_PAY',v_group.id,
    (select c.client_id from public.contracts c join public.timesheets t on t.contract_id=c.id
      where t.timesheet_id=v_roots[1]),v_cycle.finalisation_week_ending);
  -- Same actual pricing statement and SAME rate-row calculator inputs for
  -- every genuine A and own-B component. Neither B work nor money is invented.
  for v_before_root_ordinal in 1..2 loop
  v_inventory:=private.weekly_source_effective_inventory_v1(v_roots[v_before_root_ordinal]);
  if v_inventory->'ok' is distinct from 'true'::jsonb
     or jsonb_typeof(v_inventory->'components') is distinct from 'array' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_BEFORE_INVENTORY_REQUIRED' using errcode='55000';end if;
  if v_before_root_ordinal=2 and jsonb_array_length(v_inventory->'components')=0 then
    continue; -- Only real empty B is blank, not a missing financial snapshot.
  end if;
  v_head:=(v_inventory->>'head_id')::uuid;
  -- V1 positively supports genuine chosen HEAD economics only. Initial TSFIN,
  -- amount-led components and later bucket/policy changes are explicit OPEN
  -- obligations, never implicitly priced with invented hourly equivalence.
  if v_head is null then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_INITIAL_DETAIL_OWNER_REQUIRED' using errcode='55000'; end if;
  for v_before in select value from jsonb_array_elements(v_inventory->'components')
    order by value->>'component_id'
  loop
    v_component:=private.weekly_source_publication_component_canonical_v1(v_before-'component_sha256','destination.before');
    if v_component->>'component_kind' is distinct from 'WORKED_TIME'
       or v_component->'unit_count'<>'null'::jsonb or v_component->'unit_pay_rate'<>'null'::jsonb then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_COMPONENT_POLICY_REQUIRED' using errcode='55000',
        detail=jsonb_build_object('component_id',v_component->>'component_id','component_kind',v_component->>'component_kind')::text;
    end if;
    select * into strict v_detail from private.bpay_next_source_chosen_detail
      where head_id=v_head and component_id=(v_component->>'component_id')::uuid;
    if v_detail.component_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
         private.weekly_source_publication_component_content_v1(v_component))
       or v_detail.detail_sha256 is distinct from sha256(convert_to(v_detail.detail_json::text,'UTF8'))
       or nullif(v_detail.detail_json->>'economic_snapshot_id','') is null then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_ECONOMIC_ORIGIN_REQUIRED' using errcode='23514'; end if;
    select * into strict v_e from public.weekly_source_row_economic_snapshots
      where id=(v_detail.detail_json->>'economic_snapshot_id')::uuid;
    select * into strict v_row from public.weekly_source_upload_rows where id=v_e.upload_row_id;
    select p.profile_code into strict v_profile from public.weekly_source_uploads u
      join public.weekly_source_format_profiles p on p.id=u.source_format_profile_id where u.id=v_row.upload_id;
    if v_e.work_event_id::text is distinct from v_component->>'component_member_identity'
       or v_e.candidate_id is distinct from v_contract.candidate_id
       or v_detail.detail_json->>'work_date' is distinct from v_component->>'work_date'
       or (v_detail.detail_json->>'break_minutes')::integer is distinct from v_e.break_minutes
       or to_char(v_row.start_at_local,'HH24:MI') is distinct from v_detail.detail_json->>'start'
       or to_char(v_row.end_at_local,'HH24:MI') is distinct from v_detail.detail_json->>'end'
       or v_row.work_date::text is distinct from v_component->>'work_date' then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_WORK_FACTS_CHANGED' using errcode='23514'; end if;
    v_policy:=private._weekly_source_effective_policy_v1(v_contract.client_id,v_contract.id,(v_component->>'work_date')::date);
    v_settings:=private._contract_settings_effective_core_v1(v_contract.client_id,v_contract.id,
      (v_component->>'work_date')::date,'IMPORT',null);
    if v_policy->>'weekly_rate_classification_method' is distinct from v_e.rate_method then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BUCKET_POLICY_REVIEW_REQUIRED' using errcode='55000'; end if;
    v_prefix:=case when v_contract.pay_method_snapshot='PAYE' then 'paye_' else 'umb_' end;
    v_pay:='{}'::jsonb; v_charge:='{}'::jsonb;
    foreach v_key in array array['day','night','sat','sun','bh'] loop
      if coalesce(v_contract.rates_json->>(v_prefix||v_key),'')!~'^[+]?[0-9]+([.][0-9]{1,6})?$'
         or coalesce(v_contract.rates_json->>('charge_'||v_key),'')!~'^[+]?[0-9]+([.][0-9]{1,6})?$'
         or (v_contract.rates_json->>(v_prefix||v_key))::numeric<=0
         or (v_contract.rates_json->>('charge_'||v_key))::numeric<=0 then
        raise exception 'WEEKLY_SOURCE_DESTINATION_RATE_AUTHORITY_INCOMPLETE' using errcode='55000'; end if;
      v_pay:=v_pay||jsonb_build_object(v_key,(v_contract.rates_json->>(v_prefix||v_key))::numeric);
      v_charge:=v_charge||jsonb_build_object(v_key,(v_contract.rates_json->>('charge_'||v_key))::numeric);
      if coalesce((v_component->>('hours_'||v_key))::numeric,0) is distinct from
        (to_jsonb(v_e)->>('hours_'||v_key))::numeric then
        raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_BUCKET_FACTS_CHANGED' using errcode='23514'; end if;
    end loop;
    v_components:=v_components||jsonb_build_array(jsonb_build_object(
      'component',v_component,'before_root_ordinal',v_before_root_ordinal,
      'before_root_timesheet_id',v_roots[v_before_root_ordinal],'before_head_id',v_head,
      'before_component_sha256',encode(v_detail.component_sha256,'hex'),
      'before_detail',v_detail.detail_json,'before_detail_sha256',encode(v_detail.detail_sha256,'hex'),
      'original_economic_snapshot_id',v_e.id,'original_calculation_fingerprint',encode(v_e.calculation_fingerprint,'hex'),
      'original_economic',v_e.canonical_result_json,
      'server_row',jsonb_build_object('profile_id',v_profile,'start_at_local',to_char(v_row.start_at_local,'YYYY-MM-DD"T"HH24:MI:SS'),
        'end_at_local',to_char(v_row.end_at_local,'YYYY-MM-DD"T"HH24:MI:SS'),'break_minutes',v_e.break_minutes,
        'actual_net_minutes',v_e.paid_minutes,'source_shift_charge_pence',v_row.source_shift_charge_pence::text),
      'destination_contract',jsonb_build_object('contract_id',v_contract.id,'pay_type',v_contract.pay_method_snapshot,
        'updated_at',v_contract.updated_at,'rates_json',v_contract.rates_json,'additional_rates_json',v_contract.additional_rates_json,
        -- The real owner includes a read-time clock outside its fingerprint.
        -- Retain every authority fact; only that non-economic clock is omitted
        -- so two unchanged reads can share one exact review digest.
        'effective_policy',v_policy,'settings_authority',v_settings-'resolved_at_utc'),
      'destination_pay_rates',v_pay,'destination_charge_rates',v_charge));
  end loop;
  end loop;
  return jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_RATE_CONTEXT_V1',
    'actor_user_id',p_actor,'agency_id',v_group.agency_id,'base_request',p_base_request,
    'before_canonical',v_base,'destination_pay_channel',v_contract.pay_method_snapshot,
    'stage_snapshot',v_stage,'components',v_components);
end;
$function$;

create or replace function private.weekly_source_destination_reprice_quote_v1(
  p_context jsonb,p_calculations jsonb
) returns jsonb language plpgsql immutable
set search_path to 'pg_catalog','private','pg_temp'
as $function$
declare
  v_items jsonb:='[]'::jsonb; v_target jsonb:='[]'::jsonb; v_item jsonb; v_calc jsonb; v_e jsonb;
  v_original jsonb; v_component jsonb; v_after jsonb; v_request jsonb; v_detail jsonb;
  v_key text; v_pay numeric; v_charge numeric; v_sign integer; v_review jsonb; v_count integer;
  v_price jsonb; v_price_expected jsonb; v_source_pence bigint; v_calculated_pence bigint;
  v_difference bigint; v_result text; v_needs_acceptance boolean; v_acceptance text;
begin
  if jsonb_typeof(p_calculations) is distinct from 'array'
     or jsonb_array_length(p_calculations) is distinct from jsonb_array_length(p_context->'components') then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CALCULATION_INCOMPLETE' using errcode='22023'; end if;
  for v_item in select value from jsonb_array_elements(p_context->'components') order by value#>>'{component,component_id}' loop
    select count(*)::integer,jsonb_agg(value)->0 into v_count,v_calc from jsonb_array_elements(p_calculations)
      where value->>'component_id'=v_item#>>'{component,component_id}';
    if v_count<>1 then raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CALCULATION_INCOMPLETE' using errcode='22023'; end if;
    perform private.weekly_source_publication_require_keys_v1(v_calc,array['component_id','economic_snapshot','price_comparison'],'destination.calculation');
    v_e:=v_calc->'economic_snapshot'; v_original:=v_item->'original_economic'; v_component:=v_item->'component';
    perform private.weekly_source_publication_require_keys_v1(v_e,array[
      'schema_version','calculator_version','source_mode','rate_method','sign','paid_minutes','break_minutes',
      'bucket_minutes','hours','pay_rates','charge_rates','total_pay_pence','calculated_charge_pence']
      ||case when v_e ? 'break_allocation' then array['break_allocation'] else array[]::text[] end,'destination.economic_snapshot');
    if v_e->>'schema_version' is distinct from 'WEEKLY_SOURCE_CANONICAL_ECONOMIC_SNAPSHOT_V1'
       or v_e->>'calculator_version' is distinct from 'WEEKLY_SHIFT_FINANCIAL_SEGMENT_V1'
       or v_e->'source_mode' is distinct from v_original->'source_mode'
       or v_e->'rate_method' is distinct from v_original->'rate_method'
       or v_e->'sign' is distinct from v_original->'sign'
       or v_e->'paid_minutes' is distinct from v_original->'paid_minutes'
       or v_e->'break_minutes' is distinct from v_original->'break_minutes'
       or v_e->'bucket_minutes' is distinct from v_original->'bucket_minutes'
       or v_e->'hours' is distinct from v_original->'hours'
       or coalesce(v_e->'break_allocation','null'::jsonb) is distinct from coalesce(v_original->'break_allocation','null'::jsonb)
       or v_e->'pay_rates' is distinct from v_item->'destination_pay_rates'
       or v_e->'charge_rates' is distinct from v_item->'destination_charge_rates'
       or coalesce(v_e->>'total_pay_pence','')!~'^-?[0-9]{1,12}$'
       or coalesce(v_e->>'calculated_charge_pence','')!~'^-?[0-9]{1,12}$' then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_CALCULATION_NOT_GENUINE' using errcode='23514'; end if;
    v_pay:=0; v_charge:=0; v_sign:=(v_original->>'sign')::integer;
    foreach v_key in array array['day','night','sat','sun','bh'] loop
      v_pay:=v_pay+abs((v_original#>>array['hours',v_key])::numeric)*(v_item#>>array['destination_pay_rates',v_key])::numeric;
      v_charge:=v_charge+abs((v_original#>>array['hours',v_key])::numeric)*(v_item#>>array['destination_charge_rates',v_key])::numeric;
    end loop;
    v_pay:=round(v_pay,2)*v_sign; v_charge:=round(v_charge,2)*v_sign;
    if (v_e->>'total_pay_pence')::bigint is distinct from (v_pay*100)::bigint
       or (v_e->>'calculated_charge_pence')::bigint is distinct from (v_charge*100)::bigint then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_TOTAL_NOT_REDERIVED' using errcode='23514'; end if;
    -- Re-derive the existing actual comparator's signed-pence classification.
    -- It is shown and accepted with the whole vector, not silently discarded
    -- when a destination charge differs from immutable source invoice facts.
    v_price:=v_calc->'price_comparison';
    perform private.weekly_source_publication_require_keys_v1(v_price,array['source_mode','result',
      'requires_office_acceptance','acceptance_kind','calculated_comparison_charge_pence',
      'source_validation_charge_pence','invoice_presentation_charge_pence','amount_authority',
      'canonical_pay_pence','signed_difference_pence'],'destination.price_comparison');
    v_calculated_pence:=(v_e->>'calculated_charge_pence')::bigint;
    if v_e->>'source_mode'='NHSP_WEEKLY' then
      if coalesce(v_item#>>'{server_row,source_shift_charge_pence}','')!~'^-?[0-9]{1,12}$' then
        raise exception 'NHSP_SOURCE_CHARGE_INVALID' using errcode='23514'; end if;
      v_source_pence:=(v_item#>>'{server_row,source_shift_charge_pence}')::bigint;
      if v_calculated_pence=0 and v_source_pence<>0 then
        raise exception 'NHSP_CALCULATED_CHARGE_ZERO_INVALID' using errcode='23514'; end if;
      if (v_source_pence>0 and v_calculated_pence<0) or (v_source_pence<0 and v_calculated_pence>0) then
        raise exception 'NHSP_SOURCE_CHARGE_SIGN_INVALID' using errcode='23514'; end if;
      v_difference:=v_source_pence-v_calculated_pence;
      v_result:=case when v_source_pence<>0 and v_calculated_pence<>0 and v_difference=0 then 'EXACT'
        when v_source_pence<>0 and v_calculated_pence<>0 and abs(v_difference)=1 then 'SOURCE_ROUNDING_EQUIVALENT'
        when v_source_pence=0 and v_calculated_pence<>0 then 'ZERO_SOURCE_CHARGE' else 'MISMATCH' end;
      v_needs_acceptance:=v_result in ('MISMATCH','ZERO_SOURCE_CHARGE');
      v_acceptance:=case when v_result='ZERO_SOURCE_CHARGE' then 'ACCEPTED_ZERO'
        when v_result='MISMATCH' then 'ACCEPTED_DISPARITY' end;
      v_price_expected:=jsonb_build_object('source_mode','NHSP_WEEKLY','result',v_result,
        'requires_office_acceptance',v_needs_acceptance,'acceptance_kind',v_acceptance,
        'calculated_comparison_charge_pence',v_calculated_pence::text,'source_validation_charge_pence',v_source_pence::text,
        'invoice_presentation_charge_pence',v_source_pence::text,'amount_authority','VALIDATED_SOURCE_PENCE',
        'canonical_pay_pence',v_e->>'total_pay_pence','signed_difference_pence',v_difference::text);
    else
      v_price_expected:=jsonb_build_object('source_mode','HEALTHROSTER_WEEKLY','result','NOT_APPLICABLE',
        'requires_office_acceptance',false,'acceptance_kind',null,
        'calculated_comparison_charge_pence',v_calculated_pence::text,'source_validation_charge_pence',null,
        'invoice_presentation_charge_pence',v_calculated_pence::text,'amount_authority','CLOUDTMS_CALCULATION',
        'canonical_pay_pence',v_e->>'total_pay_pence','signed_difference_pence',null);
    end if;
    if v_price is distinct from v_price_expected then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_PRICE_COMPARISON_NOT_REDERIVED' using errcode='23514'; end if;
    -- Stable work identity, quantity, exclusions and original charge remain
    -- exact. Destination charge calculation is informational, never invoice
    -- or Source billing-movement authority.
    v_after:=v_component||jsonb_build_object('pay_ex_vat',v_pay::numeric(12,2)::text);
    v_detail:=v_item->'before_detail'||jsonb_build_object('rates',v_item->'destination_pay_rates',
      'source_component_sha256',encode(private.weekly_source_publication_request_digest_v1(
        private.weekly_source_publication_component_content_v1(v_after)),'hex'),
      'destination_reprice',jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_V1',
        'destination_contract_id',v_item#>>'{destination_contract,contract_id}',
        'destination_pay_channel',p_context->>'destination_pay_channel',
        'original_economic_snapshot_id',v_item->>'original_economic_snapshot_id',
        'before_component_sha256',v_item->>'before_component_sha256',
        'before_detail_sha256',v_item->>'before_detail_sha256'));
    if octet_length(v_detail::text)>4096 then
      raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_DETAIL_LIMIT' using errcode='22023'; end if;
    v_items:=v_items||jsonb_build_array(jsonb_build_object('component_id',v_component->>'component_id',
      'before_component',v_component,'after_content',private.weekly_source_publication_component_content_v1(v_after),
      'detail',v_detail,'economic_snapshot',v_e,'price_comparison',v_price_expected)
      -- Old frozen Source certificates retain their byte-exact quote shape.
      ||case when v_item ? 'before_root_ordinal' then jsonb_build_object(
        'before_root_ordinal',v_item->'before_root_ordinal',
        'before_root_timesheet_id',v_item->'before_root_timesheet_id','before_head_id',v_item->'before_head_id',
        'before_component_sha256',v_item->'before_component_sha256')
        else '{}'::jsonb end);
  end loop;
  v_request:=p_context->'base_request';
  for v_component in select value from jsonb_array_elements(v_request#>'{financial_request,member_entitlements,1,components}')
    order by (value->>'component_ordinal')::integer loop
    select value into v_item from jsonb_array_elements(v_items) where value->>'component_id'=v_component->>'component_id';
    v_target:=v_target||jsonb_build_array(case when v_item is null then v_component else
      v_component||jsonb_build_object('pay_ex_vat',v_item#>'{after_content,pay_ex_vat}') end);
  end loop;
  v_request:=jsonb_set(v_request,'{financial_request,member_entitlements,1,components}',v_target);
  v_review:=jsonb_build_object('schema_version','WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_V1',
    'context',p_context,'calculated_components',v_items,'complete_destination_components',v_target);
  return jsonb_build_object('review',v_review,'review_sha256',encode(private.weekly_source_sha256_jsonb_v1(
    'WEEKLY_SOURCE_DESTINATION_REPRICE_REVIEW_V1',v_review),'hex'),'request',v_request,'components',v_items);
end;
$function$;

create or replace function private.weekly_source_destination_reprice_detail_v1(
  p_bundle uuid,p_revision bigint,p_component jsonb,p_origin integer
) returns jsonb language plpgsql volatile security definer
set search_path to 'public','private','pg_catalog','pg_temp'
as $function$
declare v_saved private.weekly_source_destination_reprice_witness_v1%rowtype; v_item jsonb;
begin
  select * into v_saved from private.weekly_source_destination_reprice_witness_v1
    where decision_bundle_id=p_bundle and bundle_revision=p_revision;
  if not found then return null; end if;
  select value into v_item from jsonb_array_elements(v_saved.economic_snapshots_json)
    where value->>'component_id'=p_component->>'component_id';
  if v_item is null then return null; end if;
  if p_origin not in (1,2) or p_origin is distinct from
       coalesce((v_item->>'before_root_ordinal')::integer,1)
     or (v_item ? 'before_root_ordinal' and (
       v_item->>'before_root_timesheet_id' is distinct from
         v_saved.accepted_request_json#>>array['member_root_ids',(p_origin-1)::text]
       or not exists(select 1 from public.weekly_source_entitlement_head_components oldc
         where oldc.head_id=(v_item->>'before_head_id')::uuid
           and oldc.component_id=(p_component->>'component_id')::uuid
           and encode(oldc.component_sha256,'hex')=v_item->>'before_component_sha256')))
     or not exists(select 1 from public.weekly_source_entitlement_head_components c
      where c.head_id=(v_saved.accepted_request_json#>>'{head_ids,1}')::uuid
        and c.component_id=(p_component->>'component_id')::uuid)
     or private.weekly_source_publication_component_content_v1(p_component) is distinct from v_item->'after_content' then
    raise exception 'WEEKLY_SOURCE_DESTINATION_REPRICE_DETAIL_NOT_EXACT' using errcode='23514'; end if;
  perform private.weekly_source_destination_reprice_verify_v1(
    private.weekly_source_publication_request_canonical_v1(v_saved.accepted_request_json,'IMMEDIATE',null),
    v_saved.accepted_request_json->'control');
  return jsonb_set(v_item->'detail','{destination_reprice}',(v_item#>'{detail,destination_reprice}')||
    jsonb_build_object('witness_id',v_saved.id,'review_sha256',encode(v_saved.review_sha256,'hex')));
end;
$function$;


