-- E-only qualified Source collection owner helper. No installation/native proof.


create or replace function private.bpay_next_work_collection_source_original_v2(p_basis private.bpay_next_work_collection)
returns boolean language sql stable security invoker set search_path=pg_catalog,private as $function$
 select exists(
  select 1 from private.bpay_next_financial_effect e
  join private.bpay_next_run_line l on l.id=(p_basis).original_run_line_id
  join private.bpay_next_run_worker candidate_worker on candidate_worker.id=l.run_worker_id
    and candidate_worker.candidate_id=(p_basis).candidate_id
  join private.bpay_next_hold h on h.id=e.operation_item_id and h.run_line_id=l.id and h.status='REALISED'
  join private.bpay_next_work w on w.id=(p_basis).work_id and w.candidate_id=(p_basis).candidate_id and w.work_kind='SOURCE'
  join private.bpay_next_work_revision r on r.id=(p_basis).original_revision_id and r.work_id=w.id and r.sealed_at_utc is not null
  join private.bpay_next_approved_line a on a.id=(p_basis).original_approved_line_id and a.revision_id=r.id
  join private.bpay_next_source_component_binding_version v on v.id=l.source_binding_version_id
  join private.bpay_next_transfer t on t.id=(p_basis).original_transfer_id and t.candidate_id=(p_basis).candidate_id
  join private.bpay_next_transfer_member m on m.transfer_id=t.id and m.run_line_id=l.id and m.subject_kind='WORK'
  join private.bpay_next_position p on p.work_id=w.id and p.component_key=(p_basis).component_key
  where e.id=(p_basis).original_effect_id and e.effect_kind='PAYROLL_SETTLED' and e.source_disposition_ex_vat>0
    and (e.work_id,e.component_key,e.candidate_id,e.original_transfer_id)
      =((p_basis).work_id,(p_basis).component_key,(p_basis).candidate_id,(p_basis).original_transfer_id)
    and (l.work_id,l.component_key,l.captured_revision_id,l.approved_line_id,l.source_pay_channel,l.valuation_policy_id)
      =((p_basis).work_id,(p_basis).component_key,(p_basis).original_revision_id,(p_basis).original_approved_line_id,
        (p_basis).original_source_pay_channel,(p_basis).original_valuation_policy_id)
    and l.source_pay_channel in ('PAYE','UMBRELLA') and l.target_pay_channel in ('PAYE','UMBRELLA')
    and (e.source_disposition_ex_vat,e.target_amount_ex_vat,e.target_amount_vat,e.target_amount_inc_vat)
      =(l.source_consumed_ex_vat,l.frozen_ex_vat,l.frozen_vat,l.frozen_inc_vat)
    and h.source_reserved_ex_vat=l.source_consumed_ex_vat and m.signed_cash_contribution=l.frozen_inc_vat
    and t.original_transfer_id is null and t.return_cash_id is null
    and (t.status in ('SETTLED','RETURNED') or (t.execution_kind='INTERNAL_ZERO' and t.status='INTERNAL_PROCESSING'))
    and a.component_kind='WORK' and a.tax_treatment='TAXABLE' and a.source_component_id is not null
    and a.source_component_id=v.source_component_id and a.component_key=(p_basis).component_key
    and (p_basis).component_key='SOURCE:'||a.source_component_id::text and (p_basis).original_tax_treatment='TAXABLE'
    and (v.approval_work_id,v.approval_revision_id,v.approved_line_id,v.candidate_id,
      v.canonical_work_id,v.canonical_component_key)
      =(l.work_id,l.captured_revision_id,l.approved_line_id,candidate_worker.candidate_id,(p_basis).work_id,(p_basis).component_key)
    and (e.source_run_line_id,e.source_binding_version_id,e.canonical_source_work_id,e.canonical_source_component_key,e.native_source_channel)
      =(l.id,v.id,(p_basis).work_id,(p_basis).component_key,l.source_pay_channel)
    -- Paid origin is this genuine actual operation, NOT the book's immutable
    -- approval seed: a normal ZERO-seeded book has no paid seed effect.
    and p.source_book_state='READY'
    and ((r.source_kind='SOURCE' and r.source_event_id is not null and (r.source_head_id is null or r.source_event_id=r.source_head_id))
      or (r.source_kind='PROTECTED' and r.source_head_id is not null and r.source_event_id=r.source_head_id))
 )
$function$;
alter function private.bpay_next_work_collection_source_original_v2(private.bpay_next_work_collection) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_work_collection_source_original_v2(private.bpay_next_work_collection) from public,anon,authenticated,service_role;
-- Genuine current-comparison owner. Called only from existing 1519 leased owner.
create or replace function private.bpay_next_reconcile_source_comparison_collection_v2(
 p_job_id uuid,p_canonical_work_id uuid,p_component_key text,p_effect_id uuid default null)
returns void language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare j private.bpay_next_job%rowtype;wc private.bpay_next_worker_control%rowtype;
 p private.bpay_next_position%rowtype;r private.bpay_next_source_comparison_receipt%rowtype;
 b private.bpay_next_work_collection%rowtype;v private.bpay_next_source_component_binding_version%rowtype;
 c private.bpay_next_finance_case%rowtype;x private.bpay_next_case_component%rowtype;
 principal numeric;delta numeric;ev text;s numeric;o numeric;actual jsonb;
begin
 select * into strict j from private.bpay_next_job where id=p_job_id;
 select * into strict wc from private.bpay_next_worker_control where candidate_id=j.candidate_id for update;
 perform 1 from private.bpay_next_work where id=p_canonical_work_id and candidate_id=j.candidate_id for update;
 select * into strict p from private.bpay_next_position where work_id=p_canonical_work_id and component_key=p_component_key for update;
 select * into strict r from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
 if j.status<>'LEASED' or j.owner_epoch<>wc.active_owner_epoch or j.lease_until_utc<=clock_timestamp()
   or not exists(select 1 from private.bpay_next_module_control m where m.id=1 and m.active_owner='NEXT' and m.owner_epoch=j.module_epoch)
   or exists(select 1 from private.bpay_next_job prior where prior.candidate_id=j.candidate_id and prior.command_sequence<j.command_sequence and prior.status<>'DONE')
   or r.candidate_id<>j.candidate_id or not private.bpay_next_source_comparison_book_certified_v2(p) then
  raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_OWNER_STALE' using errcode='55000';end if;
 if r.receipt_kind='CASE_RECONCILE' and r.operation_job_id=j.id and
   ((j.job_kind='POSITION_APPLY' and p_effect_id is null and j.phase in ('NEW','REMOVED')) or
    (j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') and j.phase='MEMBERS' and p_effect_id is not null
      and exists(select 1 from private.bpay_next_source_comparison_receipt actual_operation
        where actual_operation.id=r.previous_comparison_id and actual_operation.operation_effect_id=p_effect_id
          and actual_operation.operation_job_id=j.id and actual_operation.receipt_kind in ('SETTLE','CASE_RECOVERY')))) then
  return;
 end if;
 if j.job_kind='POSITION_APPLY' then
  if p_effect_id is not null or j.phase not in ('NEW','REMOVED') or not exists(
    select 1 from private.bpay_next_publication publication where publication.command_id=j.command_id
      and publication.candidate_id=j.candidate_id and publication.work_id=p_canonical_work_id
      and publication.revision_id=p.applied_revision_id and publication.status in ('QUEUED','APPLYING')) then
    raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_PUBLICATION_SCOPE_INVALID';end if;
 elsif j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') then
  if p_effect_id is null or j.phase<>'MEMBERS' or r.operation_job_id is distinct from j.id or r.operation_effect_id is distinct from p_effect_id
    or r.receipt_kind not in ('SETTLE','CASE_RECOVERY') then raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_EFFECT_SCOPE_INVALID';end if;
 elsif j.job_kind in ('SIMPLE_CANCEL','PREPARATION_EXPIRY') then
  -- Exact hold carry has already certified the physical release. No hold/history scan.
  if p_effect_id is not null or j.phase<>'RELEASE' or r.receipt_kind<>'CASE_RELEASE'
    or r.operation_job_id is distinct from j.id or r.operation_case_hold_id is null
    or r.review_issue_code is distinct from 'CASE_RECONCILIATION_REQUIRED' then
    raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CASE_CAPACITY_SCOPE_INVALID';end if;
  perform private.bpay_next_source_comparison_case_capacity_proof_v2(
    (select input from private.bpay_next_source_comparison_receipt input where input.id=r.previous_comparison_id),
    j.id,r.operation_case_hold_id,'CASE_RELEASE');
 else raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_JOB_KIND_INVALID';
 end if;
 if r.comparable_paid_ex_vat is null or r.comparable_held_ex_vat is null then
  -- Truthful actual native posting remains recorded; missing comparison authority
  -- cannot be made READY by a collection calculation.
  return;
 end if;
 if not (r.qualification_state in ('READY','PENDING') or r.review_issue_code='CASE_RECONCILIATION_REQUIRED') then
  raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CURRENT_REVIEW_REQUIRED' using errcode='55000';end if;
 select * into strict v from private.bpay_next_source_component_binding_version where id=r.source_binding_version_id;
 if not exists(select 1 from private.bpay_next_source_component_binding current where current.current_binding_version_id=v.id
   and current.canonical_work_id=p.work_id and current.canonical_component_key=p.component_key)
   or (v.approval_work_id,v.approval_revision_id,v.approval_component_key,v.approved_line_id,v.candidate_id)
     is distinct from (r.approval_work_id,r.approval_revision_id,r.approval_component_key,r.approved_line_id,r.candidate_id)
   or not ((v.origin_kind='COMMON_HEAD_RECEIPT_V1' and exists(select 1 from public.weekly_source_entitlement_heads h
     join public.weekly_source_entitlement_decision_bundles bundle on bundle.decision_bundle_id=h.decision_bundle_id and bundle.bundle_revision=h.bundle_revision
     join public.weekly_source_root_authorisations auth on auth.current_entitlement_head_id=h.id and auth.root_timesheet_id=h.root_timesheet_id
     where h.id=v.head_id and h.state='COMMITTED_CURRENT' and bundle.state='COMMITTED' and auth.withdrawn_at_utc is null))
     or (v.origin_kind='INITIAL_AUTHORISED_TSFIN_V1' and exists(
       select 1 from private.bpay_next_bound_source_snapshot_v1(v.id,p.source_book_revision) initial
       where initial.qualification_state='READY' and
         (initial.candidate_id,initial.canonical_work_id,initial.canonical_component_key,initial.binding_version_id,
           initial.approval_work_id,initial.approval_revision_id,initial.approved_line_id)
         =(v.candidate_id,v.canonical_work_id,v.canonical_component_key,v.id,v.approval_work_id,v.approval_revision_id,v.approved_line_id)))) then
   raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_SOURCE_AUTHORITY_INVALID';end if;
 select * into b from private.bpay_next_work_collection where work_id=p.work_id and component_key=p.component_key for update;
 if not found or not b.paid_basis_qualified or not private.bpay_next_work_collection_source_original_v2(b) then
   raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_ORIGINAL_ORIGIN_REVIEW_REQUIRED' using errcode='55000';end if;
 actual:=private.bpay_next_source_comparison_case_basis_v2(p.work_id,p.component_key,true);
 if r.case_basis is distinct from actual then raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CASE_BASIS_CHANGED';end if;
 if b.case_id is null then
   principal:=greatest(r.comparable_paid_ex_vat-r.approved_source_ex_vat,0);
   if principal>0 then
     insert into private.bpay_next_finance_case(id,candidate_id,case_kind,tax_treatment,status,principal_approved,order_key,case_revision)
       values(b.id,j.candidate_id,'OVERPAYMENT','TAXABLE','OPEN',principal,j.command_sequence,1);
     insert into private.bpay_next_case_rule(id,case_id,candidate_id,rule_revision,case_kind,case_subtype,tax_treatment,case_created_at_utc)
       values(b.id,b.id,j.candidate_id,1,'OVERPAYMENT','OVERPAYMENT','TAXABLE',transaction_timestamp());
     update private.bpay_next_finance_case set current_rule_id=b.id,current_rule_revision=1 where id=b.id;
     insert into private.bpay_next_case_component(id,case_id,candidate_id,component_key,component_ordinal,component_revision,rule_id,
       case_kind,case_subtype,tax_treatment,instruction_kind,direction,payroll_stage,source_pay_channel,currency,approved_source_ex_vat,resolution_state)
       values(b.id,b.id,j.candidate_id,'RECOVERY',1,1,b.id,'OVERPAYMENT','OVERPAYMENT','TAXABLE','RECOVERY','DEDUCTION',
         'GROSS_DEDUCT',r.target_pay_channel,'GBP',principal,'REVIEW');
     b.case_id:=b.id;b.case_component_id:=b.id;delta:=principal;ev:='APPROVED';
   end if;
 else
   select * into strict c from private.bpay_next_finance_case where id=b.case_id for update;
   select * into strict x from private.bpay_next_case_component where id=b.case_component_id for update;
   if (c.principal_approved,c.principal_recovered,c.principal_written_off,c.active_recovery_hold_amount)
     is distinct from (x.approved_source_ex_vat,x.recovered_source_ex_vat,x.written_off_source_ex_vat,x.active_recovery_source_ex_vat) then
     raise exception 'BPAY_NEXT_WORK_COLLECTION_BALANCE_MISMATCH';end if;
   o:=greatest(r.comparable_paid_ex_vat-r.approved_source_ex_vat-(r.case_resolution->>'target_written_off_ex_vat')::numeric,
     (r.case_resolution->>'target_active_capacity_ex_vat')::numeric,0);
   if x.source_pay_channel=r.target_pay_channel then s:=o;
   else
     s:=(r.case_resolution->>'source_outstanding_ex_vat')::numeric;
     if s is null or (r.case_resolution->>'target_outstanding_ex_vat')::numeric is distinct from o then
       raise exception 'BPAY_NEXT_COMPARISON_CASE_SELECTED_REMAINDER_REVIEW_REQUIRED' using errcode='55000';end if;
   end if;
   principal:=c.principal_recovered+c.principal_written_off+greatest(s,c.active_recovery_hold_amount);
   delta:=principal-c.principal_approved;
   if delta<>0 then
     update private.bpay_next_finance_case set principal_approved=principal,
       status=case when principal=principal_recovered+principal_written_off then 'CLOSED' when status='PAUSED' then 'PAUSED' else 'OPEN' end,
       case_revision=case_revision+1,updated_at_utc=transaction_timestamp() where id=c.id;
     update private.bpay_next_case_component set approved_source_ex_vat=principal,component_revision=component_revision+1,
       resolution_state='REVIEW',target_pay_channel=null,target_ex_vat=null,target_vat=null,target_inc_vat=null,
       valuation_policy_id=null,valuation_window_id=null,resolution_ref=null,updated_at_utc=transaction_timestamp() where id=x.id;
     ev:='CORRECTED';
   elsif principal=c.principal_recovered+c.principal_written_off and c.status<>'CLOSED' then
     update private.bpay_next_finance_case set status='CLOSED',case_revision=case_revision+1,updated_at_utc=transaction_timestamp() where id=c.id;
   end if;
 end if;
 if ev is not null then
   insert into private.bpay_next_case_event(case_id,operation_id,operation_item_id,event_kind,approved_delta,original_transfer_id,original_effect_id)
     values(b.case_id,j.command_id,b.id,ev,delta,b.original_transfer_id,b.original_effect_id);
 end if;
 update private.bpay_next_work_collection set case_id=b.case_id,case_component_id=b.case_component_id,qualification_state='READY',
   observed_revision_id=p.applied_revision_id,observed_approved_source_ex_vat=p.approved_source_ex_vat,
   observed_realised_source_ex_vat=p.realised_source_ex_vat,reconcile_revision=reconcile_revision+1,last_job_id=j.id,last_effect_id=p_effect_id,
   updated_at_utc=transaction_timestamp() where id=b.id;
 if b.case_id is not null then
   perform private.bpay_next_source_comparison_case_reconcile_v2(j.id,p.source_book_revision,r.id,b.id);
 end if;
end $function$;
alter function private.bpay_next_reconcile_source_comparison_collection_v2(uuid,uuid,text,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_reconcile_source_comparison_collection_v2(uuid,uuid,text,uuid) from public,anon,authenticated,service_role;
-- Real0460/0510 callers preserve the ONE actual released hold UUID.
create or replace function private.bpay_next_reconcile_source_comparison_case_release_v2(p_job_id uuid,p_case_hold_id uuid)
returns void language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare b private.bpay_next_work_collection%rowtype;p private.bpay_next_position%rowtype;
 r private.bpay_next_source_comparison_receipt%rowtype;prior private.bpay_next_source_comparison_receipt%rowtype;result jsonb;
begin
 select b0.* into strict b from private.bpay_next_case_hold hold
   join private.bpay_next_run_case_instruction instruction on instruction.id=hold.instruction_id
   join private.bpay_next_work_collection b0 on b0.id=instruction.work_collection_id
     and (b0.case_id,b0.case_component_id,b0.candidate_id)=(hold.case_id,hold.case_component_id,hold.candidate_id)
   where hold.id=p_case_hold_id and hold.status='RELEASED';
 perform 1 from private.bpay_next_worker_control where candidate_id=b.candidate_id for update;
 perform 1 from private.bpay_next_work where id=b.work_id and candidate_id=b.candidate_id for update;
 select * into strict p from private.bpay_next_position where work_id=b.work_id and component_key=b.component_key for update;
 select * into strict r from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
 if not private.bpay_next_source_comparison_book_certified_v2(p) then
   raise exception 'BPAY_NEXT_COMPARISON_CASE_RELEASE_BOOK_STALE';end if;
 -- Exact same-operation replay is a fixed point, not another capacity decrement.
 if r.receipt_kind='CASE_RECONCILE' and r.operation_job_id=p_job_id then
   select * into strict prior from private.bpay_next_source_comparison_receipt where id=r.previous_comparison_id;
   if prior.receipt_kind='CASE_RELEASE' and prior.operation_job_id=p_job_id and prior.operation_case_hold_id=p_case_hold_id then return;end if;
 end if;
 if not (r.receipt_kind='CASE_RELEASE' and r.operation_job_id=p_job_id and r.operation_case_hold_id=p_case_hold_id) then
   result:=private.bpay_next_source_comparison_case_capacity_carry_v2(
     p_job_id,p.source_book_revision,r.id,p_case_hold_id,'CASE_RELEASE');
   select * into strict r from private.bpay_next_source_comparison_receipt where id=(result->>'comparison_id')::uuid;
 end if;
 -- Missing/inexact q is truthful REVIEW, not rollback of release or invented S.
 if r.review_issue_code='CASE_RECONCILIATION_REQUIRED' then
   perform private.bpay_next_reconcile_source_comparison_collection_v2(p_job_id,b.work_id,b.component_key,null);
 end if;
end $function$;
alter function private.bpay_next_reconcile_source_comparison_case_release_v2(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_reconcile_source_comparison_case_release_v2(uuid,uuid) from public,anon,authenticated,service_role;


-- Unadopted E-only integration. Requires the full V2 comparison owner.
-- Point reads of actual immutable children; no financial-history aggregation.


create or replace function private.bpay_next_source_comparison_carry_known_work_v2(
  p_job_id uuid,p_run_line_id uuid,p_operation_kind text,p_operation_id uuid
) returns boolean language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare p private.bpay_next_position%rowtype;
begin
  if p_operation_kind not in ('SETTLE','RELEASE') or p_job_id is null
    or p_run_line_id is null or p_operation_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_COMPARISON_KNOWN_WORK_INPUT_INVALID';
  end if;
  select cp.* into p from private.bpay_next_run_line l
    join private.bpay_next_run_worker candidate_worker on candidate_worker.id=l.run_worker_id
    join private.bpay_next_source_component_binding b on b.candidate_id=candidate_worker.candidate_id
      and ((l.source_binding_version_id is not null
        and (b.canonical_work_id,b.canonical_component_key)
          =(l.canonical_source_work_id,l.canonical_source_component_key))
        or (l.source_binding_version_id is null
          and (b.canonical_work_id,b.canonical_component_key)=(l.work_id,l.component_key)))
    join private.bpay_next_position cp
      on (cp.work_id,cp.component_key)=(b.canonical_work_id,b.canonical_component_key)
    where l.id=p_run_line_id;
  -- Existing ordinary and pre-comparison Source lanes retain their owner.
  if not found or p.source_comparison_receipt_id is null then return false;end if;
  if not ((p_operation_kind='SETTLE' and exists(
      select 1 from private.bpay_next_financial_effect e
        join private.bpay_next_hold h on h.id=e.operation_item_id
        where e.id=p_operation_id and h.run_line_id=p_run_line_id))
    or (p_operation_kind='RELEASE' and exists(
      select 1 from private.bpay_next_hold h
        where h.id=p_operation_id and h.run_line_id=p_run_line_id))) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_KNOWN_WORK_OPERATION_MISMATCH';
  end if;
  -- The real operation owner validates lease, actual state, frozen amounts,
  -- canonical identity and replay; it alone writes local scalar + native book.
  perform private.bpay_next_source_comparison_carry_v2(
    p_job_id,p.source_book_revision,p.source_comparison_receipt_id,
    p_operation_kind,p_operation_id);
  return true;
end $function$;
alter function private.bpay_next_source_comparison_carry_known_work_v2(uuid,uuid,text,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_carry_known_work_v2(uuid,uuid,text,uuid)
  from public,anon,authenticated,service_role;


-- E-only: actual approval/current-book point qualification, no history fallback.


create or replace function private.bpay_next_source_comparison_select_approval_v2(
  p_candidate_id uuid,p_source_component_id uuid,p_work_id uuid,p_revision_id uuid,p_approved_line_id uuid
) returns private.bpay_next_source_comparison_receipt
language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare r private.bpay_next_source_comparison_receipt%rowtype;
  p private.bpay_next_position%rowtype;v private.bpay_next_source_component_binding_version%rowtype;
begin
  if p_candidate_id is null or p_source_component_id is null or p_work_id is null or p_revision_id is null then
    raise exception using errcode='22023',message='BPAY_NEXT_COMPARISON_SELECT_INPUT_INVALID';end if;
  select cp.* into p from private.bpay_next_source_component_binding b
    join private.bpay_next_source_component_binding_version bv on bv.id=b.current_binding_version_id
    join private.bpay_next_position cp
      on (cp.work_id,cp.component_key)=(b.canonical_work_id,b.canonical_component_key)
    where b.candidate_id=p_candidate_id and b.source_component_id=p_source_component_id;
  if not found or p.source_comparison_receipt_id is null then return null;end if;
  select * into strict r from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
  select * into strict v from private.bpay_next_source_component_binding_version where id=r.source_binding_version_id;
  if (r.candidate_id,r.approval_work_id,r.approval_revision_id,r.approved_line_id)
    is distinct from (p_candidate_id,p_work_id,p_revision_id,p_approved_line_id) then
    raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_SELECT_APPROVAL_MOVED_OR_CHANGED';end if;
  -- Existing bound owner certifies current Source receipt/HEAD, both real
  -- publication members and actual APPLIED/DONE before new preparation.
  return private.bpay_next_source_comparison_current_v2(v.id,p.source_book_revision,r.id);
end $function$;
alter function private.bpay_next_source_comparison_select_approval_v2(uuid,uuid,uuid,uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_select_approval_v2(uuid,uuid,uuid,uuid,uuid)
  from public,anon,authenticated,service_role;

-- A moved original is historical native-book authority, not a second payable
-- approval. ALL membership omits it only after certifying the real current
-- destination; an explicitly selected stale component must instead be REVIEW.
create or replace function private.bpay_next_source_comparison_retired_approval_v2(
  p_candidate_id uuid,p_work_id uuid,p_component_key text
) returns boolean language plpgsql stable security invoker
set search_path=pg_catalog,private
as $function$
declare p private.bpay_next_position%rowtype;
  v private.bpay_next_source_component_binding_version%rowtype;
  r private.bpay_next_source_comparison_receipt%rowtype;
begin
  if p_candidate_id is null or p_work_id is null or p_component_key is null then
    raise exception using errcode='22023',message='BPAY_NEXT_COMPARISON_RETIRED_INPUT_INVALID';end if;
  select bv.* into v from private.bpay_next_source_component_binding b
    join private.bpay_next_source_component_binding_version bv on bv.id=b.current_binding_version_id
    where b.candidate_id=p_candidate_id and b.canonical_work_id=p_work_id
      and b.canonical_component_key=p_component_key;
  if not found or (v.approval_work_id,v.approval_component_key)=(p_work_id,p_component_key) then
    return false;end if;
  select * into strict p from private.bpay_next_position
    where work_id=p_work_id and component_key=p_component_key;
  if p.source_comparison_receipt_id is null then return false;end if;
  r:=private.bpay_next_source_comparison_current_v2(v.id,p.source_book_revision,p.source_comparison_receipt_id);
  if (r.candidate_id,r.canonical_work_id,r.canonical_component_key,
      r.approval_work_id,r.approval_component_key)
    is distinct from (p_candidate_id,p_work_id,p_component_key,v.approval_work_id,v.approval_component_key) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_RETIRED_BINDING_MISMATCH';end if;
  return true;
end $function$;
alter function private.bpay_next_source_comparison_retired_approval_v2(uuid,uuid,text) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_retired_approval_v2(uuid,uuid,text)
  from public,anon,authenticated,service_role;


-- E-only same-family real W operation. Requires replacement 0156 + core V2 + Case owner 0215.
-- No native cash/scalar/book delta, ratio/inverse, history sweep or new balance table.



-- Writeoff eligibility is the real Case/original paid origin, not payability READY.
-- Preparation still uses the strict existing current/collection_origin owner.
create or replace function private.bpay_next_source_comparison_writeoff_origin_v2(
 p_case_id uuid,p_component_id uuid,p_candidate_id uuid)
returns private.bpay_next_work_collection language plpgsql stable security invoker set search_path=pg_catalog,private as $function$
declare b private.bpay_next_work_collection%rowtype;p private.bpay_next_position%rowtype;
 r private.bpay_next_source_comparison_receipt%rowtype;
begin
 select x.* into b from private.bpay_next_work_collection x where x.case_id=p_case_id and x.case_component_id=p_component_id
   and x.candidate_id=p_candidate_id;
 if not found then return b;end if;
 select * into strict p from private.bpay_next_position where work_id=b.work_id and component_key=b.component_key;
 if p.source_comparison_receipt_id is null then
   return private.bpay_next_work_collection_origin_v1(p_case_id,p_component_id,p_candidate_id);
 end if;
 select * into strict r from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
 if not private.bpay_next_source_comparison_book_certified_v2(p)
   or (r.candidate_id,r.canonical_work_id,r.canonical_component_key) is distinct from (p_candidate_id,b.work_id,b.component_key)
   or not b.paid_basis_qualified or b.qualification_state<>'READY' or b.original_tax_treatment<>'TAXABLE'
   or (b.observed_revision_id,b.observed_approved_source_ex_vat,b.observed_realised_source_ex_vat)
     is distinct from (p.applied_revision_id,p.approved_source_ex_vat,p.realised_source_ex_vat)
   or not private.bpay_next_work_collection_source_original_v2(b)
   or not exists(select 1 from private.bpay_next_finance_case c join private.bpay_next_case_component x
     on x.id=b.case_component_id and x.case_id=c.id and x.candidate_id=c.candidate_id
     join private.bpay_next_case_rule rule on rule.id=x.rule_id and rule.case_id=c.id and rule.candidate_id=c.candidate_id
     where c.id=b.case_id and c.id=b.id and x.id=b.id and c.candidate_id=b.candidate_id
       and c.case_kind='OVERPAYMENT' and c.tax_treatment='TAXABLE' and c.principal_funded=0
       and x.case_kind='OVERPAYMENT' and x.case_subtype='OVERPAYMENT' and x.tax_treatment='TAXABLE'
       and x.instruction_kind='RECOVERY' and x.direction='DEDUCTION' and x.payroll_stage='GROSS_DEDUCT'
       and x.component_key='RECOVERY' and x.component_ordinal=1 and x.source_pay_channel in ('PAYE','UMBRELLA')
       and c.current_rule_id=rule.id and c.current_rule_revision=rule.rule_revision and rule.id=b.id
       and rule.weekly_due_source_ex_vat is null
       and (c.principal_approved,c.principal_recovered,c.principal_written_off,c.active_recovery_hold_amount)
         =(x.approved_source_ex_vat,x.recovered_source_ex_vat,x.written_off_source_ex_vat,x.active_recovery_source_ex_vat)) then
   raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_ORIGIN_INVALID' using errcode='23514';
 end if;
 return b;
end $function$;

-- Point known request/event/Case tuple. Called after real request WRITTEN_OFF result,
-- while the exact CASE_WRITE_OFF NEW lease is still live, before command/job terminal.
create or replace function private.bpay_next_source_comparison_writeoff_proof_v2(
 p_input private.bpay_next_source_comparison_receipt,p_job_id uuid,p_event_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare j private.bpay_next_job%rowtype;req private.bpay_next_write_off_request%rowtype;
 ev private.bpay_next_case_event%rowtype;b private.bpay_next_work_collection%rowtype;
 actual jsonb;expected jsonb;resolution jsonb;oldcase jsonb;quote jsonb;wquote jsonb;
 win private.bpay_next_valuation_policy_window%rowtype;basis private.bpay_next_source_comparison_receipt%rowtype;
 eligible boolean:=false;qualified boolean:=false;oldw numeric;neww numeric;s numeric;o numeric;q numeric;
 mode text;state text:='REVIEW';issue text:='CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED';newstatus text;
begin
 select * into strict j from private.bpay_next_job where id=p_job_id;
 select * into strict req from private.bpay_next_write_off_request where command_id=j.command_id;
 select * into strict ev from private.bpay_next_case_event where id=p_event_id;
 b:=private.bpay_next_source_comparison_writeoff_origin_v2(req.case_id,req.case_component_id,req.candidate_id);
 actual:=private.bpay_next_source_comparison_case_basis_v2(b.work_id,b.component_key,true);
 if b.id is distinct from req.work_collection_id or actual is null
   or (b.candidate_id,b.work_id,b.component_key) is distinct from (p_input.candidate_id,p_input.canonical_work_id,p_input.canonical_component_key)
   or not private.bpay_next_write_off_owner_v1(j.command_id,j.candidate_id) or j.id<>p_job_id or j.lease_nonce is null
   or j.candidate_id<>req.candidate_id or req.status<>'WRITTEN_OFF' or req.completed_at_utc is distinct from transaction_timestamp()
   or req.event_id is distinct from ev.id or req.applied_amount<=0
   or (ev.id,ev.operation_id,ev.operation_item_id,ev.case_id,ev.event_kind,ev.written_off_delta)
     is distinct from (j.command_id,j.command_id,b.id,b.case_id,'WRITTEN_OFF',req.applied_amount)
   or ev.occurred_at_utc is distinct from transaction_timestamp()
   or ev.approved_delta<>0 or ev.funded_delta<>0 or ev.recovered_delta<>0 or ev.paid_credit_delta<>0
   or ev.original_effect_id is not null or ev.original_transfer_id is not null or ev.instruction_id is not null or ev.allocation_result_id is not null
   or ((actual->>'P')::numeric,(actual->>'K')::numeric,(actual->>'W')::numeric-ev.written_off_delta,(actual->>'J')::numeric,
       (actual->>'case_revision')::bigint-1,(actual->>'component_revision')::bigint-1)
     is distinct from (req.basis_principal,req.basis_recovered,req.basis_written_off,req.basis_protected,
       req.basis_case_revision,req.expected_component_revision)
   or req.remaining_amount is distinct from req.basis_principal-req.basis_recovered-req.basis_written_off-ev.written_off_delta
   or req.protected_amount is distinct from req.basis_protected
   or ev.written_off_delta>req.basis_principal-req.basis_recovered-req.basis_written_off-req.basis_protected
   or (req.requested_scope='ALL' and ev.written_off_delta is distinct from req.basis_principal-req.basis_recovered-req.basis_written_off)
   or (req.requested_scope='AMOUNT' and ev.written_off_delta is distinct from req.requested_amount) then
   raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_NOT_ACTUAL' using errcode='23514';
 end if;
 oldcase:=p_input.case_basis;resolution:=coalesce(p_input.case_resolution,'{}'::jsonb);
 newstatus:=case when req.remaining_amount=0 then 'WRITTEN_OFF' when oldcase->>'case_status'='PAUSED' then 'PAUSED' else 'OPEN' end;
 expected:=oldcase||jsonb_build_object('W',req.basis_written_off+ev.written_off_delta,
   'case_revision',req.basis_case_revision+1,'component_revision',req.expected_component_revision+1,'case_status',newstatus);
 eligible:=oldcase is not null and expected is not distinct from actual
   and ((oldcase->>'P')::numeric,(oldcase->>'K')::numeric,(oldcase->>'W')::numeric,(oldcase->>'J')::numeric,
     (oldcase->>'case_revision')::bigint,(oldcase->>'component_revision')::bigint)
     is not distinct from (req.basis_principal,req.basis_recovered,req.basis_written_off,req.basis_protected,
       req.basis_case_revision,req.expected_component_revision)
   and p_input.comparable_paid_ex_vat is not null and p_input.comparable_held_ex_vat is not null
   and p_input.qualification_state in ('READY','PENDING')
   and resolution->>'case_source_channel'=actual->>'case_source_channel';
 oldw:=(resolution->>'target_written_off_ex_vat')::numeric;s:=(resolution->>'source_outstanding_ex_vat')::numeric;
 mode:=resolution->>'selected_mode';
 select * into win from private.bpay_next_valuation_policy_window where policy_id=p_input.comparison_policy_id
   and source_window_id=p_input.policy_window_id and p_input.effective_pay_date>=date_from
   and (date_to is null or p_input.effective_pay_date<=date_to);
 if eligible and found and oldw is not null and s is not null and ev.written_off_delta<=s-(actual->>'J')::numeric then
   s:=s-ev.written_off_delta;
   -- Suggested cumulative W is a saved-policy forward quote, not delta*ratio.
   if mode='SUGGESTED_EQUIVALENT_BASIS' then
     wquote:=private.pay_finance_selected_quote_v1(mode::public.pay_finance_component_resolution_mode_enum,
       (actual->>'W')::numeric,actual->>'case_source_channel',p_input.target_pay_channel,null,null,null,
       win.erni_pct,win.vat_rate_pct,p_input.umbrella_vat_chargeable);
     neww:=(wquote->>'ex')::numeric;
   elsif mode='MANUAL_AMOUNT' and actual->>'case_source_channel'=p_input.target_pay_channel
     and (resolution->>'target_outstanding_ex_vat')::numeric=(resolution->>'source_outstanding_ex_vat')::numeric
     and oldw=req.basis_written_off then
     -- A genuinely monetary identity partition was already accepted; no rate or inverse.
     neww:=oldw+ev.written_off_delta;
   elsif mode='MANUAL_AMOUNT' and s=0 and (actual->>'J')::numeric=0 then
     -- Full remaining accepted manual outstanding, no arbitrary partial partition.
     neww:=oldw+(resolution->>'target_outstanding_ex_vat')::numeric;
   end if;
   if neww is not null then
     if wquote is null then wquote:=private.pay_finance_selected_quote_v1('MANUAL_AMOUNT',
       (actual->>'W')::numeric,actual->>'case_source_channel',p_input.target_pay_channel,null,null,neww,
       win.erni_pct,win.vat_rate_pct,p_input.umbrella_vat_chargeable);end if;
     o:=greatest(p_input.comparable_paid_ex_vat-p_input.approved_source_ex_vat-neww,
       (resolution->>'target_active_capacity_ex_vat')::numeric,0::numeric);
     quote:=private.pay_finance_selected_quote_v1(mode::public.pay_finance_component_resolution_mode_enum,s,
       actual->>'case_source_channel',p_input.target_pay_channel,null,null,
       case when mode='MANUAL_AMOUNT' then s else null end,win.erni_pct,win.vat_rate_pct,p_input.umbrella_vat_chargeable);
     -- Full remaining manual partition has exact remaining target 0, not source-derived target.
     if mode='MANUAL_AMOUNT' and s=0 then quote:=private.pay_finance_selected_quote_v1('MANUAL_AMOUNT',0,
       actual->>'case_source_channel',p_input.target_pay_channel,null,null,0,
       win.erni_pct,win.vat_rate_pct,p_input.umbrella_vat_chargeable);end if;
     qualified:=neww>=oldw and (quote->>'ex')::numeric is not distinct from o
       and ((p_input.qualification_state='PENDING') or req.basis_principal=req.basis_recovered+
         (actual->>'W')::numeric+greatest(s,(actual->>'J')::numeric));
   end if;
 end if;
 if qualified then
   q:=neww-oldw;
   resolution:=resolution||jsonb_build_object('source_outstanding_ex_vat',s,'source_written_off_ex_vat',actual->'W',
     'source_principal_ex_vat',(actual->>'K')::numeric+(actual->>'W')::numeric+greatest(s,(actual->>'J')::numeric),
     'target_written_off_ex_vat',neww,'target_outstanding_ex_vat',o,'selected_quote',quote,'written_off_quote',wquote);
   if p_input.qualification_state='PENDING' then state:='PENDING';issue:='SOURCE_PUBLICATION_PENDING';else state:='READY';issue:=null;end if;
 else
   -- Keep actual Case W/revisions and accepted R*/H*; target Case money is explicitly unqualified.
   -- Do not leave the old target forgiveness/outstanding usable as a READY amount.
   resolution:=resolution||jsonb_build_object('source_written_off_ex_vat',actual->'W',
     'target_written_off_ex_vat',null,'target_outstanding_ex_vat',null,'selected_quote',null,'written_off_quote',null,
     'qualification_issue',issue,'input_comparison_id',p_input.id);
 end if;
 resolution:=resolution||jsonb_build_object('writeoff_proof',jsonb_build_object('job_id',j.id,'event_id',ev.id,
   'request_command_id',req.command_id,'actual_source_written_off_ex_vat',ev.written_off_delta,
   'before_actual',jsonb_build_object('P',req.basis_principal,'K',req.basis_recovered,'W',req.basis_written_off,'J',req.basis_protected,
     'case_revision',req.basis_case_revision,'component_revision',req.expected_component_revision),
   'before_certified',oldcase,'after_actual',actual,'accepted_basis_current_before',eligible,
   'comparable_written_off_ex_vat',q,'exact',qualified));
 return jsonb_build_object('case_basis',actual,'case_resolution',resolution,'qualification_state',state,'review_issue_code',issue,
   'comparable_operation_ex_vat',q,'actor_user_id',req.actor_user_id,'reason',req.reason);
end $function$;

create or replace function private.bpay_next_source_comparison_writeoff_carry_v2(p_job_id uuid,p_expected_book_revision bigint,
 p_expected_comparison_id uuid,p_event_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private as $function$
declare p private.bpay_next_position%rowtype;oldr private.bpay_next_source_comparison_receipt%rowtype;
 r private.bpay_next_source_comparison_receipt%rowtype;proof jsonb;req private.bpay_next_write_off_request%rowtype;
begin
 select * into r from private.bpay_next_source_comparison_receipt where receipt_kind='CASE_WRITEOFF' and operation_identity=p_event_id;
 if found then
   if (r.operation_job_id,r.previous_comparison_id,r.source_book_revision_before)
     is distinct from (p_job_id,p_expected_comparison_id,p_expected_book_revision) then
     raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_REPLAY_CONFLICT' using errcode='23514';end if;
   return jsonb_build_object('comparison_id',r.id,'comparison_revision',r.comparison_revision,'book_revision',r.source_book_revision,
     'qualification_state',r.qualification_state,'replay',true);
 end if;
 select * into strict req from private.bpay_next_write_off_request where event_id=p_event_id;
 select canonical.* into strict p from private.bpay_next_work_collection b join private.bpay_next_position canonical
   on canonical.work_id=b.work_id and canonical.component_key=b.component_key where b.id=req.work_collection_id for update of canonical;
 if (p.source_book_revision,p.source_comparison_receipt_id) is distinct from (p_expected_book_revision,p_expected_comparison_id)
   or not private.bpay_next_source_comparison_book_certified_v2(p) then
   raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_CURRENT_STALE' using errcode='55000';end if;
 select * into strict oldr from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
 proof:=private.bpay_next_source_comparison_writeoff_proof_v2(oldr,p_job_id,p_event_id);
 r:=oldr;r.id:=gen_random_uuid();r.receipt_kind:='CASE_WRITEOFF';r.previous_comparison_id:=oldr.id;
 r.comparison_revision_before:=p.source_comparison_revision;r.comparison_revision:=p.source_comparison_revision+1;
 r.source_book_revision_before:=p.source_book_revision;r.source_book_revision:=p.source_book_revision;
 r.native_realised_paye_before:=p.native_realised_paye;r.native_realised_umbrella_before:=p.native_realised_umbrella;
 r.native_held_paye_before:=p.native_held_paye;r.native_held_umbrella_before:=p.native_held_umbrella;
 r.comparable_paid_ex_vat_before:=oldr.comparable_paid_ex_vat;r.comparable_held_ex_vat_before:=oldr.comparable_held_ex_vat;
 r.qualification_state:=proof->>'qualification_state';r.review_issue_code:=proof->>'review_issue_code';
 r.work_collection_id:=(proof#>>'{case_basis,collection_id}')::uuid;r.case_id:=(proof#>>'{case_basis,case_id}')::uuid;
 r.case_component_id:=(proof#>>'{case_basis,case_component_id}')::uuid;
 r.case_basis_before:=oldr.case_basis;r.case_basis:=proof->'case_basis';r.case_resolution:=proof->'case_resolution';
 r.operation_job_id:=p_job_id;r.operation_identity:=p_event_id;r.operation_case_event_id:=p_event_id;
 r.operation_hold_id:=null;r.operation_effect_id:=null;r.operation_case_instruction_id:=null;r.operation_case_result_id:=null;r.operation_case_hold_id:=null;
 r.native_source_channel:=null;r.native_delta_realised:=0;r.native_delta_held:=0;r.comparable_operation_ex_vat:=(proof->>'comparable_operation_ex_vat')::numeric;
 r.local_work_id:=null;r.local_component_key:=null;r.local_scalar_before:=null;r.local_scalar_after:=null;
 r.actor_user_id:=(proof->>'actor_user_id')::uuid;r.reason:=proof->>'reason';r.accepted_at_utc:=transaction_timestamp();
 r.snapshot_sha256:=sha256(convert_to((to_jsonb(r)-'snapshot_sha256')::text,'UTF8'));
 insert into private.bpay_next_source_comparison_receipt select (r).*;
 update private.bpay_next_position set source_comparison_receipt_id=r.id,source_comparison_revision=r.comparison_revision,updated_at_utc=transaction_timestamp()
   where work_id=p.work_id and component_key=p.component_key and source_book_revision=p_expected_book_revision
     and source_comparison_receipt_id=p_expected_comparison_id and source_comparison_revision=r.comparison_revision_before;
 if not found then raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_CAS_STALE';end if;
 return jsonb_build_object('comparison_id',r.id,'comparison_revision',r.comparison_revision,'book_revision',r.source_book_revision,
   'qualification_state',r.qualification_state,'replay',false);
end $function$;

-- Actual 1647 knows the real event, not a caller-supplied financial delta.
create or replace function private.bpay_next_source_comparison_writeoff_known_v2(p_job_id uuid,p_event_id uuid)
returns boolean language plpgsql security invoker set search_path=pg_catalog,private as $function$
declare p private.bpay_next_position%rowtype;
begin
 select canonical.* into strict p from private.bpay_next_write_off_request req join private.bpay_next_work_collection b on b.id=req.work_collection_id
   join private.bpay_next_position canonical on canonical.work_id=b.work_id and canonical.component_key=b.component_key where req.event_id=p_event_id;
 if p.source_comparison_receipt_id is null then return false;end if;
 perform private.bpay_next_source_comparison_writeoff_carry_v2(p_job_id,p.source_book_revision,p.source_comparison_receipt_id,p_event_id);
 return true;
end $function$;

alter function private.bpay_next_source_comparison_writeoff_origin_v2(uuid,uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_writeoff_proof_v2(private.bpay_next_source_comparison_receipt,uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_writeoff_carry_v2(uuid,bigint,uuid,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_writeoff_known_v2(uuid,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_writeoff_origin_v2(uuid,uuid,uuid),
 private.bpay_next_source_comparison_writeoff_proof_v2(private.bpay_next_source_comparison_receipt,uuid,uuid),
 private.bpay_next_source_comparison_writeoff_carry_v2(uuid,bigint,uuid,uuid),
 private.bpay_next_source_comparison_writeoff_known_v2(uuid,uuid) from public,anon,authenticated,service_role;


-- Exact successor of two frozen 0157 guard functions; all other bodies unchanged.



create or replace function private.bpay_next_source_comparison_guard_v2()
returns trigger language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare p private.bpay_next_position%rowtype;oldr private.bpay_next_source_comparison_receipt%rowtype;
  w private.weekly_source_destination_reprice_witness_v1%rowtype;v private.bpay_next_source_component_binding_version%rowtype;
  op record;m private.bpay_next_source_comparison_hold_mapping%rowtype;q numeric;plan jsonb;ctx jsonb;item jsonb;counted integer;
  dr numeric;dh numeric;qualified boolean;localp private.bpay_next_position%rowtype;
  basis private.bpay_next_source_comparison_receipt%rowtype;promoting boolean:=false;request jsonb;validation jsonb;
  cm private.bpay_next_source_comparison_case_hold_mapping%rowtype;
  actual_case jsonb;credit_qualified boolean;case_qualified boolean;proof jsonb;expected_state text;
begin
  if tg_op<>'INSERT' then raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_COMPARISON_IMMUTABLE';end if;
  select * into strict p from private.bpay_next_position where work_id=new.canonical_work_id and component_key=new.canonical_component_key;
  select * into strict v from private.bpay_next_source_component_binding_version where id=new.source_binding_version_id;
  if p.source_book_state<>'READY' or new.accepted_at_utc is distinct from transaction_timestamp()
    or new.snapshot_sha256 is distinct from sha256(convert_to((to_jsonb(new)-'snapshot_sha256')::text,'UTF8'))
    or (new.source_book_revision_before,new.comparison_revision_before,new.previous_comparison_id,
      new.native_realised_paye_before,new.native_realised_umbrella_before,new.native_held_paye_before,new.native_held_umbrella_before)
      is distinct from (p.source_book_revision,p.source_comparison_revision,p.source_comparison_receipt_id,
        p.native_realised_paye,p.native_realised_umbrella,p.native_held_paye,p.native_held_umbrella)
    or (new.candidate_id,new.approval_work_id,new.approval_revision_id,new.approval_component_key,new.approved_line_id,
      new.approval_component_state,new.binding_digest,new.approval_component_sha256,new.approval_chosen_detail_sha256)
      is distinct from (v.candidate_id,v.approval_work_id,v.approval_revision_id,v.approval_component_key,v.approved_line_id,
        v.component_state,v.binding_digest,v.component_sha256,v.chosen_detail_sha256) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_SNAPSHOT_CURRENTNESS_INVALID';end if;
  if p.source_comparison_receipt_id is not null then
    select * into strict oldr from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
  end if;
  if (new.comparable_paid_ex_vat_before,new.comparable_held_ex_vat_before)
    is distinct from (oldr.comparable_paid_ex_vat,oldr.comparable_held_ex_vat) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_BEFORE_QUOTE_INVALID';end if;
  if new.receipt_kind in ('REVIEW','PENDING_REVIEW') then
    if not exists(select 1 from private.bpay_next_source_component_binding b where b.current_binding_version_id=v.id
      and b.canonical_work_id=v.canonical_work_id and b.canonical_component_key=v.canonical_component_key) then
      raise exception 'BPAY_NEXT_COMPARISON_REVIEW_BINDING_NOT_CURRENT';end if;
    select * into strict w from private.weekly_source_destination_reprice_witness_v1 where id=new.review_certificate_id;
    select count(*),jsonb_agg(c) into counted,item from jsonb_array_elements(w.context_json#>'{financial_plan,components}') c
      where c->>'source_component_id'=v.source_component_id::text;
    if counted<>1 then raise exception 'BPAY_NEXT_COMPARISON_REVIEW_PLAN_MISSING';end if;
    ctx:=item->0->'context';plan:=item->0->'plan';
    actual_case:=private.bpay_next_source_comparison_case_basis_v2(new.canonical_work_id,new.canonical_component_key,false);
    request:=w.accepted_request_json#-'{financial_request,contract_choices,1,destination_reprice}';
    request:=jsonb_set(request,'{control,whole_root_office_review}',w.context_json#>'{base_request,control,whole_root_office_review}');
    validation:=private.bpay_next_source_comparison_validate_plan_snapshot_v2(request,w.context_json->'financial_context',w.context_json->'financial_plan');
    if new.receipt_kind='REVIEW' and oldr.qualification_state='PENDING' then
      select * into strict basis from private.bpay_next_source_comparison_receipt where id=oldr.basis_review_id;
      promoting:=basis.receipt_kind='PENDING_REVIEW' and basis.review_certificate_id=w.id
        and oldr.review_certificate_id=w.id and new.basis_review_id=basis.id
        and (oldr.target_pay_channel,oldr.comparison_policy_id,oldr.policy_window_id,oldr.effective_pay_date,
          oldr.umbrella_vat_chargeable,oldr.selected_mode,oldr.quote_json,oldr.basis_sha256)
          is not distinct from (new.target_pay_channel,new.comparison_policy_id,new.policy_window_id,new.effective_pay_date,
            new.umbrella_vat_chargeable,new.selected_mode,new.quote_json,new.basis_sha256);
      if not promoting then raise exception 'BPAY_NEXT_COMPARISON_PENDING_PROMOTION_BASIS_CONFLICT';end if;
    end if;
    if new.case_basis_before is distinct from oldr.case_basis or new.case_basis is distinct from actual_case
      or (not promoting and new.case_basis is distinct from nullif(ctx->'case_basis','null'::jsonb))
      or (promoting and oldr.case_basis is distinct from actual_case)
      or new.case_resolution is distinct from (case when promoting then oldr.case_resolution else nullif(plan->'case_resolution','null'::jsonb) end)
      or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
        is distinct from (actual_case->>'collection_id',actual_case->>'case_id',actual_case->>'case_component_id') then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_CURRENT_REVIEW_REQUIRED';end if;
    if (new.receipt_kind='REVIEW' and (w.decision_bundle_id<>v.decision_bundle_id or w.bundle_revision<>v.bundle_revision))
      or new.review_sha256 is distinct from w.review_sha256 or new.actor_user_id<>w.actor_user_id
      or w.accepted_request_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
        private.weekly_source_publication_request_canonical_v1(w.accepted_request_json,'IMMEDIATE',null))
      or w.context_json->>'financial_plan_digest' is distinct from validation->>'financial_plan_digest'
      or validation->>'ok' is distinct from 'true'
      or ctx is null or plan is null
      or (not promoting and (ctx->>'canonical_work_id',ctx->>'canonical_component_key',ctx->>'source_book_revision',
          ctx->>'source_comparison_receipt_id',ctx->>'source_comparison_revision')
        is distinct from (p.work_id::text,p.component_key,p.source_book_revision::text,p.source_comparison_receipt_id::text,p.source_comparison_revision::text))
      or (not promoting and ((ctx->>'native_realised_paye')::numeric,(ctx->>'native_realised_umbrella')::numeric,
          (ctx->>'native_held_paye')::numeric,(ctx->>'native_held_umbrella')::numeric)
        is distinct from (p.native_realised_paye,p.native_realised_umbrella,p.native_held_paye,p.native_held_umbrella))
      or (new.target_pay_channel,new.comparison_policy_id::text,new.policy_window_id::text,new.effective_pay_date::text,
          new.umbrella_vat_chargeable::text,new.selected_mode,new.quote_json,new.basis_sha256,
          new.comparable_paid_ex_vat,new.comparable_held_ex_vat,new.approved_source_ex_vat)
        is distinct from (plan->>'target_pay_channel',plan->>'comparison_policy_id',plan->>'policy_window_id',plan->>'effective_pay_date',
          plan->>'umbrella_vat_chargeable',plan->>'selected_mode',plan->'quote_json',decode(plan->>'basis_sha256','hex'),
          case when promoting then oldr.comparable_paid_ex_vat else (plan->>'comparable_paid_ex_vat')::numeric end,
          case when promoting then oldr.comparable_held_ex_vat else (plan->>'comparable_held_ex_vat')::numeric end,
          (plan->>'approved_source_ex_vat')::numeric)
      or (new.receipt_kind='REVIEW' and new.target_pay_channel<>v.approval_source_channel)
      or new.observed_approved_source_ex_vat is distinct from (case when v.component_state='REMOVED' then 0::numeric
        else (select a.source_pay_ex_vat from private.bpay_next_approved_line a where a.id=v.approved_line_id) end) then
      raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_REVIEW_NOT_SERVER_CERTIFIED';end if;
    if new.receipt_kind='REVIEW' and new.approved_source_ex_vat<>new.observed_approved_source_ex_vat then
      raise exception 'BPAY_NEXT_COMPARISON_REVIEW_ACTUAL_APPROVAL_MISMATCH';end if;
    if new.receipt_kind='PENDING_REVIEW' and (ctx->>'source_binding_version_id' is distinct from v.id::text
      or new.qualification_state<>'PENDING' or new.basis_review_id<>new.id) then
      raise exception 'BPAY_NEXT_COMPARISON_PENDING_CURRENT_INPUT_REQUIRED';end if;
    if not promoting and new.basis_review_id<>new.id then raise exception 'BPAY_NEXT_COMPARISON_REVIEW_BASIS_INVALID';end if;
    -- Root PLAN owns genuine original paid/held quantity proof; explicit refusal, not a money/rate guess.
    if new.selected_mode='MANUAL_REPLACEMENT_RATE' and plan->>'quantity_partition_qualified' is distinct from 'true' then
      raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_PAID_RATE_QUANTITY_UNBOUND';end if;
    return new;
  end if;
  if new.receipt_kind='CASE_WRITEOFF' then
    proof:=private.bpay_next_source_comparison_writeoff_proof_v2(oldr,new.operation_job_id,new.operation_case_event_id);
    if new.operation_identity is distinct from new.operation_case_event_id
      or (new.qualification_state,new.review_issue_code,new.case_basis_before,new.case_basis,new.case_resolution,
          new.comparable_operation_ex_vat,new.actor_user_id,new.reason)
        is distinct from (proof->>'qualification_state',proof->>'review_issue_code',oldr.case_basis,proof->'case_basis',proof->'case_resolution',
          (proof->>'comparable_operation_ex_vat')::numeric,(proof->>'actor_user_id')::uuid,proof->>'reason')
      or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
        is distinct from (proof#>>'{case_basis,collection_id}',proof#>>'{case_basis,case_id}',proof#>>'{case_basis,case_component_id}')
      or (to_jsonb(new)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id',
        'actor_user_id','reason','accepted_at_utc','snapshot_sha256'])
      is distinct from (to_jsonb(oldr)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id',
        'actor_user_id','reason','accepted_at_utc','snapshot_sha256']) then
      raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_CERTIFICATE_INVALID' using errcode='23514';end if;
    return new;
  end if;
  if new.receipt_kind='CASE_RECONCILE' then
    proof:=private.bpay_next_source_comparison_case_reconcile_proof_v2(oldr,new.operation_job_id,new.work_collection_id);
    select * into strict basis from private.bpay_next_source_comparison_receipt where id=oldr.basis_review_id;
    expected_state:=case when basis.receipt_kind='PENDING_REVIEW' and basis.source_binding_version_id=oldr.source_binding_version_id then 'PENDING' else 'READY' end;
    if new.operation_identity<>new.work_collection_id or new.operation_case_event_id is distinct from (proof->>'case_event_id')::uuid
      or new.case_basis_before is distinct from oldr.case_basis or new.case_basis is distinct from proof->'case_basis'
      or new.case_resolution is distinct from proof->'case_resolution' or new.qualification_state<>expected_state
      or new.review_issue_code is distinct from (case when expected_state='PENDING' then 'SOURCE_PUBLICATION_PENDING' else null end)
      or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
        is distinct from (proof#>>'{case_basis,collection_id}',proof#>>'{case_basis,case_id}',proof#>>'{case_basis,case_component_id}')
      or (to_jsonb(new)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id','accepted_at_utc','snapshot_sha256'])
      is distinct from (to_jsonb(oldr)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id','accepted_at_utc','snapshot_sha256']) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_RECONCILE_CERTIFICATE_INVALID';end if;
    return new;
  end if;
  if new.receipt_kind in ('CASE_RESERVE','CASE_RELEASE') then
    proof:=private.bpay_next_source_comparison_case_capacity_proof_v2(oldr,new.operation_job_id,new.operation_case_hold_id,new.receipt_kind);
    if new.operation_identity is distinct from new.operation_case_hold_id
      or (new.operation_case_instruction_id,new.operation_case_result_id,new.native_source_channel,new.comparable_operation_ex_vat)
        is distinct from ((proof->>'instruction_id')::uuid,(proof->>'allocation_result_id')::uuid,
          proof->>'native_source_channel',(proof->>'comparable_operation_ex_vat')::numeric)
      or (new.qualification_state,new.review_issue_code,new.case_basis_before,new.case_basis,new.case_resolution)
        is distinct from (proof->>'qualification_state',proof->>'review_issue_code',oldr.case_basis,proof->'case_basis',proof->'case_resolution')
      or (new.work_collection_id,new.case_id,new.case_component_id) is distinct from (oldr.work_collection_id,oldr.case_id,oldr.case_component_id)
      or (new.source_binding_version_id,new.basis_review_id,new.review_certificate_id,new.review_sha256,new.basis_sha256,new.target_pay_channel,
          new.comparison_policy_id,new.policy_window_id,new.effective_pay_date,new.umbrella_vat_chargeable,new.selected_mode,new.quote_json,
          new.approved_source_ex_vat,new.observed_approved_source_ex_vat,new.comparable_paid_ex_vat,new.comparable_held_ex_vat)
        is distinct from (oldr.source_binding_version_id,oldr.basis_review_id,oldr.review_certificate_id,oldr.review_sha256,oldr.basis_sha256,oldr.target_pay_channel,
          oldr.comparison_policy_id,oldr.policy_window_id,oldr.effective_pay_date,oldr.umbrella_vat_chargeable,oldr.selected_mode,oldr.quote_json,
          oldr.approved_source_ex_vat,oldr.observed_approved_source_ex_vat,oldr.comparable_paid_ex_vat,oldr.comparable_held_ex_vat) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_CAPACITY_CERTIFICATE_INVALID';end if;
    return new;
  end if;
  select * into strict op from private.bpay_next_source_comparison_operation_v2(new.operation_job_id,new.receipt_kind,new.operation_identity);
  if (new.candidate_id,new.canonical_work_id,new.canonical_component_key,new.local_work_id,new.local_component_key,
      new.native_source_channel,new.operation_hold_id,new.operation_effect_id,new.operation_case_event_id,
      new.operation_case_instruction_id,new.operation_case_result_id)
    is distinct from (op.candidate_id,op.canonical_work_id,op.canonical_component_key,op.local_work_id,op.local_component_key,
      op.native_channel,op.hold_id,op.effect_id,op.case_event_id,op.case_instruction_id,op.case_result_id)
    or (new.source_binding_version_id,new.basis_review_id,new.review_certificate_id,new.review_sha256,new.basis_sha256,
      new.target_pay_channel,new.comparison_policy_id,new.policy_window_id,new.effective_pay_date,new.umbrella_vat_chargeable,
      new.selected_mode,new.quote_json,new.approved_source_ex_vat,new.observed_approved_source_ex_vat)
      is distinct from (oldr.source_binding_version_id,oldr.basis_review_id,oldr.review_certificate_id,oldr.review_sha256,oldr.basis_sha256,
        oldr.target_pay_channel,oldr.comparison_policy_id,oldr.policy_window_id,oldr.effective_pay_date,oldr.umbrella_vat_chargeable,
        oldr.selected_mode,oldr.quote_json,oldr.approved_source_ex_vat,oldr.observed_approved_source_ex_vat) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_OPERATION_CERTIFICATE_INVALID';end if;
  dr:=case new.receipt_kind when 'SETTLE' then op.native_amount when 'CASE_RECOVERY' then -op.native_amount else 0 end;
  dh:=case new.receipt_kind when 'RESERVE' then op.native_amount when 'SETTLE' then -op.native_amount when 'RELEASE' then -op.native_amount else 0 end;
  if (new.native_delta_realised,new.native_delta_held,new.native_realised_paye,new.native_realised_umbrella,new.native_held_paye,new.native_held_umbrella)
    is distinct from (dr,dh,p.native_realised_paye+case when op.native_channel='PAYE' then dr else 0 end,
      p.native_realised_umbrella+case when op.native_channel='UMBRELLA' then dr else 0 end,
      p.native_held_paye+case when op.native_channel='PAYE' then dh else 0 end,
      p.native_held_umbrella+case when op.native_channel='UMBRELLA' then dh else 0 end) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_NATIVE_DELTA_INVALID';end if;
  select * into strict localp from private.bpay_next_position where work_id=op.local_work_id and component_key=op.local_component_key;
  if new.local_scalar_before is distinct from private.bpay_next_source_comparison_scalar_v2(localp)
    or new.local_scalar_after is distinct from (case when not op.updates_local_scalar then new.local_scalar_before
      else private.bpay_next_source_comparison_scalar_delta_v2(
        new.local_scalar_before,new.receipt_kind,op.native_amount,op.target_ex,op.target_vat,op.target_inc) end) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_LOCAL_SCALAR_INVALID';end if;
  if new.receipt_kind='RESERVE' and (oldr.qualification_state<>'READY' or oldr.selected_residual_ex_vat<>op.native_amount
    or op.native_channel<>oldr.target_pay_channel or op.target_ex<>op.native_amount
    or not exists(select 1 from private.bpay_next_hold h join private.bpay_next_run_line l on l.id=h.run_line_id
      where h.id=op.hold_id and l.source_comparison_receipt_id=oldr.id and l.source_book_revision=oldr.source_book_revision
        and l.source_binding_version_id=oldr.source_binding_version_id and l.target_pay_channel=oldr.target_pay_channel)) then
    raise exception 'BPAY_NEXT_COMPARISON_NEW_RESERVE_NOT_EXACT_RESIDUAL';end if;
  if new.receipt_kind='RESERVE' then
    q:=op.native_amount;qualified:=op.native_channel=oldr.target_pay_channel;
  elsif new.receipt_kind='CASE_RECOVERY' then
    select * into cm from private.bpay_next_source_comparison_case_hold_mapping where basis_review_id=oldr.basis_review_id
      and case_hold_id=(select operation_item_id from private.bpay_next_case_event where id=op.case_event_id);
    if found then
      qualified:=cm.native_target_channel=op.native_channel and cm.native_target_ex_vat=op.native_amount
        and cm.instruction_id=op.case_instruction_id and cm.allocation_result_id=op.case_result_id;q:=cm.comparable_recovery_ex_vat;
    else q:=op.native_amount;qualified:=op.native_channel=oldr.target_pay_channel;end if;
  else
    select * into m from private.bpay_next_source_comparison_hold_mapping where basis_review_id=oldr.basis_review_id and hold_id=op.hold_id;
    qualified:=found and m.native_source_channel=op.native_channel and m.native_reserved_ex_vat=op.native_amount;
    q:=m.comparable_reserved_ex_vat;
  end if;
  credit_qualified:=qualified and (oldr.qualification_state in ('READY','PENDING') or oldr.review_issue_code='CASE_RECONCILIATION_REQUIRED');
  case_qualified:=true;
  actual_case:=private.bpay_next_source_comparison_case_basis_v2(new.canonical_work_id,new.canonical_component_key,false);
  if new.case_basis_before is distinct from oldr.case_basis or new.case_basis is distinct from actual_case
    or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
      is distinct from (actual_case->>'collection_id',actual_case->>'case_id',actual_case->>'case_component_id') then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_CARRY_TUPLE_INVALID';end if;
  if oldr.case_basis is not null then
    plan:=private.bpay_next_source_comparison_case_remainder_v2(oldr,new.receipt_kind,op.case_event_id,q,
      oldr.comparable_paid_ex_vat+case new.receipt_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end,actual_case);
    case_qualified:=plan is not null;
    if new.case_resolution is distinct from coalesce(plan,oldr.case_resolution) then raise exception 'BPAY_NEXT_COMPARISON_CASE_CARRY_REMAINDER_INVALID';end if;
  elsif actual_case is not null then case_qualified:=false;end if;
  if credit_qualified then
    if new.qualification_state is distinct from (case when case_qualified then oldr.qualification_state else 'REVIEW' end)
      or (not case_qualified and new.review_issue_code is distinct from 'CASE_RECONCILIATION_REQUIRED')
      or new.comparable_operation_ex_vat is distinct from q
      or (new.comparable_paid_ex_vat,new.comparable_held_ex_vat) is distinct from
        (oldr.comparable_paid_ex_vat+case new.receipt_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end,
         oldr.comparable_held_ex_vat+case new.receipt_kind when 'RESERVE' then q when 'SETTLE' then -q when 'RELEASE' then -q else 0 end)
      then raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_CARRY_AMOUNT_INVALID';end if;
  elsif new.qualification_state<>'REVIEW' or new.comparable_operation_ex_vat is not null
    or new.review_issue_code<>'ACTUAL_OPERATION_COMPARABLE_MAPPING_UNBOUND' then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_CARRY_REVIEW_REQUIRED';end if;
  return new;
end $function$;

create or replace function private.bpay_next_source_comparison_assert_book_update_v2(
  p_old private.bpay_next_position,p_new private.bpay_next_position)
returns void language plpgsql security invoker set search_path=pg_catalog,private as $function$
declare r private.bpay_next_source_comparison_receipt%rowtype;expected_scalar jsonb;op record;
begin
  select * into strict r from private.bpay_next_source_comparison_receipt where id=p_new.source_comparison_receipt_id;
  if p_old.source_book_state<>'READY' or p_new.source_book_state<>'READY'
    or r.snapshot_sha256 is distinct from sha256(convert_to((to_jsonb(r)-'snapshot_sha256')::text,'UTF8'))
    or (r.canonical_work_id,r.canonical_component_key,r.previous_comparison_id,r.comparison_revision_before,r.source_book_revision_before,
        r.native_realised_paye_before,r.native_realised_umbrella_before,r.native_held_paye_before,r.native_held_umbrella_before)
      is distinct from (p_old.work_id,p_old.component_key,p_old.source_comparison_receipt_id,p_old.source_comparison_revision,p_old.source_book_revision,
        p_old.native_realised_paye,p_old.native_realised_umbrella,p_old.native_held_paye,p_old.native_held_umbrella)
    or (r.comparison_revision,r.source_book_revision,r.native_realised_paye,r.native_realised_umbrella,r.native_held_paye,r.native_held_umbrella)
      is distinct from (p_new.source_comparison_revision,p_new.source_book_revision,p_new.native_realised_paye,p_new.native_realised_umbrella,
        p_new.native_held_paye,p_new.native_held_umbrella)
    or (to_jsonb(p_new)-array['source_comparison_receipt_id','source_comparison_revision','source_book_revision','native_realised_paye',
      'native_realised_umbrella','native_held_paye','native_held_umbrella','realised_source_ex_vat','held_source_ex_vat',
      'realised_target_ex_vat','realised_target_vat','realised_target_inc_vat','held_target_ex_vat','held_target_vat','held_target_inc_vat','updated_at_utc'])
      is distinct from (to_jsonb(p_old)-array['source_comparison_receipt_id','source_comparison_revision','source_book_revision','native_realised_paye',
      'native_realised_umbrella','native_held_paye','native_held_umbrella','realised_source_ex_vat','held_source_ex_vat',
      'realised_target_ex_vat','realised_target_vat','realised_target_inc_vat','held_target_ex_vat','held_target_vat','held_target_inc_vat','updated_at_utc']) then
    raise exception 'BPAY_NEXT_COMPARISON_BOOK_CERTIFICATE_INVALID';end if;
  expected_scalar:=private.bpay_next_source_comparison_scalar_v2(p_old);
  if r.receipt_kind='CASE_WRITEOFF' then
    perform private.bpay_next_source_comparison_writeoff_proof_v2(
      (select x from private.bpay_next_source_comparison_receipt x where x.id=r.previous_comparison_id),r.operation_job_id,r.operation_case_event_id);
  elsif r.receipt_kind in ('CASE_RESERVE','CASE_RELEASE') then
    perform private.bpay_next_source_comparison_case_capacity_proof_v2(
      (select x from private.bpay_next_source_comparison_receipt x where x.id=r.previous_comparison_id),r.operation_job_id,r.operation_case_hold_id,r.receipt_kind);
  elsif r.receipt_kind='CASE_RECONCILE' then
    perform private.bpay_next_source_comparison_case_reconcile_proof_v2(
      (select x from private.bpay_next_source_comparison_receipt x where x.id=r.previous_comparison_id),r.operation_job_id,r.work_collection_id);
  elsif r.receipt_kind not in ('REVIEW','PENDING_REVIEW') then
    select * into strict op from private.bpay_next_source_comparison_operation_v2(r.operation_job_id,r.receipt_kind,r.operation_identity);
    if (op.canonical_work_id,op.canonical_component_key) is distinct from (p_old.work_id,p_old.component_key) then
      raise exception 'BPAY_NEXT_COMPARISON_BOOK_OPERATION_SCOPE_INVALID';end if;
    if r.local_work_id=p_old.work_id then
      if r.local_scalar_before is distinct from expected_scalar then raise exception 'BPAY_NEXT_COMPARISON_BOOK_SCALAR_BEFORE_INVALID';end if;
      expected_scalar:=r.local_scalar_after;
    end if;
  end if;
  if private.bpay_next_source_comparison_scalar_v2(p_new) is distinct from expected_scalar then
    raise exception 'BPAY_NEXT_COMPARISON_BOOK_SCALAR_AFTER_INVALID';end if;
end $function$;

alter function private.bpay_next_source_comparison_guard_v2() OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_assert_book_update_v2(private.bpay_next_position,private.bpay_next_position) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_guard_v2(),private.bpay_next_source_comparison_assert_book_update_v2(private.bpay_next_position,private.bpay_next_position) from public,anon,authenticated,service_role;


-- E-only successor: known credit is not qualification of unpriced Case forgiveness.



create or replace function private.bpay_next_source_comparison_review_credit_operation_proof_v2(
 p_input private.bpay_next_source_comparison_receipt,p_job_id uuid,p_kind text,p_operation_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private as $function$
declare op record;m private.bpay_next_source_comparison_hold_mapping%rowtype;
 cm private.bpay_next_source_comparison_case_hold_mapping%rowtype;ev private.bpay_next_case_event%rowtype;
 actual jsonb;expected jsonb;resolution jsonb;q numeric;js numeric;qualified boolean;
begin
 if p_input.qualification_state<>'REVIEW' or p_input.review_issue_code is distinct from 'CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED'
   or p_input.comparable_paid_ex_vat is null or p_input.comparable_held_ex_vat is null
   or p_input.case_basis is null or p_input.case_resolution->>'target_written_off_ex_vat' is not null
   or p_input.case_resolution->>'target_outstanding_ex_vat' is not null
   or p_kind not in ('SETTLE','RELEASE','CASE_RECOVERY')
   or p_input.snapshot_sha256 is distinct from sha256(convert_to((to_jsonb(p_input)-'snapshot_sha256')::text,'UTF8'))
   then return null;end if;
 -- Reuse the actual closed operation owner, not caller money or a GUC.
 select * into strict op from private.bpay_next_source_comparison_operation_v2(p_job_id,p_kind,p_operation_id);
 if (op.candidate_id,op.canonical_work_id,op.canonical_component_key)
   is distinct from (p_input.candidate_id,p_input.canonical_work_id,p_input.canonical_component_key) then
   raise exception 'BPAY_NEXT_REVIEW_CREDIT_OPERATION_ORIGIN_INVALID';end if;
 actual:=private.bpay_next_source_comparison_case_basis_snapshot_v2(p_input.canonical_work_id,p_input.canonical_component_key);
 expected:=p_input.case_basis;
 js:=(p_input.case_resolution->>'target_active_capacity_ex_vat')::numeric;
 if p_kind='CASE_RECOVERY' then
   select * into strict ev from private.bpay_next_case_event where id=op.case_event_id;
   select * into cm from private.bpay_next_source_comparison_case_hold_mapping
     where basis_review_id=p_input.basis_review_id and case_hold_id=ev.operation_item_id;
   if found then
     qualified:=cm.native_target_channel=op.native_channel and cm.native_target_ex_vat=op.native_amount
       and cm.instruction_id=op.case_instruction_id and cm.allocation_result_id=op.case_result_id
       and cm.mapping_sha256=sha256(convert_to((to_jsonb(cm)-'mapping_sha256')::text,'UTF8'));
     q:=cm.comparable_recovery_ex_vat;
   else qualified:=op.native_channel=p_input.target_pay_channel;q:=op.native_amount;end if;
   expected:=expected||jsonb_build_object('K',(expected->>'K')::numeric+ev.source_amount_ex_vat,
     'J',(expected->>'J')::numeric-ev.source_amount_ex_vat,
     'case_revision',(expected->>'case_revision')::bigint+1,'component_revision',(expected->>'component_revision')::bigint+1);
   if js is not null and qualified then
     js:=js-q;if js<0 then qualified:=false;end if;
   end if;
 else
   select * into m from private.bpay_next_source_comparison_hold_mapping
     where basis_review_id=p_input.basis_review_id and hold_id=op.hold_id;
   qualified:=found and m.native_source_channel=op.native_channel and m.native_reserved_ex_vat=op.native_amount
     and m.mapping_sha256=sha256(convert_to((to_jsonb(m)-'mapping_sha256')::text,'UTF8'));
   q:=m.comparable_reserved_ex_vat;
   if qualified and p_input.comparable_held_ex_vat<q then qualified:=false;end if;
 end if;
 if not coalesce(qualified,false) or q is null or q<0 or actual is distinct from expected then return null;end if;
 -- Only the actual SOURCE tuple and frozen q advance. Never calculate unknown W*/O*.
 resolution:=p_input.case_resolution||jsonb_build_object(
   'source_outstanding_ex_vat',null,'source_principal_ex_vat',null,
   'source_written_off_ex_vat',actual->'W','target_written_off_ex_vat',null,'target_outstanding_ex_vat',null,
   'target_active_capacity_ex_vat',js,'selected_quote',null,'written_off_quote',null,
   'qualification_issue','CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED',
   'review_credit_operation_proof',jsonb_build_object('input_comparison_id',p_input.id,
     'job_id',p_job_id,'operation_kind',p_kind,'operation_id',p_operation_id,
     'hold_id',op.hold_id,'effect_id',op.effect_id,'case_event_id',op.case_event_id,
     'comparable_operation_ex_vat',q,'before_actual',p_input.case_basis,'after_actual',actual,
     'credit_qualification_state','READY','case_qualification_state','REVIEW'));
 return jsonb_build_object('case_basis',actual,'case_resolution',resolution,'comparable_operation_ex_vat',q);
end $function$;

-- Closed point snapshot for a fresh accepted review. This is NOT a payability reader.
create or replace function private.bpay_next_source_comparison_review_credit_snapshot_v2(
 p_comparison_id uuid,p_expected_book_revision bigint)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,private as $function$
declare r private.bpay_next_source_comparison_receipt%rowtype;p private.bpay_next_position%rowtype;
 v private.bpay_next_source_component_binding_version%rowtype;w private.weekly_source_destination_reprice_witness_v1%rowtype;
 actual jsonb;policy jsonb;operation_actual boolean;
begin
 select * into r from private.bpay_next_source_comparison_receipt where id=p_comparison_id;
 if not found or r.qualification_state<>'REVIEW'
   or r.review_issue_code is distinct from 'CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED'
   or r.comparable_paid_ex_vat is null or r.comparable_held_ex_vat is null or r.comparable_held_ex_vat<0
   or r.case_resolution->>'target_written_off_ex_vat' is not null
   or r.case_resolution->>'target_outstanding_ex_vat' is not null then return null;end if;
 select * into p from private.bpay_next_position where work_id=r.canonical_work_id and component_key=r.canonical_component_key;
 if not found or p.source_book_state<>'READY'
   or (p.source_comparison_receipt_id,p.source_comparison_revision,p.source_book_revision)
     is distinct from (r.id,r.comparison_revision,p_expected_book_revision)
   or not private.bpay_next_source_comparison_book_certified_v2(p) then return null;end if;
 select * into v from private.bpay_next_source_component_binding_version where id=r.source_binding_version_id;
 if not found or not exists(select 1 from private.bpay_next_source_component_binding b
     where b.current_binding_version_id=v.id and b.canonical_work_id=p.work_id and b.canonical_component_key=p.component_key)
   or (r.candidate_id,r.approval_work_id,r.approval_revision_id,r.approval_component_key,r.approved_line_id,
       r.approval_component_state,r.binding_digest,r.approval_component_sha256,r.approval_chosen_detail_sha256)
     is distinct from (v.candidate_id,v.approval_work_id,v.approval_revision_id,v.approval_component_key,v.approved_line_id,
       v.component_state,v.binding_digest,v.component_sha256,v.chosen_detail_sha256) then return null;end if;
 select * into w from private.weekly_source_destination_reprice_witness_v1 where id=r.review_certificate_id;
 if not found or w.review_sha256 is distinct from r.review_sha256 then return null;end if;
 actual:=private.bpay_next_source_comparison_case_basis_snapshot_v2(p.work_id,p.component_key);
 if actual is null or r.case_basis is distinct from actual then return null;end if;
 -- Point-check the already committed real output. No leased-job proof is called from this STABLE reader.
 operation_actual:=case r.receipt_kind
   when 'CASE_WRITEOFF' then exists(select 1 from private.bpay_next_case_event e
     join private.bpay_next_write_off_request req on req.event_id=e.id and req.command_id=e.operation_id
     where e.id=r.operation_case_event_id and e.event_kind='WRITTEN_OFF' and e.case_id=r.case_id
       and e.written_off_delta>0 and req.status='WRITTEN_OFF' and req.work_collection_id=r.work_collection_id)
   when 'SETTLE' then exists(select 1 from private.bpay_next_financial_effect e join private.bpay_next_hold h
     on h.id=e.operation_item_id and h.status='REALISED'
     where e.id=r.operation_effect_id and h.id=r.operation_hold_id and e.effect_kind='PAYROLL_SETTLED')
   when 'RELEASE' then exists(select 1 from private.bpay_next_hold h
     where h.id=r.operation_hold_id and h.status='RELEASED' and h.finished_at_utc is not null)
   when 'CASE_RECOVERY' then exists(select 1 from private.bpay_next_financial_effect e
     join private.bpay_next_case_event ev on ev.id=e.source_case_event_id and ev.event_kind='RECOVERED'
     join private.bpay_next_case_hold h on h.id=ev.operation_item_id and h.status='REALISED'
     where e.id=r.operation_effect_id and ev.id=r.operation_case_event_id
       and e.effect_kind='WORK_COLLECTION_RECOVERED' and ev.case_id=r.case_id)
   when 'CASE_RELEASE' then exists(select 1 from private.bpay_next_case_hold h
     join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id and u.status='RELEASED' and u.realisation_event_id is null
     where h.id=r.operation_case_hold_id and h.status='RELEASED' and h.finished_at_utc is not null)
   else false end;
 if not operation_actual then return null;end if;
 -- Saved immutable quote policy, not today's settings or a newly priced credit.
 policy:=r.quote_json#>'{context,policy}';
 if policy is null or (policy->>'target_pay_channel',policy->>'comparison_policy_id',policy->>'policy_window_id',
     policy->>'effective_pay_date',policy->>'umbrella_vat_chargeable')
   is distinct from (r.target_pay_channel,r.comparison_policy_id::text,r.policy_window_id::text,
     r.effective_pay_date::text,r.umbrella_vat_chargeable::text)
   or policy->>'erni_pct' is null or policy->>'vat_rate_pct' is null then return null;end if;
 return jsonb_build_object('id',r.id,'qualification_state',r.qualification_state,'selected_mode',r.selected_mode,
   'basis',policy,'quantity_partition_qualified',coalesce((r.quote_json#>>'{quote,quantity_partition_qualified}')::boolean,false),
   'comparable_paid_ex_vat',r.comparable_paid_ex_vat,'comparable_held_ex_vat',r.comparable_held_ex_vat,
   'receipt_kind',r.receipt_kind,'review_issue_code',r.review_issue_code,'credit_qualification_state','READY',
   'current_comparison_revision',r.comparison_revision,'source_book_revision',r.source_book_revision,
   'native_realised_paye',r.native_realised_paye,'native_realised_umbrella',r.native_realised_umbrella,
   'native_held_paye',r.native_held_paye,'native_held_umbrella',r.native_held_umbrella,
   'source_binding_version_id',r.source_binding_version_id,'basis_review_id',r.basis_review_id,
   'approval_work_id',r.approval_work_id,'approval_revision_id',r.approval_revision_id,
   'approval_component_key',r.approval_component_key,'approved_line_id',r.approved_line_id,
   'approval_component_state',r.approval_component_state,'binding_digest',encode(r.binding_digest,'hex'),
   'approval_component_sha256',encode(r.approval_component_sha256,'hex'),
   'approval_chosen_detail_sha256',encode(r.approval_chosen_detail_sha256,'hex'),
   'review_certificate_id',r.review_certificate_id,'review_sha256',encode(r.review_sha256,'hex'),
   'current_case_basis',actual,'comparison_snapshot_sha256',encode(r.snapshot_sha256,'hex'),
   'previous_comparison_id',r.previous_comparison_id,'operation_job_id',r.operation_job_id,'operation_identity',r.operation_identity,
   'operation_hold_id',r.operation_hold_id,'operation_effect_id',r.operation_effect_id,
   'operation_case_event_id',r.operation_case_event_id,'operation_case_hold_id',r.operation_case_hold_id);
end $function$;

alter function private.bpay_next_source_comparison_review_credit_operation_proof_v2(private.bpay_next_source_comparison_receipt,uuid,text,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_review_credit_snapshot_v2(uuid,bigint) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_review_credit_operation_proof_v2(private.bpay_next_source_comparison_receipt,uuid,text,uuid),
 private.bpay_next_source_comparison_review_credit_snapshot_v2(uuid,bigint) from public,anon,authenticated,service_role;


-- Exact four-function successor; all other frozen bodies unchanged.



create or replace function private.bpay_next_source_comparison_case_capacity_proof_v2(
  p_input private.bpay_next_source_comparison_receipt,p_job_id uuid,p_case_hold_id uuid,p_kind text)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare j private.bpay_next_job%rowtype;h private.bpay_next_case_hold%rowtype;i private.bpay_next_run_case_instruction%rowtype;
  m private.bpay_next_source_comparison_case_hold_mapping%rowtype;actual jsonb;expected jsonb;r jsonb;
  amount numeric;compq numeric;js numeric;o numeric;s numeric;delta integer;win private.bpay_next_valuation_policy_window%rowtype;
  quote jsonb;state text;issue text;qualified boolean:=true;
begin
  select * into strict j from private.bpay_next_job where id=p_job_id;
  select * into strict h from private.bpay_next_case_hold where id=p_case_hold_id;
  select * into strict i from private.bpay_next_run_case_instruction where id=h.instruction_id;
  actual:=private.bpay_next_source_comparison_case_basis_v2(p_input.canonical_work_id,p_input.canonical_component_key,true);
  if p_kind not in ('CASE_RESERVE','CASE_RELEASE') or j.status<>'LEASED' or j.lease_nonce is null or j.lease_until_utc<=clock_timestamp()
    or j.candidate_id<>p_input.candidate_id or p_input.case_basis is null or actual is null
    or (i.work_collection_id,i.case_id,i.case_component_id,i.candidate_id)
      is distinct from (p_input.work_collection_id,p_input.case_id,p_input.case_component_id,p_input.candidate_id)
    or i.instruction_kind<>'RECOVERY' or i.case_kind<>'OVERPAYMENT' or h.source_reserved_ex_vat<=0 or h.target_amount_ex_vat<=0
    or not exists(select 1 from private.bpay_next_case_allocation_result a where a.id=h.allocation_result_id and a.instruction_id=i.id
      and (a.allocated_source_ex_vat,a.allocated_target_ex_vat,a.allocated_target_vat,a.allocated_target_inc_vat)
        =(h.source_reserved_ex_vat,h.target_amount_ex_vat,h.target_amount_vat,h.target_amount_inc_vat))
    or not exists(select 1 from private.bpay_next_module_control mc join private.bpay_next_worker_control wc on wc.candidate_id=j.candidate_id
      where mc.id=1 and mc.active_owner='NEXT' and mc.owner_epoch=j.module_epoch and wc.active_owner_epoch=j.owner_epoch)
    or exists(select 1 from private.bpay_next_job prior where prior.candidate_id=j.candidate_id and prior.command_sequence<j.command_sequence and prior.status<>'DONE') then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_CAPACITY_SCOPE_INVALID';end if;
  if p_kind='CASE_RESERVE' then
    -- FINANCE_ALLOCATE is the real PREPARE job phase; ALLOCATE is only its DRAFT state stage.
    if p_input.qualification_state<>'READY' or j.job_kind<>'PREPARE' or j.phase<>'FINANCE_ALLOCATE' or h.status<>'ACTIVE'
      or h.allocation_pass_kind<>'DRAFT' or h.projection_id is not null or h.finished_at_utc is not null
      or i.payroll_stage<>'GROSS_DEDUCT' or i.hold_purpose<>'GROSS_RECOVERY'
      or i.source_comparison_receipt_id is distinct from p_input.id or i.target_pay_channel<>p_input.target_pay_channel
      or (i.source_binding_version_id,i.canonical_source_work_id,i.canonical_source_component_key)
        is distinct from (p_input.source_binding_version_id,p_input.canonical_work_id,p_input.canonical_component_key)
      or not exists(select 1 from private.bpay_next_run_command rc
        join private.bpay_next_pay_run pr on pr.id=rc.run_id
        join private.bpay_next_run_worker rw on rw.run_id=rc.run_id
        join private.bpay_next_case_allocation_result a on a.id=h.allocation_result_id and a.instruction_id=i.id
        join private.bpay_next_case_allocation_state s on s.id=a.state_id
        join private.bpay_next_case_selection cs on cs.run_id=rw.run_id
          and cs.candidate_id=rw.candidate_id and cs.selection_revision=rw.case_selection_revision
        join private.bpay_next_case_capacity_use u on u.case_hold_id=h.id
        join private.bpay_next_position p on p.work_id=p_input.canonical_work_id
          and p.component_key=p_input.canonical_component_key
        where rc.command_id=j.command_id and pr.status='PREPARING' and pr.selection_state='SEALED'
          and rw.id=h.run_worker_id and rw.id=i.run_worker_id and rw.candidate_id=j.candidate_id
          and rw.run_id=i.run_id and rw.status='PREPARING' and rw.review_issue_code is null and rw.financial_resolution_count=0
          and rw.target_pay_channel=i.target_pay_channel and i.allocation_channel=rw.target_pay_channel
          and (rw.target_pay_channel<>'UMBRELLA' or rw.target_umbrella_vat_chargeable is not distinct from p_input.umbrella_vat_chargeable)
          and (i.preparation_revision,i.selection_revision)=(rw.preparation_revision,rw.case_selection_revision)
          and (s.run_worker_id,s.run_id,s.candidate_id,s.preparation_revision,s.selection_revision,s.job_id,s.command_id,s.module_epoch,s.owner_epoch)
            =(rw.id,rw.run_id,rw.candidate_id,rw.preparation_revision,rw.case_selection_revision,j.id,j.command_id,j.module_epoch,j.owner_epoch)
          and s.pass_kind='DRAFT' and s.projection_no=0 and s.projection_id is null
          and s.status='BUILDING' and s.prepare_stage='ALLOCATE' and s.weekly_binding_state='BOUND'
          and cs.status='SEALED' and s.expected_instruction_count=cs.selected_count
          and s.captured_instruction_count=s.expected_instruction_count and rw.case_instruction_count=s.expected_instruction_count
          and (a.run_worker_id,a.candidate_id,a.preparation_revision,a.selection_revision,a.pass_kind,a.allocation_channel,a.hold_purpose)
            =(rw.id,rw.candidate_id,rw.preparation_revision,rw.case_selection_revision,'DRAFT',i.allocation_channel,i.hold_purpose)
          and u.status='ACTIVE' and u.realisation_event_id is null
          and (u.case_component_id,u.case_id,u.candidate_id,u.pay_week_start,u.purpose,u.source_amount_ex_vat)
            =(h.case_component_id,h.case_id,h.candidate_id,h.pay_week_start,h.purpose,h.source_reserved_ex_vat)
          and p.source_book_state='READY' and p.source_book_revision=p_input.source_book_revision
          and p.source_comparison_receipt_id=p_input.id and p.source_comparison_revision=p_input.comparison_revision) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_RESERVE_NOT_ACCEPTED';end if;
    compq:=h.target_amount_ex_vat;delta:=1;
  else
    if h.status<>'RELEASED' or h.finished_at_utc is null or h.finished_at_utc>clock_timestamp() or j.phase<>'RELEASE'
      or not exists(select 1 from private.bpay_next_case_capacity_use u where u.case_hold_id=h.id and u.status='RELEASED' and u.realisation_event_id is null)
      or not ((j.job_kind='PREPARATION_EXPIRY' and private.bpay_next_source_comparison_expired_case_scope_v2(j.id,i.work_collection_id,h.id))
        or (j.job_kind='SIMPLE_CANCEL' and exists(select 1 from private.bpay_next_case_cancel_binding cb
          join private.bpay_next_cancel_request cr on cr.command_id=cb.command_id and cr.status='CANCELLING'
          join private.bpay_next_run_worker rw on rw.id=cb.run_worker_id and rw.candidate_id=j.candidate_id and rw.status='CANCELLING'
          where cb.command_id=j.command_id and cb.candidate_id=j.candidate_id and cb.run_worker_id=h.run_worker_id
            and cb.status='CANCELLING' and cb.stage='CASE' and h.finished_at_utc>=cr.started_at_utc
            and (cb.case_hold_cursor is null or h.id>cb.case_hold_cursor)))) then raise exception 'BPAY_NEXT_COMPARISON_CASE_RELEASE_NOT_ACTUAL';end if;
    select * into m from private.bpay_next_source_comparison_case_hold_mapping where basis_review_id=p_input.basis_review_id and case_hold_id=h.id;
    if found then
      qualified:=m.instruction_id=i.id and m.allocation_result_id=h.allocation_result_id
        and m.native_target_channel=i.target_pay_channel and m.native_target_ex_vat=h.target_amount_ex_vat;
      compq:=m.comparable_recovery_ex_vat;
    elsif i.source_comparison_receipt_id is not null and i.target_pay_channel=p_input.target_pay_channel then compq:=h.target_amount_ex_vat;
    else qualified:=false;end if;
    delta:=-1;
  end if;
  expected:=p_input.case_basis||jsonb_build_object('J',(p_input.case_basis->>'J')::numeric+delta*h.source_reserved_ex_vat,
    'case_revision',(p_input.case_basis->>'case_revision')::bigint+1,'component_revision',(p_input.case_basis->>'component_revision')::bigint+1);
  if expected is distinct from actual then raise exception 'BPAY_NEXT_COMPARISON_CASE_CAPACITY_NATIVE_TUPLE_INVALID';end if;
  r:=p_input.case_resolution;
  -- Actual known Case release cannot qualify a still-unknown W*/O*.
  if p_input.qualification_state='REVIEW'
    and p_input.review_issue_code='CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED' then
    if p_kind<>'CASE_RELEASE' then raise exception 'BPAY_NEXT_REVIEW_CREDIT_DENIES_CASE_RESERVE';end if;
    if p_input.case_resolution->>'target_written_off_ex_vat' is not null
      or p_input.case_resolution->>'target_outstanding_ex_vat' is not null then
      raise exception 'BPAY_NEXT_REVIEW_CREDIT_CASE_WRITE_OFF_SHAPE_INVALID';end if;
    js:=case when qualified and r->>'target_active_capacity_ex_vat' is not null
      then (r->>'target_active_capacity_ex_vat')::numeric-compq else null end;
    if js<0 then js:=null;qualified:=false;end if;
    r:=r||jsonb_build_object('source_outstanding_ex_vat',null,'source_principal_ex_vat',null,
      'source_written_off_ex_vat',actual->'W','target_written_off_ex_vat',null,'target_outstanding_ex_vat',null,
      'target_active_capacity_ex_vat',js,'selected_quote',null,'written_off_quote',null,
      'qualification_issue','CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED',
      'review_credit_capacity_proof',jsonb_build_object('input_comparison_id',p_input.id,'job_id',j.id,
        'case_hold_id',h.id,'actual_source_capacity_delta',-h.source_reserved_ex_vat,
        'comparable_capacity_delta',case when qualified then -compq else null end,
        'before_actual',p_input.case_basis,'after_actual',actual,'case_qualification_state','REVIEW'));
    return jsonb_build_object('case_basis',actual,'case_resolution',r,'qualification_state','REVIEW',
      'review_issue_code','CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED',
      'comparable_operation_ex_vat',case when qualified then compq else null end,
      'instruction_id',i.id,'allocation_result_id',h.allocation_result_id,'native_source_channel',i.target_pay_channel);
  end if;

  if qualified and p_input.comparable_paid_ex_vat is not null and r->>'target_active_capacity_ex_vat' is not null then
    js:=(r->>'target_active_capacity_ex_vat')::numeric+delta*compq;
    o:=greatest(p_input.comparable_paid_ex_vat-p_input.approved_source_ex_vat-(r->>'target_written_off_ex_vat')::numeric,js,0::numeric);
    s:=(r->>'source_outstanding_ex_vat')::numeric;
    select * into strict win from private.bpay_next_valuation_policy_window where policy_id=p_input.comparison_policy_id
      and source_window_id=p_input.policy_window_id and p_input.effective_pay_date>=date_from and (date_to is null or p_input.effective_pay_date<=date_to);
    quote:=private.pay_finance_selected_quote_v1((r->>'selected_mode')::public.pay_finance_component_resolution_mode_enum,s,
      r->>'case_source_channel',p_input.target_pay_channel,null,null,
      case when r->>'selected_mode'='MANUAL_AMOUNT' then (r->>'target_outstanding_ex_vat')::numeric else null end,
      win.erni_pct,win.vat_rate_pct,p_input.umbrella_vat_chargeable);
    if (quote->>'ex')::numeric is distinct from o and p_kind='CASE_RELEASE' then
      s:=greatest(s-h.source_reserved_ex_vat,0::numeric);
      quote:=private.pay_finance_selected_quote_v1((r->>'selected_mode')::public.pay_finance_component_resolution_mode_enum,s,
        r->>'case_source_channel',p_input.target_pay_channel,null,null,
        case when r->>'selected_mode'='MANUAL_AMOUNT' then greatest((r->>'target_outstanding_ex_vat')::numeric-compq,0::numeric) else null end,
        win.erni_pct,win.vat_rate_pct,p_input.umbrella_vat_chargeable);
    end if;
    qualified:=js>=0 and (quote->>'ex')::numeric is not distinct from o;
    if qualified then r:=r||jsonb_build_object('source_outstanding_ex_vat',s,'target_outstanding_ex_vat',o,
      'target_active_capacity_ex_vat',js,'source_principal_ex_vat',(actual->>'K')::numeric+(actual->>'W')::numeric+greatest(s,(actual->>'J')::numeric),
      'selected_quote',quote,'capacity_remainder_proof',jsonb_build_object('case_hold_id',h.id,'operation_kind',p_kind,
        'actual_source_capacity_delta',delta*h.source_reserved_ex_vat,'comparable_capacity_delta',delta*compq));end if;
  else qualified:=false;end if;
  if not qualified and p_kind='CASE_RESERVE' then raise exception 'BPAY_NEXT_COMPARISON_CASE_CAPACITY_RESERVE_REVIEW_REQUIRED';end if;
  if not qualified then
    state:='REVIEW';issue:='CASE_CAPACITY_COMPARISON_REVIEW_REQUIRED';
    r:=r||jsonb_build_object('qualification_issue',issue,'actual_case_hold_id',h.id);
  elsif p_input.qualification_state='PENDING' then state:='PENDING';issue:='SOURCE_PUBLICATION_PENDING';
  elsif (r->>'source_principal_ex_vat')::numeric is distinct from (actual->>'P')::numeric then state:='REVIEW';issue:='CASE_RECONCILIATION_REQUIRED';
  else state:='READY';end if;
  return jsonb_build_object('case_basis',actual,'case_resolution',r,'qualification_state',state,'review_issue_code',issue,
    'comparable_operation_ex_vat',compq,'instruction_id',i.id,'allocation_result_id',h.allocation_result_id,'native_source_channel',i.target_pay_channel);
end $function$;

create or replace function private.bpay_next_source_comparison_guard_v2()
returns trigger language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare p private.bpay_next_position%rowtype;oldr private.bpay_next_source_comparison_receipt%rowtype;
  w private.weekly_source_destination_reprice_witness_v1%rowtype;v private.bpay_next_source_component_binding_version%rowtype;
  op record;m private.bpay_next_source_comparison_hold_mapping%rowtype;q numeric;plan jsonb;ctx jsonb;item jsonb;counted integer;
  dr numeric;dh numeric;qualified boolean;localp private.bpay_next_position%rowtype;
  basis private.bpay_next_source_comparison_receipt%rowtype;promoting boolean:=false;request jsonb;validation jsonb;
  cm private.bpay_next_source_comparison_case_hold_mapping%rowtype;
  actual_case jsonb;credit_qualified boolean;case_qualified boolean;proof jsonb;expected_state text;
begin
  if tg_op<>'INSERT' then raise exception using errcode='55000',message='BPAY_NEXT_SOURCE_COMPARISON_IMMUTABLE';end if;
  select * into strict p from private.bpay_next_position where work_id=new.canonical_work_id and component_key=new.canonical_component_key;
  select * into strict v from private.bpay_next_source_component_binding_version where id=new.source_binding_version_id;
  if p.source_book_state<>'READY' or new.accepted_at_utc is distinct from transaction_timestamp()
    or new.snapshot_sha256 is distinct from sha256(convert_to((to_jsonb(new)-'snapshot_sha256')::text,'UTF8'))
    or (new.source_book_revision_before,new.comparison_revision_before,new.previous_comparison_id,
      new.native_realised_paye_before,new.native_realised_umbrella_before,new.native_held_paye_before,new.native_held_umbrella_before)
      is distinct from (p.source_book_revision,p.source_comparison_revision,p.source_comparison_receipt_id,
        p.native_realised_paye,p.native_realised_umbrella,p.native_held_paye,p.native_held_umbrella)
    or (new.candidate_id,new.approval_work_id,new.approval_revision_id,new.approval_component_key,new.approved_line_id,
      new.approval_component_state,new.binding_digest,new.approval_component_sha256,new.approval_chosen_detail_sha256)
      is distinct from (v.candidate_id,v.approval_work_id,v.approval_revision_id,v.approval_component_key,v.approved_line_id,
        v.component_state,v.binding_digest,v.component_sha256,v.chosen_detail_sha256) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_SNAPSHOT_CURRENTNESS_INVALID';end if;
  if p.source_comparison_receipt_id is not null then
    select * into strict oldr from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
  end if;
  if (new.comparable_paid_ex_vat_before,new.comparable_held_ex_vat_before)
    is distinct from (oldr.comparable_paid_ex_vat,oldr.comparable_held_ex_vat) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_BEFORE_QUOTE_INVALID';end if;
  if new.receipt_kind in ('REVIEW','PENDING_REVIEW') then
    if not exists(select 1 from private.bpay_next_source_component_binding b where b.current_binding_version_id=v.id
      and b.canonical_work_id=v.canonical_work_id and b.canonical_component_key=v.canonical_component_key) then
      raise exception 'BPAY_NEXT_COMPARISON_REVIEW_BINDING_NOT_CURRENT';end if;
    select * into strict w from private.weekly_source_destination_reprice_witness_v1 where id=new.review_certificate_id;
    select count(*),jsonb_agg(c) into counted,item from jsonb_array_elements(w.context_json#>'{financial_plan,components}') c
      where c->>'source_component_id'=v.source_component_id::text;
    if counted<>1 then raise exception 'BPAY_NEXT_COMPARISON_REVIEW_PLAN_MISSING';end if;
    ctx:=item->0->'context';plan:=item->0->'plan';
    actual_case:=private.bpay_next_source_comparison_case_basis_v2(new.canonical_work_id,new.canonical_component_key,false);
    request:=w.accepted_request_json#-'{financial_request,contract_choices,1,destination_reprice}';
    request:=jsonb_set(request,'{control,whole_root_office_review}',w.context_json#>'{base_request,control,whole_root_office_review}');
    validation:=private.bpay_next_source_comparison_validate_plan_snapshot_v2(request,w.context_json->'financial_context',w.context_json->'financial_plan');
    if new.receipt_kind='REVIEW' and oldr.qualification_state='PENDING' then
      select * into strict basis from private.bpay_next_source_comparison_receipt where id=oldr.basis_review_id;
      promoting:=basis.receipt_kind='PENDING_REVIEW' and basis.review_certificate_id=w.id
        and oldr.review_certificate_id=w.id and new.basis_review_id=basis.id
        and (oldr.target_pay_channel,oldr.comparison_policy_id,oldr.policy_window_id,oldr.effective_pay_date,
          oldr.umbrella_vat_chargeable,oldr.selected_mode,oldr.quote_json,oldr.basis_sha256)
          is not distinct from (new.target_pay_channel,new.comparison_policy_id,new.policy_window_id,new.effective_pay_date,
            new.umbrella_vat_chargeable,new.selected_mode,new.quote_json,new.basis_sha256);
      if not promoting then raise exception 'BPAY_NEXT_COMPARISON_PENDING_PROMOTION_BASIS_CONFLICT';end if;
    end if;
    if new.case_basis_before is distinct from oldr.case_basis or new.case_basis is distinct from actual_case
      or (not promoting and new.case_basis is distinct from nullif(ctx->'case_basis','null'::jsonb))
      or (promoting and oldr.case_basis is distinct from actual_case)
      or new.case_resolution is distinct from (case when promoting then oldr.case_resolution else nullif(plan->'case_resolution','null'::jsonb) end)
      or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
        is distinct from (actual_case->>'collection_id',actual_case->>'case_id',actual_case->>'case_component_id') then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_CURRENT_REVIEW_REQUIRED';end if;
    if (new.receipt_kind='REVIEW' and (w.decision_bundle_id<>v.decision_bundle_id or w.bundle_revision<>v.bundle_revision))
      or new.review_sha256 is distinct from w.review_sha256 or new.actor_user_id<>w.actor_user_id
      or w.accepted_request_sha256 is distinct from private.weekly_source_publication_request_digest_v1(
        private.weekly_source_publication_request_canonical_v1(w.accepted_request_json,'IMMEDIATE',null))
      or w.context_json->>'financial_plan_digest' is distinct from validation->>'financial_plan_digest'
      or validation->>'ok' is distinct from 'true'
      or ctx is null or plan is null
      or (not promoting and (ctx->>'canonical_work_id',ctx->>'canonical_component_key',ctx->>'source_book_revision',
          ctx->>'source_comparison_receipt_id',ctx->>'source_comparison_revision')
        is distinct from (p.work_id::text,p.component_key,p.source_book_revision::text,p.source_comparison_receipt_id::text,p.source_comparison_revision::text))
      or (not promoting and ((ctx->>'native_realised_paye')::numeric,(ctx->>'native_realised_umbrella')::numeric,
          (ctx->>'native_held_paye')::numeric,(ctx->>'native_held_umbrella')::numeric)
        is distinct from (p.native_realised_paye,p.native_realised_umbrella,p.native_held_paye,p.native_held_umbrella))
      or (new.target_pay_channel,new.comparison_policy_id::text,new.policy_window_id::text,new.effective_pay_date::text,
          new.umbrella_vat_chargeable::text,new.selected_mode,new.quote_json,new.basis_sha256,
          new.comparable_paid_ex_vat,new.comparable_held_ex_vat,new.approved_source_ex_vat)
        is distinct from (plan->>'target_pay_channel',plan->>'comparison_policy_id',plan->>'policy_window_id',plan->>'effective_pay_date',
          plan->>'umbrella_vat_chargeable',plan->>'selected_mode',plan->'quote_json',decode(plan->>'basis_sha256','hex'),
          case when promoting then oldr.comparable_paid_ex_vat else (plan->>'comparable_paid_ex_vat')::numeric end,
          case when promoting then oldr.comparable_held_ex_vat else (plan->>'comparable_held_ex_vat')::numeric end,
          (plan->>'approved_source_ex_vat')::numeric)
      or (new.receipt_kind='REVIEW' and new.target_pay_channel<>v.approval_source_channel)
      or new.observed_approved_source_ex_vat is distinct from (case when v.component_state='REMOVED' then 0::numeric
        else (select a.source_pay_ex_vat from private.bpay_next_approved_line a where a.id=v.approved_line_id) end) then
      raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_REVIEW_NOT_SERVER_CERTIFIED';end if;
    if new.receipt_kind='REVIEW' and new.approved_source_ex_vat<>new.observed_approved_source_ex_vat then
      raise exception 'BPAY_NEXT_COMPARISON_REVIEW_ACTUAL_APPROVAL_MISMATCH';end if;
    if new.receipt_kind='PENDING_REVIEW' and (ctx->>'source_binding_version_id' is distinct from v.id::text
      or new.qualification_state<>'PENDING' or new.basis_review_id<>new.id) then
      raise exception 'BPAY_NEXT_COMPARISON_PENDING_CURRENT_INPUT_REQUIRED';end if;
    if not promoting and new.basis_review_id<>new.id then raise exception 'BPAY_NEXT_COMPARISON_REVIEW_BASIS_INVALID';end if;
    -- Root PLAN owns genuine original paid/held quantity proof; explicit refusal, not a money/rate guess.
    if new.selected_mode='MANUAL_REPLACEMENT_RATE' and plan->>'quantity_partition_qualified' is distinct from 'true' then
      raise exception using errcode='55000',message='BPAY_NEXT_COMPARISON_PAID_RATE_QUANTITY_UNBOUND';end if;
    return new;
  end if;
  if new.receipt_kind='CASE_WRITEOFF' then
    proof:=private.bpay_next_source_comparison_writeoff_proof_v2(oldr,new.operation_job_id,new.operation_case_event_id);
    if new.operation_identity is distinct from new.operation_case_event_id
      or (new.qualification_state,new.review_issue_code,new.case_basis_before,new.case_basis,new.case_resolution,
          new.comparable_operation_ex_vat,new.actor_user_id,new.reason)
        is distinct from (proof->>'qualification_state',proof->>'review_issue_code',oldr.case_basis,proof->'case_basis',proof->'case_resolution',
          (proof->>'comparable_operation_ex_vat')::numeric,(proof->>'actor_user_id')::uuid,proof->>'reason')
      or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
        is distinct from (proof#>>'{case_basis,collection_id}',proof#>>'{case_basis,case_id}',proof#>>'{case_basis,case_component_id}')
      or (to_jsonb(new)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id',
        'actor_user_id','reason','accepted_at_utc','snapshot_sha256'])
      is distinct from (to_jsonb(oldr)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id',
        'actor_user_id','reason','accepted_at_utc','snapshot_sha256']) then
      raise exception 'BPAY_NEXT_COMPARISON_WRITEOFF_CERTIFICATE_INVALID' using errcode='23514';end if;
    return new;
  end if;
  if new.receipt_kind='CASE_RECONCILE' then
    proof:=private.bpay_next_source_comparison_case_reconcile_proof_v2(oldr,new.operation_job_id,new.work_collection_id);
    select * into strict basis from private.bpay_next_source_comparison_receipt where id=oldr.basis_review_id;
    expected_state:=case when basis.receipt_kind='PENDING_REVIEW' and basis.source_binding_version_id=oldr.source_binding_version_id then 'PENDING' else 'READY' end;
    if new.operation_identity<>new.work_collection_id or new.operation_case_event_id is distinct from (proof->>'case_event_id')::uuid
      or new.case_basis_before is distinct from oldr.case_basis or new.case_basis is distinct from proof->'case_basis'
      or new.case_resolution is distinct from proof->'case_resolution' or new.qualification_state<>expected_state
      or new.review_issue_code is distinct from (case when expected_state='PENDING' then 'SOURCE_PUBLICATION_PENDING' else null end)
      or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
        is distinct from (proof#>>'{case_basis,collection_id}',proof#>>'{case_basis,case_id}',proof#>>'{case_basis,case_component_id}')
      or (to_jsonb(new)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id','accepted_at_utc','snapshot_sha256'])
      is distinct from (to_jsonb(oldr)-array['id','receipt_kind','qualification_state','review_issue_code','previous_comparison_id','comparison_revision_before',
        'comparison_revision','source_book_revision_before','native_realised_paye_before','native_realised_umbrella_before','native_held_paye_before',
        'native_held_umbrella_before','comparable_paid_ex_vat_before','comparable_held_ex_vat_before','case_basis_before','case_basis','case_resolution',
        'work_collection_id','case_id','case_component_id','operation_job_id','operation_identity','operation_case_event_id','native_delta_realised',
        'native_delta_held','native_source_channel','comparable_operation_ex_vat','local_work_id','local_component_key','local_scalar_before','local_scalar_after',
        'operation_effect_id','operation_hold_id','operation_case_instruction_id','operation_case_result_id','operation_case_hold_id','accepted_at_utc','snapshot_sha256']) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_RECONCILE_CERTIFICATE_INVALID';end if;
    return new;
  end if;
  if new.receipt_kind in ('CASE_RESERVE','CASE_RELEASE') then
    proof:=private.bpay_next_source_comparison_case_capacity_proof_v2(oldr,new.operation_job_id,new.operation_case_hold_id,new.receipt_kind);
    if new.operation_identity is distinct from new.operation_case_hold_id
      or (new.operation_case_instruction_id,new.operation_case_result_id,new.native_source_channel,new.comparable_operation_ex_vat)
        is distinct from ((proof->>'instruction_id')::uuid,(proof->>'allocation_result_id')::uuid,
          proof->>'native_source_channel',(proof->>'comparable_operation_ex_vat')::numeric)
      or (new.qualification_state,new.review_issue_code,new.case_basis_before,new.case_basis,new.case_resolution)
        is distinct from (proof->>'qualification_state',proof->>'review_issue_code',oldr.case_basis,proof->'case_basis',proof->'case_resolution')
      or (new.work_collection_id,new.case_id,new.case_component_id) is distinct from (oldr.work_collection_id,oldr.case_id,oldr.case_component_id)
      or (new.source_binding_version_id,new.basis_review_id,new.review_certificate_id,new.review_sha256,new.basis_sha256,new.target_pay_channel,
          new.comparison_policy_id,new.policy_window_id,new.effective_pay_date,new.umbrella_vat_chargeable,new.selected_mode,new.quote_json,
          new.approved_source_ex_vat,new.observed_approved_source_ex_vat,new.comparable_paid_ex_vat,new.comparable_held_ex_vat)
        is distinct from (oldr.source_binding_version_id,oldr.basis_review_id,oldr.review_certificate_id,oldr.review_sha256,oldr.basis_sha256,oldr.target_pay_channel,
          oldr.comparison_policy_id,oldr.policy_window_id,oldr.effective_pay_date,oldr.umbrella_vat_chargeable,oldr.selected_mode,oldr.quote_json,
          oldr.approved_source_ex_vat,oldr.observed_approved_source_ex_vat,oldr.comparable_paid_ex_vat,oldr.comparable_held_ex_vat) then
      raise exception 'BPAY_NEXT_COMPARISON_CASE_CAPACITY_CERTIFICATE_INVALID';end if;
    return new;
  end if;
  select * into strict op from private.bpay_next_source_comparison_operation_v2(new.operation_job_id,new.receipt_kind,new.operation_identity);
  if (new.candidate_id,new.canonical_work_id,new.canonical_component_key,new.local_work_id,new.local_component_key,
      new.native_source_channel,new.operation_hold_id,new.operation_effect_id,new.operation_case_event_id,
      new.operation_case_instruction_id,new.operation_case_result_id)
    is distinct from (op.candidate_id,op.canonical_work_id,op.canonical_component_key,op.local_work_id,op.local_component_key,
      op.native_channel,op.hold_id,op.effect_id,op.case_event_id,op.case_instruction_id,op.case_result_id)
    or (new.source_binding_version_id,new.basis_review_id,new.review_certificate_id,new.review_sha256,new.basis_sha256,
      new.target_pay_channel,new.comparison_policy_id,new.policy_window_id,new.effective_pay_date,new.umbrella_vat_chargeable,
      new.selected_mode,new.quote_json,new.approved_source_ex_vat,new.observed_approved_source_ex_vat)
      is distinct from (oldr.source_binding_version_id,oldr.basis_review_id,oldr.review_certificate_id,oldr.review_sha256,oldr.basis_sha256,
        oldr.target_pay_channel,oldr.comparison_policy_id,oldr.policy_window_id,oldr.effective_pay_date,oldr.umbrella_vat_chargeable,
        oldr.selected_mode,oldr.quote_json,oldr.approved_source_ex_vat,oldr.observed_approved_source_ex_vat) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_OPERATION_CERTIFICATE_INVALID';end if;
  dr:=case new.receipt_kind when 'SETTLE' then op.native_amount when 'CASE_RECOVERY' then -op.native_amount else 0 end;
  dh:=case new.receipt_kind when 'RESERVE' then op.native_amount when 'SETTLE' then -op.native_amount when 'RELEASE' then -op.native_amount else 0 end;
  if (new.native_delta_realised,new.native_delta_held,new.native_realised_paye,new.native_realised_umbrella,new.native_held_paye,new.native_held_umbrella)
    is distinct from (dr,dh,p.native_realised_paye+case when op.native_channel='PAYE' then dr else 0 end,
      p.native_realised_umbrella+case when op.native_channel='UMBRELLA' then dr else 0 end,
      p.native_held_paye+case when op.native_channel='PAYE' then dh else 0 end,
      p.native_held_umbrella+case when op.native_channel='UMBRELLA' then dh else 0 end) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_NATIVE_DELTA_INVALID';end if;
  select * into strict localp from private.bpay_next_position where work_id=op.local_work_id and component_key=op.local_component_key;
  if new.local_scalar_before is distinct from private.bpay_next_source_comparison_scalar_v2(localp)
    or new.local_scalar_after is distinct from (case when not op.updates_local_scalar then new.local_scalar_before
      else private.bpay_next_source_comparison_scalar_delta_v2(
        new.local_scalar_before,new.receipt_kind,op.native_amount,op.target_ex,op.target_vat,op.target_inc) end) then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_LOCAL_SCALAR_INVALID';end if;
  if new.receipt_kind='RESERVE' and (oldr.qualification_state<>'READY' or oldr.selected_residual_ex_vat<>op.native_amount
    or op.native_channel<>oldr.target_pay_channel or op.target_ex<>op.native_amount
    or not exists(select 1 from private.bpay_next_hold h join private.bpay_next_run_line l on l.id=h.run_line_id
      where h.id=op.hold_id and l.source_comparison_receipt_id=oldr.id and l.source_book_revision=oldr.source_book_revision
        and l.source_binding_version_id=oldr.source_binding_version_id and l.target_pay_channel=oldr.target_pay_channel)) then
    raise exception 'BPAY_NEXT_COMPARISON_NEW_RESERVE_NOT_EXACT_RESIDUAL';end if;
  if new.receipt_kind='RESERVE' then
    q:=op.native_amount;qualified:=op.native_channel=oldr.target_pay_channel;
  elsif new.receipt_kind='CASE_RECOVERY' then
    select * into cm from private.bpay_next_source_comparison_case_hold_mapping where basis_review_id=oldr.basis_review_id
      and case_hold_id=(select operation_item_id from private.bpay_next_case_event where id=op.case_event_id);
    if found then
      qualified:=cm.native_target_channel=op.native_channel and cm.native_target_ex_vat=op.native_amount
        and cm.instruction_id=op.case_instruction_id and cm.allocation_result_id=op.case_result_id;q:=cm.comparable_recovery_ex_vat;
    else q:=op.native_amount;qualified:=op.native_channel=oldr.target_pay_channel;end if;
  else
    select * into m from private.bpay_next_source_comparison_hold_mapping where basis_review_id=oldr.basis_review_id and hold_id=op.hold_id;
    qualified:=found and m.native_source_channel=op.native_channel and m.native_reserved_ex_vat=op.native_amount;
    q:=m.comparable_reserved_ex_vat;
  end if;
  if oldr.qualification_state='REVIEW'
    and oldr.review_issue_code='CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED' then
    proof:=private.bpay_next_source_comparison_review_credit_operation_proof_v2(
      oldr,new.operation_job_id,new.receipt_kind,new.operation_identity);
    if proof is not null then
      q:=(proof->>'comparable_operation_ex_vat')::numeric;
      if (new.qualification_state,new.review_issue_code,new.comparable_operation_ex_vat)
          is distinct from ('REVIEW','CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED',q)
        or (new.case_basis_before,new.case_basis,new.case_resolution)
          is distinct from (oldr.case_basis,proof->'case_basis',proof->'case_resolution')
        or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
          is distinct from (proof#>>'{case_basis,collection_id}',proof#>>'{case_basis,case_id}',proof#>>'{case_basis,case_component_id}')
        or (new.comparable_paid_ex_vat,new.comparable_held_ex_vat) is distinct from
          (oldr.comparable_paid_ex_vat+case new.receipt_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end,
           oldr.comparable_held_ex_vat-case when new.receipt_kind in ('SETTLE','RELEASE') then q else 0 end)
        or new.selected_residual_ex_vat is distinct from new.approved_source_ex_vat-new.comparable_paid_ex_vat-new.comparable_held_ex_vat then
        raise exception 'BPAY_NEXT_REVIEW_CREDIT_OPERATION_CERTIFICATE_INVALID';end if;
      return new;
    end if;
  end if;
  credit_qualified:=qualified and (oldr.qualification_state in ('READY','PENDING') or oldr.review_issue_code='CASE_RECONCILIATION_REQUIRED');
  case_qualified:=true;
  actual_case:=private.bpay_next_source_comparison_case_basis_v2(new.canonical_work_id,new.canonical_component_key,false);
  if new.case_basis_before is distinct from oldr.case_basis or new.case_basis is distinct from actual_case
    or (new.work_collection_id::text,new.case_id::text,new.case_component_id::text)
      is distinct from (actual_case->>'collection_id',actual_case->>'case_id',actual_case->>'case_component_id') then
    raise exception 'BPAY_NEXT_COMPARISON_CASE_CARRY_TUPLE_INVALID';end if;
  if oldr.case_basis is not null then
    plan:=private.bpay_next_source_comparison_case_remainder_v2(oldr,new.receipt_kind,op.case_event_id,q,
      oldr.comparable_paid_ex_vat+case new.receipt_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end,actual_case);
    case_qualified:=plan is not null;
    if new.case_resolution is distinct from coalesce(plan,oldr.case_resolution) then raise exception 'BPAY_NEXT_COMPARISON_CASE_CARRY_REMAINDER_INVALID';end if;
  elsif actual_case is not null then case_qualified:=false;end if;
  if credit_qualified then
    if new.qualification_state is distinct from (case when case_qualified then oldr.qualification_state else 'REVIEW' end)
      or (not case_qualified and new.review_issue_code is distinct from 'CASE_RECONCILIATION_REQUIRED')
      or new.comparable_operation_ex_vat is distinct from q
      or (new.comparable_paid_ex_vat,new.comparable_held_ex_vat) is distinct from
        (oldr.comparable_paid_ex_vat+case new.receipt_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end,
         oldr.comparable_held_ex_vat+case new.receipt_kind when 'RESERVE' then q when 'SETTLE' then -q when 'RELEASE' then -q else 0 end)
      then raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_CARRY_AMOUNT_INVALID';end if;
  elsif new.qualification_state<>'REVIEW' or new.comparable_operation_ex_vat is not null
    or new.review_issue_code<>'ACTUAL_OPERATION_COMPARABLE_MAPPING_UNBOUND' then
    raise exception using errcode='23514',message='BPAY_NEXT_COMPARISON_CARRY_REVIEW_REQUIRED';end if;
  return new;
end $function$;

create or replace function private.bpay_next_source_comparison_carry_v2(p_job_id uuid,p_expected_book_revision bigint,
  p_expected_comparison_id uuid,p_operation_kind text,p_operation_id uuid)
returns jsonb language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare op record;p private.bpay_next_position%rowtype;localp private.bpay_next_position%rowtype;
  r private.bpay_next_source_comparison_receipt%rowtype;oldr private.bpay_next_source_comparison_receipt%rowtype;
  m private.bpay_next_source_comparison_hold_mapping%rowtype;dr numeric;dh numeric;q numeric;qualified boolean;
  cm private.bpay_next_source_comparison_case_hold_mapping%rowtype;
  actual_case jsonb;case_remainder jsonb;credit_qualified boolean;case_qualified boolean:=true;review_credit_proof jsonb;review_credit boolean:=false;
begin
  -- Exact operation replay precedes currentness: old OUTPUT remains the immutable result after later moves.
  select * into r from private.bpay_next_source_comparison_receipt where receipt_kind=p_operation_kind and operation_identity=p_operation_id;
  if found then
    if (r.operation_job_id,r.source_book_revision_before,r.previous_comparison_id)
      is distinct from (p_job_id,p_expected_book_revision,p_expected_comparison_id) then raise exception 'BPAY_NEXT_COMPARISON_OPERATION_REPLAY_CONFLICT';end if;
    return jsonb_build_object('comparison_id',r.id,'comparison_revision',r.comparison_revision,'book_revision',r.source_book_revision,
      'qualification_state',r.qualification_state,'replay',true);
  end if;
  select * into strict op from private.bpay_next_source_comparison_operation_v2(p_job_id,p_operation_kind,p_operation_id);
  perform 1 from private.bpay_next_worker_control where candidate_id=op.candidate_id for update;
  perform 1 from private.bpay_next_work where id in(op.canonical_work_id,op.local_work_id) order by id for update;
  perform 1 from private.bpay_next_position where (work_id,component_key) in
    ((op.canonical_work_id,op.canonical_component_key),(op.local_work_id,op.local_component_key)) order by work_id,component_key for update;
  select * into strict p from private.bpay_next_position where work_id=op.canonical_work_id and component_key=op.canonical_component_key;
  if p.source_book_revision is distinct from p_expected_book_revision or p.source_comparison_receipt_id is distinct from p_expected_comparison_id
    or not private.bpay_next_source_comparison_book_certified_v2(p) then raise exception 'BPAY_NEXT_COMPARISON_CARRY_STALE';end if;
  select * into strict oldr from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
  select * into strict localp from private.bpay_next_position where work_id=op.local_work_id and component_key=op.local_component_key;
  r:=oldr;r.id:=gen_random_uuid();r.receipt_kind:=p_operation_kind;r.review_issue_code:=null;
  r.previous_comparison_id:=oldr.id;r.comparison_revision_before:=p.source_comparison_revision;r.comparison_revision:=p.source_comparison_revision+1;
  r.source_book_revision_before:=p.source_book_revision;r.source_book_revision:=p.source_book_revision+1;
  r.native_realised_paye_before:=p.native_realised_paye;r.native_realised_umbrella_before:=p.native_realised_umbrella;
  r.native_held_paye_before:=p.native_held_paye;r.native_held_umbrella_before:=p.native_held_umbrella;
  dr:=case p_operation_kind when 'SETTLE' then op.native_amount when 'CASE_RECOVERY' then -op.native_amount else 0 end;
  dh:=case p_operation_kind when 'RESERVE' then op.native_amount when 'SETTLE' then -op.native_amount when 'RELEASE' then -op.native_amount else 0 end;
  r.native_realised_paye:=p.native_realised_paye+case when op.native_channel='PAYE' then dr else 0 end;
  r.native_realised_umbrella:=p.native_realised_umbrella+case when op.native_channel='UMBRELLA' then dr else 0 end;
  r.native_held_paye:=p.native_held_paye+case when op.native_channel='PAYE' then dh else 0 end;
  r.native_held_umbrella:=p.native_held_umbrella+case when op.native_channel='UMBRELLA' then dh else 0 end;
  r.native_source_channel:=op.native_channel;r.native_delta_realised:=dr;r.native_delta_held:=dh;
  r.operation_job_id:=p_job_id;r.operation_identity:=p_operation_id;r.operation_hold_id:=op.hold_id;r.operation_effect_id:=op.effect_id;
  r.operation_case_event_id:=op.case_event_id;r.operation_case_instruction_id:=op.case_instruction_id;r.operation_case_result_id:=op.case_result_id;
  r.operation_case_hold_id:=null;
  r.local_work_id:=op.local_work_id;r.local_component_key:=op.local_component_key;
  r.local_scalar_before:=private.bpay_next_source_comparison_scalar_v2(localp);
  r.local_scalar_after:=case when not op.updates_local_scalar then r.local_scalar_before
    else private.bpay_next_source_comparison_scalar_delta_v2(r.local_scalar_before,p_operation_kind,op.native_amount,op.target_ex,op.target_vat,op.target_inc) end;
  if op.updates_local_scalar and localp.source_basis_channel is distinct from op.native_channel then
    raise exception 'BPAY_NEXT_COMPARISON_LOCAL_NATIVE_BASIS_UNQUALIFIED';end if;
  r.comparable_paid_ex_vat_before:=oldr.comparable_paid_ex_vat;r.comparable_held_ex_vat_before:=oldr.comparable_held_ex_vat;
  if p_operation_kind='RESERVE' then q:=op.native_amount;qualified:=op.native_channel=oldr.target_pay_channel;
  elsif p_operation_kind='CASE_RECOVERY' then
    select * into cm from private.bpay_next_source_comparison_case_hold_mapping where basis_review_id=oldr.basis_review_id
      and case_hold_id=(select operation_item_id from private.bpay_next_case_event where id=op.case_event_id);
    if found then
      qualified:=cm.native_target_channel=op.native_channel and cm.native_target_ex_vat=op.native_amount
        and cm.instruction_id=op.case_instruction_id and cm.allocation_result_id=op.case_result_id;q:=cm.comparable_recovery_ex_vat;
    else q:=op.native_amount;qualified:=op.native_channel=oldr.target_pay_channel;end if;
  else
    select * into m from private.bpay_next_source_comparison_hold_mapping where basis_review_id=oldr.basis_review_id and hold_id=op.hold_id;
    qualified:=found and m.native_source_channel=op.native_channel and m.native_reserved_ex_vat=op.native_amount;q:=m.comparable_reserved_ex_vat;
  end if;
  review_credit_proof:=private.bpay_next_source_comparison_review_credit_operation_proof_v2(oldr,p_job_id,p_operation_kind,p_operation_id);
  review_credit:=review_credit_proof is not null;
  credit_qualified:=review_credit or (qualified and (oldr.qualification_state in ('READY','PENDING') or oldr.review_issue_code='CASE_RECONCILIATION_REQUIRED'));
  actual_case:=private.bpay_next_source_comparison_case_basis_v2(op.canonical_work_id,op.canonical_component_key,true);
  r.case_basis_before:=oldr.case_basis;r.case_basis:=actual_case;
  r.work_collection_id:=(actual_case->>'collection_id')::uuid;r.case_id:=(actual_case->>'case_id')::uuid;r.case_component_id:=(actual_case->>'case_component_id')::uuid;
  if review_credit then
    q:=(review_credit_proof->>'comparable_operation_ex_vat')::numeric;
    if actual_case is distinct from review_credit_proof->'case_basis' then raise exception 'BPAY_NEXT_REVIEW_CREDIT_ACTUAL_CASE_STALE';end if;
    r.case_resolution:=review_credit_proof->'case_resolution';case_qualified:=false;
  elsif oldr.case_basis is not null then
    case_remainder:=private.bpay_next_source_comparison_case_remainder_v2(oldr,p_operation_kind,op.case_event_id,q,
      oldr.comparable_paid_ex_vat+case p_operation_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end,actual_case);
    case_qualified:=case_remainder is not null;r.case_resolution:=coalesce(case_remainder,oldr.case_resolution);
  elsif actual_case is not null then
    case_qualified:=false;r.case_resolution:=jsonb_build_object('qualification_issue','CASE_OWNER_CHANGED_WITHOUT_ACCEPTED_BASIS');
  end if;
  if p_operation_kind='RESERVE' and oldr.qualification_state<>'READY' then raise exception 'BPAY_NEXT_COMPARISON_PENDING_DENIES_NEW_RESERVE';end if;
  if credit_qualified then
    r.qualification_state:=case when case_qualified then oldr.qualification_state else 'REVIEW' end;
    r.review_issue_code:=case when review_credit then 'CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED'
      when not case_qualified or oldr.review_issue_code='CASE_RECONCILIATION_REQUIRED' then 'CASE_RECONCILIATION_REQUIRED'
      when oldr.qualification_state='PENDING' then 'SOURCE_PUBLICATION_PENDING' else null end;
    r.comparable_operation_ex_vat:=q;
    r.comparable_paid_ex_vat:=oldr.comparable_paid_ex_vat+case p_operation_kind when 'SETTLE' then q when 'CASE_RECOVERY' then -q else 0 end;
    r.comparable_held_ex_vat:=oldr.comparable_held_ex_vat+case p_operation_kind when 'RESERVE' then q when 'SETTLE' then -q when 'RELEASE' then -q else 0 end;
    r.selected_residual_ex_vat:=r.approved_source_ex_vat-r.comparable_paid_ex_vat-r.comparable_held_ex_vat;
  else
    if p_operation_kind='RESERVE' then raise exception 'BPAY_NEXT_COMPARISON_NEW_RESERVE_REVIEW_REQUIRED';end if;
    r.qualification_state:='REVIEW';r.review_issue_code:='ACTUAL_OPERATION_COMPARABLE_MAPPING_UNBOUND';
    r.comparable_operation_ex_vat:=null;r.comparable_paid_ex_vat:=null;r.comparable_held_ex_vat:=null;r.selected_residual_ex_vat:=null;
  end if;
  r.accepted_at_utc:=transaction_timestamp();r.snapshot_sha256:=sha256(convert_to((to_jsonb(r)-'snapshot_sha256')::text,'UTF8'));
  insert into private.bpay_next_source_comparison_receipt select(r).*;
  if p_operation_kind='RESERVE' then
    m.basis_review_id:=r.basis_review_id;m.hold_id:=op.hold_id;m.run_line_id:=(select run_line_id from private.bpay_next_hold where id=op.hold_id);
    m.native_source_channel:=op.native_channel;m.native_reserved_ex_vat:=op.native_amount;m.comparable_reserved_ex_vat:=q;m.created_by_comparison_id:=r.id;
    m.mapping_sha256:=sha256(convert_to((to_jsonb(m)-'mapping_sha256')::text,'UTF8'));
    insert into private.bpay_next_source_comparison_hold_mapping select(m).*;
  end if;
  if (op.local_work_id,op.local_component_key) is distinct from (op.canonical_work_id,op.canonical_component_key) then
    if localp.source_book_state<>'UNBOUND' then raise exception 'BPAY_NEXT_COMPARISON_LOCAL_CANONICAL_COLLISION';end if;
    update private.bpay_next_position set
      realised_source_ex_vat=(r.local_scalar_after->>'realised_source_ex_vat')::numeric,held_source_ex_vat=(r.local_scalar_after->>'held_source_ex_vat')::numeric,
      realised_target_ex_vat=(r.local_scalar_after->>'realised_target_ex_vat')::numeric,realised_target_vat=(r.local_scalar_after->>'realised_target_vat')::numeric,
      realised_target_inc_vat=(r.local_scalar_after->>'realised_target_inc_vat')::numeric,held_target_ex_vat=(r.local_scalar_after->>'held_target_ex_vat')::numeric,
      held_target_vat=(r.local_scalar_after->>'held_target_vat')::numeric,held_target_inc_vat=(r.local_scalar_after->>'held_target_inc_vat')::numeric,
      updated_at_utc=transaction_timestamp() where work_id=op.local_work_id and component_key=op.local_component_key;
  end if;
  update private.bpay_next_position x set native_realised_paye=r.native_realised_paye,native_realised_umbrella=r.native_realised_umbrella,
    native_held_paye=r.native_held_paye,native_held_umbrella=r.native_held_umbrella,source_book_revision=r.source_book_revision,
    source_comparison_receipt_id=r.id,source_comparison_revision=r.comparison_revision,
    realised_source_ex_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'realised_source_ex_vat')::numeric else x.realised_source_ex_vat end,
    held_source_ex_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'held_source_ex_vat')::numeric else x.held_source_ex_vat end,
    realised_target_ex_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'realised_target_ex_vat')::numeric else x.realised_target_ex_vat end,
    realised_target_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'realised_target_vat')::numeric else x.realised_target_vat end,
    realised_target_inc_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'realised_target_inc_vat')::numeric else x.realised_target_inc_vat end,
    held_target_ex_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'held_target_ex_vat')::numeric else x.held_target_ex_vat end,
    held_target_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'held_target_vat')::numeric else x.held_target_vat end,
    held_target_inc_vat=case when x.work_id=r.local_work_id then (r.local_scalar_after->>'held_target_inc_vat')::numeric else x.held_target_inc_vat end,
    updated_at_utc=transaction_timestamp() where x.work_id=op.canonical_work_id and x.component_key=op.canonical_component_key
      and x.source_book_revision=p_expected_book_revision and x.source_comparison_receipt_id=p_expected_comparison_id;
  if not found then raise exception 'BPAY_NEXT_COMPARISON_CARRY_CAS_STALE';end if;
  return jsonb_build_object('comparison_id',r.id,'comparison_revision',r.comparison_revision,'book_revision',r.source_book_revision,
    'qualification_state',r.qualification_state,'replay',false);
end $function$;

create or replace function private.bpay_next_reconcile_source_comparison_collection_v2(
 p_job_id uuid,p_canonical_work_id uuid,p_component_key text,p_effect_id uuid default null)
returns void language plpgsql security invoker set search_path=pg_catalog,private,public as $function$
declare j private.bpay_next_job%rowtype;wc private.bpay_next_worker_control%rowtype;
 p private.bpay_next_position%rowtype;r private.bpay_next_source_comparison_receipt%rowtype;
 b private.bpay_next_work_collection%rowtype;v private.bpay_next_source_component_binding_version%rowtype;
 c private.bpay_next_finance_case%rowtype;x private.bpay_next_case_component%rowtype;
 principal numeric;delta numeric;ev text;s numeric;o numeric;actual jsonb;
begin
 select * into strict j from private.bpay_next_job where id=p_job_id;
 select * into strict wc from private.bpay_next_worker_control where candidate_id=j.candidate_id for update;
 perform 1 from private.bpay_next_work where id=p_canonical_work_id and candidate_id=j.candidate_id for update;
 select * into strict p from private.bpay_next_position where work_id=p_canonical_work_id and component_key=p_component_key for update;
 select * into strict r from private.bpay_next_source_comparison_receipt where id=p.source_comparison_receipt_id;
 if j.status<>'LEASED' or j.owner_epoch<>wc.active_owner_epoch or j.lease_until_utc<=clock_timestamp()
   or not exists(select 1 from private.bpay_next_module_control m where m.id=1 and m.active_owner='NEXT' and m.owner_epoch=j.module_epoch)
   or exists(select 1 from private.bpay_next_job prior where prior.candidate_id=j.candidate_id and prior.command_sequence<j.command_sequence and prior.status<>'DONE')
   or r.candidate_id<>j.candidate_id or not private.bpay_next_source_comparison_book_certified_v2(p) then
  raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_OWNER_STALE' using errcode='55000';end if;
 if r.receipt_kind='CASE_RECONCILE' and r.operation_job_id=j.id and
   ((j.job_kind='POSITION_APPLY' and p_effect_id is null and j.phase in ('NEW','REMOVED')) or
    (j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') and j.phase='MEMBERS' and p_effect_id is not null
      and exists(select 1 from private.bpay_next_source_comparison_receipt actual_operation
        where actual_operation.id=r.previous_comparison_id and actual_operation.operation_effect_id=p_effect_id
          and actual_operation.operation_job_id=j.id and actual_operation.receipt_kind in ('SETTLE','CASE_RECOVERY')))) then
  return;
 end if;
 -- Do not roll back genuine money or automatically rebase Case P while W* is unqualified.
 if r.qualification_state='REVIEW' and r.review_issue_code='CASE_WRITEOFF_COMPARISON_REVIEW_REQUIRED'
   and r.operation_job_id=j.id and r.comparable_paid_ex_vat is not null and r.comparable_held_ex_vat is not null then
   if (j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') and j.phase='MEMBERS'
       and p_effect_id is not null and r.operation_effect_id=p_effect_id and r.receipt_kind in ('SETTLE','CASE_RECOVERY'))
     or (j.job_kind in ('SIMPLE_CANCEL','PREPARATION_EXPIRY') and j.phase='RELEASE'
       and p_effect_id is null and r.receipt_kind='RELEASE' and r.operation_hold_id is not null) then
     actual:=private.bpay_next_source_comparison_review_credit_operation_proof_v2(
       (select input from private.bpay_next_source_comparison_receipt input where input.id=r.previous_comparison_id),
       j.id,r.receipt_kind,r.operation_identity);
     if actual is null or (r.case_basis,r.case_resolution,r.comparable_operation_ex_vat)
       is distinct from (actual->'case_basis',actual->'case_resolution',(actual->>'comparable_operation_ex_vat')::numeric) then
       raise exception 'BPAY_NEXT_REVIEW_CREDIT_COLLECTION_OPERATION_INVALID';end if;
     return;
   end if;
 end if;
 if j.job_kind='POSITION_APPLY' then
  if p_effect_id is not null or j.phase not in ('NEW','REMOVED') or not exists(
    select 1 from private.bpay_next_publication publication where publication.command_id=j.command_id
      and publication.candidate_id=j.candidate_id and publication.work_id=p_canonical_work_id
      and publication.revision_id=p.applied_revision_id and publication.status in ('QUEUED','APPLYING')) then
    raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_PUBLICATION_SCOPE_INVALID';end if;
 elsif j.job_kind in ('CSV_SETTLEMENT','INTERNAL_SETTLEMENT') then
  if p_effect_id is null or j.phase<>'MEMBERS' or r.operation_job_id is distinct from j.id or r.operation_effect_id is distinct from p_effect_id
    or r.receipt_kind not in ('SETTLE','CASE_RECOVERY') then raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_EFFECT_SCOPE_INVALID';end if;
 elsif j.job_kind in ('SIMPLE_CANCEL','PREPARATION_EXPIRY') then
  -- Exact hold carry has already certified the physical release. No hold/history scan.
  if p_effect_id is not null or j.phase<>'RELEASE' or r.receipt_kind<>'CASE_RELEASE'
    or r.operation_job_id is distinct from j.id or r.operation_case_hold_id is null
    or r.review_issue_code is distinct from 'CASE_RECONCILIATION_REQUIRED' then
    raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CASE_CAPACITY_SCOPE_INVALID';end if;
  perform private.bpay_next_source_comparison_case_capacity_proof_v2(
    (select input from private.bpay_next_source_comparison_receipt input where input.id=r.previous_comparison_id),
    j.id,r.operation_case_hold_id,'CASE_RELEASE');
 else raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_JOB_KIND_INVALID';
 end if;
 if r.comparable_paid_ex_vat is null or r.comparable_held_ex_vat is null then
  -- Truthful actual native posting remains recorded; missing comparison authority
  -- cannot be made READY by a collection calculation.
  return;
 end if;
 if not (r.qualification_state in ('READY','PENDING') or r.review_issue_code='CASE_RECONCILIATION_REQUIRED') then
  raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CURRENT_REVIEW_REQUIRED' using errcode='55000';end if;
 select * into strict v from private.bpay_next_source_component_binding_version where id=r.source_binding_version_id;
 if not exists(select 1 from private.bpay_next_source_component_binding current where current.current_binding_version_id=v.id
   and current.canonical_work_id=p.work_id and current.canonical_component_key=p.component_key)
   or (v.approval_work_id,v.approval_revision_id,v.approval_component_key,v.approved_line_id,v.candidate_id)
     is distinct from (r.approval_work_id,r.approval_revision_id,r.approval_component_key,r.approved_line_id,r.candidate_id)
   or not ((v.origin_kind='COMMON_HEAD_RECEIPT_V1' and exists(select 1 from public.weekly_source_entitlement_heads h
     join public.weekly_source_entitlement_decision_bundles bundle on bundle.decision_bundle_id=h.decision_bundle_id and bundle.bundle_revision=h.bundle_revision
     join public.weekly_source_root_authorisations auth on auth.current_entitlement_head_id=h.id and auth.root_timesheet_id=h.root_timesheet_id
     where h.id=v.head_id and h.state='COMMITTED_CURRENT' and bundle.state='COMMITTED' and auth.withdrawn_at_utc is null))
     or (v.origin_kind='INITIAL_AUTHORISED_TSFIN_V1' and exists(
       select 1 from private.bpay_next_bound_source_snapshot_v1(v.id,p.source_book_revision) initial
       where initial.qualification_state='READY' and
         (initial.candidate_id,initial.canonical_work_id,initial.canonical_component_key,initial.binding_version_id,
           initial.approval_work_id,initial.approval_revision_id,initial.approved_line_id)
         =(v.candidate_id,v.canonical_work_id,v.canonical_component_key,v.id,v.approval_work_id,v.approval_revision_id,v.approved_line_id)))) then
   raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_SOURCE_AUTHORITY_INVALID';end if;
 select * into b from private.bpay_next_work_collection where work_id=p.work_id and component_key=p.component_key for update;
 if not found or not b.paid_basis_qualified or not private.bpay_next_work_collection_source_original_v2(b) then
   raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_ORIGINAL_ORIGIN_REVIEW_REQUIRED' using errcode='55000';end if;
 actual:=private.bpay_next_source_comparison_case_basis_v2(p.work_id,p.component_key,true);
 if r.case_basis is distinct from actual then raise exception 'BPAY_NEXT_COMPARISON_COLLECTION_CASE_BASIS_CHANGED';end if;
 if b.case_id is null then
   principal:=greatest(r.comparable_paid_ex_vat-r.approved_source_ex_vat,0);
   if principal>0 then
     insert into private.bpay_next_finance_case(id,candidate_id,case_kind,tax_treatment,status,principal_approved,order_key,case_revision)
       values(b.id,j.candidate_id,'OVERPAYMENT','TAXABLE','OPEN',principal,j.command_sequence,1);
     insert into private.bpay_next_case_rule(id,case_id,candidate_id,rule_revision,case_kind,case_subtype,tax_treatment,case_created_at_utc)
       values(b.id,b.id,j.candidate_id,1,'OVERPAYMENT','OVERPAYMENT','TAXABLE',transaction_timestamp());
     update private.bpay_next_finance_case set current_rule_id=b.id,current_rule_revision=1 where id=b.id;
     insert into private.bpay_next_case_component(id,case_id,candidate_id,component_key,component_ordinal,component_revision,rule_id,
       case_kind,case_subtype,tax_treatment,instruction_kind,direction,payroll_stage,source_pay_channel,currency,approved_source_ex_vat,resolution_state)
       values(b.id,b.id,j.candidate_id,'RECOVERY',1,1,b.id,'OVERPAYMENT','OVERPAYMENT','TAXABLE','RECOVERY','DEDUCTION',
         'GROSS_DEDUCT',r.target_pay_channel,'GBP',principal,'REVIEW');
     b.case_id:=b.id;b.case_component_id:=b.id;delta:=principal;ev:='APPROVED';
   end if;
 else
   select * into strict c from private.bpay_next_finance_case where id=b.case_id for update;
   select * into strict x from private.bpay_next_case_component where id=b.case_component_id for update;
   if (c.principal_approved,c.principal_recovered,c.principal_written_off,c.active_recovery_hold_amount)
     is distinct from (x.approved_source_ex_vat,x.recovered_source_ex_vat,x.written_off_source_ex_vat,x.active_recovery_source_ex_vat) then
     raise exception 'BPAY_NEXT_WORK_COLLECTION_BALANCE_MISMATCH';end if;
   o:=greatest(r.comparable_paid_ex_vat-r.approved_source_ex_vat-(r.case_resolution->>'target_written_off_ex_vat')::numeric,
     (r.case_resolution->>'target_active_capacity_ex_vat')::numeric,0);
   if x.source_pay_channel=r.target_pay_channel then s:=o;
   else
     s:=(r.case_resolution->>'source_outstanding_ex_vat')::numeric;
     if s is null or (r.case_resolution->>'target_outstanding_ex_vat')::numeric is distinct from o then
       raise exception 'BPAY_NEXT_COMPARISON_CASE_SELECTED_REMAINDER_REVIEW_REQUIRED' using errcode='55000';end if;
   end if;
   principal:=c.principal_recovered+c.principal_written_off+greatest(s,c.active_recovery_hold_amount);
   delta:=principal-c.principal_approved;
   if delta<>0 then
     update private.bpay_next_finance_case set principal_approved=principal,
       status=case when principal=principal_recovered+principal_written_off then 'CLOSED' when status='PAUSED' then 'PAUSED' else 'OPEN' end,
       case_revision=case_revision+1,updated_at_utc=transaction_timestamp() where id=c.id;
     update private.bpay_next_case_component set approved_source_ex_vat=principal,component_revision=component_revision+1,
       resolution_state='REVIEW',target_pay_channel=null,target_ex_vat=null,target_vat=null,target_inc_vat=null,
       valuation_policy_id=null,valuation_window_id=null,resolution_ref=null,updated_at_utc=transaction_timestamp() where id=x.id;
     ev:='CORRECTED';
   elsif principal=c.principal_recovered+c.principal_written_off and c.status<>'CLOSED' then
     update private.bpay_next_finance_case set status='CLOSED',case_revision=case_revision+1,updated_at_utc=transaction_timestamp() where id=c.id;
   end if;
 end if;
 if ev is not null then
   insert into private.bpay_next_case_event(case_id,operation_id,operation_item_id,event_kind,approved_delta,original_transfer_id,original_effect_id)
     values(b.case_id,j.command_id,b.id,ev,delta,b.original_transfer_id,b.original_effect_id);
 end if;
 update private.bpay_next_work_collection set case_id=b.case_id,case_component_id=b.case_component_id,qualification_state='READY',
   observed_revision_id=p.applied_revision_id,observed_approved_source_ex_vat=p.approved_source_ex_vat,
   observed_realised_source_ex_vat=p.realised_source_ex_vat,reconcile_revision=reconcile_revision+1,last_job_id=j.id,last_effect_id=p_effect_id,
   updated_at_utc=transaction_timestamp() where id=b.id;
 if b.case_id is not null then
   perform private.bpay_next_source_comparison_case_reconcile_v2(j.id,p.source_book_revision,r.id,b.id);
 end if;
end $function$;

alter function private.bpay_next_source_comparison_case_capacity_proof_v2(private.bpay_next_source_comparison_receipt,uuid,uuid,text) OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_guard_v2() OWNER TO CURRENT_USER;
alter function private.bpay_next_source_comparison_carry_v2(uuid,bigint,uuid,text,uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_reconcile_source_comparison_collection_v2(uuid,uuid,text,uuid) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_source_comparison_case_capacity_proof_v2(private.bpay_next_source_comparison_receipt,uuid,uuid,text),
 private.bpay_next_source_comparison_guard_v2(),
 private.bpay_next_source_comparison_carry_v2(uuid,bigint,uuid,text,uuid),
 private.bpay_next_reconcile_source_comparison_collection_v2(uuid,uuid,text,uuid) from public,anon,authenticated,service_role;


-- Pure saved selected quote and exact source-first slice. No live repricing,
-- reverse bank-cash conversion, new calculator, cent search or guessed units.


create or replace function private.pay_finance_selected_reuse_factors_v2(
  p_source numeric,p_ex numeric,p_vat numeric,p_inc numeric,p_units numeric)
returns jsonb language sql immutable security invoker set search_path=pg_catalog
as $function$
  select jsonb_build_object('ex',round(p_ex/p_source,10),'vat',round(p_vat/p_source,10),
    'inc',round(p_inc/p_source,10),'units',case when p_units is null then null else round(p_units/p_source,10) end)
$function$;

create or replace function private.bpay_next_case_quote_from_snapshot_v2(p_snapshot jsonb,p_source numeric)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,private,public
as $function$
declare q jsonb; m numeric; f jsonb; mode text:=p_snapshot->>'selected_mode'; base numeric;baseq jsonb;
begin
  perform private.weekly_source_publication_require_keys_v1(p_snapshot,array[
    'selected_mode','source_pay_channel','target_pay_channel','source_basis_ex_vat','selected_quote',
    'comparison_policy_id','policy_window_id','effective_pay_date','erni_pct','vat_rate_pct','umbrella_vat_chargeable'],
    'case.selected_quote_snapshot');
  if p_snapshot is null or jsonb_typeof(p_snapshot)<>'object' or p_source is null or p_source<0
    or p_source<>round(p_source,2) or p_source>=10000000000000000
    or mode not in ('SUGGESTED_EQUIVALENT_BASIS','MANUAL_AMOUNT') or mode is null
    or p_snapshot->>'source_pay_channel' is null or p_snapshot->>'target_pay_channel' is null
    or p_snapshot->>'source_pay_channel' not in ('PAYE','UMBRELLA')
    or p_snapshot->>'target_pay_channel' not in ('PAYE','UMBRELLA')
    or p_snapshot->>'erni_pct' is null or p_snapshot->>'vat_rate_pct' is null then
    raise exception 'BPAY_NEXT_CASE_SELECTED_SNAPSHOT_INVALID' using errcode='22023';end if;
  base:=(p_snapshot->>'source_basis_ex_vat')::numeric;
  if base is null or base<0 or base<>round(base,2) or p_source>base
    or p_snapshot->>'comparison_policy_id' is null or p_snapshot->>'policy_window_id' is null
    or p_snapshot->>'effective_pay_date' is null
    or (p_snapshot->>'target_pay_channel'='UMBRELLA' and p_snapshot->>'umbrella_vat_chargeable' is null) then
    raise exception 'BPAY_NEXT_CASE_SELECTED_SNAPSHOT_INVALID' using errcode='22023';end if;
  perform private.weekly_source_publication_require_keys_v1(p_snapshot->'selected_quote',array['ex','vat','inc','rate'],
    'case.selected_quote');
  baseq:=private.pay_finance_selected_quote_v1(mode::public.pay_finance_component_resolution_mode_enum,
    base,p_snapshot->>'source_pay_channel',p_snapshot->>'target_pay_channel',null,null,
    case when mode='MANUAL_AMOUNT' then (p_snapshot#>>'{selected_quote,ex}')::numeric else null end,
    (p_snapshot->>'erni_pct')::numeric,(p_snapshot->>'vat_rate_pct')::numeric,(p_snapshot->>'umbrella_vat_chargeable')::boolean);
  if baseq is distinct from p_snapshot->'selected_quote' or (baseq->>'ex')::numeric is null
    or (baseq->>'ex')::numeric<0 or (baseq->>'ex')::numeric>=10000000000000000 then
    raise exception 'BPAY_NEXT_CASE_SELECTED_QUOTE_MISMATCH' using errcode='23514';end if;
  if mode='MANUAL_AMOUNT' then
    if base=0 then
      if (p_snapshot#>>'{selected_quote,ex}')::numeric<>0 then
        raise exception 'BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' using errcode='55000';end if;
      m:=0;
    else
      f:=private.pay_finance_selected_reuse_factors_v2(base,(p_snapshot#>>'{selected_quote,ex}')::numeric,
        (p_snapshot#>>'{selected_quote,vat}')::numeric,(p_snapshot#>>'{selected_quote,inc}')::numeric,null);
      -- Actual saved selected resolver's 10-decimal proportional reuse.
      m:=case when p_source=base then (p_snapshot#>>'{selected_quote,ex}')::numeric
        else round(p_source*(f->>'ex')::numeric,2) end;
    end if;
  end if;
  q:=private.pay_finance_selected_quote_v1(mode::public.pay_finance_component_resolution_mode_enum,
    p_source,p_snapshot->>'source_pay_channel',p_snapshot->>'target_pay_channel',null,null,m,
    (p_snapshot->>'erni_pct')::numeric,(p_snapshot->>'vat_rate_pct')::numeric,
    (p_snapshot->>'umbrella_vat_chargeable')::boolean);
  if p_source=base and q is distinct from p_snapshot->'selected_quote' then
    raise exception 'BPAY_NEXT_CASE_SELECTED_QUOTE_MISMATCH' using errcode='23514';end if;
  return q;
end $function$;

create or replace function private.bpay_next_case_source_slice_v2(p_snapshot jsonb,p_target numeric,p_capacity_source numeric)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,private,public
as $function$
declare s numeric;q jsonb;fullq jsonb;ratio numeric;
begin
  if p_target is null or p_capacity_source is null or p_target<0 or p_capacity_source<0
    or p_target<>round(p_target,2) or p_capacity_source<>round(p_capacity_source,2) then
    raise exception 'BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' using errcode='55000';end if;
  fullq:=private.bpay_next_case_quote_from_snapshot_v2(p_snapshot,p_capacity_source);
  if p_target=0 then s:=0;
  elsif p_target=(fullq->>'ex')::numeric then s:=p_capacity_source; -- genuine whole/due SOURCE slice
  elsif p_snapshot->>'selected_mode'='SUGGESTED_EQUIVALENT_BASIS'
    and p_snapshot->>'source_pay_channel'=p_snapshot->>'target_pay_channel' then s:=p_target;
  else
    -- Existing selected schedule mapping (56551–56569), not reverse paid cash.
    -- ONE cent candidate from the captured full selected basis; accept ONLY
    -- exact forward shared quote, never search or invent a rounding tie rule.
    if (p_snapshot->>'source_basis_ex_vat')::numeric<=0 then
      raise exception 'BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' using errcode='55000';end if;
    ratio:=(p_snapshot#>>'{selected_quote,ex}')::numeric/(p_snapshot->>'source_basis_ex_vat')::numeric;
    if ratio is null or ratio<=0 then
      raise exception 'BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' using errcode='55000';end if;
    s:=round(p_target/ratio,2);
  end if;
  if s<0 or s>p_capacity_source then
    raise exception 'BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' using errcode='55000';end if;
  q:=private.bpay_next_case_quote_from_snapshot_v2(p_snapshot,s);
  if (q->>'ex')::numeric is distinct from p_target then
    raise exception 'BPAY_NEXT_CASE_SOURCE_PARTITION_REVIEW_REQUIRED' using errcode='55000';end if;
  return q||jsonb_build_object('source',s);
end $function$;

create or replace function private.bpay_next_case_result_quote_valid_v2(
  p_instruction private.bpay_next_run_case_instruction,p_result private.bpay_next_case_allocation_result)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog,private,public
as $function$
declare q jsonb;
begin
  if p_instruction.selected_quote_snapshot is null then
    return p_instruction.source_pay_channel='PAYE' and p_instruction.target_pay_channel='PAYE'
      and p_result.allocated_source_ex_vat=p_result.allocated_target_ex_vat and p_result.allocated_target_vat=0
      and p_result.allocated_target_inc_vat=p_result.allocated_target_ex_vat;
  end if;
  q:=private.bpay_next_case_quote_from_snapshot_v2(p_instruction.selected_quote_snapshot,p_result.allocated_source_ex_vat);
  return (p_result.allocated_target_ex_vat,p_result.allocated_target_vat,p_result.allocated_target_inc_vat)
    is not distinct from ((q->>'ex')::numeric,(q->>'vat')::numeric,(q->>'inc')::numeric)
    and p_instruction.source_pay_channel=p_instruction.selected_quote_snapshot->>'source_pay_channel'
    and p_instruction.target_pay_channel=p_instruction.selected_quote_snapshot->>'target_pay_channel';
end $function$;
alter function private.pay_finance_selected_reuse_factors_v2(numeric,numeric,numeric,numeric,numeric) OWNER TO CURRENT_USER;
alter function private.bpay_next_case_quote_from_snapshot_v2(jsonb,numeric) OWNER TO CURRENT_USER;
alter function private.bpay_next_case_source_slice_v2(jsonb,numeric,numeric) OWNER TO CURRENT_USER;
alter function private.bpay_next_case_result_quote_valid_v2(private.bpay_next_run_case_instruction,private.bpay_next_case_allocation_result) OWNER TO CURRENT_USER;
revoke all on function private.pay_finance_selected_reuse_factors_v2(numeric,numeric,numeric,numeric,numeric),
  private.bpay_next_case_quote_from_snapshot_v2(jsonb,numeric),private.bpay_next_case_source_slice_v2(jsonb,numeric,numeric),
  private.bpay_next_case_result_quote_valid_v2(private.bpay_next_run_case_instruction,private.bpay_next_case_allocation_result)
  from public,anon,authenticated,service_role;


-- Existing projection/weekly owners, genuine NULL Umbrella NET. No fictitious
-- NET request/job/result and no current settings or original-money reconversion.


create or replace function private.bpay_next_umbrella_case_projection_snapshot_valid_v2(
  p_worker private.bpay_next_run_worker,p_projection private.bpay_next_net_projection)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare d private.bpay_next_case_allocation_state%rowtype;
begin
  if p_worker.target_pay_channel<>'UMBRELLA' or p_worker.target_umbrella_id is null
    or p_worker.target_umbrella_vat_chargeable is null or p_worker.case_selection_revision<1
    or p_worker.entered_paye_net is not null or p_worker.net_request_revision<>0
    or p_projection.input_kind<>'UMBRELLA' or p_projection.entered_paye_net is not null
    or p_projection.request_command_id is not null
    or p_projection.run_worker_id<>p_worker.id or p_projection.umbrella_case_draft_state_id is null
    or p_projection.projection_no<>1 then return false;end if;
  select * into strict d from private.bpay_next_case_allocation_state where id=p_projection.umbrella_case_draft_state_id;
  return d.run_worker_id=p_worker.id and d.candidate_id=p_worker.candidate_id
    and d.preparation_revision=p_worker.preparation_revision and d.selection_revision=p_worker.case_selection_revision
    and d.pass_kind='DRAFT' and d.projection_no=0 and d.status='COMPLETE' and d.prepare_stage='COMPLETE'
    and d.expected_instruction_count=p_worker.case_instruction_count and d.processed_instruction_count=d.expected_instruction_count
    and (p_projection.gross_ex_vat,p_projection.gross_vat,p_projection.gross_inc_vat)
      is not distinct from (d.captured_work_gross+d.allocated_gross_additions-d.allocated_gross_deductions,
        d.captured_work_vat+d.allocated_gross_additions_vat-d.allocated_gross_deductions_vat,
        p_worker.gross_inc_vat)
    and (p_projection.gross_ex_vat,p_projection.gross_vat) is not distinct from (p_worker.gross_ex_vat,p_worker.gross_vat)
    and (p_projection.accepted_gross_additions,p_projection.accepted_gross_deductions,
      p_projection.accepted_net_additions,p_projection.accepted_recoveries)
      is not distinct from (d.allocated_gross_additions+d.allocated_gross_additions_vat,
        d.allocated_gross_deductions+d.allocated_gross_deductions_vat,
        d.allocated_net_additions+d.allocated_net_additions_vat,
        d.allocated_net_recoveries+d.allocated_net_recoveries_vat)
    and p_projection.cash_amount=p_projection.gross_inc_vat+p_projection.accepted_net_additions-p_projection.accepted_recoveries;
end $function$;

create or replace function private.bpay_next_umbrella_case_projection_valid_v2(
  p_worker private.bpay_next_run_worker,p_projection private.bpay_next_net_projection)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
begin
  if p_projection.retired_at_utc is not null then return false;end if;
  return private.bpay_next_umbrella_case_projection_snapshot_valid_v2(p_worker,p_projection);
end $function$;

create or replace function private.bpay_next_capture_umbrella_case_projection_v2(p_worker_id uuid)
returns void language plpgsql volatile security invoker set search_path=pg_catalog,private
as $function$
declare w private.bpay_next_run_worker%rowtype;r private.bpay_next_pay_run%rowtype;
  d private.bpay_next_case_allocation_state%rowtype;p private.bpay_next_net_projection%rowtype;
  prior private.bpay_next_worker_week_contribution%rowtype;week private.bpay_next_worker_week%rowtype;
  earned numeric;cash numeric;
begin
  select * into strict w from private.bpay_next_run_worker where id=p_worker_id for update;
  select * into strict r from private.bpay_next_pay_run where id=w.run_id;
  if r.status<>'DRAFT' or r.confirmed_at_utc is null or w.status<>'READY'
    or w.target_pay_channel<>'UMBRELLA' or w.target_umbrella_id is null or w.target_umbrella_vat_chargeable is null
    or w.case_selection_revision<1 or w.case_pending_binding_count<>0 or w.financial_resolution_count<>0
    or w.entered_paye_net is not null or w.net_request_revision<>0 then
    raise exception 'BPAY_NEXT_UMBRELLA_CASE_PROJECTION_NOT_ELIGIBLE' using errcode='55000';end if;
  if w.net_projection_revision<>0 then
    select * into strict p from private.bpay_next_net_projection where run_worker_id=w.id and projection_no=w.net_projection_revision;
    if not private.bpay_next_umbrella_case_projection_valid_v2(w,p) then
      raise exception 'BPAY_NEXT_UMBRELLA_CASE_PROJECTION_REPLAY_INVALID' using errcode='23514';end if;
    return;
  end if;
  select * into strict d from private.bpay_next_case_allocation_state where run_worker_id=w.id
    and preparation_revision=w.preparation_revision and selection_revision=w.case_selection_revision
    and pass_kind='DRAFT' and projection_no=0 and status='COMPLETE' and prepare_stage='COMPLETE';
  cash:=w.gross_inc_vat+d.allocated_net_additions+d.allocated_net_additions_vat
    -d.allocated_net_recoveries-d.allocated_net_recoveries_vat;
  earned:=w.gross_ex_vat-d.allocated_net_recoveries;
  if cash<0 or cash>=10000000000000000 or earned<0 then
    raise exception 'BPAY_NEXT_UMBRELLA_CASE_CASH_RANGE_INVALID' using errcode='23514';end if;
  insert into private.bpay_next_net_projection(run_worker_id,request_command_id,projection_no,input_kind,
    gross_ex_vat,gross_vat,gross_inc_vat,entered_paye_net,accepted_recoveries,cash_amount,
    accepted_net_additions,accepted_gross_additions,accepted_gross_deductions,umbrella_case_draft_state_id)
    values(w.id,null,1,'UMBRELLA',w.gross_ex_vat,w.gross_vat,w.gross_inc_vat,null,
      d.allocated_net_recoveries+d.allocated_net_recoveries_vat,cash,d.allocated_net_additions+d.allocated_net_additions_vat,
      d.allocated_gross_additions+d.allocated_gross_additions_vat,d.allocated_gross_deductions+d.allocated_gross_deductions_vat,d.id)
    returning * into p;
  if not private.bpay_next_umbrella_case_projection_valid_v2(w,p) then
    raise exception 'BPAY_NEXT_UMBRELLA_CASE_PROJECTION_INVALID' using errcode='23514';end if;
  select * into strict week from private.bpay_next_worker_week where candidate_id=w.candidate_id and pay_week_start=d.pay_week_start for update;
  select * into strict prior from private.bpay_next_worker_week_contribution where original_run_worker_id=w.id for update;
  if prior.payment_state<>'ARRANGED' or prior.basis_kind<>'GROSS_FALLBACK' or prior.original_payroll_net is not null
    or prior.original_gross_amount<>w.gross_ex_vat or prior.accepted_projection_id is not null
    or prior.original_transfer_id is not null or prior.eligibility_state='UNBOUND' then
    raise exception 'BPAY_NEXT_UMBRELLA_CASE_WEEK_NOT_EXACT' using errcode='23514';end if;
  update private.bpay_next_worker_week_contribution set accepted_projection_id=p.id,accepted_bank_cash=cash,
    eligibility_state=case when earned>0 then 'ELIGIBLE' else 'EXCLUDED' end,eligible_arranged_amount=earned,
    contribution_revision=contribution_revision+1,primary_binding_revision=primary_binding_revision+1 where id=prior.id;
  update private.bpay_next_worker_week set resolved_arranged_take_home=resolved_arranged_take_home-prior.eligible_arranged_amount+earned,
    period_revision=period_revision+1 where candidate_id=w.candidate_id and pay_week_start=d.pay_week_start;
  update private.bpay_next_run_worker set net_projection_revision=1 where id=w.id;
end $function$;

create or replace function private.bpay_next_umbrella_case_projection_insert_guard_v2()
returns trigger language plpgsql security invoker set search_path=pg_catalog,private
as $function$
declare w private.bpay_next_run_worker%rowtype;
begin
  if new.umbrella_case_draft_state_id is null then return new;end if;
  select * into strict w from private.bpay_next_run_worker where id=new.run_worker_id;
  if w.status<>'READY' or w.net_projection_revision<>0
    or not private.bpay_next_umbrella_case_projection_valid_v2(w,new)
    or not exists(select 1 from private.bpay_next_pay_run where id=w.run_id and status='DRAFT' and confirmed_at_utc is not null) then
    raise exception 'BPAY_NEXT_UMBRELLA_CASE_PROJECTION_INSERT_INVALID' using errcode='23514';end if;
  return new;
end $function$;
drop trigger if exists bpay_next_umbrella_case_projection_insert_guard_v2 on private.bpay_next_net_projection;
create trigger bpay_next_umbrella_case_projection_insert_guard_v2 before insert on private.bpay_next_net_projection
  for each row execute function private.bpay_next_umbrella_case_projection_insert_guard_v2();
alter function private.bpay_next_umbrella_case_projection_snapshot_valid_v2(private.bpay_next_run_worker,private.bpay_next_net_projection) OWNER TO CURRENT_USER;
alter function private.bpay_next_umbrella_case_projection_valid_v2(private.bpay_next_run_worker,private.bpay_next_net_projection) OWNER TO CURRENT_USER;
alter function private.bpay_next_capture_umbrella_case_projection_v2(uuid) OWNER TO CURRENT_USER;
alter function private.bpay_next_umbrella_case_projection_insert_guard_v2() OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_umbrella_case_projection_snapshot_valid_v2(private.bpay_next_run_worker,private.bpay_next_net_projection),
  private.bpay_next_umbrella_case_projection_valid_v2(private.bpay_next_run_worker,private.bpay_next_net_projection),
  private.bpay_next_capture_umbrella_case_projection_v2(uuid),private.bpay_next_umbrella_case_projection_insert_guard_v2()
  from public,anon,authenticated,service_role;


-- Immutable captured economics remain separate from the live projection gate.
-- These point proofs add no mutation, external leg, finance quote or pay authority.


create or replace function private.bpay_next_umbrella_case_completed_transfer_valid_v2(
  w private.bpay_next_run_worker,t private.bpay_next_transfer)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare p private.bpay_next_net_projection%rowtype;b private.bpay_next_case_transfer_build%rowtype;
begin
  if w.target_pay_channel<>'UMBRELLA' or w.case_selection_revision<1
    or t.run_worker_id<>w.id or t.candidate_id<>w.candidate_id or t.original_transfer_id is not null
    or t.return_cash_id is not null or t.projection_id is null
    or t.beneficiary_kind<>'UMBRELLA' or t.beneficiary_id is distinct from w.target_umbrella_id
    or t.cash_amount<0 or t.member_count<0 or t.member_cash_sum<>t.cash_amount then return false;end if;
  select * into p from private.bpay_next_net_projection where id=t.projection_id;
  if not found or p.projection_no<>w.net_projection_revision
    or not private.bpay_next_umbrella_case_projection_valid_v2(w,p) then return false;end if;
  select * into b from private.bpay_next_case_transfer_build where transfer_id=t.id;
  if not found then return false;end if;
  return (b.run_worker_id,b.candidate_id,b.projection_id,b.draft_state_id,b.preparation_revision,b.selection_revision,b.target_pay_channel)
      is not distinct from (w.id,w.candidate_id,p.id,p.umbrella_case_draft_state_id,w.preparation_revision,w.case_selection_revision,'UMBRELLA'::text)
    and b.net_state_id is null and b.stage='COMPLETE' and b.completed_at_utc is not null
    and b.processed_work_count=b.expected_work_count and b.expected_work_count=w.captured_line_count
    and b.processed_case_count=b.expected_case_count and b.expected_case_count=w.case_instruction_count
    and t.member_count=b.expected_work_count+b.expected_case_count
    and (b.gross_additions_total,b.gross_deductions_total,b.net_additions_total,b.net_recoveries_total)
      is not distinct from (p.accepted_gross_additions,p.accepted_gross_deductions,p.accepted_net_additions,p.accepted_recoveries)
    and b.work_cash_total+b.gross_additions_total-b.gross_deductions_total=p.gross_inc_vat
    and t.cash_amount=p.cash_amount
    and exists(select 1 from private.bpay_next_command c where c.id=t.build_command_id
      and c.command_kind='TRANSFER_BUILD' and c.status='COMPLETE')
    and not exists(select 1 from private.bpay_next_destination_group_leg l where l.transfer_id=t.id);
end $function$;

create or replace function private.bpay_next_umbrella_case_csv_transfer_valid_v2(
  w private.bpay_next_run_worker,t private.bpay_next_transfer)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
begin
  if w.status<>'READY' or t.status<>'MEMBERS_READY' or t.cash_amount<=0 or t.member_count<=0 then return false;end if;
  return private.bpay_next_umbrella_case_completed_transfer_valid_v2(w,t);
end $function$;

-- The live validator remains retirement-strict. Only an actual completed
-- SIMPLE_CANCEL fact can qualify a retired projection for CANCELLED week state.
create or replace function private.bpay_next_umbrella_case_cancelled_projection_valid_v2(
  w private.bpay_next_run_worker,p private.bpay_next_net_projection)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,private
as $function$
declare b private.bpay_next_case_cancel_binding%rowtype;r private.bpay_next_cancel_request%rowtype;
  j private.bpay_next_job%rowtype;
begin
  if w.target_pay_channel<>'UMBRELLA' or w.status<>'CANCELLED' or p.retired_at_utc is null
    or not pg_catalog.isfinite(p.retired_at_utc)
    or not private.bpay_next_umbrella_case_projection_snapshot_valid_v2(w,p) then return false;end if;
  select * into b from private.bpay_next_case_cancel_binding where projection_id=p.id;
  if not found or b.status<>'CANCELLED' or b.stage<>'COMPLETE'
    or (b.run_worker_id,b.candidate_id,b.projection_id,b.umbrella_draft_state_id,b.draft_state_id,
      b.preparation_revision,b.selection_revision,b.accepted_projection_revision)
    is distinct from (w.id,w.candidate_id,p.id,p.umbrella_case_draft_state_id,p.umbrella_case_draft_state_id,
      w.preparation_revision,w.case_selection_revision,p.projection_no)
    or b.net_state_id is not null or b.finished_at_utc is distinct from p.retired_at_utc
    or b.started_at_utc is null or b.finished_at_utc<b.started_at_utc
    or b.released_work_count<>b.expected_work_count or b.released_case_hold_count<>b.expected_case_hold_count
    or w.active_case_hold_count<>0 then return false;end if;
  select * into r from private.bpay_next_cancel_request where command_id=b.command_id;
  if not found or r.run_worker_id<>w.id or r.candidate_id<>w.candidate_id or r.status<>'CANCELLED'
    or (r.expected_line_count,r.released_line_count,r.cursor_line_no,r.finished_at_utc)
      is distinct from (b.expected_work_count,b.released_work_count,b.checkpoint,b.finished_at_utc) then return false;end if;
  select * into j from private.bpay_next_job where command_id=b.command_id and candidate_id=w.candidate_id;
  if not found or j.job_kind<>'SIMPLE_CANCEL' or j.cursor_key is distinct from b.checkpoint::text
    or j.applied_line_count<>b.released_work_count
    or not ((j.status='LEASED' and j.phase='RELEASE' and j.lease_nonce is not null
        and j.lease_until_utc>pg_catalog.statement_timestamp()) or (j.status='DONE' and j.phase='CANCELLED'))
    or not exists(select 1 from private.bpay_next_command c where c.id=b.command_id
      and c.command_kind='SIMPLE_CANCEL' and c.agency_sequence=j.command_sequence and c.module_epoch=j.module_epoch
      and c.expected_member_count=1 and c.enrolled_member_count=1)
    or exists(select 1 from private.bpay_next_case_hold h where h.run_worker_id=w.id and h.status='ACTIVE') then return false;end if;
  return true;
end $function$;
alter function private.bpay_next_umbrella_case_completed_transfer_valid_v2(private.bpay_next_run_worker,private.bpay_next_transfer) OWNER TO CURRENT_USER;
alter function private.bpay_next_umbrella_case_csv_transfer_valid_v2(private.bpay_next_run_worker,private.bpay_next_transfer) OWNER TO CURRENT_USER;
alter function private.bpay_next_umbrella_case_cancelled_projection_valid_v2(private.bpay_next_run_worker,private.bpay_next_net_projection) OWNER TO CURRENT_USER;
revoke all on function private.bpay_next_umbrella_case_completed_transfer_valid_v2(private.bpay_next_run_worker,private.bpay_next_transfer),
  private.bpay_next_umbrella_case_csv_transfer_valid_v2(private.bpay_next_run_worker,private.bpay_next_transfer),
  private.bpay_next_umbrella_case_cancelled_projection_valid_v2(private.bpay_next_run_worker,private.bpay_next_net_projection)
  from public,anon,authenticated,service_role;

